class Visual final : public Scene {
  static constexpr int kMax = 128;
  static constexpr int kAlgorithms = 9;
  struct Op { int16_t a, b, value; uint8_t kind; };  // 0 cambio, 1 escritura, 2 comparación
  enum Phase { kShuffle, kSort, kSweep };
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  // Relojes en doble precisión: la escena sin música es idéntica a 30 y 60 FPS.
  double phaseTime = 0, duration = 1;
  int n = 0, algorithm = 0, phase = kShuffle;
  size_t applied = 0;
  int lastA = -1, lastB = -1;
  Random rng{1};
  std::array<int, kMax> values{};
  std::vector<Op> ops;

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

  // Tono (0..1) de un color de la paleta: el arcoíris empieza en él.
  static float hueOf(const Color& c) {
    float hi = std::max(c.r, std::max(c.g, c.b)), lo = std::min(c.r, std::min(c.g, c.b));
    float d = hi - lo;
    if (d < 1e-4f) return 0.0f;
    float h = hi == c.r ? (c.g - c.b) / d : (hi == c.g ? 2.0f + (c.b - c.r) / d : 4.0f + (c.r - c.g) / d);
    h /= 6.0f;
    return h - std::floor(h);
  }

  static Color hsv(float h, float s, float v) {
    h = h - std::floor(h);
    float r = std::clamp(std::fabs(h * 6.0f - 3.0f) - 1.0f, 0.0f, 1.0f);
    float g = std::clamp(2.0f - std::fabs(h * 6.0f - 2.0f), 0.0f, 1.0f);
    float b = std::clamp(2.0f - std::fabs(h * 6.0f - 4.0f), 0.0f, 1.0f);
    return {v * (1.0f - s + s * r), v * (1.0f - s + s * g), v * (1.0f - s + s * b), 1.0f};
  }

  // Grabación: cada algoritmo trabaja sobre una copia y anota sus pasos.
  void swapOp(std::array<int, kMax>& w, int i, int j) {
    std::swap(w[size_t(i)], w[size_t(j)]);
    ops.push_back({int16_t(i), int16_t(j), 0, 0});
  }
  void setOp(std::array<int, kMax>& w, int i, int v) {
    w[size_t(i)] = v;
    ops.push_back({int16_t(i), int16_t(i), int16_t(v), 1});
  }
  void cmpOp(int i, int j) { ops.push_back({int16_t(i), int16_t(j), 0, 2}); }

  void record(int which) {
    ops.clear();
    std::array<int, kMax> w = values;
    switch (which) {
      case 0:  // Burbuja
        for (int end = n - 1; end > 0; end--) {
          bool any = false;
          for (int i = 0; i < end; i++) {
            if (w[size_t(i)] > w[size_t(i + 1)]) {
              swapOp(w, i, i + 1);
              any = true;
            }
          }
          if (!any) break;
        }
        break;
      case 1: {  // Cóctel
        int lo = 0, hi = n - 1;
        bool any = true;
        while (any && lo < hi) {
          any = false;
          for (int i = lo; i < hi; i++) if (w[size_t(i)] > w[size_t(i + 1)]) { swapOp(w, i, i + 1); any = true; }
          hi--;
          for (int i = hi; i > lo; i--) if (w[size_t(i - 1)] > w[size_t(i)]) { swapOp(w, i - 1, i); any = true; }
          lo++;
        }
        break;
      }
      case 2:  // Inserción
        for (int i = 1; i < n; i++) {
          for (int j = i; j > 0 && w[size_t(j - 1)] > w[size_t(j)]; j--) swapOp(w, j - 1, j);
        }
        break;
      case 3:  // Selección: se ve cómo recorre buscando el mínimo
        for (int i = 0; i < n - 1; i++) {
          int best = i;
          for (int j = i + 1; j < n; j++) {
            cmpOp(best, j);
            if (w[size_t(j)] < w[size_t(best)]) best = j;
          }
          if (best != i) swapOp(w, i, best);
        }
        break;
      case 4:  // Shell
        for (int gap = n / 2; gap > 0; gap /= 2) {
          for (int i = gap; i < n; i++) {
            for (int j = i; j >= gap && w[size_t(j - gap)] > w[size_t(j)]; j -= gap) swapOp(w, j - gap, j);
          }
        }
        break;
      case 5: {  // Peine
        int gap = n;
        bool sorted = false;
        while (!sorted) {
          gap = std::max(1, int(float(gap) / 1.3f));
          sorted = gap == 1;
          for (int i = 0; i + gap < n; i++) {
            cmpOp(i, i + gap);
            if (w[size_t(i)] > w[size_t(i + gap)]) {
              swapOp(w, i, i + gap);
              sorted = false;
            }
          }
        }
        break;
      }
      case 6: {  // Rápido (Lomuto, con pila propia)
        std::array<int, kMax * 4> stack{};
        int top = 0;
        stack[size_t(top++)] = 0;
        stack[size_t(top++)] = n - 1;
        while (top > 0) {
          int hi = stack[size_t(--top)];
          int lo = stack[size_t(--top)];
          if (lo >= hi) continue;
          int pivot = w[size_t(hi)];
          int i = lo;
          for (int j = lo; j < hi; j++) {
            cmpOp(j, hi);
            if (w[size_t(j)] < pivot) {
              if (i != j) swapOp(w, i, j);
              i++;
            }
          }
          if (i != hi) swapOp(w, i, hi);
          if (top + 4 <= int(stack.size())) {
            stack[size_t(top++)] = lo;
            stack[size_t(top++)] = i - 1;
            stack[size_t(top++)] = i + 1;
            stack[size_t(top++)] = hi;
          }
        }
        break;
      }
      case 7: {  // Montículo
        auto sift = [&](int start, int end) {
          int root = start;
          while (root * 2 + 1 <= end) {
            int child = root * 2 + 1;
            int target = root;
            if (w[size_t(target)] < w[size_t(child)]) target = child;
            if (child + 1 <= end && w[size_t(target)] < w[size_t(child + 1)]) target = child + 1;
            cmpOp(root, child);
            if (target == root) return;
            swapOp(w, root, target);
            root = target;
          }
        };
        for (int start = (n - 2) / 2; start >= 0; start--) sift(start, n - 1);
        for (int end = n - 1; end > 0; end--) {
          swapOp(w, 0, end);
          sift(0, end - 1);
        }
        break;
      }
      default: {  // Mezcla, de abajo arriba
        std::array<int, kMax> tmp{};
        for (int width = 1; width < n; width *= 2) {
          for (int lo = 0; lo < n - width; lo += 2 * width) {
            int mid = lo + width, hi = std::min(lo + 2 * width, n);
            int i = lo, j = mid, k = 0;
            while (i < mid && j < hi) {
              cmpOp(i, j);
              tmp[size_t(k++)] = w[size_t(i)] <= w[size_t(j)] ? w[size_t(i++)] : w[size_t(j++)];
            }
            while (i < mid) tmp[size_t(k++)] = w[size_t(i++)];
            while (j < hi) tmp[size_t(k++)] = w[size_t(j++)];
            for (int t = 0; t < k; t++) setOp(w, lo + t, tmp[size_t(t)]);
          }
        }
        break;
      }
    }
  }

  void recordShuffle() {
    ops.clear();
    std::array<int, kMax> w = values;
    for (int i = n - 1; i > 0; i--) {
      int j = std::min(int(rng.unit() * float(i + 1)), i);
      swapOp(w, i, j);
    }
  }

  void apply(const Op& op) {
    if (op.kind == 0) std::swap(values[size_t(op.a)], values[size_t(op.b)]);
    else if (op.kind == 1) values[size_t(op.a)] = op.value;
    lastA = op.a;
    lastB = op.b;
  }

  void startPhase(int next) {
    phase = next;
    applied = 0;
    if (next == kShuffle) {
      recordShuffle();
      duration = 1.1;
    } else if (next == kSort) {
      record(algorithm);
      duration = std::clamp(2.5 + double(ops.size()) / 1100.0, 4.0, 9.0);
    } else {
      ops.clear();
      duration = 1.3;
    }
  }

 public:
  void reset(uint32_t seed) override {
    rng = Random(seed);
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    phaseTime = 0;
    duration = 1;
    n = 0;
    algorithm = int(seed % uint32_t(kAlgorithms));
    phase = kShuffle;
    applied = 0;
    lastA = lastB = -1;
    ops.reserve(20000);
  }

  void update(const Frame& f) override {
    auto m = modifiers(f);
    float dt = float(f.delta);
    const Music& mu = f.music;
    bass = follow(bass, mu.bass, 22.0f, 4.5f, dt);
    body = follow(body, mu.body, 12.0f, 3.0f, dt);
    spark = follow(spark, mu.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, mu.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, mu.active ? std::pow(std::clamp(mu.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : mu.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : mu.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : mu.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((mu.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, mu.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));

    int want = std::clamp(m.barras, 8, kMax);
    if (want != n) {
      n = want;
      for (int i = 0; i < kMax; i++) values[size_t(i)] = i;
      phaseTime = 0;
      startPhase(kShuffle);
    }
    // Algoritmo: uno fijo (o Todos, que los recorre). Si cambia a mitad de
    // ordenar, el nuevo sigue desde el estado actual: ninguna barra salta.
    constexpr int kChoice[8] = {-1, 0, 2, 3, 4, 6, 7, 8};
    int pick = kChoice[std::clamp(m.algoritmo, 0, 7)];
    if (pick >= 0 && pick != algorithm) {
      algorithm = pick;
      if (phase == kSort) {
        phaseTime = 0;
        startPhase(kSort);
      }
    }
    phaseTime += f.delta * f.speed * (1.0 + 1.3 * drive + 1.5 * kick);
    for (int guard = 0; guard < 4; guard++) {
      double t = std::min(phaseTime / duration, 1.0);
      size_t target = std::min(ops.size(), size_t(std::floor(t * double(ops.size()) + 1e-6)));
      while (applied < target) apply(ops[applied++]);
      if (phaseTime < duration) break;
      phaseTime -= duration;
      if (phase == kShuffle) {
        startPhase(kSort);
      } else if (phase == kSort) {
        lastA = lastB = -1;
        startPhase(kSweep);
      } else {
        if (pick < 0) algorithm = (algorithm + 1) % kAlgorithms;
        startPhase(kShuffle);
      }
    }
  }

  void render(const Frame& f, Canvas& c) const override {
    auto m = modifiers(f);
    auto gl = glide(f);
    float amp = f.intensity;
    const Color& bg = f.colors[0];
    c.rect({0, 0, f.width, f.height}, Paint::radial({f.width * 0.5f, f.height * 0.5f}, std::max(f.width, f.height) * 0.75f,
                                                   {Color{std::min(1.0f, bg.r + 0.04f), std::min(1.0f, bg.g + 0.03f), std::min(1.0f, bg.b + 0.05f), 1.0f},
                                                    Color{bg.r, bg.g, bg.b, 1.0f}}));
    if (n <= 0) return;
    float side = std::min(f.width, f.height);
    float px = side / 400.0f;
    float sweep = phase == kSweep ? float(phaseTime / duration) * float(n + 6) : -10.0f;
    // Rastro: los pasos recientes dejan luz en las barras que tocaron y se
    // apaga con la edad del paso; también alarga la cola del barrido final.
    const float rastro = std::clamp(gl.rastro, 0.0f, 1.0f);
    const float tail = 2.0f + 20.0f * rastro;
    std::array<float, kMax> trail{};
    if (phase != kSweep && applied > 0 && rastro > 0.001f) {
      // Los pasos de los últimos 0,8 s del algoritmo (en su propio reloj).
      size_t reach = size_t(std::clamp(double(rastro) * double(ops.size()) / duration * 0.8, 0.0, 2000.0));
      size_t first = applied > reach ? applied - reach : 0;
      for (size_t j = first; j < applied; j++) {
        float fresh = 1.0f - float(applied - 1 - j) / float(std::max<size_t>(reach, 1));
        float w = fresh * fresh * 0.6f;
        const Op& op = ops[j];
        trail[size_t(op.a)] = std::max(trail[size_t(op.a)], w);
        trail[size_t(op.b)] = std::max(trail[size_t(op.b)], w);
      }
    }
    const float baseHue = hueOf(f.colors[1]);
    auto colorOf = [&](int value, int index) {
      float t = float(value) / float(n - 1);
      Color col = hsv(baseHue + t * 0.83f, 0.95f, 1.0f);
      float lit = (0.8f + 0.25f * bass + 0.25f * kick) * amp;
      // Barrido final: las barras ya revisadas brillan hacia el blanco.
      float s = std::clamp(sweep - float(index), 0.0f, 1.0f) * std::clamp(1.0f - (sweep - float(index)) / tail, 0.0f, 1.0f);
      bool touched = index == lastA || index == lastB;
      float trace = index >= 0 && index < kMax ? trail[size_t(index)] : 0.0f;
      float w = touched ? 0.85f : std::max(s * 0.7f, trace);
      return Color{std::clamp((col.r * lit) * (1.0f - w) + w, 0.0f, 1.0f), std::clamp((col.g * lit) * (1.0f - w) + w, 0.0f, 1.0f),
                   std::clamp((col.b * lit) * (1.0f - w) + w, 0.0f, 1.0f), 1.0f};
    };

    if (m.vista == 0) {
      float left = f.width * 0.04f, usable = f.width * 0.92f;
      float bw = usable / float(n);
      float bottom = f.height * 0.9f, maxH = f.height * 0.78f;
      for (int i = 0; i < n; i++) {
        int v = values[size_t(i)];
        float h = maxH * (float(v) + 1.0f) / float(n);
        Paint p;
        p.color = colorOf(v, i);
        c.rect({left + float(i) * bw, bottom - h, std::max(bw * 0.82f, 1.0f), h}, p);
      }
      // Reflejo tenue bajo las barras.
      Paint floor = Paint::linear({0, bottom}, {0, bottom + f.height * 0.08f}, {Color{1, 1, 1, 0.08f * amp}, Color{1, 1, 1, 0}});
      c.rect({left, bottom + 2.0f * px, usable, f.height * 0.08f}, floor);
    } else if (m.vista == 1) {
      // Rueda: cada cuña con su color; el radio baja cuanto más lejos está
      // la barra de su sitio, así ordenada es un círculo perfecto.
      Vec2 center{f.width * 0.5f, f.height * 0.5f};
      float R = side * 0.44f * (1.0f + 0.05f * bass * amp);
      for (int i = 0; i < n; i++) {
        int v = values[size_t(i)];
        float off = std::fabs(float(i - v)) / float(n);
        float r = R * (1.0f - 0.75f * off);
        float a0 = 6.2831853f * float(i) / float(n) - 1.5707963f;
        float a1 = 6.2831853f * float(i + 1) / float(n) - 1.5707963f;
        Path wedge;
        wedge.moveTo(center.x, center.y);
        for (int k = 0; k <= 3; k++) {
          float a = a0 + (a1 - a0) * float(k) / 3.0f;
          wedge.lineTo(center.x + r * std::cos(a), center.y + r * std::sin(a));
        }
        wedge.close();
        Paint p;
        p.color = colorOf(v, i);
        c.path(wedge, p);
      }
      Paint hole;
      hole.color = Color{bg.r, bg.g, bg.b, 1.0f};
      c.circle(center, R * 0.12f, hole);
    } else {
      float left = f.width * 0.06f, usable = f.width * 0.88f;
      float bottom = f.height * 0.5f + usable * 0.5f, top = f.height * 0.5f - usable * 0.5f;
      std::array<std::vector<Vec2>, 8> groups;
      for (auto& g : groups) g.reserve(size_t(n));
      for (int i = 0; i < n; i++) {
        int v = values[size_t(i)];
        float x = left + usable * (float(i) + 0.5f) / float(n);
        float y = bottom - (bottom - top) * (float(v) + 0.5f) / float(n);
        groups[size_t(std::min(7, v * 8 / n))].push_back({x, y});
      }
      for (int g = 0; g < 8; g++) {
        int v = (g * n) / 8 + n / 16;
        Paint halo;
        halo.blend = Blend::plus;
        Color col = colorOf(std::min(v, n - 1), -10);
        halo.color = col.opacity(std::clamp(0.22f * f.glow * amp, 0.0f, 1.0f));
        c.points(groups[size_t(g)], 7.0f * px, halo);
        Paint dot;
        dot.color = col;
        c.points(groups[size_t(g)], 2.6f * px, dot);
      }
      // Rastro en la nube: un halo blanco que se apaga sobre los puntos tocados.
      std::array<std::vector<Vec2>, 4> traced;
      for (int i = 0; i < n; i++) {
        float w = trail[size_t(i)];
        if (w < 0.03f) continue;
        float x = left + usable * (float(i) + 0.5f) / float(n);
        float y = bottom - (bottom - top) * (float(values[size_t(i)]) + 0.5f) / float(n);
        traced[size_t(std::min(3, int(w / 0.6f * 4.0f)))].push_back({x, y});
      }
      for (int k = 0; k < 4; k++) {
        if (traced[size_t(k)].empty()) continue;
        Paint tp;
        tp.blend = Blend::plus;
        tp.color = Color{1, 1, 1, std::clamp(0.12f * float(k + 1), 0.0f, 1.0f)};
        c.points(traced[size_t(k)], 4.5f * px, tp);
      }
      if (lastA >= 0 && lastA < n) {
        Paint hl;
        hl.blend = Blend::plus;
        hl.color = Color{1, 1, 1, 0.9f};
        for (int idx : {lastA, lastB}) {
          if (idx < 0 || idx >= n) continue;
          float x = left + usable * (float(idx) + 0.5f) / float(n);
          float y = bottom - (bottom - top) * (float(values[size_t(idx)]) + 0.5f) / float(n);
          c.circle({x, y}, 4.0f * px, hl);
        }
      }
    }
    if (flash > 0.01f) {
      Paint fl;
      fl.blend = Blend::plus;
      fl.color = Color{1, 1, 1, std::clamp(flash * 0.05f * amp, 0.0f, 1.0f)};
      c.rect({0, 0, f.width, f.height}, fl);
    }
  }
};

class Visual final : public Scene {
  static constexpr int kRings = 6;
  float bass = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  // Relojes en doble precisión: sin música es idéntico a 30 y 60 FPS.
  double clock = 0, sinceIdle = 0, sinceShot = 10;
  std::array<double, kRings> birth{};
  std::array<float, kRings> power{}, angle{}, spin{};
  int nextRing = 0;
  uint32_t shots = 0;

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }
  static float hashU(uint32_t x) {
    x ^= x >> 16; x *= 0x7feb352dU; x ^= x >> 15; x *= 0x846ca68bU; x ^= x >> 16;
    return float(x & 0xffffffu) / 16777216.0f;
  }
  static int slots(float detail) { return std::clamp(int(std::lround(3.0f + 1.5f * detail)), 3, kRings); }
  // Dispara un anillo; carry es el tiempo que ya pasó desde el disparo.
  void fire(int pattern, float strength, double carry, int limit) {
    const uint32_t k = shots++;
    const int slot = nextRing % limit;
    float a = (hashU(k * 2654435761u + 1u) - 0.5f) * 0.12f;
    if (pattern == 1) a = (k % 2u == 0 ? 1.0f : -1.0f) * (0.25f + 0.2f * hashU(k * 3266489917u + 4u));
    if (pattern == 2) a = 0.5f * std::sin(float(k) * 0.9f);
    birth[size_t(slot)] = clock - carry;
    power[size_t(slot)] = strength;
    angle[size_t(slot)] = a;
    spin[size_t(slot)] = (hashU(k * 2246822519u + 2u) < 0.5f ? -1.0f : 1.0f) * (1.0f + float(k % 7u));
    nextRing = (slot + 1) % limit;
  }

 public:
  void reset(uint32_t seed) override {
    bass = energy = slowBass = kick = flash = drive = 0;
    clock = 0;
    sinceIdle = 0;
    sinceShot = 10;
    birth.fill(-1000.0);
    power.fill(1.0f);
    angle.fill(0.0f);
    spin.fill(1.0f);
    nextRing = 0;
    shots = seed * 5u;
    for (int i = 0; i < 3; i++) fire(0, 1.0f, 0.4 + 1.3 * double(i), kRings);
  }

  void update(const Frame& f) override {
    auto m = modifiers(f);
    const float dt = float(f.delta);
    const Music& mu = f.music;
    bass = follow(bass, mu.bass, 22.0f, 4.5f, dt);
    energy = follow(energy, mu.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, mu.active ? std::pow(std::clamp(mu.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);
    float hit = 0, fl = 0;
    for (const auto& e : mu.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : mu.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : mu.events[3]) fl = std::max(fl, e.strength);
    const float onset = std::clamp((mu.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, mu.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    const bool fresh = hit > kick + 0.2f;
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    const double step = f.delta * f.speed;
    clock += step;
    sinceShot += f.delta;
    const int limit = slots(f.detail);
    // Golpes: cada golpe dispara un anillo, más grande cuanto más fuerte.
    if (m.pulso == 0 && fresh && sinceShot > 0.25) {
      fire(m.disparo, 0.8f + 0.5f * hit * f.intensity, 0.0, limit);
      sinceShot = 0;
    }
    // A su ritmo dispara uno cada 1,3 s; en Ráfaga, la energía lo acelera.
    double period = 1.3;
    if (mu.active && m.pulso == 0) period = 3.9;
    if (m.pulso == 2) period = 1.3 / (1.0 + 1.8 * double(drive * f.intensity));
    sinceIdle += step;
    while (sinceIdle >= period) {
      sinceIdle -= period;
      fire(m.disparo, 1.0f, sinceIdle, limit);
    }
  }

  void render(const Frame& f, Canvas& c) const override {
    auto g = glide(f);
    const float amp = f.intensity;
    const float side = std::min(f.width, f.height);
    std::vector<float> u;
    u.reserve(56);
    const float rush = g.pulso.weight(2) * std::min(drive * amp, 1.0f);
    u.insert(u.end(), {float(std::fmod(clock, 1000.0)), std::min(bass * amp, 1.5f) * g.pulso.weight(1), std::min(kick * amp, 1.0f), rush});
    u.insert(u.end(), {std::clamp(g.remolino, 0.0f, 1.0f), std::clamp(g.bruma, 0.0f, 1.0f), f.glow, std::min(flash * amp, 1.0f)});
    u.insert(u.end(), {0.5f * f.height / side, 0.5f * f.width / side, 0.0f, 0.0f});
    for (int i = 0; i < kRings; i++) {
      const float age = float(std::min(clock - birth[size_t(i)], 1000.0));
      u.insert(u.end(), {age, power[size_t(i)], angle[size_t(i)], spin[size_t(i)]});
    }
    for (int i = 0; i < 4; i++) u.insert(u.end(), {f.colors[size_t(i)].r, f.colors[size_t(i)].g, f.colors[size_t(i)].b});
    c.material("smoke_rings", {0, 0, f.width, f.height}, u);
  }
};

shaderSources.smoke_rings:
#version 460 core
#include <flutter/runtime_effect.glsl>
uniform vec2 uSize;
uniform vec4 uA;   // tiempo, graves, golpe, ráfaga
uniform vec4 uB;   // remolino, bruma, glow, destello
uniform vec4 uE;   // media altura, medio ancho
uniform vec4 uR0;  // anillos: edad, fuerza, ángulo, giro
uniform vec4 uR1;
uniform vec4 uR2;
uniform vec4 uR3;
uniform vec4 uR4;
uniform vec4 uR5;
uniform vec3 uC0;
uniform vec3 uC1;
uniform vec3 uC2;
uniform vec3 uC3;
out vec4 fragColor;

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash12(i), hash12(i + vec2(1.0, 0.0)), u.x),
             mix(hash12(i + vec2(0.0, 1.0)), hash12(i + vec2(1.0, 1.0)), u.x), u.y);
}

// Densidad de un anillo y cuánto de su lado cercano se ve aquí.
float ring(vec2 p, vec4 Rg, float halfH, out float near) {
  near = 0.0;
  float age = Rg.x;
  if (age < 0.0 || age > 9.0) return 0.0;
  vec2 dir = vec2(sin(Rg.z), -cos(Rg.z));
  vec2 start = vec2(0.0, halfH * 0.8);
  // El anillo sube y a la vez viene hacia ti: crece mucho mientras avanza.
  float travel = (0.75 * (1.0 - exp(-age / 1.4)) + 0.04 * age) * (1.0 + 0.6 * uA.w);
  vec2 c = start + dir * travel * halfH * 1.15;
  float R = Rg.y * (0.06 + 0.16 * (1.0 - exp(-age / 1.6)) + 0.09 * age * age * 0.25) * (1.0 + 0.15 * uA.y);
  vec2 d = p - c;
  vec2 ax = vec2(-dir.y, dir.x);
  vec2 l = vec2(dot(d, ax), dot(d, dir));
  float e = 0.42;
  // Lejos del tubo de humo no hay nada: se descarta antes del atan y el ruido.
  float s0 = length(vec2(l.x, l.y / e)) - R;
  if (abs(s0) > R * 0.6 + 0.02) return 0.0;
  float th = atan(l.y / e, l.x);
  // Remolino: el aro se retuerce y el humo rueda más rápido.
  float Rw = R * (1.0 + 0.09 * uB.x * sin(th * 2.0 + age * 3.0 + Rg.w));
  float s = length(vec2(l.x, l.y / e)) - Rw;
  float w = R * (0.12 + 0.1 * min(age / 3.0, 1.0));
  float tube = exp(-(s * s) / (w * w));
  if (tube < 0.002) return 0.0;
  float roll = noise(vec2(th * 9.0 + Rg.w * 7.0, s / w * 2.2 - age * (2.0 + 4.0 * uB.x) * sign(Rg.w)));
  near = smoothstep(-0.2, 0.6, sin(th));
  return tube * (0.35 + 0.95 * roll) * exp(-age / 2.6) * smoothstep(0.0, 0.12, age);
}

void main() {
  vec2 frag = FlutterFragCoord().xy;
  float scale = min(uSize.x, uSize.y);
  vec2 p = (frag - 0.5 * uSize) / scale;
  float t = uA.x;
  float halfH = uE.x;
  // Bruma de la sala atravesada por un foco que sube desde abajo.
  float rise = halfH - p.y;
  float beam = exp(-abs(p.x) / (0.08 + rise * 0.22)) * smoothstep(-0.1, 0.4, rise);
  float haze = noise(p * 2.2 + vec2(0.0, t * 0.08)) * 0.6 + noise(p * 5.0 + vec2(t * 0.05, t * 0.12)) * 0.4;
  vec3 col = uC0 + uC1 * (0.05 + 0.3 * beam * haze) * uB.y * uB.z;
  col += uC2 * 0.06 * exp(-length(p - vec2(0.0, halfH)) * 4.0) * (1.0 + uA.z);
  float n0;
  float n1;
  float n2;
  float n3;
  float n4;
  float n5;
  float d0 = ring(p, uR0, halfH, n0);
  float d1 = ring(p, uR1, halfH, n1);
  float d2 = ring(p, uR2, halfH, n2);
  float d3 = ring(p, uR3, halfH, n3);
  float d4 = ring(p, uR4, halfH, n4);
  float d5 = ring(p, uR5, halfH, n5);
  float acc = d0 + d1 + d2 + d3 + d4 + d5;
  float near = (d0 * n0 + d1 * n1 + d2 * n2 + d3 * n3 + d4 * n4 + d5 * n5) / max(acc, 1e-4);
  // El humo toma la luz del foco: más claro por delante y donde pasa el haz.
  float light = 0.55 + 0.6 * beam + 0.3 * uB.w;
  vec3 smoke = mix(uC1, mix(uC2, uC3, 0.45), 0.25 + 0.6 * near) * light;
  col = mix(col, smoke * 1.25, 1.0 - exp(-acc * 2.4));
  col += uC2 * acc * 0.12 * uB.z;
  col *= 1.0 + 0.12 * uA.z;
  col *= 1.0 - 0.3 * smoothstep(0.6, 1.4, length(p * vec2(0.9, 0.65)) / max(uE.y * 2.0, 0.5));
  float peak = max(col.r, max(col.g, col.b));
  if (peak > 0.9) col *= (0.9 + 0.1 * (peak - 0.9) / (peak - 0.8)) / peak;
  col += (hash12(frag) - 0.5) / 255.0;
  fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

visuals.nativeSource:
class Visual final : public Scene {
  static constexpr int kMaxNodes = 1023;
  static constexpr int kPetals = 70;
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  // Relojes en doble precisión: la escena sin música es idéntica a 30 y 60 FPS.
  double clock = 0, wind = 0, sincePulse = 100, sinceForm = 0;
  float pulsePower = 0, asym = 0, curl = 0;
  int beats = 0, autoForm = 0;
  // Variación fija de cada rama, elegida al reiniciar.
  std::array<float, kMaxNodes> jitterA{}, jitterL{};
  // Pétalos que caen flotando: posición, velocidad y vaivén propios.
  std::array<float, kPetals> petalX{}, petalSpeed{}, petalPhase{}, petalSway{};
  // Ramas calculadas en update y dibujadas en render.
  std::array<Vec2, kMaxNodes> start{}, end{};
  std::array<float, kMaxNodes> angle{}, length{};
  std::array<bool, kMaxNodes> alive{};
  int nodes = 0, generations = 0;

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

  static int depthOf(int i) {
    int d = 0;
    for (int n = i + 1; n > 1; n >>= 1) d++;
    return d;
  }

 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    clock = 0;
    wind = rng.unit() * 20.0;
    sincePulse = 100;
    sinceForm = 0;
    pulsePower = 0;
    asym = curl = 0;
    beats = 0;
    autoForm = 0;
    for (int i = 0; i < kMaxNodes; i++) {
      jitterA[size_t(i)] = rng.unit() * 2.0f - 1.0f;
      jitterL[size_t(i)] = rng.unit() * 2.0f - 1.0f;
    }
    for (int i = 0; i < kPetals; i++) {
      petalX[size_t(i)] = rng.unit();
      petalSpeed[size_t(i)] = 0.03f + 0.05f * rng.unit();
      petalPhase[size_t(i)] = rng.unit();
      petalSway[size_t(i)] = rng.unit() * 6.2831853f;
    }
    nodes = generations = 0;
  }

  void update(const Frame& f) override {
    auto m = modifiers(f);
    float dt = float(f.delta);
    const Music& mu = f.music;
    bass = follow(bass, mu.bass, 22.0f, 4.5f, dt);
    body = follow(body, mu.body, 12.0f, 3.0f, dt);
    spark = follow(spark, mu.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, mu.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, mu.active ? std::pow(std::clamp(mu.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : mu.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : mu.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : mu.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((mu.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, mu.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    sincePulse += f.delta;
    sinceForm += f.delta;
    if (hit > kick + 0.2f) {
      beats++;
      sincePulse = 0;
      pulsePower = hit;
      if (beats % 8 == 0) {
        autoForm = (autoForm + 1) % 3;
        sinceForm = 0;
      }
    }
    if (!mu.active && sinceForm > 11.0) {
      autoForm = (autoForm + 1) % 3;
      sinceForm = 0;
    }
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    clock += f.delta;
    wind += f.delta * f.speed * (0.7 + 1.3 * drive);

    // La forma se transforma poco a poco: asimetría y rizo hacia su objetivo.
    int form = m.forma == 0 ? autoForm : m.forma - 1;
    float asymGoal = form == 1 ? 1.0f : (form == 2 ? 0.25f : 0.0f);
    float curlGoal = form == 2 ? 1.0f : 0.0f;
    float k = 1.0f - std::exp(-dt * 1.5f);
    asym += (asymGoal - asym) * k;
    curl += (curlGoal - curl) * k;

    // Ramas: recorrido por niveles; los hijos de i son 2i+1 y 2i+2.
    generations = std::clamp(m.ramas, 5, 10);
    nodes = (1 << generations) - 1;
    float growth = float(std::min(clock / 3.0, 1.0)) * float(generations);
    float spread = m.apertura * (1.0f + 0.18f * energy + 0.12f * kick);
    float trunk = f.height * 0.26f;
    float ratio = 0.76f;
    float shortSide = std::min(f.width, f.height);
    // Con pocas generaciones el árbol es más corto: se agranda para llenar.
    float total = 0;
    for (int d = 0; d < generations; d++) total += std::pow(ratio, float(d));
    trunk = std::min(trunk * 3.6f / total, shortSide * 0.45f);
    for (int i = 0; i < nodes; i++) {
      int d = depthOf(i);
      float g = std::clamp(growth - float(d), 0.0f, 1.0f);
      alive[size_t(i)] = g > 0.0f;
      float sway = (0.05f + 0.1f * bass + 0.04f * drive) *
                   float(std::sin(wind * 0.9 + double(d) * 0.55)) * (0.4f + 0.12f * float(d));
      if (i == 0) {
        start[0] = {f.width * 0.5f, f.height * 0.94f};
        angle[0] = -1.5707963f + sway * 0.4f;
        length[0] = trunk * g;
      } else {
        int parent = (i - 1) / 2;
        float dir = (i == 2 * parent + 1) ? -1.0f : 1.0f;
        // Las ramas altas se abren menos: la copa crece hacia arriba.
        float spreadHere = spread * (1.0f + asym * 0.45f * jitterA[size_t(i)]) * (1.0f - 0.035f * float(d));
        float bend = curl * spread * 0.75f;
        angle[size_t(i)] = angle[size_t(parent)] + dir * spreadHere + bend + sway;
        float full = length[size_t(parent)] > 0 ? 1.0f : 0.0f;
        float base = trunk * std::pow(ratio, float(d)) * (1.0f + asym * 0.22f * jitterL[size_t(i)]);
        length[size_t(i)] = base * g * full;
        start[size_t(i)] = end[size_t(parent)];
      }
      end[size_t(i)] = {start[size_t(i)].x + std::cos(angle[size_t(i)]) * length[size_t(i)],
                        start[size_t(i)].y + std::sin(angle[size_t(i)]) * length[size_t(i)]};
    }
    // Encaje: si la copa se sale (formas abiertas o en espiral), el árbol se
    // reduce desde la raíz y se centra en horizontal.
    float minX = f.width * 0.5f, maxX = f.width * 0.5f, minY = start[0].y;
    for (int i = 0; i < nodes; i++) {
      if (!alive[size_t(i)]) continue;
      minX = std::min(minX, end[size_t(i)].x);
      maxX = std::max(maxX, end[size_t(i)].x);
      minY = std::min(minY, end[size_t(i)].y);
    }
    float rootY = start[0].y;
    float fit = 1.0f;
    if (maxX - minX > f.width * 0.94f) fit = std::min(fit, f.width * 0.94f / (maxX - minX));
    if (rootY - minY > rootY - f.height * 0.04f) fit = std::min(fit, (rootY - f.height * 0.04f) / (rootY - minY));
    float centerX = (minX + maxX) * 0.5f;
    float shift = f.width * 0.5f - centerX;
    if (fit < 1.0f || std::fabs(shift) > 0.5f) {
      for (int i = 0; i < nodes; i++) {
        start[size_t(i)] = {f.width * 0.5f + (start[size_t(i)].x - centerX) * fit, rootY + (start[size_t(i)].y - rootY) * fit};
        end[size_t(i)] = {f.width * 0.5f + (end[size_t(i)].x - centerX) * fit, rootY + (end[size_t(i)].y - rootY) * fit};
      }
    }
  }

  void render(const Frame& f, Canvas& c) const override {
    auto m = modifiers(f);
    float amp = f.intensity;
    const Color& bg = f.colors[0];
    const Color& gold = f.colors[1];
    const Color& pink = f.colors[2];
    const Color& bloom = f.colors[3];
    // Fondo oscuro con un resplandor detrás de la copa.
    Color glowBg{std::min(1.0f, bg.r + pink.r * 0.10f * (1.0f + bass)), std::min(1.0f, bg.g + pink.g * 0.06f),
                 std::min(1.0f, bg.b + pink.b * 0.10f * (1.0f + bass)), 1.0f};
    c.rect({0, 0, f.width, f.height}, Paint::radial({f.width * 0.5f, f.height * 0.45f}, std::max(f.width, f.height) * 0.7f,
                                                   {glowBg, Color{bg.r, bg.g, bg.b, 1.0f}}));
    Paint ground = Paint::radial({f.width * 0.5f, f.height * 0.97f}, f.width * 0.6f,
                                 {gold.opacity(0.22f + 0.2f * kick * amp), gold.opacity(0.0f)});
    c.rect({0, 0, f.width, f.height}, ground);

    float px = std::min(f.width, f.height) / 400.0f;
    // Pétalos que caen desde arriba meciéndose con el viento.
    {
      std::array<std::vector<Vec2>, 2> petals;
      for (auto& g : petals) g.reserve(kPetals / 2 + 1);
      for (int i = 0; i < kPetals; i++) {
        double fall = std::fmod(wind * 0.35 * double(petalSpeed[size_t(i)]) * 10.0 + double(petalPhase[size_t(i)]), 1.0);
        float y = (float(fall) * 1.1f - 0.05f) * f.height;
        float x = petalX[size_t(i)] * f.width + float(std::sin(wind * 0.8 + double(petalSway[size_t(i)]))) * 18.0f * px;
        petals[size_t(i % 2)].push_back({x, y});
      }
      for (int g = 0; g < 2; g++) {
        Paint petal;
        petal.blend = Blend::plus;
        const Color& pc = g == 0 ? pink : gold;
        petal.color = pc.opacity(std::clamp((0.35f + 0.4f * kick + 0.3f * spark) * amp, 0.0f, 1.0f));
        c.points(petals[size_t(g)], (1.6f + 0.8f * float(g) + 1.5f * kick) * px, petal);
      }
    }
    float pulsePos = float(sincePulse) * 9.0f;
    for (int d = 0; d < generations; d++) {
      Path p;
      int first = (1 << d) - 1;
      int last = std::min((1 << (d + 1)) - 1, nodes);
      bool any = false;
      for (int i = first; i < last; i++) {
        if (!alive[size_t(i)] || length[size_t(i)] <= 0.0f) continue;
        p.moveTo(start[size_t(i)].x, start[size_t(i)].y);
        p.lineTo(end[size_t(i)].x, end[size_t(i)].y);
        any = true;
      }
      if (!any) continue;
      float t = float(d) / float(std::max(generations - 1, 1));
      float pulse = sincePulse < 2.0 ? pulsePower * std::exp(-(float(d) - pulsePos) * (float(d) - pulsePos) * 0.5f) : 0.0f;
      float lit = (0.8f + 0.3f * body + 1.1f * pulse) * amp;
      Color base{gold.r + (pink.r - gold.r) * t, gold.g + (pink.g - gold.g) * t, gold.b + (pink.b - gold.b) * t, 1.0f};
      float w = std::max(1.0f * px, side(f) * 0.034f * std::pow(0.7f, float(d)));
      Paint halo;
      halo.blend = Blend::plus;
      halo.strokeWidth = w * 2.6f + 4.0f * px;
      halo.strokeCap = 1;
      halo.color = {base.r, base.g, base.b, std::clamp(0.13f * lit * f.glow, 0.0f, 1.0f)};
      c.path(p, halo);
      Paint core;
      core.strokeWidth = w;
      core.strokeCap = 1;
      core.strokeJoin = 1;
      core.color = {std::min(1.0f, base.r * lit + pulse * 0.4f), std::min(1.0f, base.g * lit + pulse * 0.4f),
                    std::min(1.0f, base.b * lit + pulse * 0.4f), 1.0f};
      c.path(p, core);
    }

    if (m.hojas) {
      // Brotes en las puntas: tres grupos que parpadean desfasados.
      int first = (1 << (generations - 1)) - 1;
      std::array<std::vector<Vec2>, 3> groups;
      for (auto& g : groups) g.reserve(size_t(nodes - first) / 3 + 1);
      for (int i = first; i < nodes; i++) {
        if (!alive[size_t(i)] || length[size_t(i)] <= 0.0f) continue;
        groups[size_t(i % 3)].push_back(end[size_t(i)]);
      }
      float arrive = sincePulse < 2.0 ? pulsePower * std::exp(-std::pow(float(generations) - pulsePos, 2.0f) * 0.3f) : 0.0f;
      for (int g = 0; g < 3; g++) {
        if (groups[size_t(g)].empty()) continue;
        float tw = 0.5f + 0.5f * float(std::sin(clock * 2.3 + double(g) * 2.1));
        float r = (1.6f + 1.4f * tw + 3.0f * arrive + 2.5f * spark) * px;
        Paint halo;
        halo.blend = Blend::plus;
        halo.color = pink.opacity(std::clamp((0.18f + 0.3f * arrive) * f.glow * amp, 0.0f, 1.0f));
        c.points(groups[size_t(g)], r * 3.0f, halo);
        Paint dot;
        dot.blend = Blend::plus;
        dot.color = bloom.opacity(std::clamp((0.55f + 0.35f * tw + 0.5f * arrive) * amp, 0.0f, 1.0f));
        c.points(groups[size_t(g)], r, dot);
      }
    }
    if (flash > 0.01f) {
      Paint fl;
      fl.blend = Blend::plus;
      fl.color = bloom.opacity(std::clamp(flash * 0.06f * amp, 0.0f, 1.0f));
      c.rect({0, 0, f.width, f.height}, fl);
    }
  }

 private:
  static float side(const Frame& f) { return std::min(f.width, f.height); }
};

class Visual final : public Scene {
  static constexpr int kMaxNodes = 1023;
  static constexpr int kPetals = 70;
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  // Relojes en doble precisión: la escena sin música es idéntica a 30 y 60 FPS.
  double clock = 0, wind = 0, sincePulse = 100, sinceForm = 0;
  float pulsePower = 0, asym = 0, curl = 0;
  int beats = 0, autoForm = 0;
  // Variación fija de cada rama, elegida al reiniciar.
  std::array<float, kMaxNodes> jitterA{}, jitterL{};
  // Pétalos que caen flotando: posición, velocidad y vaivén propios.
  std::array<float, kPetals> petalX{}, petalSpeed{}, petalPhase{}, petalSway{};
  // Ramas calculadas en update y dibujadas en render.
  std::array<Vec2, kMaxNodes> start{}, end{};
  std::array<float, kMaxNodes> angle{}, length{};
  std::array<bool, kMaxNodes> alive{};
  int nodes = 0, generations = 0;

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

  static int depthOf(int i) {
    int d = 0;
    for (int n = i + 1; n > 1; n >>= 1) d++;
    return d;
  }

 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    clock = 0;
    wind = rng.unit() * 20.0;
    sincePulse = 100;
    sinceForm = 0;
    pulsePower = 0;
    asym = curl = 0;
    beats = 0;
    autoForm = 0;
    for (int i = 0; i < kMaxNodes; i++) {
      jitterA[size_t(i)] = rng.unit() * 2.0f - 1.0f;
      jitterL[size_t(i)] = rng.unit() * 2.0f - 1.0f;
    }
    for (int i = 0; i < kPetals; i++) {
      petalX[size_t(i)] = rng.unit();
      petalSpeed[size_t(i)] = 0.03f + 0.05f * rng.unit();
      petalPhase[size_t(i)] = rng.unit();
      petalSway[size_t(i)] = rng.unit() * 6.2831853f;
    }
    nodes = generations = 0;
  }

  void update(const Frame& f) override {
    auto m = modifiers(f);
    float dt = float(f.delta);
    const Music& mu = f.music;
    bass = follow(bass, mu.bass, 22.0f, 4.5f, dt);
    body = follow(body, mu.body, 12.0f, 3.0f, dt);
    spark = follow(spark, mu.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, mu.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, mu.active ? std::pow(std::clamp(mu.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : mu.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : mu.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : mu.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((mu.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, mu.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    sincePulse += f.delta;
    sinceForm += f.delta;
    if (hit > kick + 0.2f) {
      beats++;
      sincePulse = 0;
      pulsePower = hit;
      if (beats % 8 == 0) {
        autoForm = (autoForm + 1) % 3;
        sinceForm = 0;
      }
    }
    if (!mu.active && sinceForm > 11.0) {
      autoForm = (autoForm + 1) % 3;
      sinceForm = 0;
    }
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    clock += f.delta;
    wind += f.delta * f.speed * (0.7 + 1.3 * drive);

    // La forma se transforma poco a poco: asimetría y rizo hacia su objetivo.
    int form = m.forma == 0 ? autoForm : m.forma - 1;
    float asymGoal = form == 1 ? 1.0f : (form == 2 ? 0.25f : 0.0f);
    float curlGoal = form == 2 ? 1.0f : 0.0f;
    float k = 1.0f - std::exp(-dt * 1.5f);
    asym += (asymGoal - asym) * k;
    curl += (curlGoal - curl) * k;

    // Ramas: recorrido por niveles; los hijos de i son 2i+1 y 2i+2.
    generations = std::clamp(m.ramas, 5, 10);
    nodes = (1 << generations) - 1;
    float growth = float(std::min(clock / 3.0, 1.0)) * float(generations);
    float spread = m.apertura * (1.0f + 0.18f * energy + 0.12f * kick);
    float trunk = f.height * 0.26f;
    float ratio = 0.76f;
    float shortSide = std::min(f.width, f.height);
    // Con pocas generaciones el árbol es más corto: se agranda para llenar.
    float total = 0;
    for (int d = 0; d < generations; d++) total += std::pow(ratio, float(d));
    trunk = std::min(trunk * 3.6f / total, shortSide * 0.45f);
    for (int i = 0; i < nodes; i++) {
      int d = depthOf(i);
      float g = std::clamp(growth - float(d), 0.0f, 1.0f);
      alive[size_t(i)] = g > 0.0f;
      float sway = (0.05f + 0.1f * bass + 0.04f * drive) *
                   float(std::sin(wind * 0.9 + double(d) * 0.55)) * (0.4f + 0.12f * float(d));
      if (i == 0) {
        start[0] = {f.width * 0.5f, f.height * 0.94f};
        angle[0] = -1.5707963f + sway * 0.4f;
        length[0] = trunk * g;
      } else {
        int parent = (i - 1) / 2;
        float dir = (i == 2 * parent + 1) ? -1.0f : 1.0f;
        // Las ramas altas se abren menos: la copa crece hacia arriba.
        float spreadHere = spread * (1.0f + asym * 0.45f * jitterA[size_t(i)]) * (1.0f - 0.035f * float(d));
        float bend = curl * spread * 0.75f;
        angle[size_t(i)] = angle[size_t(parent)] + dir * spreadHere + bend + sway;
        float full = length[size_t(parent)] > 0 ? 1.0f : 0.0f;
        float base = trunk * std::pow(ratio, float(d)) * (1.0f + asym * 0.22f * jitterL[size_t(i)]);
        length[size_t(i)] = base * g * full;
        start[size_t(i)] = end[size_t(parent)];
      }
      end[size_t(i)] = {start[size_t(i)].x + std::cos(angle[size_t(i)]) * length[size_t(i)],
                        start[size_t(i)].y + std::sin(angle[size_t(i)]) * length[size_t(i)]};
    }
    // Encaje: si la copa se sale (formas abiertas o en espiral), el árbol se
    // reduce desde la raíz y se centra en horizontal.
    float minX = f.width * 0.5f, maxX = f.width * 0.5f, minY = start[0].y;
    for (int i = 0; i < nodes; i++) {
      if (!alive[size_t(i)]) continue;
      minX = std::min(minX, end[size_t(i)].x);
      maxX = std::max(maxX, end[size_t(i)].x);
      minY = std::min(minY, end[size_t(i)].y);
    }
    float rootY = start[0].y;
    float fit = 1.0f;
    if (maxX - minX > f.width * 0.94f) fit = std::min(fit, f.width * 0.94f / (maxX - minX));
    if (rootY - minY > rootY - f.height * 0.04f) fit = std::min(fit, (rootY - f.height * 0.04f) / (rootY - minY));
    float centerX = (minX + maxX) * 0.5f;
    float shift = f.width * 0.5f - centerX;
    if (fit < 1.0f || std::fabs(shift) > 0.5f) {
      for (int i = 0; i < nodes; i++) {
        start[size_t(i)] = {f.width * 0.5f + (start[size_t(i)].x - centerX) * fit, rootY + (start[size_t(i)].y - rootY) * fit};
        end[size_t(i)] = {f.width * 0.5f + (end[size_t(i)].x - centerX) * fit, rootY + (end[size_t(i)].y - rootY) * fit};
      }
    }
  }

  void render(const Frame& f, Canvas& c) const override {
    auto m = modifiers(f);
    float amp = f.intensity;
    const Color& bg = f.colors[0];
    const Color& gold = f.colors[1];
    const Color& pink = f.colors[2];
    const Color& bloom = f.colors[3];
    // Sin fondo: sólo un resplandor pequeño en la raíz.
    (void)bg;
    float rootR = f.width * 0.28f;
    Paint ground = Paint::radial({f.width * 0.5f, f.height * 0.95f}, rootR,
                                 {gold.opacity(0.22f + 0.2f * kick * amp), gold.opacity(0.0f)});
    c.circle({f.width * 0.5f, f.height * 0.95f}, rootR, ground);

    float px = std::min(f.width, f.height) / 400.0f;
    // Pétalos que caen desde arriba meciéndose con el viento.
    {
      std::array<std::vector<Vec2>, 2> petals;
      for (auto& g : petals) g.reserve(kPetals / 2 + 1);
      for (int i = 0; i < kPetals; i++) {
        double fall = std::fmod(wind * 0.35 * double(petalSpeed[size_t(i)]) * 10.0 + double(petalPhase[size_t(i)]), 1.0);
        float y = (float(fall) * 1.1f - 0.05f) * f.height;
        float x = petalX[size_t(i)] * f.width + float(std::sin(wind * 0.8 + double(petalSway[size_t(i)]))) * 18.0f * px;
        petals[size_t(i % 2)].push_back({x, y});
      }
      for (int g = 0; g < 2; g++) {
        Paint petal;
        petal.blend = Blend::plus;
        const Color& pc = g == 0 ? pink : gold;
        petal.color = pc.opacity(std::clamp((0.35f + 0.4f * kick + 0.3f * spark) * amp, 0.0f, 1.0f));
        c.points(petals[size_t(g)], (1.6f + 0.8f * float(g) + 1.5f * kick) * px, petal);
      }
    }
    float pulsePos = float(sincePulse) * 9.0f;
    for (int d = 0; d < generations; d++) {
      Path p;
      int first = (1 << d) - 1;
      int last = std::min((1 << (d + 1)) - 1, nodes);
      bool any = false;
      for (int i = first; i < last; i++) {
        if (!alive[size_t(i)] || length[size_t(i)] <= 0.0f) continue;
        p.moveTo(start[size_t(i)].x, start[size_t(i)].y);
        p.lineTo(end[size_t(i)].x, end[size_t(i)].y);
        any = true;
      }
      if (!any) continue;
      float t = float(d) / float(std::max(generations - 1, 1));
      float pulse = sincePulse < 2.0 ? pulsePower * std::exp(-(float(d) - pulsePos) * (float(d) - pulsePos) * 0.5f) : 0.0f;
      float lit = (0.8f + 0.3f * body + 1.1f * pulse) * amp;
      Color base{gold.r + (pink.r - gold.r) * t, gold.g + (pink.g - gold.g) * t, gold.b + (pink.b - gold.b) * t, 1.0f};
      float w = std::max(1.0f * px, side(f) * 0.034f * std::pow(0.7f, float(d)));
      Paint halo;
      halo.blend = Blend::plus;
      halo.strokeWidth = w * 2.6f + 4.0f * px;
      halo.strokeCap = 1;
      halo.color = {base.r, base.g, base.b, std::clamp(0.13f * lit * f.glow, 0.0f, 1.0f)};
      c.path(p, halo);
      Paint core;
      core.strokeWidth = w;
      core.strokeCap = 1;
      core.strokeJoin = 1;
      core.color = {std::min(1.0f, base.r * lit + pulse * 0.4f), std::min(1.0f, base.g * lit + pulse * 0.4f),
                    std::min(1.0f, base.b * lit + pulse * 0.4f), 1.0f};
      c.path(p, core);
    }

    if (m.hojas) {
      // Brotes en las puntas: tres grupos que parpadean desfasados.
      int first = (1 << (generations - 1)) - 1;
      std::array<std::vector<Vec2>, 3> groups;
      for (auto& g : groups) g.reserve(size_t(nodes - first) / 3 + 1);
      for (int i = first; i < nodes; i++) {
        if (!alive[size_t(i)] || length[size_t(i)] <= 0.0f) continue;
        groups[size_t(i % 3)].push_back(end[size_t(i)]);
      }
      float arrive = sincePulse < 2.0 ? pulsePower * std::exp(-std::pow(float(generations) - pulsePos, 2.0f) * 0.3f) : 0.0f;
      for (int g = 0; g < 3; g++) {
        if (groups[size_t(g)].empty()) continue;
        float tw = 0.5f + 0.5f * float(std::sin(clock * 2.3 + double(g) * 2.1));
        float r = (1.6f + 1.4f * tw + 3.0f * arrive + 2.5f * spark) * px;
        Paint halo;
        halo.blend = Blend::plus;
        halo.color = pink.opacity(std::clamp((0.18f + 0.3f * arrive) * f.glow * amp, 0.0f, 1.0f));
        c.points(groups[size_t(g)], r * 3.0f, halo);
        Paint dot;
        dot.blend = Blend::plus;
        dot.color = bloom.opacity(std::clamp((0.55f + 0.35f * tw + 0.5f * arrive) * amp, 0.0f, 1.0f));
        c.points(groups[size_t(g)], r, dot);
      }
    }
  }

 private:
  static float side(const Frame& f) { return std::min(f.width, f.height); }
};

class Visual final : public Scene {
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  // Relojes en doble precisión: la escena sin música es idéntica a 30 y 60 FPS.
  double travel = 0, clock = 0;
  float boost = 0;

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    travel = rng.unit() * 10.0;
    clock = rng.unit() * 50.0;
    boost = 0;
  }

  void update(const Frame& f) override {
    float dt = float(f.delta);
    const Music& m = f.music;
    bass = follow(bass, m.bass, 22.0f, 4.5f, dt);
    body = follow(body, m.body, 12.0f, 3.0f, dt);
    spark = follow(spark, m.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, m.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, m.active ? std::pow(std::clamp(m.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : m.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : m.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : m.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((m.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, m.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    if (hit > kick + 0.2f) boost = std::max(boost, hit);
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    boost *= std::exp(-dt * 3.0f);
    travel += f.delta * f.speed * (0.45 + 0.9 * drive + 1.5 * boost);
    clock += f.delta * f.speed;
  }

  void render(const Frame& f, Canvas& c) const override {
    float amp = f.intensity;
    std::vector<float> u;
    u.reserve(20);
    u.insert(u.end(), {float(std::fmod(travel, 1000.0)), bass * amp, kick * amp, energy});
    u.insert(u.end(), {float(std::fmod(clock, 1000.0)), f.glow, spark * amp, flash * amp});
    for (int i = 0; i < 4; i++) u.insert(u.end(), {f.colors[i].r, f.colors[i].g, f.colors[i].b});
    c.material("dream_arches", {0, 0, f.width, f.height}, u);
  }
};

shaderSources.dream_arches:
#version 460 core
#include <flutter/runtime_effect.glsl>
uniform vec2 uSize;
uniform vec4 uA;   // avance, graves, golpe, energía
uniform vec4 uB;   // reloj, glow, agudos, destello
uniform vec3 uC0;
uniform vec3 uC1;
uniform vec3 uC2;
uniform vec3 uC3;
out vec4 fragColor;

const float PI = 3.14159265;

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash12(i), hash12(i + vec2(1.0, 0.0)), u.x),
             mix(hash12(i + vec2(0.0, 1.0)), hash12(i + vec2(1.0, 1.0)), u.x), u.y);
}

vec3 paint(float x) {
  float k = fract(x) * 4.0;
  vec3 cream = vec3(1.0, 0.86, 0.6);
  vec3 a = k < 1.0 ? uC1 : (k < 2.0 ? uC2 : (k < 3.0 ? cream : uC2));
  vec3 b = k < 1.0 ? uC2 : (k < 2.0 ? cream : (k < 3.0 ? uC2 : uC1));
  return mix(a, b, smoothstep(0.6, 1.0, fract(k)));
}

void main() {
  vec2 frag = FlutterFragCoord().xy;
  float scale = min(uSize.x, uSize.y);
  vec2 p = (frag - 0.5 * uSize) / scale;
  float t = uB.x;
  float travel = uA.x;
  // El pasillo respira con los graves y se ondula suavemente.
  p += 0.012 * vec2(sin(p.y * 6.0 + t), cos(p.x * 5.0 - t * 0.8)) * (1.0 + 2.0 * uA.y);
  p.y += 0.12;
  // Sección en arco: paredes rectas, suelo plano y bóveda semicircular.
  float s = p.y > 0.0 ? length(p) : max(abs(p.x), -p.y * 1.25);
  s = max(s, 1e-4);
  float z = 0.32 / s;
  float depth = z + travel;
  bool floorZone = p.y < 0.0 && -p.y * 1.25 > abs(p.x);
  vec3 col;
  if (floorZone) {
    // Suelo: río de ondas turquesa, crema y rojo.
    float u = p.x / (-p.y * 1.25);
    float river = u * 2.5 + 0.6 * sin(depth * 1.3 + u * 2.0) + 0.3 * noise(vec2(u * 3.0, depth * 0.8));
    float k = fract(river);
    vec3 cream = vec3(1.0, 0.9, 0.75);
    col = k < 0.33 ? uC3 : (k < 0.55 ? cream : (k < 0.8 ? uC1 : cream * 0.85));
    col *= 0.7 + 0.3 * smoothstep(0.0, 0.08, min(abs(k - 0.33), abs(k - 0.8)));
  } else {
    // Paredes y bóveda: bandas verticales que gotean.
    float v = p.y > 0.0 ? atan(p.x, p.y) / PI : (p.x > 0.0 ? 0.5 + (-p.y / s) * 0.5 : -0.5 - (-p.y / s) * 0.5);
    float melt = noise(vec2(v * 9.0, depth * 0.6)) * 0.5 + noise(vec2(v * 22.0, depth * 1.4 - t * 0.2)) * 0.25;
    col = paint(v * 1.6 + melt + depth * 0.05);
    // Arcos: anillos más oscuros con borde dorado a intervalos regulares.
    float fz = fract(depth * 0.5);
    float arch = smoothstep(0.0, 0.05, fz) * smoothstep(0.4, 0.3, fz);
    col = mix(col, col * vec3(0.35, 0.18, 0.12), arch);
    // Borde dorado del arco, nítido y brillante.
    col += mix(uC2, vec3(1.0, 0.9, 0.6), 0.4) * exp(-abs(fz - 0.4) * 60.0) * (0.6 + 0.9 * uA.z) * uB.y;
    col += uC2 * exp(-abs(fz) * 60.0) * 0.4 * uB.y;
    // Agujeros y manchas que salpican las paredes.
    float blot = smoothstep(0.82, 0.86, noise(vec2(v * 14.0, depth * 2.0)));
    col = mix(col, uC3 * 0.8, blot * 0.6);
  }
  // Niebla cálida y puerta de luz al fondo.
  col *= exp(-z * 0.11) * (0.85 + 0.35 * uA.y + 0.25 * uA.z);
  vec2 dp = p - vec2(0.0, 0.015);
  float door = smoothstep(0.06, 0.03, s);
  col = mix(col, mix(uC1, vec3(1.0, 0.8, 0.6), 0.4) * (1.2 + uB.w), door);
  col += vec3(1.0, 0.85, 0.7) * exp(-dot(dp, dp) * 3000.0) * (0.6 + 0.8 * uA.z);
  col += uC2 * uB.w * 0.05;
  col += (hash12(frag) - 0.5) / 255.0;
  fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

