    hit = std::min(std::max(hit, onset), 1.0f);
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    clock += f.delta * f.speed;
  }

  void render(const Frame& f, Canvas& c) const override {
    auto g = glide(f);
    const auto& pal = f.colors;
    const float amp = f.intensity;
    const float W = f.width, H = f.height;
    const float side = std::min(W, H);
    const float px = side / 400.0f;
    // Carácter: el tiempo corre suave o avanza a saltos de mecanismo.
    const double tt = clock;
    const double tq = (std::floor(tt * 1.5) + double(std::clamp(float((tt * 1.5 - std::floor(tt * 1.5) - 0.75) / 0.25), 0.0f, 1.0f))) / 1.5;
    const float at = float(g.ritmo.weight(0) * tt + g.ritmo.weight(1) * tq);
    const float wGolpes = g.pulso.weight(0), wGraves = g.pulso.weight(1), wDest = g.pulso.weight(2);
    const float punch = std::min(kick * amp, 1.0f) * wGolpes;
    // Graves: el ornamento respira más hondo y sus líneas se engrosan y brillan.
    const float graves = std::min(bass * amp, 1.0f) * wGraves;
    const float breath = 1.0f + 0.16f * graves;
    // Destellos: el resplandor de las líneas centellea con los agudos.
    const float shimmer = std::min(spark * amp, 1.0f) * wDest * (0.55f + 0.45f * float(std::sin(clock * 17.0)));
    const float lujo = std::clamp(g.lujo, 0.0f, 1.0f);
    const float fill = std::clamp(g.relleno, 0.0f, 1.0f);
    const Color& bg = pal[0];
    c.rect({0, 0, W, H}, Paint::radial({W * 0.5f, H * 0.55f}, std::max(W, H) * 0.8f,
                                       {Color{std::min(1.0f, bg.r + pal[1].r * 0.08f), std::min(1.0f, bg.g + pal[1].g * 0.05f), std::min(1.0f, bg.b + pal[1].b * 0.05f), 1.0f},
                                        Color{bg.r, bg.g, bg.b, 1.0f}}));
    // Oro: un degradado de dos tonos cuyo brillo recorre la pantalla.
    const float sweep = float(std::sin(clock * 0.4)) * W * 0.35f * (0.3f + 0.7f * lujo);
    auto gold = [&](float width) {
      Paint p = Paint::linear({-W * 0.3f + sweep, -H * 0.2f}, {W * 1.3f + sweep, H * 1.2f},
                              {pal[2], pal[3], pal[2], pal[3], pal[2], pal[3], pal[2]});
      p.strokeWidth = width * (1.0f + 0.6f * graves);
      p.strokeJoin = 0;
      return p;
    };
    auto glowPaint = [&](float width) {
      Paint p;
      p.blend = Blend::plus;
      p.strokeWidth = width;
      p.strokeCap = 1;
      p.color = pal[3].opacity(std::clamp((0.06f + 0.14f * lujo + 0.3f * punch + 0.14f * graves + 0.2f * shimmer) * f.glow, 0.0f, 0.8f));
      return p;
    };
    // Golpes: un filo de luz que sólo existe mientras dura el golpe.
    auto beatGlow = [&](float width) {
      Paint p;
      p.blend = Blend::plus;
      p.strokeWidth = width;
      p.strokeCap = 1;
      p.color = pal[3].opacity(std::clamp(0.4f * punch * f.glow, 0.0f, 0.6f));
      return p;
    };
    std::vector<Vec2> sparkA, sparkB;
    // Segmentos por los que corren los destellos.
    auto sparkOn = [&](Vec2 a, Vec2 b, int id) {
      if (wDest < 0.01f) return;
      const float s = float(std::fmod(at * 0.5 + double(id) * 0.37, 1.0));
      if (hashU(uint32_t(id) * 2654435761u + uint32_t(std::floor(at * 2.0f))) > spark * amp * wDest * 2.4f) return;
      sparkA.push_back({a.x + (b.x - a.x) * s, a.y + (b.y - a.y) * s});
    };
    const int rays = std::clamp(int(std::lround(16.0f + 12.0f * f.detail)), 16, 40);

    // Todo el ornamento queda dentro del marco.
    const float inset = side * 0.05f + 6.0f * px;
    Path inside;
    inside.rect({inset, inset, W - 2.0f * inset, H - 2.0f * inset});
    c.save();
    c.clip(inside);
    c.save();
    c.translate(W * 0.5f, H * 0.55f);
    c.scale(breath, breath);
    c.translate(-W * 0.5f, -H * 0.55f);

    // SOL: rayos desde un sol bajo, con arcos escalonados encima.
    const float wSol = g.motivo.weight(0);
    if (wSol > 0.01f) {
      if (wSol < 0.99f) c.saveLayer(wSol);
      const Vec2 O{W * 0.5f, H * 0.64f};
      const float r0 = side * 0.13f;
      Path thick, thin, wedgeA;
      for (int i = 0; i < rays; i++) {
        const float a = -3.14159265f + 0.15f + (3.14159265f - 0.3f) * (float(i) + 0.5f) / float(rays);
        const float open = 0.85f + 0.15f * std::sin(at * 0.9f + float(i) * 0.25f);
        // Golpes: los rayos se disparan casi al doble de largo.
        const float L = side * (i % 2 == 0 ? 0.8f : 0.58f) * open * (1.0f + 0.8f * punch);
        const Vec2 a0{O.x + r0 * std::cos(a), O.y + r0 * std::sin(a)};
        const Vec2 a1{O.x + L * std::cos(a), O.y + L * std::sin(a)};
        (i % 2 == 0 ? thick : thin).moveTo(a0.x, a0.y).lineTo(a1.x, a1.y);
        sparkOn(a0, a1, i);
        if (i % 2 == 0 && i + 1 < rays) {
          const float b = -3.14159265f + 0.15f + (3.14159265f - 0.3f) * (float(i) + 1.5f) / float(rays);
          wedgeA.moveTo(a0.x, a0.y).lineTo(a1.x, a1.y).lineTo(O.x + L * 0.72f * std::cos(b), O.y + L * 0.72f * std::sin(b))
              .lineTo(O.x + r0 * std::cos(b), O.y + r0 * std::sin(b)).close();
        }
      }
      if (fill > 0.01f) {
        Paint wp = Paint::radial(O, side * 0.8f, {pal[1].opacity(0.95f * fill), pal[1].opacity(0.35f * fill)});
        c.path(wedgeA, wp);
      }
      c.path(thick, glowPaint(6.0f * px));
      if (punch > 0.01f) c.path(thin, beatGlow(4.0f * px));
      c.path(thick, gold(2.4f * px));
      c.path(thin, gold(1.1f * px));
      // Arcos escalonados como la puerta de un rascacielos.
      Path arches;
      for (int k = 0; k < 4; k++) {
        const float r = side * (0.17f + 0.075f * float(k)) * (0.97f + 0.03f * std::sin(at * 1.3f - float(k)));
        const float foot = O.y + side * 0.06f * float(k + 1);
        arches.moveTo(O.x - r - side * 0.03f, foot).lineTo(O.x - r, foot).lineTo(O.x - r, O.y);
        arc(arches, O, r, -3.14159265f, 0.0f, 28, false);
        arches.lineTo(O.x + r, foot).lineTo(O.x + r + side * 0.03f, foot);
      }
      c.path(arches, glowPaint(5.0f * px));
      c.path(arches, gold(1.6f * px));
      // Golpes: el sol late, más grande y con un halo de luz alrededor.
      if (punch > 0.01f) {
        Paint halo = Paint::radial(O, r0 * (1.5f + 0.7f * punch),
                                   {pal[3].opacity(std::clamp(0.45f * punch * f.glow, 0.0f, 0.6f)), pal[3].opacity(0.0f)});
        halo.blend = Blend::plus;
        c.circle(O, r0 * (1.5f + 0.7f * punch), halo);
      }
      Paint sun = Paint::radial(O, r0, {pal[3], pal[2]});
      c.circle(O, r0 * (0.92f + 0.36f * punch), sun);
      Path sunRings;
      sunRings.circle(O, r0 * 0.7f);
      sunRings.circle(O, r0 * 0.45f);
      Paint sr;
      sr.strokeWidth = 1.2f * px;
      sr.color = pal[1].opacity(0.8f);
      c.path(sunRings, sr);
      Path base;
      base.moveTo(W * 0.08f, O.y + side * 0.3f).lineTo(W * 0.92f, O.y + side * 0.3f);
      base.moveTo(W * 0.08f, O.y + side * 0.32f).lineTo(W * 0.92f, O.y + side * 0.32f);
      c.path(base, gold(1.4f * px));
      if (wSol < 0.99f) c.restore();
    }

    // ABANICOS: mosaico de abanicos que se abren y cierran en olas.
    const float wFan = g.motivo.weight(1);
    if (wFan > 0.01f) {
      if (wFan < 0.99f) c.saveLayer(wFan);
      const int cols = std::clamp(int(std::lround(2.0f + 1.2f * f.detail)), 2, 5);
      const float fr = W / float(cols) * 0.5f;
      const int rows = int(H / (fr * 0.55f)) + 3;
      int id = 100;
      // Golpes: los abanicos se abren de par en par y su borde se enciende.
      Path fanBeat;
      for (int row = 0; row < rows; row++) {
        const float cy = -fr * 0.5f + float(row) * fr * 0.55f;
        const float shift = (row % 2 == 0) ? 0.0f : fr;
        for (int col = -1; col <= cols; col++) {
          const Vec2 O{float(col) * fr * 2.0f + fr + shift, cy + fr};
          const float open = std::clamp(0.55f + 0.45f * std::sin(at * 1.2f - float(row) * 0.5f - float(col) * 0.3f) + 0.7f * punch, 0.2f, 1.0f);
          const float span = 3.14159265f * open;
          const float a0 = -1.5707963f - span * 0.5f, a1 = -1.5707963f + span * 0.5f;
          Path fan;
          fan.moveTo(O.x, O.y);
          arc(fan, O, fr, a0, a1, 20, false);
          fan.close();
          if (fill > 0.01f) {
            Paint fp = Paint::radial(O, fr, {(row % 2 == 0 ? pal[1] : bg).opacity(0.95f * fill), pal[1].opacity(0.55f * fill)});
            c.path(fan, fp);
          }
          Path lines;
          for (int k = 0; k <= 6; k++) {
            const float a = a0 + span * float(k) / 6.0f;
            lines.moveTo(O.x, O.y).lineTo(O.x + fr * std::cos(a), O.y + fr * std::sin(a));
          }
          arc(lines, O, fr * 0.45f, a0, a1, 12, true);
          arc(lines, O, fr * 0.75f, a0, a1, 14, true);
          c.path(fan, gold(1.8f * px));
          c.path(lines, gold(0.9f * px));
          if (punch > 0.01f) arc(fanBeat, O, fr, a0, a1, 20, true);
          sparkOn({O.x + fr * std::cos(a0), O.y + fr * std::sin(a0)}, {O.x + fr * std::cos(a1), O.y + fr * std::sin(a1)}, id++);
        }
      }
      if (punch > 0.01f) c.path(fanBeat, beatGlow(5.0f * px));
      if (wFan < 0.99f) c.restore();
    }

    // TORRE: la corona del Chrysler, arcos que se encienden de abajo arriba.
    const float wTorre = g.motivo.weight(2);
    if (wTorre > 0.01f) {
      if (wTorre < 0.99f) c.saveLayer(wTorre);
      const float cx = W * 0.5f;
      // Líneas de velocidad que suben a los lados.
      Path speed;
      for (int i = 0; i < 10; i++) {
        const float x = W * (0.06f + 0.035f * float(i % 5)) + (i >= 5 ? W * 0.72f : 0.0f);
        const float len = H * 0.12f;
        const float y = H - float(std::fmod(double(at) * 0.18 * double(H) + double(i) * 0.37 * double(H), double(H + len)));
        speed.moveTo(x, y).lineTo(x, y + len);
      }
      c.path(speed, gold(1.0f * px));
      Path crown, windows;
      int id = 300;
      for (int k = 0; k < 6; k++) {
        const float r = W * (0.4f - 0.055f * float(k));
        const float by = H * (0.86f - 0.095f * float(k));
        const float lightK = std::clamp(0.5f + 0.5f * std::sin(at * 2.0f - float(k) * 0.9f) + punch, 0.0f, 1.0f);
        crown.moveTo(cx - r, by + H * 0.06f).lineTo(cx - r, by);
        arc(crown, {cx, by}, r, -3.14159265f, 0.0f, 30, false);
        crown.lineTo(cx + r, by + H * 0.06f);
        // Ventanas triangulares en abanico a lo largo de cada arco.
        const int teeth = 7 + k;
        for (int j = 0; j < teeth; j++) {
          const float a = -3.14159265f + 3.14159265f * (float(j) + 0.5f) / float(teeth);
          const float da = 3.14159265f / float(teeth) * 0.35f;
          windows.moveTo(cx + r * 0.78f * std::cos(a - da), by + r * 0.78f * std::sin(a - da))
              .lineTo(cx + r * 0.95f * std::cos(a), by + r * 0.95f * std::sin(a))
              .lineTo(cx + r * 0.78f * std::cos(a + da), by + r * 0.78f * std::sin(a + da))
              .close();
        }
        if (lightK > 0.05f) {
          Paint lit;
          lit.blend = Blend::plus;
          // Golpes: toda la corona se enciende de golpe.
          lit.color = pal[3].opacity(std::clamp((0.12f * lightK + 0.16f * punch) * f.glow, 0.0f, 1.0f));
          Path glowArc;
          glowArc.moveTo(cx - r, by);
          arc(glowArc, {cx, by}, r, -3.14159265f, 0.0f, 30, false);
          glowArc.close();
          c.path(glowArc, lit);
        }
        sparkOn({cx - r, by}, {cx + r, by - r * 0.2f}, id++);
      }
      if (fill > 0.01f) {
        Paint wp;
        wp.color = pal[1].opacity(0.9f * fill);
        c.path(windows, wp);
      }
      c.path(crown, glowPaint(5.0f * px));
      if (punch > 0.01f) c.path(windows, beatGlow(3.0f * px));
      c.path(crown, gold(1.8f * px));
      c.path(windows, gold(1.0f * px));
      // La aguja de la cúspide con su rombo.
      const float topY = H * (0.86f - 0.095f * 5.0f) - W * (0.4f - 0.055f * 5.0f);
      Path spire;
      spire.moveTo(cx, topY).lineTo(cx, H * 0.05f);
      spire.moveTo(cx, H * 0.1f - side * 0.04f).lineTo(cx + side * 0.025f, H * 0.1f).lineTo(cx, H * 0.1f + side * 0.04f)
          .lineTo(cx - side * 0.025f, H * 0.1f).close();
      c.path(spire, glowPaint(5.0f * px));
      c.path(spire, gold(1.8f * px));
      sparkOn({cx, topY}, {cx, H * 0.05f}, id++);
      if (wTorre < 0.99f) c.restore();
    }
    c.restore();
    c.restore();

    // Marco doble con esquinas escalonadas y rombos arriba y abajo.
    {
      const float m = side * 0.05f;
      const float s = side * 0.035f;
      Path frame;
      auto stepped = [&](float inset) {
        const float x0 = m + inset, y0 = m + inset, x1 = W - m - inset, y1 = H - m - inset;
        frame.moveTo(x0 + s, y0).lineTo(x1 - s, y0).lineTo(x1 - s, y0 + s).lineTo(x1, y0 + s)
            .lineTo(x1, y1 - s).lineTo(x1 - s, y1 - s).lineTo(x1 - s, y1).lineTo(x0 + s, y1)
            .lineTo(x0 + s, y1 - s).lineTo(x0, y1 - s).lineTo(x0, y0 + s).lineTo(x0 + s, y0 + s).close();
      };
      stepped(0.0f);
      stepped(6.0f * px);
      Path gems;
      for (int k = 0; k < 2; k++) {
        const float y = k == 0 ? m : H - m;
        gems.moveTo(W * 0.5f, y - side * 0.03f).lineTo(W * 0.5f + side * 0.045f, y).lineTo(W * 0.5f, y + side * 0.03f)
            .lineTo(W * 0.5f - side * 0.045f, y).close();
      }
      Paint gemFill;
      gemFill.color = pal[1];
      c.path(gems, gemFill);
      c.path(frame, glowPaint(4.0f * px));
      c.path(frame, gold(1.3f * px));
      c.path(gems, gold(1.3f * px));
    }
    if (!sparkA.empty()) {
      Paint sp;
      sp.blend = Blend::plus;
      sp.color = pal[3].opacity(0.95f);
      c.points(sparkA, 3.2f * px, sp);
      Paint halo;
      halo.blend = Blend::plus;
      halo.color = pal[3].opacity(std::clamp(0.32f * f.glow, 0.0f, 0.6f));
      c.points(sparkA, 10.0f * px, halo);
    }
    if (flash > 0.01f) {
      Paint fl;
      fl.blend = Blend::plus;
      fl.color = pal[2].opacity(std::clamp(flash * 0.06f * amp, 0.0f, 1.0f));
      c.rect({0, 0, W, H}, fl);
    }
    (void)sparkB;
  }
};

class Visual final : public Scene {
  static constexpr int kPresets = 7;
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  // Relojes en doble precisión: la escena sin música es idéntica a 30 y 60 FPS.
  double morph = 0, spin = 0, sinceShape = 0;
  float fade = 1;
  int beats = 0, from = 0, to = 0;
  // Onda de choque del último golpe y reloj de los destellos de los agudos.
  double ringAge = 100, shimmer = 0;
  float ringPower = 0;
  mutable std::vector<float> raw;
  mutable std::array<std::vector<Vec2>, 3> groups;
  mutable std::vector<Vec2> lit, glints;

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }
  static float hashU(uint32_t x) {
    x ^= x >> 16; x *= 0x7feb352dU; x ^= x >> 15; x *= 0x846ca68bU; x ^= x >> 16;
    return float(x & 0xffffffu) / 16777216.0f;
  }

  // Formas probadas y cuánto pueden variar sin caer en una órbita pobre
  // (comprobado recorriendo todas las variaciones posibles).
  static float preset(int k, float& a, float& b, float& c, float& d) {
    static const float P[kPresets][5] = {{-1.4f, 1.6f, 1.0f, 0.7f, 0.4f},    {1.5f, -1.8f, 1.6f, 0.9f, 0.4f},
                                         {-1.8f, -2.0f, -0.5f, -0.9f, 0.6f}, {-1.3f, -1.3f, -1.8f, -1.9f, 0.6f},
                                         {1.5f, -1.8f, 1.6f, 2.0f, 0.6f},    {-1.9f, -1.9f, -1.9f, -1.0f, 1.0f},
                                         {-1.6f, 1.6f, 0.7f, -1.0f, 0.6f}};
    a = P[k][0];
    b = P[k][1];
    c = P[k][2];
    d = P[k][3];
    return P[k][4];
  }

  // Itera una forma y deja sus puntos (en el espacio del atractor) en raw.
  void iterate(int k, int n, float wobble, float push, size_t offset) const {
    float a, b, c, d;
    float safe = preset(k, a, b, c, d);
    a += 0.05f * safe * std::sin(wobble);
    b += 0.05f * safe * std::sin(wobble * 0.8f + 1.0f);
    c += (0.04f * std::sin(wobble * 0.6f + 2.0f) + push) * safe;
    d += 0.04f * safe * std::sin(wobble * 0.7f + 3.0f);
    // Algunas variaciones caen en una órbita de pocos puntos: se prueban 400
    // saltos y, si casi no ocupan sitio, se usa la forma pura (siempre rica).
    {
      std::array<uint8_t, 1024> seen{};
      int distinct = 0;
      float x = 0.1f, y = 0.1f;
      for (int i = 0; i < 420; i++) {
        float nx = std::sin(a * y) + c * std::cos(a * x);
        float ny = std::sin(b * x) + d * std::cos(b * y);
        x = nx;
        y = ny;
        if (i < 20) continue;
        int gx = std::clamp(int((x + 3.0f) * 32.0f / 6.0f), 0, 31), gy = std::clamp(int((y + 3.0f) * 32.0f / 6.0f), 0, 31);
        if (!seen[size_t(gy * 32 + gx)]) {
          seen[size_t(gy * 32 + gx)] = 1;
          distinct++;
        }
      }
      if (distinct < 40) preset(k, a, b, c, d);
    }
    float x = 0.1f, y = 0.1f;
    for (int i = 0; i < n + 20; i++) {
      float nx = std::sin(a * y) + c * std::cos(a * x);
      float ny = std::sin(b * x) + d * std::cos(b * y);
      float jump = std::fabs(nx - x) + std::fabs(ny - y);
      x = nx;
      y = ny;
      if (i < 20) continue;
      size_t j = (offset + size_t(i - 20)) * 3;
      raw[j] = x;
      raw[j + 1] = y;
      raw[j + 2] = jump;
    }
  }

 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    morph = rng.unit() * 60.0;
    spin = rng.unit() * 6.28;
    sinceShape = 0;
    fade = 1;
    beats = 0;
    from = to = int(seed % uint32_t(kPresets));
    raw.assign(30000 * 3, 0.0f);
    for (auto& g : groups) g.reserve(30000);
    ringAge = 100;
    ringPower = 0;
    shimmer = 0;
    lit.reserve(30000);
    glints.reserve(30000);
  }

  void update(const Frame& f) override {
    auto m = modifiers(f);
    float dt = float(f.delta);
    const Music& mu = f.music;
    bass = follow(bass, mu.bass, 22.0f, 4.5f, dt);
    body = follow(body, mu.body, 12.0f, 3.0f, dt);
    spark = follow(spark, mu.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, mu.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, mu.active ? std::pow(std::clamp(mu.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : mu.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : mu.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : mu.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((mu.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, mu.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    sinceShape += f.delta;
    // El fundido avanza antes de mirar cambios: si el cambio es por tiempo,
    // empieza en su instante exacto (igual a 30 y 60 FPS).
    fade = std::min(1.0f, fade + dt / 2.0f);
    bool next = false;
    double carry = -1.0;
    if (hit > kick + 0.2f && ++beats % 8 == 0) next = true;
    if (!mu.active && sinceShape > 10.0) {
      next = true;
      sinceShape -= 10.0;
      carry = sinceShape;
    }
    if (next) {
      from = to;
      to = (to + 1) % kPresets;
      fade = carry >= 0.0 ? std::min(1.0f, float(carry / 2.0)) : 0.0f;
      if (mu.active) sinceShape = 0;
    }
    // Cada golpe lanza una onda de choque desde el centro de la nube.
    ringAge += f.delta;
    shimmer += f.delta;
    if (hit > kick + 0.2f) {
      ringAge = 0.0;
      ringPower = hit;
    }
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    morph += f.delta * f.speed * m.cambio * (0.25 + 0.6 * drive);
    if (m.giro) spin += f.delta * f.speed * (0.05 + 0.08 * drive);
  }

  void render(const Frame& f, Canvas& c) const override {
    auto m = modifiers(f);
    auto gl = glide(f);
    float amp = f.intensity;
    // Pulso: cada opción mueve algo distinto; sin música todo vale cero.
    const float kickP = std::min(kick * amp, 1.0f) * gl.pulso.weight(0);
    const float bassP = std::min(bass * amp, 1.0f) * gl.pulso.weight(1);
    const float sparkP = std::min(spark * amp, 1.0f) * gl.pulso.weight(2);
    const Color& bg = f.colors[0];
    c.rect({0, 0, f.width, f.height}, Paint::radial({f.width * 0.5f, f.height * 0.5f}, std::max(f.width, f.height) * 0.7f,
                                                   {Color{std::min(1.0f, bg.r + f.colors[1].r * 0.05f), std::min(1.0f, bg.g + 0.01f), bg.b, 1.0f},
                                                    Color{bg.r, bg.g, bg.b, 1.0f}}));
    int total = std::clamp(m.miles, 1, 30) * 1000;
    float e = fade * fade * (3.0f - 2.0f * fade);
    int nTo = fade >= 1.0f ? total : int(float(total) * e);
    int nFrom = total - nTo;
    float wobble = float(std::fmod(morph, 1000.0));
    float push = 0.06f * bass * amp;
    if (nFrom > 0) iterate(from, nFrom, wobble, push, 0);
    if (nTo > 0) iterate(to, nTo, wobble, push, size_t(nFrom));
    int n = nFrom + nTo;
    // Encuadre según la figura real: ocupa la pantalla sea cual sea la forma.
    float minX = 1e9f, maxX = -1e9f, minY = 1e9f, maxY = -1e9f;
    for (int i = 0; i < n; i++) {
      minX = std::min(minX, raw[size_t(i) * 3]);
      maxX = std::max(maxX, raw[size_t(i) * 3]);
      minY = std::min(minY, raw[size_t(i) * 3 + 1]);
      maxY = std::max(maxY, raw[size_t(i) * 3 + 1]);
    }
    float cx = (minX + maxX) * 0.5f, cy = (minY + maxY) * 0.5f;
    float hx = std::max(0.05f, (maxX - minX) * 0.5f), hy = std::max(0.05f, (maxY - minY) * 0.5f);
    float rot = float(std::fmod(spin, 6.2831853));
    float cr = std::cos(rot), sr = std::sin(rot);
    float scale = m.giro ? std::min(f.width, f.height) * 0.47f / std::sqrt(hx * hx + hy * hy)
                         : std::min(f.width * 0.47f / hx, f.height * 0.47f / hy);
    scale *= 1.0f + 0.04f * kick * amp;
    // Golpes: la nube da un salto; Graves: crece despacio con los graves.
    scale *= 1.0f + 0.15f * kickP + 0.14f * bassP;
    float px = std::min(f.width, f.height) / 400.0f;
    // Onda de choque de cada golpe: un anillo que sale del centro, empuja los
    // velos hacia fuera y enciende los puntos por donde pasa.
    const float maxR = std::min(f.width, f.height) * 0.5f;
    const float ringR = float(std::min(ringAge, 10.0)) * 1.7f;
    const float ring = ringAge < 1.6 ? std::min(ringPower * amp, 1.0f) * std::exp(-float(ringAge) * 2.2f) * gl.pulso.weight(0) : 0.0f;
    // Agudos: temblor fino y destellos sueltos que cambian 14 veces por segundo.
    const uint32_t tick = uint32_t(std::fmod(shimmer, 100000.0) * 14.0);
    const bool react = ring > 0.002f || sparkP > 0.002f;
    for (auto& g : groups) g.clear();
    lit.clear();
    glints.clear();
    for (int i = 0; i < n; i++) {
      float x = raw[size_t(i) * 3] - cx, y = raw[size_t(i) * 3 + 1] - cy, jump = raw[size_t(i) * 3 + 2];
      float X = f.width * 0.5f + (x * cr - y * sr) * scale;
      float Y = f.height * 0.5f + (x * sr + y * cr) * scale;
      if (react) {
        if (ring > 0.002f) {
          const float dx = X - f.width * 0.5f, dy = Y - f.height * 0.5f;
          const float r = std::sqrt(dx * dx + dy * dy) + 1e-3f;
          const float d = (r / maxR - ringR) / 0.09f;
          const float band = std::exp(-d * d) * ring;
          X += dx / r * band * 0.12f * maxR;
          Y += dy / r * band * 0.12f * maxR;
          if (band > 0.12f) lit.push_back({X, Y});
        }
        if (sparkP > 0.002f) {
          const uint32_t h = uint32_t(i) * 2654435761u + tick * 40503u;
          X += (hashU(h) - 0.5f) * 3.5f * px * sparkP;
          Y += (hashU(h ^ 0x9e3779b9u) - 0.5f) * 3.5f * px * sparkP;
          if (hashU(h + 7u) < 0.15f * sparkP) glints.push_back({X, Y});
        }
      }
      int g = jump < 1.1f ? 0 : (jump < 2.3f ? 1 : 2);
      groups[size_t(g)].push_back({X, Y});
    }
    float density = std::clamp(18000.0f / float(std::max(n, 1)), 0.5f, 3.0f);
    // Brillo básico (glow 0..2): la luz de cada punto, nunca a cero.
    float light = 0.4f + 0.6f * std::clamp(f.glow, 0.0f, 2.0f);
    // Grano: puntos más gruesos y cada uno más tenue, así la luz total se
    // reparte en un polvo suave en vez de saturar.
    float grain = 1.0f + 2.6f * std::clamp(gl.grano, 0.0f, 1.0f);
    float soften = 1.0f / (grain * std::sqrt(grain));
    float base = 0.11f * light * soften * density * (1.0f + 0.6f * kick + 0.3f * bass) * amp;
    // Golpes destella la nube entera; Graves la aviva y engorda sus hilos;
    // Agudos la hace chispear.
    base *= 1.0f + 1.0f * kickP + 0.8f * bassP + 0.35f * sparkP;
    // Resplandor local de la nube: Golpes lo enciende y Graves lo hace latir.
    const float aura = std::clamp((0.32f * kickP + 0.2f * bassP) * f.glow, 0.0f, 0.6f);
    if (aura > 0.002f) {
      const Vec2 mid{f.width * 0.5f, f.height * 0.5f};
      const float auraR = maxR * (1.05f + 0.1f * kickP);
      Paint ap = Paint::radial(mid, auraR, {f.colors[2].opacity(aura), f.colors[1].opacity(aura * 0.4f), f.colors[1].opacity(0.0f)},
                               {0.0f, 0.55f, 1.0f});
      ap.blend = Blend::plus;
      c.circle(mid, auraR, ap);
    }
    for (int g = 0; g < 3; g++) {
      const Color& col = f.colors[size_t(1 + g)];
      Paint p;
      p.blend = Blend::plus;
      p.color = col.opacity(std::clamp(base * (g == 2 ? 1.3f : 1.0f), 0.0f, 1.0f));
      c.points(groups[size_t(g)], (0.9f + 0.3f * spark) * px * grain * (1.0f + 0.6f * bassP + 0.3f * kickP), p);
    }
    // El frente de la onda de choque, en el tono más claro de la paleta.
    if (!lit.empty()) {
      Paint lp;
      lp.blend = Blend::plus;
      lp.color = f.colors[3].opacity(std::clamp(0.55f * ring * light, 0.0f, 0.8f));
      c.points(lit, 1.5f * px * grain, lp);
    }
    // Destellos de los agudos.
    if (!glints.empty()) {
      Paint gp;
      gp.blend = Blend::plus;
      gp.color = f.colors[3].opacity(std::clamp(0.9f * sparkP, 0.0f, 0.95f));
      c.points(glints, 2.2f * px * std::sqrt(grain), gp);
    }
    if (flash > 0.01f) {
      Paint fl;
      fl.blend = Blend::plus;
      fl.color = f.colors[2].opacity(std::clamp(flash * 0.05f * amp, 0.0f, 1.0f));
      c.rect({0, 0, f.width, f.height}, fl);
    }
  }
};

class Visual final : public Scene {
  // Integración en pasos fijos de 1/60 s contados con el tiempo absoluto:
  // es idéntica a 30 y a 60 FPS y se dibuja interpolada.
  static constexpr double kHz = 60.0;
  static constexpr int kTrail = 14;
  struct P { float x, y, z; };
  std::vector<P> now, prev;
  std::vector<P> trail;  // anillo: partícula * kTrail
  int head = 0;
  int64_t steps = -1;
  float frac = 0, pendingKick = 0;
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  double yaw = 0;
  Random rng{67};

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

  void integrate(P& p, float rho, float h) const {
    const float sigma = 10.0f, beta = 8.0f / 3.0f;
    for (int k = 0; k < 3; k++) {
      float dx = sigma * (p.y - p.x);
      float dy = p.x * (rho - p.z) - p.y;
      float dz = p.x * p.y - beta * p.z;
      p.x += dx * h;
      p.y += dy * h;
      p.z += dz * h;
    }
  }

  void step() {
    float rho = 28.0f + 7.0f * bass;
    float h = 0.0035f * (1.0f + 1.2f * drive);
    float push = pendingKick;
    pendingKick = 0;
    for (size_t i = 0; i < now.size(); i++) {
      prev[i] = now[i];
      P& p = now[i];
      if (push > 0) {
        // Golpe: la partícula sale despedida y el atractor la vuelve a atrapar.
        p.x += (rng.unit() - 0.5f) * 6.0f * push;
        p.y += (rng.unit() - 0.5f) * 6.0f * push;
        p.z += (rng.unit() - 0.5f) * 4.0f * push;
      }
      integrate(p, rho, h);
      trail[i * kTrail + size_t(head)] = p;
    }
    head = (head + 1) % kTrail;
  }

 public:
  void reset(uint32_t seed) override {
    rng = Random(seed);
    now.clear();
    prev.clear();
    trail.clear();
    head = 0;
    steps = -1;
    frac = pendingKick = 0;
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    yaw = rng.unit() * 6.2831853;
  }

  void update(const Frame& f) override {
    float dt = float(f.delta);
    if (now.empty()) {
      int count = int(600.0f + 200.0f * std::clamp(f.detail, 0.25f, 2.0f));
      now.resize(size_t(count));
      for (auto& p : now) p = {1.0f + rng.unit() * 2.0f, 1.0f + rng.unit() * 2.0f, 20.0f + rng.unit() * 2.0f};
      // El caos reparte las partículas por la mariposa antes de empezar.
      for (auto& p : now)
        for (int k = 0; k < 400; k++) integrate(p, 28.0f, 0.004f);
      prev = now;
      trail.assign(now.size() * kTrail, P{0, 0, 0});
      for (size_t i = 0; i < now.size(); i++)
        for (int k = 0; k < kTrail; k++) trail[i * kTrail + size_t(k)] = now[i];
    }
    const Music& m = f.music;
    bass = follow(bass, m.bass, 22.0f, 4.5f, dt);
    body = follow(body, m.body, 12.0f, 3.0f, dt);
    spark = follow(spark, m.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, m.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, m.active ? std::pow(std::clamp(m.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : m.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : m.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : m.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((m.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, m.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    if (hit > kick + 0.2f) pendingKick = std::max(pendingKick, hit);
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    yaw += f.delta * f.speed * (0.12 + 0.25 * drive);

    int64_t target = int64_t(std::floor(f.time * kHz + 1e-6));
    if (steps < 0 || target < steps || target - steps > 15) steps = target - 1;
    while (steps < target) {
      step();
      steps++;
    }
    frac = std::clamp(float(f.time * kHz - double(steps)), 0.0f, 1.0f);
  }

  void render(const Frame& f, Canvas& c) const override {
    float amp = f.intensity;
    float w = f.width, h = f.height, s = std::min(w, h);
    std::vector<float> u;
    u.reserve(20);
    u.insert(u.end(), {bass * amp, kick * amp, energy, f.glow});
    u.insert(u.end(), {spark * amp, flash * amp, 0.0f, 0.0f});
    for (int i = 0; i < 4; i++) u.insert(u.end(), {f.colors[i].r, f.colors[i].g, f.colors[i].b});
    c.material("chaos_space", {0, 0, w, h}, u);
    if (now.empty()) return;

    float cy = float(std::cos(yaw)), sy = float(std::sin(yaw));
    const float tilt = 0.35f;
    float ct = std::cos(tilt), st = std::sin(tilt);
    float scale = s * 0.026f;
    float ox = w * 0.5f, oy = h * 0.5f;
    auto project = [&](const P& p) -> Vec2 {
      // Centrado: las alas giran alrededor del eje vertical de la mariposa.
      float x = p.x, y = p.y, z = p.z - 25.0f;
      float rx = x * cy + y * sy;
      float ry = -x * sy + y * cy;
      float vy = z * ct - ry * st;
      float vz = z * st + ry * ct;
      float persp = 80.0f / (80.0f - vz);
      return {ox + rx * scale * persp, oy - vy * scale * persp};
    };
    std::array<std::vector<Vec2>, 2> heads;
    std::array<Path, 2> tails;
    for (int g = 0; g < 2; g++) heads[size_t(g)].reserve(now.size());
    for (size_t i = 0; i < now.size(); i++) {
      P p{prev[i].x + (now[i].x - prev[i].x) * frac, prev[i].y + (now[i].y - prev[i].y) * frac,
          prev[i].z + (now[i].z - prev[i].z) * frac};
      int wing = p.x > 0 ? 0 : 1;
      Vec2 hp = project(p);
      heads[size_t(wing)].push_back(hp);
      Path& path = tails[size_t(wing)];
      for (int k = 0; k < kTrail; k++) {
        Vec2 q = project(trail[i * kTrail + size_t((head + k) % kTrail)]);
        if (k == 0) path.moveTo(q.x, q.y); else path.lineTo(q.x, q.y);
      }
      path.lineTo(hp.x, hp.y);
    }
    float px = s / 400.0f;
    float gain = std::clamp((0.85f + 0.5f * bass + 0.6f * kick) * amp, 0.0f, 1.6f);
    for (int g = 0; g < 2; g++) {
      const Color& col = f.colors[1 + g];
      Paint tailGlow;
      tailGlow.blend = Blend::plus;
      tailGlow.strokeWidth = 4.0f * px;
      tailGlow.strokeCap = 1;
      tailGlow.strokeJoin = 1;
      tailGlow.color = {col.r, col.g, col.b, std::clamp(0.05f * gain * f.glow, 0.0f, 1.0f)};
      c.path(tails[size_t(g)], tailGlow);
      Paint tail = tailGlow;
      tail.strokeWidth = 1.1f * px;
      tail.color = {col.r, col.g, col.b, std::clamp(0.4f * gain, 0.0f, 1.0f)};
      c.path(tails[size_t(g)], tail);
      Paint halo;
      halo.blend = Blend::plus;
      halo.color = {col.r, col.g, col.b, std::clamp(0.08f * gain * f.glow, 0.0f, 1.0f)};
      c.points(heads[size_t(g)], 4.5f * px, halo);
      Paint core;
      core.blend = Blend::plus;
      const Color& white = f.colors[3];
      core.color = {col.r + (white.r - col.r) * 0.5f, col.g + (white.g - col.g) * 0.5f, col.b + (white.b - col.b) * 0.5f,
                    std::clamp(0.9f * gain, 0.0f, 1.0f)};
      c.points(heads[size_t(g)], (1.4f + 0.5f * spark * amp) * px, core);
    }
  }
};

shaderSources.chaos_space:
#version 460 core
#include <flutter/runtime_effect.glsl>
uniform vec2 uSize;
uniform vec4 uA;   // graves, golpe, energía, glow
uniform vec4 uB;   // agudos, destello
uniform vec3 uC0;
uniform vec3 uC1;
uniform vec3 uC2;
uniform vec3 uC3;
out vec4 fragColor;

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

void main() {
  vec2 frag = FlutterFragCoord().xy;
  float scale = min(uSize.x, uSize.y);
  vec2 p = (frag - 0.5 * uSize) / scale;
  // Espacio azul profundo con resplandor detrás de la mariposa.
  vec3 col = uC0 + uC1 * exp(-dot(p, p) * 2.2) * (0.06 + 0.05 * uA.x + 0.12 * uA.y) * uA.w;
  col += uC2 * uB.y * 0.04;
  col *= 1.0 - 0.45 * smoothstep(0.5, 1.4, length(p * vec2(0.9, 0.65)));
  col += (hash12(frag) - 0.5) / 255.0;
  fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

