vec4 paintVisual(vec2 uv, CreatorFrame f) {
vec2 p = uv - 0.5;
p.x *= f.size.x / max(f.size.y, 1.0);
float t = f.time * f.speed * 0.32;
float seed = mod(f.seedLow + f.seedHigh, 10000.0) * 0.001;
vec3 c = f.color0.rgb * (0.7 + 0.3 * uv.y);
for (int i = 0; i < 4; i++) {
  float k = float(i);
  float center = 0.14 * sin(p.x * (2.0 + k * 0.32) + t + seed + k)
               + 0.08 * cos(p.x * 5.0 * f.detail - t * 0.6 + k)
               + (k - 1.5) * 0.105;
  float d = abs(p.y - center);
  float width = 0.014 + 0.013 * f.bass;
  float core = exp(-d * d / (width * width));
  float halo = exp(-d * 12.0) * 0.13 * f.glow;
  vec3 ink = mix(f.color1.rgb, f.color2.rgb, k / 3.0);
  ink = mix(ink, f.color3.rgb, 0.15 * (0.5 + 0.5 * sin(t + p.x * 2.0 + k)));
  c += ink * (core * 0.30 + halo) * f.intensity * (0.75 + 0.3 * f.energy + 0.15 * f.pulse);
}
float vignette = clamp(1.0 - dot(p, p) * 0.65, 0.25, 1.0);
return vec4(c * vignette, 1.0);
}

visuals.nativeSource:
class Visual final : public Scene {
  static constexpr int kMaxCells = 30000;
  static constexpr double kStep = 1.0 / 60.0;
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  // Relojes en doble precisión: la escena sin música es idéntica a 30 y 60 FPS.
  double sim = 0, fadeStart = -1;
  int64_t steps = 0;
  int w = 0, h = 0, cellMode = 0, seedsUsed = 1, cycle = 0, burst = 0;
  float grainAcc = 0;
  std::vector<uint32_t> grid;
  std::vector<int> stack;

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

  void drop(int cell, uint32_t grains) {
    grid[size_t(cell)] += grains;
    if (grid[size_t(cell)] >= 4) stack.push_back(cell);
    while (!stack.empty()) {
      int c = stack.back();
      stack.pop_back();
      uint32_t v = grid[size_t(c)];
      if (v < 4) continue;
      uint32_t q = v / 4;
      grid[size_t(c)] = v - 4 * q;
      int x = c % w, y = c / w;
      // Los granos que salen del borde se pierden.
      if (x > 0) { if ((grid[size_t(c - 1)] += q) >= 4) stack.push_back(c - 1); }
      if (x < w - 1) { if ((grid[size_t(c + 1)] += q) >= 4) stack.push_back(c + 1); }
      if (y > 0) { if ((grid[size_t(c - w)] += q) >= 4) stack.push_back(c - w); }
      if (y < h - 1) { if ((grid[size_t(c + w)] += q) >= 4) stack.push_back(c + w); }
    }
  }

  void seeds(std::array<int, 4>& out, int& n) const {
    int cx = w / 2, cy = h / 2, d = std::max(4, w / 6);
    n = seedsUsed;
    if (n == 1) {
      out[0] = cy * w + cx;
    } else if (n == 2) {
      out[0] = (cy - d) * w + cx;
      out[1] = (cy + d) * w + cx;
    } else {
      out[0] = (cy - d) * w + cx - d;
      out[1] = (cy - d) * w + cx + d;
      out[2] = (cy + d) * w + cx - d;
      out[3] = (cy + d) * w + cx + d;
    }
  }

  bool touchesEdge() const {
    for (int x = 0; x < w; x++) if (grid[size_t(x)] || grid[size_t((h - 1) * w + x)]) return true;
    for (int y = 0; y < h; y++) if (grid[size_t(y * w)] || grid[size_t(y * w + w - 1)]) return true;
    return false;
  }

 public:
  void reset(uint32_t seed) override {
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    sim = 0;
    fadeStart = -1;
    steps = 0;
    w = h = 0;
    cellMode = 0;
    seedsUsed = 1;
    cycle = int(seed % 3u);
    burst = 0;
    grainAcc = 0;
    grid.assign(kMaxCells, 0);
    stack.reserve(kMaxCells);
  }

  void update(const Frame& f) override {
    auto m = modifiers(f);
    float dt = float(f.delta);
    const Music& mu = f.music;
    bass = follow(bass, mu.bass, 22.0f, 4.5f, dt);
    body = follow(body, mu.body, 12.0f, 3.0f, dt);
    spark = follow(spark, mu.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, mu.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, mu.active ? std::pow(std::clamp(mu.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : mu.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : mu.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : mu.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((mu.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, mu.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    if (hit > kick + 0.2f) burst += int(250.0f + 500.0f * hit);
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));

    // Rejilla de unas 30 000 celdas como mucho, con lados impares (simetría).
    float area = f.width * f.height;
    float cell = std::max(std::sqrt(area / float(kMaxCells)), std::min(f.width, f.height) / 400.0f * (1.5f + float(m.grano)));
    int nw = (int(f.width / cell) | 1), nh = (int(f.height / cell) | 1);
    nw = std::max(nw, 11);
    nh = std::max(nh, 11);
    while (nw * nh > kMaxCells) {
      nw -= 2;
      nh -= 2;
    }
    int wantSeeds = m.semillas == 0 ? (cycle % 3 == 0 ? 1 : (cycle % 3 == 1 ? 4 : 2)) : (m.semillas == 1 ? 1 : (m.semillas == 2 ? 2 : 4));
    if (nw != w || nh != h || m.grano != cellMode || (m.semillas != 0 && wantSeeds != seedsUsed)) {
      w = nw;
      h = nh;
      cellMode = m.grano;
      seedsUsed = wantSeeds;
      std::fill(grid.begin(), grid.end(), 0);
      fadeStart = -1;
    }
    sim += f.delta * f.speed;
    int64_t target = int64_t(std::floor(sim / kStep + 1e-6));
    if (target - steps > 30) steps = target - 30;
    std::array<int, 4> s{};
    int ns = 1;
    while (steps < target) {
      steps++;
      double now = double(steps) * kStep;
      if (fadeStart >= 0.0) {
        if (now - fadeStart > 1.5) {
          // Montón nuevo: limpio y, en Auto, con otra disposición de semillas.
          std::fill(grid.begin(), grid.end(), 0);
          fadeStart = -1;
          cycle++;
          if (m.semillas == 0) seedsUsed = cycle % 3 == 0 ? 1 : (cycle % 3 == 1 ? 4 : 2);
        }
        continue;
      }
      seeds(s, ns);
      grainAcc += m.caudal * (14.0f + 40.0f * drive) * float(w * h) / 20000.0f;
      uint32_t grains = uint32_t(grainAcc);
      grainAcc -= float(grains);
      if (burst > 0) {
        grains += uint32_t(burst);
        burst = 0;
      }
      if (grains == 0) continue;
      for (int k = 0; k < ns; k++) drop(s[size_t(k)], std::max(1u, grains / uint32_t(ns)));
      if (steps % 30 == 0 && touchesEdge()) fadeStart = now;
    }
  }

  void render(const Frame& f, Canvas& c) const override {
    auto g = glide(f);
    float amp = f.intensity;
    const Color& bg = f.colors[0];
    Paint back;
    back.color = Color{bg.r, bg.g, bg.b, 1.0f};
    c.rect({0, 0, f.width, f.height}, back);
    if (w <= 0) return;
    float cw = f.width / float(w), ch = f.height / float(h);
    float fade = fadeStart >= 0.0 ? float(std::clamp(1.0 - (sim - fadeStart) / 1.5, 0.0, 1.0)) : 1.0f;
    // Textura: cada celda se pinta como tesela, como cuenta redonda o, en
    // encaje, sólo si es borde (alguna vecina tiene otros granos). Al cambiar,
    // las celdas se reparten entre las texturas según sus pesos.
    const std::array<float, 3> weight = {g.textura.weight(0), g.textura.weight(1), g.textura.weight(2)};
    auto level = [&](int x, int y) {
      return (x < 0 || y < 0 || x >= w || y >= h) ? 0u : std::min(grid[size_t(y * w + x)], 3u);
    };
    auto finish = [&](int x, int y) {
      if (weight[0] >= 1.0f) return 0;
      if (weight[1] >= 1.0f) return 1;
      if (weight[2] >= 1.0f) return 2;
      uint32_t k = uint32_t(x) * 73856093u ^ uint32_t(y) * 19349663u;
      k ^= k >> 13;
      k *= 0x5bd1e995u;
      k ^= k >> 15;
      float u = float(k & 0xffffu) / 65536.0f;
      return u < weight[0] ? 0 : (u < weight[0] + weight[1] ? 1 : 2);
    };
    // Tipo de cada celda: -1 nada, 0..2 tesela del nivel, 3..5 cuenta del nivel.
    auto kind = [&](int x, int y) {
      uint32_t v = level(x, y);
      if (v == 0) return -1;
      int t = finish(x, y);
      if (t == 1) return int(v) + 2;
      if (t == 2 && level(x - 1, y) == v && level(x + 1, y) == v && level(x, y - 1) == v && level(x, y + 1) == v) return -1;
      return int(v) - 1;
    };
    std::array<Path, 3> paths;
    std::array<std::vector<Vec2>, 3> beads;
    for (int y = 0; y < h; y++) {
      int x = 0;
      while (x < w) {
        int k = kind(x, y);
        if (k < 0) {
          x++;
          continue;
        }
        if (k >= 3) {
          beads[size_t(k - 3)].push_back({(float(x) + 0.5f) * cw, (float(y) + 0.5f) * ch});
          x++;
          continue;
        }
        int start = x;
        while (x < w && kind(x, y) == k) x++;
        paths[size_t(k)].rect({float(start) * cw, float(y) * ch, float(x - start) * cw + 0.5f, ch + 0.5f});
      }
    }
    const std::array<Color, 3> pal = {f.colors[1], f.colors[2], f.colors[3]};
    float lit = (0.85f + 0.3f * bass + 0.25f * kick) * amp * fade;
    for (int k = 0; k < 3; k++) {
      const Color& col = pal[size_t(k)];
      Paint p;
      p.color = Color{std::min(1.0f, col.r * lit + bg.r * (1.0f - fade)), std::min(1.0f, col.g * lit + bg.g * (1.0f - fade)),
                      std::min(1.0f, col.b * lit + bg.b * (1.0f - fade)), 1.0f};
      c.path(paths[size_t(k)], p);
      if (!beads[size_t(k)].empty()) c.points(beads[size_t(k)], 0.46f * std::min(cw, ch), p);
    }
    if (flash > 0.01f) {
      Paint fl;
      fl.blend = Blend::plus;
      fl.color = f.colors[2].opacity(std::clamp(flash * 0.05f * amp, 0.0f, 1.0f));
      c.rect({0, 0, f.width, f.height}, fl);
    }
  }
};

class Visual final : public Scene {
  static constexpr int kMaxCells = 6 * 16;
  static constexpr int kShapes = 8;
  struct Cell { int bg, shape, color, turns; int nShape, nColor, nBg; double start; int mode; };
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  // Relojes en doble precisión: la escena sin música es idéntica a 30 y 60 FPS.
  double clock = 0, idle = 0;
  int cols = 0, rows = 0;
  bool useBlack = true;
  Random rng{1};
  std::array<Cell, kMaxCells> cells{};

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

  int randomColor(int avoid) {
    int n = useBlack ? 5 : 4;
    int c = std::min(int(rng.unit() * float(n)), n - 1);
    if (c == avoid) c = (c + 1 + std::min(int(rng.unit() * float(n - 1)), n - 2)) % n;
    return c;
  }

  void randomize(Cell& c) {
    c.bg = std::min(int(rng.unit() * 5.0f), 4);
    if (!useBlack && c.bg == 4) c.bg = 0;
    if (rng.unit() < 0.45f) c.bg = 0;
    c.shape = std::min(int(rng.unit() * float(kShapes)), kShapes - 1);
    c.color = randomColor(c.bg);
    c.turns = std::min(int(rng.unit() * 4.0f), 3);
    c.mode = 0;
    c.start = -10;
  }

  // Una celda al azar que no esté a medio cambio, para que ninguna salte.
  int pickIdle(int count) {
    int first = std::min(int(rng.unit() * float(count)), count - 1);
    for (int k = 0; k < count; k++) {
      int i = (first + k) % count;
      if (cells[size_t(i)].mode == 0) return i;
    }
    return first;
  }

  // Cambio de una celda: girar, o encoger y volver con otra forma.
  void change(int i, double when) {
    Cell& c = cells[size_t(i)];
    finish(c);
    c.start = when;
    if (rng.unit() < 0.45f) {
      c.mode = 1;
    } else {
      c.mode = 2;
      c.nShape = std::min(int(rng.unit() * float(kShapes)), kShapes - 1);
      c.nBg = rng.unit() < 0.5f ? c.bg : std::min(int(rng.unit() * (useBlack ? 5.0f : 4.0f)), useBlack ? 4 : 3);
      c.nColor = randomColor(c.nBg);
    }
  }

  void finish(Cell& c) {
    if (c.mode == 1) c.turns = (c.turns + 1) % 4;
    if (c.mode == 2) {
      c.shape = c.nShape;
      c.color = c.nColor;
      c.bg = c.nBg;
    }
    c.mode = 0;
  }

  Color colorOf(const Frame& f, int k) const {
    if (k == 4) return Color{0.07f, 0.07f, 0.08f, 1.0f};
    return f.colors[size_t(k)];
  }

  static float easeBack(float t) {
    const float s = 1.9f;
    t -= 1.0f;
    return t * t * ((s + 1.0f) * t + s) + 1.0f;
  }

  void shapePath(Path& p, int shape, float h) const {
    auto arc = [&](float cx, float cy, float r, float a0, float a1, bool first) {
      const int n = 24;
      for (int k = 0; k <= n; k++) {
        float a = a0 + (a1 - a0) * float(k) / float(n);
        float x = cx + r * std::cos(a), y = cy + r * std::sin(a);
        if (first && k == 0) p.moveTo(x, y); else p.lineTo(x, y);
      }
    };
    switch (shape) {
      case 0: p.circle({0, 0}, h * 0.78f); break;
      case 1: arc(0, h, h, 3.14159265f, 6.2831853f, true); p.close(); break;
      case 2: p.moveTo(-h, h); arc(-h, h, h * 2.0f, -1.5707963f, 0.0f, false); p.close(); break;
      case 3: p.rect({-h * 0.55f, -h * 0.55f, h * 1.1f, h * 1.1f}); break;
      case 4: p.moveTo(-h, -h).lineTo(h, h).lineTo(-h, h).close(); break;
      case 5:
        for (int k = 0; k < 3; k++) p.rect({-h, -h + float(k) * h * 0.7f + h * 0.1f, h * 2.0f, h * 0.38f});
        break;
      case 6:
        p.fillRule = FillRule::evenOdd;
        p.circle({0, 0}, h * 0.8f);
        p.circle({0, 0}, h * 0.42f);
        break;
      default:
        for (int k = 0; k < 4; k++) p.circle({(k % 2 == 0 ? -0.45f : 0.45f) * h, (k < 2 ? -0.45f : 0.45f) * h}, h * 0.3f);
        break;
    }
  }

 public:
  void reset(uint32_t seed) override {
    rng = Random(seed);
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    clock = 0;
    idle = 0;
    cols = rows = 0;
  }

  void update(const Frame& f) override {
    auto m = modifiers(f);
    float dt = float(f.delta);
    const Music& mu = f.music;
    bass = follow(bass, mu.bass, 22.0f, 4.5f, dt);
    body = follow(body, mu.body, 12.0f, 3.0f, dt);
    spark = follow(spark, mu.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, mu.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, mu.active ? std::pow(std::clamp(mu.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : mu.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : mu.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : mu.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((mu.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, mu.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    bool beat = hit > kick + 0.2f;
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));

    int c = std::clamp(m.columnas, 2, 6);
    float size = f.width / float(c);
    int r = std::clamp(int(std::ceil(f.height / size)), 1, kMaxCells / c);
    if (c != cols || r != rows || m.negro != useBlack) {
      cols = c;
      rows = r;
      useBlack = m.negro;
      for (int i = 0; i < cols * rows; i++) randomize(cells[size_t(i)]);
    }
    clock += f.delta * f.speed;
    int count = cols * rows;
    // Agitación: cuántas celdas cambia cada golpe (con música) y cada cuánto
    // cambia una sola (sin música).
    if (beat) {
      int n = std::clamp(int(std::lround(float(1 + int(hit * 3.0f)) * m.ritmo)), 1, count);
      for (int k = 0; k < n; k++) change(pickIdle(count), clock);
    }
    // Sin música, un cambio a ritmo tranquilo, en su instante exacto.
    double period = 0.7 / double(m.ritmo);
    idle += f.delta * f.speed;
    while (idle >= period) {
      idle -= period;
      if (!mu.active) change(pickIdle(count), clock - idle);
    }
    for (int i = 0; i < count; i++) {
      Cell& cell = cells[size_t(i)];
      if (cell.mode != 0 && clock - cell.start >= 0.5) finish(cell);
    }
  }

  void render(const Frame& f, Canvas& c) const override {
    auto m = modifiers(f);
    float amp = f.intensity;
    Paint paper;
    paper.color = colorOf(f, 0);
    c.rect({0, 0, f.width, f.height}, paper);
    if (cols <= 0) return;
    float size = f.width / float(cols);
    float top = (f.height - float(rows) * size) * 0.5f;
    float h = size * 0.5f;
    for (int i = 0; i < cols * rows; i++) {
      const Cell& cell = cells[size_t(i)];
      float x = float(i % cols) * size, y = top + float(i / cols) * size;
      float t = cell.mode != 0 ? std::clamp(float((clock - cell.start) / 0.5), 0.0f, 1.0f) : 1.0f;
      int bg = cell.bg, shape = cell.shape, color = cell.color;
      float angle = float(cell.turns) * 1.5707963f;
      float s = 1.0f;
      if (cell.mode == 1) {
        angle += 1.5707963f * easeBack(t);
      } else if (cell.mode == 2) {
        if (t < 0.4f) {
          s = 1.0f - t / 0.4f;
        } else {
          bg = cell.nBg;
          shape = cell.nShape;
          color = cell.nColor;
          s = easeBack((t - 0.4f) / 0.6f);
        }
      }
      Paint bp;
      bp.color = colorOf(f, bg);
      c.rect({x, y, size + 0.5f, size + 0.5f}, bp);
      c.save();
      Path clip;
      clip.rect({x, y, size, size});
      c.clip(clip);
      c.translate(x + h, y + h);
      c.rotate(angle);
      float breathe = 1.0f + 0.05f * bass * amp;
      c.scale(s * breathe, s * breathe);
      Path p;
      shapePath(p, shape, h);
      Paint sp;
      sp.color = colorOf(f, color);
      c.path(p, sp);
      c.restore();
    }
    if (m.lineas) {
      Path grid;
      for (int k = 0; k <= cols; k++) grid.moveTo(float(k) * size, 0).lineTo(float(k) * size, f.height);
      for (int k = 0; k <= rows; k++) grid.moveTo(0, top + float(k) * size).lineTo(f.width, top + float(k) * size);
      Paint gp;
      gp.strokeWidth = std::max(1.5f, size * 0.025f);
      gp.color = Color{0.07f, 0.07f, 0.08f, 1.0f};
      c.path(grid, gp);
    }
    if (flash > 0.01f) {
      Paint fl;
      fl.color = Color{1.0f, 1.0f, 1.0f, std::clamp(flash * 0.06f * amp, 0.0f, 1.0f)};
      c.rect({0, 0, f.width, f.height}, fl);
    }
  }
};

class Visual final : public Scene {
  struct Disc { float x, y, vx, vy, size, depth, phase; int color; };
  struct Spark { float x, y, phase; };
  std::vector<Disc> discs;
  std::vector<Spark> sparks;
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  // Reloj en doble precisión: la escena sin música es idéntica a 30 y 60 FPS.
  double clock = 0;

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

  static float wrap(float v) { return v - std::floor(v); }

 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    discs.clear();
    sparks.clear();
    for (int i = 0; i < 64; i++) {
      Disc d;
      d.depth = rng.unit();
      d.size = 0.03f + 0.11f * d.depth * d.depth;
      d.x = rng.unit();
      d.y = rng.unit();
      float speed = 0.3f + d.depth;
      d.vx = (rng.unit() - 0.5f) * 0.02f * speed;
      d.vy = -(0.004f + 0.012f * rng.unit()) * speed;
      d.phase = rng.unit() * 6.2831853f;
      d.color = int(rng.unit() * 3.0f) % 3;
      discs.push_back(d);
    }
    // Lejos primero: los discos cercanos quedan delante.
    std::stable_sort(discs.begin(), discs.end(), [](const Disc& a, const Disc& b) { return a.depth < b.depth; });
    for (int i = 0; i < 50; i++) sparks.push_back({rng.unit(), rng.unit(), rng.unit() * 6.2831853f});
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    clock = rng.unit() * 100.0;
  }

  void update(const Frame& f) override {
    float dt = float(f.delta);
    const Music& m = f.music;
    bass = follow(bass, m.bass, 18.0f, 3.5f, dt);
    body = follow(body, m.body, 12.0f, 3.0f, dt);
    spark = follow(spark, m.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, m.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, m.active ? std::pow(std::clamp(m.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : m.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : m.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : m.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((m.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, m.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    kick = std::max(kick * std::exp(-dt * 4.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    clock += f.delta * f.speed * (1.0 + 1.2 * drive);
  }

  void render(const Frame& f, Canvas& c) const override {
    float amp = f.intensity;
    float w = f.width, h = f.height, s = std::min(w, h);
    float t = float(std::fmod(clock, 100000.0));
    std::vector<float> u;
    u.reserve(20);
    u.insert(u.end(), {t, bass * amp, kick * amp, energy});
    u.insert(u.end(), {f.glow, spark * amp, flash * amp, 0.0f});
    for (int i = 0; i < 4; i++) u.insert(u.end(), {f.colors[i].r, f.colors[i].g, f.colors[i].b});
    c.material("bokeh_night", {0, 0, w, h}, u);

    for (const Disc& d : discs) {
      float x = (wrap(d.x + d.vx * t) * 1.3f - 0.15f) * w;
      float y = (wrap(d.y + d.vy * t) * 1.3f - 0.15f) * h;
      float near = d.depth;
      float pulse = 1.0f + (0.28f * bass + 0.22f * kick) * near * amp;
      float r = d.size * s * pulse;
      float twinkle = 0.75f + 0.25f * std::sin(t * 0.8f + d.phase);
      float a = (0.16f + 0.24f * near) * twinkle * (0.75f + 0.7f * bass + 0.9f * kick * near) * amp * f.glow;
      a = std::clamp(a, 0.0f, 0.8f);
      const Color& col = f.colors[1 + d.color];
      // Disco de lente: interior parejo, borde algo más brillante y canto suave.
      Paint disc = Paint::radial({x, y}, r,
                                 {Color{col.r, col.g, col.b, a * 0.65f}, Color{col.r, col.g, col.b, a * 0.72f},
                                  Color{std::min(1.0f, col.r * 1.1f + 0.08f), std::min(1.0f, col.g * 1.1f + 0.08f),
                                        std::min(1.0f, col.b * 1.1f + 0.08f), a},
                                  Color{col.r, col.g, col.b, 0.0f}},
                                 {0.0f, 0.72f, 0.9f, 1.0f});
      disc.blend = Blend::plus;
      c.circle({x, y}, r, disc);
    }

    // Chispas diminutas que titilan con los agudos.
    std::vector<Vec2> pts;
    for (const Spark& sp : sparks) {
      float tw = std::sin(t * 2.3f + sp.phase * 3.0f);
      if (tw < 0.4f - 0.8f * spark) continue;
      pts.push_back({wrap(sp.x + 0.004f * t) * w, wrap(sp.y - 0.006f * t) * h});
    }
    if (!pts.empty()) {
      Paint p;
      p.blend = Blend::plus;
      p.color = {1.0f, 0.95f, 0.9f, std::clamp((0.35f + 0.6f * spark) * amp, 0.0f, 1.0f)};
      c.points(pts, (0.9f + 0.6f * spark) * s / 400.0f, p);
    }
  }
};

shaderSources.bokeh_night:
#version 460 core
#include <flutter/runtime_effect.glsl>
uniform vec2 uSize;
uniform vec4 uA;   // reloj, graves, golpe, energía
uniform vec4 uB;   // glow, agudos, destello
uniform vec3 uC0;
uniform vec3 uC1;
uniform vec3 uC2;
uniform vec3 uC3;
out vec4 fragColor;

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

void main() {
  vec2 frag = FlutterFragCoord().xy;
  float scale = min(uSize.x, uSize.y);
  vec2 p = (frag - 0.5 * uSize) / scale;
  float t = uA.x;
  // Noche suave con neblinas de color muy desenfocadas.
  vec3 col = uC0;
  vec2 a = vec2(0.35 * sin(t * 0.05), -0.4 + 0.2 * cos(t * 0.04));
  vec2 b = vec2(-0.3 * cos(t * 0.045), 0.45 + 0.15 * sin(t * 0.035));
  col += uC1 * exp(-dot(p - a, p - a) * 2.2) * (0.05 + 0.03 * uA.y);
  col += uC3 * exp(-dot(p - b, p - b) * 2.0) * (0.05 + 0.03 * uA.y);
  col += uC2 * uB.z * 0.03;
  col *= 1.0 - 0.4 * smoothstep(0.5, 1.3, length(p * vec2(0.9, 0.65)));
  col += (hash12(frag) - 0.5) / 255.0;
  fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

bokeh_night.metalSource:
