#version 460 core
#include <flutter/runtime_effect.glsl>
uniform vec2 uSize;
uniform vec4 uA;   // reloj, graves, golpe, energía
uniform vec4 uB;   // glow, agudos, destello
uniform vec3 uC0;
uniform vec3 uC1;
uniform vec3 uC2;
uniform vec3 uC3;
out vec4 fragColor;

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

void main() {
  vec2 frag = FlutterFragCoord().xy;
  float scale = min(uSize.x, uSize.y);
  vec2 p = (frag - 0.5 * uSize) / scale;
  float t = uA.x;
  // Noche suave con neblinas de color muy desenfocadas.
  vec3 col = uC0;
  vec2 a = vec2(0.35 * sin(t * 0.05), -0.4 + 0.2 * cos(t * 0.04));
  vec2 b = vec2(-0.3 * cos(t * 0.045), 0.45 + 0.15 * sin(t * 0.035));
  col += uC1 * exp(-dot(p - a, p - a) * 2.2) * (0.14 + 0.18 * uA.y + 0.25 * uA.z);
  col += uC3 * exp(-dot(p - b, p - b) * 2.0) * (0.10 + 0.15 * uA.y + 0.2 * uA.z);
  col += uC2 * uB.z * 0.08;
  col *= 1.0 - 0.4 * smoothstep(0.5, 1.3, length(p * vec2(0.9, 0.65)));
  col += (hash12(frag) - 0.5) / 255.0;
  fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

