#version 460 core
#include <flutter/runtime_effect.glsl>
uniform vec2 uSize;
uniform vec4 uA;   // tiempo del campo, graves, golpe, energía
uniform vec2 uB;   // tono, glow
uniform vec3 uC0;
uniform vec3 uC1;
uniform vec3 uC2;
uniform vec3 uC3;
out vec4 fragColor;

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash12(i), hash12(i + vec2(1.0, 0.0)), u.x),
             mix(hash12(i + vec2(0.0, 1.0)), hash12(i + vec2(1.0, 1.0)), u.x), u.y);
}

float fbm(vec2 p) {
  float s = 0.0;
  float a = 0.5;
  for (int i = 0; i < 3; i++) {
    s += a * noise(p);
    p = mat2(1.6, 1.2, -1.2, 1.6) * p;
    a *= 0.5;
  }
  return s / 0.875;
}

void main() {
  vec2 frag = FlutterFragCoord().xy;
  float scale = min(uSize.x, uSize.y);
  vec2 p = (frag - 0.5 * uSize) / scale;
  float t = uA.x;
  // Humo de color que fluye en la misma dirección general que las partículas.
  float a = sin(p.x * 3.1 + t * 0.3) * 1.6 + cos(p.y * 2.7 - t * 0.25) * 1.6;
  vec2 flow = vec2(cos(a), sin(a));
  float smoke = fbm(p * 2.0 + flow * 0.35 + vec2(t * 0.05, -t * 0.04));
  float mixer = fbm(p * 1.2 - vec2(t * 0.03, 0.0) + 3.0);
  vec3 tint = mix(mix(uC1, uC2, smoothstep(0.3, 0.7, mixer)), uC3, smoothstep(0.65, 0.9, mixer) * 0.5);
  vec3 col = uC0 + tint * smoothstep(0.45, 0.9, smoke) * (0.05 + 0.08 * uA.w + 0.12 * uA.z + 0.06 * uA.y) * uB.y;
  col *= 1.0 - 0.4 * smoothstep(0.5, 1.3, length(p * vec2(0.9, 0.65)));
  // Fondo transparente: el color va premultiplicado y la opacidad sale del
  // brillo, así la luz se compone sobre lo que haya debajo.
  col = clamp(col, 0.0, 1.0);
  // La luz muy tenue se vuelve transparente del todo: sin velo sobre la app.
  float veilPeak = max(col.r, max(col.g, col.b));
  float clearCut = smoothstep(0.04, 0.12, veilPeak);
  col *= clearCut;
  float alpha = clamp(veilPeak * 1.25, 0.0, 1.0) * clearCut;
  fragColor = vec4(col, alpha);
}

visuals.nativeSource:
class Visual final : public Scene {
  float plasmaTime = 0.0f;
  float smoothBass = 0.0f;
  float smoothEnergy = 0.0f;
 public:
  void reset(uint32_t seed) override {
    (void)seed;
    plasmaTime = 0.0f;
    smoothBass = 0.0f;
    smoothEnergy = 0.0f;
  }
  void update(const Frame& f) override {
    float dt = float(f.delta);
    float targetEnergy = f.music.active ? f.music.energy : 0.0f;
    float targetBass = f.music.active ? f.music.bass : 0.0f;
    smoothEnergy += (targetEnergy - smoothEnergy) * float(1.0 - std::exp(-dt * 6.0));
    smoothBass += (targetBass - smoothBass) * float(1.0 - std::exp(-dt * 8.0));

    // En silencio reposa en un flujo suave y relajante (~0.09f).
    // Con música acelera vigorosamente con los ritmos y bombos.
    float audioDrive = 0.09f + smoothEnergy * 0.76f + smoothBass * 0.35f;
    plasmaTime += dt * f.speed * audioDrive;
  }
  void render(const Frame& f, Canvas& c) const override {
    float w = f.width, h = f.height;
    float uEnergy = std::clamp(smoothEnergy * f.intensity, 0.0f, 1.0f);
    c.material("plasma", {0, 0, w, h}, {plasmaTime, std::clamp(smoothBass, 0.0f, 1.0f), uEnergy});
    Paint shade = Paint::radial({w * 0.5f, h * 0.5f}, h * 0.75f,
      {{0, 0, 0, 0}, {0, 0, 0, 0.6f}}, {0, 1.0f});
    c.rect({0, 0, w, h}, shade);
  }
};

