class Visual final : public Scene {
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  float phase = 0, wave = 0, drift = 0;
  std::array<float, 4> splash{};  // x, z, radio, amplitud
  Random rng{7};

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

 public:
  void reset(uint32_t seed) override {
    rng = Random(seed);
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    phase = rng.unit() * 40.0f;
    wave = 0;
    drift = 0;
    splash = {0.0f, 2.0f, 4.0f, 0.0f};
  }

  void update(const Frame& f) override {
    float dt = float(f.delta);
    const Music& m = f.music;
    bass = follow(bass, m.bass, 20.0f, 4.0f, dt);
    body = follow(body, m.body, 12.0f, 3.0f, dt);
    spark = follow(spark, m.spark, 30.0f, 6.0f, dt);
    energy = follow(energy, m.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, m.active ? std::pow(std::clamp(m.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : m.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : m.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : m.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((m.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, m.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    if (hit > kick + 0.2f) {
      splash = {(rng.unit() - 0.5f) * 1.6f, 1.2f + rng.unit() * 1.6f, 0.0f, hit};
    }
    kick = std::max(kick * std::exp(-dt * 4.5f), hit);
    flash = std::max(flash * std::exp(-dt * 6.0f), std::min(fl, 1.0f));
    splash[2] += dt * 1.6f;
    splash[3] *= std::exp(-dt * 1.6f);

    phase += dt * f.speed * (0.35f + 1.3f * drive + 1.0f * kick);
    wave = follow(wave, 0.35f + 0.9f * bass + 0.6f * kick, 10.0f, 2.0f, dt);
    drift += dt * f.speed * (0.04f + 0.12f * drive);
  }

  void render(const Frame& f, Canvas& c) const override {
    float amp = f.intensity;
    std::vector<float> u;
    u.reserve(32);
    u.insert(u.end(), {phase, wave * amp, kick * amp, energy});
    u.insert(u.end(), {splash[0], splash[1], splash[2], splash[3] * amp});
    u.insert(u.end(), {spark * amp, body, flash, f.glow});
    u.insert(u.end(), {drift, f.detail, 0.0f, 0.0f});
    for (int i = 0; i < 4; i++) u.insert(u.end(), {f.colors[i].r, f.colors[i].g, f.colors[i].b});
    c.material("caustics", {0, 0, f.width, f.height}, u);
  }
};

shaderSources.caustics:
#version 460 core
#include <flutter/runtime_effect.glsl>
uniform vec2 uSize;
uniform vec4 uA;   // tiempo, oleaje, golpe, energía
uniform vec4 uS;   // salpicadura: x, z, radio, amplitud
uniform vec4 uM;   // agudos, medios, destello, glow
uniform vec4 uX;   // deriva, detalle
uniform vec3 uC0;
uniform vec3 uC1;
uniform vec3 uC2;
uniform vec3 uC3;
out vec4 fragColor;

// Campana gaussiana segura: pow() con base negativa no está definido en GLSL.
float gauss(float x) {
  return exp(-x * x);
}

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash12(i), hash12(i + vec2(1.0, 0.0)), u.x),
             mix(hash12(i + vec2(0.0, 1.0)), hash12(i + vec2(1.0, 1.0)), u.x), u.y);
}

// Cáustica de agua periódica (iteración de Hoskins).
float caustic(vec2 uv, float time) {
  vec2 p = mod(uv * 6.2831853, 6.2831853) - 250.0;
  vec2 i = p;
  float c = 1.0;
  float inten = 0.005;
  for (int n = 0; n < 5; n++) {
    float t = time * (1.0 - (3.5 / float(n + 1)));
    i = p + vec2(cos(t - i.x) + sin(t + i.y), sin(t - i.y) + cos(t + i.x));
    c += 1.0 / length(vec2(p.x / (sin(i.x + t) / inten), p.y / (cos(i.y + t) / inten)));
  }
  c /= 5.0;
  c = 1.17 - pow(c, 1.4);
  return pow(abs(c), 8.0);
}

void main() {
  vec2 frag = FlutterFragCoord().xy;
  float scale = min(uSize.x, uSize.y);
  vec2 uv = (frag - 0.5 * uSize) / scale;
  uv.y = -uv.y;
  float t = uA.x;

  // Refracción de la superficie: toda la imagen ondula un poco con los graves.
  uv += vec2(sin(uv.y * 9.0 + t * 1.3), cos(uv.x * 7.0 - t * 1.1)) * 0.004 * (0.5 + uA.y);

  vec3 ro = vec3(0.0, 1.25, 0.0);
  float pitch = -0.62;
  vec3 fw = vec3(0.0, sin(pitch), cos(pitch));
  vec3 rt = vec3(1.0, 0.0, 0.0);
  vec3 up = cross(fw, rt);
  vec3 rd = normalize(fw * 1.5 + rt * uv.x + up * uv.y);

  vec3 water = mix(uC0, uC1, smoothstep(-0.6, 0.6, uv.y) * 0.8);
  vec3 col = water;
  float ct = t * 0.55 + 20.0;

  if (rd.y < -0.02) {
    float dist = -ro.y / rd.y;
    vec2 xz = (ro + rd * dist).xz + vec2(uX.x, -uX.x * 0.6);
    // Salpicadura: un anillo que deforma la luz alrededor del golpe.
    vec2 toS = xz - uS.xy;
    float ds = length(toS);
    float ring = gauss((ds - uS.z) * 5.0) * uS.w;
    xz += toS / max(ds, 0.001) * sin((ds - uS.z) * 18.0) * ring * 0.06;

    vec2 cuv = xz * 0.75;
    float spread = 0.0025 + 0.003 * uM.x;
    vec3 caus = vec3(caustic(cuv, ct), caustic(cuv + spread, ct), caustic(cuv + 2.0 * spread, ct));
    float strength = 0.35 + 1.1 * uA.y + 1.6 * uA.z;
    // Arena con ondas suaves, teñida por el agua.
    float rip = sin(dot(xz, vec2(3.1, 1.4)) * 6.0 + noise(xz * 3.0) * 4.0);
    vec3 sand = mix(uC3, uC1, 0.55) * (0.07 + 0.02 * rip + 0.03 * noise(xz * 18.0));
    vec3 light = mix(uC2, uC3, 0.55);
    vec3 floorCol = sand * (0.7 + 0.5 * uM.y) + light * caus * strength * 0.45 + light * ring * 0.25;
    float fog = exp(-dist * (0.30 - 0.04 * uX.y));
    col = mix(water, floorCol, fog);
  }

  // Haces de luz desde la superficie.
  vec2 lp = uv - vec2(0.15, 1.1);
  float ang = atan(lp.x, -lp.y);
  float shafts = pow(noise(vec2(ang * 34.0, t * 0.25)) * noise(vec2(ang * 11.0 + 3.0, t * 0.12)), 1.8);
  float fall = smoothstep(-0.5, 0.9, uv.y);
  col += mix(uC2, uC3, 0.7) * shafts * fall * (0.06 + 0.22 * uA.y + 0.35 * uA.z + 0.5 * uM.z) * uM.w;

  // Plancton bioluminiscente en dos capas de profundidad.
  for (int layer = 0; layer < 2; layer++) {
    float fl = float(layer);
    float cells = 26.0 - fl * 10.0;
    vec2 g = (uv + vec2(0.0, t * (0.012 + fl * 0.01))) * cells;
    vec2 id = floor(g);
    vec2 fr = fract(g) - 0.5;
    float h = hash12(id + fl * 17.0);
    vec2 o = vec2(hash12(id + 4.1), hash12(id + 9.3)) - 0.5;
    o += 0.15 * vec2(sin(t * 0.7 + h * 30.0), cos(t * 0.5 + h * 20.0));
    float d = length(fr - o * 0.7);
    float glow = smoothstep(0.07 + fl * 0.04, 0.0, d) * step(0.9, h);
    float blink = 0.25 + 0.75 * smoothstep(0.4, 1.0, sin(t * 2.0 + h * 60.0) * 0.5 + 0.5);
    col += uC2 * glow * blink * (0.12 + 1.8 * uM.x + 0.6 * uA.z) * (0.6 + 0.4 * fl);
  }

  col += uC3 * uM.z * 0.12;
  col *= 1.0 - 0.4 * smoothstep(0.45, 1.25, length(uv * vec2(0.85, 0.7)));
  col = clamp((col * (2.51 * col + 0.03)) / (col * (2.43 * col + 0.59) + 0.14), 0.0, 1.0);
  col = pow(col, vec3(0.4545));
  col += (hash12(frag) - 0.5) / 255.0;
  fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

visuals.nativeSource:
class Visual final : public Scene {
  float bass = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, split = 0, drive = 0;
  // Reloj en doble precisión: sin música es idéntico a 30 y 60 FPS.
  double clock = 0;

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    bass = spark = energy = slowBass = kick = flash = split = drive = 0;
    clock = double(rng.unit()) * 50.0;
  }

  void update(const Frame& f) override {
    const float dt = float(f.delta);
    const Music& mu = f.music;
    bass = follow(bass, mu.bass, 22.0f, 4.5f, dt);
    spark = follow(spark, mu.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, mu.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, mu.active ? std::pow(std::clamp(mu.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);
    float hit = 0, fl = 0;
    for (const auto& e : mu.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : mu.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : mu.events[3]) fl = std::max(fl, e.strength);
    const float onset = std::clamp((mu.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, mu.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    // Cada golpe parte las células; luego se van juntando otra vez.
    if (hit > kick + 0.2f) split = std::max(split, hit);
    split *= std::exp(-dt * 2.5f);
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    clock += f.delta * f.speed * (1.0 + 0.5 * double(drive));
  }

  void render(const Frame& f, Canvas& c) const override {
    auto g = glide(f);
    const float amp = f.intensity;
    std::vector<float> u;
    u.reserve(32);
    u.insert(u.end(), {float(std::fmod(clock, 1000.0)), std::min(bass * amp, 1.5f) * g.pulso.weight(1),
                       std::min(split * amp, 1.0f) * g.pulso.weight(0), std::min(spark * amp, 1.0f) * g.pulso.weight(2)});
    // Detalle: cuántas células caben a lo ancho.
    u.insert(u.end(), {3.2f + 2.2f * f.detail, std::clamp(g.vida, 0.0f, 1.0f), std::clamp(g.microscopio, 0.0f, 1.0f), f.glow});
    u.insert(u.end(), {g.celulas.weight(0), g.celulas.weight(1), g.celulas.weight(2), std::min(flash * amp, 1.0f)});
    for (int i = 0; i < 4; i++) u.insert(u.end(), {f.colors[size_t(i)].r, f.colors[size_t(i)].g, f.colors[size_t(i)].b});
    c.material("voronoi_cells", {0, 0, f.width, f.height}, u);
  }
};

shaderSources.voronoi_cells:
#version 460 core
#include <flutter/runtime_effect.glsl>
uniform vec2 uSize;
uniform vec4 uA;   // tiempo, graves, división por golpe, chispas
uniform vec4 uB;   // células a lo ancho, actividad, microscopio, glow
uniform vec4 uW;   // pesos: tejido, panal, burbujas; destello
uniform vec3 uC0;
uniform vec3 uC1;
uniform vec3 uC2;
uniform vec3 uC3;
out vec4 fragColor;

float sq(float x) {
  return x * x;
}

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

vec2 hash22(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973));
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.xx + p3.yz) * p3.zy);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash12(i), hash12(i + vec2(1.0, 0.0)), u.x),
             mix(hash12(i + vec2(0.0, 1.0)), hash12(i + vec2(1.0, 1.0)), u.x), u.y);
}

void main() {
  vec2 frag = FlutterFragCoord().xy;
  float scale = min(uSize.x, uSize.y);
  vec2 q = (frag - 0.5 * uSize) / scale;
  vec2 p = q * uB.x;
  float t = uA.x;
  float vida = uB.y;
  float jitter = uW.x * 0.8 + uW.y * 0.25 + uW.z * 0.7;
  vec2 g = floor(p);
  float F1 = 9.0;
  float F2 = 9.0;
  vec2 seed = vec2(0.0);
  // De qué célula vienen las dos semillas más cercanas y cuánto se partió.
  vec2 id1 = vec2(-99.0);
  vec2 id2 = vec2(-98.0);
  float split1 = 0.0;
  for (int j = -1; j <= 1; j++) {
    for (int i = -1; i <= 1; i++) {
      vec2 cell = g + vec2(float(i), float(j));
      vec2 h = hash22(cell);
      // Segundo azar derivado del primero: sin otro hash.
      vec2 h2 = fract(h * vec2(7.13, 5.71) + vec2(0.31, 0.77));
      vec2 move = 0.12 * (0.3 + vida) * sin(vec2(t * (0.5 + h.x) + h.y * 6.28, t * (0.4 + h.y) + h.x * 6.28 + 1.5707963));
      vec2 c = cell + 0.5 + (h - 0.5) * jitter + move * (1.0 - 0.7 * uW.y);
      // División: unas células se parten y se vuelven a juntar; los golpes parten muchas.
      float cyc = 0.5 + 0.5 * sin(t * 0.35 * (0.6 + h2.x) * (0.5 + vida) + h2.y * 20.0);
      float sp = clamp(smoothstep(0.55, 0.95, cyc) * (0.3 + 0.7 * vida) + uA.z * step(0.4, h2.x), 0.0, 1.0);
      // Dirección de la división sin trigonometría.
      vec2 dir = normalize(h2 - 0.5 + vec2(0.001, 0.0)) * 0.2 * sp;
      vec2 a = c + dir;
      float da = length(p - a);
      if (da < F1) { F2 = F1; id2 = id1; F1 = da; id1 = cell; split1 = sp; seed = a; } else if (da < F2) { F2 = da; id2 = cell; }
      if (sp > 0.02) {
        vec2 b = c - dir;
        float db = length(p - b);
        if (db < F1) { F2 = F1; id2 = id1; F1 = db; id1 = cell; split1 = sp; seed = b; } else if (db < F2) { F2 = db; id2 = cell; }
      }
    }
  }
  float edge = F2 - F1;
  // Entre dos mitades de una célula que aún se está partiendo, la membrana
  // nace poco a poco en vez de llenar la célula.
  float sibling = (id1.x == id2.x && id1.y == id2.y) ? 1.0 - smoothstep(0.2, 0.7, split1) : 0.0;
  edge = mix(edge, 1.0, sibling);
  float aa = uB.x * 1.5 / scale;
  // Membranas: más gruesas con los graves y más nítidas en el panal.
  float mw = (0.06 + 0.05 * uA.y) * mix(1.0, 0.6, uW.y);
  float memTissue = 1.0 - smoothstep(0.0, mw, edge);
  // Burbujas: células redondas con huecos entre ellas.
  float R0 = 0.42 + 0.06 * uA.y;
  float bubble = smoothstep(R0 + aa, R0 - aa, F1) * smoothstep(0.02, 0.06, edge);
  float mask = mix(1.0, bubble, uW.z);
  float memBubble = max(memTissue * bubble, exp(-sq((F1 - R0) / 0.03)) * smoothstep(0.0, 0.04, edge));
  float membrane = mix(memTissue, memBubble, uW.z);
  // Citoplasma con gránulos, núcleo y nucléolo.
  float shade = clamp(1.0 - F1 / 0.55, 0.0, 1.0);
  vec3 cyto = mix(uC1, uC2, shade) * (0.85 + 0.3 * noise(p * 8.0 + seed * 3.0));
  float nucleus = smoothstep(0.13 + aa, 0.13 - aa, F1);
  float nucleolus = smoothstep(0.05 + aa, 0.05 - aa, F1);
  cyto = mix(cyto, mix(uC2, uC3, 0.6), nucleus);
  cyto = mix(cyto, uC1 * 0.5, nucleolus);
  vec3 col = mix(uC0, cyto, mask);
  col += uC2 * exp(-edge / 0.08) * 0.22 * uB.w * mask;
  col = mix(col, uC3, membrane * 0.9);
  // Chispas: impulsos eléctricos que corren por las membranas.
  float travel = fract(dot(p, vec2(0.7, 0.7)) * 0.5 - t * 1.5);
  col += uC3 * membrane * smoothstep(0.85, 1.0, travel) * uA.w * 1.2;
  col *= 1.0 + 0.15 * uW.w;
  // Microscopio: el campo circular del ocular, con grano.
  float r = length(q);
  float field = smoothstep(0.49, 0.46, r);
  vec3 scope = col * field + uC2 * 0.08 * exp(-abs(r - 0.475) * 60.0);
  scope += (hash12(frag + t) - 0.5) * 0.06;
  col = mix(col, scope, uB.z);
  col *= 1.0 - 0.3 * smoothstep(0.6, 1.4, length(q * vec2(0.9, 0.65)));
  float peak = max(col.r, max(col.g, col.b));
  if (peak > 0.9) col *= (0.9 + 0.1 * (peak - 0.9) / (peak - 0.8)) / peak;
  col += (hash12(frag) - 0.5) / 255.0;
  fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

visuals.nativeSource:
class Visual final : public Scene {
  // La arena avanza en pasos fijos de 1/60 s contados con el tiempo absoluto:
  // es idéntica a 30 y a 60 FPS y se dibuja interpolada.
  static constexpr double kHz = 60.0;
  static constexpr float kStep = float(1.0 / kHz);
  static constexpr int kLut = 1024;
  struct Grain { float x, y, px, py; };
  struct Mode { float n, m, s; };
  std::vector<Grain> grains;
  std::array<float, kLut + 1> table{};
  Mode modeA{3, 5, -1}, modeB{3, 5, -1};
  float morph = 1;
  int modeIndex = 0, beats = 0, stepsSinceMode = 0;
  int64_t steps = -1;
  float frac = 0, pendingJolt = 0, pendingMode = 0;
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0, t = 0;
  Random rng{31};

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

  // cos(pi * x) desde una tabla: miles de granos por paso sin coste de trigonometría.
  float cospi(float x) const {
    float u = x * 0.5f;
    u -= std::floor(u);
    float i = u * kLut;
    int k = std::min(int(i), kLut - 1);
    float a = table[k];
    return a + (table[k + 1] - a) * (i - float(k));
  }
  float sinpi(float x) const { return cospi(x - 0.5f); }

  // Figura de Chladni de una placa rectangular y su gradiente.
  static float plate(const Mode& md, float x, float y, float& gx, float& gy, const Visual& v) {
    float cnx = v.cospi(md.n * x), cmy = v.cospi(md.m * y), cmx = v.cospi(md.m * x), cny = v.cospi(md.n * y);
    float snx = v.sinpi(md.n * x), smy = v.sinpi(md.m * y), smx = v.sinpi(md.m * x), sny = v.sinpi(md.n * y);
    const float p = 3.14159265f;
    gx = -p * (md.n * snx * cmy + md.s * md.m * smx * cny);
    gy = -p * (md.m * cnx * smy + md.s * md.n * cmx * sny);
    return cnx * cmy + md.s * cmx * cny;
  }

  void advanceMode() {
    // Figuras elegidas por su simetría: pares (n, m) y signo de la mezcla.
    static const Mode modes[10] = {{3, 5, -1}, {1, 5, 1}, {3, 7, -1}, {2, 6, 1}, {5, 7, -1},
                                   {1, 7, -1}, {4, 6, 1}, {3, 9, 1}, {2, 4, -1}, {5, 9, -1}};
    modeIndex = (modeIndex + 1) % 10;
    modeA = modeB;
    modeB = modes[modeIndex];
    morph = 0;
    stepsSinceMode = 0;
  }

  void step() {
    float jolt = pendingJolt;
    pendingJolt = 0;
    if (pendingMode > 0 || stepsSinceMode > int(kHz * 9.0)) {
      advanceMode();
      jolt = std::max(jolt, 0.8f);
      pendingMode = 0;
    }
    stepsSinceMode++;
    morph = std::min(1.0f, morph + kStep * 1.4f);
    t += kStep;
    float w = morph * morph * (3.0f - 2.0f * morph);
    float agitation = 0.0010f + 0.0012f * bass + 0.0006f * drive;
    float pull = 0.05f;  // fracción de la distancia a la línea por paso
    for (auto& g : grains) {
      g.px = g.x;
      g.py = g.y;
      float bx, by;
      float fv = plate(modeB, g.x, g.y, bx, by, *this);
      float gx = bx, gy = by;
      // La figura anterior sólo se calcula durante la transición.
      if (w < 1.0f) {
        float ax, ay;
        float fa = plate(modeA, g.x, g.y, ax, ay, *this);
        fv = fa + (fv - fa) * w;
        gx = ax + (bx - ax) * w;
        gy = ay + (by - ay) * w;
      }
      float gl = std::sqrt(gx * gx + gy * gy) + 1e-3f;
      // La arena baja por la pendiente de |f| hacia las líneas quietas y salta
      // más donde la placa vibra con fuerza.
      float stepLen = std::min(std::fabs(fv) / gl, 0.06f);
      float dir = fv > 0 ? -1.0f : 1.0f;
      g.x += dir * gx / gl * stepLen * pull;
      g.y += dir * gy / gl * stepLen * pull;
      float shake = agitation * (0.6f + 2.5f * std::fabs(fv)) + jolt * 0.06f * (0.3f + std::fabs(fv));
      g.x += (rng.unit() - 0.5f) * shake;
      g.y += (rng.unit() - 0.5f) * shake;
      if (g.x < 0) g.x = -g.x;
      if (g.x > 1) g.x = 2.0f - g.x;
      if (g.y < 0) g.y = -g.y;
      if (g.y > 1) g.y = 2.0f - g.y;
    }
  }

 public:
  void reset(uint32_t seed) override {
    rng = Random(seed);
    for (int i = 0; i <= kLut; i++) table[i] = float(std::cos(2.0 * pi * double(i) / kLut));
    grains.clear();
    modeA = modeB = Mode{3, 5, -1};
    morph = 1;
    modeIndex = beats = stepsSinceMode = 0;
    steps = -1;
    frac = pendingJolt = pendingMode = 0;
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    t = 0;
  }

  void update(const Frame& f) override {
    float dt = float(f.delta);
    if (grains.empty()) {
      int count = int(5000.0f + 2500.0f * std::clamp(f.detail, 0.25f, 2.0f));
      grains.resize(count);
      for (auto& g : grains) {
        g.x = g.px = rng.unit();
        g.y = g.py = rng.unit();
      }
    }
    const Music& m = f.music;
    bass = follow(bass, m.bass, 22.0f, 4.5f, dt);
    body = follow(body, m.body, 12.0f, 3.0f, dt);
    spark = follow(spark, m.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, m.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, m.active ? std::pow(std::clamp(m.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : m.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : m.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : m.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((m.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, m.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    if (hit > kick + 0.2f) {
      beats++;
      pendingJolt = std::max(pendingJolt, hit);
      if (beats % 4 == 0) pendingMode = 1;
    }
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));

    int64_t target = int64_t(std::floor(f.time * kHz + 1e-6));
    if (steps < 0 || target < steps || target - steps > 15) steps = target - 1;
    while (steps < target) {
      step();
      steps++;
    }
    frac = std::clamp(float(f.time * kHz - double(steps)), 0.0f, 1.0f);
  }

  void render(const Frame& f, Canvas& c) const override {
    float amp = f.intensity;
    float w = morph * morph * (3.0f - 2.0f * morph);
    std::vector<float> u;
    u.reserve(24);
    u.insert(u.end(), {t, bass * amp, kick * amp, energy});
    u.insert(u.end(), {modeA.n, modeA.m, modeA.s, modeB.n});
    u.insert(u.end(), {modeB.m, modeB.s, w, f.glow});
    for (int i = 0; i < 4; i++) u.insert(u.end(), {f.colors[i].r, f.colors[i].g, f.colors[i].b});
    c.material("plate", {0, 0, f.width, f.height}, u);
    if (grains.empty()) return;

    float px = std::min(f.width, f.height) / 400.0f;
    std::vector<Vec2> gold, white;
    gold.reserve(grains.size());
    white.reserve(grains.size() / 3 + 1);
    for (size_t i = 0; i < grains.size(); i++) {
      const Grain& g = grains[i];
      Vec2 p{(g.px + (g.x - g.px) * frac) * f.width, (g.py + (g.y - g.py) * frac) * f.height};
      if (i % 3 == 0) white.push_back(p); else gold.push_back(p);
    }
    const Color& sand = f.colors[2];
    const Color& hot = f.colors[3];
    float gain = std::clamp((0.75f + 0.5f * bass + 0.6f * kick) * amp, 0.0f, 1.6f);
    Paint halo;
    halo.blend = Blend::plus;
    halo.color = {sand.r, sand.g, sand.b, std::clamp(0.07f * gain * f.glow, 0.0f, 1.0f)};
    c.points(gold, 4.4f * px, halo);
    Paint core;
    core.blend = Blend::plus;
    core.color = {sand.r, sand.g, sand.b, std::clamp(0.7f * gain, 0.0f, 1.0f)};
    c.points(gold, 1.3f * px, core);
    float twinkle = 0.7f + 0.3f * spark;
    Paint bright;
    bright.blend = Blend::plus;
    bright.color = {hot.r, hot.g, hot.b, std::clamp(0.75f * gain * twinkle, 0.0f, 1.0f)};
    c.points(white, (1.0f + 0.6f * spark * amp + 0.6f * kick * amp) * px, bright);
  }
};

shaderSources.plate:
#version 460 core
#include <flutter/runtime_effect.glsl>
uniform vec2 uSize;
uniform vec4 uA;   // tiempo, graves, golpe, energía
uniform vec4 uM;   // modo anterior (n, m, signo) y n del modo nuevo
uniform vec4 uN;   // m y signo del modo nuevo, transición, glow
uniform vec3 uC0;
uniform vec3 uC1;
uniform vec3 uC2;
uniform vec3 uC3;
out vec4 fragColor;

const float PI = 3.14159265;

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

float plate(vec2 uv, float n, float m, float s) {
  return cos(n * PI * uv.x) * cos(m * PI * uv.y) + s * cos(m * PI * uv.x) * cos(n * PI * uv.y);
}

void main() {
  vec2 frag = FlutterFragCoord().xy;
  vec2 uv = frag / uSize;
  float scale = min(uSize.x, uSize.y);
  vec2 p = (frag - 0.5 * uSize) / scale;
  float f = mix(plate(uv, uM.x, uM.y, uM.z), plate(uv, uM.w, uN.x, uN.y), uN.z);

  // Placa metálica oscura con un brillo frío que sigue la figura: las líneas
  // quietas brillan suave y las zonas que vibran tiemblan con los graves.
  float lines = exp(-abs(f) * 9.0);
  float shimmer = abs(f) * (0.5 + 0.5 * sin(uA.x * 40.0 + f * 6.0));
  vec3 col = uC0 * (1.0 + 0.6 * smoothstep(1.2, 0.0, length(p)));
  col += uC1 * lines * (0.16 + 0.22 * uA.y + 0.35 * uA.z) * uN.w;
  // Resplandor dorado de la arena sobre las líneas.
  col += uC2 * exp(-abs(f) * 40.0) * (0.05 + 0.08 * uA.y + 0.18 * uA.z) * uN.w;
  col += uC1 * shimmer * (0.02 + 0.06 * uA.y) * uN.w;
  // Onda del golpe que recorre la placa.
  col += uC1 * uA.z * 0.08 * smoothstep(0.9, 0.0, length(p));

  col *= 1.0 - 0.45 * smoothstep(0.5, 1.3, length(p * vec2(0.9, 0.65)));
  col += (hash12(frag) - 0.5) / 255.0;
  fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

visuals.nativeSource:
class Visual final : public Scene {
  // La arena avanza en pasos fijos de 1/60 s contados con el tiempo absoluto:
  // es idéntica a 30 y a 60 FPS y se dibuja interpolada.
  static constexpr double kHz = 60.0;
  static constexpr float kStep = float(1.0 / kHz);
  static constexpr int kLut = 1024;
  struct Grain { float x, y, px, py; };
  struct Mode { float n, m, s; };
  std::vector<Grain> grains;
  std::array<float, kLut + 1> table{};
  Mode modeA{3, 5, -1}, modeB{3, 5, -1};
  float morph = 1;
  int modeIndex = 0, beats = 0, stepsSinceMode = 0;
  int64_t steps = -1;
  float frac = 0, pendingJolt = 0, pendingMode = 0;
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0, t = 0;
  Random rng{31};

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

  // cos(pi * x) desde una tabla: miles de granos por paso sin coste de trigonometría.
  float cospi(float x) const {
    float u = x * 0.5f;
    u -= std::floor(u);
    float i = u * kLut;
    int k = std::min(int(i), kLut - 1);
    float a = table[k];
    return a + (table[k + 1] - a) * (i - float(k));
  }
  float sinpi(float x) const { return cospi(x - 0.5f); }

  // Figura de Chladni de una placa rectangular y su gradiente.
  static float plate(const Mode& md, float x, float y, float& gx, float& gy, const Visual& v) {
    float cnx = v.cospi(md.n * x), cmy = v.cospi(md.m * y), cmx = v.cospi(md.m * x), cny = v.cospi(md.n * y);
    float snx = v.sinpi(md.n * x), smy = v.sinpi(md.m * y), smx = v.sinpi(md.m * x), sny = v.sinpi(md.n * y);
    const float p = 3.14159265f;
    gx = -p * (md.n * snx * cmy + md.s * md.m * smx * cny);
    gy = -p * (md.m * cnx * smy + md.s * md.n * cmx * sny);
    return cnx * cmy + md.s * cmx * cny;
  }

  void advanceMode() {
    // Figuras elegidas por su simetría: pares (n, m) y signo de la mezcla.
    static const Mode modes[10] = {{3, 5, -1}, {1, 5, 1}, {3, 7, -1}, {2, 6, 1}, {5, 7, -1},
                                   {1, 7, -1}, {4, 6, 1}, {3, 9, 1}, {2, 4, -1}, {5, 9, -1}};
    modeIndex = (modeIndex + 1) % 10;
    modeA = modeB;
    modeB = modes[modeIndex];
    morph = 0;
    stepsSinceMode = 0;
  }

  void step() {
    float jolt = pendingJolt;
    pendingJolt = 0;
    if (pendingMode > 0 || stepsSinceMode > int(kHz * 9.0)) {
      advanceMode();
      jolt = std::max(jolt, 0.8f);
      pendingMode = 0;
    }
    stepsSinceMode++;
    morph = std::min(1.0f, morph + kStep * 1.4f);
    t += kStep;
    float w = morph * morph * (3.0f - 2.0f * morph);
    float agitation = 0.0010f + 0.0012f * bass + 0.0006f * drive;
    float pull = 0.05f;  // fracción de la distancia a la línea por paso
    for (auto& g : grains) {
      g.px = g.x;
      g.py = g.y;
      float bx, by;
      float fv = plate(modeB, g.x, g.y, bx, by, *this);
      float gx = bx, gy = by;
      // La figura anterior sólo se calcula durante la transición.
      if (w < 1.0f) {
        float ax, ay;
        float fa = plate(modeA, g.x, g.y, ax, ay, *this);
        fv = fa + (fv - fa) * w;
        gx = ax + (bx - ax) * w;
        gy = ay + (by - ay) * w;
      }
      float gl = std::sqrt(gx * gx + gy * gy) + 1e-3f;
      // La arena baja por la pendiente de |f| hacia las líneas quietas y salta
      // más donde la placa vibra con fuerza.
      float stepLen = std::min(std::fabs(fv) / gl, 0.06f);
      float dir = fv > 0 ? -1.0f : 1.0f;
      g.x += dir * gx / gl * stepLen * pull;
      g.y += dir * gy / gl * stepLen * pull;
      float shake = agitation * (0.6f + 2.5f * std::fabs(fv)) + jolt * 0.06f * (0.3f + std::fabs(fv));
      g.x += (rng.unit() - 0.5f) * shake;
      g.y += (rng.unit() - 0.5f) * shake;
      if (g.x < 0) g.x = -g.x;
      if (g.x > 1) g.x = 2.0f - g.x;
      if (g.y < 0) g.y = -g.y;
      if (g.y > 1) g.y = 2.0f - g.y;
    }
  }

 public:
  void reset(uint32_t seed) override {
    rng = Random(seed);
    for (int i = 0; i <= kLut; i++) table[i] = float(std::cos(2.0 * pi * double(i) / kLut));
    grains.clear();
    modeA = modeB = Mode{3, 5, -1};
    morph = 1;
    modeIndex = beats = stepsSinceMode = 0;
    steps = -1;
    frac = pendingJolt = pendingMode = 0;
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    t = 0;
  }

  void update(const Frame& f) override {
    float dt = float(f.delta);
    if (grains.empty()) {
      int count = int(5000.0f + 2500.0f * std::clamp(f.detail, 0.25f, 2.0f));
      grains.resize(count);
      for (auto& g : grains) {
        g.x = g.px = rng.unit();
        g.y = g.py = rng.unit();
      }
    }
    const Music& m = f.music;
    bass = follow(bass, m.bass, 22.0f, 4.5f, dt);
    body = follow(body, m.body, 12.0f, 3.0f, dt);
    spark = follow(spark, m.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, m.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, m.active ? std::pow(std::clamp(m.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : m.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : m.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : m.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((m.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, m.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    if (hit > kick + 0.2f) {
      beats++;
      pendingJolt = std::max(pendingJolt, hit);
      if (beats % 4 == 0) pendingMode = 1;
    }
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));

    int64_t target = int64_t(std::floor(f.time * kHz + 1e-6));
    if (steps < 0 || target < steps || target - steps > 15) steps = target - 1;
    while (steps < target) {
      step();
      steps++;
    }
    frac = std::clamp(float(f.time * kHz - double(steps)), 0.0f, 1.0f);
  }

  void render(const Frame& f, Canvas& c) const override {
    float amp = f.intensity;
    float w = morph * morph * (3.0f - 2.0f * morph);
    std::vector<float> u;
    u.reserve(24);
    u.insert(u.end(), {t, bass * amp, kick * amp, energy});
    u.insert(u.end(), {modeA.n, modeA.m, modeA.s, modeB.n});
    u.insert(u.end(), {modeB.m, modeB.s, w, f.glow});
    for (int i = 0; i < 4; i++) u.insert(u.end(), {f.colors[i].r, f.colors[i].g, f.colors[i].b});
    c.material("plate", {0, 0, f.width, f.height}, u);
    if (grains.empty()) return;

    float px = std::min(f.width, f.height) / 400.0f;
    std::vector<Vec2> gold, white;
    gold.reserve(grains.size());
    white.reserve(grains.size() / 3 + 1);
    for (size_t i = 0; i < grains.size(); i++) {
      const Grain& g = grains[i];
      Vec2 p{(g.px + (g.x - g.px) * frac) * f.width, (g.py + (g.y - g.py) * frac) * f.height};
      if (i % 3 == 0) white.push_back(p); else gold.push_back(p);
    }
    const Color& sand = f.colors[2];
    const Color& hot = f.colors[3];
    float gain = std::clamp((0.75f + 0.5f * bass + 0.6f * kick) * amp, 0.0f, 1.6f);
    Paint halo;
    halo.blend = Blend::plus;
    halo.color = {sand.r, sand.g, sand.b, std::clamp(0.07f * gain * f.glow, 0.0f, 1.0f)};
    c.points(gold, 4.4f * px, halo);
    Paint core;
    core.blend = Blend::plus;
    core.color = {sand.r, sand.g, sand.b, std::clamp(0.7f * gain, 0.0f, 1.0f)};
    c.points(gold, 1.3f * px, core);
    float twinkle = 0.7f + 0.3f * spark;
    Paint bright;
    bright.blend = Blend::plus;
    bright.color = {hot.r, hot.g, hot.b, std::clamp(0.75f * gain * twinkle, 0.0f, 1.0f)};
    c.points(white, (1.0f + 0.6f * spark * amp + 0.6f * kick * amp) * px, bright);
  }
};

