visuals.nativeSource:
class Visual final : public Scene {
  static constexpr int kLayers = 6;
  static constexpr int kBins = 32;
  static constexpr int kParticles = 150;
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  std::array<std::array<float, kBins>, kLayers> layers{};
  // Relojes en doble precisión: la escena sin música es idéntica a 30 y 60 FPS.
  double clock = 0, rise = 0, sway = 0;
  bool live = false;
  std::array<float, kParticles> pAngle{}, pSpeed{}, pPhase{}, pSize{};

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

  // Onda tranquila sin música, calculada directamente del tiempo.
  static float idle(int i, double t) {
    return 0.18f + 0.1f * float(std::sin(t * 1.7 + double(i) * 0.45)) * float(std::sin(t * 0.6 + double(i) * 0.21)) +
           0.08f * float(std::sin(t * 3.1 + double(i) * 0.9));
  }

 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    for (auto& l : layers) l.fill(0);
    clock = 0;
    rise = 0;
    sway = 0;
    live = false;
    for (int i = 0; i < kParticles; i++) {
      pAngle[size_t(i)] = rng.unit() * 6.2831853f;
      pSpeed[size_t(i)] = 0.15f + 0.35f * rng.unit();
      pPhase[size_t(i)] = rng.unit();
      pSize[size_t(i)] = 0.6f + 1.4f * rng.unit();
    }
  }

  void update(const Frame& f) override {
    float dt = float(f.delta);
    const Music& mu = f.music;
    bass = follow(bass, mu.bass, 22.0f, 4.5f, dt);
    body = follow(body, mu.body, 12.0f, 3.0f, dt);
    spark = follow(spark, mu.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, mu.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, mu.active ? std::pow(std::clamp(mu.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : mu.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : mu.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : mu.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((mu.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, mu.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    clock += f.delta * f.speed;
    rise += f.delta * f.speed * (1.0 + 2.5 * drive + 2.0 * kick);
    sway = std::fmod(sway + f.delta * f.speed * 0.9, 6.283185307179586);
    live = mu.active;
    if (mu.active) {
      // Cada capa sigue a la anterior con retraso: el círculo deja un rastro.
      for (int i = 0; i < kBins; i++) {
        float v = mu.smoothSpectrum[size_t(std::min(i, 30))];
        layers[0][size_t(i)] = follow(layers[0][size_t(i)], v, 30.0f, 8.0f, dt);
      }
      for (int l = 1; l < kLayers; l++) {
        for (int i = 0; i < kBins; i++) layers[size_t(l)][size_t(i)] = follow(layers[size_t(l)][size_t(i)], layers[size_t(l - 1)][size_t(i)], 9.0f, 6.0f, dt);
      }
    }
  }

  void render(const Frame& f, Canvas& c) const override {
    auto m = modifiers(f);
    auto gl = glide(f);
    float amp = f.intensity;
    const Color& bg = f.colors[0];
    float side = std::min(f.width, f.height);
    float px = side / 400.0f;
    float shakeX = 0, shakeY = 0;
    if (m.temblor) {
      float a = bass * bass * 7.0f * px * amp + kick * 4.0f * px * amp;
      shakeX = a * float(std::sin(clock * 37.0));
      shakeY = a * float(std::cos(clock * 43.0));
    }
    Vec2 center{f.width * 0.5f + shakeX, f.height * 0.5f + shakeY};
    int n = std::clamp(m.capas, 2, kLayers);
    // De delante hacia atrás: los acentos de la paleta y el primero cada vez
    // más oscuro, así el rastro se hunde en el fondo.
    auto dim = [](const Color& col, float k) { return Color{col.r * k, col.g * k, col.b * k, 1.0f}; };
    const std::array<Color, kLayers> pal = {f.colors[3], f.colors[2], f.colors[1],
                                            dim(f.colors[1], 0.85f), dim(f.colors[1], 0.55f), dim(f.colors[1], 0.35f)};
    // Remolino: cada capa gira un poco más que la de delante y se mece con
    // retraso, y lo que sobresale de cada onda se curva hacia un lado; a 0
    // todas quedan alineadas como el visualizador clásico.
    const float swirl = gl.remolino;
    auto twist = [&](int l) { return swirl * (0.6f * float(l) + 0.35f * float(std::sin(sway + 0.7 * double(l)))); };
    // Fondo con resplandor del color principal y rayos tenues que giran.
    c.rect({0, 0, f.width, f.height}, Paint::radial(center, std::max(f.width, f.height) * 0.75f,
                                                   {Color{std::min(1.0f, bg.r + pal[2].r * 0.12f * (1.0f + bass)), std::min(1.0f, bg.g + pal[2].g * 0.06f * (1.0f + bass)),
                                                          std::min(1.0f, bg.b + pal[2].b * 0.06f), 1.0f},
                                                    Color{bg.r, bg.g, bg.b, 1.0f}}));
    float R = side * 0.2f * (1.0f + 0.1f * bass * amp + 0.05f * kick * amp);
    if (m.particulas) {
      std::array<std::vector<Vec2>, 3> groups;
      for (auto& g : groups) g.reserve(kParticles / 3 + 1);
      float reach = std::max(f.width, f.height) * 0.7f;
      for (int i = 0; i < kParticles; i++) {
        float life = float(std::fmod(rise * double(pSpeed[size_t(i)]) + double(pPhase[size_t(i)]), 1.0));
        float r = R * 1.05f + life * life * reach;
        // Con remolino salen en espiral: el ángulo avanza con la distancia.
        float a = pAngle[size_t(i)] + float(clock * 0.05) + swirl * 1.6f * life;
        groups[size_t(i % 3)].push_back({center.x + r * std::cos(a), center.y + r * std::sin(a)});
      }
      for (int g = 0; g < 3; g++) {
        Paint p;
        p.blend = Blend::plus;
        p.color = pal[size_t(1 + g)].opacity(std::clamp((0.35f + 0.4f * spark) * amp, 0.0f, 1.0f));
        c.points(groups[size_t(g)], (1.2f + 0.8f * float(g)) * px, p);
      }
    }
    // Ondas de atrás hacia delante.
    const int samples = 72;
    for (int l = n - 1; l >= 0; l--) {
      Path p;
      const float turn = twist(l);
      for (int k = 0; k <= samples * 2; k++) {
        float u = float(k) / float(samples * 2);
        float a = -1.5707963f + u * 6.2831853f + turn;
        float mirror = 1.0f - std::fabs(1.0f - 2.0f * u);
        float pos = mirror * float(kBins - 1) * 0.85f;
        int i0 = int(pos);
        float fr = pos - float(i0);
        int i1 = std::min(i0 + 1, kBins - 1);
        float v0, v1;
        if (live) {
          v0 = layers[size_t(l)][size_t(i0)];
          v1 = layers[size_t(l)][size_t(i1)];
        } else {
          v0 = idle(i0, clock - 0.08 * double(l));
          v1 = idle(i1, clock - 0.08 * double(l));
        }
        float v = (v0 + (v1 - v0) * fr) * amp;
        float bulge = std::max(v * (1.0f + 0.22f * float(l)), 0.0f);
        float r = R * (1.02f + 0.07f * float(l)) + side * 0.2f * bulge;
        // Cuanto más sobresale, más se curva (hasta ~1 radián).
        a += swirl * 1.1f * bulge / (0.5f + bulge);
        float x = center.x + r * std::cos(a), y = center.y + r * std::sin(a);
        if (k == 0) p.moveTo(x, y); else p.lineTo(x, y);
      }
      p.close();
      Paint fill;
      const Color& col = pal[size_t(std::min(l, kLayers - 1))];
      fill.color = col;
      c.path(p, fill);
      if (l == 0) {
        // Borde blanco fino en la onda de delante.
        Paint edge;
        edge.strokeWidth = 2.0f * px;
        edge.strokeJoin = 1;
        edge.color = Color{1.0f, 1.0f, 1.0f, std::clamp(0.85f * amp, 0.0f, 1.0f)};
        c.path(p, edge);
      }
    }
    // Disco central oscuro con aros que laten.
    Paint disc = Paint::radial(center, R, {Color{bg.r * 0.6f + 0.06f, bg.g * 0.6f + 0.03f, bg.b * 0.6f + 0.04f, 1.0f}, Color{bg.r, bg.g, bg.b, 1.0f}});
    c.circle(center, R, disc);
    Paint ring;
    ring.strokeWidth = (2.5f + 3.0f * kick) * px;
    ring.color = pal[0].opacity(std::clamp(0.9f * amp, 0.0f, 1.0f));
    Path rp;
    rp.circle(center, R);
    c.path(rp, ring);
    Paint inner;
    inner.blend = Blend::plus;
    inner.strokeWidth = 1.5f * px;
    inner.color = pal[2].opacity(std::clamp((0.25f + 0.5f * bass) * amp, 0.0f, 1.0f));
    Path ip;
    ip.circle(center, R * (0.55f + 0.25f * float(std::fmod(rise * 0.4, 1.0))));
    c.path(ip, inner);
    if (flash > 0.01f) {
      Paint fl;
      fl.blend = Blend::plus;
      fl.color = pal[2].opacity(std::clamp(flash * 0.06f * amp, 0.0f, 1.0f));
      c.rect({0, 0, f.width, f.height}, fl);
    }
  }
};

class Visual final : public Scene {
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  std::array<float, 3> bands{};
  // Relojes en doble precisión: la escena sin música es idéntica a 30 y 60 FPS.
  double travel = 0, spin = 0, sinceWave = 100, sinceSwitch = 0;
  float wavePower = 0, fade = 1;
  int beats = 0, current = 1, previous = 1, autoSize = 1;

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

  // Pares (i, j) de la red: i·e1 + j·e2 da exactamente una vuelta. Con
  // i - j múltiplo de 3 los tres colores de círculo casan al cerrar la vuelta.
  static void lattice(int size, float& i, float& j) {
    if (size == 0) { i = 5; j = 2; return; }
    if (size == 1) { i = 8; j = 5; return; }
    i = 13; j = 7;
  }

 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    bands.fill(0);
    travel = rng.unit();
    spin = rng.unit() * 6.2831853;
    sinceWave = 100;
    sinceSwitch = 0;
    wavePower = 0;
    fade = 1;
    beats = 0;
    current = previous = autoSize = 1;
  }

  void update(const Frame& f) override {
    auto m = modifiers(f);
    float dt = float(f.delta);
    const Music& mu = f.music;
    bass = follow(bass, mu.bass, 22.0f, 4.5f, dt);
    body = follow(body, mu.body, 12.0f, 3.0f, dt);
    spark = follow(spark, mu.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, mu.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, mu.active ? std::pow(std::clamp(mu.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);
    for (int b = 0; b < 3; b++) {
      float v = 0;
      for (int k = b * 10; k < b * 10 + 10; k++) v = std::max(v, mu.smoothSpectrum[size_t(k)]);
      bands[size_t(b)] = follow(bands[size_t(b)], v, 18.0f, 4.0f, dt);
    }

    float hit = 0, fl = 0;
    for (const auto& e : mu.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : mu.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : mu.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((mu.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, mu.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    sinceWave += f.delta;
    sinceSwitch += f.delta;
    if (hit > kick + 0.2f) {
      beats++;
      sinceWave = 0;
      wavePower = hit;
      if (beats % 8 == 0) {
        autoSize = (autoSize + 1) % 3;
        sinceSwitch = 0;
      }
    }
    if (!mu.active && sinceSwitch > 12.0) {
      autoSize = (autoSize + 1) % 3;
      sinceSwitch = 0;
    }
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    int wanted = m.espiral == 0 ? autoSize : m.espiral - 1;
    if (wanted != current) {
      previous = current;
      current = wanted;
      fade = 0;
    }
    fade = std::min(1.0f, fade + dt * 1.2f);
    // Avance en vectores de la red: cada 3 pasos los colores vuelven a coincidir.
    travel += f.delta * f.speed * m.velocidad_zoom * (0.18 + 0.4 * drive + 0.25 * kick);
    spin += f.delta * f.speed * (0.6 + 1.2 * drive);
  }

  void render(const Frame& f, Canvas& c) const override {
    auto m = modifiers(f);
    float amp = f.intensity;
    float ia, ja, ib, jb;
    lattice(current, ia, ja);
    lattice(previous, ib, jb);
    float wave = sinceWave < 3.0 ? float(sinceWave) * 2.2f - 4.0f : 10.0f;
    std::vector<float> u;
    u.reserve(32);
    u.insert(u.end(), {float(std::fmod(travel, 3.0)), bass * amp, kick * amp, energy});
    u.insert(u.end(), {ia, ja, ib, jb});
    u.insert(u.end(), {fade, m.grosor, m.anidados ? 1.0f : 0.0f, float(std::fmod(spin, 6.2831853))});
    u.insert(u.end(), {wave, wavePower * amp, f.glow, flash * amp});
    u.insert(u.end(), {bands[0] * amp, bands[1] * amp, bands[2] * amp, spark * amp});
    for (int i = 0; i < 4; i++) u.insert(u.end(), {f.colors[i].r, f.colors[i].g, f.colors[i].b});
    c.material("doyle_zoom", {0, 0, f.width, f.height}, u);
  }
};

shaderSources.doyle_zoom:
#version 460 core
#include <flutter/runtime_effect.glsl>
uniform vec2 uSize;
uniform vec4 uA;   // avance (0..3), graves, golpe, energía
uniform vec4 uB;   // red actual (i, j), red anterior (i, j)
uniform vec4 uD;   // fundido, grosor, anidados, giro interior
uniform vec4 uE;   // onda (log r), fuerza de la onda, glow, destello
uniform vec4 uS;   // graves, medios, agudos del espectro, chispa
uniform vec3 uC0;
uniform vec3 uC1;
uniform vec3 uC2;
uniform vec3 uC3;
out vec4 fragColor;

const float TAU = 6.2831853;

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

float bandFor(float k) {
  return k < 1.0 ? uS.x : (k < 2.0 ? uS.y : uS.z);
}

vec3 familyColor(float k) {
  return k < 1.0 ? uC1 : (k < 2.0 ? uC2 : mix(uC1, uC3, 0.6));
}

// Un aro suavizado; fw es el tamaño del píxel en el plano log-polar.
float ring(float dist, float radius, float width, float fw) {
  float w = max(width, fw);
  float on = 1.0 - smoothstep(w * 0.5, w * 0.5 + fw, abs(dist - radius));
  return on * min(1.0, width / fw);
}

// Espiral de Doyle para la red (i, j): color del píxel en el plano log-polar.
vec3 doyle(vec2 w, float fw, float i, float j) {
  float d = TAU / sqrt(i * i + i * j + j * j);
  // Base hexagonal girada para que i·e1 + j·e2 apunte a una vuelta completa.
  vec2 v = vec2(i + 0.5 * j, 0.8660254 * j) * d;
  float ang = atan(v.y, v.x);
  float rot = 1.5707963 - ang;
  float cs = cos(rot);
  float sn = sin(rot);
  vec2 e1 = vec2(cs, sn) * d;
  vec2 e2 = vec2(cs * 0.5 - sn * 0.8660254, sn * 0.5 + cs * 0.8660254) * d;
  // Zoom continuo: desplazar 3·e1 deja la red y sus colores iguales.
  w -= e1 * uA.x;
  float det = e1.x * e2.y - e1.y * e2.x;
  vec2 ab = vec2(w.x * e2.y - w.y * e2.x, e1.x * w.y - e1.y * w.x) / det;
  vec2 base = floor(ab);
  vec2 best = base;
  float bestD = 1e9;
  for (int k = 0; k < 4; k++) {
    vec2 o = vec2(float(k - (k / 2) * 2), float(k / 2));
    vec2 cand = base + o;
    vec2 cw = cand.x * e1 + cand.y * e2;
    float dd = length(w - cw);
    if (dd < bestD) {
      bestD = dd;
      best = cand;
    }
  }
  vec2 center = best.x * e1 + best.y * e2;
  vec2 rel = w - center;
  float R = d * 0.5;
  float family = mod(best.x - best.y + 300.0, 3.0);
  float level = bandFor(family);
  vec3 tint = familyColor(family);
  float width = R * 0.07 * uD.y * (1.0 + 0.6 * uA.y);
  float main = ring(bestD, R * 0.93, width, fw);
  vec3 col = tint * main * (0.75 + 0.9 * level);
  // Relleno tenue dentro de cada círculo.
  col += tint * 0.06 * (1.0 - smoothstep(R * 0.8, R * 0.93, bestD)) * (0.6 + level);
  if (uD.z > 0.5) {
    // Tres círculos tangentes dentro de cada círculo, girando.
    float r3 = R * 0.93 * 0.4641016;
    float cdist = R * 0.93 - r3;
    float spinDir = mod(family, 2.0) < 1.0 ? 1.0 : -1.0;
    float a0 = uD.w * spinDir + family;
    float inner = 0.0;
    for (int k = 0; k < 3; k++) {
      float a = a0 + float(k) * 2.0943951;
      vec2 cc = vec2(cos(a), sin(a)) * cdist;
      inner = max(inner, ring(length(rel - cc), r3, width * 0.7, fw));
    }
    col += mix(tint, uC3, 0.35) * inner * (0.45 + 0.8 * level);
  }
  return col;
}

void main() {
  vec2 frag = FlutterFragCoord().xy;
  float scale = min(uSize.x, uSize.y);
  vec2 p = (frag - 0.5 * uSize) / scale;
  float r = max(length(p), 1e-4);
  vec2 w = vec2(log(r), atan(p.y, p.x));
  float fw = 1.5 / (scale * r);
  vec3 col = doyle(w, fw, uB.x, uB.y);
  if (uD.x < 1.0) col = mix(doyle(w, fw, uB.z, uB.w), col, smoothstep(0.0, 1.0, uD.x));
  // Onda de luz del centro hacia fuera con cada golpe.
  float wave = exp(-abs(w.x - uE.x) * 3.0) * uE.y;
  col *= 1.0 + 1.8 * wave;
  col += uC3 * wave * 0.05;
  // El centro se vuelve un punto de luz donde los círculos son diminutos.
  float core = exp(-r * 22.0);
  col = mix(col, mix(uC1, uC3, 0.5) * (0.35 + 0.6 * uA.y + 0.5 * uA.z), core);
  col *= (0.85 + 0.25 * uA.z) * mix(1.0, uE.z, 0.6);
  col += uC1 * uE.w * 0.05;
  col += uC0;
  // Compresión que conserva el tono.
  float peak = max(col.r, max(col.g, col.b));
  if (peak > 0.85) {
    float e = (peak - 0.85) / 0.15;
    col *= (0.85 + 0.15 * e / (1.0 + e)) / peak;
  }
  col += (hash12(frag) - 0.5) / 255.0;
  fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

visuals.nativeSource:
class Visual final : public Scene {
  static constexpr int kMax = 900;
  static constexpr double kStep = 1.0 / 60.0;
  struct Piece { float x, y, px, py, vx, vy, angle, spin, flip, flipSpeed, w, h; uint8_t color, shape; };
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  // Relojes en doble precisión: la escena sin música es idéntica a 30 y 60 FPS.
  double sim = 0, nextIdle = 0.3, rainAcc = 0;
  int64_t steps = 0;
  int idleCount = 0, side = 0;
  int pendingLeft = 0, pendingRight = 0, pendingCenter = 0;
  // Fogonazos de Golpes: edad del último disparo de cada cañón y del último
  // estallido, su fuerza y dónde estalló.
  double leftAge = 100, rightAge = 100, popAge = 100;
  float burstPow = 0, popX = 0, popY = 0;
  float width = 1, height = 1;
  Random rng{1};
  std::vector<Piece> pieces;

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }
  static float hashU(uint32_t x) {
    x ^= x >> 16; x *= 0x7feb352dU; x ^= x >> 15; x *= 0x846ca68bU; x ^= x >> 16;
    return float(x & 0xffffffu) / 16777216.0f;
  }

  // El tono intermedio de dos colores por el arco corto del círculo de tonos,
  // con la saturación media y el valor del más luminoso: rojo y amarillo dan
  // naranja, amarillo y azul dan verde.
  static Color between(const Color& a, const Color& b) {
    auto hsv = [](const Color& c, float& h, float& s, float& v) {
      float hi = std::max({c.r, c.g, c.b}), lo = std::min({c.r, c.g, c.b}), d = hi - lo;
      v = hi;
      s = hi > 1e-5f ? d / hi : 0.0f;
      h = 0.0f;
      if (d > 1e-5f) {
        if (hi == c.r) h = (c.g - c.b) / d;
        else if (hi == c.g) h = 2.0f + (c.b - c.r) / d;
        else h = 4.0f + (c.r - c.g) / d;
        h /= 6.0f;
        if (h < 0.0f) h += 1.0f;
      }
    };
    float ha, sa, va, hb, sb, vb;
    hsv(a, ha, sa, va);
    hsv(b, hb, sb, vb);
    if (sa < 0.05f) ha = hb;
    if (sb < 0.05f) hb = ha;
    float dh = hb - ha;
    if (dh > 0.5f) dh -= 1.0f;
    if (dh < -0.5f) dh += 1.0f;
    float h = ha + dh * 0.5f;
    h -= std::floor(h);
    float s = 0.5f * (sa + sb), v = std::max(va, vb);
    auto ch = [&](float n) {
      float k = std::fmod(n + h * 6.0f, 6.0f);
      return std::clamp(v - v * s * std::clamp(std::min(k, 4.0f - k), 0.0f, 1.0f), 0.0f, 1.0f);
    };
    return Color{ch(5.0f), ch(3.0f), ch(1.0f), 1.0f};
  }

  void spawn(float x, float y, float vx, float vy, float sizeMul) {
    if (int(pieces.size()) >= kMax) return;
    float s = std::min(width, height);
    Piece p;
    p.x = p.px = x;
    p.y = p.py = y;
    p.vx = vx;
    p.vy = vy;
    p.angle = rng.unit() * 6.2831853f;
    p.spin = (rng.unit() - 0.5f) * 9.0f;
    p.flip = rng.unit() * 6.2831853f;
    p.flipSpeed = 4.0f + 9.0f * rng.unit();
    p.shape = uint8_t(std::min(int(rng.unit() * 3.0f), 2));
    float base = s * 0.012f * sizeMul * (0.7f + 0.6f * rng.unit());
    p.w = p.shape == 1 ? base * 0.45f : base;
    p.h = p.shape == 1 ? base * 2.6f : (p.shape == 2 ? base : base * 1.5f);
    p.color = uint8_t(std::min(int(rng.unit() * 6.0f), 5));
    pieces.push_back(p);
  }

  void cannon(bool left, int count, float sizeMul) {
    float s = std::min(width, height);
    for (int i = 0; i < count; i++) {
      float a = (left ? -1.05f : -2.09f) + (rng.unit() - 0.5f) * 0.55f;
      float speed = s * (1.9f + 1.4f * rng.unit());
      spawn(left ? 0.0f : width, height * 1.01f, std::cos(a) * speed, std::sin(a) * speed, sizeMul);
    }
  }

  void pop(int count, float sizeMul) {
    float s = std::min(width, height);
    float cx = width * (0.3f + 0.4f * rng.unit()), cy = height * (0.3f + 0.25f * rng.unit());
    popX = cx;
    popY = cy;
    for (int i = 0; i < count; i++) {
      float a = rng.unit() * 6.2831853f;
      float speed = s * (0.4f + 1.3f * rng.unit());
      spawn(cx, cy, std::cos(a) * speed, std::sin(a) * speed - s * 0.5f, sizeMul);
    }
  }

  // [flutter], [swirl] y [wind] son los pesos de Vuelo (suman 1); [lift], el
  // soplo de los graves (cero sin música).
  void step(float rainRate, float amount, float sizeMul, bool rain, float flutter, float swirl, float wind, float lift) {
    float s = std::min(width, height);
    float dt = float(kStep);
    double t = double(steps) * kStep;
    // Sin música: ráfagas a su hora exacta, alternando cañones y estallidos.
    if (t >= nextIdle) {
      int kind = idleCount % 4;
      int n = int(55.0f * amount);
      if (kind == 0) cannon(true, n, sizeMul);
      if (kind == 1) cannon(false, n, sizeMul);
      if (kind == 2) { cannon(true, n / 2, sizeMul); cannon(false, n / 2, sizeMul); }
      if (kind == 3) pop(n, sizeMul);
      idleCount++;
      nextIdle += 3.2;
    }
    if (pendingLeft > 0) { cannon(true, pendingLeft, sizeMul); pendingLeft = 0; }
    if (pendingRight > 0) { cannon(false, pendingRight, sizeMul); pendingRight = 0; }
    if (pendingCenter > 0) { pop(pendingCenter, sizeMul); pendingCenter = 0; }
    if (rain) {
      rainAcc += double(rainRate) * kStep;
      while (rainAcc >= 1.0) {
        rainAcc -= 1.0;
        spawn(rng.unit() * width, -s * 0.03f, (rng.unit() - 0.5f) * s * 0.2f, s * 0.15f, sizeMul);
      }
    }
    // En el remolino flotan: la gravedad pesa menos.
    const float g = s * 1.35f * (1.0f - 0.55f * swirl);
    const float drag = 2.4f;
    float k = std::exp(-drag * dt);
    const float cx = width * 0.5f, cy = height * 0.45f;
    // Viento: ráfagas que cambian de lado despacio y ondulan con la altura.
    const float gust = float(std::sin(t * 0.45));
    for (auto& p : pieces) {
      p.px = p.x;
      p.py = p.y;
      // Los papelitos planean: más freno cuanto más de cara caen.
      float face = std::fabs(std::cos(p.flip));
      p.vy += g * dt;
      // Graves: un soplo desde abajo hace flotar el confeti.
      if (lift > 0.0f) p.vy -= lift * dt;
      float kk = k * (1.0f - 0.02f * face);
      p.vx *= kk;
      p.vy *= kk;
      // Aleteo: cada papelito se mece de lado según cómo gira.
      p.vx += std::sin(p.flip * 0.5f + p.angle) * s * 0.35f * dt * (flutter + 0.3f * wind);
      if (swirl > 0.0f) {
        // Remolino: empuje tangencial alrededor del centro (máximo a 0,35 del
        // lado) y un tirón hacia dentro que los mantiene girando.
        float dx = p.x - cx, dy = p.y - cy;
        float r = std::sqrt(dx * dx + dy * dy + 1.0f);
        float q = r / (0.35f * s);
        float push = s * 3.4f * q / (1.0f + q * q) * swirl;
        float pull = s * 0.9f * std::min(q, 1.5f) * swirl;
        p.vx += (-dy / r * push - dx / r * pull) * dt;
        p.vy += (dx / r * push - dy / r * pull) * dt;
      }
      if (wind > 0.0f) {
        float blow = s * (1.25f * gust + 0.7f * std::sin(float(t) * 1.7f + p.y / s * 3.0f));
        p.vx += blow * wind * dt;
      }
      p.x += p.vx * dt;
      p.y += p.vy * dt;
      p.angle += p.spin * dt * (1.0f + wind);
      p.flip += p.flipSpeed * dt * (1.0f + 0.8f * wind);
    }
    pieces.erase(std::remove_if(pieces.begin(), pieces.end(), [&](const Piece& p) {
      return p.y > height + s * 0.08f || p.x < -s * 0.3f || p.x > width + s * 0.3f;
    }), pieces.end());
  }

 public:
  void reset(uint32_t seed) override {
    rng = Random(seed);
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    sim = 0;
    steps = 0;
    nextIdle = 0.3;
    rainAcc = 0;
    idleCount = 0;
    side = 0;
    pendingLeft = pendingRight = pendingCenter = 0;
    leftAge = rightAge = popAge = 100;
    burstPow = popX = popY = 0;
    pieces.clear();
    pieces.reserve(kMax + 64);
  }

  void update(const Frame& f) override {
    auto m = modifiers(f);
    float dt = float(f.delta);
    const Music& mu = f.music;
    bass = follow(bass, mu.bass, 22.0f, 4.5f, dt);
    body = follow(body, mu.body, 12.0f, 3.0f, dt);
    spark = follow(spark, mu.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, mu.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, mu.active ? std::pow(std::clamp(mu.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : mu.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : mu.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : mu.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((mu.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, mu.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    bool beat = hit > kick + 0.2f;
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    width = f.width;
    height = f.height;
    leftAge += f.delta;
    rightAge += f.delta;
    popAge += f.delta;
    if (beat) {
      int n = int((14.0f + 30.0f * hit) * m.cantidad);
      burstPow = hit;
      // Golpes: ráfagas mucho más grandes y un estallido extra en el centro.
      if (m.pulso == 0) {
        n = int(float(n) * (1.0f + 0.8f * std::min(f.intensity, 2.0f)));
        if (hit <= 0.75f) {
          pendingCenter += n / 2;
          popAge = 0.0;
        }
      }
      if (hit > 0.75f) {
        pendingLeft += n;
        pendingRight += n;
        pendingCenter += n;
        leftAge = rightAge = popAge = 0.0;
      } else if ((side++ & 1) == 0) {
        pendingLeft += n;
        leftAge = 0.0;
      } else {
        pendingRight += n;
        rightAge = 0.0;
      }
    }
    if (fl > 0.5f) pendingCenter += int(30.0f * m.cantidad);
    // Con música las ráfagas las marcan los golpes, no el reloj.
    if (mu.active) nextIdle = double(steps) * kStep + 3.2;
    sim += f.delta * f.speed;
    int64_t target = int64_t(std::floor(sim / kStep + 1e-6));
    if (target - steps > 30) steps = target - 30;
    float rainRate = (6.0f + 40.0f * energy) * m.cantidad;
    auto g = glide(f);
    const float flutter = g.vuelo.weight(0), swirl = g.vuelo.weight(1), wind = g.vuelo.weight(2);
    const float lift = std::min(bass * f.intensity, 1.0f) * g.pulso.weight(1) * std::min(width, height) * 1.5f;
    while (steps < target) {
      step(rainRate, m.cantidad, m.tamano, m.lluvia, flutter, swirl, wind, lift);
      steps++;
    }
  }

  void render(const Frame& f, Canvas& c) const override {
    auto m = modifiers(f);
    auto gl = glide(f);
    float amp = f.intensity;
    // Pulso: cada opción mueve algo distinto; sin música todo vale cero.
    const float kickP = std::min(kick * amp, 1.0f) * gl.pulso.weight(0);
    const float bassP = std::min(bass * amp, 1.0f) * gl.pulso.weight(1);
    const float sparkP = std::min(spark * amp, 1.0f) * gl.pulso.weight(2);
    // Golpes: salto de tamaño; Graves: el confeti se hincha con los graves.
    const float grow = 1.0f + 0.2f * kickP + 0.15f * bassP;
    // Agudos: las caras que miran de frente, y muchos papelitos sueltos,
    // destellan como lentejuelas.
    std::vector<Vec2> glints;
    if (sparkP > 0.002f) glints.reserve(pieces.size());
    const uint32_t tick = uint32_t(std::fmod(sim, 100000.0) * 14.0);
    const float span = std::min(f.width, f.height);
    // Golpes: un fogonazo de luz en la boca de cada cañón y en cada estallido.
    const float burst = std::min(burstPow * amp, 1.0f) * gl.pulso.weight(0);
    auto bloom = [&](Vec2 at, double age, float radius) {
      if (age > 1.5) return;
      const float o = std::clamp(0.4f * burst * std::exp(-float(age) * 5.0f) * f.glow, 0.0f, 0.6f);
      if (o < 0.003f) return;
      Paint bp = Paint::radial(at, radius, {f.colors[3].opacity(o), f.colors[2].opacity(o * 0.5f), f.colors[1].opacity(0.0f)},
                               {0.0f, 0.4f, 1.0f});
      bp.blend = Blend::plus;
      c.circle(at, radius, bp);
    };
    if (burst > 0.002f) {
      bloom({0.0f, f.height}, leftAge, span * 0.45f);
      bloom({f.width, f.height}, rightAge, span * 0.45f);
      bloom({popX, popY}, popAge, span * 0.32f);
    }
    // Graves: el soplo de abajo se ve como un resplandor que late.
    const float updraft = std::clamp(0.28f * bassP * f.glow, 0.0f, 0.5f);
    if (updraft > 0.003f) {
      const Vec2 at{f.width * 0.5f, f.height * 1.05f};
      Paint up = Paint::radial(at, span * 0.7f, {f.colors[2].opacity(updraft), f.colors[1].opacity(0.0f)});
      up.blend = Blend::plus;
      c.circle(at, span * 0.7f, up);
    }
    // Entre el paso anterior y el último: movimiento suave a cualquier FPS.
    float a = float(std::clamp(sim / kStep - double(steps), 0.0, 1.0));
    // Arcoíris de la paleta: cada acento y, entre ellos, su tono intermedio.
    const Color& c1 = f.colors[1];
    const Color& c2 = f.colors[2];
    const Color& c3 = f.colors[3];
    const std::array<Color, 6> cols = {c1, between(c1, c2), c2, between(c2, c3), c3, between(c3, c1)};
    // Cara delantera y trasera de cada color.
    std::array<Path, 12> paths;
    for (const auto& p : pieces) {
      float x = p.px + (p.x - p.px) * a, y = p.py + (p.y - p.py) * a;
      float cf = std::cos(p.flip);
      float hw = 0.5f * p.w * std::max(0.08f, std::fabs(cf));
      float hh = 0.5f * p.h;
      hw *= grow;
      hh *= grow;
      if (sparkP > 0.002f &&
          (std::fabs(cf) > 0.9f || hashU(uint32_t(&p - pieces.data()) * 2654435761u + tick * 40503u) < 0.2f * sparkP))
        glints.push_back({x, y});
      float ca = std::cos(p.angle), sa = std::sin(p.angle);
      Path& path = paths[size_t(p.color * 2 + (cf < 0.0f ? 1 : 0))];
      path.moveTo(x + (-hw) * ca - (-hh) * sa, y + (-hw) * sa + (-hh) * ca)
          .lineTo(x + hw * ca - (-hh) * sa, y + hw * sa + (-hh) * ca)
          .lineTo(x + hw * ca - hh * sa, y + hw * sa + hh * ca)
          .lineTo(x + (-hw) * ca - hh * sa, y + (-hw) * sa + hh * ca)
          .close();
    }
    float lit = (0.9f + 0.2f * kick) * amp * (1.0f + 0.8f * kickP + 0.3f * bassP);
    for (int k = 0; k < 12; k++) {
      const Color& col = cols[size_t(k / 2)];
      float shade = (k % 2 == 0 ? 1.0f : 0.62f) * lit;
      Paint p;
      p.color = Color{std::min(1.0f, col.r * shade), std::min(1.0f, col.g * shade), std::min(1.0f, col.b * shade), 1.0f};
      c.path(paths[size_t(k)], p);
    }
    if (!glints.empty()) {
      const Color& c3 = f.colors[3];
      Paint gp;
      gp.blend = Blend::plus;
      gp.color = Color{std::min(1.0f, c3.r * 0.4f + 0.6f), std::min(1.0f, c3.g * 0.4f + 0.6f), std::min(1.0f, c3.b * 0.4f + 0.6f),
                       std::clamp(1.0f * sparkP, 0.0f, 0.95f)};
      c.points(glints, std::min(f.width, f.height) * 0.009f * m.tamano, gp);
    }
    (void)flash;
  }
};

class Visual final : public Scene {
  struct Star { float x, y, z, size, phase; int band; };
  struct Edge { int a, b; };
  std::vector<Star> stars;
  std::vector<Edge> edges;
  std::vector<float> pulseRate, pulseOffset;
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  std::array<float, 8> bands{};
  float time = 0, yaw = 0, spinVel = 0, pulsePhase = 0, push = 0, pushVel = 0;
  std::array<float, 4> rings{};  // radio, amplitud, radio, amplitud

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

  struct Projected { float x, y, depth, persp; };

  // Campo de estrellas a pantalla completa: una capa con profundidad que gira
  // suavemente; las cercanas se mueven más que las lejanas (paralaje).
  Projected project(const Star& s, float cx, float cy, float sx, float sy, float tilt) const {
    float a = std::sin(yaw) * 0.45f;
    float ca = std::cos(a), sa = std::sin(a);
    float x1 = s.x * ca + s.z * sa;
    float z1 = -s.x * sa + s.z * ca;
    float ct = std::cos(tilt), st = std::sin(tilt);
    float y2 = s.y * ct - z1 * st;
    float z2 = s.y * st + z1 * ct;
    float persp = 2.4f / (2.4f + z2);
    return {cx + x1 * sx * persp, cy - y2 * sy * persp, 0.5f - 0.5f * z2, persp};
  }

 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    stars.clear();
    edges.clear();
    // Rejilla con desplazamiento aleatorio: estrellas repartidas por toda la
    // pantalla sin huecos grandes ni montones.
    const int cols = 6, rows = 12;
    const int count = cols * rows;
    for (int i = 0; i < count; i++) {
      float gx = (float(i % cols) + 0.15f + 0.7f * rng.unit()) / float(cols);
      float gy = (float(i / cols) + 0.15f + 0.7f * rng.unit()) / float(rows);
      stars.push_back({(gx * 2.0f - 1.0f) * 1.25f, (gy * 2.0f - 1.0f) * 1.12f, rng.unit() * 2.0f - 1.0f,
                       0.6f + rng.unit() * 0.8f, rng.unit() * 6.2831853f, i % 8});
    }
    // Cada estrella se une a sus dos vecinas más cercanas.
    for (int i = 0; i < count; i++) {
      int best[2] = {-1, -1};
      float dist[2] = {1e9f, 1e9f};
      for (int j = 0; j < count; j++) {
        if (j == i) continue;
        float dx = stars[i].x - stars[j].x, dy = (stars[i].y - stars[j].y) * 1.8f;
        float dz = (stars[i].z - stars[j].z) * 0.35f;
        float d = dx * dx + dy * dy + dz * dz;
        if (d < dist[0]) { dist[1] = dist[0]; best[1] = best[0]; dist[0] = d; best[0] = j; }
        else if (d < dist[1]) { dist[1] = d; best[1] = j; }
      }
      for (int k = 0; k < 2; k++) {
        int a = std::min(i, best[k]), b = std::max(i, best[k]);
        bool exists = false;
        for (const auto& e : edges) if (e.a == a && e.b == b) exists = true;
        if (!exists) edges.push_back({a, b});
      }
    }
    pulseRate.clear();
    pulseOffset.clear();
    for (int i = 0; i < 40; i++) {
      pulseRate.push_back(0.5f + rng.unit() * 0.7f);
      pulseOffset.push_back(rng.unit());
    }
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    bands.fill(0);
    time = 0;
    yaw = rng.unit() * 6.2831853f;
    spinVel = pulsePhase = push = pushVel = 0;
    rings = {2.0f, 0.0f, 2.0f, 0.0f};
  }

  void update(const Frame& f) override {
    float dt = float(f.delta);
    const Music& m = f.music;
    bass = follow(bass, m.bass, 22.0f, 4.5f, dt);
    body = follow(body, m.body, 12.0f, 3.0f, dt);
    spark = follow(spark, m.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, m.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, m.active ? std::pow(std::clamp(m.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : m.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : m.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : m.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((m.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, m.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    if (hit > kick + 0.2f) {
      pushVel += 2.4f * hit;
      spinVel += 0.7f * hit;
      rings[2] = rings[0];
      rings[3] = rings[1];
      rings[0] = 0.0f;
      rings[1] = hit;
    }
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));

    static const int edgesSpec[9] = {0, 3, 6, 9, 13, 17, 21, 26, 31};
    for (int b = 0; b < 8; b++) {
      float v = 0;
      for (int i = edgesSpec[b]; i < edgesSpec[b + 1]; i++) v = std::max(v, m.smoothSpectrum[i]);
      bands[b] = follow(bands[b], v, 22.0f, 4.5f, dt);
    }

    // Explosión con rebote: muelle amortiguado que vuelve a la forma original.
    pushVel += (-push * 32.0f - pushVel * 6.5f) * dt;
    push += pushVel * dt;
    spinVel *= std::exp(-dt * 1.8f);
    time += dt * f.speed;
    yaw += dt * f.speed * (0.06f + 0.22f * drive) + dt * spinVel;
    pulsePhase += dt * f.speed * (0.18f + 0.6f * drive + 0.9f * kick + 0.6f * spark);
    for (int i = 0; i < 4; i += 2) {
      rings[i] += dt * (0.7f + 0.3f * drive);
      rings[i + 1] *= std::exp(-dt * 2.2f);
    }
  }

  void render(const Frame& f, Canvas& c) const override {
    float w = f.width, h = f.height;
    float s = std::min(w, h);
    float k = s / 400.0f;
    float cx = w * 0.5f, cy = h * 0.5f;
    float amp = f.intensity;
    float glow = std::clamp(f.glow, 0.0f, 2.0f);
    const Color& c1 = f.colors[1];
    const Color& c2 = f.colors[2];
    const Color& c3 = f.colors[3];

    // Fondo: nebulosa suave que respira con los graves.
    c.material("cosmos", {0, 0, w, h},
               {time, bass * amp, kick * amp, energy, flash, glow,
                f.colors[0].r, f.colors[0].g, f.colors[0].b, c1.r, c1.g, c1.b, c2.r, c2.g, c2.b});

    float tilt = 0.12f * std::sin(time * 0.13f);
    float zoom = 1.0f + 0.22f * push * amp + 0.05f * bass * amp;
    float sx = w * 0.5f * zoom, sy = h * 0.5f * zoom;
    std::vector<Projected> pts;
    pts.reserve(stars.size());
    for (const auto& st : stars) pts.push_back(project(st, cx, cy, sx, sy, tilt));

    auto alpha = [](float v) { return std::clamp(v, 0.0f, 1.0f); };
    float lineBoost = 0.7f + 0.6f * energy + 1.1f * kick * amp + 0.5f * flash;

    // Líneas de luz: lejanas y cercanas, cada grupo en tres capas de brillo.
    Path farPath, nearPath;
    for (const auto& e : edges) {
      const Projected& a = pts[e.a];
      const Projected& b = pts[e.b];
      Path& target = (a.depth + b.depth) * 0.5f > 0.5f ? nearPath : farPath;
      target.moveTo(a.x, a.y);
      target.lineTo(b.x, b.y);
    }
    for (int layer = 0; layer < 2; layer++) {
      const Path& path = layer == 0 ? farPath : nearPath;
      float depthGain = layer == 0 ? 0.55f : 1.0f;
      Paint halo;
      halo.blend = Blend::plus;
      halo.strokeCap = 1;
      halo.strokeWidth = (layer == 0 ? 10.0f : 16.0f) * k;
      halo.color = {c1.r, c1.g, c1.b, alpha(0.09f * lineBoost * depthGain * glow)};
      c.path(path, halo);
      Paint mid = halo;
      mid.strokeWidth = (layer == 0 ? 4.0f : 6.0f) * k;
      mid.color = {c2.r, c2.g, c2.b, alpha(0.2f * lineBoost * depthGain)};
      c.path(path, mid);
      Paint core = halo;
      core.strokeWidth = (layer == 0 ? 1.6f : 2.6f) * k;
      core.color = {(c1.r + c3.r) * 0.5f, (c1.g + c3.g) * 0.5f, (c1.b + c3.b) * 0.5f,
                    alpha(0.7f * lineBoost * depthGain)};
      c.path(path, core);
    }

    // Pulsos de energía que recorren las líneas.
    std::vector<Vec2> pulses;
    pulses.reserve(pulseRate.size());
    for (size_t i = 0; i < pulseRate.size() && !edges.empty(); i++) {
      const Edge& e = edges[(i * 7 + 3) % edges.size()];
      float t = pulsePhase * pulseRate[i] + pulseOffset[i];
      t -= std::floor(t);
      if (int(std::floor(pulsePhase * pulseRate[i] + pulseOffset[i])) % 2 == 1) t = 1.0f - t;
      const Projected& a = pts[e.a];
      const Projected& b = pts[e.b];
      pulses.push_back({a.x + (b.x - a.x) * t, a.y + (b.y - a.y) * t});
    }
    Paint pulseGlow;
    pulseGlow.blend = Blend::plus;
    pulseGlow.color = {c1.r, c1.g, c1.b, alpha(0.14f + 0.18f * energy + 0.3f * kick * amp)};
    c.points(pulses, 6.5f * k, pulseGlow);
    Paint pulseCore = pulseGlow;
    pulseCore.color = {1, 1, 1, alpha(0.55f + 0.3f * spark + 0.3f * kick)};
    c.points(pulses, 2.8f * k, pulseCore);

    // Estrellas: halo radial que late con su banda del espectro.
    std::vector<Vec2> cores;
    cores.reserve(stars.size());
    for (size_t i = 0; i < stars.size(); i++) {
      const Star& st = stars[i];
      const Projected& p = pts[i];
      float band = bands[st.band];
      float twinkle = 0.85f + 0.15f * std::sin(time * 2.3f + st.phase);
      float radius = (14.0f + 16.0f * st.size) * k * p.persp *
                     (1.0f + 1.1f * band * amp + 0.9f * kick * amp) * twinkle;
      float mixT = float(st.band) / 7.0f;
      Color col{c1.r + (c2.r - c1.r) * mixT, c1.g + (c2.g - c1.g) * mixT, c1.b + (c2.b - c1.b) * mixT, 1};
      float a = alpha((0.55f + 0.5f * band + 0.45f * kick * amp) * (0.55f + 0.45f * p.depth) * glow);
      Paint halo = Paint::radial({p.x, p.y}, radius,
                                 {col.opacity(a), col.opacity(a * 0.45f), col.opacity(a * 0.12f), col.opacity(0.0f)},
                                 {0.0f, 0.2f, 0.5f, 1.0f});
      halo.blend = Blend::plus;
      c.circle({p.x, p.y}, radius, halo);
      cores.push_back({p.x, p.y});
    }
    Paint coreP;
    coreP.blend = Blend::plus;
    coreP.color = {1, 1, 1, alpha(0.75f + 0.25f * kick)};
    c.points(cores, 2.8f * k, coreP);

    // Destellos en cruz en las estrellas más cercanas.
    for (size_t i = 0; i < stars.size(); i++) {
      const Projected& p = pts[i];
      if (p.depth < 0.72f) continue;
      float band = bands[stars[i].band];
      float len = (22.0f + 40.0f * band * amp + 45.0f * kick * amp) * k * p.persp;
      float a = alpha((0.35f + 0.4f * band + 0.4f * kick * amp) * (p.depth - 0.6f) * 2.5f);
      Color tint{1, 1, 1, 1};
      for (int axis = 0; axis < 2; axis++) {
        Vec2 from = axis == 0 ? Vec2{p.x - len, p.y} : Vec2{p.x, p.y - len};
        Vec2 to = axis == 0 ? Vec2{p.x + len, p.y} : Vec2{p.x, p.y + len};
        Paint spike = Paint::linear(from, to, {tint.opacity(0.0f), tint.opacity(a), tint.opacity(0.0f)},
                                    {0.0f, 0.5f, 1.0f});
        spike.blend = Blend::plus;
        spike.strokeWidth = 1.6f * k;
        Path line;
        line.moveTo(from.x, from.y);
        line.lineTo(to.x, to.y);
        c.path(line, spike);
      }
    }

    // Anillos de choque con cada golpe.
    for (int i = 0; i < 4; i += 2) {
      if (rings[i + 1] < 0.02f) continue;
      Paint ring;
      ring.blend = Blend::plus;
      ring.strokeWidth = 4.0f * k;
      float fade = rings[i + 1] * amp * std::max(0.0f, 1.0f - rings[i] / 1.2f);
      ring.color = {c3.r, c3.g, c3.b, alpha(0.75f * fade)};
      c.circle({cx, cy}, rings[i] * s * 0.6f, ring);
      Paint wide = ring;
      wide.strokeWidth = 22.0f * k;
      wide.color = {c1.r, c1.g, c1.b, alpha(0.18f * fade)};
      c.circle({cx, cy}, rings[i] * s * 0.6f, wide);
    }
  }
};

