class Visual final : public Scene {
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  // Relojes en doble precisión: la escena sin música es idéntica a 30 y 60 FPS.
  double travel = 0, clock = 0, sinceSwitch = 0;
  float boost = 0, theme = 0, themeTarget = 0;
  int beats = 0;

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    travel = rng.unit() * 20.0;
    clock = 0;
    sinceSwitch = 0;
    boost = 0;
    theme = themeTarget = rng.unit() < 0.5f ? 0.0f : 1.0f;
    beats = 0;
  }

  void update(const Frame& f) override {
    float dt = float(f.delta);
    const Music& m = f.music;
    bass = follow(bass, m.bass, 22.0f, 4.5f, dt);
    body = follow(body, m.body, 12.0f, 3.0f, dt);
    spark = follow(spark, m.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, m.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, m.active ? std::pow(std::clamp(m.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : m.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : m.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : m.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((m.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, m.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    if (hit > kick + 0.2f) {
      beats++;
      boost = std::max(boost, hit);
      if (beats % 8 == 0) {
        themeTarget = 1.0f - themeTarget;
        sinceSwitch = 0;
      }
    }
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    boost *= std::exp(-dt * 3.0f);
    sinceSwitch += f.delta;
    if (!m.active && sinceSwitch > 10.0) {
      themeTarget = 1.0f - themeTarget;
      sinceSwitch = 0;
    }
    theme += (themeTarget - theme) * (1.0f - std::exp(-dt * 2.5f));
    travel += f.delta * f.speed * (0.7 + 1.4 * drive + 2.0 * boost);
    clock += f.delta * f.speed;
  }

  void render(const Frame& f, Canvas& c) const override {
    float amp = f.intensity;
    std::vector<float> u;
    u.reserve(20);
    u.insert(u.end(), {float(std::fmod(travel, 1000.0)), bass * amp, kick * amp, energy});
    u.insert(u.end(), {theme, f.glow, spark * amp, flash * amp});
    for (int i = 0; i < 4; i++) u.insert(u.end(), {f.colors[i].r, f.colors[i].g, f.colors[i].b});
    c.material("neon_corridor", {0, 0, f.width, f.height}, u);
  }
};

shaderSources.neon_corridor:
#version 460 core
#include <flutter/runtime_effect.glsl>
uniform vec2 uSize;
uniform vec4 uA;   // avance, graves, golpe, energía
uniform vec4 uB;   // tema (0 fuego, 1 hielo), glow, agudos, destello
uniform vec3 uC0;
uniform vec3 uC1;
uniform vec3 uC2;
uniform vec3 uC3;
out vec4 fragColor;

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash12(i), hash12(i + vec2(1.0, 0.0)), u.x),
             mix(hash12(i + vec2(0.0, 1.0)), hash12(i + vec2(1.0, 1.0)), u.x), u.y);
}

void main() {
  vec2 frag = FlutterFragCoord().xy;
  float scale = min(uSize.x, uSize.y);
  vec2 p = (frag - 0.5 * uSize) / scale;
  float travel = uA.x;
  float kick = uA.z;
  float theme = uB.x;
  // Colores del tema: fuego (rojo, amarillo) o hielo (blanco, azul).
  vec3 wallCol = mix(uC1, mix(uC3, vec3(1.0), 0.35), theme);
  vec3 frameCol = mix(uC2, vec3(0.92, 0.97, 1.0), theme);
  vec3 endCol = mix(vec3(0.6, 0.75, 1.0), vec3(1.0, 0.2, 0.15), theme);

  // Corredor cuadrado: la distancia a la pared da la profundidad.
  float sq = max(abs(p.x), abs(p.y)) + 1e-4;
  float z = 0.32 / sq;
  float depth = z + travel;
  bool side = abs(p.x) > abs(p.y);
  float v = side ? p.y / abs(p.x) : p.x / abs(p.y);
  float wallId = side ? (p.x > 0.0 ? 0.0 : 1.0) : (p.y > 0.0 ? 2.0 : 3.0);

  // Paredes de metal líquido: burbujas y agujeros con relieve reflejado.
  vec2 w = vec2(v * 4.5 + wallId * 7.3, depth * 3.2);
  float n = noise(w) * 0.65 + noise(w * 2.3 + 4.0) * 0.35;
  float nx = noise(w + vec2(0.05, 0.0)) * 0.65 + noise(w * 2.3 + 4.0 + vec2(0.115, 0.0)) * 0.35;
  float ny = noise(w + vec2(0.0, 0.05)) * 0.65 + noise(w * 2.3 + 4.0 + vec2(0.0, 0.115)) * 0.35;
  vec2 grad = vec2(nx - n, ny - n) * 20.0;
  float holes = smoothstep(0.45, 0.4, n);
  float spec = pow(max(0.0, 1.0 - length(grad - vec2(0.4, 0.6)) * 0.9), 6.0);
  float liquid = (0.15 + 0.85 * smoothstep(0.45, 0.85, n)) * (1.0 - holes);
  float lit = 0.18 + 0.75 * uA.w + 0.35 * uA.y;
  vec3 col = wallCol * liquid * liquid * lit * 0.9 + mix(wallCol, vec3(1.0), 0.5) * spec * (1.0 - holes) * (0.25 + 0.9 * lit);

  // Marcos de neón que pasan, con un marco fino entre cada dos.
  float fz = fract(depth * 0.5);
  float dz = min(fz, 1.0 - fz) / 0.5;
  float frame = exp(-dz * z * 10.0) * 1.4;
  float fz2 = fract(depth * 0.5 + 0.5);
  float frame2 = exp(-min(fz2, 1.0 - fz2) / 0.5 * z * 26.0) * 0.5;
  col += frameCol * (frame + frame2) * (1.0 + 1.6 * kick) * uB.y;

  // Niebla hacia el fondo y puerta luminosa al final.
  float fog = exp(-z * 0.16);
  col *= fog;
  float endSq = abs(sq - 0.045);
  col += endCol * exp(-endSq * 260.0) * (0.8 + 0.6 * kick);
  col *= smoothstep(0.02, 0.05, sq) * 0.85 + 0.15;

  // Partículas rojas que flotan en el aire.
  vec2 pc = floor(frag / scale * 22.0);
  float ph = hash12(pc);
  vec2 off = fract(frag / scale * 22.0) - 0.5 - (vec2(hash12(pc + 3.1), hash12(pc + 7.7)) - 0.5) * 0.6;
  float mote = step(0.9, ph) * exp(-dot(off, off) * 60.0) * (0.5 + 0.5 * sin(travel * 3.0 + ph * 40.0));
  col += vec3(1.0, 0.12, 0.08) * mote * (0.7 + 0.8 * uB.z);
  col += frameCol * uB.w * 0.06;

  float peak = max(col.r, max(col.g, col.b));
  if (peak > 0.85) {
    float e = (peak - 0.85) / 0.15;
    col *= (0.85 + 0.15 * e / (1.0 + e)) / peak;
  }
  col += (hash12(frag) - 0.5) / 255.0;
  fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

visuals.nativeSource:
class Visual final : public Scene {
  static constexpr int kCrystals = 4;
  float bass = 0, spark = 0, slowBass = 0;
  float kick = 0, flash = 0, ripplePower = 0;
  // Relojes en doble precisión: sin música es idéntico a 30 y 60 FPS.
  double clock = 0, rippleAge = 100;
  std::array<float, kCrystals> cx{}, cy{}, csize{}, cangle{}, cdir{};

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    bass = spark = slowBass = kick = flash = ripplePower = 0;
    clock = double(rng.unit()) * 30.0;
    rippleAge = 100;
    const float bx[kCrystals] = {-0.16f, 0.2f, -0.18f, 0.18f};
    const float by[kCrystals] = {-0.55f, -0.12f, 0.3f, 0.66f};
    for (int i = 0; i < kCrystals; i++) {
      cx[size_t(i)] = bx[i] + (rng.unit() - 0.5f) * 0.08f;
      cy[size_t(i)] = by[i] + (rng.unit() - 0.5f) * 0.08f;
      csize[size_t(i)] = 0.27f + 0.1f * rng.unit();
      cangle[size_t(i)] = (rng.unit() - 0.5f) * 0.9f;
      cdir[size_t(i)] = rng.unit() < 0.5f ? -1.0f : 1.0f;
    }
  }

  void update(const Frame& f) override {
    const float dt = float(f.delta);
    const Music& mu = f.music;
    bass = follow(bass, mu.bass, 22.0f, 4.5f, dt);
    spark = follow(spark, mu.spark, 30.0f, 7.0f, dt);
    float hit = 0, fl = 0;
    for (const auto& e : mu.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : mu.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : mu.events[3]) fl = std::max(fl, e.strength);
    const float onset = std::clamp((mu.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, mu.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    rippleAge += f.delta;
    if (hit > kick + 0.2f) {
      rippleAge = 0;
      ripplePower = hit;
    }
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    clock += f.delta * f.speed;
  }

  void render(const Frame& f, Canvas& c) const override {
    auto g = glide(f);
    const float amp = f.intensity;
    const float t = float(std::fmod(clock, 10000.0));
    const float wQuieto = g.giro.weight(0), wRota = g.giro.weight(1), wFlota = g.giro.weight(2);
    // Golpes: una ola de color ancha y luminosa sale del centro de cada cristal
    // y se apaga despacio mientras lo cruza.
    const float wave = g.pulso.weight(0) * ripplePower * amp * float(std::exp(-rippleAge * 1.1));
    const float waveR = float(std::min(rippleAge, 10.0)) * 1.4f;
    // Graves: los cristales crecen y sus terrazas brillan más.
    const float graves = std::min(bass * amp, 1.0f) * g.pulso.weight(1);
    const float grow = 1.0f + 0.2f * graves;
    std::vector<float> u;
    u.reserve(48);
    u.insert(u.end(), {t, std::min(bass * amp, 1.5f), wave, std::min(spark * amp, 1.0f) * g.pulso.weight(2)});
    // Detalle: más finas las terrazas con más detalle.
    u.insert(u.end(), {g.escalones * (0.75f + 0.25f * f.detail), std::clamp(g.espiral, 0.0f, 1.0f), std::clamp(g.reflejo, 0.0f, 1.0f), f.glow});
    u.insert(u.end(), {waveR, std::min(flash * amp, 1.0f), graves, 0.0f});
    for (int i = 0; i < kCrystals; i++) {
      const float fi = float(i);
      const float rot = cangle[size_t(i)] + float(clock) * 0.12f * cdir[size_t(i)];
      const float bob = cangle[size_t(i)] + 0.15f * std::sin(t * 0.2f + fi);
      const float a = wQuieto * cangle[size_t(i)] + wRota * rot + wFlota * bob;
      const float x = cx[size_t(i)] + wFlota * 0.03f * std::sin(t * 0.4f + fi);
      const float y = cy[size_t(i)] + wFlota * 0.04f * std::sin(t * 0.33f + fi * 2.0f);
      u.insert(u.end(), {x, y, csize[size_t(i)] * grow, a});
    }
    for (int i = 0; i < 4; i++) u.insert(u.end(), {f.colors[size_t(i)].r, f.colors[size_t(i)].g, f.colors[size_t(i)].b});
    c.material("bismuth", {0, 0, f.width, f.height}, u);
  }
};

shaderSources.bismuth:
#version 460 core
#include <flutter/runtime_effect.glsl>
uniform vec2 uSize;
uniform vec4 uA;   // tiempo, graves, ola de golpe, destellos
uniform vec4 uB;   // escalones, espiral, reflejo, glow
uniform vec4 uE;   // radio de la ola, destello, graves
uniform vec4 uK0;  // cristales: x, y, tamaño, ángulo
uniform vec4 uK1;
uniform vec4 uK2;
uniform vec4 uK3;
uniform vec3 uC0;
uniform vec3 uC1;
uniform vec3 uC2;
uniform vec3 uC3;
out vec4 fragColor;

float sq(float x) {
  return x * x;
}

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

// Color de la capa de óxido según su grosor: recorre la paleta y un acero.
vec3 film(float tau) {
  vec3 steel = mix(uC1, uC3, 0.5) * 0.35;
  float s = fract(tau) * 4.0;
  if (s < 1.0) return mix(uC1, uC2, smoothstep(0.0, 1.0, s));
  if (s < 2.0) return mix(uC2, uC3, smoothstep(1.0, 2.0, s));
  if (s < 3.0) return mix(uC3, steel, smoothstep(2.0, 3.0, s));
  return mix(steel, uC1, smoothstep(3.0, 4.0, s));
}

// Un cristal en p: nivel de terraza, cara, distancia al centro y si está dentro.
vec4 crystal(vec2 p, vec4 K, out vec2 inward) {
  vec2 d = p - K.xy;
  float cs = cos(K.w);
  float sn = sin(K.w);
  vec2 q = vec2(cs * d.x + sn * d.y, -sn * d.x + cs * d.y) / K.z;
  float dC = max(abs(q.x), abs(q.y));
  vec2 n = abs(q.x) > abs(q.y) ? vec2(-sign(q.x), 0.0) : vec2(0.0, -sign(q.y));
  // La pared de cada escalón mira hacia el centro.
  inward = vec2(cs * n.x - sn * n.y, sn * n.x + cs * n.y);
  if (dC > 1.0) return vec4(-1.0, 0.0, dC, 0.0);
  float ang = atan(q.y, q.x) / 6.2831853 + 0.5;
  float level = dC * uB.x + uB.y * ang;
  return vec4(level, 0.0, dC, 1.0);
}

void main() {
  vec2 frag = FlutterFragCoord().xy;
  float scale = min(uSize.x, uSize.y);
  vec2 p = (frag - 0.5 * uSize) / scale;
  float t = uA.x;
  vec2 n0;
  vec2 n1;
  vec2 n2;
  vec2 n3;
  vec4 a0 = crystal(p, uK0, n0);
  vec4 a1 = crystal(p, uK1, n1);
  vec4 a2 = crystal(p, uK2, n2);
  vec4 a3 = crystal(p, uK3, n3);
  // El escalón más alto tapa a los demás (los bordes de fuera son altos).
  float h0 = a0.w > 0.5 ? floor(a0.x) / uB.x + 0.0 : -9.0;
  float h1 = a1.w > 0.5 ? floor(a1.x) / uB.x + 0.15 : -9.0;
  float h2 = a2.w > 0.5 ? floor(a2.x) / uB.x + 0.3 : -9.0;
  float h3 = a3.w > 0.5 ? floor(a3.x) / uB.x + 0.45 : -9.0;
  vec4 a = a0;
  vec2 inward = n0;
  float idx = 0.0;
  float best = h0;
  if (h1 > best) { best = h1; a = a1; inward = n1; idx = 1.0; }
  if (h2 > best) { best = h2; a = a2; inward = n2; idx = 2.0; }
  if (h3 > best) { best = h3; a = a3; inward = n3; idx = 3.0; }
  // Fondo de terciopelo oscuro con la sombra de los cristales.
  vec3 col = uC0 * (1.0 + 0.4 * (1.0 - length(p * vec2(0.9, 0.6))));
  float nearest = min(min(a0.z, a1.z), min(a2.z, a3.z));
  col *= 1.0 - 0.6 * smoothstep(1.12, 1.0, nearest);
  if (best > -5.0) {
    float k = floor(a.x);
    float u = fract(a.x);
    float dC = a.z;
    float tau = k * 0.13 + dC * 0.25 + idx * 0.31 + t * 0.03 + uA.y * 0.15;
    // Golpes: la ola es una banda ancha que cambia el color a su paso.
    float band = exp(-sq((dC - uE.x) / 0.22));
    tau += min(uA.z, 1.2) * band * 0.5;
    vec2 toLight = normalize(vec2(-0.6, -0.8));
    float lit = max(dot(inward, toLight), 0.0);
    // Reflejos metálicos que recorren las terrazas.
    float sheen = 0.5 + 0.5 * sin(dot(p, vec2(0.8, 0.6)) * 7.0 - t * 0.8 + k * 0.5);
    float wall = 1.0 - smoothstep(0.14, 0.18, u);
    vec3 tread = film(tau) * (0.5 + 0.35 * sheen + 0.6 * uB.z * pow(sheen, 8.0));
    vec3 riser = film(tau + 0.08) * (0.22 + 0.95 * lit);
    vec3 c = mix(tread, riser, wall);
    float edge = exp(-sq((u - 0.17) / 0.02));
    c += mix(uC3, vec3(1.0), 0.3) * edge * (0.25 + 0.5 * lit) * (0.6 + 0.4 * uB.w);
    c *= 1.0 - 0.6 * exp(-sq(u / 0.025));
    // Destellos: las aristas y las terrazas centellean con los agudos.
    float glint = step(0.86 - 0.08 * uA.w, hash12(floor(p * 90.0) + floor(t * 8.0)));
    c += uC3 * edge * glint * uA.w * 2.0;
    float speck = step(0.95, hash12(floor(p * 140.0) + floor(t * 11.0) + 17.0));
    c += uC3 * speck * uA.w * 0.45 * (1.0 - wall);
    // Golpes: la ola ilumina los escalones y enciende las aristas a su paso.
    float ring = min(uA.z, 1.0) * band;
    c += uC3 * edge * ring * 0.8;
    // Graves: las terrazas brillan más.
    c *= 1.0 + 0.5 * ring + 0.22 * uE.z;
    // Borde exterior del cristal.
    c *= smoothstep(1.0, 0.985, dC) * 0.6 + 0.4;
    col = c;
  }
  col *= 1.0 + 0.12 * uE.y;
  col *= 1.0 - 0.25 * smoothstep(0.7, 1.5, length(p * vec2(0.9, 0.65)));
  float peak = max(col.r, max(col.g, col.b));
  if (peak > 0.9) col *= (0.9 + 0.1 * (peak - 0.9) / (peak - 0.8)) / peak;
  col += (hash12(frag) - 0.5) / 255.0;
  fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

