class Visual final : public Scene {
  static constexpr int kMax = 10;
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  std::array<float, kMax> bands{};
  // Relojes en doble precisión: la escena sin música es idéntica a 30 y 60 FPS.
  double clock = 0, yaw = 0, sinceAnim = 0, sinceHit = 100;
  float hitPower = 0;
  int beats = 0, autoAnim = 0;

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

  static float hash(int a, int b) {
    uint32_t x = uint32_t(a) * 374761393u + uint32_t(b) * 668265263u;
    x = (x ^ (x >> 13)) * 1274126177u;
    return float(x ^ (x >> 16)) / 4294967296.0f;
  }

 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    bands.fill(0);
    clock = rng.unit() * 20.0;
    yaw = rng.unit() * 6.28;
    sinceAnim = 0;
    sinceHit = 100;
    hitPower = 0;
    beats = 0;
    autoAnim = 0;
  }

  void update(const Frame& f) override {
    auto m = modifiers(f);
    float dt = float(f.delta);
    const Music& mu = f.music;
    bass = follow(bass, mu.bass, 22.0f, 4.5f, dt);
    body = follow(body, mu.body, 12.0f, 3.0f, dt);
    spark = follow(spark, mu.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, mu.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, mu.active ? std::pow(std::clamp(mu.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);
    int n = std::clamp(m.tamano, 4, kMax);
    for (int i = 0; i < n; i++) {
      int b0 = i * 28 / n, b1 = std::max(b0 + 1, (i + 1) * 28 / n);
      float v = 0;
      for (int b = b0; b < b1; b++) v = std::max(v, mu.smoothSpectrum[size_t(b)]);
      bands[size_t(i)] = follow(bands[size_t(i)], v, 20.0f, 5.0f, dt);
    }

    float hit = 0, fl = 0;
    for (const auto& e : mu.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : mu.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : mu.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((mu.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, mu.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    sinceAnim += f.delta;
    sinceHit += f.delta;
    if (hit > kick + 0.2f) {
      sinceHit = 0;
      hitPower = hit;
      if (++beats % 8 == 0) {
        autoAnim = (autoAnim + 1) % 5;
        sinceAnim = 0;
      }
    }
    if (!mu.active) {
      // Sin música: una explosión cada 1,6 s y otra animación cada 9 s.
      if (sinceHit > 1.6) {
        sinceHit -= 1.6;
        hitPower = 0.8f;
      }
      if (sinceAnim > 9.0) {
        sinceAnim -= 9.0;
        autoAnim = (autoAnim + 1) % 5;
      }
    }
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    clock += f.delta * f.speed * (1.0 + 0.8 * drive);
    yaw += f.delta * f.speed * m.giro * (0.3 + 0.5 * drive + 0.6 * bass);
  }

  void render(const Frame& f, Canvas& c) const override {
    auto m = modifiers(f);
    float amp = f.intensity;
    const Color& bg = f.colors[0];
    c.rect({0, 0, f.width, f.height}, Paint::radial({f.width * 0.5f, f.height * 0.5f}, std::max(f.width, f.height) * 0.7f,
                                                   {Color{std::min(1.0f, bg.r + 0.06f), std::min(1.0f, bg.g + 0.03f), std::min(1.0f, bg.b + 0.05f), 1.0f},
                                                    Color{bg.r, bg.g, bg.b, 1.0f}}));
    int n = std::clamp(m.tamano, 4, kMax);
    int mode = m.animacion == 0 ? autoAnim : m.animacion - 1;
    float t = float(std::fmod(clock, 1000.0));
    float side = std::min(f.width, f.height);
    float px = side / 400.0f;
    float cy = float(std::cos(yaw)), sy = float(std::sin(yaw));
    float tilt = 0.45f + 0.12f * float(std::sin(clock * 0.3));
    float cp = std::cos(tilt), sp = std::sin(tilt);
    float scale = side * 0.36f;
    float boom = sinceHit < 2.0 ? float(sinceHit) * 1.9f : 9.0f;
    float boomPower = sinceHit < 2.0 ? hitPower * float(1.0 - sinceHit / 2.0) : 0.0f;
    // Grupos por brillo (4 niveles) y color (5 tonos).
    std::array<std::vector<Vec2>, 20> lit;
    std::vector<Vec2> off;
    off.reserve(size_t(n * n * n));
    for (auto& g : lit) g.reserve(size_t(n * n * n / 4));
    for (int ix = 0; ix < n; ix++) {
      for (int iy = 0; iy < n; iy++) {
        for (int iz = 0; iz < n; iz++) {
          float x = float(ix) / float(n - 1) * 2.0f - 1.0f;
          float y = float(iy) / float(n - 1) * 2.0f - 1.0f;  // y = -1 abajo, 1 arriba
          float z = float(iz) / float(n - 1) * 2.0f - 1.0f;
          float v = 0;
          switch (mode) {
            case 0: {  // Lluvia: gotas que caen por cada columna.
              float h = hash(ix * 31 + iz, 7);
              float speed = 0.5f + 0.8f * hash(ix, iz * 17);
              float drop = 1.0f - 2.0f * float(std::fmod(double(t) * speed * (1.0 + 1.2 * double(drive)) + double(h) * 9.0, 1.4)) / 1.4f;
              float d = y - drop;
              v = d >= 0.0f ? std::exp(-d * 5.0f) : std::exp(d * 18.0f);
              v *= 0.6f + 0.4f * hash(ix + 3, iz + 5);
              break;
            }
            case 1: {  // Ondas: una superficie que se ondula desde el centro.
              float r = std::sqrt(x * x + z * z);
              float s = std::sin(r * 3.2f - t * 2.6f) * (0.45f + 0.35f * bass) + 0.3f * std::sin(x * 2.0f + t);
              v = std::exp(-std::fabs(y - s) * 5.5f);
              break;
            }
            case 2: {  // Espectro: barras en volumen, una banda por fila.
              float level = mu_level(ix, iz, n, t);
              float top = -1.0f + 2.0f * level;
              v = y <= top ? 0.55f + 0.45f * (y + 1.0f) / 2.0f : std::exp(-(y - top) * 9.0f) * 0.4f;
              break;
            }
            case 3: {  // Explosión: una cáscara esférica que crece.
              float r = std::sqrt(x * x + y * y + z * z);
              v = std::exp(-std::fabs(r - boom) * 5.0f) * (0.35f + boomPower) + std::exp(-r * 4.0f) * (0.3f + 0.6f * bass);
              break;
            }
            default: {  // Espiral: una hélice que sube girando.
              float ang = std::atan2(z, x);
              float r = std::sqrt(x * x + z * z);
              float ph = ang / 6.2831853f - y * 0.45f + t * 0.4f;
              float arm = std::fabs(ph * 2.0f - std::floor(ph * 2.0f + 0.5f));
              v = std::exp(-arm * 9.0f) * std::exp(-std::fabs(r - 0.75f) * 3.0f);
              break;
            }
          }
          v = std::clamp(v * (0.85f + 0.4f * kick), 0.0f, 1.0f);
          float rx = x * cy + z * sy, rz = -x * sy + z * cy;
          float ry = y * cp - rz * sp;
          float rzz = y * sp + rz * cp;
          float persp = 2.6f / (3.4f + rzz);
          Vec2 q{f.width * 0.5f + rx * persp * scale, f.height * 0.5f - ry * persp * scale};
          if (v < 0.12f) {
            off.push_back(q);
            continue;
          }
          int level = std::min(3, int(v * 4.0f));
          int col = std::clamp(int((y * 0.5f + 0.5f) * 4.99f), 0, 4);
          lit[size_t(level * 5 + col)].push_back(q);
        }
      }
    }
    float cell = scale * 2.0f / float(n - 1);
    if (m.apagados) {
      Paint dim;
      dim.color = Color{0.35f, 0.3f, 0.32f, 0.35f};
      c.points(off, std::max(0.8f, cell * 0.06f), dim);
    }
    std::array<Color, 5> tones = {f.colors[1],
                                  Color{(f.colors[1].r + f.colors[2].r) * 0.5f, (f.colors[1].g + f.colors[2].g) * 0.5f, (f.colors[1].b + f.colors[2].b) * 0.5f, 1.0f},
                                  f.colors[2],
                                  Color{(f.colors[2].r + f.colors[3].r) * 0.5f, (f.colors[2].g + f.colors[3].g) * 0.5f, (f.colors[2].b + f.colors[3].b) * 0.5f, 1.0f},
                                  f.colors[3]};
    for (int level = 0; level < 4; level++) {
      float b = (0.35f + 0.22f * float(level)) * amp;
      for (int k = 0; k < 5; k++) {
        const auto& pts = lit[size_t(level * 5 + k)];
        if (pts.empty()) continue;
        Paint halo;
        halo.blend = Blend::plus;
        halo.color = tones[size_t(k)].opacity(std::clamp(b * 0.28f * f.glow, 0.0f, 1.0f));
        c.points(pts, cell * (0.32f + 0.08f * float(level)), halo);
        Paint core;
        core.blend = Blend::plus;
        core.color = tones[size_t(k)].opacity(std::clamp(b * 1.1f, 0.0f, 1.0f));
        c.points(pts, std::max(1.2f * px, cell * (0.1f + 0.025f * float(level))), core);
      }
    }
    if (flash > 0.01f) {
      Paint fl;
      fl.blend = Blend::plus;
      fl.color = f.colors[2].opacity(std::clamp(flash * 0.05f * amp, 0.0f, 1.0f));
      c.rect({0, 0, f.width, f.height}, fl);
    }
  }

 private:
  // Nivel de la barra de espectro de una columna (con música) o una
  // ecualización de demostración (sin música).
  float mu_level(int ix, int iz, int n, float t) const {
    float band = bands[size_t(std::min(ix, n - 1))];
    float depth = 1.0f - 0.12f * float(std::abs(iz - n / 2));
    float idle = 0.35f + 0.25f * std::sin(t * 2.1f + float(ix) * 0.9f) * std::cos(t * 1.3f + float(iz) * 0.7f);
    float v = std::max(band * 1.3f, energy > 0.02f ? 0.0f : idle);
    return std::clamp(v * depth, 0.0f, 1.0f);
  }
};

class Visual final : public Scene {
  static constexpr int kMoves = 20;
  static constexpr int kSlots = kMoves * 2 + 6;
  struct Cubie { int p[3]; int o[3]; int r[9]; };
  struct Move { int axis, layer, dir; };
  struct Quad { Vec2 v[4]; float depth; Color color; bool sticker; float light; };
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  // Relojes en doble precisión: la escena sin música es idéntica a 30 y 60 FPS.
  double moveClock = 0, yaw = 0, clock = 0;
  int64_t applied = 0;
  int cycle = -1;
  uint32_t baseSeed = 1;
  std::array<Cubie, 27> cubes{};
  std::array<Move, kMoves> scramble{};
  mutable std::vector<Quad> quads;

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

  static void rot90(int axis, int dir, int& x, int& y, int& z) {
    int a = x, b = y, c = z;
    if (axis == 0) { if (dir > 0) { y = -c; z = b; } else { y = c; z = -b; } }
    else if (axis == 1) { if (dir > 0) { x = c; z = -a; } else { x = -c; z = a; } }
    else { if (dir > 0) { x = -b; y = a; } else { x = b; y = -a; } }
  }

  void solved() {
    int k = 0;
    for (int x = -1; x <= 1; x++) {
      for (int y = -1; y <= 1; y++) {
        for (int z = -1; z <= 1; z++) {
          Cubie& c = cubes[size_t(k++)];
          c.p[0] = c.o[0] = x;
          c.p[1] = c.o[1] = y;
          c.p[2] = c.o[2] = z;
          for (int i = 0; i < 9; i++) c.r[i] = (i % 4 == 0) ? 1 : 0;
        }
      }
    }
  }

  void apply(const Move& mv) {
    for (auto& c : cubes) {
      if (c.p[mv.axis] != mv.layer) continue;
      rot90(mv.axis, mv.dir, c.p[0], c.p[1], c.p[2]);
      // Las columnas de la orientación son los ejes propios de la pieza.
      for (int col = 0; col < 3; col++) rot90(mv.axis, mv.dir, c.r[col], c.r[3 + col], c.r[6 + col]);
    }
  }

  void newCycle(int index) {
    cycle = index;
    solved();
    Random rng(baseSeed + uint32_t(index) * 7919u);
    int last = -1;
    for (int i = 0; i < kMoves; i++) {
      int axis;
      do {
        axis = std::min(int(rng.unit() * 3.0f), 2);
      } while (axis == last);
      last = axis;
      scramble[size_t(i)] = {axis, rng.unit() < 0.5f ? -1 : 1, rng.unit() < 0.5f ? -1 : 1};
    }
  }

  // Giro de la casilla s del ciclo: mezcla, pausa, resolución, pausa.
  bool slotMove(int s, Move& mv) const {
    if (s < kMoves) {
      mv = scramble[size_t(s)];
      return true;
    }
    if (s >= kMoves + 2 && s < kMoves * 2 + 2) {
      Move m = scramble[size_t(kMoves - 1 - (s - kMoves - 2))];
      mv = {m.axis, m.layer, -m.dir};
      return true;
    }
    return false;
  }

  static Color faceColor(int axis, int sign) {
    int k = axis * 2 + (sign > 0 ? 0 : 1);
    std::array<Color, 6> pal = {Color{0.92f, 0.08f, 0.1f, 1.0f}, Color{1.0f, 0.5f, 0.0f, 1.0f}, Color{0.96f, 0.96f, 0.93f, 1.0f},
                                Color{1.0f, 0.86f, 0.0f, 1.0f},  Color{0.05f, 0.78f, 0.25f, 1.0f}, Color{0.1f, 0.32f, 1.0f, 1.0f}};
    return pal[size_t(k)];
  }

 public:
  void reset(uint32_t seed) override {
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    baseSeed = seed;
    moveClock = 0;
    yaw = 0.6;
    clock = 0;
    applied = 0;
    newCycle(0);
    quads.reserve(240);
  }

  void update(const Frame& f) override {
    auto m = modifiers(f);
    float dt = float(f.delta);
    const Music& mu = f.music;
    bass = follow(bass, mu.bass, 22.0f, 4.5f, dt);
    body = follow(body, mu.body, 12.0f, 3.0f, dt);
    spark = follow(spark, mu.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, mu.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, mu.active ? std::pow(std::clamp(mu.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : mu.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : mu.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : mu.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((mu.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, mu.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    clock += f.delta * f.speed;
    yaw += f.delta * f.speed * m.giro * (0.35 + 0.5 * drive + 1.5 * kick);
    // Un giro de capa cada 0,45 s a velocidad 1.
    moveClock += f.delta * f.speed * m.velocidad * (2.2 + 2.0 * drive);
    int64_t target = int64_t(std::floor(moveClock + 1e-9));
    while (applied < target) {
      int s = int(applied % kSlots);
      Move mv;
      if (slotMove(s, mv)) apply(mv);
      applied++;
      if (applied % kSlots == 0) newCycle(int(applied / kSlots));
    }
  }

  void render(const Frame& f, Canvas& c) const override {
    auto m = modifiers(f);
    auto g = glide(f);
    float amp = f.intensity;
    const Color& bg = f.colors[0];
    c.rect({0, 0, f.width, f.height}, Paint::radial({f.width * 0.5f, f.height * 0.45f}, std::max(f.width, f.height) * 0.7f,
                                                   {Color{std::min(1.0f, bg.r + 0.08f), std::min(1.0f, bg.g + 0.06f), std::min(1.0f, bg.b + 0.09f), 1.0f},
                                                    Color{bg.r, bg.g, bg.b, 1.0f}}));
    int s = int(applied % kSlots);
    // Avance del giro actual medido desde el último giro aplicado en update:
    // así un final justo en el borde de un giro es igual a 30 y a 60 FPS.
    float prog = float(std::clamp(moveClock - double(applied), 0.0, 1.0));
    float anim = std::clamp(prog / 0.7f, 0.0f, 1.0f);
    anim = anim * anim * (3.0f - 2.0f * anim);
    Move mv{0, 9, 1};
    bool moving = slotMove(s, mv);
    float theta = moving ? float(mv.dir) * anim * 1.5707963f : 0.0f;
    float ct = std::cos(theta), st = std::sin(theta);
    auto partial = [&](float& x, float& y, float& z) {
      float a = x, b = y, cc = z;
      if (mv.axis == 0) { y = b * ct - cc * st; z = b * st + cc * ct; }
      else if (mv.axis == 1) { x = a * ct + cc * st; z = -a * st + cc * ct; }
      else { x = a * ct - b * st; y = a * st + b * ct; }
    };
    float cy = float(std::cos(yaw)), sy = float(std::sin(yaw));
    float pitch = -0.55f - 0.12f * float(std::sin(clock * 0.37));
    float cp = std::cos(pitch), sp = std::sin(pitch);
    float side = std::min(f.width, f.height);
    // Piezas: juntas (cubo macizo), separadas (huecos entre cubitos) o
    // flotantes (cubitos sueltos que levitan). Los pesos funden el cambio.
    const float wOpen = g.estilo.weight(1), wFloat = g.estilo.weight(2);
    const float gap = wOpen * 0.32f + wFloat * 0.8f;
    // Con piezas abiertas, los graves y cada golpe las empujan hacia fuera.
    const float push = (wOpen + wFloat) * std::min((0.06f * bass + 0.12f * kick) * amp, 0.25f);
    // El cubo abierto ocupa el mismo lugar que el macizo: las piezas se achican.
    float scale = side * 0.24f * (1.0f + 0.04f * bass * amp) * (1.47f / (1.47f + gap));
    auto toCam = [&](float x, float y, float z, float& X, float& Y, float& Z) {
      float rx = x * cy + z * sy, rz = -x * sy + z * cy;
      X = rx;
      Y = y * cp - rz * sp;
      Z = y * sp + rz * cp;
    };
    auto project = [&](float X, float Y, float Z) {
      float k = 7.0f / (Z + 9.0f);
      return Vec2{f.width * 0.5f + X * k * scale, f.height * 0.5f - Y * k * scale};
    };
    // Celebración: destello al quedar resuelto.
    bool done = s >= kMoves * 2 + 2;
    float celebrate = done ? std::exp(-float(s - (kMoves * 2 + 2)) * 0.6f - prog * 0.6f) : 0.0f;
    quads.clear();
    const float h = 0.47f;
    for (const auto& cu : cubes) {
      bool inLayer = moving && cu.p[mv.axis] == mv.layer;
      // Cada pieza conserva su fase de flotación aunque cambie de sitio.
      const float spread = 1.0f + gap + push;
      const float lift = wFloat * 0.16f * float(std::sin(clock * 1.3 + 1.7 * cu.o[0] + 2.9 * cu.o[1] + 4.3 * cu.o[2]));
      for (int ax = 0; ax < 3; ax++) {
        for (int sg = -1; sg <= 1; sg += 2) {
          // Normal y esquinas en el espacio propio de la pieza.
          for (int pass = 0; pass < 2; pass++) {
            bool sticker = pass == 1;
            if (sticker && cu.o[ax] != sg) continue;
            float inset = sticker ? 0.39f : h, out = sticker ? h + 0.004f : h;
            int a1 = (ax + 1) % 3, a2 = (ax + 2) % 3;
            std::array<float, 3> corner[4];
            float sx[4] = {-1, 1, 1, -1}, sy2[4] = {-1, -1, 1, 1};
            Quad q;
            float zs = 0;
            float nX = 0, nY = 0, nZ = 0;
            {
              float nl[3] = {0, 0, 0};
              nl[ax] = float(sg);
              float wx = float(cu.r[0]) * nl[0] + float(cu.r[1]) * nl[1] + float(cu.r[2]) * nl[2];
              float wy = float(cu.r[3]) * nl[0] + float(cu.r[4]) * nl[1] + float(cu.r[5]) * nl[2];
              float wz = float(cu.r[6]) * nl[0] + float(cu.r[7]) * nl[1] + float(cu.r[8]) * nl[2];
              if (inLayer) partial(wx, wy, wz);
              toCam(wx, wy, wz, nX, nY, nZ);
            }
            float cxw = 0, cyw = 0, czw = 0;
            for (int k = 0; k < 4; k++) {
              float l[3];
              l[ax] = float(sg) * out;
              l[a1] = sx[k] * inset;
              l[a2] = sy2[k] * inset;
              float wx = float(cu.r[0]) * l[0] + float(cu.r[1]) * l[1] + float(cu.r[2]) * l[2] + float(cu.p[0]) * spread;
              float wy = float(cu.r[3]) * l[0] + float(cu.r[4]) * l[1] + float(cu.r[5]) * l[2] + float(cu.p[1]) * spread;
              float wz = float(cu.r[6]) * l[0] + float(cu.r[7]) * l[1] + float(cu.r[8]) * l[2] + float(cu.p[2]) * spread;
              if (inLayer) partial(wx, wy, wz);
              wy += lift;
              float X, Y, Z;
              toCam(wx, wy, wz, X, Y, Z);
              corner[k] = {X, Y, Z};
              cxw += X;
              cyw += Y;
              czw += Z;
              zs += Z;
            }
            // Cara de espaldas a la cámara: no se dibuja.
            float vx = cxw * 0.25f, vy = cyw * 0.25f, vz = czw * 0.25f + 9.0f;
            if (nX * vx + nY * vy + nZ * vz >= 0.0f) continue;
            for (int k = 0; k < 4; k++) q.v[k] = project(corner[k][0], corner[k][1], corner[k][2]);
            q.depth = zs * 0.25f - (sticker ? 0.001f : 0.0f);
            q.sticker = sticker;
            q.light = std::clamp(0.45f + 0.55f * (0.4f * nX + 0.75f * nY - 0.5f * nZ), 0.25f, 1.1f);
            q.color = sticker ? faceColor(ax, sg) : Color{0.05f, 0.05f, 0.06f, 1.0f};
            quads.push_back(q);
          }
        }
      }
    }
    std::sort(quads.begin(), quads.end(), [](const Quad& a, const Quad& b) { return a.depth > b.depth; });
    float lit = (0.9f + 0.2f * kick + 0.5f * celebrate) * amp;
    // Halo de las pegatinas: suave en reposo, se enciende con cada golpe y al resolverse.
    const float halo = std::clamp((0.05f + 0.22f * kick * amp + 0.3f * celebrate) * f.glow, 0.0f, 0.45f);
    for (const auto& q : quads) {
      Path p;
      p.moveTo(q.v[0].x, q.v[0].y).lineTo(q.v[1].x, q.v[1].y).lineTo(q.v[2].x, q.v[2].y).lineTo(q.v[3].x, q.v[3].y).close();
      Paint paint;
      float shade = q.sticker ? q.light * lit : q.light * 0.8f;
      paint.color = Color{std::clamp(q.color.r * shade, 0.0f, 1.0f), std::clamp(q.color.g * shade, 0.0f, 1.0f), std::clamp(q.color.b * shade, 0.0f, 1.0f), 1.0f};
      c.path(p, paint);
      if (q.sticker && halo > 0.005f) {
        Paint glow;
        glow.blend = Blend::plus;
        glow.strokeWidth = 6.0f * side / 400.0f;
        glow.strokeJoin = 1;
        glow.color = q.color.opacity(halo);
        c.path(p, glow);
      }
      if (q.sticker && m.brillo) {
        // Reflejo en una esquina de la pegatina.
        Vec2 a = q.v[0], b = q.v[1], d = q.v[3];
        Path shine;
        shine.moveTo(a.x + (b.x - a.x) * 0.12f + (d.x - a.x) * 0.12f, a.y + (b.y - a.y) * 0.12f + (d.y - a.y) * 0.12f)
            .lineTo(a.x + (b.x - a.x) * 0.45f + (d.x - a.x) * 0.12f, a.y + (b.y - a.y) * 0.45f + (d.y - a.y) * 0.12f)
            .lineTo(a.x + (b.x - a.x) * 0.12f + (d.x - a.x) * 0.45f, a.y + (b.y - a.y) * 0.12f + (d.y - a.y) * 0.45f)
            .close();
        Paint sp;
        sp.blend = Blend::plus;
        sp.color = Color{1.0f, 1.0f, 1.0f, std::clamp(0.18f * q.light * amp, 0.0f, 1.0f)};
        c.path(shine, sp);
      }
    }
    if (celebrate > 0.01f || flash > 0.01f) {
      Paint fl;
      fl.blend = Blend::plus;
      fl.color = f.colors[3].opacity(std::clamp((celebrate * 0.12f + flash * 0.05f) * amp, 0.0f, 1.0f));
      c.rect({0, 0, f.width, f.height}, fl);
    }
  }
};

class Visual final : public Scene {
  static constexpr int kMax = 12;
  static constexpr int kPoints = 150;
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  std::array<float, kMax> bands{};
  // Relojes en doble precisión: la escena sin música es idéntica a 30 y 60 FPS.
  double clock = 0, strumAge = 100, sinceIdle = 0;
  float strumPower = 0;
  bool strumUp = false;

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    bands.fill(0);
    clock = rng.unit() * 20.0;
    strumAge = 0.3;
    strumPower = 0.8f;
    sinceIdle = 0;
    strumUp = false;
  }

  void update(const Frame& f) override {
    auto m = modifiers(f);
    float dt = float(f.delta);
    const Music& mu = f.music;
    bass = follow(bass, mu.bass, 22.0f, 4.5f, dt);
    body = follow(body, mu.body, 12.0f, 3.0f, dt);
    spark = follow(spark, mu.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, mu.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, mu.active ? std::pow(std::clamp(mu.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);
    int n = std::clamp(m.cuerdas, 2, kMax);
    for (int i = 0; i < n; i++) {
      int b0 = i * 26 / n, b1 = std::max(b0 + 1, (i + 1) * 26 / n);
      float v = 0;
      for (int b = b0; b < b1; b++) v = std::max(v, mu.smoothSpectrum[size_t(b)]);
      bands[size_t(i)] = follow(bands[size_t(i)], v, 25.0f, 5.0f, dt);
    }

    float hit = 0, fl = 0;
    for (const auto& e : mu.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : mu.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : mu.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((mu.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, mu.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    strumAge += f.delta;
    sinceIdle += f.delta;
    if (hit > kick + 0.2f) {
      strumAge = 0;
      strumPower = hit;
      strumUp = !strumUp;
      sinceIdle = 0;
    }
    if (!mu.active && sinceIdle > 2.4) {
      sinceIdle -= 2.4;
      strumAge = sinceIdle;
      strumPower = 0.85f;
      strumUp = !strumUp;
    }
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    clock += f.delta * f.speed * (1.0 + 0.6 * drive);
  }

  void render(const Frame& f, Canvas& c) const override {
    auto m = modifiers(f);
    float amp = f.intensity;
    const Color& bg = f.colors[0];
    const Color& red = f.colors[1];
    const Color& gold = f.colors[2];
    const Color& silver = f.colors[3];
    c.rect({0, 0, f.width, f.height}, Paint::linear({0, 0}, {0, f.height}, {Color{bg.r, bg.g, bg.b, 1.0f}, Color{std::min(1.0f, bg.r + red.r * 0.12f), std::min(1.0f, bg.g + red.g * 0.04f), bg.b, 1.0f}}));
    // Luz roja desde abajo, más fuerte con los graves.
    Paint glowBg = Paint::radial({f.width * 0.5f, f.height * 1.05f}, f.height * 0.75f,
                                 {red.opacity(std::clamp((0.35f + 0.35f * bass) * amp, 0.0f, 1.0f)), red.opacity(0.0f)});
    glowBg.blend = Blend::plus;
    c.rect({0, 0, f.width, f.height}, glowBg);
    float px = std::min(f.width, f.height) / 400.0f;
    float top = -f.height * 0.02f, bottom = f.height * 1.02f;
    float L = bottom - top;
    // Trastes: barras metálicas cada vez más juntas, como en el mástil.
    if (m.trastes) {
      Path frets;
      for (int k = 1; k <= 14; k++) {
        float y = top + L * (1.0f - std::pow(2.0f, -float(k) / 12.0f)) * 1.9f;
        if (y > bottom) break;
        frets.moveTo(f.width * 0.08f, y).lineTo(f.width * 0.92f, y);
      }
      Paint fp;
      fp.strokeWidth = 2.0f * px;
      fp.color = Color{0.7f, 0.68f, 0.66f, std::clamp(0.16f * amp, 0.0f, 1.0f)};
      c.path(frets, fp);
    }
    int n = std::clamp(m.cuerdas, 2, kMax);
    float t = float(std::fmod(clock, 1000.0));
    for (int i = 0; i < n; i++) {
      float u = n > 1 ? float(i) / float(n - 1) : 0.0f;
      float x0 = f.width * (0.14f + 0.72f * u);
      // Rasgueo: cada cuerda se pulsa un poco después que la anterior.
      int order = strumUp ? n - 1 - i : i;
      float delay = 0.028f * float(order);
      float sa = float(strumAge) - delay;
      float pluck = sa >= 0.0f ? strumPower * std::exp(-sa * 2.4f) : 0.0f;
      float level = std::clamp(0.22f + 1.1f * bands[size_t(i)] * amp + 1.1f * pluck, 0.0f, 1.6f);
      float A = f.width * 0.05f * m.amplitud * level * (1.15f - 0.5f * u);
      float waves = (2.0f + 3.5f * u) * m.ondas;
      float k1 = 6.2831853f * waves / L;
      float w1 = 6.2831853f * (0.5f + 0.35f * float(i));
      float k2 = k1 * 2.3f;
      float w2 = w1 * 1.7f;
      Path s;
      for (int p = 0; p <= kPoints; p++) {
        float y = top + L * float(p) / float(kPoints);
        float env = std::sin(3.14159265f * float(p) / float(kPoints));
        float d = A * env * (0.78f * std::sin(k1 * y - w1 * t + float(i) * 1.7f) + 0.22f * std::sin(k2 * y + w2 * t));
        if (p == 0) s.moveTo(x0 + d, y); else s.lineTo(x0 + d, y);
      }
      bool wound = u < 0.5f;
      const Color& base = wound ? gold : silver;
      float thick = (wound ? 4.2f - 2.6f * u : 2.2f - 1.2f * (u - 0.5f)) * px;
      Paint halo;
      halo.blend = Blend::plus;
      halo.strokeWidth = thick * 5.0f;
      halo.strokeJoin = 1;
      halo.color = (wound ? gold : red).opacity(std::clamp((0.05f + 0.22f * level) * f.glow * amp, 0.0f, 1.0f));
      c.path(s, halo);
      // Sombreado de cilindro con su reflejo.
      Paint core;
      core.strokeWidth = thick;
      core.strokeJoin = 1;
      float lit = (0.75f + 0.45f * level) * amp;
      core.color = Color{std::min(1.0f, base.r * lit), std::min(1.0f, base.g * lit), std::min(1.0f, base.b * lit), 1.0f};
      c.path(s, core);
      Paint shine;
      shine.blend = Blend::plus;
      shine.strokeWidth = std::max(0.8f, thick * 0.3f);
      shine.strokeJoin = 1;
      shine.color = Color{1.0f, 0.95f, 0.9f, std::clamp((0.25f + 0.4f * level) * amp, 0.0f, 1.0f)};
      c.path(s, shine);
    }
    if (flash > 0.01f) {
      Paint fl;
      fl.blend = Blend::plus;
      fl.color = red.opacity(std::clamp(flash * 0.06f * amp, 0.0f, 1.0f));
      c.rect({0, 0, f.width, f.height}, fl);
    }
  }
};

class Visual final : public Scene {
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  // Relojes en doble precisión: la escena sin música es idéntica a 30 y 60 FPS.
  double phaseTime = 0, pulseAge = 100;
  float pulsePower = 0;
  // Reloj del parpadeo y las chispas de los agudos.
  double shimmer = 0;
  // stage: posición dentro de la ventana de niveles que fija Nivel máximo.
  int autoCurve = 0, stage = 0, builtCurve = -1, builtLevel = -1;
  bool holding = false;
  std::vector<Vec2> pts;

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

  static float hashU(uint32_t x) {
    x ^= x >> 16; x *= 0x7feb352dU; x ^= x >> 15; x *= 0x846ca68bU; x ^= x >> 16;
    return float(x & 0xffffffu) / 16777216.0f;
  }

  static void hilbert(int order, std::vector<Vec2>& out) {
    int n = 1 << order;
    out.clear();
    for (int d = 0; d < n * n; d++) {
      int x = 0, y = 0, t = d;
      for (int s = 1; s < n; s *= 2) {
        int rx = 1 & (t / 2), ry = 1 & (t ^ rx);
        if (ry == 0) {
          if (rx == 1) {
            x = s - 1 - x;
            y = s - 1 - y;
          }
          std::swap(x, y);
        }
        x += s * rx;
        y += s * ry;
        t /= 4;
      }
      out.push_back({float(x), float(y)});
    }
  }

  static void dragon(int order, std::vector<Vec2>& out) {
    out.clear();
    int x = 0, y = 0, dir = 0;
    static const int dx[4] = {1, 0, -1, 0}, dy[4] = {0, 1, 0, -1};
    out.push_back({0, 0});
    int n = 1 << order;
    for (int i = 1; i <= n; i++) {
      x += dx[dir];
      y += dy[dir];
      out.push_back({float(x), float(y)});
      bool right = (((i & -i) << 1) & i) != 0;
      dir = (dir + (right ? 3 : 1)) % 4;
    }
  }

  // Tortuga para los sistemas L de Gosper y Koch.
  struct Turtle { float x = 0, y = 0, a = 0; };
  static void gosper(int lv, bool isA, Turtle& t, std::vector<Vec2>& out) {
    if (lv == 0) {
      t.x += std::cos(t.a);
      t.y += std::sin(t.a);
      out.push_back({t.x, t.y});
      return;
    }
    const float r = 1.0471976f;
    const char* rule = isA ? "A-B--B+A++AA+B-" : "+A-AA--B-B++A+B";
    for (const char* p = rule; *p; p++) {
      if (*p == 'A') gosper(lv - 1, true, t, out);
      else if (*p == 'B') gosper(lv - 1, false, t, out);
      else if (*p == '+') t.a += r;
      else t.a -= r;
    }
  }
  static void koch(int lv, Turtle& t, std::vector<Vec2>& out) {
    if (lv == 0) {
      t.x += std::cos(t.a);
      t.y += std::sin(t.a);
      out.push_back({t.x, t.y});
      return;
    }
    koch(lv - 1, t, out);
    t.a += 1.0471976f;
    koch(lv - 1, t, out);
    t.a -= 2.0943951f;
    koch(lv - 1, t, out);
    t.a += 1.0471976f;
    koch(lv - 1, t, out);
  }

  // Nivel más fino de cada curva para un Nivel máximo dado.
  static int maxLevel(int curve, int nivel) {
    if (curve == 0 || curve == 1) return std::clamp(nivel, 1, 7);
    if (curve == 2) return std::clamp(nivel - 2, 1, 4);
    return std::clamp(nivel - 1, 1, 6);
  }
  // Ventana que recorre: los tres niveles que terminan en el máximo. Así el
  // ajuste se ve desde el primer trazo, no sólo al final de un ciclo largo.
  static int firstLevel(int curve, int nivel) { return std::max(1, maxLevel(curve, nivel) - 2); }
  static int stages(int curve, int nivel) { return maxLevel(curve, nivel) - firstLevel(curve, nivel) + 1; }
  // El dragón dobla la tira dos veces por nivel.
  static int order(int curve, int lv) { return curve == 1 ? std::max(2, lv * 2) : lv; }
  void buildStage(int curve, int nivel) {
    stage = std::clamp(stage, 0, stages(curve, nivel) - 1);
    build(curve, order(curve, firstLevel(curve, nivel) + stage));
  }

  void build(int curve, int lv) {
    if (curve == builtCurve && lv == builtLevel) return;
    builtCurve = curve;
    builtLevel = lv;
    if (curve == 0) {
      hilbert(lv, pts);
    } else if (curve == 1) {
      dragon(lv, pts);
    } else if (curve == 2) {
      pts.clear();
      Turtle t;
      pts.push_back({0, 0});
      gosper(lv, true, t, pts);
    } else {
      pts.clear();
      Turtle t;
      pts.push_back({0, 0});
      for (int k = 0; k < 3; k++) {
        koch(lv, t, pts);
        t.a -= 2.0943951f;
      }
    }
    // Normaliza al cuadrado [-1, 1] conservando proporciones.
    float minX = 1e9f, maxX = -1e9f, minY = 1e9f, maxY = -1e9f;
    for (auto& p : pts) {
      minX = std::min(minX, p.x);
      maxX = std::max(maxX, p.x);
      minY = std::min(minY, p.y);
      maxY = std::max(maxY, p.y);
    }
    float cx = (minX + maxX) * 0.5f, cy = (minY + maxY) * 0.5f;
    float s = 2.0f / std::max(std::max(maxX - minX, maxY - minY), 1e-3f);
    for (auto& p : pts) p = {(p.x - cx) * s, (p.y - cy) * s};
  }

  double drawTime() const { return 3.2 + 0.6 * double(builtLevel > 0 ? std::min(builtLevel, 7) : 1); }

 public:
  void reset(uint32_t seed) override {
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    phaseTime = 0;
    pulseAge = 100;
    pulsePower = 0;
    shimmer = 0;
    autoCurve = int(seed % 4u);
    stage = 0;
    builtCurve = builtLevel = -1;
    holding = false;
    pts.reserve(20000);
  }

  void update(const Frame& f) override {
    auto m = modifiers(f);
    float dt = float(f.delta);
    const Music& mu = f.music;
    bass = follow(bass, mu.bass, 22.0f, 4.5f, dt);
    body = follow(body, mu.body, 12.0f, 3.0f, dt);
    spark = follow(spark, mu.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, mu.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, mu.active ? std::pow(std::clamp(mu.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : mu.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : mu.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : mu.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((mu.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, mu.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    pulseAge += f.delta;
    shimmer += f.delta;
    if (hit > kick + 0.2f) {
      pulseAge = 0;
      pulsePower = hit;
    }
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));

    int curve = m.curva == 0 ? autoCurve : m.curva - 1;
    buildStage(curve, m.nivel);
    phaseTime += f.delta * f.speed * m.velocidad * (1.0 + 1.2 * drive);
    for (int guard = 0; guard < 4; guard++) {
      double length = holding ? 1.4 : drawTime();
      if (phaseTime < length) break;
      phaseTime -= length;
      if (!holding) {
        holding = true;
        continue;
      }
      holding = false;
      if (stage + 1 >= stages(curve, m.nivel)) {
        stage = 0;
        if (m.curva == 0) autoCurve = (autoCurve + 1) % 4;
      } else {
        stage++;
      }
      curve = m.curva == 0 ? autoCurve : m.curva - 1;
      buildStage(curve, m.nivel);
    }
  }

  void render(const Frame& f, Canvas& c) const override {
    auto m = modifiers(f);
    auto gl = glide(f);
    float amp = f.intensity;
    // Pulso: cada opción mueve algo distinto; sin música todo vale cero.
    const float wGolpes = gl.pulso.weight(0);
    const float kickP = std::min(kick * amp, 1.0f) * wGolpes;
    const float bassP = std::min(bass * amp, 1.0f) * gl.pulso.weight(1);
    const float sparkP = std::min(spark * amp, 1.0f) * gl.pulso.weight(2);
    const uint32_t tick = uint32_t(std::fmod(shimmer, 100000.0) * 14.0);
    const Color& bg = f.colors[0];
    c.rect({0, 0, f.width, f.height}, Paint::radial({f.width * 0.5f, f.height * 0.5f}, std::max(f.width, f.height) * 0.7f,
                                                   {Color{std::min(1.0f, bg.r + 0.05f), std::min(1.0f, bg.g + 0.02f), std::min(1.0f, bg.b + 0.06f), 1.0f},
                                                    Color{bg.r, bg.g, bg.b, 1.0f}}));
    if (pts.size() < 2) return;
    float side = std::min(f.width, f.height);
    float px = side / 400.0f;
    float half = side * 0.45f;
    Vec2 center{f.width * 0.5f, f.height * 0.5f};
    size_t n = pts.size();
    float prog = holding ? 1.0f : float(std::clamp(phaseTime / drawTime(), 0.0, 1.0));
    prog = prog * prog * (3.0f - 2.0f * prog);
    size_t shown = std::max<size_t>(2, size_t(prog * float(n)));
    float spacing = 2.0f * half / std::sqrt(float(n));
    // Graves: la línea engorda con los graves.
    float width = std::clamp(spacing * 0.32f, 1.0f * px, 6.0f * px) * m.grosor * (1.0f + 0.3f * bass * amp) * (1.0f + 0.45f * bassP);
    const int chunks = 28;
    float wave = pulseAge < 2.5 ? float(pulseAge / 1.6) : 9.0f;
    for (int ch = 0; ch < chunks; ch++) {
      size_t a = n * size_t(ch) / chunks, b = std::min(shown, n * size_t(ch + 1) / chunks + 1);
      if (a >= shown) break;
      Path p;
      for (size_t i = a; i < b; i++) {
        Vec2 q{center.x + pts[i].x * half, center.y + pts[i].y * half};
        if (i == a) p.moveTo(q.x, q.y); else p.lineTo(q.x, q.y);
      }
      float t = float(ch) / float(chunks - 1);
      const Color& c0 = f.colors[1];
      const Color& c1 = f.colors[2];
      const Color& c2 = f.colors[3];
      Color col = t < 0.5f ? Color{c0.r + (c1.r - c0.r) * t * 2.0f, c0.g + (c1.g - c0.g) * t * 2.0f, c0.b + (c1.b - c0.b) * t * 2.0f, 1.0f}
                           : Color{c1.r + (c2.r - c1.r) * (t - 0.5f) * 2.0f, c1.g + (c2.g - c1.g) * (t - 0.5f) * 2.0f, c1.b + (c2.b - c1.b) * (t - 0.5f) * 2.0f, 1.0f};
      // Golpes: el pulso de luz corre más fuerte y más ancho (sin música no hay pulso).
      float pulse = pulsePower * std::exp(-(t - wave) * (t - wave) * (60.0f - 30.0f * wGolpes)) * (1.0f + 0.4f * wGolpes);
      // Golpes enciende el trazo entero; Graves lo aviva; Agudos lo hace parpadear por tramos.
      const float flick = sparkP > 0.002f ? hashU(uint32_t(ch) * 2654435761u + tick * 40503u) : 0.0f;
      float lit = (0.8f + 0.3f * body + 1.2f * pulse) * amp * (1.0f + 0.5f * kickP + 0.25f * bassP + 0.45f * sparkP * flick);
      Paint glow;
      glow.blend = Blend::plus;
      glow.strokeWidth = width * 3.0f + 2.0f * px;
      glow.strokeJoin = 1;
      glow.strokeCap = 1;
      glow.color = col.opacity(std::clamp((0.1f + 0.3f * pulse) * f.glow * amp * (1.0f + 1.2f * kickP + 0.8f * bassP), 0.0f, 1.0f));
      c.path(p, glow);
      Paint line;
      line.strokeWidth = width;
      line.strokeJoin = 1;
      line.strokeCap = 1;
      line.color = Color{std::min(1.0f, col.r * lit + pulse * 0.4f), std::min(1.0f, col.g * lit + pulse * 0.4f), std::min(1.0f, col.b * lit + pulse * 0.4f), 1.0f};
      c.path(p, line);
    }
    // Agudos: chispas sueltas a lo largo del dibujo, unas 160 a la vez.
    if (sparkP > 0.002f) {
      std::vector<Vec2> glints;
      glints.reserve(512);
      const float chance = std::min(0.5f, 160.0f * sparkP / float(shown));
      for (size_t i = 0; i < shown && glints.size() < 512; i++) {
        if (hashU(uint32_t(i) * 2654435761u + tick * 40503u) < chance) glints.push_back({center.x + pts[i].x * half, center.y + pts[i].y * half});
      }
      const Color& c3 = f.colors[3];
      Paint gp;
      gp.blend = Blend::plus;
      gp.color = Color{std::min(1.0f, c3.r * 0.5f + 0.5f), std::min(1.0f, c3.g * 0.5f + 0.5f), std::min(1.0f, c3.b * 0.5f + 0.5f),
                       std::clamp(0.85f * sparkP, 0.0f, 0.9f)};
      c.points(glints, std::max(1.6f * px, width * 0.9f), gp);
    }
    // Lápiz de luz en la punta; Golpes lo hace destellar.
    if (!holding) {
      const Vec2& h = pts[shown - 1];
      Vec2 q{center.x + h.x * half, center.y + h.y * half};
      const float tipR = 16.0f * px * (1.0f + 0.6f * kickP);
      Paint halo = Paint::radial(q, tipR, {f.colors[3].opacity(std::clamp(0.8f * amp, 0.0f, 1.0f)), f.colors[3].opacity(0.0f)});
      halo.blend = Blend::plus;
      c.circle(q, tipR, halo);
      Paint dot;
      dot.color = Color{1.0f, 1.0f, 0.95f, 1.0f};
      c.circle(q, 2.4f * px, dot);
    }
    if (flash > 0.01f) {
      Paint fl;
      fl.blend = Blend::plus;
      fl.color = f.colors[2].opacity(std::clamp(flash * 0.05f * amp, 0.0f, 1.0f));
      c.rect({0, 0, f.width, f.height}, fl);
    }
  }
};

class Visual final : public Scene {
  float phase = 0.0f;
  float smoothEnergy = 0.0f;
  float smoothBass = 0.0f;
  float smoothSpark = 0.0f;
 public:
  void reset(uint32_t seed) override {
    (void)seed;
    phase = 0.0f;
    smoothEnergy = 0.0f;
    smoothBass = 0.0f;
    smoothSpark = 0.0f;
  }
  void update(const Frame& f) override {
    float dt = float(f.delta);
    float targetEnergy = f.music.active ? f.music.energy : 0.0f;
    float targetBass = f.music.active ? f.music.bass : 0.0f;
    float targetSpark = f.music.active ? f.music.spark : 0.0f;
    smoothEnergy += (targetEnergy - smoothEnergy) * float(1.0 - std::exp(-dt * 6.0));
    smoothBass += (targetBass - smoothBass) * float(1.0 - std::exp(-dt * 8.0));
    smoothSpark += (targetSpark - smoothSpark) * float(1.0 - std::exp(-dt * 12.0));

    // En silencio reposa en un planeo zen majestuoso (~0.08f).
    // Con música la velocidad responde en tiempo real a la energía y bombos.
    float audioDrive = 0.08f + smoothEnergy * 0.72f + smoothBass * 0.35f;
    phase += dt * f.speed * audioDrive;
  }
  void render(const Frame& f, Canvas& c) const override {
    float w = f.width, h = f.height;
    float time = phase * 6.2831853f;

    // Deformación del atractor de Julia según el bajo rítmico
    float bassDeform = smoothBass * 0.075f;
    float cx = 0.7885f * std::cos(time * 0.17f) + bassDeform * std::sin(time * 0.45f);
    float cy = 0.7885f * std::sin(time * 0.23f) - bassDeform * std::cos(time * 0.45f);

    // Zoom pulsante ante bombos y sub-graves
    float baseZoom = 1.32f + std::sin(time * 0.06f) * 0.04f;
    float zoomPulse = smoothBass * 0.28f;
    float currentZoom = baseZoom * (1.0f - zoomPulse);

    // Iteraciones adaptativas: menos pasos cuanto más densa es la pantalla.
    float px = w * h;
    float maxIter = px > 3.0e6f ? 48.0f : (px > 1.0e6f ? 72.0f : 96.0f);

    float uAudio = std::clamp((smoothEnergy * 0.7f + smoothBass * 0.5f) * f.intensity, 0.0f, 1.0f);
    float uSpark = std::clamp(smoothSpark * f.intensity, 0.0f, 1.0f);

    std::vector<float> u;
    u.reserve(8);
    u.push_back(cx);
    u.push_back(cy);
    u.push_back(time);
    u.push_back(currentZoom);
    u.push_back(maxIter);
    u.push_back(uAudio);
    u.push_back(uSpark);
    c.material("julia", {0, 0, w, h}, u);
  }
};

shaderSources.julia:
#version 460 core
#include <flutter/runtime_effect.glsl>
uniform vec2 uSize;
uniform vec2 uC;
uniform float uTime;
uniform float uZoom;
uniform float uMaxIter;
uniform float uAudio;
uniform float uSpark;
out vec4 fragColor;
vec3 palette(float t) {
  return 0.5 + 0.5 * cos(6.28318 * (vec3(1.0, 0.9, 0.8) * t + vec3(0.02, 0.18, 0.34)));
}
void main() {
  vec2 uv = FlutterFragCoord().xy / uSize.xy;
  float aspect = uSize.x / uSize.y;
  vec2 z = (uv * 2.0 - 1.0) * vec2(uZoom * aspect, uZoom);
  float i = 0.0;
  float m2 = 0.0;
  for (int k = 0; k < 96; k++) {
    if (float(k) >= uMaxIter || m2 > 6.0) break;
    z = vec2(z.x * z.x - z.y * z.y, 2.0 * z.x * z.y) + uC;
    m2 = dot(z, z);
    i += 1.0;
  }
  if (i >= uMaxIter) {
    fragColor = vec4(0.02, 0.015, 0.04, 1.0);
    return;
  }
  float sl = i - log2(max(1e-4, log2(max(1.0001, m2))));
  vec3 col = palette(sl * 0.012 + uTime * 0.02);

  // Realce reactivo al audio: filamentos interiores y resplandor de chispas
  float filament = exp(-abs(sl - 14.0) * 0.28) * uAudio * 0.65;
  vec3 glowColor = vec3(0.4, 0.85, 1.0) * filament;
  float sparkShimmer = exp(-abs(sl - 28.0) * 0.35) * uSpark * 0.5;
  vec3 sparkColor = vec3(1.0, 0.75, 0.3) * sparkShimmer;
  col = col * (0.85 + 0.30 * uAudio) + glowColor + sparkColor;

  float d = length(uv - 0.5);
  col *= smoothstep(0.95, 0.25, d);
  fragColor = vec4(clamp(pow(col, vec3(0.85)), 0.0, 1.0), 1.0);
}

