visuals.nativeSource:
class Visual final : public Scene {
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  // Relojes en doble precisión: la escena sin música es idéntica a 30 y 60 FPS.
  double flow = 0, melt = 0;
  float hueKick = 0;

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    flow = rng.unit() * 20.0;
    melt = rng.unit() * 20.0;
    hueKick = 0;
  }

  void update(const Frame& f) override {
    float dt = float(f.delta);
    const Music& m = f.music;
    bass = follow(bass, m.bass, 22.0f, 4.5f, dt);
    body = follow(body, m.body, 12.0f, 3.0f, dt);
    spark = follow(spark, m.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, m.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, m.active ? std::pow(std::clamp(m.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : m.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : m.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : m.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((m.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, m.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    if (hit > kick + 0.2f) hueKick += 0.18f * hit;
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    flow += f.delta * f.speed * (0.25 + 0.6 * drive);
    melt += f.delta * f.speed * (0.06 + 0.2 * drive);
  }

  void render(const Frame& f, Canvas& c) const override {
    float amp = f.intensity;
    std::vector<float> u;
    u.reserve(20);
    u.insert(u.end(), {float(std::fmod(flow, 1000.0)), bass * amp, kick * amp, energy});
    u.insert(u.end(), {float(std::fmod(melt, 1000.0)), float(std::fmod(hueKick, 100.0)), f.glow, flash * amp});
    for (int i = 0; i < 4; i++) u.insert(u.end(), {f.colors[i].r, f.colors[i].g, f.colors[i].b});
    c.material("melt_bands", {0, 0, f.width, f.height}, u);
  }
};

shaderSources.melt_bands:
#version 460 core
#include <flutter/runtime_effect.glsl>
uniform vec2 uSize;
uniform vec4 uA;   // flujo, graves, golpe, energía
uniform vec4 uB;   // goteo, salto de color, glow, destello
uniform vec3 uC0;
uniform vec3 uC1;
uniform vec3 uC2;
uniform vec3 uC3;
out vec4 fragColor;

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash12(i), hash12(i + vec2(1.0, 0.0)), u.x),
             mix(hash12(i + vec2(0.0, 1.0)), hash12(i + vec2(1.0, 1.0)), u.x), u.y);
}

// Paleta de póster: rojo, naranja, amarillo, magenta, turquesa, violeta.
vec3 poster(float x) {
  float k = fract(x) * 6.0;
  vec3 c0 = uC1;
  vec3 c1 = uC2;
  vec3 c2 = vec3(1.0, 0.9, 0.2);
  vec3 c3 = vec3(1.0, 0.1, 0.6);
  vec3 c4 = uC3;
  vec3 c5 = vec3(0.45, 0.1, 0.85);
  vec3 a = k < 1.0 ? c0 : (k < 2.0 ? c1 : (k < 3.0 ? c2 : (k < 4.0 ? c3 : (k < 5.0 ? c4 : c5))));
  vec3 b = k < 1.0 ? c1 : (k < 2.0 ? c2 : (k < 3.0 ? c3 : (k < 4.0 ? c4 : (k < 5.0 ? c5 : c0))));
  return mix(a, b, smoothstep(0.7, 1.0, fract(k)));
}

void main() {
  vec2 frag = FlutterFragCoord().xy;
  float scale = min(uSize.x, uSize.y);
  vec2 p = (frag - 0.5 * uSize) / scale;
  float t = uA.x;
  // Chorros que caen desde arriba: columnas que estiran la pintura hacia abajo.
  float cols = 7.0;
  float cx = p.x * cols;
  float id = floor(cx);
  float local = fract(cx) - 0.5;
  float h = hash12(vec2(id, 3.0));
  float len = fract(uB.x * (0.4 + 0.5 * h) + h) * 1.6;
  float column = exp(-local * local * 9.0) * smoothstep(-0.8, 0.0, -(p.y + 0.6 - len)) * smoothstep(-0.6, 0.4, p.y);
  float drip = column * (0.25 + 0.3 * h);
  // Campo retorcido que ondula las bandas.
  vec2 q = vec2(p.x, p.y + drip);
  float w = 0.35 + 0.35 * uA.y;
  vec2 warp = vec2(noise(q * 2.0 + vec2(t * 0.3, 0.0)), noise(q * 2.0 + vec2(4.1, -t * 0.25))) - 0.5;
  q += warp * w;
  float v = q.y * 4.0 + 0.6 * sin(q.x * 3.0 + t * 0.5) + noise(q * 4.0) * 0.6 - t * 0.35 + uB.y;
  vec3 col = poster(v * 0.5);
  // Trazos oscuros entre bandas y brillo de pintura fresca.
  float edge = abs(fract(v * 3.0) - 0.5);
  col *= 0.35 + 0.65 * smoothstep(0.02, 0.12, edge);
  float gloss = pow(max(0.0, 1.0 - abs(fract(v * 3.0 + 0.2) - 0.5) * 6.0), 4.0);
  col += vec3(1.0) * gloss * 0.12 * (1.0 + uA.z);
  col *= (0.85 + 0.3 * uA.y + 0.35 * uA.z) * mix(1.0, uB.z, 0.5);
  col = mix(col, vec3(1.0), uB.w * 0.06);
  col *= 1.0 - 0.25 * smoothstep(0.6, 1.5, length(p * vec2(0.9, 0.65)));
  col += (hash12(frag) - 0.5) / 255.0;
  fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

visuals.nativeSource:
class Visual final : public Scene {
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  std::array<float, 8> bands{}, base{}, goal{}, seeds{}, power{};
  float phase = 0, crackle = 0;
  Random rng{3};

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

 public:
  void reset(uint32_t seed) override {
    rng = Random(seed);
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    bands.fill(0);
    power.fill(0);
    for (int i = 0; i < 8; i++) {
      base[i] = rng.unit() * 6.2831853f;
      goal[i] = base[i];
      seeds[i] = rng.unit() * 10.0f;
    }
    phase = rng.unit() * 10.0f;
    crackle = 0;
  }

  void update(const Frame& f) override {
    float dt = float(f.delta);
    const Music& m = f.music;
    bass = follow(bass, m.bass, 22.0f, 4.5f, dt);
    body = follow(body, m.body, 12.0f, 3.0f, dt);
    spark = follow(spark, m.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, m.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, m.active ? std::pow(std::clamp(m.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : m.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : m.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : m.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((m.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, m.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    bool strike = hit > kick + 0.2f;
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));

    static const int edges[9] = {0, 3, 6, 9, 13, 17, 21, 26, 31};
    for (int b = 0; b < 8; b++) {
      float v = 0;
      for (int i = edges[b]; i < edges[b + 1]; i++) v = std::max(v, m.smoothSpectrum[i]);
      bands[b] = follow(bands[b], v, 22.0f, 4.0f, dt);
    }

    for (int i = 0; i < 8; i++) {
      // Tres filamentos siempre vivos; el resto aparece con su banda.
      float target = (i < 4 ? 0.5f : 0.0f) + bands[i] * 1.1f + kick * (i < 6 ? 0.7f : 0.4f);
      power[i] = follow(power[i], target, 25.0f, 5.0f, dt);
      // El golpe fija un destino nuevo y el rayo se desliza hasta él en
      // unas décimas de segundo, como un latigazo continuo.
      if (strike) goal[i] += (rng.unit() - 0.5f) * 2.2f;
      goal[i] += dt * f.speed * (i % 2 ? 1.0f : -1.0f) * (0.08f + 0.25f * drive);
      base[i] += (goal[i] - base[i]) * (1.0f - std::exp(-dt * 9.0f));
    }
    phase += dt * f.speed * (0.6f + 1.4f * drive + 0.6f * kick);
    // Reloj propio del chisporroteo: cambia de forma continua, sin parpadeo.
    crackle += dt * (1.6f + 2.4f * spark);
  }

  void render(const Frame& f, Canvas& c) const override {
    float amp = f.intensity;
    std::array<float, 8> angle{};
    for (int i = 0; i < 8; i++) angle[i] = base[i] + std::sin(phase * 0.35f + seeds[i]) * 0.45f;
    std::vector<float> u;
    u.reserve(44);
    u.insert(u.end(), {phase, bass * amp, kick * amp, energy});
    u.insert(u.end(), {angle[0], angle[1], angle[2], angle[3]});
    u.insert(u.end(), {angle[4], angle[5], angle[6], angle[7]});
    for (int i = 0; i < 8; i++) u.push_back(std::min(power[i] * amp, 2.0f));
    u.insert(u.end(), {spark * amp, flash, f.glow, crackle});
    for (int i = 0; i < 4; i++) u.insert(u.end(), {f.colors[i].r, f.colors[i].g, f.colors[i].b});
    c.material("plasma", {0, 0, f.width, f.height}, u);
  }
};

shaderSources.plasma:
#version 460 core
#include <flutter/runtime_effect.glsl>
uniform vec2 uSize;
uniform vec4 uA;     // tiempo, graves, golpe, energía
uniform vec4 uAng0;
uniform vec4 uAng1;
uniform vec4 uPow0;
uniform vec4 uPow1;
uniform vec4 uM;     // agudos, destello, glow, reloj del chisporroteo
uniform vec3 uC0;
uniform vec3 uC1;
uniform vec3 uC2;
uniform vec3 uC3;
out vec4 fragColor;

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash12(i), hash12(i + vec2(1.0, 0.0)), u.x),
             mix(hash12(i + vec2(0.0, 1.0)), hash12(i + vec2(1.0, 1.0)), u.x), u.y);
}

// Desvío lateral suave del rayo a lo largo de su recorrido (s = 0..1).
float wander(float s, float len, float seed) {
  float t = uA.x;
  float env = sin(3.14159 * s) * (0.55 + 0.45 * s);
  float amp = min(len, 0.7);
  return (sin(s * 6.0 + t * 1.3 + seed * 5.0) * 0.09 + sin(s * 15.0 - t * 2.7 + seed * 11.0) * 0.035) * amp * env;
}

// Rayo de plasma desde `origin` en la dirección `dir`; devuelve (núcleo, halo).
// Lejos del rayo sólo se calcula su halo; la forma y el chisporroteo se
// evalúan cerca, con una transición suave entre ambos cálculos.
vec2 bolt(vec2 p, vec2 origin, vec2 dir, float len, float power, float seed, float width0) {
  vec2 nrm = vec2(-dir.y, dir.x);
  vec2 q = p - origin;
  float along = dot(q, dir);
  float lat0 = dot(q, nrm);
  float beyond = along < 0.0 ? -along : max(along - len, 0.0);
  float reach = 0.13 * min(len, 0.7);
  float k = 0.00005 + 0.0001 * power;
  if (abs(lat0) > reach + 0.2 || beyond > 0.2) {
    return vec2(0.0, k / (lat0 * lat0 + beyond * beyond + 0.0004) * power);
  }
  float s = clamp(along / len, 0.0, 1.0);
  float smoothLat = lat0 - wander(s, len, seed);
  float lateral = smoothLat;
  if (abs(smoothLat) < 0.06) {
    float env = sin(3.14159 * s);
    lateral -= (noise(vec2(s * 40.0 + seed * 3.0, uM.w)) - 0.5) * (0.035 + 0.09 * uM.x) * min(len, 0.7) * env;
  }
  float blend = smoothstep(reach + 0.08, reach + 0.2, abs(lat0));
  float haloLat = mix(smoothLat, lat0, blend);
  float inside = step(0.0, along) * step(along, len);
  float width = (width0 + 0.005 * min(power, 1.5)) * (1.0 - 0.5 * s);
  float core = exp(-lateral * lateral / (width * width)) * inside;
  float halo = k / (haloLat * haloLat + beyond * beyond + 0.0004);
  return vec2(core * 1.5 * power, halo * power);
}

// Rayo principal hasta el borde de la pantalla, con una rama.
vec2 tendril(vec2 p, float ang, float power, float seed, vec2 halfSize) {
  if (power < 0.02) return vec2(0.0);
  vec2 dir = vec2(cos(ang), sin(ang));
  float len = min(halfSize.x / max(abs(dir.x), 0.001), halfSize.y / max(abs(dir.y), 0.001)) * 1.02;
  vec2 acc = bolt(p, vec2(0.0), dir, len, power, seed, 0.004);
  // Punto de contacto con el borde: la descarga ilumina donde toca.
  vec2 tip = dir * len;
  acc.x += exp(-dot(p - tip, p - tip) / (0.0012 + 0.002 * power)) * power;
  if (power > 0.35) {
    float fork = 0.42 + 0.2 * fract(seed * 0.37);
    vec2 nrm = vec2(-dir.y, dir.x);
    vec2 origin = dir * len * fork + nrm * wander(fork, len, seed);
    float side = fract(seed * 0.61) < 0.5 ? -1.0 : 1.0;
    float ba = ang + side * (0.45 + 0.25 * sin(uA.x * 0.7 + seed));
    vec2 bdir = vec2(cos(ba), sin(ba));
    acc += bolt(p, origin, bdir, len * 0.45, power * 0.7, seed + 7.0, 0.0025) * 0.8;
  }
  return acc;
}

void main() {
  vec2 frag = FlutterFragCoord().xy;
  float scale = min(uSize.x, uSize.y);
  vec2 p = (frag - 0.5 * uSize) / scale;
  p.y = -p.y;
  vec2 halfSize = 0.5 * uSize / scale;
  float r = length(p);
  float kick = uA.z;
  float t = uA.x;

  // Gas eléctrico en toda la pantalla, más vivo con la música y el golpe.
  float gas = noise(p * 2.2 + vec2(t * 0.12, -t * 0.08));
  vec3 col = uC0 + mix(uC2, uC1, gas) * gas * (0.006 + 0.03 * uA.w + 0.12 * kick) * uM.z;
  col += mix(uC1, uC2, 0.5) * exp(-r * r * 2.5) * (0.015 + 0.04 * uA.w + 0.2 * kick);

  vec2 acc = vec2(0.0);
  acc += tendril(p, uAng0.x, uPow0.x, 0.0, halfSize);
  acc += tendril(p, uAng0.y, uPow0.y, 1.7, halfSize);
  acc += tendril(p, uAng0.z, uPow0.z, 3.1, halfSize);
  acc += tendril(p, uAng0.w, uPow0.w, 4.6, halfSize);
  acc += tendril(p, uAng1.x, uPow1.x, 6.2, halfSize);
  acc += tendril(p, uAng1.y, uPow1.y, 7.9, halfSize);
  acc += tendril(p, uAng1.z, uPow1.z, 9.3, halfSize);
  acc += tendril(p, uAng1.w, uPow1.w, 10.8, halfSize);
  vec3 arc = mix(uC1, uC3, clamp(acc.x * 0.55, 0.0, 1.0)) * acc.x + mix(uC2, uC1, 0.4) * acc.y * (0.9 + 0.7 * kick);
  col += arc * (0.9 + 0.7 * uA.y) * uM.z;

  // Núcleo de energía con corona que pulsa con cada golpe.
  float coreR = 0.06 + 0.012 * uA.y + 0.03 * kick;
  float corona = 0.5 + 0.5 * noise(vec2(atan(p.y, p.x) * 3.0, t * 2.0));
  col += mix(uC1, uC3, 0.6) * smoothstep(coreR, coreR * 0.6, r) * (1.4 + 1.6 * kick);
  col += uC1 * (0.002 + 0.006 * kick) / (r * r + 0.003) * (0.7 + 0.3 * corona);

  col += mix(uC1, uC3, 0.5) * uM.y * 0.15;
  col *= 1.0 - 0.3 * smoothstep(0.6, 1.4, length(p * vec2(0.9, 0.6)));
  col = clamp((col * (2.51 * col + 0.03)) / (col * (2.43 * col + 0.59) + 0.14), 0.0, 1.0);
  col = pow(col, vec3(0.4545));
  col += (hash12(frag) - 0.5) / 255.0;
  fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

visuals.nativeSource:
class Visual final : public Scene {
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  std::array<float, 8> bands{}, base{}, goal{}, seeds{}, power{};
  float phase = 0, crackle = 0;
  Random rng{3};

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

 public:
  void reset(uint32_t seed) override {
    rng = Random(seed);
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    bands.fill(0);
    power.fill(0);
    for (int i = 0; i < 8; i++) {
      base[i] = rng.unit() * 6.2831853f;
      goal[i] = base[i];
      seeds[i] = rng.unit() * 10.0f;
    }
    phase = rng.unit() * 10.0f;
    crackle = 0;
  }

  void update(const Frame& f) override {
    float dt = float(f.delta);
    const Music& m = f.music;
    bass = follow(bass, m.bass, 22.0f, 4.5f, dt);
    body = follow(body, m.body, 12.0f, 3.0f, dt);
    spark = follow(spark, m.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, m.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, m.active ? std::pow(std::clamp(m.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : m.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : m.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : m.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((m.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, m.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    bool strike = hit > kick + 0.2f;
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));

    static const int edges[9] = {0, 3, 6, 9, 13, 17, 21, 26, 31};
    for (int b = 0; b < 8; b++) {
      float v = 0;
      for (int i = edges[b]; i < edges[b + 1]; i++) v = std::max(v, m.smoothSpectrum[i]);
      bands[b] = follow(bands[b], v, 22.0f, 4.0f, dt);
    }

    for (int i = 0; i < 8; i++) {
      // Tres filamentos siempre vivos; el resto aparece con su banda.
      float target = (i < 4 ? 0.5f : 0.0f) + bands[i] * 1.1f + kick * (i < 6 ? 0.7f : 0.4f);
      power[i] = follow(power[i], target, 25.0f, 5.0f, dt);
      // El golpe fija un destino nuevo y el rayo se desliza hasta él en
      // unas décimas de segundo, como un latigazo continuo.
      if (strike) goal[i] += (rng.unit() - 0.5f) * 2.2f;
      goal[i] += dt * f.speed * (i % 2 ? 1.0f : -1.0f) * (0.08f + 0.25f * drive);
      base[i] += (goal[i] - base[i]) * (1.0f - std::exp(-dt * 9.0f));
    }
    phase += dt * f.speed * (0.6f + 1.4f * drive + 0.6f * kick);
    // Reloj propio del chisporroteo: cambia de forma continua, sin parpadeo.
    crackle += dt * (1.6f + 2.4f * spark);
  }

  void render(const Frame& f, Canvas& c) const override {
    float amp = f.intensity;
    std::array<float, 8> angle{};
    for (int i = 0; i < 8; i++) angle[i] = base[i] + std::sin(phase * 0.35f + seeds[i]) * 0.45f;
    std::vector<float> u;
    u.reserve(44);
    u.insert(u.end(), {phase, bass * amp, kick * amp, energy});
    u.insert(u.end(), {angle[0], angle[1], angle[2], angle[3]});
    u.insert(u.end(), {angle[4], angle[5], angle[6], angle[7]});
    for (int i = 0; i < 8; i++) u.push_back(std::min(power[i] * amp, 2.0f));
    u.insert(u.end(), {spark * amp, flash, f.glow, crackle});
    for (int i = 0; i < 4; i++) u.insert(u.end(), {f.colors[i].r, f.colors[i].g, f.colors[i].b});
    c.material("plasma", {0, 0, f.width, f.height}, u);
  }
};

shaderSources.plasma:
#version 460 core
#include <flutter/runtime_effect.glsl>
uniform vec2 uSize;
uniform vec4 uA;     // tiempo, graves, golpe, energía
uniform vec4 uAng0;
uniform vec4 uAng1;
uniform vec4 uPow0;
uniform vec4 uPow1;
uniform vec4 uM;     // agudos, destello, glow, reloj del chisporroteo
uniform vec3 uC0;
uniform vec3 uC1;
uniform vec3 uC2;
uniform vec3 uC3;
out vec4 fragColor;

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash12(i), hash12(i + vec2(1.0, 0.0)), u.x),
             mix(hash12(i + vec2(0.0, 1.0)), hash12(i + vec2(1.0, 1.0)), u.x), u.y);
}

// Desvío lateral suave del rayo a lo largo de su recorrido (s = 0..1).
float wander(float s, float len, float seed) {
  float t = uA.x;
  float env = sin(3.14159 * s) * (0.55 + 0.45 * s);
  float amp = min(len, 0.7);
  return (sin(s * 6.0 + t * 1.3 + seed * 5.0) * 0.09 + sin(s * 15.0 - t * 2.7 + seed * 11.0) * 0.035) * amp * env;
}

// Rayo de plasma desde `origin` en la dirección `dir`; devuelve (núcleo, halo).
// Lejos del rayo sólo se calcula su halo; la forma y el chisporroteo se
// evalúan cerca, con una transición suave entre ambos cálculos.
vec2 bolt(vec2 p, vec2 origin, vec2 dir, float len, float power, float seed, float width0) {
  vec2 nrm = vec2(-dir.y, dir.x);
  vec2 q = p - origin;
  float along = dot(q, dir);
  float lat0 = dot(q, nrm);
  float beyond = along < 0.0 ? -along : max(along - len, 0.0);
  float reach = 0.13 * min(len, 0.7);
  float k = 0.00005 + 0.0001 * power;
  if (abs(lat0) > reach + 0.2 || beyond > 0.2) {
    return vec2(0.0, k / (lat0 * lat0 + beyond * beyond + 0.0004) * power);
  }
  float s = clamp(along / len, 0.0, 1.0);
  float smoothLat = lat0 - wander(s, len, seed);
  float lateral = smoothLat;
  if (abs(smoothLat) < 0.06) {
    float env = sin(3.14159 * s);
    lateral -= (noise(vec2(s * 40.0 + seed * 3.0, uM.w)) - 0.5) * (0.035 + 0.09 * uM.x) * min(len, 0.7) * env;
  }
  float blend = smoothstep(reach + 0.08, reach + 0.2, abs(lat0));
  float haloLat = mix(smoothLat, lat0, blend);
  float inside = step(0.0, along) * step(along, len);
  float width = (width0 + 0.005 * min(power, 1.5)) * (1.0 - 0.5 * s);
  float core = exp(-lateral * lateral / (width * width)) * inside;
  float halo = k / (haloLat * haloLat + beyond * beyond + 0.0004);
  return vec2(core * 1.5 * power, halo * power);
}

// Rayo principal hasta el borde de la pantalla, con una rama.
vec2 tendril(vec2 p, float ang, float power, float seed, vec2 halfSize) {
  if (power < 0.02) return vec2(0.0);
  vec2 dir = vec2(cos(ang), sin(ang));
  float len = min(halfSize.x / max(abs(dir.x), 0.001), halfSize.y / max(abs(dir.y), 0.001)) * 1.02;
  vec2 acc = bolt(p, vec2(0.0), dir, len, power, seed, 0.004);
  // Punto de contacto con el borde: la descarga ilumina donde toca.
  vec2 tip = dir * len;
  acc.x += exp(-dot(p - tip, p - tip) / (0.0012 + 0.002 * power)) * power;
  if (power > 0.35) {
    float fork = 0.42 + 0.2 * fract(seed * 0.37);
    vec2 nrm = vec2(-dir.y, dir.x);
    vec2 origin = dir * len * fork + nrm * wander(fork, len, seed);
    float side = fract(seed * 0.61) < 0.5 ? -1.0 : 1.0;
    float ba = ang + side * (0.45 + 0.25 * sin(uA.x * 0.7 + seed));
    vec2 bdir = vec2(cos(ba), sin(ba));
    acc += bolt(p, origin, bdir, len * 0.45, power * 0.7, seed + 7.0, 0.0025) * 0.8;
  }
  return acc;
}

void main() {
  vec2 frag = FlutterFragCoord().xy;
  float scale = min(uSize.x, uSize.y);
  vec2 p = (frag - 0.5 * uSize) / scale;
  p.y = -p.y;
  vec2 halfSize = 0.5 * uSize / scale;
  float r = length(p);
  float kick = uA.z;
  float t = uA.x;

  // Sin gas de fondo: sólo los rayos y el núcleo sobre lo que haya detrás.
  vec3 col = uC0;

  vec2 acc = vec2(0.0);
  acc += tendril(p, uAng0.x, uPow0.x, 0.0, halfSize);
  acc += tendril(p, uAng0.y, uPow0.y, 1.7, halfSize);
  acc += tendril(p, uAng0.z, uPow0.z, 3.1, halfSize);
  acc += tendril(p, uAng0.w, uPow0.w, 4.6, halfSize);
  acc += tendril(p, uAng1.x, uPow1.x, 6.2, halfSize);
  acc += tendril(p, uAng1.y, uPow1.y, 7.9, halfSize);
  acc += tendril(p, uAng1.z, uPow1.z, 9.3, halfSize);
  acc += tendril(p, uAng1.w, uPow1.w, 10.8, halfSize);
  vec3 arc = mix(uC1, uC3, clamp(acc.x * 0.55, 0.0, 1.0)) * acc.x + mix(uC2, uC1, 0.4) * acc.y * (0.9 + 0.7 * kick);
  col += arc * (0.9 + 0.7 * uA.y) * uM.z;

  // Núcleo de energía con corona que pulsa con cada golpe.
  float coreR = 0.06 + 0.012 * uA.y + 0.03 * kick;
  float corona = 0.5 + 0.5 * noise(vec2(atan(p.y, p.x) * 3.0, t * 2.0));
  col += mix(uC1, uC3, 0.6) * smoothstep(coreR, coreR * 0.6, r) * (1.4 + 1.6 * kick);
  col += uC1 * (0.002 + 0.006 * kick) / (r * r + 0.003) * (0.7 + 0.3 * corona);

  col *= 1.0 - 0.3 * smoothstep(0.6, 1.4, length(p * vec2(0.9, 0.6)));
  // La curva de tono levanta los negros: la transparencia se decide antes.
  float rawPeak = max(col.r, max(col.g, col.b));
  col = clamp((col * (2.51 * col + 0.03)) / (col * (2.43 * col + 0.59) + 0.14), 0.0, 1.0);
  col = pow(col, vec3(0.4545));
  col *= smoothstep(0.012, 0.05, rawPeak);
  // Fondo transparente: color premultiplicado y opacidad según el brillo; la
  // luz muy tenue se vuelve transparente del todo para no dejar velo.
  col = clamp(col, 0.0, 1.0);
  float veilPeak = max(col.r, max(col.g, col.b));
  float clearCut = smoothstep(0.04, 0.12, veilPeak);
  col *= clearCut;
  float alpha = clamp(veilPeak * 1.25, 0.0, 1.0) * clearCut;
  fragColor = vec4(col, alpha);
}

visuals.nativeSource:
class Visual final : public Scene {
  static constexpr int kLights = 6;
  static constexpr int kBursts = 4;
  static constexpr int kSweeps = 2;
  float bass = 0, spark = 0, slowBass = 0, kick = 0, flash = 0;
  // Relojes en doble precisión: sin música el dibujo es igual a 30 y 60 FPS.
  // clock sigue a Velocidad; secs mide segundos para los golpes.
  double clock = 0, secs = 0;
  std::array<float, kLights> fx{}, fy{}, phx{}, phy{}, rowY{}, speedK{}, sizeK{}, orbitK{};
  // Estallidos: anillo fijo de ranuras {inicio, fuerza, luz}.
  std::array<double, kBursts> burstAt{};
  std::array<float, kBursts> burstPow{};
  std::array<int, kBursts> burstLight{};
  // Barridos lanzados por los golpes: {inicio, fuerza, altura, sentido}.
  std::array<double, kSweeps> sweepAt{};
  std::array<float, kSweeps> sweepPow{}, sweepY{}, sweepDir{};
  uint32_t beats = 0;
  int nextBurst = 0, nextSweep = 0;

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }
  static float hashU(uint32_t x) {
    x ^= x >> 16; x *= 0x7feb352dU; x ^= x >> 15; x *= 0x846ca68bU; x ^= x >> 16;
    return float(x & 0xffffffu) / 16777216.0f;
  }
  // Detalle: cuántas luces hay (3 a 6).
  static int lightCount(float detail) {
    return std::clamp(int(std::lround(2.0f + 2.0f * detail)), 1, kLights);
  }

 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    bass = spark = slowBass = kick = flash = 0;
    clock = double(rng.unit()) * 40.0;
    secs = 0;
    for (int i = 0; i < kLights; i++) {
      const size_t s = size_t(i);
      fx[s] = 0.6f + 0.8f * rng.unit();
      fy[s] = 0.6f + 0.8f * rng.unit();
      phx[s] = rng.unit() * 6.2831853f;
      phy[s] = rng.unit() * 6.2831853f;
      rowY[s] = (float(i) + 0.5f) / float(kLights) * 1.5f - 0.75f + (rng.unit() - 0.5f) * 0.12f;
      speedK[s] = 0.6f + 0.8f * rng.unit();
      sizeK[s] = i == 0 ? 1.55f : 0.6f + 0.45f * rng.unit();
      orbitK[s] = i == 0 ? 0.55f : 0.35f + 0.65f * rng.unit();
    }
    burstAt.fill(-100.0);
    burstPow.fill(0.0f);
    burstLight.fill(0);
    sweepAt.fill(-100.0);
    sweepPow.fill(0.0f);
    sweepY.fill(0.0f);
    sweepDir.fill(1.0f);
    beats = seed;
    nextBurst = nextSweep = 0;
  }

  void update(const Frame& f) override {
    auto m = modifiers(f);
    const float dt = float(f.delta);
    const Music& mu = f.music;
    bass = follow(bass, mu.bass, 22.0f, 4.5f, dt);
    spark = follow(spark, mu.spark, 30.0f, 7.0f, dt);
    float hit = 0, fl = 0;
    for (const auto& e : mu.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : mu.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : mu.events[3]) fl = std::max(fl, e.strength);
    const float onset = std::clamp((mu.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, mu.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    const bool fresh = hit > kick + 0.2f;
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    secs += f.delta;
    // Golpes: cada golpe hace estallar una luz y uno de cada dos lanza un
    // barrido. Sólo ocurre con música.
    if (fresh && m.pulso == 0) {
      const uint32_t k = beats++;
      const uint32_t n = uint32_t(lightCount(f.detail));
      const size_t b = size_t(nextBurst);
      burstAt[b] = secs;
      burstPow[b] = hit;
      burstLight[b] = int(k % n);
      nextBurst = (nextBurst + 1) % kBursts;
      if (k % 2u == 0u) {
        const size_t w = size_t(nextSweep);
        sweepAt[w] = secs;
        sweepPow[w] = hit;
        sweepY[w] = hashU(k * 2654435761u + 7u) * 2.0f - 1.0f;
        sweepDir[w] = (k / 2u) % 2u == 0u ? 1.0f : -1.0f;
        nextSweep = (nextSweep + 1) % kSweeps;
      }
    }
    clock += f.delta * f.speed;
  }

  void render(const Frame& f, Canvas& c) const override {
    auto g = glide(f);
    const float amp = f.intensity;
    const float side = std::min(f.width, f.height);
    const float halfW = 0.5f * f.width / side, halfH = 0.5f * f.height / side;
    const float t = float(std::fmod(clock, 10000.0));
    const float rt = float(std::fmod(secs, 1000.0));
    const float wDeriva = g.recorrido.weight(0), wBarrido = g.recorrido.weight(1), wOrbita = g.recorrido.weight(2);
    const float wGolpes = g.pulso.weight(0), wGraves = g.pulso.weight(1), wBrillos = g.pulso.weight(2);
    const int count = lightCount(f.detail);
    // Pulso: cada opción mueve algo distinto (todo vale 0 sin música).
    const float punch = wGolpes * std::min(kick * amp, 1.0f);
    const float graves = wGraves * std::min(bass * amp, 1.2f);
    const float brillos = wBrillos * std::min((spark + 0.4f * flash) * amp, 1.2f);
    std::vector<float> u;
    u.reserve(80);
    u.insert(u.end(), {t, std::clamp(f.glow, 0.0f, 2.0f), std::clamp(g.reflejos, 0.0f, 1.0f), rt});
    // Pesos de la lente y el centelleo de fondo (también en silencio).
    u.insert(u.end(), {g.lente.weight(0), g.lente.weight(1), g.lente.weight(2), 0.16f});
    std::array<float, kLights> lx{}, ly{};
    for (int i = 0; i < kLights; i++) {
      const size_t s = size_t(i);
      // Deriva: curvas de Lissajous lentas por toda la pantalla.
      const float dx = halfW * 0.72f * std::sin(t * 0.13f * fx[s] + phx[s]);
      const float dy = halfH * 0.72f * std::sin(t * 0.11f * fy[s] + phy[s]);
      // Barrido: cada luz cruza de lado a lado en su carril.
      const float run = float(std::fmod(double(t) * 0.06 * double(speedK[s]) + double(phx[s]) / 6.2831853, 1.0));
      const float bx = (run * 2.0f - 1.0f) * (halfW + 0.45f);
      const float by = rowY[s] * halfH;
      // Órbita: elipses alrededor del centro; los fantasmas giran al revés.
      const float ang = t * 0.2f * (0.6f + 0.4f * speedK[s]) + phx[s];
      const float ox = std::cos(ang) * halfW * 0.85f * orbitK[s];
      const float oy = std::sin(ang) * halfH * 0.6f * orbitK[s];
      lx[s] = wDeriva * dx + wBarrido * bx + wOrbita * ox;
      ly[s] = wDeriva * dy + wBarrido * by + wOrbita * oy;
      // Cada luz respira despacio por su cuenta.
      float I = (i == 0 ? 1.2f : 0.68f) + 0.22f * std::sin(t * 0.5f + float(i) * 1.7f);
      I *= 1.0f + 0.45f * punch;
      I *= 1.0f + (i == 0 ? 0.9f : 0.25f) * graves;
      I *= 1.0f + 0.8f * brillos * (0.5f + 0.5f * std::sin(rt * 23.0f + float(i) * 3.1f));
      if (i >= count) I = 0.0f;
      // Tamaño: la principal crece un 22 % con los graves; el golpe, un 12 %.
      const float size = sizeK[s] * (1.0f + (i == 0 ? 0.22f * graves : 0.0f) + 0.12f * punch);
      u.insert(u.end(), {lx[s], ly[s], std::clamp(I, 0.0f, 3.0f), size});
    }
    // Estallidos de los golpes: siguen a su luz y se apagan en ~1,5 s.
    for (int j = 0; j < kBursts; j++) {
      const size_t s = size_t(j);
      const float age = float(std::min(secs - burstAt[s], 100.0));
      const size_t li = size_t(burstLight[s] < count ? burstLight[s] : 0);
      const float power = age < 3.0f ? std::min(burstPow[s] * amp, 1.2f) * wGolpes : 0.0f;
      u.insert(u.end(), {lx[li], ly[li], std::max(age, 0.0f), power});
    }
    // Barrido de reposo: cada 7 s una luz cruza la pantalla (también en silencio).
    const double period = 7.0;
    const double lap = std::floor(clock / period);
    const float idle = float((clock - lap * period) / 1.9);
    const uint32_t li = uint32_t(int64_t(lap) & 0x7fffffff);
    {
      const float dir = hashU(li * 747796405u + 1u) < 0.5f ? 1.0f : -1.0f;
      const float y = (hashU(li * 2891336453u + 5u) * 2.0f - 1.0f) * 0.7f * halfH;
      const float x = dir * (-(halfW + 0.5f) + 2.0f * (halfW + 0.5f) * std::min(idle, 1.0f));
      const float power = idle < 1.0f ? 0.8f * std::sin(3.1415927f * idle) : 0.0f;
      u.insert(u.end(), {x, y, std::max(power, 0.0f), 1.0f});
    }
    // Barridos de los golpes: más rápidos y con la raya más larga.
    for (int j = 0; j < kSweeps; j++) {
      const size_t s = size_t(j);
      const float run = float(std::min(secs - sweepAt[s], 100.0)) / 0.95f;
      const float x = sweepDir[s] * (-(halfW + 0.5f) + 2.0f * (halfW + 0.5f) * std::clamp(run, 0.0f, 1.0f));
      const float power = run < 1.0f ? std::min(sweepPow[s] * amp, 1.2f) * wGolpes * std::sin(3.1415927f * std::max(run, 0.0f)) : 0.0f;
      u.insert(u.end(), {x, sweepY[s] * 0.75f * halfH, std::max(power, 0.0f), 1.35f});
    }
    u.insert(u.end(), {std::min(graves, 1.2f), brillos, punch, std::min(flash * amp, 1.0f) * wBrillos});
    for (int i = 1; i < 4; i++) u.insert(u.end(), {f.colors[size_t(i)].r, f.colors[size_t(i)].g, f.colors[size_t(i)].b});
    c.material("lens_flares", {0, 0, f.width, f.height}, u);
  }
};

shaderSources.lens_flares:
#version 460 core
#include <flutter/runtime_effect.glsl>
uniform vec2 uSize;
uniform vec4 uA;   // reloj, glow, reflejos, reloj real
uniform vec4 uB;   // lente: anamórfica, estrella, arco; centelleo de fondo
uniform vec4 uL0;  // luces: x, y, intensidad, tamaño
uniform vec4 uL1;
uniform vec4 uL2;
uniform vec4 uL3;
uniform vec4 uL4;
uniform vec4 uL5;
uniform vec4 uK0;  // estallidos: x, y, edad, fuerza
uniform vec4 uK1;
uniform vec4 uK2;
uniform vec4 uK3;
uniform vec4 uW0;  // barridos: x, y, fuerza, largo
uniform vec4 uW1;
uniform vec4 uW2;
uniform vec4 uM;   // graves, brillos, golpe, destello de agudos
uniform vec3 uC1;
uniform vec3 uC2;
uniform vec3 uC3;
out vec4 fragColor;

const float TAU = 6.2831853;

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

float gauss(float x, float w) {
  float k = x / w;
  return exp(-k * k);
}

// Degradado de la raya: núcleo blanco, azul claro y azul anamórfico intenso
// que se oscurece hacia las puntas.
vec3 streakTint(float t) {
  vec3 pale = mix(uC1, uC3, 0.45);
  vec3 c = mix(uC3, pale, smoothstep(0.0, 0.1, t));
  c = mix(c, uC1, smoothstep(0.1, 0.45, t));
  return mix(c, uC1 * 0.7, smoothstep(0.45, 1.0, t));
}

// Raya: una línea fina casi blanca, un cuerpo de color saturado y un brillo
// ancho y tenue; del centro a las puntas pasa de azul claro a azul intenso.
vec3 streak(float across, float along, float len, float thick) {
  // Lejos de la raya no aporta nada: se ahorra el cálculo.
  if (abs(across) > 0.18 * thick) return vec3(0.0);
  float t = along / (len * 1.5);
  float thin = gauss(across, 0.0036 * thick) * (exp(-along / len) + 0.3 * exp(-along / (len * 3.2)));
  float body = gauss(across, 0.013 * thick) * (exp(-along / (len * 0.8)) + 0.2 * exp(-along / (len * 3.0)));
  float wide = gauss(across, 0.05 * thick) * exp(-along / (len * 0.6));
  return streakTint(t) * thin + streakTint(t + 0.3) * body * 0.55 + uC1 * wide * 0.16;
}

// Fantasma de radio 1: óvalo (anamórfica), hexágono (estrella) o círculo
// (arco), con el borde suave y un aro algo más brillante.
float ghostShape(vec2 q) {
  float oval = length(q * vec2(1.5, 0.82));
  float hexa = max(abs(q.y), abs(q.x) * 0.8660254 + abs(q.y) * 0.5);
  float circ = length(q);
  float d = uB.x * oval + uB.y * hexa + uB.z * circ;
  float body = 1.0 - smoothstep(0.7, 1.0, d);
  return body * (0.16 + 0.84 * smoothstep(0.35, 0.93, d));
}

// Aberración cromática: el rojo sale más grande y el azul más pequeño.
vec3 ghost(vec2 p, vec2 at, float radius, vec3 tint) {
  vec2 q = (p - at) / radius;
  if (dot(q, q) > 2.6) return vec3(0.0);
  return tint * vec3(ghostShape(q * 0.93), ghostShape(q), ghostShape(q * 1.07));
}

// Cadena de fantasmas en la recta que une la luz con el centro.
vec3 ghosts(vec2 p, vec4 L) {
  float I = L.z * uA.z;
  if (I < 0.003) return vec3(0.0);
  vec2 c = L.xy;
  float s = L.w;
  vec3 acc = ghost(p, c * -0.42, 0.055 * s, uC1) * 0.34;
  acc += ghost(p, c * -0.85, 0.11 * s, mix(uC2, uC3, 0.25)) * 0.18;
  acc += ghost(p, c * 0.38, 0.03 * s, mix(uC2, uC3, 0.35)) * 0.45;
  acc += ghost(p, c * -1.35, 0.17 * s, uC2) * 0.1;
  acc += ghost(p, c * -0.18, 0.02 * s, mix(uC1, uC3, 0.5)) * 0.45;
  return acc * I;
}

// Aro de arcoíris alrededor del centro óptico.
vec3 halo(vec2 p, vec4 L, float boost) {
  float I = L.z * uA.z * (0.07 + 0.1 * boost);
  if (I < 0.003) return vec3(0.0);
  float R = 0.26 + 0.55 * length(L.xy);
  float r = length(p + L.xy * 0.15);
  float w = 0.008 + 0.01 * uB.z;
  vec3 ring = vec3(gauss(r - R * 1.035, w), gauss(r - R, w), gauss(r - R * 0.965, w));
  return ring * mix(uC3, uC2, 0.35) * I;
}

vec3 light(vec2 p, vec4 L, float thick, float lenK) {
  float I = L.z;
  if (I < 0.003) return vec3(0.0);
  float s = L.w;
  vec2 d = p - L.xy;
  float r2 = dot(d, d);
  float r = sqrt(r2);
  // Núcleo blanco y halo suave, sin bordes.
  vec3 col = uC3 * I * (1.3 * exp(-r2 / (0.00011 * s * s)) + 0.45 * exp(-r2 / (0.0011 * s * s)));
  col += mix(uC1, uC3, 0.3) * I * 0.2 * uA.y * exp(-r / (0.05 * s));
  // Brillo ovalado, más ancho que alto, como el de una lente anamórfica.
  col += uC1 * I * 0.16 * uA.y * exp(-length(d * vec2(0.4, 1.7)) / (0.06 * s));
  // Raya recta: larga en Anamórfica, más corta en Estrella.
  float straight = uB.x + uB.y;
  if (straight > 0.001) {
    float len = 0.3 * s * lenK * (uB.x + 0.45 * uB.y) / straight;
    float ax = abs(d.x);
    col += streak(d.y, ax, len, thick) * I * straight;
  }
  if (uB.y > 0.001) {
    // Estrella de difracción de seis puntas, alternando largas y cortas.
    float a = atan(d.y, d.x) * (6.0 / TAU) + 0.5;
    float off = abs(fract(a) - 0.5) * (TAU / 6.0);
    float longer = mod(floor(a), 2.0) < 0.5 ? 1.0 : 0.5;
    float spikes = gauss(r * off, 0.0026 * s * thick * (1.0 + 3.0 * r)) * exp(-r / (0.09 * s * longer * lenK));
    col += mix(uC3, uC1, smoothstep(0.0, 0.25, r)) * spikes * I * uB.y;
  }
  if (uB.z > 0.001) {
    // Arco: la raya sigue un círculo alrededor del centro de la imagen.
    float lr = length(L.xy);
    vec2 n = lr > 0.001 ? L.xy / lr : vec2(0.0, 1.0);
    float R = 0.32 + 0.7 * lr;
    vec2 e = p - (L.xy - n * R);
    float er = max(length(e), 0.0001);
    float along = acos(clamp(dot(e / er, n), -1.0, 1.0)) * R;
    float len = 0.2 * s * lenK;
    col += streak(er - R, along, len, thick) * I * uB.z;
  }
  return col;
}

// Estallido de un golpe: destello, estrella de ocho puntas, onda irisada que
// se abre y una raya horizontal muy larga.
vec3 burst(vec2 p, vec4 K) {
  if (K.w < 0.003) return vec3(0.0);
  vec2 d = p - K.xy;
  float r = length(d);
  if (r > 0.9 && abs(d.y) > 0.03) return vec3(0.0);
  float age = K.z;
  float grow = 1.0 - exp(-age * 3.2);
  float R = 0.03 + 0.36 * grow;
  float w = 0.006 + 0.024 * grow;
  vec3 ring = vec3(gauss(r - R * 1.05, w), gauss(r - R, w), gauss(r - R * 0.95, w));
  vec3 col = ring * mix(uC3, uC2, 0.55) * exp(-age * 2.6) * 0.6;
  float a = atan(d.y, d.x) * (8.0 / TAU) + 0.5;
  float off = abs(fract(a) - 0.5) * (TAU / 8.0);
  float longer = mod(floor(a), 2.0) < 0.5 ? 1.0 : 0.55;
  float spikes = gauss(r * off, 0.003 + 0.012 * r) * exp(-r / ((0.04 + 0.2 * grow) * longer)) * exp(-age * 2.0);
  col += mix(uC3, uC1, smoothstep(0.0, 0.2, r)) * spikes;
  col += uC3 * exp(-r * r / (0.0016 * (1.0 + age * 3.0))) * exp(-age * 4.0) * 1.4;
  col += streakTint(abs(d.x) / 1.2) * gauss(d.y, 0.0045) * exp(-abs(d.x) / 0.5) * exp(-age * 2.4) * 1.2;
  return col * K.w;
}

// Barrido: una luz rápida que cruza la pantalla con su raya y un brillo ancho.
vec3 sweep(vec2 p, vec4 W) {
  if (W.z < 0.003) return vec3(0.0);
  vec2 d = p - W.xy;
  if (abs(d.y) > 0.2) return vec3(0.0);
  float ax = abs(d.x);
  float len = 0.42 * W.w;
  float r2 = dot(d, d);
  float core = exp(-r2 / 0.0003) * 1.6 + exp(-r2 / 0.004) * 0.45;
  float band = gauss(d.y, 0.06) * exp(-ax / (len * 1.4)) * 0.22;
  return (uC3 * core + streak(d.y, ax, len, 1.0) + uC2 * band) * W.z;
}

// Destellos de cuatro puntas que centellean en celdas repartidas.
vec3 glints(vec2 p, float level, float time) {
  if (level < 0.003) return vec3(0.0);
  float cell = 0.12;
  vec2 id = floor(p / cell);
  float h = hash12(id + 17.0);
  if (h < 0.4) return vec3(0.0);
  vec2 at = (id + 0.3 + 0.4 * vec2(hash12(id + 3.1), hash12(id + 7.7))) * cell;
  vec2 d = p - at;
  float tw = max(sin(time * (2.5 + 5.0 * h) + h * 40.0), 0.0);
  tw = tw * tw * tw * tw;
  float star = exp(-dot(d, d) / 0.00004) +
               0.7 * (gauss(d.y, 0.0016) * exp(-abs(d.x) / 0.011) + gauss(d.x, 0.0016) * exp(-abs(d.y) / 0.011));
  vec3 tint = mix(mix(uC3, uC1, hash12(id + 9.0) * 0.7), uC2, step(0.72, hash12(id + 5.0)));
  return tint * star * tw * level;
}

void main() {
  vec2 frag = FlutterFragCoord().xy;
  float scale = min(uSize.x, uSize.y);
  vec2 p = (frag - 0.5 * uSize) / scale;
  float graves = uM.x;
  float punch = uM.z;
  // Graves engruesan las rayas; el golpe las alarga.
  float thick = 1.0 + 1.1 * graves + 0.4 * punch;
  float lenK = 1.0 + 0.6 * punch + 0.25 * graves + 0.02 * sin(uA.x * 0.7);
  vec3 col = light(p, uL0, thick, lenK) + light(p, uL1, thick, lenK) + light(p, uL2, thick, lenK) +
             light(p, uL3, thick, lenK) + light(p, uL4, thick, lenK) + light(p, uL5, thick, lenK);
  col += ghosts(p, uL0) * (1.0 + 1.2 * graves) + ghosts(p, uL1) + ghosts(p, uL2);
  col += halo(p, uL0, graves);
  col += burst(p, uK0) + burst(p, uK1) + burst(p, uK2) + burst(p, uK3);
  col += sweep(p, uW0) + sweep(p, uW1) + sweep(p, uW2);
  // Los barridos también dejan su cadena de fantasmas al cruzar.
  col += ghosts(p, vec4(uW0.xy, uW0.z, 1.0)) + ghosts(p, vec4(uW1.xy, uW1.z, 1.2)) + ghosts(p, vec4(uW2.xy, uW2.z, 1.2));
  col += glints(p, uB.w + 1.5 * uM.y + 0.6 * uM.w, uA.w);
  // La luz intensa se vuelve blanca sin quemar.
  col = vec3(1.0) - exp(-col * 1.15);
  // Sin fondo: color premultiplicado y opacidad según el brillo; lo muy
  // tenue se desvanece del todo para no dejar velo.
  float veilPeak = max(col.r, max(col.g, col.b));
  float clearCut = smoothstep(0.0, 0.035, veilPeak);
  float alpha = clamp(veilPeak * 1.15, 0.0, 1.0) * clearCut;
  col = min(col * clearCut, vec3(alpha));
  fragColor = vec4(col, alpha);
}

visuals.nativeSource:
class Visual final : public Scene {
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  // Relojes en doble precisión: la escena sin música es idéntica a 30 y 60 FPS.
  double angA = 0, angB = 0, clock = 0, sinceShape = 0;
  float morph = 1;
  int beats = 0, autoShape = 0, shapeFrom = 0, shapeTo = 0;
  // Salto del último golpe.
  double hopAge = 100;
  float hopPow = 0;

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    angA = rng.unit() * 6.28;
    angB = rng.unit() * 6.28;
    clock = 0;
    sinceShape = 0;
    morph = 1;
    beats = 0;
    autoShape = shapeFrom = shapeTo = 0;
    hopAge = 100;
    hopPow = 0;
  }

  void update(const Frame& f) override {
    auto m = modifiers(f);
    float dt = float(f.delta);
    const Music& mu = f.music;
    bass = follow(bass, mu.bass, 22.0f, 4.5f, dt);
    body = follow(body, mu.body, 12.0f, 3.0f, dt);
    spark = follow(spark, mu.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, mu.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, mu.active ? std::pow(std::clamp(mu.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : mu.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : mu.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : mu.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((mu.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, mu.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    sinceShape += f.delta;
    hopAge += f.delta;
    if (hit > kick + 0.2f) {
      beats++;
      hopAge = 0.0;
      hopPow = hit;
      if (beats % 8 == 0) {
        autoShape = (autoShape + 1) % 4;
        sinceShape = 0;
      }
    }
    // La transformación avanza antes de mirar cambios: si el cambio es por
    // tiempo, empieza en su instante exacto (igual a 30 y 60 FPS).
    morph = std::min(1.0f, morph + dt / 1.2f);
    double carry = -1.0;
    if (!mu.active && sinceShape > 8.0) {
      autoShape = (autoShape + 1) % 4;
      sinceShape -= 8.0;
      carry = sinceShape;
    }
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    int wanted = m.figura == 0 ? autoShape : m.figura - 1;
    if (wanted != shapeTo) {
      shapeFrom = shapeTo;
      shapeTo = wanted;
      morph = carry >= 0.0 ? std::min(1.0f, float(carry / 1.2)) : 0.0f;
    }
    double spin = f.delta * f.speed * m.giro * (1.0 + 1.5 * drive + 1.5 * kick);
    angA += spin * 0.7;
    angB += spin * 0.35;
    clock += f.delta * f.speed;
  }

  void render(const Frame& f, Canvas& c) const override {
    auto m = modifiers(f);
    auto g = glide(f);
    float amp = f.intensity;
    std::vector<float> u;
    u.reserve(32);
    u.insert(u.end(), {float(std::fmod(angA, 6.2831853)), float(std::fmod(angB, 6.2831853)), float(std::fmod(clock, 1000.0)), morph});
    u.insert(u.end(), {float(shapeFrom), float(shapeTo), float(m.columnas), 0.0f});
    u.insert(u.end(), {bass * amp, kick * amp, spark * amp, energy});
    // Caracteres: pesos de Binario y Bloques (ASCII es el resto); se funden al cambiar.
    u.insert(u.end(), {f.glow, flash * amp, std::clamp(g.caracteres.weight(1), 0.0f, 1.0f),
                       std::clamp(g.caracteres.weight(2), 0.0f, 1.0f)});
    // Giro y mezcla de figuras ya calculados: el rayo sólo suma.
    float ca = float(std::cos(angA)), sa = float(std::sin(angA)), cb = float(std::cos(angB)), sb = float(std::sin(angB));
    u.insert(u.end(), {ca, sa, cb, sb});
    std::array<float, 4> w{0, 0, 0, 0};
    float e = morph * morph * (3.0f - 2.0f * morph);
    w[size_t(shapeFrom)] += 1.0f - e;
    w[size_t(shapeTo)] += e;
    u.insert(u.end(), {w[0], w[1], w[2], w[3]});
    // Pulso: cada opción mueve algo distinto; sin música todo vale cero.
    // Golpes: un salto que sube y baja en 0,42 s.
    const float hopArc = hopAge < 0.42 ? std::sin(float(hopAge / 0.42) * 3.1415927f) : 0.0f;
    u.insert(u.end(), {std::min(kick * amp, 1.0f) * g.pulso.weight(0), std::min(bass * amp, 1.0f) * g.pulso.weight(1),
                       std::min(spark * amp, 1.0f) * g.pulso.weight(2), std::min(hopPow * amp, 1.0f) * hopArc * g.pulso.weight(0)});
    for (int i = 0; i < 4; i++) u.insert(u.end(), {f.colors[i].r, f.colors[i].g, f.colors[i].b});
    c.material("ascii_donut", {0, 0, f.width, f.height}, u);
  }
};

shaderSources.ascii_donut:
#version 460 core
#include <flutter/runtime_effect.glsl>
uniform vec2 uSize;
uniform vec4 uA;   // ángulo A, ángulo B, reloj, transformación
uniform vec4 uB;   // figura anterior, figura nueva, columnas
uniform vec4 uM;   // graves, golpe, agudos, energía
uniform vec4 uD;   // glow, destello, peso de Binario, peso de Bloques
uniform vec4 uR;   // giro: cos A, sen A, cos B, sen B
uniform vec4 uW;   // peso de cada figura: dona, esfera, cubo, octaedro
uniform vec4 uP;   // pulso: golpe, graves, agudos, salto
uniform vec3 uC0;
uniform vec3 uC1;
uniform vec3 uC2;
uniform vec3 uC3;
out vec4 fragColor;

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

// Los doce caracteres de donut.c en mapas de bits de 5×7: filas 0–3 en x y
// filas 4–6 en y, cinco bits por fila.
vec2 glyph(float i) {
  if (i < 0.5) return vec2(0.0, 396.0);
  if (i < 1.5) return vec2(0.0, 12424.0);
  if (i < 2.5) return vec2(31.0, 0.0);
  if (i < 3.5) return vec2(277.0, 2048.0);
  if (i < 4.5) return vec2(12672.0, 12672.0);
  if (i < 5.5) return vec2(12672.0, 12424.0);
  if (i < 6.5) return vec2(992.0, 31744.0);
  if (i < 7.5) return vec2(135300.0, 4100.0);
  if (i < 8.5) return vec2(21983.0, 15008.0);
  if (i < 9.5) return vec2(338922.0, 32074.0);
  if (i < 10.5) return vec2(147086.0, 6084.0);
  return vec2(476917.0, 24078.0);
}

float bitmapBit(vec2 code, vec2 uv) {
  vec2 g = floor(uv * vec2(6.0, 8.0));
  if (g.x > 4.5 || g.y > 6.5) return 0.0;
  float val = g.y < 3.5 ? code.x : code.y;
  float shift = g.y < 3.5 ? (3.0 - g.y) * 5.0 + (4.0 - g.x) : (6.0 - g.y) * 5.0 + (4.0 - g.x);
  return mod(floor(val / exp2(shift)), 2.0);
}

float glyphBit(float i, vec2 uv) {
  return bitmapBit(glyph(i), uv);
}

// Binario: un 0 o un 1 por celda que cambia de vez en cuando, como datos; la
// luz la da el brillo de la tinta.
float binaryBit(vec2 cell, vec2 uv) {
  float flip = floor(uA.z * 1.5 + hash12(cell * 0.37) * 6.0);
  vec2 code = hash12(cell + flip * 13.7) < 0.5 ? vec2(476789.0, 26158.0) : vec2(143492.0, 4238.0);
  return bitmapBit(code, uv);
}

float bayer2(vec2 a) {
  a = floor(a);
  return fract(a.x * 0.5 + a.y * a.y * 0.75);
}

// Bloques: ░ ▒ ▓ █ de terminal, una trama ordenada que llena la celda según
// la luz.
float blockBit(float lum, vec2 uv) {
  vec2 g = floor(uv * vec2(6.0, 8.0));
  if (g.x > 4.5 || g.y > 6.5) return 0.0;
  float level = (floor(lum * 3.99) + 1.0) * 0.25;
  float threshold = bayer2(g * 0.5) * 0.25 + bayer2(g);
  return step(threshold, level - 0.01);
}

// El carácter de la celda con la mezcla de juegos de caracteres elegida.
float charBit(float idx, float lum, vec2 cell, vec2 uv) {
  float wBin = uD.z;
  float wBlk = uD.w;
  float wAscii = max(0.0, 1.0 - wBin - wBlk);
  float on = 0.0;
  if (wAscii > 0.001) on += wAscii * glyphBit(idx, uv);
  if (wBin > 0.001) on += wBin * binaryBit(cell, uv);
  if (wBlk > 0.001) on += wBlk * blockBit(lum, uv);
  return on;
}

vec3 rotate(vec3 p) {
  p = vec3(p.x, uR.x * p.y - uR.y * p.z, uR.y * p.y + uR.x * p.z);
  return vec3(uR.z * p.x - uR.w * p.y, uR.w * p.x + uR.z * p.y, p.z);
}

// Las cuatro figuras mezcladas por peso (sin ramas: siempre el mismo coste).
float scene(vec3 p) {
  float k = 1.0 + min(0.12 * uM.y + 0.14 * uP.y + 0.06 * uP.x, 0.25);
  vec3 q = rotate(p) / k;
  float torus = length(vec2(length(q.xz) - 1.0, q.y)) - 0.45;
  float sphere = length(q) - 1.15;
  vec3 d = abs(q) - vec3(0.85);
  float box = length(max(d, 0.0)) + min(max(d.x, max(d.y, d.z)), 0.0) - 0.08;
  vec3 a = abs(q);
  float octa = (a.x + a.y + a.z - 1.35) * 0.577;
  return dot(uW, vec4(torus, sphere, box, octa)) * k;
}

void main() {
  vec2 frag = FlutterFragCoord().xy;
  float cw = uSize.x / uB.z;
  vec2 cellSize = vec2(cw, cw * 8.0 / 6.0);
  vec2 cell = floor(frag / cellSize);
  vec2 cellUv = fract(frag / cellSize);
  vec2 centerPx = (cell + 0.5) * cellSize;
  float scale = min(uSize.x, uSize.y);
  vec2 uv = (centerPx - 0.5 * uSize) / scale * 1.9;
  // Golpes: la figura salta hacia arriba.
  uv.y += uP.w * 0.22;
  // Un rayo por celda contra la figura.
  vec3 ro = vec3(0.0, 0.0, -4.2);
  vec3 rd = normalize(vec3(uv, 2.2));
  float t = 0.0;
  float hit = 0.0;
  for (int i = 0; i < 32; i++) {
    float d = scene(ro + rd * t);
    if (d < 0.002) {
      hit = 1.0;
      break;
    }
    t += d;
    if (t > 8.0) break;
  }
  vec3 col = uC0;
  float lum = 0.0;
  if (hit > 0.5) {
    vec3 p = ro + rd * t;
    vec2 e = vec2(0.003, -0.003);
    vec3 n = normalize(e.xyy * scene(p + e.xyy) + e.yyx * scene(p + e.yyx) + e.yxy * scene(p + e.yxy) + e.xxx * scene(p + e.xxx));
    lum = clamp(dot(n, normalize(vec3(0.35, -0.8, -0.6))), 0.0, 1.0);
    lum = clamp(lum * (0.9 + 0.35 * uM.x) + 0.08 + 0.35 * uP.x, 0.0, 1.0);
  }
  // Chispas de los agudos: celdas sueltas que se encienden con @.
  float sparkle = step(0.994 - 0.02 * uM.z - 0.08 * uP.z, hash12(cell + floor(uA.z * 12.0)));
  float idx = floor(lum * 11.99);
  float on = 0.0;
  if (hit > 0.5) on = charBit(idx, lum, cell, cellUv);
  float sp = sparkle * (1.0 - hit) * charBit(11.0, 1.0, cell, cellUv) * uM.z;
  // Tinta ámbar del monitor: más clara donde llega más luz.
  vec3 ink = uC1 * (0.45 + 0.75 * lum);
  col += ink * on * (1.0 + 0.4 * uM.y + 1.0 * uP.x + 0.4 * uP.y);
  // Las chispas en el tono claro de la paleta y el destello en su naranja.
  col += uC3 * sp * 0.8;
  // Agudos: muchas celdas de la figura que destellan con @.
  if (uP.z > 0.001) {
    float glint = step(0.8 - 0.25 * uP.z, hash12(cell * 1.37 + floor(uA.z * 18.0) + 3.1)) * hit;
    col += uC3 * glint * charBit(11.0, 1.0, cell, cellUv) * 0.9 * uP.z;
  }
  // Resplandor del monitor detrás de cada carácter.
  col += ink * hit * lum * 0.12 * uD.x;
  // Graves: el resplandor ámbar respira.
  col += ink * hit * lum * 0.7 * uP.y;
  // Resplandor alrededor de la figura (que sigue su salto): Golpes lo
  // enciende y Graves lo hace latir.
  vec2 q = (frag - 0.5 * uSize) / scale * 1.9;
  q.y += uP.w * 0.22;
  col += uC2 * exp(-dot(q, q) * 1.6) * (0.32 * uP.x + 0.2 * uP.y) * min(uD.x, 1.5);
  // Líneas de barrido y viñeta de tubo.
  col *= 0.86 + 0.14 * sin(frag.y * 1.9);
  vec2 p0 = (frag - 0.5 * uSize) / scale;
  col *= 1.0 - 0.45 * smoothstep(0.5, 1.4, length(p0 * vec2(0.9, 0.6)));
  col += uC2 * uD.y * 0.05;
  col += (hash12(frag) - 0.5) / 255.0;
  fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

visuals.nativeSource:
class Visual final : public Scene {
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  // Relojes en doble precisión: la escena sin música es idéntica a 30 y 60 FPS.
  double angA = 0, angB = 0, clock = 0, sinceShape = 0;
  float morph = 1;
  int beats = 0, autoShape = 0, shapeFrom = 0, shapeTo = 0;
  // Salto del último golpe.
  double hopAge = 100;
  float hopPow = 0;

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    angA = rng.unit() * 6.28;
    angB = rng.unit() * 6.28;
    clock = 0;
    sinceShape = 0;
    morph = 1;
    beats = 0;
    autoShape = shapeFrom = shapeTo = 0;
    hopAge = 100;
    hopPow = 0;
  }

  void update(const Frame& f) override {
    auto m = modifiers(f);
    float dt = float(f.delta);
    const Music& mu = f.music;
    bass = follow(bass, mu.bass, 22.0f, 4.5f, dt);
    body = follow(body, mu.body, 12.0f, 3.0f, dt);
    spark = follow(spark, mu.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, mu.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, mu.active ? std::pow(std::clamp(mu.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : mu.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : mu.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : mu.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((mu.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, mu.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    sinceShape += f.delta;
    hopAge += f.delta;
    if (hit > kick + 0.2f) {
      beats++;
      hopAge = 0.0;
      hopPow = hit;
      if (beats % 8 == 0) {
        autoShape = (autoShape + 1) % 4;
        sinceShape = 0;
      }
    }
    // La transformación avanza antes de mirar cambios: si el cambio es por
    // tiempo, empieza en su instante exacto (igual a 30 y 60 FPS).
    morph = std::min(1.0f, morph + dt / 1.2f);
    double carry = -1.0;
    if (!mu.active && sinceShape > 8.0) {
      autoShape = (autoShape + 1) % 4;
      sinceShape -= 8.0;
      carry = sinceShape;
    }
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    int wanted = m.figura == 0 ? autoShape : m.figura - 1;
    if (wanted != shapeTo) {
      shapeFrom = shapeTo;
      shapeTo = wanted;
      morph = carry >= 0.0 ? std::min(1.0f, float(carry / 1.2)) : 0.0f;
    }
    double spin = f.delta * f.speed * m.giro * (1.0 + 1.5 * drive + 1.5 * kick);
    angA += spin * 0.7;
    angB += spin * 0.35;
    clock += f.delta * f.speed;
  }

  void render(const Frame& f, Canvas& c) const override {
    auto m = modifiers(f);
    auto g = glide(f);
    float amp = f.intensity;
    std::vector<float> u;
    u.reserve(32);
    u.insert(u.end(), {float(std::fmod(angA, 6.2831853)), float(std::fmod(angB, 6.2831853)), float(std::fmod(clock, 1000.0)), morph});
    u.insert(u.end(), {float(shapeFrom), float(shapeTo), float(m.columnas), 0.0f});
    u.insert(u.end(), {bass * amp, kick * amp, spark * amp, energy});
    // Caracteres: pesos de Binario y Bloques (ASCII es el resto); se funden al cambiar.
    u.insert(u.end(), {f.glow, flash * amp, std::clamp(g.caracteres.weight(1), 0.0f, 1.0f),
                       std::clamp(g.caracteres.weight(2), 0.0f, 1.0f)});
    // Giro y mezcla de figuras ya calculados: el rayo sólo suma.
    float ca = float(std::cos(angA)), sa = float(std::sin(angA)), cb = float(std::cos(angB)), sb = float(std::sin(angB));
    u.insert(u.end(), {ca, sa, cb, sb});
    std::array<float, 4> w{0, 0, 0, 0};
    float e = morph * morph * (3.0f - 2.0f * morph);
    w[size_t(shapeFrom)] += 1.0f - e;
    w[size_t(shapeTo)] += e;
    u.insert(u.end(), {w[0], w[1], w[2], w[3]});
    // Pulso: cada opción mueve algo distinto; sin música todo vale cero.
    // Golpes: un salto que sube y baja en 0,42 s.
    const float hopArc = hopAge < 0.42 ? std::sin(float(hopAge / 0.42) * 3.1415927f) : 0.0f;
    u.insert(u.end(), {std::min(kick * amp, 1.0f) * g.pulso.weight(0), std::min(bass * amp, 1.0f) * g.pulso.weight(1),
                       std::min(spark * amp, 1.0f) * g.pulso.weight(2), std::min(hopPow * amp, 1.0f) * hopArc * g.pulso.weight(0)});
    for (int i = 0; i < 4; i++) u.insert(u.end(), {f.colors[i].r, f.colors[i].g, f.colors[i].b});
    c.material("ascii_donut", {0, 0, f.width, f.height}, u);
  }
};

