#version 460 core
#include <flutter/runtime_effect.glsl>
uniform vec2 uSize;
uniform vec4 uA;   // ángulo A, ángulo B, reloj, transformación
uniform vec4 uB;   // figura anterior, figura nueva, columnas
uniform vec4 uM;   // graves, golpe, agudos, energía
uniform vec4 uD;   // glow, destello, peso de Binario, peso de Bloques
uniform vec4 uR;   // giro: cos A, sen A, cos B, sen B
uniform vec4 uW;   // peso de cada figura: dona, esfera, cubo, octaedro
uniform vec4 uP;   // pulso: golpe, graves, agudos, salto
uniform vec3 uC0;
uniform vec3 uC1;
uniform vec3 uC2;
uniform vec3 uC3;
out vec4 fragColor;

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

// Los doce caracteres de donut.c en mapas de bits de 5×7: filas 0–3 en x y
// filas 4–6 en y, cinco bits por fila.
vec2 glyph(float i) {
  if (i < 0.5) return vec2(0.0, 396.0);
  if (i < 1.5) return vec2(0.0, 12424.0);
  if (i < 2.5) return vec2(31.0, 0.0);
  if (i < 3.5) return vec2(277.0, 2048.0);
  if (i < 4.5) return vec2(12672.0, 12672.0);
  if (i < 5.5) return vec2(12672.0, 12424.0);
  if (i < 6.5) return vec2(992.0, 31744.0);
  if (i < 7.5) return vec2(135300.0, 4100.0);
  if (i < 8.5) return vec2(21983.0, 15008.0);
  if (i < 9.5) return vec2(338922.0, 32074.0);
  if (i < 10.5) return vec2(147086.0, 6084.0);
  return vec2(476917.0, 24078.0);
}

float bitmapBit(vec2 code, vec2 uv) {
  vec2 g = floor(uv * vec2(6.0, 8.0));
  if (g.x > 4.5 || g.y > 6.5) return 0.0;
  float val = g.y < 3.5 ? code.x : code.y;
  float shift = g.y < 3.5 ? (3.0 - g.y) * 5.0 + (4.0 - g.x) : (6.0 - g.y) * 5.0 + (4.0 - g.x);
  return mod(floor(val / exp2(shift)), 2.0);
}

float glyphBit(float i, vec2 uv) {
  return bitmapBit(glyph(i), uv);
}

// Binario: un 0 o un 1 por celda que cambia de vez en cuando, como datos; la
// luz la da el brillo de la tinta.
float binaryBit(vec2 cell, vec2 uv) {
  float flip = floor(uA.z * 1.5 + hash12(cell * 0.37) * 6.0);
  vec2 code = hash12(cell + flip * 13.7) < 0.5 ? vec2(476789.0, 26158.0) : vec2(143492.0, 4238.0);
  return bitmapBit(code, uv);
}

float bayer2(vec2 a) {
  a = floor(a);
  return fract(a.x * 0.5 + a.y * a.y * 0.75);
}

// Bloques: ░ ▒ ▓ █ de terminal, una trama ordenada que llena la celda según
// la luz.
float blockBit(float lum, vec2 uv) {
  vec2 g = floor(uv * vec2(6.0, 8.0));
  if (g.x > 4.5 || g.y > 6.5) return 0.0;
  float level = (floor(lum * 3.99) + 1.0) * 0.25;
  float threshold = bayer2(g * 0.5) * 0.25 + bayer2(g);
  return step(threshold, level - 0.01);
}

// El carácter de la celda con la mezcla de juegos de caracteres elegida.
float charBit(float idx, float lum, vec2 cell, vec2 uv) {
  float wBin = uD.z;
  float wBlk = uD.w;
  float wAscii = max(0.0, 1.0 - wBin - wBlk);
  float on = 0.0;
  if (wAscii > 0.001) on += wAscii * glyphBit(idx, uv);
  if (wBin > 0.001) on += wBin * binaryBit(cell, uv);
  if (wBlk > 0.001) on += wBlk * blockBit(lum, uv);
  return on;
}

vec3 rotate(vec3 p) {
  p = vec3(p.x, uR.x * p.y - uR.y * p.z, uR.y * p.y + uR.x * p.z);
  return vec3(uR.z * p.x - uR.w * p.y, uR.w * p.x + uR.z * p.y, p.z);
}

// Las cuatro figuras mezcladas por peso (sin ramas: siempre el mismo coste).
float scene(vec3 p) {
  float k = 1.0 + min(0.12 * uM.y + 0.14 * uP.y + 0.06 * uP.x, 0.25);
  vec3 q = rotate(p) / k;
  float torus = length(vec2(length(q.xz) - 1.0, q.y)) - 0.45;
  float sphere = length(q) - 1.15;
  vec3 d = abs(q) - vec3(0.85);
  float box = length(max(d, 0.0)) + min(max(d.x, max(d.y, d.z)), 0.0) - 0.08;
  vec3 a = abs(q);
  float octa = (a.x + a.y + a.z - 1.35) * 0.577;
  return dot(uW, vec4(torus, sphere, box, octa)) * k;
}

void main() {
  vec2 frag = FlutterFragCoord().xy;
  float cw = uSize.x / uB.z;
  vec2 cellSize = vec2(cw, cw * 8.0 / 6.0);
  vec2 cell = floor(frag / cellSize);
  vec2 cellUv = fract(frag / cellSize);
  vec2 centerPx = (cell + 0.5) * cellSize;
  float scale = min(uSize.x, uSize.y);
  vec2 uv = (centerPx - 0.5 * uSize) / scale * 1.9;
  // Golpes: la figura salta hacia arriba.
  uv.y += uP.w * 0.22;
  // Un rayo por celda contra la figura.
  vec3 ro = vec3(0.0, 0.0, -4.2);
  vec3 rd = normalize(vec3(uv, 2.2));
  float t = 0.0;
  float hit = 0.0;
  for (int i = 0; i < 32; i++) {
    float d = scene(ro + rd * t);
    if (d < 0.002) {
      hit = 1.0;
      break;
    }
    t += d;
    if (t > 8.0) break;
  }
  vec3 col = uC0;
  float lum = 0.0;
  if (hit > 0.5) {
    vec3 p = ro + rd * t;
    vec2 e = vec2(0.003, -0.003);
    vec3 n = normalize(e.xyy * scene(p + e.xyy) + e.yyx * scene(p + e.yyx) + e.yxy * scene(p + e.yxy) + e.xxx * scene(p + e.xxx));
    lum = clamp(dot(n, normalize(vec3(0.35, -0.8, -0.6))), 0.0, 1.0);
    lum = clamp(lum * (0.9 + 0.35 * uM.x) + 0.08 + 0.35 * uP.x, 0.0, 1.0);
  }
  // Chispas de los agudos: celdas sueltas que se encienden con @.
  float sparkle = step(0.994 - 0.02 * uM.z - 0.08 * uP.z, hash12(cell + floor(uA.z * 12.0)));
  float idx = floor(lum * 11.99);
  float on = 0.0;
  if (hit > 0.5) on = charBit(idx, lum, cell, cellUv);
  float sp = sparkle * (1.0 - hit) * charBit(11.0, 1.0, cell, cellUv) * uM.z;
  // Tinta ámbar del monitor: más clara donde llega más luz.
  vec3 ink = uC1 * (0.45 + 0.75 * lum);
  col += ink * on * (1.0 + 0.4 * uM.y + 1.0 * uP.x + 0.4 * uP.y);
  // Las chispas en el tono claro de la paleta y el destello en su naranja.
  col += uC3 * sp * 0.8;
  // Agudos: muchas celdas de la figura que destellan con @.
  if (uP.z > 0.001) {
    float glint = step(0.8 - 0.25 * uP.z, hash12(cell * 1.37 + floor(uA.z * 18.0) + 3.1)) * hit;
    col += uC3 * glint * charBit(11.0, 1.0, cell, cellUv) * 0.9 * uP.z;
  }
  // Resplandor del monitor detrás de cada carácter.
  col += ink * hit * lum * 0.12 * uD.x;
  // Graves: el resplandor ámbar respira.
  col += ink * hit * lum * 0.7 * uP.y;
  // Resplandor alrededor de la figura (que sigue su salto): Golpes lo
  // enciende y Graves lo hace latir.
  vec2 q = (frag - 0.5 * uSize) / scale * 1.9;
  q.y += uP.w * 0.22;
  col += uC2 * exp(-dot(q, q) * 1.6) * (0.32 * uP.x + 0.2 * uP.y) * min(uD.x, 1.5);
  // Líneas de barrido y viñeta de tubo.
  col *= 0.86 + 0.14 * sin(frag.y * 1.9);
  vec2 p0 = (frag - 0.5 * uSize) / scale;
  col *= 1.0 - 0.45 * smoothstep(0.5, 1.4, length(p0 * vec2(0.9, 0.6)));
  // El destello aviva la figura en lugar de cubrir la pantalla.
  col *= 1.0 + 0.4 * uD.y;
  // Fondo transparente: color premultiplicado y opacidad según el brillo; la
  // luz muy tenue se vuelve transparente del todo para no dejar velo.
  col = clamp(col, 0.0, 1.0);
  float veilPeak = max(col.r, max(col.g, col.b));
  float clearCut = smoothstep(0.04, 0.12, veilPeak);
  col *= clearCut;
  float alpha = clamp(veilPeak * 1.25, 0.0, 1.0) * clearCut;
  fragColor = vec4(col, alpha);
}

visuals.nativeSource:
class Visual final : public Scene {
  static constexpr int kSnaps = 24;
  static constexpr int kBands = 12;
  static constexpr int kPoints = 120;
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  std::array<float, kBands> bands{};
  // Relojes en doble precisión: la escena sin música es idéntica a 30 y 60 FPS.
  double clock = 0, hue = 0;
  int64_t captured = 0;
  // Instantáneas: el espectro y el momento en que se guardaron.
  std::array<std::array<float, kBands>, kSnaps> snaps{};
  std::array<double, kSnaps> snapTime{};
  std::array<float, kSnaps> snapBass{};
  int head = 0;

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

  static Color hsv(float h, float s, float v, float a) {
    h = h - std::floor(h);
    float r = std::clamp(std::fabs(h * 6.0f - 3.0f) - 1.0f, 0.0f, 1.0f);
    float g = std::clamp(2.0f - std::fabs(h * 6.0f - 2.0f), 0.0f, 1.0f);
    float b = std::clamp(2.0f - std::fabs(h * 6.0f - 4.0f), 0.0f, 1.0f);
    return {v * (1.0f - s + s * r), v * (1.0f - s + s * g), v * (1.0f - s + s * b), a};
  }

 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    bands.fill(0);
    clock = 0;
    hue = rng.unit();
    captured = 0;
    head = 0;
    for (auto& s : snaps) s.fill(0);
    snapTime.fill(0);
    snapBass.fill(0);
  }

  void update(const Frame& f) override {
    float dt = float(f.delta);
    const Music& mu = f.music;
    bass = follow(bass, mu.bass, 22.0f, 4.5f, dt);
    body = follow(body, mu.body, 12.0f, 3.0f, dt);
    spark = follow(spark, mu.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, mu.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, mu.active ? std::pow(std::clamp(mu.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);
    for (int b = 0; b < kBands; b++) {
      int k0 = b * 31 / kBands, k1 = std::max(k0 + 1, (b + 1) * 31 / kBands);
      float v = 0;
      for (int k = k0; k < k1 && k < 31; k++) v = std::max(v, mu.smoothSpectrum[size_t(k)]);
      bands[size_t(b)] = follow(bands[size_t(b)], v, 25.0f, 6.0f, dt);
    }

    float hit = 0, fl = 0;
    for (const auto& e : mu.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : mu.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : mu.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((mu.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, mu.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    if (hit > kick + 0.2f) hue += 0.08 * hit;
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    hue += f.delta * f.speed * (0.03 + 0.05 * drive);
    clock += f.delta * f.speed * (1.0 + 1.2 * drive);
    // Instantáneas a ritmo fijo del reloj: cada una es un eco.
    int64_t target = int64_t(std::floor(clock * 15.0 + 1e-6));
    if (target - captured > kSnaps) captured = target - kSnaps;
    while (captured < target) {
      captured++;
      head = (head + 1) % kSnaps;
      snaps[size_t(head)] = bands;
      snapTime[size_t(head)] = double(captured) / 15.0;
      snapBass[size_t(head)] = bass;
    }
  }

  void render(const Frame& f, Canvas& c) const override {
    auto m = modifiers(f);
    float amp = f.intensity;
    const Color& bg = f.colors[0];
    Color tint = hsv(float(hue), 0.9f, 1.0f, 1.0f);
    c.rect({0, 0, f.width, f.height},
           Paint::radial({f.width * 0.5f, f.height * 0.5f}, std::max(f.width, f.height) * 0.65f,
                         {Color{std::min(1.0f, bg.r + tint.r * 0.08f * (1.0f + bass)), std::min(1.0f, bg.g + tint.g * 0.08f * (1.0f + bass)),
                                std::min(1.0f, bg.b + tint.b * 0.08f * (1.0f + bass)), 1.0f},
                          Color{bg.r, bg.g, bg.b, 1.0f}}));
    int echoes = std::clamp(m.ecos, 6, kSnaps);
    int sym = std::clamp(m.simetria, 2, 8);
    bool inward = m.sentido == 0;
    float side = std::min(f.width, f.height);
    float px = side / 400.0f;
    float baseR = side * (inward ? 0.36f : 0.1f);
    // Fracción entre instantáneas: los ecos se mueven sin saltos.
    float frac = float(clock * 15.0 - std::floor(clock * 15.0));
    const float q = inward ? 0.86f : 1.0f / 0.86f;
    Vec2 center{f.width * 0.5f, f.height * 0.5f};
    for (int k = echoes - 1; k >= 0; k--) {
      int idx = ((head - k) % kSnaps + kSnaps) % kSnaps;
      const auto& snap = snaps[size_t(idx)];
      float age = float(k) + frac;
      float s = std::pow(q, age);
      float rot = age * 0.07f * m.giro + float(snapTime[size_t(idx)]) * 0.05f;
      float fade = 1.0f - age / float(echoes + 1);
      if (fade <= 0.0f) continue;
      Path ring;
      double t0 = snapTime[size_t(idx)];
      for (int i = 0; i <= kPoints; i++) {
        float th = 6.2831853f * float(i) / float(kPoints);
        // Banda según el ángulo, en espejo para la simetría.
        float u = std::fabs(std::sin(th * float(sym) * 0.5f));
        float bi = u * float(kBands - 1);
        int b0 = int(bi);
        int b1 = std::min(b0 + 1, kBands - 1);
        float level = snap[size_t(b0)] + (snap[size_t(b1)] - snap[size_t(b0)]) * (bi - float(b0));
        float wob = 0.06f * float(std::sin(double(th) * double(sym) + t0 * 1.7));
        float r = baseR * s * (1.0f + wob + 0.5f * level * amp + 0.25f * snapBass[size_t(idx)] * amp);
        float a = th + rot;
        float x = center.x + r * std::cos(a), y = center.y + r * std::sin(a);
        if (i == 0) ring.moveTo(x, y); else ring.lineTo(x, y);
      }
      ring.close();
      Color col = hsv(float(hue) + age * 0.055f, 0.95f, 1.0f, 1.0f);
      float lit = (k == 0 ? 1.0f + 0.6f * kick : 1.0f) * amp;
      Paint glow;
      glow.blend = Blend::plus;
      glow.strokeWidth = (7.0f + 5.0f * bass) * px * std::sqrt(s);
      glow.strokeJoin = 1;
      glow.color = col.opacity(std::clamp(0.14f * fade * f.glow * lit, 0.0f, 1.0f));
      c.path(ring, glow);
      Paint line;
      line.blend = Blend::plus;
      line.strokeWidth = std::max(0.8f, (2.4f + 1.2f * energy) * px * std::sqrt(s));
      line.strokeJoin = 1;
      line.color = col.opacity(std::clamp((0.25f + 0.75f * fade) * lit, 0.0f, 1.0f));
      c.path(ring, line);
    }
    // Núcleo que late con los graves.
    float core = side * (0.03f + 0.03f * bass);
    Paint glowCore = Paint::radial(center, core * 4.0f, {tint.opacity(std::clamp((0.4f + 0.5f * kick) * amp, 0.0f, 1.0f)), tint.opacity(0.0f)});
    glowCore.blend = Blend::plus;
    c.circle(center, core * 4.0f, glowCore);
    if (flash > 0.01f) {
      Paint fl;
      fl.blend = Blend::plus;
      fl.color = tint.opacity(std::clamp(flash * 0.06f * amp, 0.0f, 1.0f));
      c.rect({0, 0, f.width, f.height}, fl);
    }
  }
};

