class Visual final : public Scene {
  static constexpr int kMax = 6000;
  struct Seed { float u, v, w, j; };
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  std::array<float, 8> bands{};
  // Relojes en doble precisión: la escena sin música es idéntica a 30 y 60 FPS.
  double yaw = 0, pitch = 0, clock = 0, morph = 1, sinceShape = 0, blastAge = 100;
  int shapeFrom = 0, shapeTo = 0, autoShape = 0, beats = 0;
  float blastPower = 0;
  std::vector<Seed> seeds;

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

  static std::array<float, 3> shape(int kind, const Seed& s, float t) {
    const float tau = 6.2831853f;
    switch (kind) {
      case 0: {
        float th = s.u * tau, ph = std::acos(2.0f * s.v - 1.0f);
        return {std::sin(ph) * std::cos(th), std::cos(ph), std::sin(ph) * std::sin(th)};
      }
      case 1: {
        float th = s.u * tau, ph = s.v * tau;
        float R = 0.72f, r = 0.3f;
        return {(R + r * std::cos(ph)) * std::cos(th), r * std::sin(ph), (R + r * std::cos(ph)) * std::sin(th)};
      }
      case 2: {
        int face = std::min(int(s.w * 6.0f), 5);
        float a = (s.u * 2.0f - 1.0f) * 0.7f, b = (s.v * 2.0f - 1.0f) * 0.7f, sgn = (face % 2 == 0) ? 0.7f : -0.7f;
        if (face < 2) return {sgn, a, b};
        if (face < 4) return {a, sgn, b};
        return {a, b, sgn};
      }
      case 3: {
        float th = s.u * tau * 2.5f + (s.w < 0.5f ? 0.0f : 3.14159265f) + t * 0.6f;
        float y = (s.u * 2.0f - 1.0f) * 1.05f;
        float r = 0.42f + 0.05f * (s.v - 0.5f);
        return {r * std::cos(th), y, r * std::sin(th)};
      }
      default: {
        float x = s.u * 2.0f - 1.0f, z = s.v * 2.0f - 1.0f;
        float y = 0.22f * std::sin(x * 4.0f + t * 1.6f) * std::cos(z * 3.0f - t * 1.1f);
        return {x * 0.95f, y, z * 0.95f};
      }
    }
  }

  void goTo(int next) {
    if (next == shapeTo) return;
    shapeFrom = shapeTo;
    shapeTo = next;
    morph = 0;
  }

 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    bands.fill(0);
    yaw = rng.unit() * 6.2831853;
    pitch = 0;
    clock = 0;
    morph = 1;
    sinceShape = 0;
    blastAge = 100;
    blastPower = 0;
    shapeFrom = shapeTo = autoShape = 0;
    beats = 0;
    seeds.resize(kMax);
    for (auto& s : seeds) s = {rng.unit(), rng.unit(), rng.unit(), rng.unit()};
  }

  void update(const Frame& f) override {
    auto m = modifiers(f);
    float dt = float(f.delta);
    const Music& mu = f.music;
    bass = follow(bass, mu.bass, 22.0f, 4.5f, dt);
    body = follow(body, mu.body, 12.0f, 3.0f, dt);
    spark = follow(spark, mu.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, mu.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, mu.active ? std::pow(std::clamp(mu.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);
    for (int b = 0; b < 8; b++) {
      float v = 0;
      for (int k = b * 4; k < b * 4 + 4 && k < 31; k++) v = std::max(v, mu.smoothSpectrum[size_t(k)]);
      bands[size_t(b)] = follow(bands[size_t(b)], v, 18.0f, 4.0f, dt);
    }

    float hit = 0, fl = 0;
    for (const auto& e : mu.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : mu.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : mu.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((mu.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, mu.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    blastAge += f.delta;
    sinceShape += f.delta;
    if (hit > kick + 0.2f) {
      beats++;
      if (hit > 0.6f && blastAge > 0.5) {
        blastAge = 0;
        blastPower = hit;
      }
      if (beats % 8 == 0) {
        autoShape = (autoShape + 1) % 5;
        sinceShape = 0;
      }
    }
    if (!mu.active && sinceShape > 6.0) {
      autoShape = (autoShape + 1) % 5;
      sinceShape -= 6.0;
    }
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    goTo(m.forma == 0 ? autoShape : m.forma - 1);
    morph = std::min(morph + f.delta / 2.0, 1.0);
    clock += f.delta * f.speed;
    yaw += f.delta * f.speed * m.giro * (0.3 + 0.6 * drive);
    pitch += f.delta * f.speed * m.giro * 0.11;
  }

  void render(const Frame& f, Canvas& c) const override {
    auto m = modifiers(f);
    float amp = f.intensity;
    const Color& bg = f.colors[0];
    const Color& violet = f.colors[1];
    const Color& orange = f.colors[2];
    c.rect({0, 0, f.width, f.height},
           Paint::radial({f.width * 0.5f, f.height * 0.5f}, std::max(f.width, f.height) * 0.7f,
                         {Color{std::min(1.0f, bg.r + violet.r * 0.08f * (1.0f + bass)), std::min(1.0f, bg.g + violet.g * 0.05f),
                                std::min(1.0f, bg.b + violet.b * 0.1f * (1.0f + bass)), 1.0f},
                          Color{bg.r, bg.g, bg.b, 1.0f}}));
    int n = std::clamp(m.miles, 1, 6) * 1000;
    n = std::min(n, int(seeds.size()));
    float side = std::min(f.width, f.height);
    float px = side / 400.0f;
    float scale = side * 0.46f * (1.0f + 0.14f * bass * amp);
    float cy = float(std::cos(yaw)), sy = float(std::sin(yaw));
    float tilt = 0.35f * float(std::sin(pitch));
    float cp = std::cos(tilt), sp = std::sin(tilt);
    float t = float(std::fmod(clock, 1000.0));
    float mo = float(morph);
    float blast = m.estallido && blastAge < 1.6 ? blastPower * float(std::exp(-blastAge * 2.4)) * float(std::min(blastAge * 12.0, 1.0)) : 0.0f;
    // Seis grupos: dos colores por tres profundidades.
    std::array<std::vector<Vec2>, 6> groups;
    for (auto& g : groups) g.reserve(size_t(n / 4));
    for (int i = 0; i < n; i++) {
      const Seed& s = seeds[size_t(i)];
      auto a = shape(shapeFrom, s, t);
      auto b = shape(shapeTo, s, t);
      float pr = std::clamp((mo - s.w * 0.4f) / 0.6f, 0.0f, 1.0f);
      pr = pr * pr * (3.0f - 2.0f * pr);
      float x = a[0] + (b[0] - a[0]) * pr, y = a[1] + (b[1] - a[1]) * pr, z = a[2] + (b[2] - a[2]) * pr;
      // Erizado con su banda y estallido hacia fuera.
      float len = std::sqrt(x * x + y * y + z * z) + 1e-4f;
      float push = 0.18f * bands[size_t(i % 8)] * amp + blast * (0.6f + 1.2f * s.j);
      x += x / len * push;
      y += y / len * push;
      z += z / len * push;
      float rx = x * cy + z * sy, rz = -x * sy + z * cy;
      float ry = y * cp - rz * sp;
      float rzz = y * sp + rz * cp;
      float persp = 2.4f / (3.0f + rzz);
      Vec2 q{f.width * 0.5f + rx * persp * scale, f.height * 0.5f - ry * persp * scale};
      int depth = rzz < -0.3f ? 0 : (rzz < 0.3f ? 1 : 2);
      groups[size_t((i & 1) * 3 + depth)].push_back(q);
    }
    for (int g = 5; g >= 0; g--) {
      int depth = g % 3;
      const Color& col = g < 3 ? violet : orange;
      float near = 1.0f - float(depth) * 0.35f;
      Paint p;
      p.blend = Blend::plus;
      p.color = col.opacity(std::clamp((0.35f + 0.45f * near + 0.3f * kick) * amp, 0.0f, 1.0f));
      c.points(groups[size_t(g)], (1.1f + 1.3f * near + 0.6f * spark) * px, p);
      if (depth == 0) {
        Paint halo;
        halo.blend = Blend::plus;
        halo.color = col.opacity(std::clamp(0.05f * f.glow * amp, 0.0f, 1.0f));
        c.points(groups[size_t(g)], 4.0f * px, halo);
      }
    }
    if (flash > 0.01f) {
      Paint fl;
      fl.blend = Blend::plus;
      fl.color = orange.opacity(std::clamp(flash * 0.05f * amp, 0.0f, 1.0f));
      c.rect({0, 0, f.width, f.height}, fl);
    }
  }
};

class Visual final : public Scene {
  static constexpr int kMax = 6000;
  struct Seed { float u, v, w, j; };
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  std::array<float, 8> bands{};
  // Relojes en doble precisión: la escena sin música es idéntica a 30 y 60 FPS.
  double yaw = 0, pitch = 0, clock = 0, morph = 1, sinceShape = 0, blastAge = 100;
  int shapeFrom = 0, shapeTo = 0, autoShape = 0, beats = 0;
  float blastPower = 0;
  std::vector<Seed> seeds;

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

  static std::array<float, 3> shape(int kind, const Seed& s, float t) {
    const float tau = 6.2831853f;
    switch (kind) {
      case 0: {
        float th = s.u * tau, ph = std::acos(2.0f * s.v - 1.0f);
        return {std::sin(ph) * std::cos(th), std::cos(ph), std::sin(ph) * std::sin(th)};
      }
      case 1: {
        float th = s.u * tau, ph = s.v * tau;
        float R = 0.72f, r = 0.3f;
        return {(R + r * std::cos(ph)) * std::cos(th), r * std::sin(ph), (R + r * std::cos(ph)) * std::sin(th)};
      }
      case 2: {
        int face = std::min(int(s.w * 6.0f), 5);
        float a = (s.u * 2.0f - 1.0f) * 0.7f, b = (s.v * 2.0f - 1.0f) * 0.7f, sgn = (face % 2 == 0) ? 0.7f : -0.7f;
        if (face < 2) return {sgn, a, b};
        if (face < 4) return {a, sgn, b};
        return {a, b, sgn};
      }
      case 3: {
        float th = s.u * tau * 2.5f + (s.w < 0.5f ? 0.0f : 3.14159265f) + t * 0.6f;
        float y = (s.u * 2.0f - 1.0f) * 1.05f;
        float r = 0.42f + 0.05f * (s.v - 0.5f);
        return {r * std::cos(th), y, r * std::sin(th)};
      }
      default: {
        float x = s.u * 2.0f - 1.0f, z = s.v * 2.0f - 1.0f;
        float y = 0.22f * std::sin(x * 4.0f + t * 1.6f) * std::cos(z * 3.0f - t * 1.1f);
        return {x * 0.95f, y, z * 0.95f};
      }
    }
  }

  void goTo(int next) {
    if (next == shapeTo) return;
    shapeFrom = shapeTo;
    shapeTo = next;
    morph = 0;
  }

 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    bands.fill(0);
    yaw = rng.unit() * 6.2831853;
    pitch = 0;
    clock = 0;
    morph = 1;
    sinceShape = 0;
    blastAge = 100;
    blastPower = 0;
    shapeFrom = shapeTo = autoShape = 0;
    beats = 0;
    seeds.resize(kMax);
    for (auto& s : seeds) s = {rng.unit(), rng.unit(), rng.unit(), rng.unit()};
  }

  void update(const Frame& f) override {
    auto m = modifiers(f);
    float dt = float(f.delta);
    const Music& mu = f.music;
    bass = follow(bass, mu.bass, 22.0f, 4.5f, dt);
    body = follow(body, mu.body, 12.0f, 3.0f, dt);
    spark = follow(spark, mu.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, mu.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, mu.active ? std::pow(std::clamp(mu.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);
    for (int b = 0; b < 8; b++) {
      float v = 0;
      for (int k = b * 4; k < b * 4 + 4 && k < 31; k++) v = std::max(v, mu.smoothSpectrum[size_t(k)]);
      bands[size_t(b)] = follow(bands[size_t(b)], v, 18.0f, 4.0f, dt);
    }

    float hit = 0, fl = 0;
    for (const auto& e : mu.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : mu.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : mu.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((mu.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, mu.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    blastAge += f.delta;
    sinceShape += f.delta;
    if (hit > kick + 0.2f) {
      beats++;
      if (hit > 0.6f && blastAge > 0.5) {
        blastAge = 0;
        blastPower = hit;
      }
      if (beats % 8 == 0) {
        autoShape = (autoShape + 1) % 5;
        sinceShape = 0;
      }
    }
    if (!mu.active && sinceShape > 6.0) {
      autoShape = (autoShape + 1) % 5;
      sinceShape -= 6.0;
    }
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    goTo(m.forma == 0 ? autoShape : m.forma - 1);
    morph = std::min(morph + f.delta / 2.0, 1.0);
    clock += f.delta * f.speed;
    yaw += f.delta * f.speed * m.giro * (0.3 + 0.6 * drive);
    pitch += f.delta * f.speed * m.giro * 0.11;
  }

  void render(const Frame& f, Canvas& c) const override {
    auto m = modifiers(f);
    float amp = f.intensity;
    const Color& violet = f.colors[1];
    const Color& orange = f.colors[2];
    int n = std::clamp(m.miles, 1, 6) * 1000;
    n = std::min(n, int(seeds.size()));
    float side = std::min(f.width, f.height);
    float px = side / 400.0f;
    float scale = side * 0.46f * (1.0f + 0.14f * bass * amp);
    float cy = float(std::cos(yaw)), sy = float(std::sin(yaw));
    float tilt = 0.35f * float(std::sin(pitch));
    float cp = std::cos(tilt), sp = std::sin(tilt);
    float t = float(std::fmod(clock, 1000.0));
    float mo = float(morph);
    float blast = m.estallido && blastAge < 1.6 ? blastPower * float(std::exp(-blastAge * 2.4)) * float(std::min(blastAge * 12.0, 1.0)) : 0.0f;
    // Seis grupos: dos colores por tres profundidades.
    std::array<std::vector<Vec2>, 6> groups;
    for (auto& g : groups) g.reserve(size_t(n / 4));
    for (int i = 0; i < n; i++) {
      const Seed& s = seeds[size_t(i)];
      auto a = shape(shapeFrom, s, t);
      auto b = shape(shapeTo, s, t);
      float pr = std::clamp((mo - s.w * 0.4f) / 0.6f, 0.0f, 1.0f);
      pr = pr * pr * (3.0f - 2.0f * pr);
      float x = a[0] + (b[0] - a[0]) * pr, y = a[1] + (b[1] - a[1]) * pr, z = a[2] + (b[2] - a[2]) * pr;
      // Erizado con su banda y estallido hacia fuera.
      float len = std::sqrt(x * x + y * y + z * z) + 1e-4f;
      float push = 0.18f * bands[size_t(i % 8)] * amp + blast * (0.6f + 1.2f * s.j);
      x += x / len * push;
      y += y / len * push;
      z += z / len * push;
      float rx = x * cy + z * sy, rz = -x * sy + z * cy;
      float ry = y * cp - rz * sp;
      float rzz = y * sp + rz * cp;
      float persp = 2.4f / (3.0f + rzz);
      Vec2 q{f.width * 0.5f + rx * persp * scale, f.height * 0.5f - ry * persp * scale};
      int depth = rzz < -0.3f ? 0 : (rzz < 0.3f ? 1 : 2);
      groups[size_t((i & 1) * 3 + depth)].push_back(q);
    }
    for (int g = 5; g >= 0; g--) {
      int depth = g % 3;
      const Color& col = g < 3 ? violet : orange;
      float near = 1.0f - float(depth) * 0.35f;
      Paint p;
      p.blend = Blend::plus;
      p.color = col.opacity(std::clamp((0.35f + 0.45f * near + 0.3f * kick) * amp, 0.0f, 1.0f));
      c.points(groups[size_t(g)], (1.1f + 1.3f * near + 0.6f * spark) * px, p);
      if (depth == 0) {
        Paint halo;
        halo.blend = Blend::plus;
        halo.color = col.opacity(std::clamp(0.05f * f.glow * amp, 0.0f, 1.0f));
        c.points(groups[size_t(g)], 4.0f * px, halo);
      }
    }
  }
};

class Visual final : public Scene {
  static constexpr int kMax = 16;
  static constexpr int kCurve = 420;
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  // Relojes en doble precisión: la escena sin música es idéntica a 30 y 60 FPS.
  double angle = 0, sinceShape = 0, morph = 1;
  int beats = 0;
  Random rng{1};
  std::array<float, kMax> ampFrom{}, ampTo{}, phase{};
  std::array<float, kMax> bands{};

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

  // Frecuencia del círculo k según el sentido de giro: alterno 1, −1, 2, −2…;
  // mismo sentido 1, 2, 3…; contrario 1, −1, −2, −3…
  static float freq(int k, int mode) {
    if (mode == 1) return float(k + 1);
    if (mode == 2) return k == 0 ? 1.0f : -float(k);
    return float(k / 2 + 1) * (k % 2 == 0 ? 1.0f : -1.0f);
  }

  void newShape() {
    for (int k = 0; k < kMax; k++) {
      ampFrom[size_t(k)] = amplitude(k);
      float falloff = 1.0f / (1.0f + 0.55f * float(k));
      ampTo[size_t(k)] = (0.25f + 0.75f * rng.unit()) * falloff * (rng.unit() < 0.2f ? 0.2f : 1.0f);
    }
    morph = 0;
  }

  float amplitude(int k) const {
    float t = float(std::min(morph, 1.0));
    t = t * t * (3.0f - 2.0f * t);
    return ampFrom[size_t(k)] + (ampTo[size_t(k)] - ampFrom[size_t(k)]) * t;
  }

 public:
  void reset(uint32_t seed) override {
    rng = Random(seed);
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    angle = rng.unit() * 6.2831853;
    sinceShape = 0;
    beats = 0;
    bands.fill(0);
    for (int k = 0; k < kMax; k++) {
      phase[size_t(k)] = rng.unit() * 6.2831853f;
      ampFrom[size_t(k)] = 0;
      ampTo[size_t(k)] = 0;
    }
    morph = 1;
    newShape();
    morph = 1;
  }

  void update(const Frame& f) override {
    float dt = float(f.delta);
    const Music& mu = f.music;
    bass = follow(bass, mu.bass, 22.0f, 4.5f, dt);
    body = follow(body, mu.body, 12.0f, 3.0f, dt);
    spark = follow(spark, mu.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, mu.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, mu.active ? std::pow(std::clamp(mu.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);
    for (int k = 0; k < kMax; k++) {
      int b0 = k * 31 / kMax, b1 = std::max(b0 + 1, (k + 1) * 31 / kMax);
      float v = 0;
      for (int b = b0; b < b1 && b < 31; b++) v = std::max(v, mu.smoothSpectrum[size_t(b)]);
      bands[size_t(k)] = follow(bands[size_t(k)], v, 18.0f, 4.0f, dt);
    }

    float hit = 0, fl = 0;
    for (const auto& e : mu.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : mu.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : mu.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((mu.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, mu.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    sinceShape += f.delta;
    if (hit > kick + 0.2f) {
      beats++;
      if (beats % 8 == 0) {
        newShape();
        sinceShape = 0;
      }
    }
    if (!mu.active && sinceShape > 9.0) {
      newShape();
      sinceShape -= 9.0;
    }
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    morph = std::min(morph + f.delta / 1.6, 1.0);
    angle += f.delta * f.speed * (0.35 + 0.6 * drive + 1.2 * kick);
  }

  void render(const Frame& f, Canvas& c) const override {
    auto m = modifiers(f);
    auto g = glide(f);
    float amp = f.intensity;
    const Color& bg = f.colors[0];
    const Color& fire = f.colors[1];
    const Color& lime = f.colors[2];
    const Color& white = f.colors[3];
    c.rect({0, 0, f.width, f.height},
           Paint::radial({f.width * 0.5f, f.height * 0.5f}, std::max(f.width, f.height) * 0.7f,
                         {Color{std::min(1.0f, bg.r + fire.r * 0.06f), std::min(1.0f, bg.g + fire.g * 0.04f), std::min(1.0f, bg.b + 0.01f), 1.0f},
                          Color{bg.r, bg.g, bg.b, 1.0f}}));
    int n = std::clamp(m.circulos, 4, kMax);
    float side = std::min(f.width, f.height);
    float px = side / 400.0f;
    // Radios: amplitud de la figura más la banda del espectro.
    std::array<float, kMax> base{}, radii{};
    for (int k = 0; k < n; k++) {
      base[size_t(k)] = amplitude(k);
      radii[size_t(k)] = base[size_t(k)] * (1.0f + 1.6f * bands[size_t(k)] * amp);
    }
    // Sentido de giro: las frecuencias de cada opción con su peso; al cambiar,
    // la figura se transforma de una a otra.
    struct Spin { float weight; std::array<float, kMax> fr; };
    std::array<Spin, 3> spins{};
    int spinCount = 0;
    float spinTotal = 0;
    for (int o = 0; o < 3; o++) {
      float w = g.sentido.weight(o);
      if (w < 1e-3f) continue;
      Spin& s = spins[size_t(spinCount++)];
      s.weight = w;
      for (int k = 0; k < kMax; k++) s.fr[size_t(k)] = freq(k, o);
      spinTotal += w;
    }
    if (spinCount == 0) {
      spins[0].weight = 1;
      for (int k = 0; k < kMax; k++) spins[0].fr[size_t(k)] = freq(k, 0);
      spinCount = 1;
      spinTotal = 1;
    }
    for (int i = 0; i < spinCount; i++) spins[size_t(i)].weight /= spinTotal;
    // Dirección del círculo k en el ángulo a, mezclada entre sentidos.
    auto arm = [&](double a, int k) {
      Vec2 d{0, 0};
      for (int i = 0; i < spinCount; i++) {
        const Spin& s = spins[size_t(i)];
        double th = a * double(s.fr[size_t(k)]) + double(phase[size_t(k)]);
        d.x += s.weight * float(std::cos(th));
        d.y += s.weight * float(std::sin(th));
      }
      return d;
    };
    Vec2 center{f.width * 0.5f, f.height * 0.5f};
    int copies = std::clamp(m.copias, 1, 6);
    // Encaje: el tamaño sale de la figura real sin música (así la música la
    // agranda) y, con copias girando, de su distancia máxima al centro.
    float maxR = 1e-3f, maxX = 1e-3f, maxY = 1e-3f;
    for (int i = 0; i < 96; i++) {
      double a = 6.283185307179586 * double(i) / 96.0;
      float x = 0, y = 0;
      for (int k = 0; k < n; k++) {
        Vec2 d = arm(a, k);
        x += base[size_t(k)] * d.x;
        y += base[size_t(k)] * d.y;
      }
      maxR = std::max(maxR, std::sqrt(x * x + y * y));
      maxX = std::max(maxX, std::fabs(x));
      maxY = std::max(maxY, std::fabs(y));
    }
    float fit = copies > 1 ? std::min(f.width, f.height) * 0.46f / maxR
                           : std::min(f.width * 0.44f / maxX, f.height * 0.36f / maxY);
    float scale = fit * (1.0f + 0.1f * bass * amp);
    auto tip = [&](double a, std::array<Vec2, kMax + 1>* chain) {
      Vec2 p = center;
      if (chain) (*chain)[0] = p;
      for (int k = 0; k < n; k++) {
        Vec2 d = arm(a, k);
        p.x += radii[size_t(k)] * scale * d.x;
        p.y += radii[size_t(k)] * scale * d.y;
        if (chain) (*chain)[size_t(k + 1)] = p;
      }
      return p;
    };
    // Copias giradas alrededor del centro.
    auto turn = [&](Vec2 p, int copy) {
      if (copy == 0) return p;
      float a = 6.2831853f * float(copy) / float(copies);
      float cs = std::cos(a), sn = std::sin(a);
      float dx = p.x - center.x, dy = p.y - center.y;
      return Vec2{center.x + dx * cs - dy * sn, center.y + dx * sn + dy * cs};
    };

    // Figura completa tenue y estela reciente brillante, por tramos.
    Path full;
    std::vector<Vec2> curve(kCurve + 1);
    for (int i = 0; i <= kCurve; i++) curve[size_t(i)] = tip(angle + 6.283185307179586 * double(i) / double(kCurve), nullptr);
    for (int cp = 0; cp < copies; cp++) {
      for (int i = 0; i <= kCurve; i++) {
        Vec2 p = turn(curve[size_t(i)], cp);
        if (i == 0) full.moveTo(p.x, p.y); else full.lineTo(p.x, p.y);
      }
    }
    Paint faint;
    faint.strokeWidth = 1.6f * px;
    faint.strokeJoin = 1;
    faint.color = fire.opacity(0.3f);
    c.path(full, faint);

    const int chunks = 8;
    double span = 6.283185307179586 * double(m.estela);
    for (int ch = 0; ch < chunks; ch++) {
      float t = float(ch + 1) / float(chunks);
      Path seg;
      int steps = 40;
      std::array<Vec2, 41> pts{};
      for (int i = 0; i <= steps; i++) {
        double a = angle - span + span * (double(ch) + double(i) / double(steps)) / double(chunks);
        pts[size_t(i)] = tip(a, nullptr);
      }
      for (int cp = 0; cp < copies; cp++) {
        for (int i = 0; i <= steps; i++) {
          Vec2 p = turn(pts[size_t(i)], cp);
          if (i == 0) seg.moveTo(p.x, p.y); else seg.lineTo(p.x, p.y);
        }
      }
      Color col{fire.r + (lime.r - fire.r) * t, fire.g + (lime.g - fire.g) * t, fire.b + (lime.b - fire.b) * t, 1.0f};
      Paint glow;
      glow.blend = Blend::plus;
      glow.strokeWidth = (10.0f + 8.0f * bass) * px;
      glow.strokeCap = 1;
      glow.strokeJoin = 1;
      glow.color = col.opacity(std::clamp(0.18f * t * f.glow * amp, 0.0f, 1.0f));
      c.path(seg, glow);
      Paint line;
      line.blend = Blend::plus;
      line.strokeWidth = (2.0f + 2.6f * t + 1.5f * energy) * px;
      line.strokeCap = 1;
      line.strokeJoin = 1;
      line.color = col.opacity(std::clamp((0.3f + 0.7f * t) * amp, 0.0f, 1.0f));
      c.path(seg, line);
    }

    // Los círculos y sus brazos.
    std::array<Vec2, kMax + 1> chain{};
    Vec2 pen = tip(angle, &chain);
    if (m.mostrar) {
      Path rings, arms;
      for (int k = 0; k < n; k++) {
        rings.circle(chain[size_t(k)], std::max(radii[size_t(k)] * scale, 0.5f));
        arms.moveTo(chain[size_t(k)].x, chain[size_t(k)].y).lineTo(chain[size_t(k + 1)].x, chain[size_t(k + 1)].y);
      }
      Paint ring;
      ring.strokeWidth = 1.0f * px;
      ring.color = white.opacity(std::clamp((0.14f + 0.12f * kick) * amp, 0.0f, 1.0f));
      c.path(rings, ring);
      Paint arm;
      arm.strokeWidth = 1.4f * px;
      arm.strokeCap = 1;
      arm.color = white.opacity(std::clamp(0.45f * amp, 0.0f, 1.0f));
      c.path(arms, arm);
      std::vector<Vec2> joints(chain.begin(), chain.begin() + n);
      Paint dot;
      dot.color = white.opacity(std::clamp(0.6f * amp, 0.0f, 1.0f));
      c.points(joints, 1.8f * px, dot);
    }
    // El lápiz de luz.
    Paint halo = Paint::radial(pen, (14.0f + 10.0f * kick) * px, {lime.opacity(std::clamp(0.7f * f.glow * amp, 0.0f, 1.0f)), lime.opacity(0.0f)});
    halo.blend = Blend::plus;
    c.circle(pen, (14.0f + 10.0f * kick) * px, halo);
    Paint penDot;
    penDot.color = Color{1.0f, 1.0f, 0.95f, 1.0f};
    c.circle(pen, 2.6f * px, penDot);
    if (flash > 0.01f) {
      Paint fl;
      fl.blend = Blend::plus;
      fl.color = fire.opacity(std::clamp(flash * 0.05f * amp, 0.0f, 1.0f));
      c.rect({0, 0, f.width, f.height}, fl);
    }
  }
};

class Visual final : public Scene {
  static constexpr int kMax = 16;
  static constexpr int kCurve = 420;
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  // Relojes en doble precisión: la escena sin música es idéntica a 30 y 60 FPS.
  double angle = 0, sinceShape = 0, morph = 1;
  int beats = 0;
  Random rng{1};
  std::array<float, kMax> ampFrom{}, ampTo{}, phase{};
  std::array<float, kMax> bands{};

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

  // Frecuencia del círculo k según el sentido de giro: alterno 1, −1, 2, −2…;
  // mismo sentido 1, 2, 3…; contrario 1, −1, −2, −3…
  static float freq(int k, int mode) {
    if (mode == 1) return float(k + 1);
    if (mode == 2) return k == 0 ? 1.0f : -float(k);
    return float(k / 2 + 1) * (k % 2 == 0 ? 1.0f : -1.0f);
  }

  void newShape() {
    for (int k = 0; k < kMax; k++) {
      ampFrom[size_t(k)] = amplitude(k);
      float falloff = 1.0f / (1.0f + 0.55f * float(k));
      ampTo[size_t(k)] = (0.25f + 0.75f * rng.unit()) * falloff * (rng.unit() < 0.2f ? 0.2f : 1.0f);
    }
    morph = 0;
  }

  float amplitude(int k) const {
    float t = float(std::min(morph, 1.0));
    t = t * t * (3.0f - 2.0f * t);
    return ampFrom[size_t(k)] + (ampTo[size_t(k)] - ampFrom[size_t(k)]) * t;
  }

 public:
  void reset(uint32_t seed) override {
    rng = Random(seed);
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    angle = rng.unit() * 6.2831853;
    sinceShape = 0;
    beats = 0;
    bands.fill(0);
    for (int k = 0; k < kMax; k++) {
      phase[size_t(k)] = rng.unit() * 6.2831853f;
      ampFrom[size_t(k)] = 0;
      ampTo[size_t(k)] = 0;
    }
    morph = 1;
    newShape();
    morph = 1;
  }

  void update(const Frame& f) override {
    float dt = float(f.delta);
    const Music& mu = f.music;
    bass = follow(bass, mu.bass, 22.0f, 4.5f, dt);
    body = follow(body, mu.body, 12.0f, 3.0f, dt);
    spark = follow(spark, mu.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, mu.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, mu.active ? std::pow(std::clamp(mu.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);
    for (int k = 0; k < kMax; k++) {
      int b0 = k * 31 / kMax, b1 = std::max(b0 + 1, (k + 1) * 31 / kMax);
      float v = 0;
      for (int b = b0; b < b1 && b < 31; b++) v = std::max(v, mu.smoothSpectrum[size_t(b)]);
      bands[size_t(k)] = follow(bands[size_t(k)], v, 18.0f, 4.0f, dt);
    }

    float hit = 0, fl = 0;
    for (const auto& e : mu.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : mu.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : mu.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((mu.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, mu.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    sinceShape += f.delta;
    if (hit > kick + 0.2f) {
      beats++;
      if (beats % 8 == 0) {
        newShape();
        sinceShape = 0;
      }
    }
    if (!mu.active && sinceShape > 9.0) {
      newShape();
      sinceShape -= 9.0;
    }
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    morph = std::min(morph + f.delta / 1.6, 1.0);
    angle += f.delta * f.speed * (0.35 + 0.6 * drive + 1.2 * kick);
  }

  void render(const Frame& f, Canvas& c) const override {
    auto m = modifiers(f);
    auto g = glide(f);
    float amp = f.intensity;
    const Color& fire = f.colors[1];
    const Color& lime = f.colors[2];
    const Color& white = f.colors[3];
    int n = std::clamp(m.circulos, 4, kMax);
    float side = std::min(f.width, f.height);
    float px = side / 400.0f;
    // Radios: amplitud de la figura más la banda del espectro.
    std::array<float, kMax> base{}, radii{};
    for (int k = 0; k < n; k++) {
      base[size_t(k)] = amplitude(k);
      radii[size_t(k)] = base[size_t(k)] * (1.0f + 1.6f * bands[size_t(k)] * amp);
    }
    // Sentido de giro: las frecuencias de cada opción con su peso; al cambiar,
    // la figura se transforma de una a otra.
    struct Spin { float weight; std::array<float, kMax> fr; };
    std::array<Spin, 3> spins{};
    int spinCount = 0;
    float spinTotal = 0;
    for (int o = 0; o < 3; o++) {
      float w = g.sentido.weight(o);
      if (w < 1e-3f) continue;
      Spin& s = spins[size_t(spinCount++)];
      s.weight = w;
      for (int k = 0; k < kMax; k++) s.fr[size_t(k)] = freq(k, o);
      spinTotal += w;
    }
    if (spinCount == 0) {
      spins[0].weight = 1;
      for (int k = 0; k < kMax; k++) spins[0].fr[size_t(k)] = freq(k, 0);
      spinCount = 1;
      spinTotal = 1;
    }
    for (int i = 0; i < spinCount; i++) spins[size_t(i)].weight /= spinTotal;
    // Dirección del círculo k en el ángulo a, mezclada entre sentidos.
    auto arm = [&](double a, int k) {
      Vec2 d{0, 0};
      for (int i = 0; i < spinCount; i++) {
        const Spin& s = spins[size_t(i)];
        double th = a * double(s.fr[size_t(k)]) + double(phase[size_t(k)]);
        d.x += s.weight * float(std::cos(th));
        d.y += s.weight * float(std::sin(th));
      }
      return d;
    };
    Vec2 center{f.width * 0.5f, f.height * 0.5f};
    int copies = std::clamp(m.copias, 1, 6);
    // Encaje: el tamaño sale de la figura real sin música (así la música la
    // agranda) y, con copias girando, de su distancia máxima al centro.
    float maxR = 1e-3f, maxX = 1e-3f, maxY = 1e-3f;
    for (int i = 0; i < 96; i++) {
      double a = 6.283185307179586 * double(i) / 96.0;
      float x = 0, y = 0;
      for (int k = 0; k < n; k++) {
        Vec2 d = arm(a, k);
        x += base[size_t(k)] * d.x;
        y += base[size_t(k)] * d.y;
      }
      maxR = std::max(maxR, std::sqrt(x * x + y * y));
      maxX = std::max(maxX, std::fabs(x));
      maxY = std::max(maxY, std::fabs(y));
    }
    float fit = copies > 1 ? std::min(f.width, f.height) * 0.46f / maxR
                           : std::min(f.width * 0.44f / maxX, f.height * 0.36f / maxY);
    float scale = fit * (1.0f + 0.1f * bass * amp);
    auto tip = [&](double a, std::array<Vec2, kMax + 1>* chain) {
      Vec2 p = center;
      if (chain) (*chain)[0] = p;
      for (int k = 0; k < n; k++) {
        Vec2 d = arm(a, k);
        p.x += radii[size_t(k)] * scale * d.x;
        p.y += radii[size_t(k)] * scale * d.y;
        if (chain) (*chain)[size_t(k + 1)] = p;
      }
      return p;
    };
    // Copias giradas alrededor del centro.
    auto turn = [&](Vec2 p, int copy) {
      if (copy == 0) return p;
      float a = 6.2831853f * float(copy) / float(copies);
      float cs = std::cos(a), sn = std::sin(a);
      float dx = p.x - center.x, dy = p.y - center.y;
      return Vec2{center.x + dx * cs - dy * sn, center.y + dx * sn + dy * cs};
    };

    // Figura completa tenue y estela reciente brillante, por tramos.
    Path full;
    std::vector<Vec2> curve(kCurve + 1);
    for (int i = 0; i <= kCurve; i++) curve[size_t(i)] = tip(angle + 6.283185307179586 * double(i) / double(kCurve), nullptr);
    for (int cp = 0; cp < copies; cp++) {
      for (int i = 0; i <= kCurve; i++) {
        Vec2 p = turn(curve[size_t(i)], cp);
        if (i == 0) full.moveTo(p.x, p.y); else full.lineTo(p.x, p.y);
      }
    }
    Paint faint;
    faint.strokeWidth = 1.6f * px;
    faint.strokeJoin = 1;
    faint.color = fire.opacity(0.3f);
    c.path(full, faint);

    const int chunks = 8;
    double span = 6.283185307179586 * double(m.estela);
    for (int ch = 0; ch < chunks; ch++) {
      float t = float(ch + 1) / float(chunks);
      Path seg;
      int steps = 40;
      std::array<Vec2, 41> pts{};
      for (int i = 0; i <= steps; i++) {
        double a = angle - span + span * (double(ch) + double(i) / double(steps)) / double(chunks);
        pts[size_t(i)] = tip(a, nullptr);
      }
      for (int cp = 0; cp < copies; cp++) {
        for (int i = 0; i <= steps; i++) {
          Vec2 p = turn(pts[size_t(i)], cp);
          if (i == 0) seg.moveTo(p.x, p.y); else seg.lineTo(p.x, p.y);
        }
      }
      Color col{fire.r + (lime.r - fire.r) * t, fire.g + (lime.g - fire.g) * t, fire.b + (lime.b - fire.b) * t, 1.0f};
      Paint glow;
      glow.blend = Blend::plus;
      glow.strokeWidth = (10.0f + 8.0f * bass) * px;
      glow.strokeCap = 1;
      glow.strokeJoin = 1;
      glow.color = col.opacity(std::clamp(0.18f * t * f.glow * amp, 0.0f, 1.0f));
      c.path(seg, glow);
      Paint line;
      line.blend = Blend::plus;
      line.strokeWidth = (2.0f + 2.6f * t + 1.5f * energy) * px;
      line.strokeCap = 1;
      line.strokeJoin = 1;
      line.color = col.opacity(std::clamp((0.3f + 0.7f * t) * amp, 0.0f, 1.0f));
      c.path(seg, line);
    }

    // Los círculos y sus brazos.
    std::array<Vec2, kMax + 1> chain{};
    Vec2 pen = tip(angle, &chain);
    if (m.mostrar) {
      Path rings, arms;
      for (int k = 0; k < n; k++) {
        rings.circle(chain[size_t(k)], std::max(radii[size_t(k)] * scale, 0.5f));
        arms.moveTo(chain[size_t(k)].x, chain[size_t(k)].y).lineTo(chain[size_t(k + 1)].x, chain[size_t(k + 1)].y);
      }
      Paint ring;
      ring.strokeWidth = 1.0f * px;
      ring.color = white.opacity(std::clamp((0.14f + 0.12f * kick) * amp, 0.0f, 1.0f));
      c.path(rings, ring);
      Paint arm;
      arm.strokeWidth = 1.4f * px;
      arm.strokeCap = 1;
      arm.color = white.opacity(std::clamp(0.45f * amp, 0.0f, 1.0f));
      c.path(arms, arm);
      std::vector<Vec2> joints(chain.begin(), chain.begin() + n);
      Paint dot;
      dot.color = white.opacity(std::clamp(0.6f * amp, 0.0f, 1.0f));
      c.points(joints, 1.8f * px, dot);
    }
    // El lápiz de luz.
    Paint halo = Paint::radial(pen, (14.0f + 10.0f * kick) * px, {lime.opacity(std::clamp(0.7f * f.glow * amp, 0.0f, 1.0f)), lime.opacity(0.0f)});
    halo.blend = Blend::plus;
    c.circle(pen, (14.0f + 10.0f * kick) * px, halo);
    Paint penDot;
    penDot.color = Color{1.0f, 1.0f, 0.95f, 1.0f};
    c.circle(pen, 2.6f * px, penDot);
  }
};

class Visual final : public Scene {
  static constexpr int kMaxSteps = 32;
  struct Block { float x, y, z; int index; };
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  // Relojes en doble precisión: la escena sin música es idéntica a 30 y 60 FPS.
  double walk = 0, runner = 100, sinceStyle = 0;
  float neon = 0, neonTarget = 0, runnerPower = 0;
  int beats = 0;

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

  static Color shade(const Color& c, float g) {
    return {std::min(1.0f, c.r * g), std::min(1.0f, c.g * g), std::min(1.0f, c.b * g), 1.0f};
  }

  // Bloques del anillo: cuatro tramos (a, b, c, d) con el mismo ascenso por
  // escalón; el desplazamiento total (k, k, k) cae sobre la línea de vista.
  static int buildRing(int n, std::array<Block, kMaxSteps>& out, float& rise) {
    int side = std::max(2, n / 2);
    int a = n, b = n, cc = side, d = side;
    int k = a - cc;
    int total = a + b + cc + d;
    rise = float(k) / float(total);
    int x = 0, y = 0, i = 0;
    auto add = [&](int dx, int dy, int count) {
      for (int s = 0; s < count && i < kMaxSteps; s++) {
        out[size_t(i)] = {float(x), float(y), rise * float(i), i};
        x += dx;
        y += dy;
        i++;
      }
    };
    add(1, 0, a);
    add(0, 1, b);
    add(-1, 0, cc);
    add(0, -1, d);
    return i;
  }

 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    walk = rng.unit() * 10.0;
    runner = 100;
    sinceStyle = 0;
    neon = neonTarget = 0;
    runnerPower = 0;
    beats = 0;
  }

  void update(const Frame& f) override {
    auto m = modifiers(f);
    float dt = float(f.delta);
    const Music& mu = f.music;
    bass = follow(bass, mu.bass, 22.0f, 4.5f, dt);
    body = follow(body, mu.body, 12.0f, 3.0f, dt);
    spark = follow(spark, mu.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, mu.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, mu.active ? std::pow(std::clamp(mu.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : mu.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : mu.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : mu.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((mu.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, mu.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    runner += f.delta;
    sinceStyle += f.delta;
    if (hit > kick + 0.2f) {
      beats++;
      runner = 0;
      runnerPower = hit;
      if (beats % 8 == 0) {
        neonTarget = 1.0f - neonTarget;
        sinceStyle = 0;
      }
    }
    if (!mu.active && sinceStyle > 10.0) {
      neonTarget = 1.0f - neonTarget;
      sinceStyle = 0;
    }
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    float goal = m.estilo == 1 ? 0.0f : (m.estilo == 2 ? 1.0f : neonTarget);
    neon += (goal - neon) * (1.0f - std::exp(-dt * 2.5f));
    walk += f.delta * f.speed * m.subida * (1.5 + 3.0 * drive);
  }

  void render(const Frame& f, Canvas& c) const override {
    auto m = modifiers(f);
    float amp = f.intensity;
    std::vector<float> u;
    u.reserve(20);
    u.insert(u.end(), {bass * amp, kick * amp, energy, f.glow});
    u.insert(u.end(), {spark * amp, flash * amp, neon, 0.0f});
    for (int i = 0; i < 4; i++) u.insert(u.end(), {f.colors[i].r, f.colors[i].g, f.colors[i].b});
    c.material("iso_backdrop", {0, 0, f.width, f.height}, u);

    std::array<Block, kMaxSteps> ring{};
    float rise = 0;
    int count = buildRing(std::clamp(m.escalones, 4, 10), ring, rise);
    // Cada escalón es una columna hasta un suelo común, como el edificio de Escher.
    const float ground = -2.4f;
    // Proyección isométrica y encuadre: el anillo ocupa el ancho disponible.
    // Vista algo cenital; la altura escala al doble que la profundidad para
    // que el ascenso total (k, k, k) caiga exactamente sobre el comienzo.
    auto isoX = [](float x, float y) { return (x - y) * 0.8f; };
    auto isoY = [](float x, float y, float z) { return (x + y) * 0.6f - z * 1.2f; };
    float minX = 1e9f, maxX = -1e9f, minY = 1e9f, maxY = -1e9f;
    for (int i = 0; i < count; i++) {
      const Block& b = ring[size_t(i)];
      for (int cx = 0; cx <= 1; cx++) {
        for (int cy = 0; cy <= 1; cy++) {
          float X = isoX(b.x + cx, b.y + cy);
          minX = std::min(minX, X);
          maxX = std::max(maxX, X);
          minY = std::min(minY, isoY(b.x + cx, b.y + cy, b.z));
          maxY = std::max(maxY, isoY(b.x + cx, b.y + cy, ground));
        }
      }
    }
    float S = std::min(f.width * 0.86f / (maxX - minX), f.height * 0.62f / (maxY - minY));
    float ox = f.width * 0.5f - (minX + maxX) * 0.5f * S;
    float oy = f.height * 0.5f - (minY + maxY) * 0.5f * S;
    auto P = [&](float x, float y, float z) { return Vec2{ox + isoX(x, y) * S, oy + isoY(x, y, z) * S}; };

    // Orden de pintor: primero lo más lejano de la cámara.
    std::array<int, kMaxSteps> order{};
    for (int i = 0; i < count; i++) order[size_t(i)] = i;
    std::sort(order.begin(), order.begin() + count, [&](int l, int r) {
      const Block& a = ring[size_t(l)];
      const Block& b = ring[size_t(r)];
      if (a.x + a.y != b.x + b.y) return a.x + a.y < b.x + b.y;
      return a.z < b.z;
    });

    float walker = float(std::fmod(walk, double(count)));
    float run = float(runner) * 18.0f;
    const Color& coral = f.colors[1];
    const Color& yellow = f.colors[2];
    const Color& blue = f.colors[3];
    float px = std::min(f.width, f.height) / 400.0f;
    for (int oi = 0; oi < count; oi++) {
      const Block& b = ring[size_t(order[size_t(oi)])];
      // Luz que sube: distancia cíclica al caminante y al destello del golpe.
      float d = std::fabs(float(b.index) - walker);
      d = std::min(d, float(count) - d);
      float lit = m.caminante ? std::exp(-d * d * 0.6f) : 0.0f;
      float dr = std::fabs(float(b.index) - std::fmod(run, float(count)));
      dr = std::min(dr, float(count) - dr);
      lit += runner < 1.5 ? std::exp(-dr * dr * 0.5f) * runnerPower * float(1.0 - runner / 1.5) : 0.0f;
      float glow = (0.8f + 0.5f * bass + 0.9f * lit) * amp;
      // La luz que pasa levanta el escalón un poco.
      float zt = b.z + 0.22f * std::min(lit, 1.5f), zb = ground;
      Path top, right, left;
      Vec2 t0 = P(b.x, b.y, zt), t1 = P(b.x + 1, b.y, zt), t2 = P(b.x + 1, b.y + 1, zt), t3 = P(b.x, b.y + 1, zt);
      top.moveTo(t0.x, t0.y).lineTo(t1.x, t1.y).lineTo(t2.x, t2.y).lineTo(t3.x, t3.y).close();
      Vec2 r0 = P(b.x + 1, b.y, zt), r1 = P(b.x + 1, b.y + 1, zt), r2 = P(b.x + 1, b.y + 1, zb), r3 = P(b.x + 1, b.y, zb);
      right.moveTo(r0.x, r0.y).lineTo(r1.x, r1.y).lineTo(r2.x, r2.y).lineTo(r3.x, r3.y).close();
      Vec2 l0 = P(b.x, b.y + 1, zt), l1 = P(b.x + 1, b.y + 1, zt), l2 = P(b.x + 1, b.y + 1, zb), l3 = P(b.x, b.y + 1, zb);
      left.moveTo(l0.x, l0.y).lineTo(l1.x, l1.y).lineTo(l2.x, l2.y).lineTo(l3.x, l3.y).close();
      // Macizo: caras de color; neón: caras oscuras con aristas encendidas.
      float solid = 1.0f - neon;
      Color dark = f.colors[0];
      auto faceColor = [&](const Color& c, float g) {
        Color s = shade(c, g * glow);
        Color n = shade(dark, 1.4f);
        return Color{n.r + (s.r - n.r) * solid, n.g + (s.g - n.g) * solid, n.b + (s.b - n.b) * solid, 1.0f};
      };
      // Las paredes se oscurecen hacia el suelo.
      Paint pt;
      pt.color = faceColor(yellow, 1.0f);
      Vec2 rTop{(r0.x + r1.x) * 0.5f, (r0.y + r1.y) * 0.5f}, rBot{(r2.x + r3.x) * 0.5f, (r2.y + r3.y) * 0.5f};
      Vec2 lTop{(l0.x + l1.x) * 0.5f, (l0.y + l1.y) * 0.5f}, lBot{(l2.x + l3.x) * 0.5f, (l2.y + l3.y) * 0.5f};
      Paint pr = Paint::linear(rTop, rBot, {faceColor(coral, 0.9f), faceColor(coral, 0.3f)});
      Paint pl = Paint::linear(lTop, lBot, {faceColor(blue, 0.85f), faceColor(blue, 0.28f)});
      c.path(top, pt);
      c.path(right, pr);
      c.path(left, pl);
      Paint edge;
      edge.strokeWidth = (1.0f + 1.2f * neon) * px;
      edge.strokeJoin = 1;
      float e = 0.25f + 0.75f * neon;
      edge.color = {std::min(1.0f, yellow.r * e * glow), std::min(1.0f, yellow.g * e * glow), std::min(1.0f, yellow.b * e * glow), 1.0f};
      if (neon < 0.5f) edge.color = {dark.r * 0.5f, dark.g * 0.5f, dark.b * 0.5f, 0.6f};
      c.path(top, edge);
      Paint edge2 = edge;
      if (neon >= 0.5f) edge2.color = {std::min(1.0f, coral.r * glow), std::min(1.0f, coral.g * glow), std::min(1.0f, coral.b * glow), 1.0f};
      c.path(right, edge2);
      Paint edge3 = edge;
      if (neon >= 0.5f) edge3.color = {std::min(1.0f, blue.r * glow), std::min(1.0f, blue.g * glow), std::min(1.0f, blue.b * glow), 1.0f};
      c.path(left, edge3);
      if (lit > 0.05f) {
        Paint halo;
        halo.blend = Blend::plus;
        halo.color = {yellow.r, yellow.g, yellow.b, std::clamp(0.35f * lit * f.glow, 0.0f, 1.0f)};
        c.path(top, halo);
      }
    }
  }
};

