    explodeVel += (-explode * 6.0f - explodeVel * 2.6f) * dt;
    explode += explodeVel * dt;
    breathVel += (-breath * 40.0f - breathVel * 7.0f) * dt;
    breath += breathVel * dt;
    ringR += dt * (0.8f + 0.5f * drive);
    ringAmp *= std::exp(-dt * 2.2f);

