visuals.nativeSource:
class Visual final : public Scene {
  static constexpr int kRows = 130;
  static constexpr int kBins = 32;
  static constexpr int kFig = 16;
  // Figuras escondidas: cada vuelta de kCycle filas tiene kSlots huecos fijos;
  // el ajuste decide cuántos se llenan. Todo sale del número de fila.
  static constexpr int kCycle = 192;
  static constexpr int kSlots = 3;
  // Golpes: anillo fijo de las últimas filas donde cayó un golpe.
  static constexpr int kHits = 16;
  struct Hit { int64_t row; float strength; };
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  // Relojes en doble precisión: la escena sin música es idéntica a 30 y 60 FPS.
  double rowClock = 0;
  int64_t captured = 0;
  int head = 0, figureSeed = 0, hitHead = 0;
  std::array<std::array<float, kBins>, kRows> rows{};
  std::array<Hit, kHits> hits{};
  std::array<float, 31> live{};
  bool active = false;

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

  // Figuras de 16×16 escondidas: cara, corazón, estrella y ojo.
  static uint16_t figureRowBits(int fig, int row) {
    static const uint16_t art[4][kFig] = {
        {0x07E0, 0x1818, 0x2004, 0x4002, 0x4C32, 0x8C31, 0x8001, 0x8001, 0x8001, 0x9009, 0x8811, 0x47E2, 0x4002, 0x2004, 0x1818, 0x07E0},
        {0x0000, 0x1C38, 0x3E7C, 0x7FFE, 0x7FFE, 0x7FFE, 0x7FFE, 0x3FFC, 0x1FF8, 0x0FF0, 0x07E0, 0x03C0, 0x0180, 0x0000, 0x0000, 0x0000},
        {0x0180, 0x0180, 0x03C0, 0x03C0, 0x07E0, 0xFFFF, 0x7FFE, 0x3FFC, 0x1FF8, 0x0FF0, 0x1FF8, 0x1E78, 0x3C3C, 0x381C, 0x700E, 0x6006},
        {0x0000, 0x0000, 0x07E0, 0x1FF8, 0x3C3C, 0x700E, 0x63C6, 0xC7E3, 0xC7E3, 0x63C6, 0x700E, 0x3C3C, 0x1FF8, 0x07E0, 0x0000, 0x0000}};
    return art[fig % 4][std::clamp(row, 0, kFig - 1)];
  }

  // Fila de demostración sin música, calculada sólo del tiempo de la fila.
  static float idleBin(int b, double t) {
    float x = float(b) / float(kBins - 1);
    float sweep = float(std::fmod(t * 0.18, 1.0));
    float chirp = std::exp(-std::pow((x - sweep) * 14.0f, 2.0f));
    float wob = 0.5f + 0.35f * float(std::sin(t * 0.7));
    float tone = std::exp(-std::pow((x - wob) * 20.0f, 2.0f)) * 0.8f;
    float beat = std::fmod(t, 0.5) < 0.06 ? std::exp(-x * 4.0f) * 0.9f : 0.0f;
    float noise = 0.05f + 0.05f * float(std::sin(double(b) * 12.9898 + t * 78.233 - std::floor(double(b) * 12.9898 + t * 78.233)));
    return std::clamp(chirp * 0.9f + tone + beat + noise * 0.5f, 0.0f, 1.0f);
  }

  void capture() {
    head = (head + 1) % kRows;
    double t = double(captured) / 30.0;
    auto& row = rows[size_t(head)];
    for (int b = 0; b < kBins; b++) {
      float v;
      if (active) {
        float pos = float(b) / float(kBins - 1) * 29.5f;
        int i0 = int(pos);
        float fr = pos - float(i0);
        v = (live[size_t(i0)] * (1.0f - fr) + live[size_t(std::min(i0 + 1, 30))] * fr) * 1.25f;
      } else {
        v = idleBin(b, t);
      }
      row[size_t(b)] = std::clamp(v, 0.0f, 1.0f);
    }
  }

 public:
  void reset(uint32_t seed) override {
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    rowClock = 0;
    captured = 0;
    head = 0;
    figureSeed = int(seed % 4u);
    hitHead = 0;
    for (auto& r : rows) r.fill(0);
    hits.fill(Hit{-1000000, 0.0f});
    live.fill(0);
    active = false;
  }

  void update(const Frame& f) override {
    float dt = float(f.delta);
    const Music& mu = f.music;
    bass = follow(bass, mu.bass, 22.0f, 4.5f, dt);
    body = follow(body, mu.body, 12.0f, 3.0f, dt);
    spark = follow(spark, mu.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, mu.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, mu.active ? std::pow(std::clamp(mu.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : mu.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : mu.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : mu.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((mu.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, mu.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    const bool fresh = hit > kick + 0.2f;
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    active = mu.active;
    for (int i = 0; i < 31; i++) live[size_t(i)] = mu.smoothSpectrum[size_t(i)];
    rowClock += f.delta * f.speed;
    int64_t target = int64_t(std::floor(rowClock * 30.0 + 1e-6));
    if (target - captured > kRows) captured = target - kRows;
    while (captured < target) {
      captured++;
      capture();
    }
    // El golpe queda anotado en la fila más nueva; render dibuja su franja.
    if (fresh) {
      hits[size_t(hitHead)] = Hit{captured, hit};
      hitHead = (hitHead + 1) % kHits;
    }
  }

  void render(const Frame& f, Canvas& c) const override {
    auto g = glide(f);
    const bool mirror = modifiers(f).espejo;
    float amp = f.intensity;
    const Color& bg = f.colors[0];
    Paint back;
    back.color = Color{bg.r, bg.g, bg.b, 1.0f};
    c.rect({0, 0, f.width, f.height}, back);
    const int buckets = 8;
    std::array<Color, buckets> ramp;
    for (int k = 0; k < buckets; k++) {
      float v = (float(k) + 1.0f) / float(buckets);
      const Color& a = f.colors[1];
      const Color& b = f.colors[2];
      const Color& d = f.colors[3];
      Color col;
      if (v < 0.4f) col = Color{a.r * v / 0.4f, a.g * v / 0.4f, a.b * v / 0.4f, 1.0f};
      else if (v < 0.7f) { float u = (v - 0.4f) / 0.3f; col = Color{a.r + (b.r - a.r) * u, a.g + (b.g - a.g) * u, a.b + (b.b - a.b) * u, 1.0f}; }
      else if (v < 0.9f) { float u = (v - 0.7f) / 0.2f; col = Color{b.r + (d.r - b.r) * u, b.g + (d.g - b.g) * u, b.b + (d.b - b.b) * u, 1.0f}; }
      else col = Color{1.0f, 1.0f, 0.92f, 1.0f};
      ramp[size_t(k)] = col;
    }
    // Pulso: cada opción mueve algo distinto; sus pesos funden el cambio.
    const float calor = std::clamp(g.paleta.weight(0), 0.0f, 1.0f);
    const float golpes = std::clamp(g.paleta.weight(1), 0.0f, 1.0f);
    const float graves = std::clamp(g.paleta.weight(2), 0.0f, 1.0f);
    // Caída: proyección de cada fila (u va de 0 arriba a 1 abajo). Con 1 las
    // filas son parejas; por debajo llegan grandes y se alejan frenando; por
    // encima nacen finas y se agrandan acelerando hacia abajo.
    const float lean = std::pow(std::clamp(g.velocidad, 0.4f, 2.5f), -1.5f);
    const float bend = lean - 1.0f;
    auto rowY = [&](float u) { return f.height * u * lean / (1.0f + bend * u); };
    const float rowU = 1.0f / float(kRows - 2);
    // Graves: el bajo ensancha la zona de graves y empuja los agudos.
    const float swell = graves * std::clamp(bass * amp, 0.0f, 1.0f) * 0.85f;
    const float span = mirror ? f.width * 0.5f : f.width;
    std::array<float, kBins + 1> edge;
    for (int b = 0; b <= kBins; b++) {
      float u = float(b) / float(kBins);
      edge[size_t(b)] = span * (u + swell * u * (1.0f - u));
    }
    // Sub-fila coherente con la fila capturada (mismo redondeo que update).
    float frac = std::clamp(float(rowClock * 30.0 + 1e-6 - double(captured)), 0.0f, 1.0f);
    std::array<Path, buckets> paths;
    std::array<float, kBins> cell;
    const int figStart = std::max(0, (kBins - kFig) / 2);
    for (int a = 0; a < kRows; a++) {
      const auto& row = rows[size_t(((head - a) % kRows + kRows) % kRows)];
      float u0 = (float(a) - 1.0f + frac) * rowU;
      float y = rowY(u0);
      if (y > f.height) break;
      float rowH = rowY(u0 + rowU) - y;
      const int64_t idx = captured - int64_t(a);
      for (int b = 0; b < kBins; b++) cell[size_t(b)] = row[size_t(b)];
      if (idx >= 0) {
        // Figura escondida: hueco fijo de la vuelta; se lee de abajo arriba
        // para que se vea derecha.
        const int64_t cycle = idx / kCycle;
        const int o = int(idx % kCycle);
        for (int k = 0; k < kSlots; k++) {
          const int start = 24 + k * 64;
          if (o < start || o >= start + kFig) continue;
          const float show = std::clamp(g.figuras - float(k), 0.0f, 1.0f);
          if (show <= 0.0f) break;
          const int fig = int((cycle * kSlots + k + figureSeed) % 4);
          const uint16_t bits = figureRowBits(fig, kFig - 1 - (o - start));
          for (int q = 0; q < kFig; q++) {
            if (bits & (0x8000 >> q)) cell[size_t(figStart + q)] = std::max(cell[size_t(figStart + q)], 0.95f * show);
          }
          break;
        }
        // Golpes: una franja caliente en la fila del golpe que se apaga hacia
        // las filas más nuevas.
        if (golpes > 0.0f) {
          float line = 0.0f;
          for (const auto& h : hits) {
            const int64_t d = idx - h.row;
            if (d >= 0 && d < 8) line = std::max(line, h.strength * std::exp(-float(d) * 0.3f));
          }
          line = std::min(line, 1.0f) * golpes * 0.85f;
          if (line > 0.0f) {
            for (int b = 0; b < kBins; b++) cell[size_t(b)] = std::max(cell[size_t(b)], line * (0.88f + 0.12f * row[size_t(b)]));
          }
        }
      }
      int b = 0;
      while (b < kBins) {
        int k = std::min(buckets - 1, int(cell[size_t(b)] * amp * float(buckets)));
        if (cell[size_t(b)] * amp < 0.08f) {
          b++;
          continue;
        }
        int startB = b;
        while (b < kBins && std::min(buckets - 1, int(cell[size_t(b)] * amp * float(buckets))) == k && cell[size_t(b)] * amp >= 0.08f) b++;
        float x0 = edge[size_t(startB)], x1 = edge[size_t(b)];
        if (mirror) {
          paths[size_t(k)].rect({f.width * 0.5f + x0, y, x1 - x0 + 0.5f, rowH + 0.5f});
          paths[size_t(k)].rect({f.width * 0.5f - x1, y, x1 - x0 + 0.5f, rowH + 0.5f});
        } else {
          paths[size_t(k)].rect({x0, y, x1 - x0 + 0.5f, rowH + 0.5f});
        }
      }
    }
    for (int k = 0; k < buckets; k++) {
      Paint p;
      p.color = ramp[size_t(k)];
      c.path(paths[size_t(k)], p);
    }
    // Brillo de la fila que está entrando; con Calor, cada golpe lo enciende.
    const float edgeH = std::max(1.0f, rowY(8.0f * rowU));
    Paint edgeGlow = Paint::linear({0, 0}, {0, edgeH}, {f.colors[3].opacity(std::clamp((0.25f + 0.3f * kick * calor) * amp, 0.0f, 1.0f)), f.colors[3].opacity(0.0f)});
    edgeGlow.blend = Blend::plus;
    c.rect({0, 0, f.width, edgeH}, edgeGlow);
    if (flash > 0.01f) {
      Paint fl;
      fl.blend = Blend::plus;
      fl.color = f.colors[2].opacity(std::clamp(flash * 0.05f * amp, 0.0f, 1.0f));
      c.rect({0, 0, f.width, f.height}, fl);
    }
  }
};

class Visual final : public Scene {
  // mix reparte las fichas entre dos recorridos mientras uno se funde en otro.
  struct Domino { float x, y, dx, dy, hue, mix; int chain, index; };
  struct Chain { float delay; int count; };
  enum Phase { kTopple, kHold, kRise, kRest };
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  // Relojes en doble precisión: la escena sin música es idéntica a 30 y 60 FPS.
  double g = 0, phaseTime = 0, total = 1;
  // Duración de la caída con cada recorrido (directo, al revés, dos frentes).
  std::array<double, 3> totals{1, 1, 1};
  float maxDelay = 0;
  int phase = kTopple, pattern = -1, autoPattern = 0;
  float aspect = 2.0f;
  // Reloj de los destellos de los agudos.
  double twinkle = 0;
  std::vector<Domino> dominoes;
  std::vector<Chain> chains;

  static constexpr float kSpacing = 0.03f;
  static constexpr float kSpeed = 70.0f;

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

  static float hashU(uint32_t x) {
    x ^= x >> 16; x *= 0x7feb352dU; x ^= x >> 15; x *= 0x846ca68bU; x ^= x >> 16;
    return float(x & 0xffffffu) / 16777216.0f;
  }

  void addSpiral(float rOut, float rIn, float turns, float offset, float delay) {
    int chain = int(chains.size());
    float b = (rOut - rIn) / (turns * 6.2831853f);
    float theta = 0;
    int idx = 0;
    while (true) {
      float r = rOut - b * theta;
      if (r < rIn) break;
      float a = theta + offset;
      float x = r * std::cos(a), y = r * std::sin(a);
      // Dirección de avance: tangente de la espiral hacia dentro.
      float tx = -b * std::cos(a) - r * std::sin(a), ty = -b * std::sin(a) + r * std::cos(a);
      float tl = std::sqrt(tx * tx + ty * ty) + 1e-6f;
      dominoes.push_back({x, y, tx / tl, ty / tl, 0.0f, 0.0f, chain, idx++});
      theta += kSpacing / std::max(r, 0.02f);
    }
    chains.push_back({delay, idx});
  }

  void addRing(float r, float delay) {
    // Dos medias vueltas que salen del mismo punto en sentidos opuestos.
    for (int side = 0; side < 2; side++) {
      int chain = int(chains.size());
      int count = int(3.14159265f * r / kSpacing);
      for (int i = 0; i < count; i++) {
        float a = -1.5707963f + (side == 0 ? 1.0f : -1.0f) * float(i) / float(count) * 3.14159265f;
        float x = r * std::cos(a), y = r * std::sin(a);
        float s = side == 0 ? 1.0f : -1.0f;
        dominoes.push_back({x, y, -std::sin(a) * s, std::cos(a) * s, 0.0f, 0.0f, chain, i});
      }
      chains.push_back({delay, count});
    }
  }

  void build(int which) {
    pattern = which;
    dominoes.clear();
    chains.clear();
    float rOut = 0.46f;
    if (which == 0) {
      addSpiral(rOut, 0.05f, 5.0f, 0.0f, 0.0f);
    } else if (which == 1) {
      for (int k = 0; k < 3; k++) addSpiral(rOut, 0.07f, 1.8f, 6.2831853f * float(k) / 3.0f, 0.0f);
    } else {
      for (int k = 0; k < 7; k++) addRing(0.06f + 0.065f * float(k), 0.35f * float(k));
    }
    // Color a lo largo del recorrido de cada cadena.
    for (auto& d : dominoes) {
      const Chain& ch = chains[size_t(d.chain)];
      d.hue = (float(d.index) / float(std::max(ch.count - 1, 1)) + float(d.chain % 3) * 0.04f);
      uint32_t h = uint32_t(d.chain) * 2654435761u ^ uint32_t(d.index) * 2246822519u;
      h ^= h >> 15;
      h *= 2654435761u;
      d.mix = float(h >> 8) / 16777216.0f;
    }
    maxDelay = 0;
    for (const auto& ch : chains) maxDelay = std::max(maxDelay, ch.delay);
    totals = {0, 0, 0};
    for (const auto& ch : chains) {
      double run = double(ch.count) / double(kSpeed), half = double((ch.count + 1) / 2) / double(kSpeed);
      totals[0] = std::max(totals[0], double(ch.delay) + run);
      totals[1] = std::max(totals[1], double(maxDelay - ch.delay) + run);
      totals[2] = std::max(totals[2], double(ch.delay) + half);
    }
    for (auto& t : totals) t += 0.4;
    total = totals[0];
  }

 public:
  void reset(uint32_t seed) override {
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    g = 0;
    phaseTime = 0;
    phase = kTopple;
    pattern = -1;
    autoPattern = int(seed % 3u);
    twinkle = 0;
    dominoes.reserve(4000);
    chains.reserve(32);
  }

  void update(const Frame& f) override {
    auto m = modifiers(f);
    float dt = float(f.delta);
    const Music& mu = f.music;
    bass = follow(bass, mu.bass, 22.0f, 4.5f, dt);
    body = follow(body, mu.body, 12.0f, 3.0f, dt);
    spark = follow(spark, mu.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, mu.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, mu.active ? std::pow(std::clamp(mu.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : mu.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : mu.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : mu.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((mu.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, mu.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    bool beat = hit > kick + 0.2f;
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    aspect = f.height / std::max(std::min(f.width, f.height), 1.0f);

    int wanted = m.patron == 0 ? autoPattern : m.patron - 1;
    if (wanted != pattern) {
      build(wanted);
      g = 0;
      phase = kTopple;
      phaseTime = 0;
    }
    total = totals[size_t(std::clamp(m.recorrido, 0, 2))];
    twinkle += f.delta;
    // Golpes: cada golpe empuja la ola muchas fichas de una vez.
    double rate = f.delta * f.speed * (1.0 + 1.2 * drive) + (beat && phase == kTopple ? 0.08 * double(hit) : 0.0) +
                  (beat && phase == kTopple && m.pulso == 0 ? 0.22 * double(std::min(hit * f.intensity, 1.0f)) : 0.0);
    phaseTime += rate;
    for (int guard = 0; guard < 4; guard++) {
      if (phase == kTopple) {
        g = std::min(phaseTime, total);
        if (phaseTime < total) break;
        phaseTime -= total;
        phase = kHold;
      } else if (phase == kHold) {
        if (phaseTime < 1.2) break;
        phaseTime -= 1.2;
        phase = kRise;
      } else if (phase == kRise) {
        // Se rebobina al doble de velocidad.
        g = std::max(0.0, total - phaseTime * 2.0);
        if (g > 0.0) break;
        phaseTime -= total / 2.0;
        phase = kRest;
      } else {
        if (phaseTime < 0.8) break;
        phaseTime -= 0.8;
        phase = kTopple;
        g = 0;
        if (m.patron == 0) {
          autoPattern = (autoPattern + 1) % 3;
          build(autoPattern);
        }
      }
    }
  }

  void render(const Frame& f, Canvas& c) const override {
    auto m = modifiers(f);
    auto gl = glide(f);
    float amp = f.intensity;
    // Pulso: cada opción mueve algo distinto; sin música todo vale cero.
    const float kickP = std::min(kick * amp, 1.0f) * gl.pulso.weight(0);
    const float bassP = std::min(bass * amp, 1.0f) * gl.pulso.weight(1);
    const float sparkP = std::min(spark * amp, 1.0f) * gl.pulso.weight(2);
    const uint32_t tick = uint32_t(std::fmod(twinkle, 100000.0) * 12.0);
    const Color& bg = f.colors[0];
    c.rect({0, 0, f.width, f.height}, Paint::radial({f.width * 0.5f, f.height * 0.5f}, std::max(f.width, f.height) * 0.7f,
                                                   {Color{std::min(1.0f, bg.r + 0.06f), std::min(1.0f, bg.g + 0.05f), std::min(1.0f, bg.b + 0.07f), 1.0f},
                                                    Color{bg.r, bg.g, bg.b, 1.0f}}));
    // Golpes: el dibujo da un salto; Graves: respira con los graves.
    float side = std::min(f.width, f.height) * 1.0f * (1.0f + 0.1f * kickP + 0.12f * bassP);
    float px = side / 400.0f;
    Vec2 center{f.width * 0.5f, f.height * 0.5f};
    // Graves: las fichas crecen con los graves.
    const float grow = 1.0f + 0.12f * kickP + 0.15f * bassP;
    const float L = 0.024f * grow, T = 0.006f * grow, W = 0.02f * grow;
    const int buckets = 12, levels = 5;
    std::array<Path, buckets * levels> fallen;
    std::array<Path, buckets> standing;
    // Halo de las fichas recién caídas (sólo con Estela de luz).
    const int haloLevels = 3;
    std::array<std::vector<Vec2>, buckets * haloLevels> halos;
    // La ficha que está cayendo en cada frente lleva la luz: su color y lugar.
    std::vector<std::pair<Vec2, int>> heads;
    Path shadow;
    // Agudos: fichas sueltas que destellan.
    Path glint;
    // Recorrido: mientras uno se funde en otro, cada ficha sigue uno de los dos.
    const float wDirect = gl.recorrido.weight(0), wReverse = gl.recorrido.weight(1);
    const float estela = std::clamp(gl.estela, 0.0f, 1.0f);
    for (const auto& d : dominoes) {
      const Chain& ch = chains[size_t(d.chain)];
      const int way = d.mix < wDirect ? 0 : (d.mix < wDirect + wReverse ? 1 : 2);
      const float delay = way == 1 ? maxDelay - ch.delay : ch.delay;
      const int back = ch.count - 1 - d.index;
      // Puesto de la ficha en su ola y hacia dónde cae (la ola la empuja).
      const bool forward = way == 0 || (way == 2 && d.index <= back);
      const float pos = float(forward ? d.index : back), dir = forward ? 1.0f : -1.0f;
      float front = float((g - double(delay)) * double(kSpeed));
      float tilt = std::clamp((front - pos) / 2.5f, 0.0f, 1.0f);
      float s = std::sin(tilt * 1.5707963f * 0.92f);
      float len = T + (L - T) * s;
      float bx = d.x - dir * d.dx * T * 0.5f, by = d.y - dir * d.dy * T * 0.5f;
      float ex = bx + dir * d.dx * len, ey = by + dir * d.dy * len;
      float nx = -d.dy * W * 0.5f, ny = d.dx * W * 0.5f;
      auto P = [&](float x, float y) { return Vec2{center.x + x * side, center.y + y * side}; };
      Vec2 p0 = P(bx + nx, by + ny), p1 = P(ex + nx, ey + ny), p2 = P(ex - nx, ey - ny), p3 = P(bx - nx, by - ny);
      int b = std::min(buckets - 1, int(d.hue * float(buckets)));
      // Estela de luz: cuanto más lejos quedó la ola, más se apaga la ficha;
      // las recién caídas brillan con un halo de su color.
      float age = std::clamp((front - pos - 3.0f) / 30.0f, 0.0f, 1.0f);
      int level = std::clamp(int(std::lround(age * float(levels - 1))), 0, levels - 1);
      Path& dst = tilt > 0.5f ? fallen[size_t(b * levels + level)] : standing[size_t(b)];
      if (estela > 0.001f && tilt > 0.5f && level < haloLevels)
        halos[size_t(b * haloLevels + level)].push_back(P((bx + ex) * 0.5f, (by + ey) * 0.5f));
      if ((estela > 0.001f || kickP > 0.002f) && tilt > 0.4f && tilt <= 0.8f && heads.size() < 64) heads.push_back({P(d.x, d.y), b});
      dst.moveTo(p0.x, p0.y).lineTo(p1.x, p1.y).lineTo(p2.x, p2.y).lineTo(p3.x, p3.y).close();
      if (sparkP > 0.002f &&
          hashU(uint32_t(d.chain) * 2246822519u + uint32_t(d.index) * 2654435761u + tick * 40503u) < 0.3f * sparkP)
        glint.moveTo(p0.x, p0.y).lineTo(p1.x, p1.y).lineTo(p2.x, p2.y).lineTo(p3.x, p3.y).close();
      if (m.sombra) {
        float o = (1.0f + 2.5f * (1.0f - s)) * px;
        shadow.moveTo(p0.x + o, p0.y + o * 1.4f).lineTo(p1.x + o, p1.y + o * 1.4f).lineTo(p2.x + o, p2.y + o * 1.4f).lineTo(p3.x + o, p3.y + o * 1.4f).close();
      }
    }
    if (m.sombra) {
      Paint sp;
      sp.color = Color{0, 0, 0, 0.45f};
      c.path(shadow, sp);
    }
    // Resplandor local sobre el dibujo: Golpes lo enciende y Graves lo hace latir.
    const float aura = std::clamp((0.3f * kickP + 0.2f * bassP) * f.glow, 0.0f, 0.6f);
    if (aura > 0.002f) {
      Paint ap = Paint::radial(center, side * 0.55f, {f.colors[2].opacity(aura), f.colors[1].opacity(aura * 0.4f), f.colors[1].opacity(0.0f)},
                               {0.0f, 0.6f, 1.0f});
      ap.blend = Blend::plus;
      c.circle(center, side * 0.55f, ap);
    }
    // El arcoíris empieza en el tono del primer acento de la paleta.
    const Color& accent = f.colors[1];
    float hi = std::max(accent.r, std::max(accent.g, accent.b)), lo = std::min(accent.r, std::min(accent.g, accent.b));
    float spread = hi - lo, baseHue = 0.0f;
    if (spread > 1e-4f) {
      baseHue = hi == accent.r ? (accent.g - accent.b) / spread
                               : (hi == accent.g ? 2.0f + (accent.b - accent.r) / spread : 4.0f + (accent.r - accent.g) / spread);
      baseHue /= 6.0f;
    }
    std::array<Color, buckets> hues;
    for (int b = 0; b < buckets; b++) {
      float h = baseHue + (float(b) + 0.5f) / float(buckets) * 0.85f;
      h -= std::floor(h);
      hues[size_t(b)] = Color{std::clamp(std::fabs(h * 6.0f - 3.0f) - 1.0f, 0.0f, 1.0f), std::clamp(2.0f - std::fabs(h * 6.0f - 2.0f), 0.0f, 1.0f),
                              std::clamp(2.0f - std::fabs(h * 6.0f - 4.0f), 0.0f, 1.0f), 1.0f};
    }
    if (estela > 0.001f) {
      const float shine = estela * (0.5f + 0.5f * std::clamp(f.glow, 0.0f, 2.0f));
      // Cada frente lleva una luz que alumbra el suelo a su alrededor.
      for (const auto& [spot, b] : heads) {
        Paint pool = Paint::radial(spot, side * 0.17f,
                                   {hues[size_t(b)].opacity(std::clamp(0.2f * shine, 0.0f, 1.0f)), hues[size_t(b)].opacity(0.0f)});
        pool.blend = Blend::plus;
        c.circle(spot, side * 0.17f, pool);
      }
      // Dos discos por ficha (ancho y tenue, estrecho y más vivo): un halo suave.
      for (int b = 0; b < buckets; b++) {
        for (int level = 0; level < haloLevels; level++) {
          const auto& spots = halos[size_t(b * haloLevels + level)];
          if (spots.empty()) continue;
          float fresh = 1.0f - float(level) / float(haloLevels);
          Paint hp;
          hp.blend = Blend::plus;
          hp.color = hues[size_t(b)].opacity(std::clamp(0.10f * shine * fresh, 0.0f, 1.0f));
          c.points(spots, 20.0f * px, hp);
          hp.color = hues[size_t(b)].opacity(std::clamp(0.16f * shine * fresh, 0.0f, 1.0f));
          c.points(spots, 10.0f * px, hp);
        }
      }
    }
    // Golpes: la cabeza de cada ola se enciende con un charco de luz.
    if (kickP > 0.002f && !heads.empty()) {
      const float share = std::min(1.0f, 4.0f / float(heads.size()));
      for (const auto& [spot, b] : heads) {
        Paint pool = Paint::radial(spot, side * 0.2f,
                                   {hues[size_t(b)].opacity(std::clamp(0.7f * kickP * share, 0.0f, 1.0f)), hues[size_t(b)].opacity(0.0f)});
        pool.blend = Blend::plus;
        c.circle(spot, side * 0.2f, pool);
      }
    }
    for (int b = 0; b < buckets; b++) {
      const Color& col = hues[size_t(b)];
      // Golpes y Graves avivan la cadena caída.
      float lit = (0.85f + 0.25f * bass + 0.2f * kick) * amp * (1.0f + 0.7f * kickP + 0.6f * bassP + 0.3f * sparkP);
      for (int level = 0; level < levels; level++) {
        const Path& path = fallen[size_t(b * levels + level)];
        if (path.data().empty()) continue;
        float dim = lit * (1.0f - 0.78f * estela * float(level) / float(levels - 1));
        Paint fp;
        fp.color = Color{std::clamp(col.r * dim, 0.0f, 1.0f), std::clamp(col.g * dim, 0.0f, 1.0f), std::clamp(col.b * dim, 0.0f, 1.0f), 1.0f};
        c.path(path, fp);
      }
      // Con Estela de luz la sala se oscurece: las fichas en pie se apagan un poco.
      const float shade = (1.0f - 0.45f * estela) * (1.0f + 0.5f * kickP + 0.3f * bassP);
      Paint sp;
      sp.color = Color{std::clamp((col.r * 0.6f + 0.35f) * shade, 0.0f, 1.0f), std::clamp((col.g * 0.6f + 0.35f) * shade, 0.0f, 1.0f),
                       std::clamp((col.b * 0.6f + 0.35f) * shade, 0.0f, 1.0f), 1.0f};
      c.path(standing[size_t(b)], sp);
    }
    if (sparkP > 0.002f && !glint.data().empty()) {
      const Color& c3 = f.colors[3];
      Paint gp;
      gp.blend = Blend::plus;
      gp.color = Color{std::min(1.0f, c3.r * 0.5f + 0.5f), std::min(1.0f, c3.g * 0.5f + 0.5f), std::min(1.0f, c3.b * 0.5f + 0.5f),
                       std::clamp(0.95f * sparkP, 0.0f, 0.95f)};
      c.path(glint, gp);
    }
    (void)aspect;
    if (flash > 0.01f) {
      Paint fl;
      fl.blend = Blend::plus;
      fl.color = f.colors[2].opacity(std::clamp(flash * 0.05f * amp, 0.0f, 1.0f));
      c.rect({0, 0, f.width, f.height}, fl);
    }
  }
};

class Visual final : public Scene {
  // mix reparte las fichas entre dos recorridos mientras uno se funde en otro.
  struct Domino { float x, y, dx, dy, hue, mix; int chain, index; };
  struct Chain { float delay; int count; };
  enum Phase { kTopple, kHold, kRise, kRest };
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  // Relojes en doble precisión: la escena sin música es idéntica a 30 y 60 FPS.
  double g = 0, phaseTime = 0, total = 1;
  // Duración de la caída con cada recorrido (directo, al revés, dos frentes).
  std::array<double, 3> totals{1, 1, 1};
  float maxDelay = 0;
  int phase = kTopple, pattern = -1, autoPattern = 0;
  float aspect = 2.0f;
  // Reloj de los destellos de los agudos.
  double twinkle = 0;
  std::vector<Domino> dominoes;
  std::vector<Chain> chains;

  static constexpr float kSpacing = 0.03f;
  static constexpr float kSpeed = 70.0f;

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

  static float hashU(uint32_t x) {
    x ^= x >> 16; x *= 0x7feb352dU; x ^= x >> 15; x *= 0x846ca68bU; x ^= x >> 16;
    return float(x & 0xffffffu) / 16777216.0f;
  }

  void addSpiral(float rOut, float rIn, float turns, float offset, float delay) {
    int chain = int(chains.size());
    float b = (rOut - rIn) / (turns * 6.2831853f);
    float theta = 0;
    int idx = 0;
    while (true) {
      float r = rOut - b * theta;
      if (r < rIn) break;
      float a = theta + offset;
      float x = r * std::cos(a), y = r * std::sin(a);
      // Dirección de avance: tangente de la espiral hacia dentro.
      float tx = -b * std::cos(a) - r * std::sin(a), ty = -b * std::sin(a) + r * std::cos(a);
      float tl = std::sqrt(tx * tx + ty * ty) + 1e-6f;
      dominoes.push_back({x, y, tx / tl, ty / tl, 0.0f, 0.0f, chain, idx++});
      theta += kSpacing / std::max(r, 0.02f);
    }
    chains.push_back({delay, idx});
  }

  void addRing(float r, float delay) {
    // Dos medias vueltas que salen del mismo punto en sentidos opuestos.
    for (int side = 0; side < 2; side++) {
      int chain = int(chains.size());
      int count = int(3.14159265f * r / kSpacing);
      for (int i = 0; i < count; i++) {
        float a = -1.5707963f + (side == 0 ? 1.0f : -1.0f) * float(i) / float(count) * 3.14159265f;
        float x = r * std::cos(a), y = r * std::sin(a);
        float s = side == 0 ? 1.0f : -1.0f;
        dominoes.push_back({x, y, -std::sin(a) * s, std::cos(a) * s, 0.0f, 0.0f, chain, i});
      }
      chains.push_back({delay, count});
    }
  }

  void build(int which) {
    pattern = which;
    dominoes.clear();
    chains.clear();
    float rOut = 0.46f;
    if (which == 0) {
      addSpiral(rOut, 0.05f, 5.0f, 0.0f, 0.0f);
    } else if (which == 1) {
      for (int k = 0; k < 3; k++) addSpiral(rOut, 0.07f, 1.8f, 6.2831853f * float(k) / 3.0f, 0.0f);
    } else {
      for (int k = 0; k < 7; k++) addRing(0.06f + 0.065f * float(k), 0.35f * float(k));
    }
    // Color a lo largo del recorrido de cada cadena.
    for (auto& d : dominoes) {
      const Chain& ch = chains[size_t(d.chain)];
      d.hue = (float(d.index) / float(std::max(ch.count - 1, 1)) + float(d.chain % 3) * 0.04f);
      uint32_t h = uint32_t(d.chain) * 2654435761u ^ uint32_t(d.index) * 2246822519u;
      h ^= h >> 15;
      h *= 2654435761u;
      d.mix = float(h >> 8) / 16777216.0f;
    }
    maxDelay = 0;
    for (const auto& ch : chains) maxDelay = std::max(maxDelay, ch.delay);
    totals = {0, 0, 0};
    for (const auto& ch : chains) {
      double run = double(ch.count) / double(kSpeed), half = double((ch.count + 1) / 2) / double(kSpeed);
      totals[0] = std::max(totals[0], double(ch.delay) + run);
      totals[1] = std::max(totals[1], double(maxDelay - ch.delay) + run);
      totals[2] = std::max(totals[2], double(ch.delay) + half);
    }
    for (auto& t : totals) t += 0.4;
    total = totals[0];
  }

 public:
  void reset(uint32_t seed) override {
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    g = 0;
    phaseTime = 0;
    phase = kTopple;
    pattern = -1;
    autoPattern = int(seed % 3u);
    twinkle = 0;
    dominoes.reserve(4000);
    chains.reserve(32);
  }

  void update(const Frame& f) override {
    auto m = modifiers(f);
    float dt = float(f.delta);
    const Music& mu = f.music;
    bass = follow(bass, mu.bass, 22.0f, 4.5f, dt);
    body = follow(body, mu.body, 12.0f, 3.0f, dt);
    spark = follow(spark, mu.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, mu.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, mu.active ? std::pow(std::clamp(mu.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : mu.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : mu.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : mu.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((mu.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, mu.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    bool beat = hit > kick + 0.2f;
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    aspect = f.height / std::max(std::min(f.width, f.height), 1.0f);

    int wanted = m.patron == 0 ? autoPattern : m.patron - 1;
    if (wanted != pattern) {
      build(wanted);
      g = 0;
      phase = kTopple;
      phaseTime = 0;
    }
    total = totals[size_t(std::clamp(m.recorrido, 0, 2))];
    twinkle += f.delta;
    // Golpes: cada golpe empuja la ola muchas fichas de una vez.
    double rate = f.delta * f.speed * (1.0 + 1.2 * drive) + (beat && phase == kTopple ? 0.08 * double(hit) : 0.0) +
                  (beat && phase == kTopple && m.pulso == 0 ? 0.22 * double(std::min(hit * f.intensity, 1.0f)) : 0.0);
    phaseTime += rate;
    for (int guard = 0; guard < 4; guard++) {
      if (phase == kTopple) {
        g = std::min(phaseTime, total);
        if (phaseTime < total) break;
        phaseTime -= total;
        phase = kHold;
      } else if (phase == kHold) {
        if (phaseTime < 1.2) break;
        phaseTime -= 1.2;
        phase = kRise;
      } else if (phase == kRise) {
        // Se rebobina al doble de velocidad.
        g = std::max(0.0, total - phaseTime * 2.0);
        if (g > 0.0) break;
        phaseTime -= total / 2.0;
        phase = kRest;
      } else {
        if (phaseTime < 0.8) break;
        phaseTime -= 0.8;
        phase = kTopple;
        g = 0;
        if (m.patron == 0) {
          autoPattern = (autoPattern + 1) % 3;
          build(autoPattern);
        }
      }
    }
  }

  void render(const Frame& f, Canvas& c) const override {
    auto m = modifiers(f);
    auto gl = glide(f);
    float amp = f.intensity;
    // Pulso: cada opción mueve algo distinto; sin música todo vale cero.
    const float kickP = std::min(kick * amp, 1.0f) * gl.pulso.weight(0);
    const float bassP = std::min(bass * amp, 1.0f) * gl.pulso.weight(1);
    const float sparkP = std::min(spark * amp, 1.0f) * gl.pulso.weight(2);
    const uint32_t tick = uint32_t(std::fmod(twinkle, 100000.0) * 12.0);
    // Golpes: el dibujo da un salto; Graves: respira con los graves.
    float side = std::min(f.width, f.height) * 1.0f * (1.0f + 0.1f * kickP + 0.12f * bassP);
    float px = side / 400.0f;
    Vec2 center{f.width * 0.5f, f.height * 0.5f};
    // Graves: las fichas crecen con los graves.
    const float grow = 1.0f + 0.12f * kickP + 0.15f * bassP;
    const float L = 0.024f * grow, T = 0.006f * grow, W = 0.02f * grow;
    const int buckets = 12, levels = 5;
    std::array<Path, buckets * levels> fallen;
    std::array<Path, buckets> standing;
    // Halo de las fichas recién caídas (sólo con Estela de luz).
    const int haloLevels = 3;
    std::array<std::vector<Vec2>, buckets * haloLevels> halos;
    // La ficha que está cayendo en cada frente lleva la luz: su color y lugar.
    std::vector<std::pair<Vec2, int>> heads;
    Path shadow;
    // Agudos: fichas sueltas que destellan.
    Path glint;
    // Recorrido: mientras uno se funde en otro, cada ficha sigue uno de los dos.
    const float wDirect = gl.recorrido.weight(0), wReverse = gl.recorrido.weight(1);
    const float estela = std::clamp(gl.estela, 0.0f, 1.0f);
    for (const auto& d : dominoes) {
      const Chain& ch = chains[size_t(d.chain)];
      const int way = d.mix < wDirect ? 0 : (d.mix < wDirect + wReverse ? 1 : 2);
      const float delay = way == 1 ? maxDelay - ch.delay : ch.delay;
      const int back = ch.count - 1 - d.index;
      // Puesto de la ficha en su ola y hacia dónde cae (la ola la empuja).
      const bool forward = way == 0 || (way == 2 && d.index <= back);
      const float pos = float(forward ? d.index : back), dir = forward ? 1.0f : -1.0f;
      float front = float((g - double(delay)) * double(kSpeed));
      float tilt = std::clamp((front - pos) / 2.5f, 0.0f, 1.0f);
      float s = std::sin(tilt * 1.5707963f * 0.92f);
      float len = T + (L - T) * s;
      float bx = d.x - dir * d.dx * T * 0.5f, by = d.y - dir * d.dy * T * 0.5f;
      float ex = bx + dir * d.dx * len, ey = by + dir * d.dy * len;
      float nx = -d.dy * W * 0.5f, ny = d.dx * W * 0.5f;
      auto P = [&](float x, float y) { return Vec2{center.x + x * side, center.y + y * side}; };
      Vec2 p0 = P(bx + nx, by + ny), p1 = P(ex + nx, ey + ny), p2 = P(ex - nx, ey - ny), p3 = P(bx - nx, by - ny);
      int b = std::min(buckets - 1, int(d.hue * float(buckets)));
      // Estela de luz: cuanto más lejos quedó la ola, más se apaga la ficha;
      // las recién caídas brillan con un halo de su color.
      float age = std::clamp((front - pos - 3.0f) / 30.0f, 0.0f, 1.0f);
      int level = std::clamp(int(std::lround(age * float(levels - 1))), 0, levels - 1);
      Path& dst = tilt > 0.5f ? fallen[size_t(b * levels + level)] : standing[size_t(b)];
      if (estela > 0.001f && tilt > 0.5f && level < haloLevels)
        halos[size_t(b * haloLevels + level)].push_back(P((bx + ex) * 0.5f, (by + ey) * 0.5f));
      if ((estela > 0.001f || kickP > 0.002f) && tilt > 0.4f && tilt <= 0.8f && heads.size() < 64) heads.push_back({P(d.x, d.y), b});
      dst.moveTo(p0.x, p0.y).lineTo(p1.x, p1.y).lineTo(p2.x, p2.y).lineTo(p3.x, p3.y).close();
      if (sparkP > 0.002f &&
          hashU(uint32_t(d.chain) * 2246822519u + uint32_t(d.index) * 2654435761u + tick * 40503u) < 0.3f * sparkP)
        glint.moveTo(p0.x, p0.y).lineTo(p1.x, p1.y).lineTo(p2.x, p2.y).lineTo(p3.x, p3.y).close();
      if (m.sombra) {
        float o = (1.0f + 2.5f * (1.0f - s)) * px;
        shadow.moveTo(p0.x + o, p0.y + o * 1.4f).lineTo(p1.x + o, p1.y + o * 1.4f).lineTo(p2.x + o, p2.y + o * 1.4f).lineTo(p3.x + o, p3.y + o * 1.4f).close();
      }
    }
    if (m.sombra) {
      Paint sp;
      sp.color = Color{0, 0, 0, 0.45f};
      c.path(shadow, sp);
    }
    // Resplandor local sobre el dibujo: Golpes lo enciende y Graves lo hace latir.
    const float aura = std::clamp((0.3f * kickP + 0.2f * bassP) * f.glow, 0.0f, 0.6f);
    if (aura > 0.002f) {
      Paint ap = Paint::radial(center, side * 0.55f, {f.colors[2].opacity(aura), f.colors[1].opacity(aura * 0.4f), f.colors[1].opacity(0.0f)},
                               {0.0f, 0.6f, 1.0f});
      ap.blend = Blend::plus;
      c.circle(center, side * 0.55f, ap);
    }
    // El arcoíris empieza en el tono del primer acento de la paleta.
    const Color& accent = f.colors[1];
    float hi = std::max(accent.r, std::max(accent.g, accent.b)), lo = std::min(accent.r, std::min(accent.g, accent.b));
    float spread = hi - lo, baseHue = 0.0f;
    if (spread > 1e-4f) {
      baseHue = hi == accent.r ? (accent.g - accent.b) / spread
                               : (hi == accent.g ? 2.0f + (accent.b - accent.r) / spread : 4.0f + (accent.r - accent.g) / spread);
      baseHue /= 6.0f;
    }
    std::array<Color, buckets> hues;
    for (int b = 0; b < buckets; b++) {
      float h = baseHue + (float(b) + 0.5f) / float(buckets) * 0.85f;
      h -= std::floor(h);
      hues[size_t(b)] = Color{std::clamp(std::fabs(h * 6.0f - 3.0f) - 1.0f, 0.0f, 1.0f), std::clamp(2.0f - std::fabs(h * 6.0f - 2.0f), 0.0f, 1.0f),
                              std::clamp(2.0f - std::fabs(h * 6.0f - 4.0f), 0.0f, 1.0f), 1.0f};
    }
    if (estela > 0.001f) {
      const float shine = estela * (0.5f + 0.5f * std::clamp(f.glow, 0.0f, 2.0f));
      // Cada frente lleva una luz que alumbra el suelo a su alrededor.
      for (const auto& [spot, b] : heads) {
        Paint pool = Paint::radial(spot, side * 0.17f,
                                   {hues[size_t(b)].opacity(std::clamp(0.2f * shine, 0.0f, 1.0f)), hues[size_t(b)].opacity(0.0f)});
        pool.blend = Blend::plus;
        c.circle(spot, side * 0.17f, pool);
      }
      // Dos discos por ficha (ancho y tenue, estrecho y más vivo): un halo suave.
      for (int b = 0; b < buckets; b++) {
        for (int level = 0; level < haloLevels; level++) {
          const auto& spots = halos[size_t(b * haloLevels + level)];
          if (spots.empty()) continue;
          float fresh = 1.0f - float(level) / float(haloLevels);
          Paint hp;
          hp.blend = Blend::plus;
          hp.color = hues[size_t(b)].opacity(std::clamp(0.10f * shine * fresh, 0.0f, 1.0f));
          c.points(spots, 20.0f * px, hp);
          hp.color = hues[size_t(b)].opacity(std::clamp(0.16f * shine * fresh, 0.0f, 1.0f));
          c.points(spots, 10.0f * px, hp);
        }
      }
    }
    // Golpes: la cabeza de cada ola se enciende con un charco de luz.
    if (kickP > 0.002f && !heads.empty()) {
      const float share = std::min(1.0f, 4.0f / float(heads.size()));
      for (const auto& [spot, b] : heads) {
        Paint pool = Paint::radial(spot, side * 0.2f,
                                   {hues[size_t(b)].opacity(std::clamp(0.7f * kickP * share, 0.0f, 1.0f)), hues[size_t(b)].opacity(0.0f)});
        pool.blend = Blend::plus;
        c.circle(spot, side * 0.2f, pool);
      }
    }
    for (int b = 0; b < buckets; b++) {
      const Color& col = hues[size_t(b)];
      // Golpes y Graves avivan la cadena caída.
      float lit = (0.85f + 0.25f * bass + 0.2f * kick) * amp * (1.0f + 0.7f * kickP + 0.6f * bassP + 0.3f * sparkP);
      for (int level = 0; level < levels; level++) {
        const Path& path = fallen[size_t(b * levels + level)];
        if (path.data().empty()) continue;
        float dim = lit * (1.0f - 0.78f * estela * float(level) / float(levels - 1));
        Paint fp;
        fp.color = Color{std::clamp(col.r * dim, 0.0f, 1.0f), std::clamp(col.g * dim, 0.0f, 1.0f), std::clamp(col.b * dim, 0.0f, 1.0f), 1.0f};
        c.path(path, fp);
      }
      // Con Estela de luz la sala se oscurece: las fichas en pie se apagan un poco.
      const float shade = (1.0f - 0.45f * estela) * (1.0f + 0.5f * kickP + 0.3f * bassP);
      Paint sp;
      sp.color = Color{std::clamp((col.r * 0.6f + 0.35f) * shade, 0.0f, 1.0f), std::clamp((col.g * 0.6f + 0.35f) * shade, 0.0f, 1.0f),
                       std::clamp((col.b * 0.6f + 0.35f) * shade, 0.0f, 1.0f), 1.0f};
      c.path(standing[size_t(b)], sp);
    }
    if (sparkP > 0.002f && !glint.data().empty()) {
      const Color& c3 = f.colors[3];
      Paint gp;
      gp.blend = Blend::plus;
      gp.color = Color{std::min(1.0f, c3.r * 0.5f + 0.5f), std::min(1.0f, c3.g * 0.5f + 0.5f), std::min(1.0f, c3.b * 0.5f + 0.5f),
                       std::clamp(0.95f * sparkP, 0.0f, 0.95f)};
      c.path(glint, gp);
    }
    (void)aspect;
  }
};

class Visual final : public Scene {
  static constexpr int kLimit = 140000;
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  // Relojes en doble precisión: la escena sin música es idéntica a 30 y 60 FPS.
  double zoom = 0, spin = 0;
  std::vector<int> primes;

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    zoom = rng.unit() * 6.28;
    spin = 0;
    // Criba de Eratóstenes, una sola vez.
    std::vector<uint8_t> composite(kLimit + 1, 0);
    primes.clear();
    primes.reserve(13000);
    for (int i = 2; i <= kLimit; i++) {
      if (composite[size_t(i)]) continue;
      primes.push_back(i);
      for (long long j = (long long)i * i; j <= kLimit; j += i) composite[size_t(j)] = 1;
    }
  }

  void update(const Frame& f) override {
    auto m = modifiers(f);
    float dt = float(f.delta);
    const Music& mu = f.music;
    bass = follow(bass, mu.bass, 22.0f, 4.5f, dt);
    body = follow(body, mu.body, 12.0f, 3.0f, dt);
    spark = follow(spark, mu.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, mu.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, mu.active ? std::pow(std::clamp(mu.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : mu.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : mu.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : mu.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((mu.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, mu.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    zoom += f.delta * f.speed * m.velocidad * (0.09 + 0.12 * drive);
    spin += f.delta * f.speed * (0.04 + 0.06 * drive);
  }

  void render(const Frame& f, Canvas& c) const override {
    auto m = modifiers(f);
    auto gl = glide(f);
    float amp = f.intensity;
    const Color& bg = f.colors[0];
    c.rect({0, 0, f.width, f.height}, Paint::radial({f.width * 0.5f, f.height * 0.5f}, std::max(f.width, f.height) * 0.7f,
                                                   {Color{std::min(1.0f, bg.r + 0.05f), std::min(1.0f, bg.g + 0.02f), std::min(1.0f, bg.b + 0.06f), 1.0f},
                                                    Color{bg.r, bg.g, bg.b, 1.0f}}));
    // Zoom en escala logarítmica: de ver 300 números a ver casi 90 000.
    float w = 0.5f - 0.5f * float(std::cos(zoom));
    float pMax = std::exp(std::log(300.0f) + (std::log(float(kLimit) * 0.62f) - std::log(300.0f)) * w);
    float R = 0.5f * std::sqrt(f.width * f.width + f.height * f.height);
    float s = R / pMax;
    float rot = float(std::fmod(spin, 6.2831853));
    float side = std::min(f.width, f.height);
    float px = side / 400.0f;
    float dot = std::clamp(0.5f * s + 1.6f * px, 1.2f * px, 8.0f * px) * m.tamano * (1.0f + 0.35f * kick * amp);
    Vec2 center{f.width * 0.5f, f.height * 0.5f};
    const int buckets = 11;
    std::array<std::vector<Vec2>, buckets> groups;
    for (auto& g : groups) g.reserve(primes.size() / 8);
    // Estela: cada primo deja una cola detrás de su giro, en tres tramos que
    // se apagan y adelgazan. Más puntos por cola cuando hay pocos primos; el
    // total se queda en unos 30 000. Se pintan encima sin sumar luz, así las
    // colas que se cruzan nunca queman a blanco.
    const float trail = gl.estela;
    const size_t shown = size_t(std::upper_bound(primes.begin(), primes.end(), int(pMax)) - primes.begin());
    const int tailPoints = trail > 0.005f ? std::clamp(int(30000 / std::max<size_t>(shown, 1)), 3, 28) : 0;
    // Con miles de primos las colas se acortan para que sigan viéndose los
    // rayos y quede oscuridad entre ellos.
    const float crowd = std::clamp(std::sqrt(1200.0f / float(std::max<size_t>(shown, 1))), 0.4f, 1.0f);
    const float tailLength = trail * dot * crowd * (26.0f + 6.0f * kick * amp);
    std::array<std::array<std::vector<Vec2>, 3>, buckets> tails;
    // El color sigue los brazos: de cerca por resto entre 6, luego entre 44.
    int mod = pMax < 2500.0f ? 6 : 44;
    for (int p : primes) {
      if (float(p) > pMax) break;
      double a = std::fmod(double(p), 6.283185307179586) + double(rot);
      float r = float(p) * s;
      Vec2 q{center.x + r * float(std::cos(a)), center.y + r * float(std::sin(a))};
      int b = std::min(int(float(p % mod) / float(mod) * float(buckets)), buckets - 1);
      groups[size_t(b)].push_back(q);
      if (tailPoints > 0) {
        // Paso angular de la cola: tramos de un punto, sin dar la vuelta cerca del centro.
        double step = double(std::min(tailLength / float(tailPoints) / std::max(r, dot), 1.2f / float(tailPoints)));
        for (int j = 1; j <= tailPoints; j++) {
          float u = float(j) / float(tailPoints);
          double aj = a - step * double(j);
          float rj = r * (1.0f - 0.12f * trail * u);
          tails[size_t(b)][size_t(std::min(2, (j - 1) * 3 / tailPoints))].push_back(
              {center.x + rj * float(std::cos(aj)), center.y + rj * float(std::sin(aj))});
        }
      }
    }
    if (m.noprimos && pMax < 4000.0f) {
      std::vector<Vec2> rest;
      rest.reserve(size_t(pMax));
      size_t k = 0;
      for (int n = 1; float(n) <= pMax; n++) {
        while (k < primes.size() && primes[k] < n) k++;
        if (k < primes.size() && primes[k] == n) continue;
        double a = std::fmod(double(n), 6.283185307179586) + double(rot);
        float r = float(n) * s;
        rest.push_back({center.x + r * float(std::cos(a)), center.y + r * float(std::sin(a))});
      }
      Paint dim;
      dim.color = Color{0.45f, 0.42f, 0.5f, 0.35f};
      c.points(rest, dot * 0.55f, dim);
    }
    for (int b = 0; b < buckets; b++) {
      // Cada brazo con un acento de la paleta.
      const Color& col = f.colors[size_t(1 + b % 3)];
      float lit = (0.8f + 0.35f * bass + 0.3f * kick) * amp;
      if (tailPoints > 0) {
        const std::array<float, 3> fadeTail = {0.8f, 0.55f, 0.28f}, thinTail = {1.0f, 0.85f, 0.65f};
        for (int k = 0; k < 3; k++) {
          Paint tail;
          tail.color = Color{std::min(1.0f, col.r * lit), std::min(1.0f, col.g * lit), std::min(1.0f, col.b * lit),
                             std::clamp(fadeTail[size_t(k)] * std::min(1.0f, trail * 1.5f), 0.0f, 1.0f)};
          c.points(tails[size_t(b)][size_t(k)], dot * thinTail[size_t(k)], tail);
        }
      }
      Paint halo;
      halo.blend = Blend::plus;
      halo.color = col.opacity(std::clamp(0.16f * f.glow * amp, 0.0f, 1.0f));
      if (dot > 2.0f * px) c.points(groups[size_t(b)], dot * 2.4f, halo);
      Paint core;
      core.blend = Blend::plus;
      core.color = Color{std::min(1.0f, col.r * lit), std::min(1.0f, col.g * lit), std::min(1.0f, col.b * lit), 1.0f};
      c.points(groups[size_t(b)], dot, core);
    }
    if (flash > 0.01f) {
      Paint fl;
      fl.blend = Blend::plus;
      fl.color = f.colors[2].opacity(std::clamp(flash * 0.05f * amp, 0.0f, 1.0f));
      c.rect({0, 0, f.width, f.height}, fl);
    }
  }
};

class Visual final : public Scene {
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  // Relojes en doble precisión: la escena sin música es idéntica a 30 y 60 FPS.
  double travel = 0, clock = 0, swirl = 0;
  float boost = 0, laser = 0, fire = 0;

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    travel = rng.unit() * 10.0;
    clock = rng.unit() * 50.0;
    swirl = rng.unit() * 6.2831853;
    boost = laser = fire = 0;
  }

  void update(const Frame& f) override {
    float dt = float(f.delta);
    const Music& m = f.music;
    bass = follow(bass, m.bass, 22.0f, 4.5f, dt);
    body = follow(body, m.body, 12.0f, 3.0f, dt);
    spark = follow(spark, m.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, m.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, m.active ? std::pow(std::clamp(m.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : m.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : m.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : m.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((m.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, m.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    if (hit > kick + 0.2f) {
      boost = std::max(boost, hit);
      laser = std::max(laser, hit);
    }
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    boost *= std::exp(-dt * 3.0f);
    laser *= std::exp(-dt * 2.0f);
    // El mármol arde con la energía sostenida de la canción.
    fire = follow(fire, 0.15f + 0.85f * drive + 0.3f * bass, 2.0f, 0.6f, dt);
    travel += f.delta * f.speed * (0.3 + 0.5 * drive + 1.3 * boost);
    clock += f.delta * f.speed;
    swirl += f.delta * f.speed * (0.06 + 0.3 * spark + 0.1 * drive);
  }

  void render(const Frame& f, Canvas& c) const override {
    float amp = f.intensity;
    std::vector<float> u;
    u.reserve(24);
    u.insert(u.end(), {float(std::fmod(clock, 1000.0)), bass * amp, kick * amp, energy});
    u.insert(u.end(), {float(std::fmod(travel, 1000.0)), f.glow, spark * amp, flash * amp});
    u.insert(u.end(), {std::min(1.2f, fire * amp), (0.3f + laser) * amp, float(std::fmod(swirl, 6.2831853)), 0.0f});
    for (int i = 0; i < 4; i++) u.insert(u.end(), {f.colors[i].r, f.colors[i].g, f.colors[i].b});
    c.material("neon_star", {0, 0, f.width, f.height}, u);
  }
};

shaderSources.neon_star:
#version 460 core
#include <flutter/runtime_effect.glsl>
uniform vec2 uSize;
uniform vec4 uA;   // reloj, graves, golpe, energía
uniform vec4 uB;   // avance de las estrellas, glow, agudos, destello
uniform vec4 uF;   // fuego del mármol, fuerza de los láseres, giro del mármol
uniform vec3 uC0;
uniform vec3 uC1;
uniform vec3 uC2;
uniform vec3 uC3;
out vec4 fragColor;

const float PI = 3.14159265;

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash12(i), hash12(i + vec2(1.0, 0.0)), u.x),
             mix(hash12(i + vec2(0.0, 1.0)), hash12(i + vec2(1.0, 1.0)), u.x), u.y);
}

// Distancia con signo a una estrella de seis puntas de radio r (iq).
float sdStar6(vec2 p, float r) {
  const float an = PI / 6.0;
  const float en = PI / 3.0;
  vec2 acs = vec2(cos(an), sin(an));
  vec2 ecs = vec2(cos(en), sin(en));
  float bn = mod(atan(p.x, p.y), 2.0 * an) - an;
  p = length(p) * vec2(cos(bn), abs(sin(bn)));
  p -= r * acs;
  p += ecs * clamp(-dot(p, ecs), 0.0, r * acs.y / ecs.y);
  return length(p) * sign(p.x);
}

void main() {
  vec2 frag = FlutterFragCoord().xy;
  float scale = min(uSize.x, uSize.y);
  vec2 p = (frag - 0.5 * uSize) / scale;
  float r = length(p) + 1e-4;
  float a = atan(p.x, p.y);
  float t = uA.x;
  float kick = uA.z;

  // Pliegue en espejo de seis sectores para el mármol y los láseres.
  float sector = PI / 3.0;
  float fa = abs(mod(a, sector) - 0.5 * sector);
  vec2 k = vec2(cos(fa), sin(fa)) * r;

  // Mármol líquido rojo y naranja con remolinos.
  vec2 m = k * 3.0;
  float cs = cos(uF.z);
  float sn = sin(uF.z);
  m = vec2(cs * m.x - sn * m.y, sn * m.x + cs * m.y);
  float w1 = noise(m * 1.3 + vec2(t * 0.08, 0.0));
  float w2 = noise(m * 1.3 + vec2(5.2, -t * 0.07));
  vec2 mm = m + 2.2 * vec2(w1, w2);
  float veins = sin(mm.x * 5.0 + noise(mm * 1.7) * 6.0 + t * 0.4);
  float marble = smoothstep(-0.2, 1.0, veins);
  vec3 marbleCol = mix(uC3 * 0.55, mix(uC3, uC2, 0.6), marble) + vec3(1.0, 0.9, 0.5) * pow(marble, 8.0) * 0.6;
  // Oscuro cerca de las puntas (donde van los láseres) y fundido en el centro.
  float wedge = smoothstep(0.0, 0.25, fa);
  vec3 col = uC0 + mix(uC1 * 0.12 * marble, marbleCol, clamp(uF.x, 0.0, 1.0)) * wedge * smoothstep(0.05, 0.3, r) *
             (0.55 + 0.6 * uA.y);

  // Estrellas de neón dorado que salen del centro.
  for (int i = 0; i < 5; i++) {
    float ph = fract(uB.x * 0.32 + float(i) * 0.2);
    float s = 0.04 * exp(ph * 3.6);
    float sd = sdStar6(p, s);
    float d = abs(sd);
    float w = 0.003 + 0.012 * s;
    float fade = smoothstep(0.0, 0.1, ph) * smoothstep(1.0, 0.75, ph);
    vec3 gold = mix(uC2, vec3(1.0, 0.95, 0.75), exp(-d / (w * 0.3)));
    col += gold * (exp(-d / (w * 0.5)) + 0.45 * exp(-d / (w * 2.5))) * fade * uB.y;
    // Contorno interior azul, como en el doble trazo del neón.
    float d2 = abs(sd + 0.045 * s);
    col += uC1 * exp(-d2 / (w * 0.35)) * fade * 0.6;
  }

  // Láseres azules desde las puntas de la estrella.
  float beamD = sin(fa) * r;
  float width = 0.004 + 0.045 * r;
  float beam = (exp(-beamD / width) * 0.7 + exp(-beamD / (width * 0.3))) * smoothstep(0.05, 0.25, r);
  col += mix(uC1, vec3(0.65, 0.97, 1.0), exp(-beamD / (width * 0.35))) * beam * uF.y * 1.2;

  // Brillo central y destello.
  col += mix(uC2, vec3(1.0), 0.5) * (0.0015 + 0.004 * kick) / (r * r + 0.002);
  col += uC1 * uB.w * 0.06;
  col *= 1.0 - 0.3 * smoothstep(0.7, 1.5, length(p * vec2(0.9, 0.65)));
  float peak = max(col.r, max(col.g, col.b));
  if (peak > 0.85) {
    float e = (peak - 0.85) / 0.15;
    col *= (0.85 + 0.15 * e / (1.0 + e)) / peak;
  }
  col += (hash12(frag) - 0.5) / 255.0;
  fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

visuals.nativeSource:
class Visual final : public Scene {
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  // Relojes en doble precisión: la escena sin música es idéntica a 30 y 60 FPS.
  double travel = 0, clock = 0, swirl = 0;
  float boost = 0, laser = 0, fire = 0;

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    travel = rng.unit() * 10.0;
    clock = rng.unit() * 50.0;
    swirl = rng.unit() * 6.2831853;
    boost = laser = fire = 0;
  }

  void update(const Frame& f) override {
    float dt = float(f.delta);
    const Music& m = f.music;
    bass = follow(bass, m.bass, 22.0f, 4.5f, dt);
    body = follow(body, m.body, 12.0f, 3.0f, dt);
    spark = follow(spark, m.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, m.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, m.active ? std::pow(std::clamp(m.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : m.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : m.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : m.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((m.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, m.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    if (hit > kick + 0.2f) {
      boost = std::max(boost, hit);
      laser = std::max(laser, hit);
    }
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    boost *= std::exp(-dt * 3.0f);
    laser *= std::exp(-dt * 2.0f);
    // El mármol arde con la energía sostenida de la canción.
    fire = follow(fire, 0.15f + 0.85f * drive + 0.3f * bass, 2.0f, 0.6f, dt);
    travel += f.delta * f.speed * (0.3 + 0.5 * drive + 1.3 * boost);
    clock += f.delta * f.speed;
    swirl += f.delta * f.speed * (0.06 + 0.3 * spark + 0.1 * drive);
  }

  void render(const Frame& f, Canvas& c) const override {
    float amp = f.intensity;
    std::vector<float> u;
    u.reserve(24);
    u.insert(u.end(), {float(std::fmod(clock, 1000.0)), bass * amp, kick * amp, energy});
    u.insert(u.end(), {float(std::fmod(travel, 1000.0)), f.glow, spark * amp, flash * amp});
    u.insert(u.end(), {std::min(1.2f, fire * amp), (0.3f + laser) * amp, float(std::fmod(swirl, 6.2831853)), 0.0f});
    for (int i = 0; i < 4; i++) u.insert(u.end(), {f.colors[i].r, f.colors[i].g, f.colors[i].b});
    c.material("neon_star", {0, 0, f.width, f.height}, u);
  }
};

shaderSources.neon_star:
#version 460 core
#include <flutter/runtime_effect.glsl>
uniform vec2 uSize;
uniform vec4 uA;   // reloj, graves, golpe, energía
uniform vec4 uB;   // avance de las estrellas, glow, agudos, destello
uniform vec4 uF;   // fuego del mármol, fuerza de los láseres, giro del mármol
uniform vec3 uC0;
uniform vec3 uC1;
uniform vec3 uC2;
uniform vec3 uC3;
out vec4 fragColor;

const float PI = 3.14159265;

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash12(i), hash12(i + vec2(1.0, 0.0)), u.x),
             mix(hash12(i + vec2(0.0, 1.0)), hash12(i + vec2(1.0, 1.0)), u.x), u.y);
}

// Distancia con signo a una estrella de seis puntas de radio r (iq).
float sdStar6(vec2 p, float r) {
  const float an = PI / 6.0;
  const float en = PI / 3.0;
  vec2 acs = vec2(cos(an), sin(an));
  vec2 ecs = vec2(cos(en), sin(en));
  float bn = mod(atan(p.x, p.y), 2.0 * an) - an;
  p = length(p) * vec2(cos(bn), abs(sin(bn)));
  p -= r * acs;
  p += ecs * clamp(-dot(p, ecs), 0.0, r * acs.y / ecs.y);
  return length(p) * sign(p.x);
}

void main() {
  vec2 frag = FlutterFragCoord().xy;
  float scale = min(uSize.x, uSize.y);
  vec2 p = (frag - 0.5 * uSize) / scale;
  float r = length(p) + 1e-4;
  float a = atan(p.x, p.y);
  float t = uA.x;
  float kick = uA.z;

  // Pliegue en espejo de seis sectores para el mármol y los láseres.
  float sector = PI / 3.0;
  float fa = abs(mod(a, sector) - 0.5 * sector);
  vec2 k = vec2(cos(fa), sin(fa)) * r;

  // Mármol líquido rojo y naranja con remolinos.
  vec2 m = k * 3.0;
  float cs = cos(uF.z);
  float sn = sin(uF.z);
  m = vec2(cs * m.x - sn * m.y, sn * m.x + cs * m.y);
  float w1 = noise(m * 1.3 + vec2(t * 0.08, 0.0));
  float w2 = noise(m * 1.3 + vec2(5.2, -t * 0.07));
  vec2 mm = m + 2.2 * vec2(w1, w2);
  float veins = sin(mm.x * 5.0 + noise(mm * 1.7) * 6.0 + t * 0.4);
  float marble = smoothstep(-0.2, 1.0, veins);
  vec3 marbleCol = mix(uC3 * 0.55, mix(uC3, uC2, 0.6), marble) + vec3(1.0, 0.9, 0.5) * pow(marble, 8.0) * 0.6;
  // Oscuro cerca de las puntas (donde van los láseres) y fundido en el centro.
  float wedge = smoothstep(0.0, 0.25, fa);
  // En el overlay sólo quedan las vetas brillantes del mármol.
  vec3 col = uC0 + mix(uC1 * 0.12 * marble, marbleCol, clamp(uF.x, 0.0, 1.0)) * wedge * smoothstep(0.05, 0.3, r) *
             (0.55 + 0.6 * uA.y) * smoothstep(0.55, 0.95, marble);

  // Estrellas de neón dorado que salen del centro.
  for (int i = 0; i < 5; i++) {
    float ph = fract(uB.x * 0.32 + float(i) * 0.2);
    float s = 0.04 * exp(ph * 3.6);
    float sd = sdStar6(p, s);
    float d = abs(sd);
    float w = 0.003 + 0.012 * s;
    float fade = smoothstep(0.0, 0.1, ph) * smoothstep(1.0, 0.75, ph);
    vec3 gold = mix(uC2, vec3(1.0, 0.95, 0.75), exp(-d / (w * 0.3)));
    col += gold * (exp(-d / (w * 0.5)) + 0.45 * exp(-d / (w * 2.5))) * fade * uB.y;
    // Contorno interior azul, como en el doble trazo del neón.
    float d2 = abs(sd + 0.045 * s);
    col += uC1 * exp(-d2 / (w * 0.35)) * fade * 0.6;
  }

  // Láseres azules desde las puntas de la estrella.
  float beamD = sin(fa) * r;
  float width = 0.004 + 0.045 * r;
  float beam = (exp(-beamD / width) * 0.7 + exp(-beamD / (width * 0.3))) * smoothstep(0.05, 0.25, r);
  col += mix(uC1, vec3(0.65, 0.97, 1.0), exp(-beamD / (width * 0.35))) * beam * uF.y * 1.2;

  // Brillo central y destello.
  col += mix(uC2, vec3(1.0), 0.5) * (0.0015 + 0.004 * kick) / (r * r + 0.002);
  col *= 1.0 - 0.3 * smoothstep(0.7, 1.5, length(p * vec2(0.9, 0.65)));
  float peak = max(col.r, max(col.g, col.b));
  if (peak > 0.85) {
    float e = (peak - 0.85) / 0.15;
    col *= (0.85 + 0.15 * e / (1.0 + e)) / peak;
  }
  // Fondo transparente: color premultiplicado y opacidad según el brillo; la
  // luz muy tenue se vuelve transparente del todo para no dejar velo.
  col = clamp(col, 0.0, 1.0);
  float veilPeak = max(col.r, max(col.g, col.b));
  float clearCut = smoothstep(0.04, 0.12, veilPeak);
  col *= clearCut;
  float alpha = clamp(veilPeak * 1.25, 0.0, 1.0) * clearCut;
  fragColor = vec4(col, alpha);
}

visuals.nativeSource:
class Visual final : public Scene {
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  std::array<float, 8> bands{};
  float phase = 0, spin = 0, wobble = 0;

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    bands.fill(0);
    phase = rng.unit() * 10.0f;
    spin = rng.unit();
    wobble = 0;
  }

  void update(const Frame& f) override {
    float dt = float(f.delta);
    const Music& m = f.music;
    bass = follow(bass, m.bass, 22.0f, 4.5f, dt);
    body = follow(body, m.body, 14.0f, 3.5f, dt);
    spark = follow(spark, m.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, m.energy, 8.0f, 2.0f, dt);
    drive = follow(drive, m.active ? std::pow(std::clamp(m.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : m.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : m.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : m.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((m.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, m.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    kick = std::max(kick * std::exp(-dt * 6.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));

    static const int edges[9] = {0, 3, 6, 9, 13, 17, 21, 26, 31};
    for (int b = 0; b < 8; b++) {
      float v = 0;
      for (int i = edges[b]; i < edges[b + 1]; i++) v = std::max(v, m.smoothSpectrum[i]);
      bands[b] = follow(bands[b], v, 18.0f, 4.0f, dt);
    }

    phase += dt * f.speed * (0.3f + 1.2f * drive + 1.0f * kick);
    spin += dt * f.speed * (0.008f + 0.035f * drive + 0.06f * kick);
    wobble += dt * f.speed * (0.6f + 2.0f * body);
  }

  void render(const Frame& f, Canvas& c) const override {
    float amp = f.intensity;
    float spikes = std::round(18.0f + 8.0f * f.detail);
    std::vector<float> u;
    u.reserve(40);
    u.insert(u.end(), {phase, spin, 0.19f + 0.015f * bass * amp, spikes});
    u.insert(u.end(), {0.05f, 0.14f * bass * amp, 0.14f * amp, kick * amp});
    u.insert(u.end(), {wobble, body, drive, 0.0f});
    u.insert(u.end(), {bands[0], bands[1], bands[2], bands[3]});
    u.insert(u.end(), {bands[4], bands[5], bands[6], bands[7]});
    u.insert(u.end(), {spark, flash, f.glow, energy});
    for (int i = 0; i < 4; i++) u.insert(u.end(), {f.colors[i].r, f.colors[i].g, f.colors[i].b});
    c.material("ferro", {0, 0, f.width, f.height}, u);
  }
};

shaderSources.ferro:
#version 460 core
#include <flutter/runtime_effect.glsl>
uniform vec2 uSize;
uniform vec4 uA;      // tiempo, giro, radio de la cúpula, número de púas
uniform vec4 uB;      // púa base, púa por graves, púa por banda, golpe
uniform vec4 uW;      // ondulación, medios, impulso, libre
uniform vec4 uBands0;
uniform vec4 uBands1;
uniform vec4 uL;      // agudos, destello, glow, energía
uniform vec3 uC0;
uniform vec3 uC1;
uniform vec3 uC2;
uniform vec3 uC3;
out vec4 fragColor;

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

float pick(float i) {
  if (i < 0.5) return uBands0.x;
  if (i < 1.5) return uBands0.y;
  if (i < 2.5) return uBands0.z;
  if (i < 3.5) return uBands0.w;
  if (i < 4.5) return uBands1.x;
  if (i < 5.5) return uBands1.y;
  if (i < 6.5) return uBands1.z;
  return uBands1.w;
}

// Banda por dirección: graves arriba, agudos abajo, simétrico.
float bandAt(float turns) {
  float m = abs(fract(turns + 0.25) * 2.0 - 1.0) * 7.0;
  float i = floor(m);
  return mix(pick(i), pick(min(i + 1.0, 7.0)), smoothstep(0.0, 1.0, m - i));
}

float spikeLength(float turns) {
  float wave = 0.5 + 0.5 * sin(turns * 6.2831853 * 3.0 - uA.x * 1.7);
  float wave2 = 0.5 + 0.5 * sin(turns * 6.2831853 * 5.0 + uA.x * 1.1);
  return uB.x * (0.6 + 0.8 * wave * wave2) + uB.y * (0.7 + 0.3 * wave) +
         bandAt(turns) * uB.z + uB.w * (0.07 + 0.05 * wave2);
}

// Cono de sección redonda que nace del borde de la cúpula y se afila.
float spike(float r, float a, float offset, float scale) {
  float n = uA.w;
  float aa = a + offset;
  float k = floor(aa);
  float f = aa - k - 0.5;
  float len = spikeLength((k + 0.5 - offset) / n - uA.y) * scale;
  float base = uA.z * 0.80;
  float t = (r - base) / (len + uA.z * 0.22);
  float halfW = 0.5 * (1.0 - t);
  float d = abs(f) / max(halfW, 0.0001);
  float inside = step(0.0, t) * step(t, 1.0) * step(d, 1.0);
  return inside * uA.z * 0.66 * pow(max(1.0 - t, 0.0), 1.15) *
         sqrt(max(1.0 - d * d, 0.0));
}

float height(vec2 p) {
  float r = length(p);
  float a = (atan(p.y, p.x) / 6.2831853 + uA.y) * uA.w;
  float breathe = 1.0 + 0.02 * sin(uW.x + r * 30.0) + 0.05 * uB.w;
  float dr = r / (uA.z * breathe);
  float dome = uA.z * sqrt(max(1.0 - dr * dr, 0.0));
  float s = max(spike(r, a, 0.0, 1.0), spike(r, a, 0.5, 0.55));
  // Unión suave entre cúpula y púas.
  if (dome <= 0.0 || s <= 0.0) return max(dome, s);
  float k = uA.z * 0.08;
  float hk = clamp(0.5 + 0.5 * (s - dome) / k, 0.0, 1.0);
  return mix(dome, s, hk) + k * hk * (1.0 - hk);
}

vec3 environment(vec3 r) {
  float kick = uB.w;
  vec3 col = uC0 * 0.25;
  float up = step(0.0, r.z);
  // Softbox redondeado y difuso arriba a la izquierda, más brillante arriba.
  vec2 q = r.xy - vec2(-0.30, 0.36);
  vec2 bq = abs(q) - vec2(0.17, 0.10);
  float box = length(max(bq, 0.0)) + min(max(bq.x, bq.y), 0.0) - 0.06;
  float soft = (1.0 - smoothstep(-0.06, 0.10, box)) * (0.65 + 0.35 * smoothstep(-0.2, 0.2, q.y));
  col += vec3(1.0, 0.97, 0.94) * soft * (1.3 + 3.0 * uL.y + 1.0 * kick) * up;
  // Luz de relleno cálida, pequeña y muy suave abajo a la derecha.
  float fill = exp(-dot(r.xy - vec2(0.45, -0.35), r.xy - vec2(0.45, -0.35)) * 18.0);
  col += uC3 * fill * 0.35 * up;
  // Luces de color en el horizonte: sólo las ven los flancos rasantes.
  float az = atan(r.y, r.x);
  float horizon = pow(1.0 - abs(r.z), 5.0);
  vec3 rim = mix(uC1, uC2, smoothstep(-0.6, 0.6, sin(az + uA.x * 0.25)));
  col += rim * horizon * (1.4 + 3.5 * kick + 1.2 * uL.w) * uL.z;
  return col;
}

void main() {
  vec2 frag = FlutterFragCoord().xy;
  float scale = min(uSize.x, uSize.y);
  vec2 p = (frag - 0.5 * uSize) / scale;
  p.y = -p.y;
  float r0 = length(p);
  float kick = uB.w;

  // Fondo: estudio oscuro con halo de color que late con el golpe.
  float halo = exp(-r0 * r0 * 7.0);
  vec3 bg = uC0 + mix(uC1, uC2, 0.5 + 0.5 * sin(atan(p.y, p.x) + uA.x * 0.3)) *
            halo * (0.10 + 0.45 * kick + 0.15 * uL.w) * uL.z;
  float rings = 0.5 + 0.5 * sin(r0 * 60.0 - uA.x * 4.0);
  bg += mix(uC2, uC1, 0.5) * halo * rings * (0.015 + 0.08 * kick);
  vec3 col = bg;

  float h0 = height(p);
  if (h0 > 0.0) {
    float e = 1.25 / scale;
    float hx = height(p + vec2(e, 0.0));
    float hy = height(p + vec2(0.0, e));
    vec3 n = normalize(vec3(-(hx - h0) / e, -(hy - h0) / e, 1.0));
    vec3 v = vec3(0.0, 0.0, 1.0);
    vec3 r = reflect(-v, n);
    float fres = 0.05 + 0.95 * pow(1.0 - max(n.z, 0.0), 5.0);
    vec3 surf = environment(r) * (0.25 + 0.75 * fres);
    // Brillos con los agudos en las puntas de las púas.
    float tip = smoothstep(0.03, 0.0, h0) * step(uA.z * 1.05, r0);
    float tw = hash12(floor(vec2(atan(p.y, p.x) * uA.w * 0.5, uA.x * 8.0)));
    surf += uC3 * tip * smoothstep(0.4, 1.0, tw) * uL.x * 3.0;
    // Contorno suave para evitar dientes de sierra en el borde.
    float edge = smoothstep(0.0, 0.004, h0);
    col = mix(bg * 0.4, surf, edge);
  }

  col *= 1.0 - 0.4 * smoothstep(0.35, 1.2, length(p * vec2(0.9, 0.65)));
  col = clamp((col * (2.51 * col + 0.03)) / (col * (2.43 * col + 0.59) + 0.14), 0.0, 1.0);
  col = pow(col, vec3(0.4545));
  col += (hash12(frag) - 0.5) / 255.0;
  fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

visuals.shaderSource:
vec2 rotate2D(vec2 p, float a) {
  float c = cos(a);
  float s = sin(a);
  return vec2(p.x * c - p.y * s, p.x * s + p.y * c);
}

float getAngle(vec2 p) {
  float r = length(p);
  if (r < 0.00001) { return 0.0; }
  float a = asin(clamp(p.y / r, -1.0, 1.0));
  if (p.x < 0.0) {
    a = 3.14159265 - a;
  }
  if (a < 0.0) {
    a = a + 6.2831853;
  }
  return a;
}

vec4 paintVisual(vec2 uv, CreatorFrame f) {
  float aspect = max(f.size.x, 1.0) / max(f.size.y, 1.0);
  vec2 p = (uv - 0.5) * vec2(aspect, 1.0) * 2.2;

  float r = length(p);
  float a = getAngle(p);

  float beat = clamp(f.pulse, 0.0, 1.0);
  float bass = clamp(f.bass, 0.0, 1.0);
  float spark = clamp(f.spark, 0.0, 1.0);
  float flow = clamp(f.flow, 0.0, 1.0);
  float t = f.time * 0.42 * f.speed;

  // Background deep sacred cosmic aura
  vec3 bgCol = mix(vec3(0.02, 0.008, 0.06), vec3(0.06, 0.015, 0.14), r * 0.8);
  bgCol = bgCol + vec3(0.1, 0.02, 0.18) * sin(r * 4.0 - t * 1.5) * 0.3;

  vec3 col = bgCol;

  // Fibonacci Petal Ring 1 (Inner 5 petals)
  float a1 = a + t * 0.6;
  float pet1 = cos(5.0 * a1);
  float r1 = 0.18 + 0.08 * pet1 + bass * 0.06;
  float d1 = abs(r - r1);
  float edge1 = 0.012 / (d1 + 0.012);
  vec3 col1 = mix(vec3(1.0, 0.85, 0.2), vec3(1.0, 0.25, 0.6), 0.5 + 0.5 * pet1);
  col = col + col1 * edge1 * 0.7;

  // Fibonacci Petal Ring 2 (Middle 8 petals, counter-rotating)
  float a2 = a - t * 0.4;
  float pet2 = cos(8.0 * a2);
  float r2 = 0.35 + 0.12 * pet2 + beat * 0.08;
  float d2 = abs(r - r2);
  float edge2 = 0.015 / (d2 + 0.018);
  vec3 col2 = mix(vec3(0.2, 0.85, 1.0), vec3(0.9, 0.1, 0.7), 0.5 + 0.5 * pet2);
  col = col + col2 * edge2 * 0.65;

  // Fibonacci Petal Ring 3 (Outer 13 petals)
  float a3 = a + t * 0.25;
  float pet3 = cos(13.0 * a3);
  float r3 = 0.58 + 0.15 * pet3 + bass * 0.1;
  float d3 = abs(r - r3);
  float edge3 = 0.018 / (d3 + 0.022);
  vec3 col3 = mix(vec3(0.95, 0.3, 0.8), vec3(1.0, 0.7, 0.2), 0.5 + 0.5 * pet3);
  col = col + col3 * edge3 * 0.6;

  // Fibonacci Petal Ring 4 (Ethereal 21 filaments)
  float a4 = a - t * 0.15;
  float pet4 = cos(21.0 * a4);
  float r4 = 0.82 + 0.14 * pet4 + beat * 0.06;
  float d4 = abs(r - r4);
  float edge4 = 0.012 / (d4 + 0.025);
  vec3 col4 = mix(vec3(0.4, 0.3, 1.0), vec3(0.2, 0.95, 0.8), 0.5 + 0.5 * pet4);
  col = col + col4 * edge4 * (0.4 + 0.3 * spark);

  // Sacred golden spiral rays
  float spiral1 = sin(log(r + 0.02) * 5.0 - a * 3.0 + t * 1.2);
  float spiral2 = sin(log(r + 0.02) * 5.0 + a * 3.0 - t * 1.2);
  float spiralGrid = smoothstep(0.85, 0.98, spiral1) + smoothstep(0.85, 0.98, spiral2);
  col = col + vec3(1.0, 0.8, 0.3) * spiralGrid * 0.35 * exp(-r * 1.8);

  // Radiant Golden Core / Lotus Stamen
  float coreDist = r;
  float coreGlow = 0.04 / (coreDist * coreDist * 6.0 + 0.04);
  float corePulse = 1.0 + 0.4 * sin(t * 4.0) + bass * 0.8;
  vec3 coreColor = mix(vec3(1.0, 0.95, 0.5), vec3(1.0, 0.4, 0.1), clamp(r * 5.0, 0.0, 1.0));
  col = col + coreColor * coreGlow * corePulse * 1.2;

  // Stardust / Pollen particles swirling around the flower
  for (int i = 0; i < 6; i++) {
    float fi = float(i);
    float pAngle = fi * 1.047 + t * (0.8 + 0.2 * fi);
    float pRad = 0.25 + 0.15 * sin(fi * 2.1 + t * 1.5) + bass * 0.1;
    vec2 pPos = vec2(cos(pAngle), sin(pAngle)) * pRad;
    float pDist = length(p - pPos);
    float pGlow = 0.003 / (pDist * pDist * 25.0 + 0.003);
    col = col + vec3(1.0, 0.9, 0.4) * pGlow * (0.8 + 0.8 * spark);
  }

  // Soft tone mapping and cinematic vignette
  col = col / (col + vec3(0.85));
  float vig = 1.0 - smoothstep(0.5, 1.5, r);
  col = col * vig * f.intensity * f.glow;

  return vec4(clamp(col, 0.0, 1.0), 1.0);
}

vec2 rotate2D(vec2 p, float a) {
  float c = cos(a);
  float s = sin(a);
  return vec2(p.x * c - p.y * s, p.x * s + p.y * c);
}

float getAngle(vec2 p) {
  float r = length(p);
  if (r < 0.00001) { return 0.0; }
  float a = asin(clamp(p.y / r, -1.0, 1.0));
