class Visual final : public Scene {
  struct Star { float radius, angle, lift, drift; int group; float spread; };
  std::vector<Star> stars;
  float turn = 0, breath = 0;
  // Música: envolventes suavizadas y golpe corto (valen 0 sin música).
  float bass = 0, body = 0, spark = 0, energy = 0, drive = 0, slowBass = 0, kick = 0, flash = 0;
  // Reloj propio para el centelleo de los agudos.
  double clock = 0;
  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }
  // Ángulo del brazo de la estrella i cuando la espiral tiene `arms` brazos.
  static float armAngle(size_t i, int arms) {
    return float(double(int(i % size_t(arms))) * pi * 2 / double(arms));
  }
 public:
  void reset(uint32_t seed) override {
    Random rng(seed); stars.clear(); stars.reserve(1500); turn=0; breath=0;
    bass = body = spark = energy = drive = slowBass = kick = flash = 0; clock = 0;
    for(int i=0;i<1500;i++) {
      float r=std::sqrt(rng.unit()); int arm=i%4;
      // El desorden de cada estrella se guarda aparte: con más brazos se aprieta.
      const float spread=(rng.unit()-.5f)*(.25f+r*.8f);
      stars.push_back({r, float(arm*pi/2)+r*5.8f+spread,
        (rng.unit()-.5f)*(.018f+r*.035f), .7f+rng.unit()*.6f, i%9, spread});
    }
  }
  void update(const Frame& f) override {
    turn += float(f.delta)*f.speed*.06f;
    float target=f.music.energy;
    breath += (target-breath)*float(1-std::exp(-f.delta*3));
    // Música estándar: graves, cuerpo, agudos, energía y golpe corto.
    const float dt = float(f.delta);
    const Music& mu = f.music;
    bass = follow(bass, mu.bass, 22.0f, 4.5f, dt);
    body = follow(body, mu.body, 12.0f, 3.0f, dt);
    spark = follow(spark, mu.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, mu.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, mu.active ? std::pow(std::clamp(mu.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);
    float hit = 0, fl = 0;
    for (const auto& e : mu.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : mu.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : mu.events[3]) fl = std::max(fl, e.strength);
    const float onset = std::clamp((mu.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, mu.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    clock += f.delta * f.speed;
  }
  void render(const Frame& f, Canvas& c) const override {
    auto g = glide(f);
    const float amp = f.intensity;
    // Pulso: cada opción mueve algo distinto y sus pesos mezclan las opciones.
    const float golpe = g.pulso.weight(0) * std::min(kick * amp, 1.0f);
    const float graves = g.pulso.weight(1) * std::min(bass * amp, 1.0f);
    const float agudos = g.pulso.weight(2) * std::min(spark * amp, 1.0f);
    Paint sky=Paint::radial({f.width*.5f,f.height*.47f},f.height*.75f,
      {Color::argb(0xff151031),Color::argb(0xff03040d)});
    c.rect({0,0,f.width,f.height},sky);
    c.save(); c.translate(f.width*.5f,f.height*.48f); c.rotate(-.38f);
    // Graves: la galaxia crece hasta un 12% más con los graves.
    float scale=std::min(f.width*.62f,f.height*.42f)*(1+breath*.045f)*(1+graves*.12f);
    Paint haze=Paint::radial({0,0},scale*.8f,{Color{.24f,.1f,.5f,.2f},Color{.08f,.02f,.3f,0}});
    haze.blend=Blend::plus; c.rect({-scale,-scale,scale*2,scale*2},haze);
    // Golpes: el centro estalla en un resplandor cálido; Graves: un halo
    // violeta que respira alrededor de los brazos.
    const float burst = std::min(1.0f, (.55f * golpe) * f.glow);
    const float swell = std::min(1.0f, (.35f * graves) * f.glow);
    if (burst + swell > .001f) {
      Paint light = Paint::radial({0, 0}, scale * (1.1f + swell * .3f),
        {Color{1, .8f, .62f, std::min(1.0f, burst + swell * .5f)}, Color{.7f, .45f, 1, std::min(1.0f, burst * .35f + swell * .6f)},
         Color{.3f, .15f, .7f, 0}}, {0, .35f, 1});
      light.blend = Blend::plus;
      c.circle({0, 0}, scale * (1.1f + swell * .3f), light);
    }
    const float neb = std::clamp(g.nebulosa, 0.0f, 1.0f);
    if (neb > .001f) {
      // Nebulosa: una bruma de color envuelve los brazos.
      Paint mist = Paint::radial({0, 0}, scale * (.7f + neb * .4f),
        {Color{.55f, .3f, .95f, .3f * neb}, Color{.95f, .45f, .6f, .12f * neb}, Color{.2f, .1f, .6f, 0}}, {0, .5f, 1});
      mist.blend = Blend::plus;
      c.rect({-scale * 1.2f, -scale * 1.2f, scale * 2.4f, scale * 2.4f}, mist);
    }
    // Brazos se desliza (5.4 brazos): cada estrella va de su brazo entre N al
    // de N+1, así los brazos se abren sin saltos. Con 4 queda el original.
    const int fewer = int(std::floor(g.brazos)), more = fewer + 1;
    const float between = g.brazos - float(fewer);
    const bool reshaped = g.brazos != 4.0f;
    // Con más de 4 brazos el desorden se estrecha para que no se mezclen.
    const float tighten = std::min(1.0f, 4.0f / g.brazos);
    const float mirror = std::clamp(g.espejo, 0.0f, 1.0f);
    const float tick = float(std::fmod(clock, 1000.0));
    for(int group=0;group<9;group++) {
      std::vector<Vec2> batch;batch.reserve(170);
      std::vector<Vec2> twin;
      if (mirror > 0) twin.reserve(170);
      for(size_t i=0;i<stars.size();i++) { const auto& s=stars[i]; if(s.group!=group) continue;
        float a=s.angle+turn*s.drift;
        if (reshaped) {
          const float from = armAngle(i, fewer), to = armAngle(i, more);
          a += from + (to - from) * between - float(int(i % 4)*pi/2) + s.spread * (tighten - 1.0f);
        }
        const Vec2 point{std::cos(a)*s.radius*scale,
          std::sin(a)*s.radius*scale*.49f+s.lift*scale};
        batch.push_back(point);
        if (mirror > 0) twin.push_back({-point.x, point.y});
      }
      Paint p;p.blend=Blend::plus;
      p.color=group%3==0?Color{.58f,.69f,1,.65f}:group%3==1?Color{1,.67f,.48f,.6f}:Color{.9f,.72f,1,.72f};
      // Golpes enciende las estrellas; Agudos las hace centellear por grupos.
      const float twinkle = .5f + .5f * std::sin(tick * 9.0f + float(group) * 1.7f);
      p.color.a = std::min(1.0f, p.color.a * (1 - neb * .35f) + golpe * .6f + graves * .25f + agudos * twinkle * .7f);
      // Nebulosa hace las estrellas difusas; Golpes las hincha un 20%, Graves
      // un 15% y Agudos las hace parpadear de tamaño.
      const float size = (.55f+(group/3)*.5f) * (1 + neb * 1.2f + golpe * .2f + graves * .15f + agudos * twinkle * .5f);
      c.points(batch,size,p);
      if (mirror > 0) {
        // Espejo: el gemelo reflejado se funde poco a poco.
        p.color.a *= mirror;
        c.points(twin, size, p);
      }
    }
    // Golpes: el núcleo late hasta un 18% más grande.
    const float coreR = scale*.28f*(1+golpe*.18f);
    Paint core=Paint::radial({0,0},coreR,{Color{1,.87f,.68f,.92f},Color{.65f,.34f,.75f,.22f},Color{.2f,.1f,.6f,0}},{0,.22f,1});
    core.blend=Blend::screen;c.circle({0,0},coreR,core);c.restore();
  }
};

class Visual final : public Scene {
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  // Relojes en doble precisión: la escena sin música es idéntica a 30 y 60 FPS.
  double clock = 0, morph = 0, sinceSwitch = 0, pulseAge = 100;
  float fadeMix = 1, pulsePower = 0;
  int beats = 0, autoMode = 0, modeFrom = 0, modeTo = 0;

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    clock = rng.unit() * 40.0;
    morph = rng.unit() * 6.28;
    sinceSwitch = 0;
    pulseAge = 100;
    pulsePower = 0;
    fadeMix = 1;
    beats = 0;
    autoMode = modeFrom = modeTo = 0;
  }

  void update(const Frame& f) override {
    auto m = modifiers(f);
    float dt = float(f.delta);
    const Music& mu = f.music;
    bass = follow(bass, mu.bass, 22.0f, 4.5f, dt);
    body = follow(body, mu.body, 12.0f, 3.0f, dt);
    spark = follow(spark, mu.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, mu.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, mu.active ? std::pow(std::clamp(mu.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : mu.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : mu.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : mu.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((mu.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, mu.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    sinceSwitch += f.delta;
    pulseAge += f.delta;
    if (hit > kick + 0.2f) {
      beats++;
      pulseAge = 0;
      pulsePower = hit;
      if (beats % 8 == 0) {
        autoMode = 1 - autoMode;
        sinceSwitch = 0;
      }
    }
    // El fundido avanza antes de mirar cambios: si el cambio es por tiempo,
    // empieza en su instante exacto (igual a 30 y 60 FPS).
    fadeMix = std::min(1.0f, fadeMix + dt / 1.2f);
    double carry = -1.0;
    if (!mu.active && sinceSwitch > 12.0) {
      autoMode = 1 - autoMode;
      sinceSwitch -= 12.0;
      carry = sinceSwitch;
    }
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    int wanted = m.estrella == 0 ? autoMode : m.estrella - 1;
    if (wanted != modeTo) {
      modeFrom = modeTo;
      modeTo = wanted;
      fadeMix = carry >= 0.0 ? std::min(1.0f, float(carry / 1.2)) : 0.0f;
    }
    clock += f.delta * f.speed * (1.0 + 0.8 * drive);
    if (m.movimiento) morph += f.delta * f.speed * (0.25 + 0.5 * drive);
  }

  void render(const Frame& f, Canvas& c) const override {
    auto m = modifiers(f);
    float amp = f.intensity;
    float shape = 0.5f + 0.5f * float(std::sin(morph));
    float pulse = pulseAge < 3.0 ? float(pulseAge) * 0.9f : 9.0f;
    std::vector<float> u;
    u.reserve(32);
    u.insert(u.end(), {float(std::fmod(clock, 1000.0)), bass * amp, kick * amp, energy});
    u.insert(u.end(), {float(modeFrom), float(modeTo), fadeMix, shape});
    u.insert(u.end(), {m.tamano, m.cinta, f.glow, flash * amp});
    u.insert(u.end(), {pulse, pulseAge < 3.0 ? pulsePower * amp : 0.0f, spark * amp, 0.0f});
    for (int i = 0; i < 4; i++) u.insert(u.end(), {f.colors[i].r, f.colors[i].g, f.colors[i].b});
    c.material("girih", {0, 0, f.width, f.height}, u);
  }
};

shaderSources.girih:
#version 460 core
#include <flutter/runtime_effect.glsl>
uniform vec2 uSize;
uniform vec4 uA;   // reloj, graves, golpe, energía
uniform vec4 uB;   // modo anterior, modo nuevo (0 = 8 puntas, 1 = 12), fundido, forma
uniform vec4 uD;   // tamaño, grosor de cinta, glow, destello
uniform vec4 uE;   // radio de la onda, fuerza de la onda, agudos
uniform vec3 uC0;
uniform vec3 uC1;
uniform vec3 uC2;
uniform vec3 uC3;
out vec4 fragColor;

const float PI = 3.14159265;

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

// Celda local: cuadrada (8 puntas) o hexagonal (12 puntas).
vec2 cellLocal(vec2 p, float hexMode) {
  if (hexMode < 0.5) return fract(p) - 0.5;
  vec2 r = vec2(1.0, 1.7320508);
  vec2 h = r * 0.5;
  vec2 a = mod(p, r) - h;
  vec2 b = mod(p - h, r) - h;
  return dot(a, a) < dot(b, b) ? a : b;
}

// Estrella {n/k}: distancia a sus rectas y número de rectas que la rodean.
vec2 star(vec2 q, float hexMode, float shape) {
  float n = hexMode < 0.5 ? 8.0 : 12.0;
  float k = hexMode < 0.5 ? mix(2.0, 3.0, shape) : mix(4.0, 5.0, shape);
  float R = hexMode < 0.5 ? 0.56 : 0.6;
  float c = R * cos(k * PI / n);
  float d = 9.0;
  float cnt = 0.0;
  for (int j = 0; j < 12; j++) {
    float fj = float(j);
    if (fj >= n) break;
    float a = (fj + 0.5 * k) * 2.0 * PI / n;
    float s = dot(q, vec2(cos(a), sin(a))) - c;
    d = min(d, abs(s));
    cnt += step(0.0, s);
  }
  return vec2(d, cnt);
}

vec3 tile(vec2 p, float hexMode, float shape, float px, float pulseLight) {
  vec2 q = cellLocal(p, hexMode);
  vec2 s = star(q, hexMode, shape);
  float cnt = s.y;
  // Relleno de las piezas según su sitio en el patrón.
  vec3 fill = cnt < 0.5 ? uC2 : (cnt < 1.5 ? uC3 : (cnt < 2.5 ? uC0 * 2.4 : uC0 * 1.2));
  fill *= 0.85 + 0.25 * uA.y;
  // Cinta de oro con borde oscuro y brillo en el centro.
  float w = 0.03 * uD.y * (1.0 + 0.35 * uA.y);
  float band = 1.0 - smoothstep(w, w + px, s.x);
  float edge = 1.0 - smoothstep(w + px * 1.5, w + px * 3.0, s.x);
  vec3 gold = uC1 * (0.85 + 0.35 * (1.0 - s.x / max(w, 1e-4)) + 0.9 * pulseLight);
  vec3 col = mix(fill, uC0 * 0.35, edge);
  col = mix(col, gold, band);
  return col;
}

void main() {
  vec2 frag = FlutterFragCoord().xy;
  float scale = min(uSize.x, uSize.y);
  vec2 p = (frag - 0.5 * uSize) / scale;
  float t = uA.x;
  // Lento giro y deriva de todo el patrón.
  float ang = t * 0.03;
  float cs = cos(ang);
  float sn = sin(ang);
  vec2 q = vec2(cs * p.x - sn * p.y, sn * p.x + cs * p.y);
  float cells = 3.2 / uD.x;
  q = q * cells + vec2(t * 0.05, t * 0.03);
  float px = cells / scale * 1.2;
  // Onda de luz dorada que sale del centro con cada golpe.
  float pulseLight = uE.y * exp(-abs(length(p) - uE.x) * 10.0);
  vec3 col = tile(q, uB.y, uB.w, px, pulseLight);
  if (uB.z < 0.999) {
    // Cambio de estrella: barrido circular desde el centro con un aro de oro.
    float front = uB.z * 1.9;
    float r = length(p);
    if (r > front) col = tile(q, uB.x, uB.w, px, pulseLight);
    col += uC1 * exp(-abs(r - front) * 40.0) * 1.2;
  }
  // Brillos sueltos sobre el oro con los agudos.
  col += uC1 * step(0.997 - 0.004 * uE.z, hash12(floor(frag * 0.5) + floor(t * 6.0))) * 0.6 * uE.z;
  col *= mix(1.0, uD.z, 0.4) * (0.95 + 0.15 * uA.z);
  col += uC1 * uD.w * 0.05;
  col *= 1.0 - 0.3 * smoothstep(0.7, 1.5, length(p * vec2(0.9, 0.65)));
  float peak = max(col.r, max(col.g, col.b));
  if (peak > 0.85) {
    float e = (peak - 0.85) / 0.15;
    col *= (0.85 + 0.15 * e / (1.0 + e)) / peak;
  }
  col += (hash12(frag) - 0.5) / 255.0;
  fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

visuals.nativeSource:
class Visual final : public Scene {
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  std::array<float, 8> bands{}, base{}, seeds{}, power{};
  float phase = 0;
  Random rng{3};

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

 public:
  void reset(uint32_t seed) override {
    rng = Random(seed);
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    bands.fill(0);
    power.fill(0);
    for (int i = 0; i < 8; i++) {
      base[i] = rng.unit() * 6.2831853f;
      seeds[i] = rng.unit() * 10.0f;
    }
    phase = rng.unit() * 10.0f;
  }

  void update(const Frame& f) override {
    float dt = float(f.delta);
    const Music& m = f.music;
    bass = follow(bass, m.bass, 22.0f, 4.5f, dt);
    body = follow(body, m.body, 12.0f, 3.0f, dt);
    spark = follow(spark, m.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, m.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, m.active ? std::pow(std::clamp(m.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : m.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : m.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : m.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((m.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, m.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    bool strike = hit > kick + 0.2f;
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));

    static const int edges[9] = {0, 3, 6, 9, 13, 17, 21, 26, 31};
    for (int b = 0; b < 8; b++) {
      float v = 0;
      for (int i = edges[b]; i < edges[b + 1]; i++) v = std::max(v, m.smoothSpectrum[i]);
      bands[b] = follow(bands[b], v, 22.0f, 4.0f, dt);
    }

    for (int i = 0; i < 8; i++) {
      // Tres filamentos siempre vivos; el resto aparece con su banda.
      float target = (i < 3 ? 0.55f : 0.0f) + bands[i] * 1.1f + kick * (i < 6 ? 0.7f : 0.3f);
      power[i] = follow(power[i], target, 25.0f, 5.0f, dt);
      if (strike) base[i] += (rng.unit() - 0.5f) * 2.2f;
      base[i] += dt * f.speed * (i % 2 ? 1.0f : -1.0f) * (0.08f + 0.25f * drive);
    }
    phase += dt * f.speed * (0.6f + 1.6f * drive + 1.2f * kick);
  }

  void render(const Frame& f, Canvas& c) const override {
    float amp = f.intensity;
    std::array<float, 8> angle{};
    for (int i = 0; i < 8; i++) angle[i] = base[i] + std::sin(phase * 0.35f + seeds[i]) * 0.45f;
    std::vector<float> u;
    u.reserve(44);
    u.insert(u.end(), {phase, bass * amp, kick * amp, energy});
    u.insert(u.end(), {angle[0], angle[1], angle[2], angle[3]});
    u.insert(u.end(), {angle[4], angle[5], angle[6], angle[7]});
    for (int i = 0; i < 8; i++) u.push_back(std::min(power[i] * amp, 2.0f));
    u.insert(u.end(), {spark * amp, flash, f.glow, f.detail});
    for (int i = 0; i < 4; i++) u.insert(u.end(), {f.colors[i].r, f.colors[i].g, f.colors[i].b});
    c.material("plasma_globe", {0, 0, f.width, f.height}, u);
  }
};

shaderSources.plasma_globe:
#version 460 core
#include <flutter/runtime_effect.glsl>
uniform vec2 uSize;
uniform vec4 uA;     // tiempo, graves, golpe, energía
uniform vec4 uAng0;
uniform vec4 uAng1;
uniform vec4 uPow0;
uniform vec4 uPow1;
uniform vec4 uM;     // agudos, destello, glow, detalle
uniform vec3 uC0;
uniform vec3 uC1;
uniform vec3 uC2;
uniform vec3 uC3;
out vec4 fragColor;

// Campana gaussiana segura: pow() con base negativa no está definido en GLSL.
float gauss(float x) {
  return exp(-x * x);
}

const float R = 0.34;

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash12(i), hash12(i + vec2(1.0, 0.0)), u.x),
             mix(hash12(i + vec2(0.0, 1.0)), hash12(i + vec2(1.0, 1.0)), u.x), u.y);
}

// Devuelve (núcleo, halo) de un filamento que va del centro al cristal.
vec2 filament(vec2 p, float ang, float power, float seed) {
  if (power < 0.02) return vec2(0.0);
  float t = uA.x;
  vec2 dir = vec2(cos(ang), sin(ang));
  vec2 nrm = vec2(-dir.y, dir.x);
  float along = dot(p, dir);
  float s = clamp(along / R, 0.0, 1.0);
  float env = sin(3.14159 * s) * (0.6 + 0.4 * s);
  float disp = (sin(s * 6.0 + t * 1.3 + seed * 5.0) * 0.07 +
                sin(s * 15.0 - t * 2.7 + seed * 11.0) * 0.03) * env * R;
  disp += (noise(vec2(s * 38.0 + seed, t * 9.0)) - 0.5) * (0.02 + 0.07 * uM.x) * env * R;
  float lateral = dot(p, nrm) - disp;
  float inside = smoothstep(-0.01, 0.02, along) * smoothstep(R * 1.01, R * 0.96, along);
  float width = (0.0030 + 0.0040 * min(power, 1.5)) * (1.0 - 0.45 * s);
  float core = exp(-lateral * lateral / (width * width));
  float halo = (0.00006 + 0.00012 * power) / (lateral * lateral + 0.00025);
  // Punto de contacto con el cristal.
  vec2 tip = dir * R + nrm * disp;
  float contact = exp(-dot(p - tip, p - tip) / (0.00025 + 0.0004 * power));
  return vec2((core * 1.4 + contact * 1.6) * inside * power + contact * power * 0.6,
              halo * inside * power);
}

void main() {
  vec2 frag = FlutterFragCoord().xy;
  float scale = min(uSize.x, uSize.y);
  vec2 p = (frag - 0.5 * uSize) / scale;
  p.y = -p.y;
  p.y -= 0.04;
  float r = length(p);
  float kick = uA.z;

  // Sala oscura con resplandor de color detrás del globo.
  vec3 col = uC0 + mix(uC2, uC1, 0.4) * exp(-r * r * 4.0) * (0.10 + 0.30 * kick + 0.12 * uA.w);

  // Peana bajo el globo.
  float baseTop = -R * 0.93;
  float baseW = 0.11 + (baseTop - p.y) * 0.35;
  float pedestal = step(p.y, baseTop) * step(abs(p.x), baseW) * step(baseTop - 0.22, p.y);
  float sheen = smoothstep(baseW, baseW * 0.2, abs(p.x - baseW * 0.35));
  vec3 pedestalCol = uC0 * 0.5 + vec3(0.05) * sheen +
                     mix(uC1, uC2, 0.5) * 0.18 * exp(-(baseTop - p.y) * 40.0) * (0.4 + kick);
  col = mix(col, pedestalCol, pedestal);

  if (r < R * 1.02) {
    // Gas interior y electrodo central.
    float inside = smoothstep(R, R * 0.97, r);
    vec3 gas = mix(uC2, uC1, 0.5 + 0.5 * sin(atan(p.y, p.x) * 2.0 + uA.x * 0.3)) *
               (0.015 + 0.04 * uA.w + 0.10 * kick) * (0.6 + 0.4 * noise(p * 6.0 + uA.x * 0.2));
    col = mix(col, uC0 * 0.35 + gas, inside);

    vec2 acc = vec2(0.0);
    acc += filament(p, uAng0.x, uPow0.x, 0.0);
    acc += filament(p, uAng0.y, uPow0.y, 1.7);
    acc += filament(p, uAng0.z, uPow0.z, 3.1);
    acc += filament(p, uAng0.w, uPow0.w, 4.6);
    acc += filament(p, uAng1.x, uPow1.x, 6.2);
    acc += filament(p, uAng1.y, uPow1.y, 7.9);
    acc += filament(p, uAng1.z, uPow1.z, 9.3);
    acc += filament(p, uAng1.w, uPow1.w, 10.8);
    vec3 arc = mix(uC1, uC3, clamp(acc.x * 0.6, 0.0, 1.0)) * acc.x;
    arc += uC1 * acc.y;
    col += arc * inside * (0.9 + 0.8 * uA.y) * uM.z;

    float coreR = 0.05 + 0.006 * uA.y + 0.01 * kick;
    float electrode = smoothstep(coreR, coreR * 0.85, r);
    vec3 electrodeCol = mix(uC1, uC3, 0.6) * (1.2 + 1.5 * kick) * (0.75 + 0.25 * smoothstep(coreR, 0.0, length(p - vec2(-0.015, 0.015))));
    col = mix(col, electrodeCol, electrode);
    col += uC1 * (0.0005 + 0.0025 * kick) / (r * r + 0.0025) * inside;

    // Cristal: borde con Fresnel y reflejo de ventana.
    float rim = gauss((r - R) / 0.006);
    col += mix(uC2, vec3(1.0), 0.5) * rim * (0.35 + 0.4 * kick);
    col += uC2 * smoothstep(R * 0.8, R, r) * inside * 0.06;
    vec2 hl = p - vec2(-0.13, 0.17);
    float highlight = exp(-dot(hl * vec2(1.0, 1.8), hl * vec2(1.0, 1.8)) * 140.0);
    col += vec3(1.0) * highlight * 0.12;
    float arcHl = gauss((r - R * 0.9) / 0.01) * smoothstep(0.2, 0.9, dot(normalize(p + vec2(1e-5, 0.0)), normalize(vec2(-0.6, 0.8))));
    col += vec3(1.0) * arcHl * 0.15;
  }

  col += uC3 * uM.y * 0.15;
  col *= 1.0 - 0.4 * smoothstep(0.45, 1.2, length(p * vec2(0.9, 0.65)));
  col = clamp((col * (2.51 * col + 0.03)) / (col * (2.43 * col + 0.59) + 0.14), 0.0, 1.0);
  col = pow(col, vec3(0.4545));
  col += (hash12(frag) - 0.5) / 255.0;
  fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

visuals.nativeSource:
class Visual final : public Scene {
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  std::array<float, 8> bands{}, base{}, seeds{}, power{};
  float phase = 0;
  Random rng{3};

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

 public:
  void reset(uint32_t seed) override {
    rng = Random(seed);
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    bands.fill(0);
    power.fill(0);
    for (int i = 0; i < 8; i++) {
      base[i] = rng.unit() * 6.2831853f;
      seeds[i] = rng.unit() * 10.0f;
    }
    phase = rng.unit() * 10.0f;
  }

  void update(const Frame& f) override {
    float dt = float(f.delta);
    const Music& m = f.music;
    bass = follow(bass, m.bass, 22.0f, 4.5f, dt);
    body = follow(body, m.body, 12.0f, 3.0f, dt);
    spark = follow(spark, m.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, m.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, m.active ? std::pow(std::clamp(m.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : m.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : m.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : m.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((m.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, m.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    bool strike = hit > kick + 0.2f;
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));

    static const int edges[9] = {0, 3, 6, 9, 13, 17, 21, 26, 31};
    for (int b = 0; b < 8; b++) {
      float v = 0;
      for (int i = edges[b]; i < edges[b + 1]; i++) v = std::max(v, m.smoothSpectrum[i]);
      bands[b] = follow(bands[b], v, 22.0f, 4.0f, dt);
    }

    for (int i = 0; i < 8; i++) {
      // Tres filamentos siempre vivos; el resto aparece con su banda.
      float target = (i < 3 ? 0.55f : 0.0f) + bands[i] * 1.1f + kick * (i < 6 ? 0.7f : 0.3f);
      power[i] = follow(power[i], target, 25.0f, 5.0f, dt);
      if (strike) base[i] += (rng.unit() - 0.5f) * 2.2f;
      base[i] += dt * f.speed * (i % 2 ? 1.0f : -1.0f) * (0.08f + 0.25f * drive);
    }
    phase += dt * f.speed * (0.6f + 1.6f * drive + 1.2f * kick);
  }

  void render(const Frame& f, Canvas& c) const override {
    float amp = f.intensity;
    std::array<float, 8> angle{};
    for (int i = 0; i < 8; i++) angle[i] = base[i] + std::sin(phase * 0.35f + seeds[i]) * 0.45f;
    std::vector<float> u;
    u.reserve(44);
    u.insert(u.end(), {phase, bass * amp, kick * amp, energy});
    u.insert(u.end(), {angle[0], angle[1], angle[2], angle[3]});
    u.insert(u.end(), {angle[4], angle[5], angle[6], angle[7]});
    for (int i = 0; i < 8; i++) u.push_back(std::min(power[i] * amp, 2.0f));
    u.insert(u.end(), {spark * amp, flash, f.glow, f.detail});
    for (int i = 0; i < 4; i++) u.insert(u.end(), {f.colors[i].r, f.colors[i].g, f.colors[i].b});
    c.material("plasma_globe", {0, 0, f.width, f.height}, u);
  }
};

shaderSources.plasma_globe:
#version 460 core
#include <flutter/runtime_effect.glsl>
uniform vec2 uSize;
uniform vec4 uA;     // tiempo, graves, golpe, energía
uniform vec4 uAng0;
uniform vec4 uAng1;
uniform vec4 uPow0;
uniform vec4 uPow1;
uniform vec4 uM;     // agudos, destello, glow, detalle
uniform vec3 uC0;
uniform vec3 uC1;
uniform vec3 uC2;
uniform vec3 uC3;
out vec4 fragColor;

// Campana gaussiana segura: pow() con base negativa no está definido en GLSL.
float gauss(float x) {
  return exp(-x * x);
}

const float R = 0.34;

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash12(i), hash12(i + vec2(1.0, 0.0)), u.x),
             mix(hash12(i + vec2(0.0, 1.0)), hash12(i + vec2(1.0, 1.0)), u.x), u.y);
}

// Devuelve (núcleo, halo) de un filamento que va del centro al cristal.
vec2 filament(vec2 p, float ang, float power, float seed) {
  if (power < 0.02) return vec2(0.0);
  float t = uA.x;
  vec2 dir = vec2(cos(ang), sin(ang));
  vec2 nrm = vec2(-dir.y, dir.x);
  float along = dot(p, dir);
  float s = clamp(along / R, 0.0, 1.0);
  float env = sin(3.14159 * s) * (0.6 + 0.4 * s);
  float disp = (sin(s * 6.0 + t * 1.3 + seed * 5.0) * 0.07 +
                sin(s * 15.0 - t * 2.7 + seed * 11.0) * 0.03) * env * R;
  disp += (noise(vec2(s * 38.0 + seed, t * 9.0)) - 0.5) * (0.02 + 0.07 * uM.x) * env * R;
  float lateral = dot(p, nrm) - disp;
  float inside = smoothstep(-0.01, 0.02, along) * smoothstep(R * 1.01, R * 0.96, along);
  float width = (0.0030 + 0.0040 * min(power, 1.5)) * (1.0 - 0.45 * s);
  float core = exp(-lateral * lateral / (width * width));
  float halo = (0.00006 + 0.00012 * power) / (lateral * lateral + 0.00025);
  // Punto de contacto con el cristal.
  vec2 tip = dir * R + nrm * disp;
  float contact = exp(-dot(p - tip, p - tip) / (0.00025 + 0.0004 * power));
  return vec2((core * 1.4 + contact * 1.6) * inside * power + contact * power * 0.6,
              halo * inside * power);
}

void main() {
  vec2 frag = FlutterFragCoord().xy;
  float scale = min(uSize.x, uSize.y);
  vec2 p = (frag - 0.5 * uSize) / scale;
  p.y = -p.y;
  p.y -= 0.04;
  float r = length(p);
  float kick = uA.z;

  // Sala oscura con resplandor de color detrás del globo.
  vec3 col = uC0 + mix(uC2, uC1, 0.4) * exp(-r * r * 8.0) * (0.10 + 0.30 * kick + 0.12 * uA.w);

  // Peana bajo el globo.
  float baseTop = -R * 0.93;
  float baseW = 0.11 + (baseTop - p.y) * 0.35;
  float pedestal = step(p.y, baseTop) * step(abs(p.x), baseW) * step(baseTop - 0.22, p.y);
  float sheen = smoothstep(baseW, baseW * 0.2, abs(p.x - baseW * 0.35));
  vec3 pedestalCol = uC0 * 0.5 + vec3(0.05) * sheen +
                     mix(uC1, uC2, 0.5) * 0.18 * exp(-(baseTop - p.y) * 40.0) * (0.4 + kick);
  col = mix(col, pedestalCol, pedestal);

  if (r < R * 1.02) {
    // Gas interior y electrodo central.
    float inside = smoothstep(R, R * 0.97, r);
    vec3 gas = mix(uC2, uC1, 0.5 + 0.5 * sin(atan(p.y, p.x) * 2.0 + uA.x * 0.3)) *
               (0.015 + 0.04 * uA.w + 0.10 * kick) * (0.6 + 0.4 * noise(p * 6.0 + uA.x * 0.2));
    col = mix(col, uC0 * 0.35 + gas, inside);

    vec2 acc = vec2(0.0);
    acc += filament(p, uAng0.x, uPow0.x, 0.0);
    acc += filament(p, uAng0.y, uPow0.y, 1.7);
    acc += filament(p, uAng0.z, uPow0.z, 3.1);
    acc += filament(p, uAng0.w, uPow0.w, 4.6);
    acc += filament(p, uAng1.x, uPow1.x, 6.2);
    acc += filament(p, uAng1.y, uPow1.y, 7.9);
    acc += filament(p, uAng1.z, uPow1.z, 9.3);
    acc += filament(p, uAng1.w, uPow1.w, 10.8);
    vec3 arc = mix(uC1, uC3, clamp(acc.x * 0.6, 0.0, 1.0)) * acc.x;
    arc += uC1 * acc.y;
    col += arc * inside * (0.9 + 0.8 * uA.y) * uM.z;

    float coreR = 0.05 + 0.006 * uA.y + 0.01 * kick;
    float electrode = smoothstep(coreR, coreR * 0.85, r);
    vec3 electrodeCol = mix(uC1, uC3, 0.6) * (1.2 + 1.5 * kick) * (0.75 + 0.25 * smoothstep(coreR, 0.0, length(p - vec2(-0.015, 0.015))));
    col = mix(col, electrodeCol, electrode);
    col += uC1 * (0.0005 + 0.0025 * kick) / (r * r + 0.0025) * inside;

    // Cristal: borde con Fresnel y reflejo de ventana.
    float rim = gauss((r - R) / 0.006);
    col += mix(uC2, vec3(1.0), 0.5) * rim * (0.35 + 0.4 * kick);
    col += uC2 * smoothstep(R * 0.8, R, r) * inside * 0.06;
    vec2 hl = p - vec2(-0.13, 0.17);
    float highlight = exp(-dot(hl * vec2(1.0, 1.8), hl * vec2(1.0, 1.8)) * 140.0);
    col += vec3(1.0) * highlight * 0.12;
    float arcHl = gauss((r - R * 0.9) / 0.01) * smoothstep(0.2, 0.9, dot(normalize(p + vec2(1e-5, 0.0)), normalize(vec2(-0.6, 0.8))));
    col += vec3(1.0) * arcHl * 0.15;
  }

  col *= 1.0 - 0.4 * smoothstep(0.45, 1.2, length(p * vec2(0.9, 0.65)));
  col = clamp((col * (2.51 * col + 0.03)) / (col * (2.43 * col + 0.59) + 0.14), 0.0, 1.0);
  col = pow(col, vec3(0.4545));
  // Fondo transparente: color premultiplicado y opacidad según el brillo; la
  // luz muy tenue se vuelve transparente del todo para no dejar velo.
  col = clamp(col, 0.0, 1.0);
  float veilPeak = max(col.r, max(col.g, col.b));
  float clearCut = smoothstep(0.04, 0.12, veilPeak);
  col *= clearCut;
  float alpha = clamp(veilPeak * 1.25, 0.0, 1.0) * clearCut;
  // La peana es un objeto sólido.
  alpha = max(alpha, pedestal);
  fragColor = vec4(col, alpha);
}

visuals.nativeSource:
class Visual final : public Scene {
  struct Particle { float x,y,velocity,phase; };
  // Se reserva el máximo de Motas: cambiar el ajuste nunca reserva memoria.
  static constexpr int kMax=480;
  std::vector<Particle> particles;
  float impulse=0;
  // Música: envolventes suavizadas y golpe corto (valen 0 sin música).
  float bass=0,body=0,spark=0,energy=0,drive=0,slowBass=0,kick=0,flash=0;
  // Reloj propio para el centelleo de los agudos.
  double clock=0;
  static float follow(float v,float target,float up,float down,float dt){
    return v+(target-v)*(1.0f-std::exp(-(target>v?up:down)*dt));
  }
 public:
  void reset(uint32_t seed) override {
    Random r(seed);particles.clear();particles.reserve(kMax);impulse=0;
    bass=body=spark=energy=drive=slowBass=kick=flash=0;clock=0;
    // Las primeras 240 son las de siempre; las demás sólo aparecen con Motas.
    for(int i=0;i<kMax;i++)particles.push_back({r.unit(),r.unit(),.02f+r.unit()*.03f,r.unit()*6.28f});
  }
  void update(const Frame& f) override {
    for(const auto& event:f.music.events[0])impulse=std::max(impulse,event.strength);
    impulse*=float(std::exp(-f.delta*2.2));
    for(auto& p:particles){p.y-=p.velocity*float(f.delta)*f.speed*(1+impulse*3);
      if(p.y<-.03f)p.y+=1.06f;p.phase+=float(f.delta)*.3f;}
    // Música estándar: graves, cuerpo, agudos, energía y golpe corto.
    const float dt=float(f.delta);
    const Music& mu=f.music;
    bass=follow(bass,mu.bass,22.0f,4.5f,dt);
    body=follow(body,mu.body,12.0f,3.0f,dt);
    spark=follow(spark,mu.spark,30.0f,7.0f,dt);
    energy=follow(energy,mu.energy,6.0f,1.8f,dt);
    drive=follow(drive,mu.active?std::pow(std::clamp(mu.energy,0.0f,1.0f),0.8f):0.0f,3.0f,0.7f,dt);
    float hit=0,fl=0;
    for(const auto& e:mu.events[0])hit=std::max(hit,e.strength);
    for(const auto& e:mu.events[2])hit=std::max(hit,e.strength*0.85f);
    for(const auto& e:mu.events[3])fl=std::max(fl,e.strength);
    const float onset=std::clamp((mu.bass-slowBass-0.15f)*2.5f,0.0f,1.0f);
    slowBass=follow(slowBass,mu.bass,3.0f,3.0f,dt);
    hit=std::min(std::max(hit,onset),1.0f);
    kick=std::max(kick*std::exp(-dt*5.0f),hit);
    flash=std::max(flash*std::exp(-dt*8.0f),std::min(fl,1.0f));
    clock+=f.delta*f.speed;
  }
  void render(const Frame& f, Canvas& c) const override {
    auto g=glide(f);
    const float amp=f.intensity;
    // Pulso: cada opción mueve algo distinto y sus pesos mezclan las opciones.
    const float golpe=g.pulso.weight(0)*std::min(kick*amp,1.0f);
    const float graves=g.pulso.weight(1)*std::min(bass*amp,1.0f);
    const float agudos=g.pulso.weight(2)*std::min(spark*amp,1.0f);
    // Motas: cuántas se dibujan de las reservadas (240 es el original).
    const int visible=std::clamp(int(g.motas),0,kMax);
    // Vaivén: 0 sube recto, 1 es el original, 4 serpentea ancho y apretado.
    const float sway=g.vaiven;
    const float curl=1+(sway-1)*.5f;
    const float trail=std::clamp(g.estela,0.0f,1.0f);
    const float tick=float(std::fmod(clock,1000.0));
    for(int group=0;group<4;group++){
      std::vector<Vec2> points;points.reserve(size_t(visible/4+1));
      for(int i=group;i<visible;i+=4){const auto& p=particles[size_t(i)];
        // Graves abre el enjambre desde el centro; Agudos lo hace temblar.
        const float open=(p.x-.5f)*graves*.12f;
        const float jx=std::sin(tick*41.0f+float(i)*2.3f)*agudos*.004f;
        const float jy=std::cos(tick*37.0f+float(i)*1.7f)*agudos*.003f;
        points.push_back({(p.x+std::sin(p.phase+p.y*3*curl)*.02f*sway+open+jx)*f.width,(p.y+jy)*f.height});}
      // Golpes enciende las motas; Agudos las hace titilar por grupos.
      const float twinkle=.5f+.5f*std::sin(tick*9.0f+float(group)*1.7f);
      const float alpha=std::min(1.0f,.35f+group*.16f+golpe*.6f+agudos*twinkle*.35f);
      // Golpes las hincha un 20%; Graves, un 15% que respira.
      const float size=(.8f+group*.45f+impulse*.4f)*(1+golpe*.2f+graves*.15f);
      if(trail>.001f){
        // Estela: una cola de luz bajo cada mota que dibuja su vaivén; la
        // mitad cercana brilla más que la lejana.
        Path near,far;
        for(int i=group;i<visible;i+=4){const auto& p=particles[size_t(i)];
          const float open=(p.x-.5f)*graves*.12f;
          for(int k=0;k<=4;k++){
            const float y=p.y+float(k)*(.01f+p.velocity*.6f)*trail;
            const Vec2 q{(p.x+std::sin(p.phase+y*3*curl)*.02f*sway+open)*f.width,y*f.height};
            if(k==0)near.moveTo(q.x,q.y);else if(k<=2)near.lineTo(q.x,q.y);
            if(k==2)far.moveTo(q.x,q.y);else if(k>2)far.lineTo(q.x,q.y);
          }
        }
        Paint tp;tp.blend=Blend::plus;tp.strokeWidth=size*1.1f;tp.strokeCap=1;tp.strokeJoin=1;
        tp.color={1,.6f+group*.05f,.2f+group*.1f,std::min(1.0f,alpha*trail*.2f)};
        c.path(far,tp);
        tp.color.a=std::min(1.0f,alpha*trail*.45f);
        c.path(near,tp);
      }
      // Golpes y Graves: cada mota florece en un halo de luz, como un bokeh.
      const float bloom=std::min(1.0f,(golpe*.4f+graves*.25f)*f.glow);
      if(bloom>.001f){
        Paint halo;halo.blend=Blend::plus;halo.color={1,.6f+group*.05f,.25f+group*.1f,bloom};
        c.points(points,size*6.0f,halo);
      }
      Paint paint;paint.blend=Blend::plus;paint.color={1,.65f+group*.05f,.25f+group*.12f,alpha};
      c.points(points,size,paint);
      if(agudos>.001f){
        // Agudos: la mitad de las motas centellea, cada una a su ritmo.
        std::vector<Vec2> lit;lit.reserve(points.size());
        for(size_t k=0;k<points.size();k++)
          if(std::sin(tick*11.0f+float(k*4+size_t(group))*2.39f)>0.0f)lit.push_back(points[k]);
        Paint sp;sp.blend=Blend::plus;sp.color={1,.85f,.6f,std::min(1.0f,agudos*.3f*f.glow)};
        c.points(lit,size*4.5f,sp);
        sp.color={1,.92f,.75f,std::min(1.0f,agudos)};
        c.points(lit,size*2.0f,sp);
      }
    }
  }
};

class Visual final : public Scene {
  static constexpr int kMax = 150;
  struct Stroke {
    double start;
    std::vector<Vec2> left, right;   // contorno del trazo, en unidades del lado corto
    std::vector<Vec2> drops;
    std::vector<float> dropSize;
    uint8_t color;
    float duration;
  };
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  // Relojes en doble precisión: la escena sin música es idéntica a 30 y 60 FPS.
  double clock = 0, spawnAcc = 0, clearStart = -1;
  float halfH = 1;
  Random rng{1};
  std::vector<Stroke> strokes;

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

  float range(float a, float b) { return a + (b - a) * rng.unit(); }

  void spawn(double when, int kind, float thick) {
    if (int(strokes.size()) >= kMax || clearStart >= 0.0) return;
    Stroke s;
    s.start = when;
    s.color = uint8_t(std::min(int(rng.unit() * 5.0f), 4));
    // Latigazo largo, chorro grueso que serpentea o salpicón.
    int points = kind == 2 ? 10 : 64;
    float x = range(-0.55f, 0.55f), y = range(-halfH * 1.05f, halfH * 1.05f);
    float heading = range(0.0f, 6.2831853f);
    float length = kind == 0 ? range(0.6f, 1.5f) : (kind == 1 ? range(0.2f, 0.5f) : range(0.04f, 0.08f));
    float base = (kind == 0 ? range(0.004f, 0.014f) : (kind == 1 ? range(0.018f, 0.04f) : range(0.045f, 0.09f))) * thick;
    float bend = range(-3.0f, 3.0f), wiggle = range(1.0f, 4.0f), ph = range(0.0f, 6.28f);
    float step = length / float(points - 1);
    std::vector<Vec2> center(static_cast<size_t>(points));
    std::vector<float> width(static_cast<size_t>(points));
    float wp1 = range(0.0f, 6.28f), wp2 = range(0.0f, 6.28f);
    for (int i = 0; i < points; i++) {
      float u = float(i) / float(points - 1);
      center[size_t(i)] = {x, y};
      float taper = std::min(1.0f, std::min(u, 1.0f - u) * 6.0f + 0.15f);
      float w = base * (0.45f + 0.35f * std::sin(u * 17.0f + wp1) + 0.3f * std::sin(u * 41.0f + wp2));
      if (kind == 2) w = base * (0.75f + 0.25f * std::sin(u * 6.28f * 2.0f + wp1));
      width[size_t(i)] = std::max(base * 0.12f, w) * taper;
      heading += (bend + wiggle * std::sin(u * 9.0f + ph)) * step * 2.0f;
      x += std::cos(heading) * step;
      y += std::sin(heading) * step;
    }
    // Contorno: a cada lado del centro según el grosor (un salpicón es redondo).
    for (int i = 0; i < points; i++) {
      Vec2 a = center[size_t(std::max(0, i - 1))], b = center[size_t(std::min(points - 1, i + 1))];
      float dx = b.x - a.x, dy = b.y - a.y, len = std::sqrt(dx * dx + dy * dy) + 1e-6f;
      float nx = -dy / len, ny = dx / len;
      if (kind == 2) {
        float ang = 6.2831853f * float(i) / float(points);
        float r = width[size_t(i)] * range(0.8f, 1.25f);
        s.left.push_back({center[0].x + std::cos(ang) * r, center[0].y + std::sin(ang) * r});
        continue;
      }
      s.left.push_back({center[size_t(i)].x + nx * width[size_t(i)] * 0.5f, center[size_t(i)].y + ny * width[size_t(i)] * 0.5f});
      s.right.push_back({center[size_t(i)].x - nx * width[size_t(i)] * 0.5f, center[size_t(i)].y - ny * width[size_t(i)] * 0.5f});
    }
    // Gotas alrededor: muchas en un salpicón, unas pocas en un latigazo.
    int drops = kind == 2 ? 40 : int(range(4.0f, 18.0f));
    for (int k = 0; k < drops; k++) {
      Vec2 c0 = center[size_t(std::min(int(rng.unit() * float(points)), points - 1))];
      float ang = range(0.0f, 6.2831853f);
      float dist = kind == 2 ? base * range(1.0f, 4.5f) : range(0.005f, 0.06f);
      s.drops.push_back({c0.x + std::cos(ang) * dist, c0.y + std::sin(ang) * dist});
      s.dropSize.push_back(range(0.0015f, kind == 2 ? 0.012f : 0.006f) * thick);
    }
    s.duration = kind == 0 ? 0.45f : (kind == 1 ? 0.35f : 0.12f);
    strokes.push_back(std::move(s));
  }

  // Qué trazo cae según el gesto: 0 latigazo, 1 chorro, 2 salpicón.
  int pickKind(int gesture) {
    static const float mix[3][2] = {{0.68f, 0.9f}, {0.18f, 0.88f}, {0.15f, 0.3f}};
    const float* m = mix[std::clamp(gesture, 0, 2)];
    float r = rng.unit();
    return r < m[0] ? 0 : (r < m[1] ? 1 : 2);
  }

 public:
  void reset(uint32_t seed) override {
    rng = Random(seed);
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    clock = 0;
    spawnAcc = 0.6;
    clearStart = -1;
    halfH = 1;
    strokes.clear();
    strokes.reserve(kMax + 4);
  }

  void update(const Frame& f) override {
    auto m = modifiers(f);
    float dt = float(f.delta);
    const Music& mu = f.music;
    bass = follow(bass, mu.bass, 22.0f, 4.5f, dt);
    body = follow(body, mu.body, 12.0f, 3.0f, dt);
    spark = follow(spark, mu.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, mu.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, mu.active ? std::pow(std::clamp(mu.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : mu.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : mu.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : mu.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((mu.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, mu.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    bool beat = hit > kick + 0.2f;
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    halfH = 0.5f * f.height / std::max(std::min(f.width, f.height), 1.0f);

    double step = f.delta * f.speed;
    double before = clock;
    clock += step;
    // Ritmo constante de pintura, cada trazo en su instante exacto.
    double rate = 2.2 * double(m.ritmo) * (1.0 + 1.5 * double(drive));
    spawnAcc += step * rate;
    while (spawnAcc >= 1.0) {
      spawnAcc -= 1.0;
      spawn(clock - spawnAcc / rate, pickKind(m.colores), m.grosor);
    }
    if (beat) {
      // El trazo extra de cada golpe es el del gesto elegido.
      spawn(clock, std::clamp(m.colores, 0, 2), m.grosor * (1.0f + 0.5f * hit));
      if (hit > 0.7f) spawn(clock, 2, m.grosor);
    }
    (void)before;
    // Lienzo lleno: se cubre durante 1,4 s y se empieza otro.
    if (clearStart < 0.0 && int(strokes.size()) >= kMax) clearStart = clock;
    if (clearStart >= 0.0 && clock - clearStart > 1.4) {
      strokes.clear();
      clearStart = -1;
    }
  }

  void render(const Frame& f, Canvas& c) const override {
    auto m = modifiers(f);
    float amp = f.intensity;
    bool dark = m.fondo == 1;
    Color paper = dark ? Color{0.035f, 0.03f, 0.03f, 1.0f} : f.colors[0];
    std::vector<float> u = {paper.r, paper.g, paper.b, dark ? 1.0f : 0.0f};
    c.material("linen", {0, 0, f.width, f.height}, u);
    std::array<Color, 5> pal = {f.colors[3], f.colors[3], f.colors[1], f.colors[2], Color{0.88f, 0.48f, 0.08f, 1.0f}};
    // En lienzo negro, la pintura negra pasa a ser blanca.
    if (dark) {
      pal[0] = Color{0.95f, 0.93f, 0.88f, 1.0f};
      pal[1] = Color{0.95f, 0.93f, 0.88f, 1.0f};
    }
    float side = std::min(f.width, f.height);
    float cx = f.width * 0.5f, cy = f.height * 0.5f;
    auto toPx = [&](Vec2 p) { return Vec2{cx + p.x * side, cy + p.y * side}; };
    float cover = clearStart >= 0.0 ? float(std::clamp((clock - clearStart) / 1.4, 0.0, 1.0)) : 0.0f;
    float lit = (0.92f + 0.15f * kick) * amp;
    for (const auto& s : strokes) {
      float prog = float(std::clamp((clock - s.start) / double(s.duration), 0.0, 1.0));
      if (prog <= 0.0f) continue;
      const Color& base = pal[size_t(s.color)];
      Paint p;
      p.color = Color{std::min(1.0f, base.r * lit), std::min(1.0f, base.g * lit), std::min(1.0f, base.b * lit), 1.0f};
      Path path;
      if (s.right.empty()) {
        // Salpicón: crece desde el centro.
        Vec2 c0{0, 0};
        for (const auto& q : s.left) { c0.x += q.x; c0.y += q.y; }
        c0.x /= float(s.left.size());
        c0.y /= float(s.left.size());
        for (size_t i = 0; i < s.left.size(); i++) {
          Vec2 q{c0.x + (s.left[i].x - c0.x) * prog, c0.y + (s.left[i].y - c0.y) * prog};
          Vec2 px = toPx(q);
          if (i == 0) path.moveTo(px.x, px.y); else path.lineTo(px.x, px.y);
        }
      } else {
        size_t count = std::max<size_t>(2, size_t(prog * float(s.left.size())));
        for (size_t i = 0; i < count; i++) {
          Vec2 px = toPx(s.left[i]);
          if (i == 0) path.moveTo(px.x, px.y); else path.lineTo(px.x, px.y);
        }
        for (size_t i = count; i-- > 0;) {
          Vec2 px = toPx(s.right[i]);
          path.lineTo(px.x, px.y);
        }
      }
      path.close();
      c.path(path, p);
      if (prog >= 0.6f && !s.drops.empty()) {
        // Gotas en tres tamaños.
        std::array<std::vector<Vec2>, 3> sized;
        for (size_t k = 0; k < s.drops.size(); k++) {
          int b = s.dropSize[k] < 0.003f ? 0 : (s.dropSize[k] < 0.006f ? 1 : 2);
          sized[size_t(b)].push_back(toPx(s.drops[k]));
        }
        static const float radii[3] = {0.0016f, 0.0038f, 0.0075f};
        for (int b = 0; b < 3; b++) {
          if (!sized[size_t(b)].empty()) c.points(sized[size_t(b)], radii[b] * side * m.grosor, p);
        }
      }
    }
    if (cover > 0.0f) {
      // Lienzo nuevo: una capa de imprimación cubre el cuadro.
      Paint veil;
      veil.color = Color{paper.r, paper.g, paper.b, cover};
      c.rect({0, 0, f.width, f.height}, veil);
    }
    if (flash > 0.01f) {
      Paint fl;
      fl.color = pal[2].opacity(std::clamp(flash * 0.06f * amp, 0.0f, 1.0f));
      c.rect({0, 0, f.width, f.height}, fl);
    }
  }
};

