        _146 = (uB.xyz * ((exp(abs(_59) * (-60.0)) * (0.2199999988079071044921875 + (0.25 * uA.w))) + ((smoothstep(0.0, 0.119999997317790985107421875, _59) * (1.0 - smoothstep(0.119999997317790985107421875, 0.300000011920928955078125, _59))) * 0.039999999105930328369140625))) * smoothstep(0.4199999868869781494140625, 0.300000011920928955078125, abs(_26.x - 0.5));
    }
    else
