visuals.nativeSource:
class Visual final : public Scene {
  struct Star { float x, y, z0, cycle; };
  std::vector<Star> stars;
  float travel = 0.0f;
  float smoothBass = 0.0f;
  float smoothEnergy = 0.0f;
  // Música estándar: envolventes y golpe corto (valen 0 sin música).
  float bass = 0, body = 0, spark = 0, energy = 0, drive = 0, slowBass = 0, kick = 0, flash = 0;
  // Reloj propio para el temblor de los agudos.
  double clock = 0;
  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }
  static float hashU(uint32_t x) {
    x ^= x >> 16; x *= 0x7feb352dU; x ^= x >> 15; x *= 0x846ca68bU; x ^= x >> 16;
    return float(x & 0xffffffu) / 16777216.0f;
  }
  // Remolino: gira un punto alrededor del centro de la pantalla.
  static void turn(float& x, float& y, float angle) {
    const float cs = std::cos(angle), sn = std::sin(angle);
    const float nx = x * cs - y * sn;
    y = x * sn + y * cs; x = nx;
  }
 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    stars.clear(); stars.reserve(621);
    travel = 0.0f; smoothBass = 0.0f; smoothEnergy = 0.0f;
    bass = body = spark = energy = drive = slowBass = kick = flash = 0; clock = 0;
    for (int i = 0; i < 621; i++) {
      Star s;
      s.x = (rng.unit() - 0.5f) * 2.2f;
      s.y = (rng.unit() - 0.5f) * 2.2f;
      s.z0 = rng.unit() * 2.2f + 0.05f;
      s.cycle = 2.2f + 1.2f;
      stars.push_back(s);
    }
  }
  void update(const Frame& f) override {
    float dt = float(f.delta);
    float targetEnergy = f.music.active ? f.music.energy : 0.0f;
    float targetBass = f.music.active ? f.music.bass : 0.0f;
    smoothBass += (targetBass - smoothBass) * float(1.0 - std::exp(-dt * 6.0));
    smoothEnergy += (targetEnergy - smoothEnergy) * float(1.0 - std::exp(-dt * 5.0));

    // En silencio reposa en un crucero estelar pausado (~0.10f).
    // Con música acelera hacia velocidad hiperlumínica con estelas largas.
    float audioDrive = 0.10f + smoothEnergy * 0.90f + smoothBass * 0.45f;
    if (f.reducedMotion) audioDrive *= 0.4f;
    travel += dt * f.speed * audioDrive * 1.6f;

    // Música estándar: graves, cuerpo, agudos, energía y golpe corto.
    const Music& mu = f.music;
    bass = follow(bass, mu.bass, 22.0f, 4.5f, dt);
    body = follow(body, mu.body, 12.0f, 3.0f, dt);
    spark = follow(spark, mu.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, mu.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, mu.active ? std::pow(std::clamp(mu.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);
    float hit = 0, fl = 0;
    for (const auto& e : mu.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : mu.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : mu.events[3]) fl = std::max(fl, e.strength);
    const float onset = std::clamp((mu.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, mu.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    // Golpes: cada golpe da un tirón hacia delante (vale 0 sin música).
    auto g = glide(f);
    travel += dt * f.speed * std::min(kick * f.intensity, 1.0f) * g.pulso.weight(0) * 1.4f;
    clock += f.delta;
  }
  void render(const Frame& f, Canvas& c) const override {
    auto g = glide(f);
    const float level = f.intensity;
    // Pulso: cada opción mueve algo distinto y sus pesos mezclan las opciones.
    const float golpe = g.pulso.weight(0) * std::min(kick * level, 1.0f);
    const float graves = g.pulso.weight(1) * std::min(bass * level, 1.0f);
    const float agudos = g.pulso.weight(2) * std::min(spark * level, 1.0f);
    const float tick = float(std::fmod(clock, 1000.0));
    float w = f.width, h = f.height;
    float cx = w * 0.5f, cy = h * 0.5f;
    float boost = std::clamp((0.7f + 0.5f * smoothEnergy + 0.4f * smoothBass) * f.intensity, 0.0f, 1.0f);
    Paint bg; bg.color = Color::argb(0xff02020c);
    c.rect({0, 0, w, h}, bg);
    // Apertura: 0 es el núcleo original; 1 abre el salto a toda la pantalla.
    // Graves: el campo se abre un 14% más con los graves.
    // Golpes: el núcleo estalla hacia fuera en cada golpe (menos cuanto más
    // abierto está ya el salto, para no sacar las estrellas de la pantalla).
    const float lens = 0.75f * std::exp(g.apertura * 5.7f) * (1.0f + graves * 0.14f)
      * (1.0f + golpe * 3.0f * (1.0f - g.apertura * 0.85f));
    const float swirl = g.remolino;
    const float trail = g.estela;
    Path lanes[3];
    std::vector<Vec2> heads[3];
    for (int i = 0; i < 3; i++) heads[i].reserve(240);
    std::vector<Vec2> glints;
    for (size_t idx = 0; idx < stars.size(); idx++) {
      const Star& s = stars[idx];
      float z = std::fmod(s.z0 - travel, s.cycle);
      if (z < 0.04f) z += s.cycle;
      // Remolino: las estrellas cercanas giran más, así el viaje se enrosca.
      float hx = s.x, hy = s.y;
      if (swirl > 0.001f) turn(hx, hy, swirl * 1.3f / (z + 0.3f));
      float x1 = cx + (hx / z) * lens;
      float y1 = cy + (hy / z) * lens;
      if (x1 < -80 || x1 > w + 80 || y1 < -80 || y1 > h + 80) continue;
      // Estela alarga o acorta el rastro; Golpes lo estira mucho un instante.
      float tail = z + 0.04f * trail + smoothEnergy * 0.10f * trail + golpe * 0.6f;
      float tx = s.x, ty = s.y;
      if (swirl > 0.001f) turn(tx, ty, swirl * 1.3f / (tail + 0.3f));
      if (agudos > 0.001f) {
        // Agudos: las cabezas tiemblan y algunas centellean.
        x1 += std::sin(tick * 53.0f + float(idx) * 1.9f) * 1.5f * agudos;
        y1 += std::cos(tick * 47.0f + float(idx) * 2.7f) * 1.5f * agudos;
        if (hashU(uint32_t(idx) * 2654435761u ^ uint32_t(tick * 14.0f) * 0x9e3779b9u) > 0.55f) glints.push_back({x1, y1});
      }
      int lane = int(idx % 3);
      lanes[lane].moveTo(cx + (tx / tail) * lens, cy + (ty / tail) * lens);
      lanes[lane].lineTo(x1, y1);
      heads[lane].push_back({x1, y1});
    }
    for (int lane = 0; lane < 3; lane++) {
      Paint p; p.blend = Blend::plus;
      if (lane == 0) { p.color = {1, 1, 1, 0.9f * boost}; p.strokeWidth = 1.7f; }
      else if (lane == 1) { p.color = {0.749f, 0.894f, 1, 0.55f * boost}; p.strokeWidth = 1.1f; }
      else { p.color = {1, 0.839f, 0.941f, 0.55f * boost}; p.strokeWidth = 1.1f; }
      // Golpes: las estelas se engrosan en cada golpe (×2,2); Graves, ×1,6.
      p.strokeWidth *= 1.0f + golpe * 1.2f + graves * 0.6f;
      p.strokeCap = 1; p.strokeJoin = 1;
      c.path(lanes[lane], p);
      if (!heads[lane].empty()) {
        Paint hp; hp.blend = Blend::plus;
        hp.color = {1, 1, 1, 0.85f * boost};
        c.points(heads[lane], 0.85f * (1.0f + golpe * 0.6f), hp);
      }
    }
    if (!glints.empty()) {
      Paint gp; gp.blend = Blend::plus;
      gp.color = {0.6f, 0.8f, 1, std::min(1.0f, agudos * 0.3f * f.glow)};
      c.points(glints, 6.0f, gp);
      gp.color = {0.85f, 0.93f, 1, std::min(1.0f, agudos)};
      c.points(glints, 2.6f, gp);
    }
    // Graves: el resplandor central crece y se aviva.
    Paint glow = Paint::radial({cx, cy}, std::min(w, h) * 0.45f * (1.0f + graves * 0.25f),
      {{0.549f, 0.745f, 1, std::min(1.0f, 0.28f * boost * (1.0f + graves * 0.8f)
        + agudos * 0.25f * (0.5f + 0.5f * std::sin(tick * 31.0f)))}, {0, 0, 0, 0}});
    glow.blend = Blend::plus;
    c.rect({0, 0, w, h}, glow);
    if (golpe > 0.001f) {
      // Golpes: un gran resplandor local estalla desde el núcleo.
      const float flare = std::min(1.0f, 0.65f * golpe * f.glow);
      const float reach = std::min(w, h) * 0.8f;
      Paint burst = Paint::radial({cx, cy}, reach,
        {{0.75f, 0.88f, 1, flare}, {0.45f, 0.65f, 1, flare * 0.35f}, {0.3f, 0.4f, 1, 0}}, {0, 0.3f, 1.0f});
      burst.blend = Blend::plus;
      c.circle({cx, cy}, reach, burst);
    }
  }
};

class Visual final : public Scene {
  struct Star { float x, y, z0, cycle; };
  std::vector<Star> stars;
  float travel = 0.0f;
  float smoothBass = 0.0f;
  float smoothEnergy = 0.0f;
  // Música estándar: envolventes y golpe corto (valen 0 sin música).
  float bass = 0, body = 0, spark = 0, energy = 0, drive = 0, slowBass = 0, kick = 0, flash = 0;
  // Reloj propio para el temblor de los agudos.
  double clock = 0;
  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }
  static float hashU(uint32_t x) {
    x ^= x >> 16; x *= 0x7feb352dU; x ^= x >> 15; x *= 0x846ca68bU; x ^= x >> 16;
    return float(x & 0xffffffu) / 16777216.0f;
  }
  // Remolino: gira un punto alrededor del centro de la pantalla.
  static void turn(float& x, float& y, float angle) {
    const float cs = std::cos(angle), sn = std::sin(angle);
    const float nx = x * cs - y * sn;
    y = x * sn + y * cs; x = nx;
  }
 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    stars.clear(); stars.reserve(621);
    travel = 0.0f; smoothBass = 0.0f; smoothEnergy = 0.0f;
    bass = body = spark = energy = drive = slowBass = kick = flash = 0; clock = 0;
    for (int i = 0; i < 621; i++) {
      Star s;
      s.x = (rng.unit() - 0.5f) * 2.2f;
      s.y = (rng.unit() - 0.5f) * 2.2f;
      s.z0 = rng.unit() * 2.2f + 0.05f;
      s.cycle = 2.2f + 1.2f;
      stars.push_back(s);
    }
  }
  void update(const Frame& f) override {
    float dt = float(f.delta);
    float targetEnergy = f.music.active ? f.music.energy : 0.0f;
    float targetBass = f.music.active ? f.music.bass : 0.0f;
    smoothBass += (targetBass - smoothBass) * float(1.0 - std::exp(-dt * 6.0));
    smoothEnergy += (targetEnergy - smoothEnergy) * float(1.0 - std::exp(-dt * 5.0));

    // En silencio reposa en un crucero estelar pausado (~0.10f).
    // Con música acelera hacia velocidad hiperlumínica con estelas largas.
    float audioDrive = 0.10f + smoothEnergy * 0.90f + smoothBass * 0.45f;
    if (f.reducedMotion) audioDrive *= 0.4f;
    travel += dt * f.speed * audioDrive * 1.6f;

    // Música estándar: graves, cuerpo, agudos, energía y golpe corto.
    const Music& mu = f.music;
    bass = follow(bass, mu.bass, 22.0f, 4.5f, dt);
    body = follow(body, mu.body, 12.0f, 3.0f, dt);
    spark = follow(spark, mu.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, mu.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, mu.active ? std::pow(std::clamp(mu.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);
    float hit = 0, fl = 0;
    for (const auto& e : mu.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : mu.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : mu.events[3]) fl = std::max(fl, e.strength);
    const float onset = std::clamp((mu.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, mu.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    // Golpes: cada golpe da un tirón hacia delante (vale 0 sin música).
    auto g = glide(f);
    travel += dt * f.speed * std::min(kick * f.intensity, 1.0f) * g.pulso.weight(0) * 1.4f;
    clock += f.delta;
  }
  void render(const Frame& f, Canvas& c) const override {
    auto g = glide(f);
    const float level = f.intensity;
    // Pulso: cada opción mueve algo distinto y sus pesos mezclan las opciones.
    const float golpe = g.pulso.weight(0) * std::min(kick * level, 1.0f);
    const float graves = g.pulso.weight(1) * std::min(bass * level, 1.0f);
    const float agudos = g.pulso.weight(2) * std::min(spark * level, 1.0f);
    const float tick = float(std::fmod(clock, 1000.0));
    float w = f.width, h = f.height;
    float cx = w * 0.5f, cy = h * 0.5f;
    float boost = std::clamp((0.7f + 0.5f * smoothEnergy + 0.4f * smoothBass) * f.intensity, 0.0f, 1.0f);
    // Apertura: 0 es el núcleo original; 1 abre el salto a toda la pantalla.
    // Graves: el campo se abre un 14% más con los graves.
    // Golpes: el núcleo estalla hacia fuera en cada golpe (menos cuanto más
    // abierto está ya el salto, para no sacar las estrellas de la pantalla).
    const float lens = 0.75f * std::exp(g.apertura * 5.7f) * (1.0f + graves * 0.14f)
      * (1.0f + golpe * 3.0f * (1.0f - g.apertura * 0.85f));
    const float swirl = g.remolino;
    const float trail = g.estela;
    Path lanes[3];
    std::vector<Vec2> heads[3];
    for (int i = 0; i < 3; i++) heads[i].reserve(240);
    std::vector<Vec2> glints;
    for (size_t idx = 0; idx < stars.size(); idx++) {
      const Star& s = stars[idx];
      float z = std::fmod(s.z0 - travel, s.cycle);
      if (z < 0.04f) z += s.cycle;
      // Remolino: las estrellas cercanas giran más, así el viaje se enrosca.
      float hx = s.x, hy = s.y;
      if (swirl > 0.001f) turn(hx, hy, swirl * 1.3f / (z + 0.3f));
      float x1 = cx + (hx / z) * lens;
      float y1 = cy + (hy / z) * lens;
      if (x1 < -80 || x1 > w + 80 || y1 < -80 || y1 > h + 80) continue;
      // Estela alarga o acorta el rastro; Golpes lo estira mucho un instante.
      float tail = z + 0.04f * trail + smoothEnergy * 0.10f * trail + golpe * 0.6f;
      float tx = s.x, ty = s.y;
      if (swirl > 0.001f) turn(tx, ty, swirl * 1.3f / (tail + 0.3f));
      if (agudos > 0.001f) {
        // Agudos: las cabezas tiemblan y algunas centellean.
        x1 += std::sin(tick * 53.0f + float(idx) * 1.9f) * 1.5f * agudos;
        y1 += std::cos(tick * 47.0f + float(idx) * 2.7f) * 1.5f * agudos;
        if (hashU(uint32_t(idx) * 2654435761u ^ uint32_t(tick * 14.0f) * 0x9e3779b9u) > 0.55f) glints.push_back({x1, y1});
      }
      int lane = int(idx % 3);
      lanes[lane].moveTo(cx + (tx / tail) * lens, cy + (ty / tail) * lens);
      lanes[lane].lineTo(x1, y1);
      heads[lane].push_back({x1, y1});
    }
    for (int lane = 0; lane < 3; lane++) {
      Paint p; p.blend = Blend::plus;
      if (lane == 0) { p.color = {1, 1, 1, 0.9f * boost}; p.strokeWidth = 1.7f; }
      else if (lane == 1) { p.color = {0.749f, 0.894f, 1, 0.55f * boost}; p.strokeWidth = 1.1f; }
      else { p.color = {1, 0.839f, 0.941f, 0.55f * boost}; p.strokeWidth = 1.1f; }
      // Golpes: las estelas se engrosan en cada golpe (×2,2); Graves, ×1,6.
      p.strokeWidth *= 1.0f + golpe * 1.2f + graves * 0.6f;
      p.strokeCap = 1; p.strokeJoin = 1;
      c.path(lanes[lane], p);
      if (!heads[lane].empty()) {
        Paint hp; hp.blend = Blend::plus;
        hp.color = {1, 1, 1, 0.85f * boost};
        c.points(heads[lane], 0.85f * (1.0f + golpe * 0.6f), hp);
      }
    }
    if (!glints.empty()) {
      Paint gp; gp.blend = Blend::plus;
      gp.color = {0.6f, 0.8f, 1, std::min(1.0f, agudos * 0.3f * f.glow)};
      c.points(glints, 6.0f, gp);
      gp.color = {0.85f, 0.93f, 1, std::min(1.0f, agudos)};
      c.points(glints, 2.6f, gp);
    }
    // Graves: el resplandor central crece y se aviva.
    Paint glow = Paint::radial({cx, cy}, std::min(w, h) * 0.45f * (1.0f + graves * 0.25f),
      {{0.549f, 0.745f, 1, std::min(1.0f, 0.28f * boost * (1.0f + graves * 0.8f)
        + agudos * 0.25f * (0.5f + 0.5f * std::sin(tick * 31.0f)))}, {0, 0, 0, 0}}, {0.0f, 1.0f});
    glow.blend = Blend::plus;
    c.circle({cx, cy}, std::min(w, h) * 0.45f * (1.0f + graves * 0.25f), glow);
    if (golpe > 0.001f) {
      // Golpes: un gran resplandor local estalla desde el núcleo.
      const float flare = std::min(1.0f, 0.65f * golpe * f.glow);
      const float reach = std::min(w, h) * 0.8f;
      Paint burst = Paint::radial({cx, cy}, reach,
        {{0.75f, 0.88f, 1, flare}, {0.45f, 0.65f, 1, flare * 0.35f}, {0.3f, 0.4f, 1, 0}}, {0, 0.3f, 1.0f});
      burst.blend = Blend::plus;
      c.circle({cx, cy}, reach, burst);
    }
  }
};

class Visual final : public Scene {
  struct Part { float r, a0, spd, w; };
  struct Star { float x, y, m; };
  std::vector<Part> parts;
  std::vector<Star> stars;
  float horizonTime = 0.0f;
  float smoothEnergy = 0.0f;
  float smoothBass = 0.0f;
  // Envolventes de la música para Pulso (cero en silencio) y el último golpe.
  float bass = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0;
  double ringAge = 100.0;
  float ringPower = 0.0f;

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }
  static float hashU(uint32_t x) {
    x ^= x >> 16; x *= 0x7feb352dU; x ^= x >> 15; x *= 0x846ca68bU; x ^= x >> 16;
    return float(x & 0xffffffu) / 16777216.0f;
  }
 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    parts.clear(); stars.clear();
    horizonTime = 0.0f; smoothEnergy = 0.0f; smoothBass = 0.0f;
    bass = spark = energy = slowBass = kick = flash = 0.0f;
    ringAge = 100.0; ringPower = 0.0f;
    int np = 620;
    parts.reserve(np);
    for (int i = 0; i < np; i++) {
      Part p;
      float u = rng.unit();
      p.r = 1.55f + std::pow(u, 0.62f) * 3.6f;
      p.a0 = rng.unit() * 6.2831853f;
      // Kepler: la velocidad angular cae con r^1.5 => rotación diferencial real.
      p.spd = 1.0f / (p.r * std::sqrt(p.r));
      p.w = 0.5f + rng.unit() * 2.2f;
      parts.push_back(p);
    }
    stars.reserve(320);
    for (int i = 0; i < 320; i++) {
      Star s; s.x = rng.unit(); s.y = rng.unit(); s.m = rng.unit();
      stars.push_back(s);
    }
  }
  void update(const Frame& f) override {
    float dt = float(f.delta);
    float targetEnergy = f.music.active ? f.music.energy : 0.0f;
    float targetBass = f.music.active ? f.music.bass : 0.0f;
    smoothEnergy += (targetEnergy - smoothEnergy) * float(1.0 - std::exp(-dt * 5.0));
    smoothBass += (targetBass - smoothBass) * float(1.0 - std::exp(-dt * 6.0));

    // En silencio reposa en una rotación gravitatoria lenta (~0.10f).
    // Con música acelera la rotación del disco y la deflexión relativista.
    float audioDrive = 0.10f + smoothEnergy * 0.75f + smoothBass * 0.35f;
    horizonTime += dt * f.speed * audioDrive;

    // Música para Pulso: envolventes y golpes (todo vale cero en silencio).
    const Music& mu = f.music;
    bass = follow(bass, mu.bass, 22.0f, 4.5f, dt);
    spark = follow(spark, mu.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, mu.energy, 6.0f, 1.8f, dt);
    float hit = 0, fl = 0;
    for (const auto& e : mu.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : mu.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : mu.events[3]) fl = std::max(fl, e.strength);
    const float onset = std::clamp((mu.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, mu.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    const bool fresh = hit > kick + 0.2f;
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    ringAge += f.delta;
    if (fresh) { ringAge = 0.0; ringPower = hit; }
  }
  void render(const Frame& f, Canvas& c) const override {
    float w = f.width, h = f.height;
    float t = horizonTime;
    float cx = w * 0.5f, cy = h * 0.5f;
    float rs = std::min(w, h) * 0.13f;
    float yaw = std::sin(t * 0.09f) * 0.22f * (1.0f + smoothEnergy * 0.3f);
    float squash = 0.24f + std::cos(t * 0.07f) * 0.14f;
    float boost = std::clamp((0.85f + 0.35f * smoothEnergy + 0.30f * smoothBass) * f.intensity, 0.0f, 1.0f);
    float spin = t * 0.06f * (f.reducedMotion ? 0.3f : 1.0f);
    auto g = glide(f);
    const float amp = f.intensity;
    // Pulso: sus pesos reparten la reacción; todo vale cero sin música.
    const float punch = std::min(kick * amp, 1.0f) * g.pulso.weight(0);
    const float swell = std::min(bass * amp, 1.0f) * g.pulso.weight(1);
    const float glint = std::min(spark * amp, 1.0f) * g.pulso.weight(2);
    const float fall = g.caida;
    const float haze = g.bruma;
    const uint32_t tick = uint32_t(std::floor(f.time * 12.0));
    // Inclinación del disco: de canto (menos) o casi de frente (más).
    squash *= g.inclinacion;
    Paint bg; bg.color = Color::argb(0xff030308);
    c.rect({0, 0, w, h}, bg);

    // ── Estrellas con deflexión gravitatoria ──
    std::vector<Vec2> field, twinkle;
    field.reserve(stars.size());
    for (const auto& s : stars) {
      float bx = s.x * w, by = s.y * h;
      float dx = bx - cx, dy = by - cy;
      float d = std::sqrt(dx * dx + dy * dy) + 1.0f;
      if (d < rs * 1.25f) continue; // devoradas por la sombra
      float k = 1.0f + (rs * rs * 5.2f) / (d * d);
      field.push_back({cx + dx * k, cy + dy * k});
      // Agudos: algunas estrellas centellean.
      if (glint > 0.0f && hashU(uint32_t(field.size()) * 2654435761u + tick * 40503u) < glint * 0.8f) {
        twinkle.push_back(field.back());
      }
    }
    Paint sp; sp.blend = Blend::plus;
    sp.color = {0.863f, 0.910f, 1, 0.69f * boost};
    c.points(field, 1.1f, sp);
    if (!twinkle.empty()) {
      Paint tw; tw.blend = Blend::plus;
      tw.color = {0.92f, 0.95f, 1.0f, std::clamp(0.9f * glint, 0.0f, 1.0f)};
      c.points(twinkle, 2.5f, tw);
    }

    // Resplandor local de la música alrededor del agujero (nunca a pantalla
    // completa; la sombra lo tapa por dentro): cálido en cada golpe y con los
    // graves, blanco azulado que parpadea con los agudos.
    if (punch > 0.0f || swell > 0.0f || glint > 0.0f) {
      const float auraR = rs * 4.2f * (1.0f + 0.12f * punch + 0.15f * swell);
      const float flicker = 0.55f + 0.45f * std::sin(float(f.time) * 45.0f);
      const float warm = (0.42f * punch + 0.34f * swell) * f.glow;
      const float cool = 0.28f * glint * flicker * f.glow;
      if (warm > 0.0f) {
        Paint aura = Paint::radial({cx, cy}, auraR,
          {{1.0f, 0.82f, 0.4f, std::clamp(warm, 0.0f, 1.0f)},
           {1.0f, 0.56f, 0.29f, std::clamp(warm * 0.6f, 0.0f, 1.0f)},
           {1.0f, 0.56f, 0.29f, 0.0f}}, {0.0f, 0.55f, 1.0f});
        aura.blend = Blend::plus;
        c.circle({cx, cy}, auraR, aura);
      }
      if (cool > 0.0f) {
        Paint shimmer = Paint::radial({cx, cy}, auraR,
          {{0.86f, 0.91f, 1.0f, std::clamp(cool, 0.0f, 1.0f)}, {0.86f, 0.91f, 1.0f, 0.0f}}, {0.0f, 1.0f});
        shimmer.blend = Blend::plus;
        c.circle({cx, cy}, auraR, shimmer);
      }
    }

    const uint32_t ramp[4] = {0xffc9432a, 0xffff8f4a, 0xffffd166, 0xfffff3d0};
    std::vector<Vec2> diskSparks;

    // Disco: cuatro bandas de calor, dos pasadas para el orden.
    for (int pass = 0; pass < 2; pass++) {
      for (int b = 0; b < 4; b++) {
        Path disk;
        for (size_t pi = 0; pi < parts.size(); pi++) {
          const auto& p = parts[pi];
          float heat = 1.0f - (p.r - 1.55f) / 3.6f;
          if (heat < 0.0f) heat = 0.0f; if (heat > 1.0f) heat = 1.0f;
          if (int(heat * 3.999f) != b) continue;
          float rad = p.r * rs;
          // Graves: el disco se hincha despacio.
          if (swell > 0.0f || punch > 0.0f) rad *= 1.0f + 0.14f * swell + 0.12f * punch;
          float a = p.a0 + spin * p.spd + yaw;
          float sa = std::sin(a);
          if ((sa < 0.0f ? 0 : 1) != pass) continue;
          float x = cx + std::cos(a) * rad;
          float y = cy + sa * rad * squash;
          float len = p.w * (2.2f + heat * 6.0f);
          if (swell > 0.0f || punch > 0.0f) len *= 1.0f + 0.6f * swell + 0.8f * punch;
          if (fall > 0.0f) {
            // Caída en espiral: la estela se abre hacia fuera como un brazo.
            const float l2 = len * (1.0f + 0.8f * fall);
            disk.moveTo(x + (std::sin(a) + fall * std::cos(a)) * l2,
                        y + (fall * std::sin(a) - std::cos(a)) * squash * l2);
          } else {
            disk.moveTo(x + std::sin(a) * len, y - std::cos(a) * squash * len);
          }
          disk.lineTo(x, y);
          // Agudos: chispas calientes en el disco.
          if (glint > 0.0f && hashU(uint32_t(pi) * 747796405u + tick * 2891336453u) < glint * 0.35f) {
            diskSparks.push_back({x, y});
          }
        }
        Color cc = Color::argb(ramp[b]);
        Paint dp; dp.blend = Blend::plus;
        // Graves: el disco brilla más con los graves.
        dp.color = {cc.r, cc.g, cc.b, std::min(1.0f, (0.10f + float(b) * 0.14f) * boost + 0.25f * swell + 0.3f * punch)};
        dp.strokeWidth = 0.7f + float(b) * 0.5f;
        dp.strokeCap = 1; dp.strokeJoin = 1;
        c.path(disk, dp);
      }
      if (pass == 0) {
        // ── Anillo fotónico ──
        float ringR = rs * 1.34f;
        Paint rp; rp.blend = Blend::plus;
        for (int i = 3; i >= 1; i--) {
          // Bruma de luz: el halo del anillo (1 = el original).
          rp.color = {1, 0.819f, 0.400f, std::min(1.0f, 0.051f * boost * haze)};
          rp.strokeWidth = rs * 0.16f * float(i);
          c.circle({cx, cy}, ringR * (1.0f + float(i) * 0.07f), rp);
        }
        Paint crisp; crisp.blend = Blend::plus;
        crisp.color = {1, 0.941f, 0.824f, 0.949f * boost};
        crisp.strokeWidth = std::max(1.0f, rs * 0.045f);
        // Golpes: el anillo fotónico destella y da un salto.
        if (punch > 0.0f) crisp.strokeWidth *= 1.0f + 2.0f * punch;
        c.circle({cx, cy}, ringR * (1.0f + 0.15f * punch), crisp);
        // ── Sombra del horizonte ──
        Paint shadow; shadow.color = {0, 0, 0, 1};
        c.circle({cx, cy}, rs, shadow);
      }
    }

    if (!diskSparks.empty()) {
      Paint ds; ds.blend = Blend::plus;
      ds.color = {1.0f, 0.95f, 0.85f, std::clamp(0.85f * glint, 0.0f, 1.0f)};
      c.points(diskSparks, 2.0f, ds);
    }

    // Golpes: una onda gravitatoria sale del anillo con cada golpe.
    const float waveFade = ringPower * float(std::exp(-ringAge * 2.6)) * g.pulso.weight(0);
    if (waveFade > 0.01f) {
      Paint wave; wave.blend = Blend::plus;
      wave.color = {1.0f, 0.78f, 0.45f, std::clamp(0.85f * waveFade * amp, 0.0f, 1.0f)};
      wave.strokeWidth = rs * (0.05f + 0.1f * waveFade);
      c.circle({cx, cy}, rs * 1.34f + float(ringAge) * std::min(w, h) * 0.6f, wave);
    }

    // ── Arco de Einstein: imagen lensada del disco sobre el horizonte ──
    Path arc;
    const int steps = 48;
    for (int i = 0; i <= steps; i++) {
      float a = 3.14159265f * 1.06f + float(i) / float(steps) * 3.14159265f * 0.88f;
      float x = cx + std::cos(a) * rs * 1.16f;
      float y = cy + std::sin(a) * rs * 1.16f;
      if (i == 0) arc.moveTo(x, y); else arc.lineTo(x, y);
    }
    Paint ap; ap.blend = Blend::plus;
    ap.color = {1, 0.722f, 0.361f, std::min(1.0f, 0.502f * boost + 0.45f * punch)};
    ap.strokeWidth = rs * 0.2f; ap.strokeCap = 1; ap.strokeJoin = 1;
    c.path(arc, ap);

    // Resplandor global (Bruma de luz: 0 lo apaga, 1 = el original).
    if (haze > 0.001f) {
      Paint glow = Paint::radial({cx, cy}, rs * 6.5f,
        {{1, 0.667f, 0.314f, std::min(1.0f, 0.141f * boost * haze + (0.14f * punch + 0.1f * swell) * haze)}, {0.627f, 0.314f, 1, std::min(1.0f, 0.051f * boost * haze)}, {0, 0, 0, 0}},
        {0.0f, 0.4f, 1.0f});
      glow.blend = Blend::plus;
      c.rect({0, 0, w, h}, glow);
    }
  }
};

class Visual final : public Scene {
  std::vector<float> ridge;
  float synthTime = 0.0f;
  float smoothBass = 0.0f;
  float smoothEnergy = 0.0f;
  float pulse = 0;
  // Envolventes de la música para Pulso (cero en silencio) y el último golpe.
  float bass = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0;
  double sweepAge = 100.0;
  float sweepPower = 0.0f;
  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }
  static float vhash(int x, int y) {
    uint32_t h = uint32_t(x) * 374761393u + uint32_t(y) * 668265263u;
    h = (h ^ (h >> 13)) * 1274126177u; h ^= h >> 16;
    return float(h & 0xffffu) / 65535.0f;
  }
  static float vnoise(float x, float y) {
    int xi = int(std::floor(x)), yi = int(std::floor(y));
    float xf = x - float(xi), yf = y - float(yi);
    float u = xf * xf * (3.0f - 2.0f * xf), v = yf * yf * (3.0f - 2.0f * yf);
    float a = vhash(xi, yi), b = vhash(xi + 1, yi);
    float c = vhash(xi, yi + 1), d = vhash(xi + 1, yi + 1);
    return a + (b - a) * u + (c - a) * v + (a - b - c + d) * u * v;
  }
 public:
  Visual() {
    reset(0);
  }
  void reset(uint32_t seed) override {
    (void)seed;
    synthTime = 0.0f;
    smoothBass = 0.0f;
    smoothEnergy = 0.0f;
    pulse = 0;
    bass = spark = energy = slowBass = kick = flash = 0.0f;
    sweepAge = 100.0; sweepPower = 0.0f;
    ridge.resize(30);
    for (int i = 0; i < 30; i++)
      ridge[i] = (vnoise(float(i) * 0.4f, 1.0f) * 0.5f + vnoise(float(i) * 0.9f, 7.0f) * 0.5f);
  }
  void update(const Frame& f) override {
    float dt = float(f.delta);
    float targetEnergy = f.music.active ? f.music.energy : 0.0f;
    float targetBass = f.music.active ? f.music.bass : 0.0f;
    smoothEnergy += (targetEnergy - smoothEnergy) * float(1.0 - std::exp(-dt * 5.0));
    smoothBass += (targetBass - smoothBass) * float(1.0 - std::exp(-dt * 6.0));

    // En silencio reposa en un rodaje synthwave suave y relajante (~0.10f).
    // Con música acelera la perspectiva de la rejilla y los destellos del sol.
    float audioDrive = 0.10f + smoothEnergy * 0.78f + smoothBass * 0.35f;
    synthTime += dt * f.speed * audioDrive;

    if (ridge.size() != 30) {
      reset(0);
    }
    if (f.music.active) {
      for (const auto& band : f.music.events)
        for (const auto& e : band) pulse += e.strength;
    }
    pulse *= float(std::exp(-dt * 4.0));

    // Música para Pulso: envolventes y golpes (todo vale cero en silencio).
    const Music& mu = f.music;
    bass = follow(bass, mu.bass, 22.0f, 4.5f, dt);
    spark = follow(spark, mu.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, mu.energy, 6.0f, 1.8f, dt);
    float hit = 0, fl = 0;
    for (const auto& e : mu.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : mu.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : mu.events[3]) fl = std::max(fl, e.strength);
    const float onset = std::clamp((mu.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, mu.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    const bool fresh = hit > kick + 0.2f;
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    sweepAge += f.delta;
    if (fresh) { sweepAge = 0.0; sweepPower = hit; }
  }
  void render(const Frame& f, Canvas& c) const override {
    float w = f.width, h = f.height;
    float t = synthTime;
    float hz = h * 0.56f;
    float glowBoost = std::clamp((0.7f + 0.6f * smoothBass + 0.8f * pulse) * f.intensity, 0.0f, 1.0f);
    auto g = glide(f);
    const float amp = f.intensity;
    // Pulso: sus pesos reparten la reacción; todo vale cero sin música.
    const float punch = std::min(kick * amp, 1.0f) * g.pulso.weight(0);
    const float swell = std::min(bass * amp, 1.0f) * g.pulso.weight(1);
    const float glint = std::min(spark * amp, 1.0f) * g.pulso.weight(2);
    Paint sky = Paint::linear({0, 0}, {0, hz},
      {Color::argb(0xff160034), Color::argb(0xff4a0a6b), Color::argb(0xffff4d78)}, {0, 0.55f, 1.0f});
    c.rect({0, 0, w, hz}, sky);
    // Agudos: estrellas que centellean en el cielo.
    if (glint > 0.0f) {
      const int tick = int(std::fmod(f.time * 9.0, 100000.0));
      std::vector<Vec2> stars;
      for (int i = 0; i < 120; i++) {
        if (vhash(i, tick) > glint * 0.9f) continue;
        stars.push_back({vhash(i, 911) * w, vhash(i, 577) * hz * 0.85f});
      }
      if (!stars.empty()) {
        Paint st; st.blend = Blend::plus;
        st.color = {1.0f, 0.92f, 0.98f, std::clamp(0.95f * glint, 0.0f, 1.0f)};
        c.points(stars, 1.8f, st);
      }
    }
    // Golpes: el sol late con cada golpe.
    float sr = std::min(w, h) * 0.22f * (1.0f + 0.18f * punch + 0.12f * swell);
    float sunCx = w * 0.5f, sunCy = hz - sr * 0.15f;
    // Resplandor local de la música alrededor del sol (nunca a pantalla
    // completa; las montañas lo tapan por abajo): dorado y rosa en cada golpe
    // y con los graves, cian que parpadea con los agudos.
    if (punch > 0.0f || swell > 0.0f || glint > 0.0f) {
      const float auraR = sr * 2.6f;
      const float flicker = 0.55f + 0.45f * std::sin(float(f.time) * 45.0f);
      const float warm = (0.42f * punch + 0.34f * swell) * f.glow;
      const float cool = 0.28f * glint * flicker * f.glow;
      if (warm > 0.0f) {
        Paint aura = Paint::radial({sunCx, sunCy}, auraR,
          {{1.0f, 0.95f, 0.42f, std::clamp(warm, 0.0f, 1.0f)},
           {1.0f, 0.18f, 0.6f, std::clamp(warm * 0.55f, 0.0f, 1.0f)},
           {1.0f, 0.18f, 0.6f, 0.0f}}, {0.0f, 0.5f, 1.0f});
        aura.blend = Blend::plus;
        c.circle({sunCx, sunCy}, auraR, aura);
      }
      if (cool > 0.0f) {
        Paint shimmer = Paint::radial({sunCx, sunCy}, auraR,
          {{0.0f, 1.0f, 0.965f, std::clamp(cool, 0.0f, 1.0f)}, {0.0f, 1.0f, 0.965f, 0.0f}}, {0.0f, 1.0f});
        shimmer.blend = Blend::plus;
        c.circle({sunCx, sunCy}, auraR, shimmer);
      }
    }
    c.save();
    Path sunClip; sunClip.circle({sunCx, sunCy}, sr);
    c.clip(sunClip);
    Paint sun = Paint::linear({0, hz - sr * 1.3f}, {0, hz + 4.0f},
      {Color::argb(0xfffff36b), Color::argb(0xffff8a3d), Color::argb(0xffff2e9a)}, {0, 0.45f, 1.0f});
    c.rect({sunCx - sr, hz - sr * 1.3f, sr * 2.0f, sr * 2.0f}, sun);
    Paint bar; bar.color = Color::argb(0xff160034);
    float lane = sr * 0.14f;
    float off = std::fmod(t * 14.0f, lane);
    for (int i = 0; i < 9; i++) {
      float y = hz - sr * 0.9f + float(i) * lane + off;
      c.rect({sunCx - sr, y, sr * 2.0f, float(i) * 0.55f + 1.5f}, bar);
    }
    c.restore();
    // Montañas (1 = la cordillera original); Graves las levanta despacio.
    const float rise = g.montanas * (1.0f + 0.25f * swell);
    Path mtn; mtn.moveTo(0, hz);
    if (ridge.size() == 30) {
      for (int i = 0; i < 30; i++)
        mtn.lineTo(float(i) / 29.0f * w, rise == 1.0f ? hz - ridge[i] * h * 0.16f : hz - ridge[i] * h * 0.16f * rise);
    }
    mtn.lineTo(w, hz); mtn.close();
    Paint mfill; mfill.color = Color::argb(0xff0d0020);
    c.path(mtn, mfill);
    Paint mstroke; mstroke.color = {1, 0.435f, 0.847f, std::min(1.0f, 0.9f * f.intensity)};
    mstroke.strokeWidth = 1.0f;
    // Graves: el neón de las montañas se engrosa.
    if (swell > 0.0f || punch > 0.0f) mstroke.strokeWidth *= 1.0f + 1.5f * swell + 1.2f * punch;
    c.path(mtn, mstroke);
    Paint floor = Paint::linear({0, hz}, {0, h},
      {Color::argb(0xff12002b), Color::argb(0xff2a004d)});
    c.rect({0, hz, w, h - hz}, floor);
    Path grid;
    const float wave = g.oleaje;
    if (wave <= 0.0f) {
      for (int i = -9; i <= 9; i++) {
        grid.moveTo(w * 0.5f, hz);
        grid.lineTo(w * 0.5f + float(i) * w * 0.34f, h);
      }
      float speed = std::fmod(t * 0.55f, 1.0f);
      for (int i = 0; i < 16; i++) {
        float k = (float(i) + speed) / 16.0f;
        float y = hz + (h - hz) * k * k * 1.02f;
        if (y > h) continue;
        grid.moveTo(0, y); grid.lineTo(w, y);
      }
    } else {
      // Oleaje: el suelo ondula como el mar; las dos familias de líneas
      // siguen la misma ola, plana en el horizonte y alta cerca.
      const float floorH = h - hz;
      auto lift = [&](float x, float y) {
        const float depth = (y - hz) / floorH;
        return y - wave * floorH * 0.12f * depth * std::sin(x / w * 9.4f + t * 2.2f - depth * 5.0f);
      };
      for (int i = -9; i <= 9; i++) {
        const float x1 = w * 0.5f + float(i) * w * 0.34f;
        for (int s = 0; s <= 16; s++) {
          const float q = float(s) / 16.0f;
          const float x = w * 0.5f + (x1 - w * 0.5f) * q, y = hz + floorH * q;
          if (s == 0) grid.moveTo(x, lift(x, y)); else grid.lineTo(x, lift(x, y));
        }
      }
      float speed = std::fmod(t * 0.55f, 1.0f);
      for (int i = 0; i < 16; i++) {
        float k = (float(i) + speed) / 16.0f;
        float y = hz + (h - hz) * k * k * 1.02f;
        if (y > h) continue;
        for (int s = 0; s <= 24; s++) {
          const float x = w * float(s) / 24.0f;
          if (s == 0) grid.moveTo(x, lift(x, y)); else grid.lineTo(x, lift(x, y));
        }
      }
    }
    // Golpes: la rejilla se enciende con cada golpe.
    Paint gp; gp.color = {0, 1, 0.965f, std::min(1.0f, 0.75f * f.intensity + 0.5f * punch)};
    gp.strokeWidth = 1.1f;
    if (punch > 0.0f) gp.strokeWidth *= 1.0f + 1.2f * punch;
    c.path(grid, gp);
    // Golpes y Graves: el horizonte se enciende de rosa sobre el suelo.
    if (punch > 0.0f || swell > 0.0f) {
      const float glowW = w * 0.55f;
      Paint horizonGlow = Paint::radial({0.0f, 0.0f}, glowW,
        {{1.0f, 0.18f, 0.6f, std::clamp((0.38f * punch + 0.28f * swell) * f.glow, 0.0f, 1.0f)},
         {1.0f, 0.18f, 0.6f, std::clamp((0.12f * punch + 0.09f * swell) * f.glow, 0.0f, 1.0f)},
         {1.0f, 0.18f, 0.6f, 0.0f}}, {0.0f, 0.5f, 1.0f});
      horizonGlow.blend = Blend::plus;
      c.save();
      c.translate(w * 0.5f, hz);
      c.scale(1.0f, std::min(0.6f, (h - hz) / glowW));
      c.circle({0.0f, 0.0f}, glowW, horizonGlow);
      c.restore();
    }
    // Golpes: una línea de luz barre el suelo hacia el espectador.
    const float sweepFade = sweepPower * float(std::exp(-sweepAge * 2.0)) * g.pulso.weight(0);
    if (sweepFade > 0.01f) {
      const float q = std::min(1.0f, float(sweepAge) * 1.6f);
      const float y = hz + (h - hz) * q * q;
      Path line; line.moveTo(0, y); line.lineTo(w, y);
      Paint sweepGlow; sweepGlow.blend = Blend::plus;
      sweepGlow.color = {1.0f, 0.3f, 0.7f, std::clamp(0.35f * sweepFade * amp, 0.0f, 1.0f)};
      sweepGlow.strokeWidth = 4.0f + 10.0f * sweepFade;
      c.path(line, sweepGlow);
      Paint sweep; sweep.blend = Blend::plus;
      sweep.color = {1.0f, 0.85f, 0.97f, std::clamp(0.95f * sweepFade * amp, 0.0f, 1.0f)};
      sweep.strokeWidth = 2.0f + 3.0f * sweepFade;
      c.path(line, sweep);
    }
    // Bruma del horizonte (1 = la franja original); Graves la ensancha.
    const float band = 26.0f * g.bruma * (1.0f + 0.6f * swell + 0.8f * punch);
    if (band > 0.01f) {
      Paint hg = Paint::linear({0, hz - band}, {0, hz + band},
        {{1, 0.18f, 0.604f, 0}, {1, 0.47f, 0.784f, std::min(1.0f, 0.35f * glowBoost * std::min(g.bruma, 1.6f) + (0.35f * punch + 0.2f * swell) * std::min(g.bruma, 1.6f))}, {0, 1, 0.965f, 0}}, {0, 0.5f, 1.0f});
      hg.blend = Blend::plus;
      c.rect({0, hz - band, w, band * 2.0f}, hg);
    }
  }
};

class Visual final : public Scene {
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  // Reloj en doble precisión: la escena sin música es idéntica a 30 y 60 FPS.
  double clock = 0, sinceSwitch = 0;
  int patternA = 0, patternB = 0, beats = 0;
  float blend = 1, bulge = 0, bulgeVel = 0;

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

  void next() {
    patternA = patternB;
    patternB = (patternB + 1) % 4;
    blend = 0;
    sinceSwitch = 0;
  }

 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    clock = rng.unit() * 20.0;
    sinceSwitch = 0;
    patternA = patternB = int(rng.unit() * 4.0f) % 4;
    beats = 0;
    blend = 1;
    bulge = bulgeVel = 0;
  }

  void update(const Frame& f) override {
    float dt = float(f.delta);
    const Music& m = f.music;
    bass = follow(bass, m.bass, 22.0f, 4.5f, dt);
    body = follow(body, m.body, 12.0f, 3.0f, dt);
    spark = follow(spark, m.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, m.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, m.active ? std::pow(std::clamp(m.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : m.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : m.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : m.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((m.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, m.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    if (hit > kick + 0.2f) {
      beats++;
      bulgeVel += 2.4f * hit;
      if (beats % 8 == 0) next();
    }
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    bulgeVel += (-bulge * 30.0f - bulgeVel * 6.0f) * dt;
    bulge += bulgeVel * dt;
    blend = std::min(1.0f, blend + dt * 1.2f);
    sinceSwitch += f.delta;
    if (!m.active && sinceSwitch > 10.0) next();
    clock += f.delta * f.speed * (0.6 + 1.2 * drive);
  }

  void render(const Frame& f, Canvas& c) const override {
    float amp = f.intensity;
    float e = blend * blend * (3.0f - 2.0f * blend);
    std::vector<float> u;
    u.reserve(20);
    u.insert(u.end(), {float(std::fmod(clock, 1000.0)), bass * amp, kick * amp, energy});
    u.insert(u.end(), {float(patternA), float(patternB), e, std::max(-0.3f, bulge) * amp});
    for (int i = 0; i < 4; i++) u.insert(u.end(), {f.colors[i].r, f.colors[i].g, f.colors[i].b});
    c.material("op_art", {0, 0, f.width, f.height}, u);
  }
};

shaderSources.op_art:
#version 460 core
#include <flutter/runtime_effect.glsl>
uniform vec2 uSize;
uniform vec4 uA;   // reloj, graves, golpe, energía
uniform vec4 uB;   // patrón actual, patrón siguiente, fundido, burbuja
uniform vec3 uC0;
uniform vec3 uC1;
uniform vec3 uC2;
uniform vec3 uC3;
out vec4 fragColor;

const float PI = 3.14159265;

// Franja suavizada: v cuenta franjas y dv es cuánto cambia v por píxel.
float stripe(float v, float dv) {
  float s = sin(v * PI);
  float aa = max(dv * PI * 1.2, 0.001);
  return smoothstep(-aa, aa, s);
}

// Devuelve blanco (x) y máscara roja (y) del patrón id.
vec2 pattern(float id, vec2 p, float px) {
  float t = uA.x;
  float warp = 0.6 + 0.8 * uA.y;
  if (id < 0.5) {
    // Franjas que ondulan, estilo Bridget Riley; una de cada cinco es roja.
    float k = 16.0;
    float v = (p.y + 0.06 * warp * sin(p.x * 5.0 + t * 1.3) + 0.03 * sin(p.x * 11.0 - t * 0.7)) * k;
    float white = stripe(v, k * px);
    float red = step(4.0, mod(floor(v), 5.0)) * (1.0 - white);
    return vec2(white, red);
  }
  if (id < 1.5) {
    // Anillos con una burbuja que parece salir de la pantalla.
    vec2 bc = vec2(0.22 * sin(t * 0.4), 0.3 * cos(t * 0.33));
    vec2 d = p - bc;
    float rb = 0.32 + 0.12 * uB.w;
    float l = length(d);
    float swell = l < rb ? sqrt(max(rb * rb - l * l, 0.0)) * (0.8 + 0.6 * warp) : 0.0;
    float r = length(p) - swell * 0.35;
    float k = 22.0;
    float v = r * k - t * 2.0;
    float white = stripe(v, k * px * (1.0 + swell * 2.0));
    float red = smoothstep(rb, rb * 0.6, l) * (1.0 - white) * 0.9;
    return vec2(white, red);
  }
  if (id < 2.5) {
    // Muaré: dos tramas de anillos con centros que se separan y se cruzan.
    vec2 o = vec2(0.12 + 0.05 * warp, 0.0) * vec2(cos(t * 0.3), sin(t * 0.3));
    float k = 30.0;
    float a = stripe(length(p - o) * k - t, k * px);
    float b = stripe(length(p + o) * k - t, k * px);
    float white = a * b;
    float red = (1.0 - a) * b;
    return vec2(white, red);
  }
  // Damero comprimido hacia una costura que ondula.
  float seam = 0.25 * sin(t * 0.5) + 0.08 * warp * sin(p.y * 4.0 + t);
  float dx = p.x - seam;
  float sx = sign(dx) * pow(abs(dx) + 0.0001, 0.55) * 1.8;
  float k = 9.0;
  float cx = stripe(sx * k, k * px * 2.5 / (pow(abs(dx) + 0.02, 0.45)));
  float cy = stripe(p.y * k + t * 0.4, k * px);
  float white = abs(cx - cy);
  float red = (1.0 - white) * smoothstep(0.35, 0.0, abs(dx)) * 0.85;
  return vec2(white, red);
}

void main() {
  vec2 frag = FlutterFragCoord().xy;
  float scale = min(uSize.x, uSize.y);
  vec2 p = (frag - 0.5 * uSize) / scale;
  float px = 1.0 / scale;
  vec2 v = pattern(uB.y, p, px);
  if (uB.z < 0.999) v = mix(pattern(uB.x, p, px), v, uB.z);
  vec3 col = mix(uC0, uC2, v.x);
  col = mix(col, uC1, clamp(v.y, 0.0, 1.0));
  // El golpe enciende el rojo y oscurece el blanco un instante.
  col = mix(col, col * vec3(1.0, 0.75, 0.75), 0.4 * uA.z);
  col *= 1.0 - 0.25 * smoothstep(0.6, 1.5, length(p * vec2(0.9, 0.65)));
  fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

