class Visual final : public Scene {
  static constexpr int kShapes = 48;
  // Formas: círculo, triángulo, línea, arco, damero y puntos.
  struct Shape { int type; float x, y, size, rot, spin; int colA, colB; double birth; float life, seed; };
  float bass = 0, body = 0, spark = 0, slowBass = 0;
  float kick = 0, flash = 0;
  // Relojes en doble precisión: sin música es idéntico a 30 y 60 FPS.
  double clock = 0, sinceIdle = 0;
  std::array<float, 3> credit{};
  std::array<Shape, kShapes> shapes{};
  int next = 0;
  uint32_t spawns = 0, idleCount = 0;

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }
  static float hashU(uint32_t x) {
    x ^= x >> 16; x *= 0x7feb352dU; x ^= x >> 15; x *= 0x846ca68bU; x ^= x >> 16;
    return float(x & 0xffffffu) / 16777216.0f;
  }
  static int capacity(float detail) { return std::clamp(int(std::lround(16.0f + 16.0f * detail)), 16, kShapes); }
  static float easeOutBack(float x) {
    const float c1 = 1.70158f, c3 = c1 + 1.0f;
    const float e = x - 1.0f;
    return 1.0f + c3 * e * e * e + c1 * e * e;
  }

  // Nace una forma: los graves dan círculos, los medios triángulos y arcos,
  // los agudos líneas y puntos.
  void spawn(int band, int vocab, double carry, int limit) {
    const uint32_t k = spawns++;
    const float h1 = hashU(k * 2654435761u + 1u), h2 = hashU(k * 2246822519u + 2u);
    const float h3 = hashU(k * 3266489917u + 3u), h4 = hashU(k * 668265263u + 4u);
    const float h5 = hashU(k * 374761393u + 5u), h6 = hashU(k * 1274126177u + 6u);
    int type;
    if (vocab == 1) {
      type = band == 0 ? 0 : (band == 1 ? 3 : 5);
      if (h4 < 0.3f) type = 0;
    } else if (vocab == 2) {
      type = band == 0 ? 1 : (band == 1 ? 4 : 2);
      if (h4 < 0.25f) type = 2;
    } else {
      const int byBand[3][2] = {{0, 0}, {1, 3}, {2, 5}};
      type = byBand[band][h4 < 0.5f ? 0 : 1];
      if (h5 < 0.12f) type = 4;
    }
    const int slot = next % limit;
    Shape& s = shapes[size_t(slot)];
    s.type = type;
    s.x = 0.1f + 0.8f * h1;
    s.y = 0.08f + 0.84f * h2;
    s.size = type == 0 ? 0.05f + 0.12f * h3 : (type == 2 ? 0.25f + 0.35f * h3 : 0.04f + 0.08f * h3);
    s.rot = h5 * 6.2831853f;
    s.spin = (h6 - 0.5f) * 0.6f;
    s.colA = 1 + int(h3 * 3.0f) % 3;
    s.colB = 1 + s.colA % 3;
    s.birth = clock - carry;
    s.life = 5.0f + 4.0f * h6;
    s.seed = h1;
    next = (slot + 1) % limit;
  }

 public:
  void reset(uint32_t seed) override {
    bass = body = spark = slowBass = kick = flash = 0;
    clock = 0;
    sinceIdle = 0;
    credit.fill(0.0f);
    for (auto& s : shapes) s = Shape{0, 0.5f, 0.5f, 0.0f, 0.0f, 0.0f, 1, 2, -1000.0, 0.0f, 0.0f};
    next = 0;
    spawns = seed * 11u;
    idleCount = 0;
    // El cuadro empieza ya pintado.
    for (int i = 0; i < 12; i++) spawn(i % 3, 0, 0.45 * double(12 - i), kShapes);
  }

  void update(const Frame& f) override {
    auto m = modifiers(f);
    const float dt = float(f.delta);
    const Music& mu = f.music;
    bass = follow(bass, mu.bass, 22.0f, 4.5f, dt);
    body = follow(body, mu.body, 12.0f, 3.0f, dt);
    spark = follow(spark, mu.spark, 30.0f, 7.0f, dt);
    float hit = 0, fl = 0;
    for (const auto& e : mu.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : mu.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : mu.events[3]) fl = std::max(fl, e.strength);
    const float onset = std::clamp((mu.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, mu.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    const bool fresh = hit > kick + 0.2f;
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    const double step = f.delta * f.speed;
    clock += step;
    const int limit = capacity(f.detail);
    const float amp = f.intensity;
    // Instrumentos: cada banda de la música pinta su tipo de forma.
    if (m.pulso == 0 && mu.active) {
      credit[0] += bass * amp * dt * 2.5f;
      credit[1] += body * amp * dt * 2.5f;
      credit[2] += spark * amp * dt * 3.5f;
      for (int b = 0; b < 3; b++) {
        while (credit[size_t(b)] >= 1.0f) {
          credit[size_t(b)] -= 1.0f;
          spawn(b, m.figuras, 0.0, limit);
        }
      }
    }
    // Golpes: cada golpe lanza tres formas a la vez.
    if (m.pulso == 1 && fresh) {
      for (int b = 0; b < 3; b++) spawn(b, m.figuras, 0.0, limit);
    }
    // A su ritmo el cuadro sigue pintándose.
    const double period = mu.active ? 0.9 : 0.45;
    sinceIdle += step;
    while (sinceIdle >= period) {
      sinceIdle -= period;
      spawn(int(idleCount++ % 3u), m.figuras, sinceIdle, limit);
    }
  }

  void render(const Frame& f, Canvas& c) const override {
    auto g = glide(f);
    const auto& pal = f.colors;
    const float amp = f.intensity;
    const float W = f.width, H = f.height;
    const float side = std::min(W, H);
    const float px = side / 400.0f;
    const float night = std::clamp(g.noche, 0.0f, 1.0f);
    const float halo = std::clamp(g.halos, 0.0f, 1.0f);
    const Color& paper = pal[0];
    const Color dark{pal[3].r * 0.12f + 0.02f, pal[3].g * 0.12f + 0.02f, pal[3].b * 0.12f + 0.03f, 1.0f};
    auto mixc = [](const Color& a, const Color& b, float t) {
      return Color{a.r + (b.r - a.r) * t, a.g + (b.g - a.g) * t, a.b + (b.b - a.b) * t, 1.0f};
    };
    const Color bg = mixc(paper, dark, night);
    // La tinta es casi negra sobre crema y crema sobre negro.
    const Color ink = mixc(dark, paper, night);
    c.rect({0, 0, W, H}, Paint::radial({W * 0.45f, H * 0.42f}, std::max(W, H) * 0.8f,
                                       {bg, mixc(bg, Color{0, 0, 0, 1}, 0.18f + 0.12f * halo)}));
    const float wGolpes = g.pulso.weight(1), wGraves = g.pulso.weight(2);
    const float throb = std::min(bass * amp, 1.0f) * (0.35f + 0.65f * wGraves);
    const Blend shapeBlend = night > 0.5f ? Blend::screen : Blend::sourceOver;
    // Las grandes líneas que cruzan el cuadro.
    for (int i = 0; i < 3; i++) {
      const float a = 0.35f + 1.05f * float(i) + 0.05f * float(std::sin(clock * 0.1 + double(i)));
      const float ox = W * (0.35f + 0.15f * float(i)), oy = H * (0.4f + 0.12f * float(i));
      const float L = std::max(W, H) * 1.2f;
      Path line;
      line.moveTo(ox - L * std::cos(a), oy - L * std::sin(a)).lineTo(ox + L * std::cos(a), oy + L * std::sin(a));
      Paint lp;
      lp.strokeWidth = (1.2f + 1.3f * float(i % 2)) * px;
      lp.color = ink.opacity(0.75f);
      c.path(line, lp);
    }
    // El gran círculo, corazón del cuadro, late con los graves.
    {
      const Vec2 sun{W * 0.3f, H * 0.25f};
      const float r = side * 0.17f * (1.0f + 0.15f * throb);
      if (halo > 0.01f) {
        Paint hp = Paint::radial(sun, r * 1.9f, {pal[1].opacity(std::clamp(0.45f * halo * f.glow, 0.0f, 1.0f)), pal[1].opacity(0.0f)});
        c.circle(sun, r * 1.9f, hp);
      }
      Paint fill;
      fill.color = mixc(dark, pal[3], 0.25f + 0.5f * night);
      c.circle(sun, r, fill);
      Path ring;
      ring.circle(sun, r * 0.72f);
      Paint rp;
      rp.strokeWidth = r * 0.12f;
      rp.color = pal[2];
      c.path(ring, rp);
      Paint core;
      core.color = pal[1];
      c.circle(sun, r * 0.3f * (1.0f + 0.2f * kick * amp * wGolpes), core);
    }
    const int limit = capacity(f.detail);
    const float wFlotar = g.danza.weight(0), wGirar = g.danza.weight(1), wSaltar = g.danza.weight(2);
    // De la más vieja a la más nueva, para que las nuevas queden encima.
    for (int n = 0; n < limit; n++) {
      const Shape& s = shapes[size_t((next + n) % limit)];
      const float age = float(clock - s.birth);
      if (age < 0.0f || age > s.life) continue;
      const float grow = easeOutBack(std::clamp(age / 0.35f, 0.0f, 1.0f));
      const float leave = std::clamp((s.life - age) / 0.8f, 0.0f, 1.0f);
      float k = grow * leave;
      if (k <= 0.01f) continue;
      if (s.type == 0) k *= 1.0f + 0.18f * throb;
      // Danza: flotar, girar alrededor del centro o saltar con los golpes.
      float x = s.x, y = s.y;
      x += wFlotar * 0.015f * std::sin(age * 0.7f + s.seed * 20.0f);
      y += wFlotar * 0.02f * std::sin(age * 0.5f + s.seed * 13.0f);
      if (wGirar > 0.001f) {
        const float a = wGirar * 0.22f * age * (s.seed < 0.5f ? 1.0f : -1.0f);
        const float dx = x - 0.5f, dy = (y - 0.5f) * H / W;
        x = 0.5f + dx * std::cos(a) - dy * std::sin(a);
        y = 0.5f + (dx * std::sin(a) + dy * std::cos(a)) * W / H;
      }
      y -= wSaltar * kick * amp * 0.05f * (0.5f + s.seed);
      const float rot = s.rot + s.spin * age * (1.0f + 3.0f * wGirar);
      const Vec2 at{x * W, y * H};
      const float r = s.size * side * k;
      const Color& ca = pal[size_t(s.colA)];
      const Color& cb = pal[size_t(s.colB)];
      Paint outline;
      outline.strokeWidth = 1.5f * px;
      outline.color = ink.opacity(0.85f * leave);
      switch (s.type) {
        case 0: {
          if (halo > 0.01f) {
            Paint hp = Paint::radial(at, r * 1.6f, {ca.opacity(std::clamp(0.35f * halo * f.glow * leave, 0.0f, 1.0f)), ca.opacity(0.0f)});
            c.circle(at, r * 1.6f, hp);
          }
          Paint fa;
          fa.blend = shapeBlend;
          fa.color = ca.opacity(0.92f * leave);
          c.circle(at, r, fa);
          Paint fb;
          fb.blend = shapeBlend;
          fb.color = cb.opacity(0.92f * leave);
          c.circle(at, r * 0.55f, fb);
          Path o;
          o.circle(at, r);
          c.path(o, outline);
          Paint dot;
          dot.color = ink.opacity(leave);
          c.circle(at, r * 0.12f, dot);
          break;
        }
        case 1: {
          Path tri;
          const float a0 = rot, a1 = rot + 2.2f, a2 = rot + 4.0f;
          tri.moveTo(at.x + r * 1.6f * std::cos(a0), at.y + r * 1.6f * std::sin(a0))
              .lineTo(at.x + r * std::cos(a1), at.y + r * std::sin(a1))
              .lineTo(at.x + r * std::cos(a2), at.y + r * std::sin(a2))
              .close();
          Paint fa;
          fa.blend = shapeBlend;
          fa.color = ca.opacity(0.9f * leave);
          c.path(tri, fa);
          c.path(tri, outline);
          break;
        }
        case 2: {
          const float draw = std::clamp(age / 0.5f, 0.0f, 1.0f);
          const float L = s.size * side * draw * leave;
          Path line;
          line.moveTo(at.x - L * std::cos(rot), at.y - L * std::sin(rot)).lineTo(at.x + L * std::cos(rot), at.y + L * std::sin(rot));
          Paint lp;
          lp.strokeWidth = (1.5f + 3.0f * s.seed) * px;
          lp.color = ink.opacity(0.9f * leave);
          c.path(line, lp);
          break;
        }
        case 3: {
          Path arc;
          for (int i = 0; i <= 18; i++) {
            const float a = rot + 3.14159265f * float(i) / 18.0f;
            const float ax = at.x + r * 1.4f * std::cos(a), ay = at.y + r * 1.4f * std::sin(a);
            if (i == 0) arc.moveTo(ax, ay); else arc.lineTo(ax, ay);
          }
          Paint ap;
          ap.strokeWidth = 4.0f * px;
          ap.strokeCap = 1;
          ap.color = ca.opacity(0.95f * leave);
          c.path(arc, ap);
          break;
        }
        case 4: {
          c.save();
          c.translate(at.x, at.y);
          c.rotate(rot);
          const float cell = r * 0.5f;
          Path light, darkCells;
          for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
              Rect rc{(float(i) - 1.5f) * cell, (float(j) - 1.5f) * cell, cell, cell};
              if ((i + j) % 2 == 0) light.rect(rc); else darkCells.rect(rc);
            }
          }
          Paint pl;
          pl.color = ca.opacity(0.9f * leave);
          c.path(light, pl);
          Paint pd;
          pd.color = ink.opacity(0.9f * leave);
          c.path(darkCells, pd);
          c.restore();
          break;
        }
        default: {
          for (int i = 0; i < 5; i++) {
            const float d = (float(i) - 2.0f) * r * 0.5f;
            Paint dp;
            dp.blend = shapeBlend;
            dp.color = (i % 2 == 0 ? ca : ink).opacity(0.9f * leave);
            c.circle({at.x + d * std::cos(rot), at.y + d * std::sin(rot)}, r * 0.18f, dp);
          }
          break;
        }
      }
    }
    if (flash > 0.01f) {
      Paint fl;
      fl.blend = Blend::screen;
      fl.color = pal[2].opacity(std::clamp(flash * 0.08f * amp, 0.0f, 1.0f));
      c.rect({0, 0, W, H}, fl);
    }
  }
};

class Visual final : public Scene {
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  // Relojes en doble precisión: la escena sin música es idéntica a 30 y 60 FPS.
  double clock = 0, flips = 0, waveAge = 100;
  int waves = 0;

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    clock = rng.unit() * 30.0;
    flips = rng.unit() * 10.0;
    waveAge = 100;
    waves = 0;
  }

  void update(const Frame& f) override {
    auto m = modifiers(f);
    float dt = float(f.delta);
    const Music& mu = f.music;
    bass = follow(bass, mu.bass, 22.0f, 4.5f, dt);
    body = follow(body, mu.body, 12.0f, 3.0f, dt);
    spark = follow(spark, mu.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, mu.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, mu.active ? std::pow(std::clamp(mu.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : mu.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : mu.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : mu.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((mu.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, mu.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    waveAge += f.delta;
    // Una ola nueva sólo cuando la anterior ya cruzó la pantalla.
    if (hit > kick + 0.2f && m.ola && waveAge > 1.2) {
      waves++;
      waveAge = 0;
    }
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    clock += f.delta * f.speed * (0.8 + 1.4 * drive);
    flips += f.delta * f.speed * m.giros * 0.18;
  }

  void render(const Frame& f, Canvas& c) const override {
    auto m = modifiers(f);
    float amp = f.intensity;
    std::vector<float> u;
    u.reserve(24);
    u.insert(u.end(), {float(std::fmod(clock, 1000.0)), bass * amp, kick * amp, energy});
    u.insert(u.end(), {float(m.losetas), m.grosor, float(std::fmod(flips, 512.0)), m.luz ? 1.0f : 0.0f});
    u.insert(u.end(), {float(waves % 64), float(std::min(waveAge, 10.0)) * 1.6f, f.glow, flash * amp});
    for (int i = 0; i < 4; i++) u.insert(u.end(), {f.colors[i].r, f.colors[i].g, f.colors[i].b});
    c.material("truchet", {0, 0, f.width, f.height}, u);
  }
};

shaderSources.truchet:
#version 460 core
#include <flutter/runtime_effect.glsl>
uniform vec2 uSize;
uniform vec4 uA;   // reloj, graves, golpe, energía
uniform vec4 uB;   // losetas, grosor, giros acumulados, luz
uniform vec4 uW;   // olas, radio de la última ola, glow, destello
uniform vec3 uC0;
uniform vec3 uC1;
uniform vec3 uC2;
uniform vec3 uC3;
out vec4 fragColor;

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

void main() {
  vec2 frag = FlutterFragCoord().xy;
  float scale = min(uSize.x, uSize.y);
  vec2 p = (frag - 0.5 * uSize) / scale;
  float n = uB.x;
  vec2 g = p * n;
  vec2 id = floor(g);
  vec2 f = fract(g) - 0.5;
  // Giros propios: cada loseta gira un cuarto de vuelta cuando su reloj cruza
  // un entero; el giro se anima durante el primer cuarto del intervalo.
  float h = hash12(id);
  float own = uB.z * (0.6 + 0.8 * h) + h * 7.0;
  float ownTurns = floor(own) - 1.0 + smoothstep(0.0, 0.25, fract(own));
  // Olas de los golpes: la última todavía puede no haber llegado.
  vec2 center = (id + 0.5) / n;
  float d = length(center);
  float arrived = uW.y - d;
  float waveTurns = uW.x - 1.0 + (arrived < 0.0 ? 0.0 : smoothstep(0.0, 0.18, arrived));
  float angle = 1.5707963 * (floor(h * 2.0) + ownTurns + waveTurns);
  float cs = cos(angle);
  float sn = sin(angle);
  vec2 r = vec2(cs * f.x - sn * f.y, sn * f.x + cs * f.y);
  // Dos arcos con centro en esquinas opuestas.
  float d1 = abs(length(r - vec2(0.5, 0.5)) - 0.5);
  float d2 = abs(length(r + vec2(0.5, 0.5)) - 0.5);
  float dist = min(d1, d2);
  float px = n / scale;
  float w = 0.07 * uB.y * (1.0 + 0.35 * uA.y);
  float core = 1.0 - smoothstep(w * 0.45 - px, w * 0.45 + px, dist);
  float tubeEdge = 1.0 - smoothstep(w - px, w + px, dist);
  float glow = exp(-dist / (0.1 + 0.05 * uA.y));
  // Color por zonas que se desplazan despacio.
  float zone = 0.5 + 0.5 * sin(p.x * 3.1 + p.y * 2.3 + uA.x * 0.25);
  vec3 neon = mix(uC1, uC2, smoothstep(0.35, 0.65, zone));
  // Luz que corre en ondas desde el centro.
  float run = 1.0;
  if (uB.w > 0.5) run = 0.45 + 0.75 * pow(0.5 + 0.5 * sin(length(p) * 14.0 - uA.x * 4.0), 3.0);
  // La ola del golpe ilumina las losetas que gira.
  float waveLight = exp(-abs(d - uW.y) * 10.0) * step(uW.y, 3.0);
  vec3 col = uC0 + neon * 0.025;
  col += neon * glow * 0.22 * (run + waveLight) * uW.z;
  col = mix(col, neon * (0.55 + 0.45 * run + waveLight), tubeEdge);
  col = mix(col, mix(neon, uC3, 0.55) * (0.8 + 0.6 * run + 0.6 * uA.z), core);
  col += neon * uW.w * 0.05;
  col *= 1.0 - 0.3 * smoothstep(0.7, 1.5, length(p * vec2(0.9, 0.65)));
  float peak = max(col.r, max(col.g, col.b));
  if (peak > 0.85) {
    float e = (peak - 0.85) / 0.15;
    col *= (0.85 + 0.15 * e / (1.0 + e)) / peak;
  }
  col += (hash12(frag) - 0.5) / 255.0;
  fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

visuals.nativeSource:
class Visual final : public Scene {
  static constexpr int kMaxCols = 34;
  static constexpr int kMaxRows = 80;
  static constexpr int kMaxCells = kMaxCols * kMaxRows;
  enum Phase { kGen, kFlood, kPath, kHold, kFade };
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  // Relojes en doble precisión: la escena sin música es idéntica a 30 y 60 FPS.
  double phaseTime = 0, genSteps = 0;
  int64_t stepsDone = 0;
  int cols = 0, rows = 0, phase = kGen, maxDist = 1;
  float cellPx = 1, ox = 0, oy = 0;
  Random rng{1};
  // Por celda: pasillo a la derecha (1) y abajo (2), visitada, distancia, padre.
  std::vector<uint8_t> carved, visited;
  std::vector<int16_t> dist, parent;
  std::vector<int> stack, queue, path;

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

  void clearMaze() {
    std::fill(carved.begin(), carved.end(), 0);
    std::fill(visited.begin(), visited.end(), 0);
    std::fill(dist.begin(), dist.end(), -1);
    stack.clear();
    path.clear();
    int start = std::min(int(rng.unit() * float(cols * rows)), cols * rows - 1);
    visited[size_t(start)] = 1;
    stack.push_back(start);
    phase = kGen;
    phaseTime = 0;
    genSteps = 0;
    stepsDone = 0;
  }

  bool open(int a, int b) const {
    int lo = std::min(a, b), hi = std::max(a, b);
    if (hi - lo == 1) return (carved[size_t(lo)] & 1) != 0;
    return (carved[size_t(lo)] & 2) != 0;
  }

  // [straight]: 0 gira siempre que puede, 0.5 elige al azar, 1 sigue recto.
  void genStep(float straight) {
    if (stack.empty()) return;
    int cur = stack.back();
    int x = cur % cols, y = cur / cols;
    int options[4];
    int count = 0;
    if (x + 1 < cols && !visited[size_t(cur + 1)]) options[count++] = cur + 1;
    if (x > 0 && !visited[size_t(cur - 1)]) options[count++] = cur - 1;
    if (y + 1 < rows && !visited[size_t(cur + cols)]) options[count++] = cur + cols;
    if (y > 0 && !visited[size_t(cur - cols)]) options[count++] = cur - cols;
    if (count == 0) {
      stack.pop_back();
      return;
    }
    int choice = std::min(int(rng.unit() * float(count)), count - 1);
    if (stack.size() > 1 && straight != 0.5f) {
      // La celda de enfrente sólo cuenta si es una opción (no cruza el borde).
      const int ahead = 2 * cur - stack[stack.size() - 2];
      int aheadAt = -1;
      for (int k = 0; k < count; k++) if (options[k] == ahead) aheadAt = k;
      // Recto nunca es del todo recto: así salen pasillos largos y no una espiral.
      const float pull = straight > 0.5f ? (straight - 0.5f) * 1.7f : (0.5f - straight) * 2.0f;
      if (aheadAt >= 0 && rng.unit() < pull) {
        if (straight > 0.5f) choice = aheadAt;
        else if (choice == aheadAt && count > 1) choice = (choice + 1) % count;
      }
    }
    int next = options[choice];
    int lo = std::min(cur, next);
    carved[size_t(lo)] |= (std::abs(next - cur) == 1) ? 1 : 2;
    visited[size_t(next)] = 1;
    stack.push_back(next);
  }

  void solve() {
    // Búsqueda en anchura desde la entrada (arriba a la izquierda).
    std::fill(dist.begin(), dist.end(), -1);
    queue.clear();
    queue.push_back(0);
    dist[0] = 0;
    parent[0] = -1;
    size_t head = 0;
    maxDist = 1;
    while (head < queue.size()) {
      int cur = queue[head++];
      int x = cur % cols, y = cur / cols;
      int nb[4] = {x + 1 < cols ? cur + 1 : -1, x > 0 ? cur - 1 : -1, y + 1 < rows ? cur + cols : -1, y > 0 ? cur - cols : -1};
      for (int k = 0; k < 4; k++) {
        int b = nb[k];
        if (b < 0 || dist[size_t(b)] >= 0 || !open(cur, b)) continue;
        dist[size_t(b)] = int16_t(dist[size_t(cur)] + 1);
        parent[size_t(b)] = int16_t(cur);
        maxDist = std::max(maxDist, int(dist[size_t(b)]));
        queue.push_back(b);
      }
    }
    path.clear();
    for (int c = cols * rows - 1; c >= 0; c = parent[size_t(c)]) {
      path.push_back(c);
      if (c == 0) break;
    }
    std::reverse(path.begin(), path.end());
  }

  Vec2 center(int cell) const {
    return {ox + (float(cell % cols) + 0.5f) * cellPx, oy + (float(cell / cols) + 0.5f) * cellPx};
  }

 public:
  void reset(uint32_t seed) override {
    rng = Random(seed);
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    cols = rows = 0;
    carved.assign(kMaxCells, 0);
    visited.assign(kMaxCells, 0);
    dist.assign(kMaxCells, -1);
    parent.assign(kMaxCells, -1);
    stack.reserve(kMaxCells);
    queue.reserve(kMaxCells);
    path.reserve(kMaxCells);
    phase = kGen;
    phaseTime = genSteps = 0;
    stepsDone = 0;
    maxDist = 1;
  }

  void update(const Frame& f) override {
    auto m = modifiers(f);
    float dt = float(f.delta);
    const Music& mu = f.music;
    bass = follow(bass, mu.bass, 22.0f, 4.5f, dt);
    body = follow(body, mu.body, 12.0f, 3.0f, dt);
    spark = follow(spark, mu.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, mu.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, mu.active ? std::pow(std::clamp(mu.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : mu.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : mu.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : mu.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((mu.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, mu.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));

    int c = std::clamp(m.celdas, 6, kMaxCols);
    cellPx = f.width * 0.92f / float(c);
    int r = std::clamp(int(f.height * 0.92f / cellPx), 4, kMaxRows);
    if (c != cols || r != rows) {
      cols = c;
      rows = r;
      clearMaze();
    }
    ox = (f.width - float(cols) * cellPx) * 0.5f;
    oy = (f.height - float(rows) * cellPx) * 0.5f;
    double rate = f.delta * f.speed * (1.0 + 1.2 * drive + 1.5 * kick);
    // Unos 7 segundos para excavar todo, sea cual sea el tamaño.
    double stepsPerSecond = double(2 * cols * rows) / 7.0;
    if (phase == kGen) {
      genSteps += rate * stepsPerSecond;
      int64_t target = int64_t(std::floor(genSteps + 1e-6));
      while (stepsDone < target && !stack.empty()) {
        genStep(std::clamp(m.tramos, 0.0f, 1.0f));
        stepsDone++;
      }
      if (!stack.empty()) return;
      // El tiempo sobrante pasa a la siguiente fase: igual a 30 y 60 FPS.
      solve();
      phase = kFlood;
      phaseTime = std::max(0.0, genSteps - double(stepsDone)) / stepsPerSecond;
    } else {
      phaseTime += rate;
    }
    static const double lengths[5] = {0.0, 3.2, 1.6, 1.8, 0.9};
    while (phase != kGen && phaseTime >= lengths[phase]) {
      phaseTime -= lengths[phase];
      if (phase == kFade) {
        double carry = phaseTime;
        clearMaze();
        genSteps = carry * stepsPerSecond;
      } else {
        phase++;
      }
    }
  }

  void render(const Frame& f, Canvas& c) const override {
    auto m = modifiers(f);
    auto g = glide(f);
    // Franjas de color: 1 = franjas que se repiten cada 24 celdas, 0 = un
    // degradado continuo; al cambiar, cada pasillo se desliza entre ambos.
    const float stripes = std::clamp(g.franjas, 0.0f, 1.0f);
    float amp = f.intensity;
    const Color& bg = f.colors[0];
    c.rect({0, 0, f.width, f.height}, Paint::radial({f.width * 0.5f, f.height * 0.5f}, std::max(f.width, f.height) * 0.75f,
                                                   {Color{std::min(1.0f, bg.r + 0.035f), std::min(1.0f, bg.g + 0.025f), std::min(1.0f, bg.b + 0.04f), 1.0f},
                                                    Color{bg.r, bg.g, bg.b, 1.0f}}));
    if (cols <= 0) return;
    float px = std::min(f.width, f.height) / 400.0f;
    float fade = phase == kFade ? float(1.0 - phaseTime / 0.9) : 1.0f;
    float flood = phase == kGen ? -1.0f : (phase == kFlood ? float(phaseTime / 3.2) * float(maxDist + 4) : float(maxDist + 4));
    float width = cellPx * m.grosor;
    const Color& red = f.colors[1];
    const Color& orange = f.colors[2];
    const Color& yellow = f.colors[3];
    auto ramp = [&](float t) {
      t = std::clamp(t, 0.0f, 1.0f);
      if (t < 0.5f) return Color{red.r + (orange.r - red.r) * t * 2.0f, red.g + (orange.g - red.g) * t * 2.0f, red.b + (orange.b - red.b) * t * 2.0f, 1.0f};
      float u = (t - 0.5f) * 2.0f;
      return Color{orange.r + (yellow.r - orange.r) * u, orange.g + (yellow.g - orange.g) * u, orange.b + (yellow.b - orange.b) * u, 1.0f};
    };
    // Pasillos: tenues hasta que llega la luz; luego por franjas de distancia.
    const int buckets = 10;
    std::array<Path, buckets> lit;
    Path dim, front;
    bool anyFront = false;
    for (int cell = 0; cell < cols * rows; cell++) {
      Vec2 a = center(cell);
      for (int k = 0; k < 2; k++) {
        if (!(carved[size_t(cell)] & (k == 0 ? 1 : 2))) continue;
        int other = cell + (k == 0 ? 1 : cols);
        Vec2 b = center(other);
        int d = std::max(dist[size_t(cell)], dist[size_t(other)]);
        if (flood >= 0.0f && d >= 0 && float(d) <= flood) {
          const float smooth = float(d) / float(maxDist);
          float t = smooth + (float(d % 24) / 23.0f - smooth) * stripes;
          lit[size_t(std::min(buckets - 1, int(t * float(buckets))))].moveTo(a.x, a.y).lineTo(b.x, b.y);
          if (float(d) > flood - 2.5f) {
            front.moveTo(a.x, a.y).lineTo(b.x, b.y);
            anyFront = true;
          }
        } else {
          dim.moveTo(a.x, a.y).lineTo(b.x, b.y);
        }
      }
    }
    Paint pd;
    pd.strokeWidth = width;
    pd.strokeCap = 1;
    pd.strokeJoin = 1;
    pd.color = Color{0.55f, 0.5f, 0.52f, std::clamp((0.22f + 0.1f * bass) * fade * amp, 0.0f, 1.0f)};
    c.path(dim, pd);
    for (int b = 0; b < buckets; b++) {
      Color col = ramp((float(b) + 0.5f) / float(buckets));
      float g = (0.8f + 0.35f * bass + 0.2f * kick) * amp;
      Paint halo;
      halo.blend = Blend::plus;
      halo.strokeWidth = width * 2.2f;
      halo.strokeCap = 1;
      halo.color = col.opacity(std::clamp(0.12f * f.glow * fade * amp, 0.0f, 1.0f));
      c.path(lit[size_t(b)], halo);
      Paint p;
      p.strokeWidth = width;
      p.strokeCap = 1;
      p.strokeJoin = 1;
      p.color = Color{std::min(1.0f, col.r * g), std::min(1.0f, col.g * g), std::min(1.0f, col.b * g), fade};
      c.path(lit[size_t(b)], p);
    }
    if (anyFront && phase == kFlood) {
      Paint fp;
      fp.blend = Blend::plus;
      fp.strokeWidth = width * 1.4f;
      fp.strokeCap = 1;
      fp.color = Color{1.0f, 0.95f, 0.8f, std::clamp((0.45f + 0.5f * kick) * amp, 0.0f, 1.0f)};
      c.path(front, fp);
    }
    // Rama actual del excavador, con los colores que tendrá la luz: por
    // franjas de su profundidad o en degradado de la raíz a la punta.
    if (phase == kGen && stack.size() > 1) {
      std::array<Path, buckets> branch;
      const float depthScale = float(std::max(1, cols * rows / 2));
      int last = -1;
      for (size_t i = 1; i < stack.size(); i++) {
        const float smooth = std::min(1.0f, float(i) / depthScale);
        const float t = smooth + (float(i % 24) / 23.0f - smooth) * stripes;
        const int b = std::clamp(int(t * float(buckets)), 0, buckets - 1);
        if (b != last) {
          Vec2 a = center(stack[i - 1]);
          branch[size_t(b)].moveTo(a.x, a.y);
        }
        Vec2 p = center(stack[i]);
        branch[size_t(b)].lineTo(p.x, p.y);
        last = b;
      }
      // Una sola opacidad para toda la rama: los tramos no se suman al unirse.
      c.saveLayer(std::clamp(0.75f * amp, 0.0f, 1.0f));
      for (int b = 0; b < buckets; b++) {
        Paint bp;
        bp.strokeWidth = width * 0.8f;
        bp.strokeCap = 1;
        bp.strokeJoin = 1;
        bp.color = ramp((float(b) + 0.5f) / float(buckets));
        c.path(branch[size_t(b)], bp);
      }
      c.restore();
      Vec2 head = center(stack.back());
      Paint hp = Paint::radial(head, cellPx * 1.6f, {yellow.opacity(std::clamp((0.8f + 0.2f * kick) * amp, 0.0f, 1.0f)), yellow.opacity(0.0f)});
      hp.blend = Blend::plus;
      c.circle(head, cellPx * 1.6f, hp);
    }
    // Camino más corto, en blanco.
    if ((phase == kPath || phase == kHold || phase == kFade) && path.size() > 1) {
      float prog = phase == kPath ? float(phaseTime / 1.6) : 1.0f;
      size_t count = std::max<size_t>(2, size_t(prog * float(path.size())));
      Path sol;
      for (size_t i = 0; i < std::min(count, path.size()); i++) {
        Vec2 p = center(path[i]);
        if (i == 0) sol.moveTo(p.x, p.y); else sol.lineTo(p.x, p.y);
      }
      Paint glow;
      glow.blend = Blend::plus;
      glow.strokeWidth = width * 2.4f;
      glow.strokeCap = 1;
      glow.strokeJoin = 1;
      glow.color = Color{1.0f, 0.9f, 0.7f, std::clamp(0.25f * f.glow * fade * amp, 0.0f, 1.0f)};
      c.path(sol, glow);
      Paint line;
      line.strokeWidth = width * 0.75f;
      line.strokeCap = 1;
      line.strokeJoin = 1;
      line.color = Color{1.0f, 1.0f, 1.0f, fade};
      c.path(sol, line);
    }
    // Entrada y salida.
    Paint mark;
    mark.blend = Blend::plus;
    mark.color = yellow.opacity(std::clamp((0.6f + 0.4f * kick) * fade * amp, 0.0f, 1.0f));
    c.circle(center(0), width * 0.9f, mark);
    c.circle(center(cols * rows - 1), width * 0.9f, mark);
    (void)px;
    if (flash > 0.01f) {
      Paint fl;
      fl.blend = Blend::plus;
      fl.color = orange.opacity(std::clamp(flash * 0.05f * amp, 0.0f, 1.0f));
      c.rect({0, 0, f.width, f.height}, fl);
    }
  }
};

class Visual final : public Scene {
  static constexpr int kBlobs = 7;
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  // Relojes en doble precisión: la escena sin música es idéntica a 30 y 60 FPS.
  double clock = 0, wobble = 0;
  std::array<float, kBlobs> period{}, phase{}, lane{}, size{};

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    clock = rng.unit() * 100.0;
    wobble = 0;
    for (int i = 0; i < kBlobs; i++) {
      period[size_t(i)] = 14.0f + 12.0f * rng.unit();
      phase[size_t(i)] = rng.unit() * 6.2831853f;
      lane[size_t(i)] = (float(i) / float(kBlobs - 1) - 0.5f) * 0.55f + (rng.unit() - 0.5f) * 0.1f;
      size[size_t(i)] = 0.09f + 0.07f * rng.unit();
    }
  }

  void update(const Frame& f) override {
    float dt = float(f.delta);
    const Music& mu = f.music;
    bass = follow(bass, mu.bass, 22.0f, 4.5f, dt);
    body = follow(body, mu.body, 12.0f, 3.0f, dt);
    spark = follow(spark, mu.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, mu.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, mu.active ? std::pow(std::clamp(mu.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : mu.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : mu.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : mu.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((mu.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, mu.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    clock += f.delta * f.speed * (1.0 + 1.5 * drive);
    wobble += f.delta * (6.0 + 6.0 * energy);
  }

  void render(const Frame& f, Canvas& c) const override {
    auto m = modifiers(f);
    auto g = glide(f);
    float amp = f.intensity;
    float side = std::min(f.width, f.height);
    float halfH = 0.5f * f.height / side;
    int count = std::clamp(m.gotas, 3, kBlobs);
    // Calor de la cera (0,5 es la lámpara de siempre): fría, las gotas son
    // redondas y sólo suben un poco desde el charco; caliente, suben en
    // columnas altas que se estiran, se mecen y se juntan arriba.
    const float heat = std::clamp(g.calor, 0.0f, 1.0f);
    const float cold = std::clamp(1.0f - heat * 2.0f, 0.0f, 1.0f);
    const float hot = std::clamp(heat * 2.0f - 1.0f, 0.0f, 1.0f);
    std::vector<float> u;
    u.reserve(52);
    u.insert(u.end(), {float(std::fmod(wobble, 1000.0)), bass * amp, kick * amp, energy});
    u.insert(u.end(), {float(count), m.reflejos ? 1.0f : 0.0f, f.glow, flash * amp});
    // Charco de abajo y de arriba: crece abajo con el frío y arriba con el calor.
    u.insert(u.end(), {0.16f + 0.1f * cold - 0.03f * hot, 0.08f * (1.0f - cold) + 0.06f * hot});
    for (int i = 0; i < kBlobs; i++) {
      // Sube y baja: cerca de los extremos va más despacio, como la cera real.
      double w = 6.283185307179586 / double(period[size_t(i)]);
      double s = std::sin(clock * w + double(phase[size_t(i)]));
      double v = std::cos(clock * w + double(phase[size_t(i)]));
      float y = (float(s) * (0.78f - 0.42f * cold) - 0.44f * cold) * halfH;
      float sway = 0.05f - 0.035f * cold + 0.05f * hot;
      float x = lane[size_t(i)] + sway * float(std::sin(clock * 0.21 + double(i)));
      float r = size[size_t(i)] * m.tamano * (1.0f + 0.22f * bass * amp) * (1.0f - 0.22f * hot);
      float stretch = 1.0f + (0.55f - 0.45f * cold + 0.5f * hot) * float(std::fabs(v)) + 0.7f * hot;
      u.insert(u.end(), {x, y, i < count ? r : 0.0f, stretch});
    }
    for (int i = 0; i < 4; i++) u.insert(u.end(), {f.colors[i].r, f.colors[i].g, f.colors[i].b});
    c.material("lava_lamp", {0, 0, f.width, f.height}, u);
  }
};

shaderSources.lava_lamp:
#version 460 core
#include <flutter/runtime_effect.glsl>
uniform vec2 uSize;
uniform vec4 uA;   // temblor, graves, golpe, energía
uniform vec4 uB;   // gotas, reflejos, glow, destello
uniform vec2 uH;   // alto del charco de abajo y del de arriba (calor de la cera)
uniform vec4 uG0;  // gota: x, y, radio, estiramiento vertical
uniform vec4 uG1;
uniform vec4 uG2;
uniform vec4 uG3;
uniform vec4 uG4;
uniform vec4 uG5;
uniform vec4 uG6;
uniform vec3 uC0;
uniform vec3 uC1;
uniform vec3 uC2;
uniform vec3 uC3;
out vec4 fragColor;

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

// Suma el campo de una gota y su gradiente. El campo tiene alcance limitado
// (1 − q/R²)³: las gotas sólo se funden cuando se acercan y no hay puntos
// singulares en su centro.
void blob(vec2 p, vec4 g, inout float F, inout vec2 grad) {
  if (g.z <= 0.0) return;
  vec2 d = p - g.xy;
  d.y /= g.w;
  float R2 = g.z * g.z * 3.6;
  float q = dot(d, d);
  if (q >= R2) return;
  float k = 1.0 - q / R2;
  F += k * k * k;
  grad += -6.0 * k * k / R2 * vec2(d.x, d.y / g.w);
}

void main() {
  vec2 frag = FlutterFragCoord().xy;
  float scale = min(uSize.x, uSize.y);
  vec2 p = (frag - 0.5 * uSize) / scale;
  p.y = -p.y;
  float halfH = 0.5 * uSize.y / scale;
  // Temblor del golpe: la superficie de la cera vibra un instante.
  vec2 pw = p + uA.z * 0.012 * vec2(sin(p.y * 40.0 + uA.x * 3.0), sin(p.x * 36.0 - uA.x * 2.0));
  float F = 0.0;
  vec2 grad = vec2(0.0);
  blob(pw, uG0, F, grad);
  blob(pw, uG1, F, grad);
  blob(pw, uG2, F, grad);
  blob(pw, uG3, F, grad);
  blob(pw, uG4, F, grad);
  blob(pw, uG5, F, grad);
  blob(pw, uG6, F, grad);
  // Charco de cera abajo y un poco arriba, con el mismo tipo de campo.
  float bottom = pw.y + halfH;
  if (bottom < uH.x) {
    float k = 1.0 - bottom / uH.x;
    F += 0.9 * k * k * k;
    grad += vec2(0.0, -0.9 * 3.0 * k * k / uH.x);
  }
  float top = halfH - pw.y;
  if (uH.y > 0.001 && top < uH.y) {
    float k = 1.0 - top / uH.y;
    F += 0.7 * k * k * k;
    grad += vec2(0.0, 0.7 * 3.0 * k * k / uH.y);
  }

  // Líquido violeta iluminado desde abajo.
  float fromBottom = clamp((p.y + halfH) / (2.0 * halfH), 0.0, 1.0);
  vec3 col = uC0 * (1.6 - 0.9 * fromBottom);
  col += uC2 * exp(-(p.y + halfH) * 3.0) * (0.22 + 0.25 * uA.y);
  col += uC1 * smoothstep(0.05, 0.3, F) * 0.1 * uB.z;

  float T = 0.3;
  float inside = smoothstep(T - 0.025, T + 0.025, F);
  if (inside > 0.0) {
    // Relieve de la cera desde el gradiente del campo.
    vec3 n = normalize(vec3(-grad * 0.05, 1.0));
    vec3 L = normalize(vec3(-0.5, 0.6, 0.8));
    float diff = clamp(dot(n, L), 0.0, 1.0);
    float thick = smoothstep(T, 1.1, F);
    vec3 wax = mix(uC1, uC2, thick);
    wax = mix(wax, uC3, smoothstep(0.9, 1.6, F) * (0.5 + 0.5 * uA.y));
    wax *= 0.55 + 0.6 * diff;
    // Borde oscuro y luz de abajo que atraviesa la cera.
    float rim = 1.0 - clamp(n.z, 0.0, 1.0);
    wax *= 1.0 - 0.45 * rim;
    wax += uC2 * exp(-(p.y + halfH) * 2.5) * 0.35;
    if (uB.y > 0.5) {
      vec3 hv = normalize(L + vec3(0.0, 0.0, 1.0));
      float spec = pow(clamp(dot(n, hv), 0.0, 1.0), 40.0);
      wax += vec3(1.0, 0.92, 0.8) * spec * 0.7;
    }
    wax *= 1.0 + 0.25 * uA.y + 0.2 * uA.z;
    col = mix(col, wax, inside);
  }
  col += uC2 * uB.w * 0.05;
  col *= 1.0 - 0.3 * smoothstep(0.6, 1.4, abs(p.x) * 1.4 + 0.2);
  float peak = max(col.r, max(col.g, col.b));
  if (peak > 0.85) {
    float e = (peak - 0.85) / 0.15;
    col *= (0.85 + 0.15 * e / (1.0 + e)) / peak;
  }
  col += (hash12(frag) - 0.5) / 255.0;
  fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

visuals.nativeSource:
class Visual final : public Scene {
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  double phase = 0, drift = 0, sinceMorph = 0;
  std::array<float, 4> from{}, to{};
  float morph = 1, breath = 0, breathVel = 0;
  int beats = 0, shape = 0;

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

  // Formas elegidas: giro inicial, giro por iteración, frecuencia y remolino.
  static std::array<float, 4> shapeAt(int i) {
    static const float shapes[6][4] = {{0.8f, 1.3f, 1.3f, 1.0f}, {0.6f, 1.7f, 1.1f, 1.8f}, {1.5f, 1.1f, 1.2f, 1.3f},
                                       {0.9f, 2.4f, 1.4f, 0.9f}, {0.1f, 2.0f, 1.5f, 1.4f}, {0.3f, 0.9f, 1.7f, 0.6f}};
    const float* s = shapes[((i % 6) + 6) % 6];
    return {s[0], s[1], s[2], s[3]};
  }

  void next() {
    float e = morph * morph * (3.0f - 2.0f * morph);
    for (int i = 0; i < 4; i++) from[i] = from[i] + (to[i] - from[i]) * e;
    shape++;
    to = shapeAt(shape);
    morph = 0;
    sinceMorph = 0;
  }

 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    phase = rng.unit() * 6.2831853;
    drift = rng.unit() * 10.0;
    sinceMorph = 0;
    shape = int(rng.unit() * 6.0f);
    from = to = shapeAt(shape);
    morph = 1;
    breath = breathVel = 0;
    beats = 0;
  }

  void update(const Frame& f) override {
    float dt = float(f.delta);
    const Music& m = f.music;
    bass = follow(bass, m.bass, 22.0f, 4.5f, dt);
    body = follow(body, m.body, 12.0f, 3.0f, dt);
    spark = follow(spark, m.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, m.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, m.active ? std::pow(std::clamp(m.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : m.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : m.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : m.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((m.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, m.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    if (hit > kick + 0.2f) {
      beats++;
      breathVel += 1.4f * hit;
      if (beats % 2 == 0) next();
    }
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    // La llama respira con el golpe y vuelve con un muelle amortiguado.
    breathVel += (-breath * 30.0f - breathVel * 6.0f) * dt;
    breath += breathVel * dt;
    morph = std::min(1.0f, morph + dt * 1.1f);
    sinceMorph += f.delta;
    // En silencio la llama cambia de forma cada diez segundos.
    if (!m.active && sinceMorph > 10.0) next();
    phase += f.delta * f.speed * (0.07 + 0.25 * drive + 0.1 * bass);
    drift += f.delta * f.speed * (0.15 + 0.3 * drive);
  }

  void render(const Frame& f, Canvas& c) const override {
    float amp = f.intensity;
    float e = morph * morph * (3.0f - 2.0f * morph);
    std::array<float, 4> p;
    for (int i = 0; i < 4; i++) p[i] = from[i] + (to[i] - from[i]) * e;
    // Ondulación lenta del remolino para que la seda nunca quede quieta.
    p[3] += 0.15f * float(std::sin(drift * 0.9));
    p[2] += 0.05f * float(std::sin(drift * 0.6 + 1.3));
    std::vector<float> u;
    u.reserve(24);
    u.insert(u.end(), {float(std::fmod(phase, 6.2831853)), bass * amp, kick * amp, energy});
    u.insert(u.end(), {p[0], p[1], p[2], p[3]});
    u.insert(u.end(), {f.glow, spark * amp, 1.0f + 0.08f * breath * amp, flash * amp});
    for (int i = 0; i < 4; i++) u.insert(u.end(), {f.colors[i].r, f.colors[i].g, f.colors[i].b});
    c.material("flame", {0, 0, f.width, f.height}, u);
  }
};

