  vec2 o = vec2(hash12(id + seed + 1.7), hash12(id + seed + 4.2)) - 0.5;
  o.x += 0.3 * sin(t * 2.0 + h * 30.0);
  float d = length((f - o * 0.6) * vec2(1.0, 0.3));
  return smoothstep(0.07, 0.0, d) * step(1.0 - density, h) * (0.6 + 0.4 * sin(t * 30.0 + h * 80.0));
}

void main() {
  vec2 frag = FlutterFragCoord().xy;
  float scale = min(uSize.x, uSize.y);
  vec2 uv = (frag - 0.5 * uSize) / scale;
  uv.y = -uv.y;
  float t = uA.x;
  float bottom = -0.5 * uSize.y / scale;
  float h = uv.y - bottom;                 // altura sobre el borde inferior
  float height = 0.25 + 1.05 * uA.y;       // altura de las llamas

  // Calima: el aire caliente ondula por encima del fuego.
  vec2 p = uv;
  if (h < height * 2.0 + 0.2) {
    p.x += (noise(vec2(uv.x * 6.0, h * 4.0 - t * 2.0)) - 0.5) * 0.03 * smoothstep(0.1, 0.8, h);
  }

  vec3 col = uC0;
  // Resplandor cálido sólo alrededor del fuego.
  float glowR = length(vec2(p.x * 0.8, h - height * 0.35));
  col += uC1 * 0.06 * exp(-glowR * glowR * 3.0 / max(height, 0.15)) * (0.6 + 0.8 * uA.y);

  // Las llamas sólo existen en la parte baja: por encima la GPU se salta el ruido.
  if (h < height * 1.2 + 0.05) {
    // Ruido estirado en vertical: lenguas de fuego que suben y se rompen.
    vec2 q = vec2(p.x * 3.4, h * 1.5 - t * 1.9);
    vec2 warp = vec2(fbmLow(q * 0.6 + vec2(0.0, -t * 0.5)), fbmLow(q * 0.6 + vec2(3.7, -t * 0.6)));
    float n = fbm(q + (warp - 0.5) * 1.8);
    float licks = noise(vec2(p.x * 9.0, h * 3.0 - t * 4.0));
    float tongues = 0.7 + 0.3 * sin(p.x * 6.5 + noise(vec2(p.x * 2.5, t * 0.5)) * 5.0);
    float shape = 1.0 - h / (height * tongues);
    float widthMask = smoothstep(1.05, 0.2, abs(p.x) * (1.3 - 0.35 * uA.y));
    float flame = shape * widthMask * 1.55 - n * 1.05 - licks * 0.18 + 0.2;
    float body = smoothstep(0.0, 0.06, flame);
    float heat = clamp(flame * 0.85, 0.0, 1.0) * (0.66 + 0.22 * uA.z + 0.08 * uX.x);
    col += fireColor(heat) * body;
  }
  // Lecho de brasas en la base.
  if (h < 0.3) {
    float bed = exp(-h * 22.0) * (0.55 + 0.45 * noise(vec2(p.x * 14.0, t * 0.6)));
    col += fireColor(0.5 + 0.25 * noise(vec2(p.x * 9.0, t))) * bed * (0.7 + 0.5 * uA.y);
  }

  // Humo tenue en una franja por encima de las llamas.
  float smokeBand = smoothstep(height * 0.8, height * 1.5, h) * smoothstep(height * 2.6 + 0.5, height * 1.6, h);
  if (smokeBand > 0.0) {
    float smoke = fbmLow(vec2(p.x * 2.0, h * 1.5 - t * 0.35) + 9.0);
    col = mix(col, uC0 * 1.8, smoothstep(0.55, 0.85, smoke) * smokeBand * 0.4);
  }

  // Brasas: pocas, cerca del fuego y como estelas; más con los agudos.
  float density = 0.02 + 0.06 * uB.w + 0.03 * uA.w;
  float e = embers(p, t * 0.3, 14.0, 1.1, 0.0, density) +
            embers(p, t * 0.3, 24.0, 1.6, 13.0, density * 0.7) * 0.7;
  float fade = smoothstep(height * 1.6, height * 0.2, h) * smoothstep(1.0, 0.3, abs(p.x));
  col += mix(uC2, uC3, 0.5) * e * fade * 1.6;
  float age = uB.y;
  if (age < 2.5 && uB.x > 0.01) {
    vec2 bp = p - vec2(uB.z, bottom + height * 0.4 + age * 1.1);
    float spray = embers(bp * vec2(1.0, 0.7), 0.0, 22.0, 0.0, 31.0, 0.4);
    float cloud = exp(-dot(bp, bp) * 5.0 / (0.15 + age));
    col += mix(uC2, uC3, 0.7) * spray * cloud * uB.x * exp(-age * 1.6) * 3.0;
  }

  col *= uX.z;
  col *= 1.0 - 0.35 * smoothstep(0.5, 1.3, length(uv * vec2(0.9, 0.65)));
  col = clamp((col * (2.51 * col + 0.03)) / (col * (2.43 * col + 0.59) + 0.14), 0.0, 1.0);
  col = pow(col, vec3(0.4545));
  // Fondo transparente: el color va premultiplicado y la opacidad sale del
  // brillo, así la luz se compone sobre lo que haya debajo.
  col = clamp(col, 0.0, 1.0);
  // La luz muy tenue se vuelve transparente del todo: sin velo sobre la app.
  float veilPeak = max(col.r, max(col.g, col.b));
  float clearCut = smoothstep(0.08, 0.2, veilPeak);
  col *= clearCut;
  float alpha = clamp(veilPeak * 1.25, 0.0, 1.0) * clearCut;
  fragColor = vec4(col, alpha);
}

visuals.nativeSource:
class Visual final : public Scene {
  static constexpr int kMax = 1800;
  static constexpr double kStep = 1.0 / 120.0;
  struct Spark { float x, y, vx, vy, temp, cool; int bounces; };
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  // Relojes en doble precisión: la escena sin música es idéntica a 30 y 60 FPS.
  double sim = 0, emitAcc = 0;
  int64_t steps = 0;
  int burst = 0;
  float aspect = 2.0f;
  Random rng{1};
  std::vector<Spark> sparks, pieces;

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

  // Posición de cada punto de corte (en unidades del lado corto).
  Vec2 source(int k, int count, double t) const {
    float baseX = count == 1 ? 0.0f : (float(k) / float(count - 1) - 0.5f) * 0.6f;
    return {baseX + 0.08f * float(std::sin(t * 0.4 + double(k) * 2.1)), -aspect * 0.18f + 0.06f * float(std::sin(t * 0.33 + double(k)))};
  }

  void emit(int count, int dir, double t) {
    if (int(sparks.size()) >= kMax) return;
    int k = std::min(int(rng.unit() * float(count)), count - 1);
    Vec2 s = source(k, count, t);
    float a;
    if (dir == 1) a = 1.5708f + (rng.unit() - 0.5f) * 1.3f;
    else if (dir == 0) a = (k % 2 == 0 ? -0.35f : 3.14159f + 0.35f) + (rng.unit() - 0.5f) * 0.8f;
    else a = -1.5708f + (rng.unit() - 0.5f) * 1.0f;
    float speed = 0.9f + 1.6f * rng.unit();
    sparks.push_back({s.x, s.y, std::cos(a) * speed, std::sin(a) * speed, 1.0f, 0.45f + 0.7f * rng.unit(), 0});
  }

 public:
  void reset(uint32_t seed) override {
    rng = Random(seed);
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    sim = 0;
    emitAcc = 0;
    steps = 0;
    burst = 0;
    sparks.clear();
    sparks.reserve(kMax + 64);
    pieces.clear();
    pieces.reserve(kMax);
  }

  void update(const Frame& f) override {
    auto m = modifiers(f);
    float dt = float(f.delta);
    const Music& mu = f.music;
    bass = follow(bass, mu.bass, 22.0f, 4.5f, dt);
    body = follow(body, mu.body, 12.0f, 3.0f, dt);
    spark = follow(spark, mu.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, mu.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, mu.active ? std::pow(std::clamp(mu.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : mu.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : mu.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : mu.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((mu.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, mu.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    if (hit > kick + 0.2f) burst += int((120.0f + 220.0f * hit) * m.cantidad);
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    aspect = f.height / std::max(std::min(f.width, f.height), 1.0f) * 0.5f * 2.0f;

    int count = std::clamp(m.fuentes, 1, 3);
    float floorY = aspect * 0.5f * 0.92f;
    sim += f.delta * f.speed;
    int64_t target = int64_t(std::floor(sim / kStep + 1e-6));
    if (target - steps > 30) steps = target - 30;
    float h = float(kStep);
    while (steps < target) {
      steps++;
      double t = double(steps) * kStep;
      double rate = (260.0 + 900.0 * double(drive)) * double(m.cantidad);
      emitAcc += rate * kStep;
      while (emitAcc >= 1.0) {
        emitAcc -= 1.0;
        emit(count, m.direccion, t);
      }
      int b = std::min(burst, 60);
      for (int k = 0; k < b; k++) emit(count, m.direccion, t);
      burst -= b;
      pieces.clear();
      for (auto& s : sparks) {
        s.vy += 2.4f * h;
        float drag = 1.0f - 0.9f * h;
        s.vx *= drag;
        s.vy *= drag;
        s.x += s.vx * h;
        s.y += s.vy * h;
        s.temp -= s.cool * h;
        if (m.rebote && s.y > floorY && s.vy > 0.0f) {
          s.y = floorY;
          s.vy = -s.vy * 0.32f;
          s.vx = s.vx * 0.65f + (rng.unit() - 0.5f) * 0.4f;
          s.bounces++;
          s.temp -= 0.08f;
          if (s.bounces == 1 && rng.unit() < 0.35f && int(sparks.size() + pieces.size()) < kMax) {
            // Se parte en dos: el trozo nuevo se añade después del recorrido.
            Spark piece = s;
            piece.vx = -s.vx * 0.8f;
            piece.cool *= 1.4f;
            pieces.push_back(piece);
          }
        }
      }
      sparks.insert(sparks.end(), pieces.begin(), pieces.end());
      sparks.erase(std::remove_if(sparks.begin(), sparks.end(), [&](const Spark& s) {
        return s.temp <= 0.0f || s.bounces > 3 || std::fabs(s.x) > 1.5f || s.y > aspect;
      }), sparks.end());
    }
  }

  void render(const Frame& f, Canvas& c) const override {
    auto m = modifiers(f);
    float amp = f.intensity;
    const Color& bg = f.colors[0];
    Paint back;
    back.color = Color{bg.r, bg.g, bg.b, 1.0f};
    c.rect({0, 0, f.width, f.height}, back);
    float side = std::min(f.width, f.height);
    float px = side / 400.0f;
    float cx = f.width * 0.5f, cy = f.height * 0.5f;
    int count = std::clamp(m.fuentes, 1, 3);
    float floorY = aspect * 0.5f * 0.92f;
    // Brillo del suelo bajo los puntos de corte.
    if (m.rebote) {
      for (int k = 0; k < count; k++) {
        Vec2 s = source(k, count, double(steps) * kStep);
        Vec2 q{cx + s.x * side, cy + floorY * side};
        Paint pool = Paint::radial(q, side * 0.35f, {f.colors[2].opacity(std::clamp((0.18f + 0.25f * drive + 0.2f * kick) * amp, 0.0f, 1.0f)), f.colors[2].opacity(0.0f)});
        pool.blend = Blend::plus;
        c.rect({q.x - side * 0.35f, q.y - side * 0.35f, side * 0.7f, side * 0.7f}, pool);
      }
      Paint line;
      line.strokeWidth = 1.2f * px;
      line.color = f.colors[1].opacity(0.25f);
      Path fl;
      fl.moveTo(0, cy + floorY * side).lineTo(f.width, cy + floorY * side);
      c.path(fl, line);
    }
    // Estelas por temperatura: blanca, amarilla, naranja, roja y brasa.
    const int buckets = 5;
    std::array<Path, buckets> paths;
    std::array<bool, buckets> used{};
    for (const auto& s : sparks) {
      int b = s.temp > 0.8f ? 0 : (s.temp > 0.6f ? 1 : (s.temp > 0.4f ? 2 : (s.temp > 0.2f ? 3 : 4)));
      float x1 = cx + s.x * side, y1 = cy + s.y * side;
      float x0 = x1 - s.vx * side * 0.045f, y0 = y1 - s.vy * side * 0.045f;
      paths[size_t(b)].moveTo(x0, y0).lineTo(x1, y1);
      used[size_t(b)] = true;
    }
    std::array<Color, buckets> cols = {Color{1.0f, 0.98f, 0.9f, 1.0f}, f.colors[3], f.colors[2], f.colors[1],
                                       Color{f.colors[1].r * 0.55f, f.colors[1].g * 0.4f, f.colors[1].b * 0.4f, 1.0f}};
    static const float widths[buckets] = {1.8f, 1.6f, 1.4f, 1.2f, 1.0f};
    for (int b = buckets - 1; b >= 0; b--) {
      if (!used[size_t(b)]) continue;
      Paint glow;
      glow.blend = Blend::plus;
      glow.strokeWidth = widths[b] * 3.5f * px;
      glow.strokeCap = 1;
      glow.color = cols[size_t(b)].opacity(std::clamp(0.1f * f.glow * amp, 0.0f, 1.0f));
      c.path(paths[size_t(b)], glow);
      Paint core;
      core.blend = Blend::plus;
      core.strokeWidth = widths[b] * px;
      core.strokeCap = 1;
      core.color = cols[size_t(b)].opacity(std::clamp(0.9f * amp, 0.0f, 1.0f));
      c.path(paths[size_t(b)], core);
    }
    // Punto de corte incandescente.
    for (int k = 0; k < count; k++) {
      Vec2 s = source(k, count, double(steps) * kStep);
      Vec2 q{cx + s.x * side, cy + s.y * side};
      float r = (18.0f + 10.0f * bass + 10.0f * kick) * px;
      Paint halo = Paint::radial(q, r, {Color{1.0f, 0.95f, 0.8f, std::clamp(0.9f * amp, 0.0f, 1.0f)}, f.colors[2].opacity(0.0f)});
      halo.blend = Blend::plus;
      c.circle(q, r, halo);
    }
    if (flash > 0.01f) {
      Paint fl;
      fl.blend = Blend::plus;
      fl.color = f.colors[2].opacity(std::clamp(flash * 0.05f * amp, 0.0f, 1.0f));
      c.rect({0, 0, f.width, f.height}, fl);
    }
  }
};

class Visual final : public Scene {
  struct Drop { float x, y, depth, radius, light; };
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  // Fases en doble precisión: la escena sin música es idéntica a 30 y 60 FPS.
  double clock = 0, yaw = 0, sinceShape = 0;
  int shapeA = 0, shapeB = 0, beats = 0, step = 0;
  float morph = 1, ringR = 3.0f, ringAmp = 0;

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

  // Formas de la escultura sobre la cuadrícula (x, z en -1..1).
  static float shape(int id, float x, float z, float t) {
    float r = std::sqrt(x * x + z * z);
    switch (id) {
      case 0: return 0.28f * std::sin(x * 2.4f + t * 1.1f) + 0.12f * std::sin(z * 3.1f - t * 0.7f);
      case 1: return 0.30f * std::sin(r * 6.0f - t * 2.0f) * std::exp(-r * 0.5f);
      case 2: return 0.42f * (x * x - z * z) * std::cos(t * 0.5f);
      case 3: return 0.28f * std::sin(x * 3.0f + t) * std::cos(z * 3.0f - t * 0.8f);
      case 4: return 0.55f * std::exp(-r * r * 2.2f) * (0.8f + 0.2f * std::sin(t * 1.5f)) - 0.2f;
      default: return 0.25f * std::sin(std::atan2(z, x) * 2.0f + r * 5.0f - t * 1.8f);
    }
  }

  void next() {
    step++;
    shapeA = shapeB;
    shapeB = step % 6;
    morph = 0;
    sinceShape = 0;
  }

 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    clock = rng.unit() * 20.0;
    yaw = 0.5 + rng.unit() * 0.5;
    sinceShape = 0;
    shapeA = shapeB = 0;
    beats = step = 0;
    morph = 1;
    ringR = 3.0f;
    ringAmp = 0;
  }

  void update(const Frame& f) override {
    float dt = float(f.delta);
    const Music& m = f.music;
    bass = follow(bass, m.bass, 22.0f, 4.5f, dt);
    body = follow(body, m.body, 12.0f, 3.0f, dt);
    spark = follow(spark, m.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, m.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, m.active ? std::pow(std::clamp(m.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : m.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : m.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : m.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((m.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, m.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    if (hit > kick + 0.2f) {
      beats++;
      ringR = 0.0f;
      ringAmp = hit;
      if (beats % 8 == 0) next();
    }
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    morph = std::min(1.0f, morph + dt * 0.8f);
    sinceShape += f.delta;
    // En silencio la escultura cambia de forma cada nueve segundos.
    if (!m.active && sinceShape > 9.0) next();
    ringR += dt * (1.2f + 0.6f * drive);
    ringAmp *= std::exp(-dt * 1.6f);
    clock += f.delta * f.speed * (0.7 + 0.9 * drive);
    yaw += f.delta * f.speed * (0.06 + 0.12 * drive);
  }

  void render(const Frame& f, Canvas& c) const override {
    float amp = f.intensity;
    float s = std::min(f.width, f.height);
    std::vector<float> u;
    u.reserve(20);
    u.insert(u.end(), {float(std::fmod(clock, 1000.0)), bass * amp, kick * amp, energy});
    u.insert(u.end(), {f.glow, spark * amp, flash * amp, 0.0f});
    for (int i = 0; i < 4; i++) u.insert(u.end(), {f.colors[i].r, f.colors[i].g, f.colors[i].b});
    c.material("rain_room", {0, 0, f.width, f.height}, u);

    int n = int(14.0f + 4.0f * std::clamp(f.detail, 0.25f, 2.0f));
    float t = float(std::fmod(clock, 6283.0));
    float e = morph * morph * (3.0f - 2.0f * morph);
    float cy = float(std::cos(yaw)), sy = float(std::sin(yaw));
    const float pitch = 0.62f;
    float cp = std::cos(pitch), sp = std::sin(pitch);
    float scale = s * 0.95f, focal = 2.8f;
    float cx = f.width * 0.5f, cyScreen = f.height * 0.5f;
    float heightGain = (0.9f + 1.0f * bass) * amp;
    std::vector<Drop> drops;
    drops.reserve(size_t(n * n));
    for (int i = 0; i < n; i++) {
      for (int j = 0; j < n; j++) {
        float x = -1.0f + 2.0f * float(i) / float(n - 1);
        float z = -1.0f + 2.0f * float(j) / float(n - 1);
        float r = std::sqrt(x * x + z * z);
        float h = shape(shapeA, x, z, t) + (shape(shapeB, x, z, t) - shape(shapeA, x, z, t)) * e;
        h *= heightGain;
        h += 0.55f * ringAmp * amp * std::exp(-(r - ringR) * (r - ringR) * 10.0f);
        // Giro alrededor del eje vertical e inclinación de la cámara.
        float rx = x * cy - z * sy, rz = x * sy + z * cy;
        float vy = h * cp - rz * sp;
        float vz = h * sp + rz * cp;
        float depth = vz + focal;
        float k = focal / depth;
        Drop d;
        d.x = cx + rx * scale * k;
        d.y = cyScreen - vy * scale * k;
        d.depth = depth;
        d.radius = s * 0.021f * k;
        d.light = 0.75f + 0.9f * std::clamp(h + 0.3f, 0.0f, 1.0f);
        drops.push_back(d);
      }
    }
    // Pintor: primero las gotas lejanas.
    std::vector<int> order(drops.size());
    for (size_t i = 0; i < order.size(); i++) order[i] = int(i);
    std::stable_sort(order.begin(), order.end(), [&](int a, int b) { return drops[a].depth > drops[b].depth; });

    const Color& copper = f.colors[1];
    const Color& champagne = f.colors[2];
    const Color& shadow = f.colors[3];
    float shine = 1.15f + 0.7f * kick * amp + 0.3f * spark * amp + 0.4f * flash * amp;
    // Halo cálido detrás de las gotas.
    std::vector<Vec2> centers;
    centers.reserve(drops.size());
    for (const auto& d : drops) centers.push_back({d.x, d.y});
    Paint halo;
    halo.blend = Blend::plus;
    halo.color = {copper.r, copper.g, copper.b, std::clamp(0.05f * f.glow * shine, 0.0f, 1.0f)};
    c.points(centers, s * 0.04f, halo);
    for (int idx : order) {
      const Drop& d = drops[idx];
      float L = std::min(d.light * shine, 2.0f);
      auto mixc = [](const Color& a, const Color& b, float t, float g) {
        return Color{std::min(1.0f, (a.r + (b.r - a.r) * t) * g), std::min(1.0f, (a.g + (b.g - a.g) * t) * g),
                     std::min(1.0f, (a.b + (b.b - a.b) * t) * g), 1.0f};
      };
      Color hi = mixc(champagne, Color{1, 1, 1, 1}, 0.25f, std::min(L, 1.2f));
      Color mid = mixc(copper, champagne, 0.15f, L * 0.8f);
      Color dark = mixc(shadow, copper, 0.2f, 0.6f);
      Vec2 hot{d.x - d.radius * 0.35f, d.y - d.radius * 0.4f};
      Paint drop = Paint::radial(hot, d.radius * 1.35f, {hi, mid, dark}, {0.0f, 0.45f, 1.0f});
      c.circle({d.x, d.y}, d.radius, drop);
    }
  }
};

