visuals.nativeSource:
class Visual final : public Scene {
  static constexpr int kMaxKeys = 48;
  static constexpr int kMaxNotes = 320;
  struct Note { int key; double start, end; };
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  // Relojes en doble precisión: la escena sin música es idéntica a 30 y 60 FPS.
  double clock = 0, nextNote = 0;
  int keys = 0, step = 0;
  Random rng{1};
  std::vector<Note> notes;
  std::array<int, kMaxKeys> activeNote{};
  std::array<float, kMaxKeys> level{};
  std::array<double, kMaxKeys> lastEnd{};

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

  static bool isBlack(int key) {
    int k = key % 12;
    return k == 1 || k == 3 || k == 6 || k == 8 || k == 10;
  }

  void start(int key, double when, double end) {
    if (int(notes.size()) >= kMaxNotes) return;
    notes.push_back({key, when, end});
    if (end < 0.0) activeNote[size_t(key)] = int(notes.size()) - 1;
  }

  // Melodía sin música: arpegios sobre I–V–vi–IV.
  void schedule(double when, int voices) {
    static const int chords[4][3] = {{0, 4, 7}, {7, 11, 14}, {9, 12, 16}, {5, 9, 12}};
    int bar = (step / 8) % 4;
    int beat = step % 8;
    int octaves = std::max(1, keys / 12);
    int base = 12 * std::max(0, octaves / 2 - 1);
    const int* ch = chords[bar];
    int note = base + ch[beat % 3] + (beat >= 3 && beat < 6 ? 12 : 0);
    double len = 0.18 + 0.25 * double(rng.unit());
    if (note < keys) start(note, when, when + len);
    if (beat == 0) {
      // La mitad de las voces sostiene el acorde: grave, aguda y, con más
      // voces, dos notas más arriba.
      const int held[4] = {std::max(0, base - 12 + ch[0]), base + 12 + ch[2], base + 24 + ch[0], base + 24 + ch[1]};
      const double from[4] = {0.0, 0.02, 0.04, 0.06};
      const double to[4] = {1.6, 0.9, 0.9, 0.9};
      for (int v = 0; v < std::min(4, voices / 2); v++)
        if (held[v] < keys) start(held[v], when + from[v], when + to[v]);
    }
    step++;
  }

 public:
  void reset(uint32_t seed) override {
    rng = Random(seed);
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    clock = 0;
    nextNote = 0.2;
    keys = 0;
    step = 0;
    notes.clear();
    notes.reserve(kMaxNotes);
    activeNote.fill(-1);
    level.fill(0);
    lastEnd.fill(-10.0);
  }

  void update(const Frame& f) override {
    auto m = modifiers(f);
    float dt = float(f.delta);
    const Music& mu = f.music;
    bass = follow(bass, mu.bass, 22.0f, 4.5f, dt);
    body = follow(body, mu.body, 12.0f, 3.0f, dt);
    spark = follow(spark, mu.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, mu.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, mu.active ? std::pow(std::clamp(mu.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : mu.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : mu.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : mu.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((mu.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, mu.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    bool beat = hit > kick + 0.2f;
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));

    int k = std::clamp(m.octavas, 1, 4) * 12;
    if (k != keys) {
      keys = k;
      notes.clear();
      activeNote.fill(-1);
    }
    clock += f.delta * f.speed;
    if (mu.active) {
      // Cada tecla escucha su parte del espectro.
      float mean = 0;
      for (int i = 0; i < keys; i++) {
        float pos = float(i) / float(keys - 1) * 28.0f;
        int b = int(pos);
        float fr = pos - float(b);
        float v = mu.smoothSpectrum[size_t(b)] * (1.0f - fr) + mu.smoothSpectrum[size_t(std::min(b + 1, 30))] * fr;
        level[size_t(i)] = follow(level[size_t(i)], v, 30.0f, 8.0f, dt);
        mean += level[size_t(i)];
      }
      mean /= float(keys);
      float thr = std::max(0.16f, mean + 0.07f);
      // Sólo las que más destacan pueden sonar.
      std::array<int, kMaxKeys> order{};
      for (int i = 0; i < keys; i++) order[size_t(i)] = i;
      std::sort(order.begin(), order.begin() + keys, [&](int a, int b) { return level[size_t(a)] > level[size_t(b)]; });
      // Notas a la vez: de la más fuerte a la más débil, cada tecla separada
      // de las elegidas toma una voz si supera su umbral. La primera necesita
      // destacar de verdad; cada voz extra se conforma con un poco menos (sin
      // bajar de la media). Una nota que ya suena sigue mientras no se apague.
      std::array<bool, kMaxKeys> allowed{};
      int voices = std::clamp(m.voces, 1, 8);
      const float floorBar = std::max(0.12f, mean + 0.02f);
      int chosen = 0;
      for (int r = 0; r < keys && chosen < voices; r++) {
        int key = order[size_t(r)];
        const float need = activeNote[size_t(key)] >= 0
            ? thr - 0.08f
            : std::max(floorBar, thr + 0.03f - 0.025f * float(chosen));
        if (level[size_t(key)] <= need) continue;
        bool spaced = true;
        for (int d = -2; d <= 2 && spaced; d++) {
          int nb = key + d;
          if (d == 0 || nb < 0 || nb >= keys) continue;
          if (allowed[size_t(nb)]) spaced = false;
        }
        if (spaced) {
          allowed[size_t(key)] = true;
          chosen++;
        }
      }
      for (int i = 0; i < keys; i++) {
        int a = activeNote[size_t(i)];
        float v = level[size_t(i)];
        if (a >= 0) {
          // Cada nota dura al menos un instante: así no salta de tecla en tecla.
          Note& note = notes[size_t(a)];
          double age = clock - note.start;
          if (age > 0.14 && (!allowed[size_t(i)] || v < thr - 0.08f || age > 1.6)) {
            note.end = clock;
            activeNote[size_t(i)] = -1;
            lastEnd[size_t(i)] = clock;
          }
        } else if (allowed[size_t(i)] && clock - lastEnd[size_t(i)] > 0.1) {
          start(i, clock, -1.0);
        }
      }
      // Cada golpe toca la nota grave que más suena.
      if (beat) {
        int best = 0;
        for (int i = 1; i < keys / 3; i++) if (level[size_t(i)] > level[size_t(best)]) best = i;
        if (activeNote[size_t(best)] < 0) start(best, clock, clock + 0.25 + 0.3 * double(hit));
      }
    } else {
      for (int i = 0; i < keys; i++) {
        int a = activeNote[size_t(i)];
        if (a >= 0) {
          notes[size_t(a)].end = clock;
          activeNote[size_t(i)] = -1;
        }
      }
      while (nextNote <= clock) {
        schedule(nextNote, std::clamp(m.voces, 1, 8));
        nextNote += 0.25;
      }
    }
    if (mu.active) nextNote = clock + 0.25;
    // Se borran las notas que ya salieron por arriba.
    double travel = 1.6 / std::max(0.2, double(m.subida));
    size_t before = notes.size();
    notes.erase(std::remove_if(notes.begin(), notes.end(), [&](const Note& n) { return n.end >= 0.0 && clock - n.end > travel; }), notes.end());
    if (notes.size() != before) {
      activeNote.fill(-1);
      for (size_t i = 0; i < notes.size(); i++) if (notes[i].end < 0.0) activeNote[size_t(notes[i].key)] = int(i);
    }
  }

  void render(const Frame& f, Canvas& c) const override {
    auto m = modifiers(f);
    float amp = f.intensity;
    const Color& bg = f.colors[0];
    c.rect({0, 0, f.width, f.height}, Paint::linear({0, 0}, {0, f.height},
                                                   {Color{bg.r, bg.g, bg.b, 1.0f}, Color{std::min(1.0f, bg.r + 0.06f), std::min(1.0f, bg.g + 0.03f), std::min(1.0f, bg.b + 0.08f), 1.0f}}));
    if (keys <= 0) return;
    float px = std::min(f.width, f.height) / 400.0f;
    int whites = 0;
    for (int i = 0; i < keys; i++) if (!isBlack(i)) whites++;
    float ww = f.width / float(whites);
    float keyH = f.height * 0.13f;
    float keyTop = f.height - keyH;
    float speed = f.height * 0.62f * m.subida;
    // Posición horizontal de cada tecla.
    auto keyX = [&](int key, float& w) {
      int wIndex = 0;
      for (int i = 0; i < key; i++) if (!isBlack(i)) wIndex++;
      if (isBlack(key)) {
        w = ww * 0.6f;
        return float(wIndex) * ww - w * 0.5f;
      }
      w = ww;
      return float(wIndex) * ww;
    };
    auto noteColor = [&](int key) {
      int oct = key / 12 % 3;
      const Color& base = f.colors[size_t(1 + oct)];
      return isBlack(key) ? Color{base.r * 0.8f, base.g * 0.8f, base.b * 0.85f, 1.0f} : base;
    };
    // Guías de octava.
    Path guides;
    for (int o = 0; o <= keys / 12; o++) {
      float x = float(o * 7) * ww;
      guides.moveTo(x, 0).lineTo(x, keyTop);
    }
    Paint gp;
    gp.strokeWidth = 1.0f * px;
    gp.color = Color{1, 1, 1, 0.06f};
    c.path(guides, gp);
    // Notas: barras redondeadas por color.
    std::array<bool, kMaxKeys> pressed{};
    for (const auto& n : notes) {
      float w;
      float x = keyX(n.key, w);
      float yTop = keyTop - float(clock - n.start) * speed;
      float yBottom = n.end < 0.0 ? keyTop : keyTop - float(clock - n.end) * speed;
      if (n.end < 0.0 || clock - n.end < 0.05) pressed[size_t(n.key)] = true;
      if (yBottom < 0.0f) continue;
      Color col = noteColor(n.key);
      float lit = (0.85f + 0.3f * bass + 0.2f * kick) * amp;
      Rect r{x + w * 0.1f, std::max(yTop, -10.0f), w * 0.8f, std::max(yBottom - std::max(yTop, -10.0f), 2.0f)};
      if (m.brillo) {
        Paint halo;
        halo.blend = Blend::plus;
        halo.color = col.opacity(std::clamp(0.18f * f.glow * amp, 0.0f, 1.0f));
        c.rect({r.x - 4.0f * px, r.y - 4.0f * px, r.width + 8.0f * px, r.height + 8.0f * px}, halo);
      }
      Paint body;
      body.color = Color{std::min(1.0f, col.r * lit), std::min(1.0f, col.g * lit), std::min(1.0f, col.b * lit), 1.0f};
      c.rect(r, body);
      Paint edge;
      edge.blend = Blend::plus;
      edge.color = Color{1.0f, 0.95f, 0.85f, std::clamp(0.45f * amp, 0.0f, 1.0f)};
      c.rect({r.x, r.y, r.width, 2.0f * px}, edge);
    }
    // Línea de luz sobre el teclado.
    Paint bar = Paint::linear({0, keyTop - 10.0f * px}, {0, keyTop}, {f.colors[2].opacity(0.0f), f.colors[2].opacity(std::clamp((0.35f + 0.4f * kick) * amp, 0.0f, 1.0f))});
    c.rect({0, keyTop - 10.0f * px, f.width, 10.0f * px}, bar);
    // Teclado: blancas y luego negras.
    for (int pass = 0; pass < 2; pass++) {
      for (int i = 0; i < keys; i++) {
        if (isBlack(i) != (pass == 1)) continue;
        float w;
        float x = keyX(i, w);
        float h = isBlack(i) ? keyH * 0.62f : keyH;
        Paint kp;
        if (pressed[size_t(i)]) {
          Color col = noteColor(i);
          kp.color = Color{std::min(1.0f, col.r * 1.1f), std::min(1.0f, col.g * 1.1f), std::min(1.0f, col.b * 1.1f), 1.0f};
        } else {
          kp.color = isBlack(i) ? Color{0.06f, 0.05f, 0.07f, 1.0f} : Color{0.93f, 0.91f, 0.88f, 1.0f};
        }
        c.rect({x + 0.8f * px, keyTop, w - 1.6f * px, h}, kp);
      }
    }
    if (flash > 0.01f) {
      Paint fl;
      fl.blend = Blend::plus;
      fl.color = f.colors[2].opacity(std::clamp(flash * 0.05f * amp, 0.0f, 1.0f));
      c.rect({0, 0, f.width, f.height}, fl);
    }
  }
};

class Visual final : public Scene {
  static constexpr int kMaxKeys = 48;
  static constexpr int kMaxNotes = 320;
  struct Note { int key; double start, end; };
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  // Relojes en doble precisión: la escena sin música es idéntica a 30 y 60 FPS.
  double clock = 0, nextNote = 0;
  int keys = 0, step = 0;
  Random rng{1};
  std::vector<Note> notes;
  std::array<int, kMaxKeys> activeNote{};
  std::array<float, kMaxKeys> level{};
  std::array<double, kMaxKeys> lastEnd{};

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

  static bool isBlack(int key) {
    int k = key % 12;
    return k == 1 || k == 3 || k == 6 || k == 8 || k == 10;
  }

  void start(int key, double when, double end) {
    if (int(notes.size()) >= kMaxNotes) return;
    notes.push_back({key, when, end});
    if (end < 0.0) activeNote[size_t(key)] = int(notes.size()) - 1;
  }

  // Melodía sin música: arpegios sobre I–V–vi–IV.
  void schedule(double when, int voices) {
    static const int chords[4][3] = {{0, 4, 7}, {7, 11, 14}, {9, 12, 16}, {5, 9, 12}};
    int bar = (step / 8) % 4;
    int beat = step % 8;
    int octaves = std::max(1, keys / 12);
    int base = 12 * std::max(0, octaves / 2 - 1);
    const int* ch = chords[bar];
    int note = base + ch[beat % 3] + (beat >= 3 && beat < 6 ? 12 : 0);
    double len = 0.18 + 0.25 * double(rng.unit());
    if (note < keys) start(note, when, when + len);
    if (beat == 0) {
      // La mitad de las voces sostiene el acorde: grave, aguda y, con más
      // voces, dos notas más arriba.
      const int held[4] = {std::max(0, base - 12 + ch[0]), base + 12 + ch[2], base + 24 + ch[0], base + 24 + ch[1]};
      const double from[4] = {0.0, 0.02, 0.04, 0.06};
      const double to[4] = {1.6, 0.9, 0.9, 0.9};
      for (int v = 0; v < std::min(4, voices / 2); v++)
        if (held[v] < keys) start(held[v], when + from[v], when + to[v]);
    }
    step++;
  }

 public:
  void reset(uint32_t seed) override {
    rng = Random(seed);
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    clock = 0;
    nextNote = 0.2;
    keys = 0;
    step = 0;
    notes.clear();
    notes.reserve(kMaxNotes);
    activeNote.fill(-1);
    level.fill(0);
    lastEnd.fill(-10.0);
  }

  void update(const Frame& f) override {
    auto m = modifiers(f);
    float dt = float(f.delta);
    const Music& mu = f.music;
    bass = follow(bass, mu.bass, 22.0f, 4.5f, dt);
    body = follow(body, mu.body, 12.0f, 3.0f, dt);
    spark = follow(spark, mu.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, mu.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, mu.active ? std::pow(std::clamp(mu.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : mu.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : mu.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : mu.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((mu.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, mu.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    bool beat = hit > kick + 0.2f;
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));

    int k = std::clamp(m.octavas, 1, 4) * 12;
    if (k != keys) {
      keys = k;
      notes.clear();
      activeNote.fill(-1);
    }
    clock += f.delta * f.speed;
    if (mu.active) {
      // Cada tecla escucha su parte del espectro.
      float mean = 0;
      for (int i = 0; i < keys; i++) {
        float pos = float(i) / float(keys - 1) * 28.0f;
        int b = int(pos);
        float fr = pos - float(b);
        float v = mu.smoothSpectrum[size_t(b)] * (1.0f - fr) + mu.smoothSpectrum[size_t(std::min(b + 1, 30))] * fr;
        level[size_t(i)] = follow(level[size_t(i)], v, 30.0f, 8.0f, dt);
        mean += level[size_t(i)];
      }
      mean /= float(keys);
      float thr = std::max(0.16f, mean + 0.07f);
      // Sólo las que más destacan pueden sonar.
      std::array<int, kMaxKeys> order{};
      for (int i = 0; i < keys; i++) order[size_t(i)] = i;
      std::sort(order.begin(), order.begin() + keys, [&](int a, int b) { return level[size_t(a)] > level[size_t(b)]; });
      // Notas a la vez: de la más fuerte a la más débil, cada tecla separada
      // de las elegidas toma una voz si supera su umbral. La primera necesita
      // destacar de verdad; cada voz extra se conforma con un poco menos (sin
      // bajar de la media). Una nota que ya suena sigue mientras no se apague.
      std::array<bool, kMaxKeys> allowed{};
      int voices = std::clamp(m.voces, 1, 8);
      const float floorBar = std::max(0.12f, mean + 0.02f);
      int chosen = 0;
      for (int r = 0; r < keys && chosen < voices; r++) {
        int key = order[size_t(r)];
        const float need = activeNote[size_t(key)] >= 0
            ? thr - 0.08f
            : std::max(floorBar, thr + 0.03f - 0.025f * float(chosen));
        if (level[size_t(key)] <= need) continue;
        bool spaced = true;
        for (int d = -2; d <= 2 && spaced; d++) {
          int nb = key + d;
          if (d == 0 || nb < 0 || nb >= keys) continue;
          if (allowed[size_t(nb)]) spaced = false;
        }
        if (spaced) {
          allowed[size_t(key)] = true;
          chosen++;
        }
      }
      for (int i = 0; i < keys; i++) {
        int a = activeNote[size_t(i)];
        float v = level[size_t(i)];
        if (a >= 0) {
          // Cada nota dura al menos un instante: así no salta de tecla en tecla.
          Note& note = notes[size_t(a)];
          double age = clock - note.start;
          if (age > 0.14 && (!allowed[size_t(i)] || v < thr - 0.08f || age > 1.6)) {
            note.end = clock;
            activeNote[size_t(i)] = -1;
            lastEnd[size_t(i)] = clock;
          }
        } else if (allowed[size_t(i)] && clock - lastEnd[size_t(i)] > 0.1) {
          start(i, clock, -1.0);
        }
      }
      // Cada golpe toca la nota grave que más suena.
      if (beat) {
        int best = 0;
        for (int i = 1; i < keys / 3; i++) if (level[size_t(i)] > level[size_t(best)]) best = i;
        if (activeNote[size_t(best)] < 0) start(best, clock, clock + 0.25 + 0.3 * double(hit));
      }
    } else {
      for (int i = 0; i < keys; i++) {
        int a = activeNote[size_t(i)];
        if (a >= 0) {
          notes[size_t(a)].end = clock;
          activeNote[size_t(i)] = -1;
        }
      }
      while (nextNote <= clock) {
        schedule(nextNote, std::clamp(m.voces, 1, 8));
        nextNote += 0.25;
      }
    }
    if (mu.active) nextNote = clock + 0.25;
    // Se borran las notas que ya salieron por arriba.
    double travel = 1.6 / std::max(0.2, double(m.subida));
    size_t before = notes.size();
    notes.erase(std::remove_if(notes.begin(), notes.end(), [&](const Note& n) { return n.end >= 0.0 && clock - n.end > travel; }), notes.end());
    if (notes.size() != before) {
      activeNote.fill(-1);
      for (size_t i = 0; i < notes.size(); i++) if (notes[i].end < 0.0) activeNote[size_t(notes[i].key)] = int(i);
    }
  }

  void render(const Frame& f, Canvas& c) const override {
    auto m = modifiers(f);
    float amp = f.intensity;
    if (keys <= 0) return;
    float px = std::min(f.width, f.height) / 400.0f;
    int whites = 0;
    for (int i = 0; i < keys; i++) if (!isBlack(i)) whites++;
    float ww = f.width / float(whites);
    float keyH = f.height * 0.13f;
    float keyTop = f.height - keyH;
    float speed = f.height * 0.62f * m.subida;
    // Posición horizontal de cada tecla.
    auto keyX = [&](int key, float& w) {
      int wIndex = 0;
      for (int i = 0; i < key; i++) if (!isBlack(i)) wIndex++;
      if (isBlack(key)) {
        w = ww * 0.6f;
        return float(wIndex) * ww - w * 0.5f;
      }
      w = ww;
      return float(wIndex) * ww;
    };
    auto noteColor = [&](int key) {
      int oct = key / 12 % 3;
      const Color& base = f.colors[size_t(1 + oct)];
      return isBlack(key) ? Color{base.r * 0.8f, base.g * 0.8f, base.b * 0.85f, 1.0f} : base;
    };
    // Guías de octava.
    Path guides;
    for (int o = 0; o <= keys / 12; o++) {
      float x = float(o * 7) * ww;
      guides.moveTo(x, 0).lineTo(x, keyTop);
    }
    Paint gp;
    gp.strokeWidth = 1.0f * px;
    gp.color = Color{1, 1, 1, 0.06f};
    c.path(guides, gp);
    // Notas: barras redondeadas por color.
    std::array<bool, kMaxKeys> pressed{};
    for (const auto& n : notes) {
      float w;
      float x = keyX(n.key, w);
      float yTop = keyTop - float(clock - n.start) * speed;
      float yBottom = n.end < 0.0 ? keyTop : keyTop - float(clock - n.end) * speed;
      if (n.end < 0.0 || clock - n.end < 0.05) pressed[size_t(n.key)] = true;
      if (yBottom < 0.0f) continue;
      Color col = noteColor(n.key);
      float lit = (0.85f + 0.3f * bass + 0.2f * kick) * amp;
      Rect r{x + w * 0.1f, std::max(yTop, -10.0f), w * 0.8f, std::max(yBottom - std::max(yTop, -10.0f), 2.0f)};
      if (m.brillo) {
        Paint halo;
        halo.blend = Blend::plus;
        halo.color = col.opacity(std::clamp(0.18f * f.glow * amp, 0.0f, 1.0f));
        c.rect({r.x - 4.0f * px, r.y - 4.0f * px, r.width + 8.0f * px, r.height + 8.0f * px}, halo);
      }
      Paint body;
      body.color = Color{std::min(1.0f, col.r * lit), std::min(1.0f, col.g * lit), std::min(1.0f, col.b * lit), 1.0f};
      c.rect(r, body);
      Paint edge;
      edge.blend = Blend::plus;
      edge.color = Color{1.0f, 0.95f, 0.85f, std::clamp(0.45f * amp, 0.0f, 1.0f)};
      c.rect({r.x, r.y, r.width, 2.0f * px}, edge);
    }
    // Línea de luz sobre el teclado.
    Paint bar = Paint::linear({0, keyTop - 10.0f * px}, {0, keyTop}, {f.colors[2].opacity(0.0f), f.colors[2].opacity(std::clamp((0.35f + 0.4f * kick) * amp, 0.0f, 1.0f))});
    c.rect({0, keyTop - 10.0f * px, f.width, 10.0f * px}, bar);
    // Teclado: blancas y luego negras.
    for (int pass = 0; pass < 2; pass++) {
      for (int i = 0; i < keys; i++) {
        if (isBlack(i) != (pass == 1)) continue;
        float w;
        float x = keyX(i, w);
        float h = isBlack(i) ? keyH * 0.62f : keyH;
        Paint kp;
        if (pressed[size_t(i)]) {
          Color col = noteColor(i);
          kp.color = Color{std::min(1.0f, col.r * 1.1f), std::min(1.0f, col.g * 1.1f), std::min(1.0f, col.b * 1.1f), 1.0f};
        } else {
          kp.color = isBlack(i) ? Color{0.06f, 0.05f, 0.07f, 1.0f} : Color{0.93f, 0.91f, 0.88f, 1.0f};
        }
        c.rect({x + 0.8f * px, keyTop, w - 1.6f * px, h}, kp);
      }
    }
  }
};

class Visual final : public Scene {
  static constexpr int kMax = 400;
  static constexpr double kStep = 1.0 / 60.0;
  struct Fly { float x, y, depth, ax, ay, fx, fy, px, py, omega; double phase; };
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  // Relojes en doble precisión: la escena sin música es idéntica a 30 y 60 FPS.
  double sim = 0, cycle = 0;
  int64_t steps = 0;
  float pendingKick = 0, order = 0;
  Random rng{1};
  std::array<Fly, kMax> flies{};

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

  void scatter() {
    for (auto& fl : flies) fl.phase = double(rng.unit());
  }

 public:
  void reset(uint32_t seed) override {
    rng = Random(seed);
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    sim = 0;
    cycle = 0;
    steps = 0;
    pendingKick = 0;
    order = 0;
    for (auto& fl : flies) {
      fl.x = rng.unit();
      fl.y = rng.unit();
      fl.depth = 0.35f + 0.65f * rng.unit();
      fl.ax = 0.01f + 0.03f * rng.unit();
      fl.ay = 0.01f + 0.03f * rng.unit();
      fl.fx = 0.1f + 0.3f * rng.unit();
      fl.fy = 0.1f + 0.3f * rng.unit();
      fl.px = rng.unit() * 6.28f;
      fl.py = rng.unit() * 6.28f;
      fl.omega = 0.85f + 0.3f * rng.unit();
      fl.phase = double(rng.unit());
    }
  }

  void update(const Frame& f) override {
    auto m = modifiers(f);
    float dt = float(f.delta);
    const Music& mu = f.music;
    bass = follow(bass, mu.bass, 22.0f, 4.5f, dt);
    body = follow(body, mu.body, 12.0f, 3.0f, dt);
    spark = follow(spark, mu.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, mu.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, mu.active ? std::pow(std::clamp(mu.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : mu.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : mu.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : mu.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((mu.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, mu.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    if (hit > kick + 0.2f) pendingKick = std::max(pendingKick, hit);
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));

    int n = std::clamp(m.cantidad, 10, kMax);
    sim += f.delta * f.speed;
    int64_t target = int64_t(std::floor(sim / kStep + 1e-6));
    if (target - steps > 30) steps = target - 30;
    while (steps < target) {
      steps++;
      cycle += kStep;
      // Sin música: 24 s de sincronía creciente y luego se desordenan.
      if (!mu.active && cycle > 24.0) {
        cycle -= 24.0;
        scatter();
      }
      float ramp = float(std::min(cycle / 16.0, 1.0));
      float K = m.sincronia * (mu.active ? 0.6f + 0.6f * drive : 1.6f * ramp * ramp);
      double cs = 0, sn = 0;
      for (int i = 0; i < n; i++) {
        double a = flies[size_t(i)].phase * 6.283185307179586;
        cs += std::cos(a);
        sn += std::sin(a);
      }
      cs /= n;
      sn /= n;
      double R = std::sqrt(cs * cs + sn * sn);
      double psi = std::atan2(sn, cs);
      order = float(R);
      for (int i = 0; i < n; i++) {
        Fly& fy = flies[size_t(i)];
        double a = fy.phase * 6.283185307179586;
        double d = double(fy.omega) + double(K) * R * std::sin(psi - a) / 6.283185307179586 * 6.0;
        fy.phase += d * kStep;
        // Un golpe adelanta los relojes hacia el destello.
        if (pendingKick > 0.0f) fy.phase += 0.12 * double(pendingKick) * std::sin(-a) / 6.283185307179586 * 6.0;
        fy.phase -= std::floor(fy.phase);
      }
      pendingKick = 0;
    }
  }

  void render(const Frame& f, Canvas& c) const override {
    auto m = modifiers(f);
    float amp = f.intensity;
    const Color& bg = f.colors[0];
    int n = std::clamp(m.cantidad, 10, kMax);
    // Brillo general: cuánto destellan juntas ahora mismo.
    float together = 0;
    for (int i = 0; i < n; i++) together += std::exp(-float(flies[size_t(i)].phase) * 7.0f);
    together /= float(n);
    std::array<Color, 4> cols = {f.colors[1], f.colors[2], f.colors[3], f.colors[1]};
    int cm = std::clamp(m.color, 0, 3);
    const Color& main = cm == 3 ? f.colors[1] : cols[size_t(cm)];
    Color glowCol = main;
    c.rect({0, 0, f.width, f.height}, Paint::radial({f.width * 0.5f, f.height * 0.65f}, std::max(f.width, f.height) * 0.75f,
                                                   {Color{std::min(1.0f, bg.r + glowCol.r * 0.18f * together * amp + 0.02f), std::min(1.0f, bg.g + glowCol.g * 0.18f * together * amp + 0.03f),
                                                          std::min(1.0f, bg.b + glowCol.b * 0.18f * together * amp + 0.02f), 1.0f},
                                                    Color{bg.r, bg.g, bg.b, 1.0f}}));
    float side = std::min(f.width, f.height);
    float px = side / 400.0f;
    double t = sim * m.deriva;
    // Grupos: 5 niveles de brillo × 2 profundidades × 2 colores.
    std::array<std::vector<Vec2>, 20> groups;
    std::vector<Vec2> dim;
    dim.reserve(size_t(n));
    for (auto& g : groups) g.reserve(size_t(n / 4));
    for (int i = 0; i < n; i++) {
      const Fly& fy = flies[size_t(i)];
      float x = (fy.x + fy.ax * float(std::sin(t * double(fy.fx) + double(fy.px)))) * f.width;
      float y = (fy.y + fy.ay * float(std::sin(t * double(fy.fy) + double(fy.py)))) * f.height;
      float b = std::exp(-float(fy.phase) * 7.0f);
      if (b < 0.06f) {
        dim.push_back({x, y});
        continue;
      }
      int level = std::min(4, int(b * 5.0f));
      int depth = fy.depth > 0.65f ? 1 : 0;
      int colorIdx = cm == 3 ? (i % 2) : 0;
      groups[size_t(level * 4 + depth * 2 + colorIdx)].push_back({x, y});
    }
    // Entre destellos se ven tenues, como brasas.
    Paint dimHalo;
    dimHalo.blend = Blend::plus;
    dimHalo.color = main.opacity(0.06f);
    c.points(dim, 5.0f * px, dimHalo);
    Paint dimP;
    dimP.blend = Blend::plus;
    dimP.color = main.opacity(0.35f);
    c.points(dim, 1.6f * px, dimP);
    for (int level = 0; level < 5; level++) {
      float b = (0.2f + 0.2f * float(level)) * amp;
      for (int depth = 0; depth < 2; depth++) {
        for (int ci = 0; ci < 2; ci++) {
          const auto& pts = groups[size_t(level * 4 + depth * 2 + ci)];
          if (pts.empty()) continue;
          const Color& col = ci == 0 ? main : f.colors[2];
          float size = (depth == 1 ? 1.0f : 0.6f) * px;
          Paint halo;
          halo.blend = Blend::plus;
          halo.color = col.opacity(std::clamp(b * 0.22f * f.glow, 0.0f, 1.0f));
          c.points(pts, size * (10.0f + 4.0f * bass), halo);
          Paint core;
          core.blend = Blend::plus;
          core.color = Color{std::min(1.0f, col.r * 0.6f + 0.4f), std::min(1.0f, col.g * 0.6f + 0.4f), std::min(1.0f, col.b * 0.6f + 0.4f), std::clamp(b, 0.0f, 1.0f)};
          c.points(pts, size * 2.6f, core);
        }
      }
    }
    if (flash > 0.01f) {
      Paint fl;
      fl.blend = Blend::plus;
      fl.color = main.opacity(std::clamp(flash * 0.05f * amp, 0.0f, 1.0f));
      c.rect({0, 0, f.width, f.height}, fl);
    }
  }
};

class Visual final : public Scene {
