      fl.ay = 0.01f + 0.03f * rng.unit();
      fl.fx = 0.1f + 0.3f * rng.unit();
      fl.fy = 0.1f + 0.3f * rng.unit();
      fl.px = rng.unit() * 6.28f;
      fl.py = rng.unit() * 6.28f;
