          core.blend = Blend::plus;
          core.color = Color{std::min(1.0f, col.r * 0.6f + 0.4f), std::min(1.0f, col.g * 0.6f + 0.4f), std::min(1.0f, col.b * 0.6f + 0.4f), std::clamp(b, 0.0f, 1.0f)};
