    u.insert(u.end(), {m.calor, float(m.placas), m.brasas ? 1.0f : 0.0f, flash * amp});
    u.insert(u.end(), {float(std::fmod(drift, 1000.0)), f.glow, heat * amp, float(std::fmod(rise, 1000.0))});
