  float kick = 0, flash = 0, drive = 0;
  // Relojes en doble precisión: la escena sin música es idéntica a 30 y 60 FPS.
  double flow = 0, drift = 0, rise = 0;
  float heat = 0;

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    flow = rng.unit() * 50.0;
    drift = rng.unit() * 50.0;
    rise = 0;
    heat = 0;
  }

  void update(const Frame& f) override {
    auto m = modifiers(f);
    float dt = float(f.delta);
    const Music& mu = f.music;
    bass = follow(bass, mu.bass, 22.0f, 4.5f, dt);
    body = follow(body, mu.body, 12.0f, 3.0f, dt);
    spark = follow(spark, mu.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, mu.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, mu.active ? std::pow(std::clamp(mu.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : mu.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : mu.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : mu.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((mu.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, mu.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    if (hit > kick + 0.2f) heat = std::max(heat, hit);
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    heat *= std::exp(-dt * 2.0f);
    flow += f.delta * f.speed * m.flujo * (0.15 + 0.5 * drive);
    drift += f.delta * f.speed * (0.02 + 0.05 * drive);
    rise += f.delta * f.speed * (0.25 + 0.6 * drive + 0.8 * heat);
  }

  void render(const Frame& f, Canvas& c) const override {
    auto m = modifiers(f);
    float amp = f.intensity;
    std::vector<float> u;
    u.reserve(24);
    u.insert(u.end(), {float(std::fmod(flow, 1000.0)), bass * amp, kick * amp, energy});
    u.insert(u.end(), {m.calor, float(m.placas), m.brasas ? 1.0f : 0.0f, flash * amp});
    u.insert(u.end(), {float(std::fmod(drift, 1000.0)), f.glow, heat * amp, float(std::fmod(rise, 1000.0))});
    for (int i = 0; i < 4; i++) u.insert(u.end(), {f.colors[i].r, f.colors[i].g, f.colors[i].b});
    c.material("magma_crust", {0, 0, f.width, f.height}, u);
  }
};

shaderSources.magma_crust:
#version 460 core
#include <flutter/runtime_effect.glsl>
uniform vec2 uSize;
uniform vec4 uA;   // flujo de lava, graves, golpe, energía
uniform vec4 uB;   // calor, tamaño de placas, brasas, destello
uniform vec4 uD;   // deriva de las placas, glow, fogonazo de calor, subida de brasas
uniform vec3 uC0;
uniform vec3 uC1;
uniform vec3 uC2;
uniform vec3 uC3;
out vec4 fragColor;

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

vec2 hash22(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973));
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.xx + p3.yz) * p3.zy);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash12(i), hash12(i + vec2(1.0, 0.0)), u.x),
             mix(hash12(i + vec2(0.0, 1.0)), hash12(i + vec2(1.0, 1.0)), u.x), u.y);
}

void main() {
  vec2 frag = FlutterFragCoord().xy;
  float scale = min(uSize.x, uSize.y);
  vec2 p = frag / scale;
  vec2 g = p * (12.0 / uB.y);
  // Placas de corteza: celdas de Voronoi que se desplazan muy despacio.
  vec2 gi = floor(g);
  vec2 gf = fract(g);
  float d1 = 8.0;
  float d2 = 8.0;
  vec2 nearest = vec2(0.0);
  for (int j = -1; j <= 1; j++) {
    for (int i = -1; i <= 1; i++) {
      vec2 cell = gi + vec2(float(i), float(j));
      vec2 h = hash22(cell);
      vec2 o = vec2(float(i), float(j)) + 0.5 + 0.38 * sin(uD.x * (0.6 + h) + h * 6.2831);
      float d = length(gf - o);
      if (d < d1) {
        d2 = d1;
        d1 = d;
        nearest = cell;
      } else if (d < d2) {
        d2 = d;
      }
    }
  }
  float edge = d2 - d1;
  // Grieta: más ancha y brillante con los graves y el calor.
  float width = (0.035 + 0.05 * uA.y + 0.06 * uD.z) * uB.x;
  float crack = smoothstep(width, width * 0.3, edge);
  // En el overlay el calor queda pegado a las grietas: la roca es transparente.
  float heatGlow = exp(-edge / (width * 1.4));

  // Roca de la corteza: textura oscura con brillo rojizo junto a las grietas.
  float rock = noise(g * 3.0 + nearest * 7.0) * 0.7 + hash12(floor(frag * 0.5)) * 0.3;
  vec3 crust = uC0 + vec3(0.06, 0.04, 0.035) * rock;
  crust += uC1 * heatGlow * (0.25 + 0.5 * uA.y + 0.6 * uD.z) * uB.x;
  vec3 col = crust;
  // Lava que fluye bajo la corteza: sólo se calcula dentro de las grietas.
  if (crack > 0.002) {
    vec2 lp = p * 3.0 + vec2(uA.x * 0.4, -uA.x * 0.25);
    float w = noise(lp * 0.7 + uA.x * 0.1);
    float lava = noise(lp + vec2(w * 2.0, 0.0)) * 0.6 + noise(lp * 2.3 - w) * 0.4;
    vec3 lavaCol = mix(uC1, uC2, smoothstep(0.3, 0.7, lava));
    lavaCol = mix(lavaCol, uC3, smoothstep(0.65, 0.95, lava) * (0.6 + 0.6 * uA.y));
    col = mix(crust, lavaCol * (1.1 + 0.6 * uA.z), crack);
  }

  // Brasas que suben con el calor.
  if (uB.z > 0.5) {
    vec2 eg = vec2(p.x * 22.0, p.y * 22.0 + uD.w * 6.0);
    vec2 ec = floor(eg);
    vec2 el = fract(eg) - 0.5;
    float h = hash12(ec + 3.7);
    vec2 off = vec2(hash12(ec + 1.1), hash12(ec + 9.4)) - 0.5;
    float ember = step(0.94 - 0.05 * uA.z - 0.04 * uD.z, h) * exp(-dot(el - off * 0.6, el - off * 0.6) * 140.0);
    float flicker = 0.6 + 0.4 * sin(uD.w * 9.0 + h * 40.0);
    col += mix(uC2, uC3, h) * ember * flicker * (1.2 + uA.z);
  }
  col *= uD.y * 0.4 + 0.6;
  col *= 1.0 - 0.3 * smoothstep(0.7, 1.5, length((frag - 0.5 * uSize) / scale * vec2(0.9, 0.65)));
  // Fondo transparente: color premultiplicado y opacidad según el brillo; la
  // luz muy tenue se vuelve transparente del todo para no dejar velo.
  col = clamp(col, 0.0, 1.0);
  float veilPeak = max(col.r, max(col.g, col.b));
  float clearCut = smoothstep(0.04, 0.12, veilPeak);
  col *= clearCut;
  float alpha = clamp(veilPeak * 1.25, 0.0, 1.0) * clearCut;
  fragColor = vec4(col, alpha);
}

visuals.nativeSource:
class Visual final : public Scene {
  struct Orbit { float radius, theta0, incl, node, speed, seed; int core; };
  std::vector<Orbit> orbits;
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  // Relojes en doble precisión: la escena sin música es idéntica a 30 y 60 FPS.
  double orbitClock = 0, coreClock = 0;
  float blast = 0, blastVel = 0;

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

  // Posición del núcleo k en unidades del lado corto, centrada en la pantalla.
  void core(int k, float aspectY, float& x, float& y) const {
    double t = coreClock;
    float fk = float(k);
    x = 0.32f * float(std::sin(t * (0.21 + 0.05 * k) + fk * 2.1));
    y = (0.28f + 0.12f * aspectY) * float(std::cos(t * (0.17 + 0.04 * k) + fk * 1.3)) + (fk - 1.0f) * 0.12f * aspectY;
  }

 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    orbits.clear();
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    orbitClock = rng.unit() * 50.0;
    coreClock = rng.unit() * 50.0;
    blast = blastVel = 0;
  }

  void update(const Frame& f) override {
    float dt = float(f.delta);
    if (orbits.empty()) {
      Random rng(f.seed + 7);
      int count = int(1200.0f + 600.0f * std::clamp(f.detail, 0.25f, 2.0f));
      for (int i = 0; i < count; i++) {
        Orbit o;
        o.core = i % 3;
        float u = rng.unit();
        o.radius = 0.04f + 0.30f * u * u;
        o.theta0 = rng.unit() * 6.2831853f;
        o.incl = (rng.unit() - 0.5f) * 2.6f;
        o.node = rng.unit() * 6.2831853f;
        // Más rápido cerca del núcleo, como en una órbita de Kepler.
        o.speed = 0.06f / std::pow(o.radius, 1.5f) * (rng.unit() < 0.5f ? 1.0f : -1.0f) * 0.12f;
        o.seed = rng.unit();
        orbits.push_back(o);
      }
    }
    const Music& m = f.music;
    bass = follow(bass, m.bass, 22.0f, 4.5f, dt);
    body = follow(body, m.body, 12.0f, 3.0f, dt);
    spark = follow(spark, m.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, m.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, m.active ? std::pow(std::clamp(m.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : m.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : m.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : m.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((m.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, m.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    if (hit > kick + 0.2f) blastVel += 3.2f * hit;
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    // Supernova: las órbitas se abren con el golpe y vuelven con un muelle.
    blastVel += (-blast * 14.0f - blastVel * 4.5f) * dt;
    blast += blastVel * dt;
    orbitClock += f.delta * f.speed * (0.6 + 1.2 * drive + 0.6 * std::max(0.0f, blast));
    coreClock += f.delta * f.speed * (0.5 + 0.6 * drive);
  }

  void render(const Frame& f, Canvas& c) const override {
    float amp = f.intensity;
    float s = std::min(f.width, f.height);
    float aspectY = f.height / s - 1.0f;
    float cxs[3], cys[3];
    for (int k = 0; k < 3; k++) core(k, aspectY, cxs[k], cys[k]);
    std::vector<float> u;
    u.reserve(28);
    u.insert(u.end(), {float(std::fmod(coreClock, 1000.0)), bass * amp, kick * amp, energy});
    u.insert(u.end(), {f.glow, spark * amp, flash * amp, std::max(0.0f, blast) * amp});
    u.insert(u.end(), {cxs[0], cys[0], cxs[1], cys[1]});
    u.insert(u.end(), {cxs[2], cys[2], 0.0f, 0.0f});
    for (int i = 0; i < 4; i++) u.insert(u.end(), {f.colors[i].r, f.colors[i].g, f.colors[i].b});
    c.material("nebula_cores", {0, 0, f.width, f.height}, u);
    if (orbits.empty()) return;

    float t = float(std::fmod(orbitClock, 10000.0));
    float open = 1.0f + std::max(-0.3f, blast) * 0.9f;
    float W = f.width * 0.5f, H = f.height * 0.5f;
    // Tres muestras por partícula: la cabeza y dos puntos de estela detrás.
    std::array<std::vector<Vec2>, 3> heads, tails;
    for (const Orbit& o : orbits) {
      float r = o.radius * open * (1.0f + 0.5f * o.seed * std::max(0.0f, blast));
      float ci = std::cos(o.incl), si = std::sin(o.incl), cn = std::cos(o.node), sn = std::sin(o.node);
      for (int k = 0; k < 3; k++) {
        float th = o.theta0 + o.speed * (t - float(k) * 0.06f);
        float ox = r * std::cos(th), oy = r * std::sin(th);
        // Órbita inclinada: rotación por la inclinación y el nodo.
        float y3 = oy * ci, z3 = oy * si;
        float x = ox * cn - y3 * sn;
        float y = ox * sn + y3 * cn;
        float persp = 1.0f / (1.0f - z3 * 0.8f);
        Vec2 pt{W + (cxs[o.core] + x * persp) * s, H + (cys[o.core] + y * persp) * s};
        if (k == 0) heads[o.core].push_back(pt); else tails[o.core].push_back(pt);
      }
    }
    float px = s / 400.0f;
    float gain = std::clamp((0.8f + 0.5f * bass + 0.6f * kick) * amp, 0.0f, 1.6f);
    float tw = 0.75f + 0.25f * spark;
    for (int k = 0; k < 3; k++) {
      Color col = k == 2 ? Color{0.75f * f.colors[3].r + 0.25f * f.colors[1].r, 0.75f * f.colors[3].g + 0.25f * f.colors[1].g,
                                 0.75f * f.colors[3].b + 0.25f * f.colors[1].b, 1.0f}
                         : f.colors[1 + k];
      Paint tail;
      tail.blend = Blend::plus;
      tail.color = {col.r, col.g, col.b, std::clamp(0.28f * gain, 0.0f, 1.0f)};
      c.points(tails[k], 1.0f * px, tail);
      Paint halo;
      halo.blend = Blend::plus;
      halo.color = {col.r, col.g, col.b, std::clamp(0.07f * gain * f.glow, 0.0f, 1.0f)};
      c.points(heads[k], 4.0f * px, halo);
      Paint head;
      head.blend = Blend::plus;
      head.color = {std::min(1.0f, col.r * 0.7f + 0.3f), std::min(1.0f, col.g * 0.7f + 0.3f), std::min(1.0f, col.b * 0.7f + 0.3f),
                    std::clamp(0.85f * gain * tw, 0.0f, 1.0f)};
      c.points(heads[k], (1.3f + 0.5f * spark * amp) * px, head);
    }
  }
};

shaderSources.nebula_cores:
#version 460 core
#include <flutter/runtime_effect.glsl>
uniform vec2 uSize;
uniform vec4 uA;   // reloj, graves, golpe, energía
uniform vec4 uB;   // glow, agudos, destello, supernova
uniform vec4 uK0;  // núcleos 1 y 2 (en unidades del lado corto, centrados)
uniform vec4 uK1;  // núcleo 3
uniform vec3 uC0;
uniform vec3 uC1;
uniform vec3 uC2;
uniform vec3 uC3;
out vec4 fragColor;

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash12(i), hash12(i + vec2(1.0, 0.0)), u.x),
             mix(hash12(i + vec2(0.0, 1.0)), hash12(i + vec2(1.0, 1.0)), u.x), u.y);
}

// Núcleo: brillo central, corona y rayos que salen en todas direcciones.
vec3 coreLight(vec2 p, vec2 c, vec3 col, float t) {
  vec2 d = p - c;
  float r = length(d) + 0.001;
  float glow = (0.0015 + 0.003 * uA.y + 0.006 * uA.z) / (r * r + 0.002);
  vec3 light = col * glow + vec3(1.0) * glow * 0.3;
  // Los rayos sólo se calculan cerca del núcleo: lejos no se ven.
  if (r < 0.45) {
    vec2 dir = d / r;
    float rays = noise(dir * 7.0 + t * 0.3);
    float corona = exp(-r * 9.0) * (0.25 + 0.6 * rays) * (0.5 + 0.8 * uA.y + 0.6 * uB.w);
    light += col * corona;
  }
  return light;
}

void main() {
  vec2 frag = FlutterFragCoord().xy;
  float scale = min(uSize.x, uSize.y);
  vec2 p = (frag - 0.5 * uSize) / scale;
  float t = uA.x;
  // Nebulosa tenue teñida por los núcleos.
  float n = noise(p * 2.5 + vec2(t * 0.03, -t * 0.02));
  vec3 neb = mix(uC2, uC1, smoothstep(0.3, 0.75, noise(p * 1.3 + 4.0 + t * 0.01)));
  vec3 col = uC0 + neb * smoothstep(0.3, 1.0, n) * (0.05 + 0.04 * uA.w + 0.08 * uA.z) * uB.x;
  col += coreLight(p, uK0.xy, uC1, t) * uB.x;
  col += coreLight(p, uK0.zw, uC2, t + 3.0) * uB.x;
  col += coreLight(p, uK1.xy, mix(uC3, uC1, 0.3), t + 6.0) * uB.x;
  col += mix(uC1, uC2, 0.5) * uB.z * 0.04;
  col *= 1.0 - 0.4 * smoothstep(0.5, 1.3, length(p * vec2(0.9, 0.65)));
  float peak = max(col.r, max(col.g, col.b));
  if (peak > 0.85) {
    float e = (peak - 0.85) / 0.15;
    col *= (0.85 + 0.15 * e / (1.0 + e)) / peak;
  }
  col += (hash12(frag) - 0.5) / 255.0;
  fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

visuals.nativeSource:
class Visual final : public Scene {
  // Puntos de cada tono: memoria de trabajo que se rellena al dibujar.
  mutable std::vector<Vec2> buckets[6];
  mutable std::vector<Vec2> glints;
  float waveTime = 0.0f;
  float smoothBass = 0.0f;
  float smoothEnergy = 0.0f;
  // Música estándar: envolventes y golpe corto (valen 0 sin música).
  float bass = 0, body = 0, spark = 0, energy = 0, drive = 0, slowBass = 0, kick = 0, flash = 0;
  // Segundos reales: las ondas de los golpes no dependen de Velocidad.
  double clock = 0;
  // Golpes: anillo fijo de ondas expansivas {nacimiento, fuerza}.
  static constexpr int kRings = 4;
  std::array<double, kRings> ringBirth{};
  std::array<float, kRings> ringPower{};
  int nextRing = 0;
  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }
  static float hashU(uint32_t x) {
    x ^= x >> 16; x *= 0x7feb352dU; x ^= x >> 15; x *= 0x846ca68bU; x ^= x >> 16;
    return float(x & 0xffffffu) / 16777216.0f;
  }
  // Una onda: Picada le suma un armónico agudo; Remolino la enrosca en espiral.
  static float wave(float phase, float dx, float dy, float choppy, float swirl) {
    if (swirl > 0.001f) phase += swirl * 2.0f * std::atan2(dy, dx);
    float s = std::sin(phase);
    if (choppy > 0.001f) s += choppy * 0.8f * std::sin(phase * 2.0f + 1.3f);
    return s;
  }
 public:
  void reset(uint32_t seed) override {
    (void)seed;
    for (int i = 0; i < 6; i++) buckets[i].clear();
    glints.clear();
    waveTime = 0.0f; smoothBass = 0.0f; smoothEnergy = 0.0f;
    bass = body = spark = energy = drive = slowBass = kick = flash = 0; clock = 0;
    ringBirth.fill(-100.0); ringPower.fill(0.0f); nextRing = 0;
  }
  void update(const Frame& f) override {
    float dt = float(f.delta);
    float targetEnergy = f.music.active ? f.music.energy : 0.0f;
    float targetBass = f.music.active ? f.music.bass : 0.0f;
    smoothBass += (targetBass - smoothBass) * float(1.0 - std::exp(-dt * 6.0));
    smoothEnergy += (targetEnergy - smoothEnergy) * float(1.0 - std::exp(-dt * 5.0));

    // En silencio reposa en una ondulación zen (~0.10f).
    // Con música acelera la onda y multiplica la amplitud vertical.
    float audioDrive = 0.10f + smoothEnergy * 0.75f + smoothBass * 0.35f;
    waveTime += dt * f.speed * audioDrive;

    // Música estándar: graves, cuerpo, agudos, energía y golpe corto.
    const Music& mu = f.music;
    bass = follow(bass, mu.bass, 22.0f, 4.5f, dt);
    body = follow(body, mu.body, 12.0f, 3.0f, dt);
    spark = follow(spark, mu.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, mu.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, mu.active ? std::pow(std::clamp(mu.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);
    float hit = 0, fl = 0;
    for (const auto& e : mu.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : mu.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : mu.events[3]) fl = std::max(fl, e.strength);
    const float onset = std::clamp((mu.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, mu.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    const bool fresh = hit > kick + 0.2f;
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    clock += f.delta;
    // Golpes: cada golpe nuevo lanza una onda expansiva desde el centro.
    if (fresh) {
      ringBirth[size_t(nextRing)] = clock;
      ringPower[size_t(nextRing)] = hit;
      nextRing = (nextRing + 1) % kRings;
    }
  }
  void render(const Frame& f, Canvas& c) const override {
    auto g = glide(f);
    const float level = f.intensity;
    // Pulso: cada opción mueve algo distinto y sus pesos mezclan las opciones.
    const float golpe = g.pulso.weight(0) * std::min(kick * level, 1.0f);
    const float graves = g.pulso.weight(1) * std::min(bass * level, 1.0f);
    const float agudos = g.pulso.weight(2) * std::min(spark * level, 1.0f);
    float w = f.width, h = f.height;
    // La malla (antes en update) se calcula aquí: los ajustes se ven en pausa.
    const float step = std::max(9.0f, std::min(w, h) / (18.0f + 16.0f * f.detail));
    const float cols = std::ceil(w / step) + 1.0f;
    const float rows = std::ceil(h / step) + 1.0f;
    float t = waveTime;
    float amp = 1.0f + smoothBass * 0.85f;
    float s1x = w * (0.5f + std::sin(t * 0.35f) * 0.32f);
    float s1y = h * (0.35f + std::sin(t * 0.27f + 1.0f) * 0.2f);
    float s2x = w * (0.5f + std::sin(t * 0.31f + 2.4f) * 0.34f);
    float s2y = h * (0.68f + std::sin(t * 0.23f + 3.0f) * 0.2f);
    // Fuentes: 2 es el original; la tercera y la cuarta entran poco a poco.
    const float n = g.fuentes;
    // Varias ondas se suman casi como su raíz: con más de dos fuentes se
    // normaliza menos para no apagar el contraste (con 2 queda el original).
    const float norm = n <= 2.0f ? n : 2.0f + (n - 2.0f) * 0.4f;
    const float w2 = std::clamp(n - 1.0f, 0.0f, 1.0f);
    const float w3 = std::clamp(n - 2.0f, 0.0f, 1.0f);
    const float w4 = std::clamp(n - 3.0f, 0.0f, 1.0f);
    float s3x = w * (0.5f + std::sin(t * 0.33f + 4.2f) * 0.36f);
    float s3y = h * (0.5f + std::sin(t * 0.21f + 5.1f) * 0.3f);
    float s4x = w * (0.5f + std::sin(t * 0.27f + 1.3f) * 0.3f);
    float s4y = h * (0.12f + std::sin(t * 0.25f + 0.7f) * 0.1f);
    const float choppy = g.agua.weight(1), swirl = g.agua.weight(2);
    // Ondas expansivas vivas: radio y fuerza (Golpes; 0 sin música).
    float ringR[kRings], ringA[kRings];
    int live = 0;
    const float ringSpeed = std::max(w, h) * 0.85f, ringLife = 1.3f;
    for (int r = 0; r < kRings; r++) {
      const float age = float(clock - ringBirth[size_t(r)]);
      const float power = std::min(ringPower[size_t(r)] * level, 1.0f) * g.pulso.weight(0);
      if (age < 0.0f || age >= ringLife || power <= 0.001f) continue;
      ringR[live] = age * ringSpeed;
      ringA[live] = power * (1.0f - age / ringLife);
      live++;
    }
    const float ox = w * 0.5f, oy = h * 0.5f;
    const uint32_t sparkle = uint32_t(std::fmod(clock * 12.0, 1.0e6));
    for (int i = 0; i < 6; i++) buckets[i].clear();
    glints.clear();
    for (int j = 0; j < int(rows); j++) {
      float y = float(j) * step;
      for (int i = 0; i < int(cols); i++) {
        float x = float(i) * step;
        float dx1 = x - s1x, dy1 = y - s1y;
        float dx2 = x - s2x, dy2 = y - s2y;
        float d1 = std::sqrt(dx1 * dx1 + dy1 * dy1);
        float d2 = std::sqrt(dx2 * dx2 + dy2 * dy2);
        float v = wave(d1 * 0.085f - t * 2.4f, dx1, dy1, choppy, swirl) + w2 * wave(d2 * 0.07f - t * 1.9f, dx2, dy2, choppy, swirl);
        if (w3 > 0.0f) {
          float dx3 = x - s3x, dy3 = y - s3y;
          v += w3 * wave(std::sqrt(dx3 * dx3 + dy3 * dy3) * 0.078f - t * 2.1f, dx3, dy3, choppy, swirl);
        }
        if (w4 > 0.0f) {
          float dx4 = x - s4x, dy4 = y - s4y;
          v += w4 * wave(std::sqrt(dx4 * dx4 + dy4 * dy4) * 0.092f - t * 2.7f, dx4, dy4, choppy, swirl);
        }
        float k = (v + norm) / (2.0f * norm);
        // Golpes: la onda expansiva levanta y enciende los puntos que cruza.
        float bump = 0.0f;
        if (live > 0) {
          const float d = std::sqrt((x - ox) * (x - ox) + (y - oy) * (y - oy));
          for (int r = 0; r < live; r++) {
            const float dr = (d - ringR[r]) / (step * 2.5f);
            bump += ringA[r] * std::exp(-dr * dr);
          }
          k += bump * 0.8f;
        }
        int b = int(k * 5.99f);
        if (b < 0) b = 0; if (b > 5) b = 5;
        const Vec2 point{x, y + (k - 0.5f) * step * 0.55f * amp - bump * step * 1.2f};
        buckets[b].push_back(point);
        // Agudos: destellos que titilan sobre las crestas.
        if (agudos > 0.001f && k > 0.5f &&
            hashU(uint32_t(j * 4099 + i) * 2654435761u ^ sparkle * 0x9e3779b9u) > 0.5f)
          glints.push_back(point);
      }
    }
    Paint bg; bg.color = Color::argb(0xff03071c);
    c.rect({0, 0, w, h}, bg);
    const uint32_t pal[6] = {0xff0a1b4a, 0xff123a8a, 0xff1f6fd0,
      0xff35b3f0, 0xff7fe9ff, 0xffd9fbff};
    const float foam = std::clamp(g.espuma, 0.0f, 1.0f);
    for (int b = 0; b < 6; b++) {
      if (buckets[b].empty()) continue;
      Color cc = Color::argb(pal[b]);
      // Graves: los puntos engordan (+30%) y brillan; Golpes los hincha un 20%.
      const float radius = (1.0f + float(b) / 5.0f * step * 0.42f) * 0.5f * (1.0f + graves * 0.3f + golpe * 0.2f);
      // Espuma y Graves: un halo suave sobre las crestas.
      const float haze = foam * 0.13f + graves * 0.14f * f.glow;
      if (haze > 0.001f && b >= 3) {
        Paint halo; halo.blend = Blend::plus;
        halo.color = {cc.r, cc.g, cc.b, std::min(1.0f, haze * float(b - 2))};
        c.points(buckets[b], radius * (1.6f + foam * 1.2f + graves * 0.8f), halo);
      }
      Paint p; p.blend = Blend::plus;
      p.color = {cc.r, cc.g, cc.b, std::min(1.0f, (0.55f + 0.45f * f.music.energy) * f.intensity * (1.0f + graves * 0.5f + golpe * 0.6f))};
      c.points(buckets[b], radius, p);
    }
    if (golpe > 0.001f) {
      // Golpes: un resplandor azul brota del centro, de donde salen las ondas.
      const float flare = std::min(1.0f, 0.4f * golpe * f.glow);
      const float reach = std::min(w, h) * 0.6f;
      Paint burst = Paint::radial({ox, oy}, reach,
        {{0.55f, 0.85f, 1, flare}, {0.3f, 0.6f, 1, flare * 0.35f}, {0.2f, 0.4f, 1, 0}}, {0, 0.4f, 1.0f});
      burst.blend = Blend::plus;
      c.circle({ox, oy}, reach, burst);
    }
    // Golpes: cada onda expansiva lleva un anillo de luz que recorre la malla.
    for (int r = 0; r < live; r++) {
      const float width = step * 3.0f;
      const float outer = ringR[r] + width;
      const float inner = std::max(0.0f, ringR[r] - width) / outer;
      const float a = std::min(1.0f, 0.45f * ringA[r] * f.glow);
      Paint ring = Paint::radial({ox, oy}, outer,
        {{0.5f, 0.85f, 1, 0}, {0.55f, 0.9f, 1, a}, {0.5f, 0.85f, 1, 0}}, {inner, ringR[r] / outer, 1.0f});
      ring.blend = Blend::plus;
      c.circle({ox, oy}, outer, ring);
    }
    if (!glints.empty()) {
      Paint gp; gp.blend = Blend::plus;
      gp.color = {0.6f, 0.9f, 1.0f, std::min(1.0f, agudos * 0.3f * f.glow)};
      c.points(glints, (1.0f + step * 0.12f) * 3.0f, gp);
      gp.color = {0.85f, 0.97f, 1.0f, std::min(1.0f, agudos)};
      c.points(glints, 1.0f + step * 0.14f, gp);
    }
  }
};

class Visual final : public Scene {
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  // Relojes en doble precisión: la escena sin música es idéntica a 30 y 60 FPS.
  double morph = 0;
  float spread = 0, spreadVel = 0;

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    morph = rng.unit() * 40.0;
    spread = spreadVel = 0;
  }

  void update(const Frame& f) override {
    auto m = modifiers(f);
    float dt = float(f.delta);
    const Music& mu = f.music;
    bass = follow(bass, mu.bass, 22.0f, 4.5f, dt);
    body = follow(body, mu.body, 12.0f, 3.0f, dt);
    spark = follow(spark, mu.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, mu.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, mu.active ? std::pow(std::clamp(mu.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : mu.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : mu.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : mu.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((mu.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, mu.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    if (hit > kick + 0.2f) spreadVel += 2.2f * hit;
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    // Muelle: la mancha se expande de golpe y vuelve despacio.
    spreadVel += (-spread * 18.0f - spreadVel * 5.0f) * dt;
    spread += spreadVel * dt;
    morph += f.delta * f.speed * m.cambio * (0.12 + 0.3 * drive);
  }

  void render(const Frame& f, Canvas& c) const override {
    auto m = modifiers(f);
    float amp = f.intensity;
    float t = float(std::fmod(morph, 1000.0));
    std::vector<float> u;
    u.reserve(48);
    u.insert(u.end(), {t, bass * amp, kick * amp, energy});
    u.insert(u.end(), {float(m.simetria), m.tamano, m.roja ? 1.0f : 0.0f, std::max(-0.2f, spread) * amp});
    u.insert(u.end(), {f.glow, flash * amp, spark * amp, 0.0f});
    // Lóbulos de la mancha: cinco manchas grandes que derivan despacio.
    static const float lx[5] = {0.1f, 0.26f, 0.16f, 0.28f, 0.07f};
    static const float ly[5] = {-0.55f, -0.2f, 0.12f, 0.42f, 0.55f};
    static const float lr[5] = {0.14f, 0.16f, 0.18f, 0.14f, 0.12f};
    for (int k = 0; k < 5; k++) {
      float fk = float(k);
      u.insert(u.end(), {lx[k] + 0.07f * std::sin(t * 0.7f + fk * 1.9f), ly[k] + 0.07f * std::cos(t * 0.5f + fk * 2.7f), lr[k], 0.0f});
    }
    // Dos lóbulos de tinta roja.
    u.insert(u.end(), {0.24f + 0.05f * std::sin(t * 0.4f), -0.42f + 0.06f * std::cos(t * 0.3f), 0.3f, 0.38f + 0.05f * std::sin(t * 0.5f)});
    for (int i = 0; i < 4; i++) u.insert(u.end(), {f.colors[i].r, f.colors[i].g, f.colors[i].b});
    c.material("inkblot", {0, 0, f.width, f.height}, u);
  }
};

shaderSources.inkblot:
#version 460 core
#include <flutter/runtime_effect.glsl>
uniform vec2 uSize;
uniform vec4 uA;   // cambio, graves, golpe, energía
uniform vec4 uB;   // simetría, tamaño, tinta roja, expansión
uniform vec4 uD;   // glow, destello, agudos
uniform vec4 uL0;  // lóbulos: x, y, radio
uniform vec4 uL1;
uniform vec4 uL2;
uniform vec4 uL3;
uniform vec4 uL4;
uniform vec4 uR;   // lóbulos rojos: centro 1 (x, y), centro 2 (x, y)
uniform vec3 uC0;
uniform vec3 uC1;
uniform vec3 uC2;
uniform vec3 uC3;
out vec4 fragColor;

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash12(i), hash12(i + vec2(1.0, 0.0)), u.x),
             mix(hash12(i + vec2(0.0, 1.0)), hash12(i + vec2(1.0, 1.0)), u.x), u.y);
}

float fbm(vec2 p) {
  float v = 0.0;
  float a = 0.5;
  for (int i = 0; i < 3; i++) {
    v += noise(p) * a;
    p = p * 2.03 + vec2(1.7, 9.2);
    a *= 0.5;
  }
  return v / 0.875;
}

float lobe(vec2 q, vec4 L) {
  vec2 d = q - L.xy;
  return exp(-dot(d, d) / (L.z * L.z));
}

void main() {
  vec2 frag = FlutterFragCoord().xy;
  float scale = min(uSize.x, uSize.y);
  vec2 p = (frag - 0.5 * uSize) / scale;
  float t = uA.x;
  // Espejo: la tinta se dobla sobre el eje como al plegar el papel.
  vec2 q = vec2(abs(p.x), p.y);
  if (uB.x > 0.5) q.y = abs(q.y);
  q /= uB.y;
  // Deformación lenta del campo para que la mancha cambie de forma.
  float w1 = noise(q * 2.2 + vec2(t * 0.6, 0.0));
  vec2 w = vec2(w1, noise(q * 2.2 + vec2(4.3, -t * 0.5))) - 0.5;
  float n = fbm(q * 3.6 + w * 1.4 + vec2(0.0, t * 0.25));
  float grow = 0.1 * uA.y + 0.2 * uB.w;
  vec2 qw = q + w * 0.08;
  float env = lobe(qw, uL0) + lobe(qw, uL1) + lobe(qw, uL2) + lobe(qw, uL3) + lobe(qw, uL4);
  // El eje central siempre tiene tinta, como al plegar el papel.
  env += 0.9 * exp(-q.x * q.x / 0.004) * (1.0 - smoothstep(0.55, 0.95, abs(q.y)));
  float F = env * 0.8 + (n - 0.5) * 1.1 - 0.5 + grow;
  // Tinta roja: dos lóbulos propios, con bordes del mismo ruido.
  vec2 r1 = q - uR.xy;
  vec2 r2 = q - vec2(uR.z, uR.w);
  float redEnv = exp(-dot(r1, r1) / 0.03) + 0.8 * exp(-dot(r2, r2) / 0.02);
  float R = (redEnv * 0.8 + (n - 0.5) * 1.0 - 0.45 + grow) * uB.z;

  // Papel crema con fibras.
  float fiber = hash12(floor(frag * vec2(0.5, 0.08))) * 0.6 + w1 * 0.4;
  vec3 col = uC0 * (0.93 + 0.07 * fiber);
  col *= 1.0 - 0.16 * smoothstep(0.6, 1.4, length(p * vec2(0.9, 0.65)));
  float aa = 0.008;
  // Aureola: el papel absorbe un poco de tinta alrededor del borde.
  col *= 1.0 - 0.12 * smoothstep(-0.12, 0.0, F);
  // Tinta negra: densidad suave por dentro y más oscura en el borde.
  float ink = smoothstep(-aa, aa, F);
  float rim = smoothstep(0.12, 0.0, F);
  float density = 0.75 + 0.25 * smoothstep(0.3, 0.7, w1 + 0.3 * n);
  vec3 inkCol = uC1 + (uC0 - uC1) * 0.12 * (1.0 - density) * (1.0 - rim);
  col = mix(col, inkCol, ink);
  // Tinta roja encima, con su borde más oscuro.
  float red = smoothstep(-aa, aa, R);
  float redRim = smoothstep(0.1, 0.0, R);
  vec3 redCol = mix(uC2 * (0.9 + 0.2 * n), uC3, redRim * 0.75);
  col = mix(col, redCol * (1.0 + 0.25 * uA.z), red);
  // Salpicaduras: gotas al azar cerca del borde, de tamaños distintos.
  if (F > -0.22 && F < -0.02) {
    vec2 g = q * 34.0;
    vec2 cell = floor(g);
    float hs = hash12(cell);
    vec2 off = vec2(hash12(cell + 3.1), hash12(cell + 7.7)) - 0.5;
    float rad = 0.08 + 0.22 * hash12(cell + 11.3);
    float dropShape = 1.0 - smoothstep(rad - 0.04, rad, length(fract(g) - 0.5 - off * 0.5));
    col = mix(col, uC1, step(0.86 - 0.08 * uA.z - 0.05 * uD.z, hs) * dropShape);
  }
  col = mix(col, uC2, uD.y * 0.03);
  col += (hash12(frag) - 0.5) / 255.0;
  fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

