class Visual final : public Scene {
  static constexpr int kOps = 16;
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  // Relojes en doble precisión: la escena sin música es idéntica a 30 y 60 FPS.
  double opClock = 0, wipe = -1, bathClock = 0, shine = 0;
  int cycle = 0, opsDone = 0;
  bool pending = false;

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

  static float hash(int a, int b, int salt) {
    uint32_t x = uint32_t(a) * 73856093u ^ uint32_t(b) * 19349663u ^ uint32_t(salt) * 83492791u;
    x ^= x >> 16;
    x *= 0x7feb352du;
    x ^= x >> 15;
    x *= 0x846ca68bu;
    x ^= x >> 16;
    return float(x >> 8) / 16777216.0f;
  }

  // Tipo de operación: 0 gota, 1 peine, 2 peine ondulado, 3 remolino.
  // Primero muchas gotas cubren el baño; luego se alternan peines y gotas.
  // El orden es fijo: el shader llama a la función de cada tipo sin ramas.
  static int opType(int i) {
    if (i == 9 || i == 11) return 1;
    if (i == 14) return 2;
    if (i == 15) return 3;
    return 0;
  }

 public:
  void reset(uint32_t seed) override {
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    cycle = int(seed % 97u);
    opsDone = 0;
    opClock = 0;
    wipe = -1;
    bathClock = shine = 0;
    pending = false;
  }

  void update(const Frame& f) override {
    auto m = modifiers(f);
    float dt = float(f.delta);
    const Music& mu = f.music;
    bass = follow(bass, mu.bass, 22.0f, 4.5f, dt);
    body = follow(body, mu.body, 12.0f, 3.0f, dt);
    spark = follow(spark, mu.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, mu.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, mu.active ? std::pow(std::clamp(mu.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : mu.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : mu.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : mu.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((mu.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, mu.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    // Pulso «Golpes»: cada golpe adelanta la siguiente gota o peine; con los
    // otros pulsos el baño sigue su propio ritmo.
    bool onBeats = m.ritmo == 1;
    if (onBeats && hit > kick + 0.2f) pending = true;
    if (!onBeats) pending = false;
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));

    // Reloj propio de la luz que corre por los bordes (Brillos).
    shine = std::fmod(shine + f.delta * f.speed * 4.0, 6.283185307179586);
    opClock += f.delta * f.speed;
    if (wipe >= 0.0) {
      wipe += f.delta * f.speed / 1.3;
      if (wipe >= 1.0) {
        wipe = -1;
        opClock = 0;
        bathClock = 0;
      }
      return;
    }
    // El vórtice del modo remolino se enrosca con el tiempo del baño.
    bathClock = std::min(bathClock + f.delta * f.speed, 40.0);
    // La siguiente operación llega con un golpe o, sin música, a su ritmo.
    double idle = 1.5;
    if (opClock > 0.75 && (pending || opClock > idle)) {
      // Sin música se conserva el sobrante: el ritmo no depende de los FPS.
      opClock = pending ? 0.0 : opClock - idle;
      pending = false;
      if (opsDone >= kOps - 1) {
        cycle++;
        opsDone = 0;
        wipe = 0;
      } else {
        opsDone++;
      }
    }
  }

  void render(const Frame& f, Canvas& c) const override {
    auto m = modifiers(f);
    auto g = glide(f);
    float amp = f.intensity;
    // Pulso: Graves, Golpes y Brillos, mezclados por sus pesos mientras cambian.
    float graves = g.ritmo.weight(0), golpes = g.ritmo.weight(1), brillos = g.ritmo.weight(2);
    // Graves: inflan la gota más reciente hasta un 25% y empujan la tinta.
    float swell = 1.0f + 0.25f * graves * std::min(bass * amp, 1.0f);
    float side = std::min(f.width, f.height);
    float halfH = 0.5f * f.height / side;
    // Durante la cortina se describe el baño anterior completo.
    bool wiping = wipe >= 0.0;
    int bath = wiping ? cycle - 1 : cycle;
    int shown = wiping ? kOps : opsDone + 1;
    float progress = float(std::min(opClock / 0.75, 1.0));
    float ease = 1.0f - (1.0f - progress) * (1.0f - progress);
    std::vector<float> u;
    u.reserve(96);
    // Remolino: el giro del vórtice en el centro, que se enrosca con el baño.
    float vortex = g.remolino * (2.2f + 0.1f * float(bathClock));
    u.insert(u.end(), {float(((bath % 1000) + 1000) % 1000), wiping ? float(wipe) : -1.0f,
                       kick * amp * golpes, bass * amp});
    u.insert(u.end(), {0.11f / m.peine, f.glow, flash * amp, vortex});
    float glints = brillos * std::clamp((spark * 1.2f + flash) * amp, 0.0f, 1.0f);
    u.insert(u.end(), {glints, float(shine), 0.0f, 0.0f});
    int startAnchor = int(hash(bath, 0, 9) * 5.0f);
    int newestDrop = -1;
    for (int i = 0; i < std::min(shown, kOps); i++) {
      if (opType(i) == 0) newestDrop = i;
    }
    for (int i = 0; i < kOps; i++) {
      // Las operaciones que aún no llegan no mueven nada (radio o arrastre 0).
      float e = i >= shown ? 0.0f : ((!wiping && i == opsDone) ? ease : 1.0f);
      int type = opType(i);
      if (type == 0) {
        // Gota: cinco puntos repartidos; al repetir punto se forman dianas.
        int anchor = (i + startAnchor) % 5;
        float cx = (hash(bath, anchor, 2) - 0.5f) * 0.7f + (hash(bath, i, 3) - 0.5f) * 0.08f;
        float cy = ((float(anchor) + 0.5f) / 5.0f - 0.5f) * halfH * 1.7f + (hash(bath, i, 4) - 0.5f) * 0.08f;
        float r = (0.17f + 0.17f * hash(bath, i, 5)) * m.gotas * e * (i == newestDrop ? swell : 1.0f);
        u.insert(u.end(), {cx, cy, r, float(((bath + i + anchor) % 4 + 4) % 4)});
      } else if (type == 3) {
        u.insert(u.end(), {0.0f, 0.0f, 3.2f * e, 0.0f});
      } else {
        float a = i == 9 ? 1.5707963f : (i == 11 ? 0.0f : 0.785f);
        float sgn = hash(bath, i, 6) > 0.5f ? 1.0f : -1.0f;
        u.insert(u.end(), {std::cos(a) * sgn, std::sin(a) * sgn, 0.16f * e, 0.0f});
      }
    }
    for (int i = 0; i < 4; i++) u.insert(u.end(), {f.colors[i].r, f.colors[i].g, f.colors[i].b});
    c.material("ebru", {0, 0, f.width, f.height}, u);
  }
};

shaderSources.ebru:
#version 460 core
#include <flutter/runtime_effect.glsl>
uniform vec2 uSize;
uniform vec4 uA;   // baño, cortina, golpe, graves
uniform vec4 uB;   // separación de púas, glow, destello, vórtice
uniform vec4 uE;   // brillos: cantidad, fase de la luz
uniform vec4 uO0;  // operaciones en orden fijo: gota (x, y, radio, tinta),
uniform vec4 uO1;  // peine (dirección x, y, arrastre) y remolino (-, -, giro)
uniform vec4 uO2;
uniform vec4 uO3;
uniform vec4 uO4;
uniform vec4 uO5;
uniform vec4 uO6;
uniform vec4 uO7;
uniform vec4 uO8;
uniform vec4 uO9;
uniform vec4 uO10;
uniform vec4 uO11;
uniform vec4 uO12;
uniform vec4 uO13;
uniform vec4 uO14;
uniform vec4 uO15;
uniform vec3 uC0;
uniform vec3 uC1;
uniform vec3 uC2;
uniform vec3 uC3;
out vec4 fragColor;

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

vec3 ink(float k) {
  if (k < 1.0) return uC1;
  if (k < 2.0) return uC2;
  if (k < 3.0) return uC3;
  return vec3(0.96, 0.93, 0.86);
}

// Deshacer una gota: si el punto cae dentro, toma su tinta; si no, vuelve
// a donde estaba antes de que la gota lo empujara. rim junta su borde
// visible (para los Brillos).
void undoDrop(inout vec2 P, inout vec3 col, inout float w, inout float rim, vec4 O) {
  vec2 d = P - O.xy;
  float q = dot(d, d);
  float r2 = O.z * O.z;
  float edge = (sqrt(q) - O.z) * 220.0;
  rim += w * (exp(-edge * edge) + 0.3 * uB.y * exp(-abs(edge) * 0.35)) * step(1e-4, O.z);
  float f = clamp((r2 - q) / (O.z * 0.016 + 1e-5) + 0.5, 0.0, 1.0);
  col += w * f * ink(O.w);
  w *= 1.0 - f;
  P = O.xy + d * sqrt(max(1.0 - r2 / max(q, r2 + 1e-6), 0.0));
}

// Deshacer una pasada de peine: arrastre máximo junto a cada púa.
void undoComb(inout vec2 P, vec4 O, float wavy) {
  vec2 M = O.xy;
  float across = dot(P, vec2(-M.y, M.x)) + wavy * 0.05 * sin(dot(P, M) * 9.0 + uA.x);
  float spacing = uB.x;
  float tine = abs(fract(across / spacing) - 0.5) * spacing;
  float k = max(1.0 - tine / 0.07, 0.0);
  P -= M * O.z * k * k * k;
}

// Deshacer un giro: girar al revés, más cerca del centro.
void undoTwist(inout vec2 P, float amount, float reach) {
  float ang = -amount * exp(-length(P) / reach);
  float cs = cos(ang);
  float sn = sin(ang);
  P = vec2(cs * P.x - sn * P.y, sn * P.x + cs * P.y);
}

// Deshacer el remolino final.
void undoSwirl(inout vec2 P, vec4 O) {
  undoTwist(P, O.z, 0.32);
}

void main() {
  vec2 frag = FlutterFragCoord().xy;
  float scale = min(uSize.x, uSize.y);
  vec2 p = (frag - 0.5 * uSize) / scale;
  float halfH = 0.5 * uSize.y / scale;
  // Cortina: el papel se levanta de arriba abajo y deja el agua limpia.
  float line = -halfH - 0.1 + uA.y * (2.0 * halfH + 0.2);
  vec3 col = uC0;
  float rim = 0.0;
  if (uA.y < 0.0 || p.y > line) {
    vec2 P = p;
    vec3 acc = vec3(0.0);
    float w = 1.0;
    // Vórtice del modo remolino: lo más nuevo, se deshace primero.
    undoTwist(P, uB.w, 0.3);
    undoSwirl(P, uO15);
    undoComb(P, uO14, 1.0);
    undoDrop(P, acc, w, rim, uO13);
    undoDrop(P, acc, w, rim, uO12);
    undoComb(P, uO11, 0.0);
    undoDrop(P, acc, w, rim, uO10);
    undoComb(P, uO9, 0.0);
    undoDrop(P, acc, w, rim, uO8);
    undoDrop(P, acc, w, rim, uO7);
    undoDrop(P, acc, w, rim, uO6);
    undoDrop(P, acc, w, rim, uO5);
    undoDrop(P, acc, w, rim, uO4);
    undoDrop(P, acc, w, rim, uO3);
    undoDrop(P, acc, w, rim, uO2);
    undoDrop(P, acc, w, rim, uO1);
    undoDrop(P, acc, w, rim, uO0);
    col = acc + w * uC0;
  }
  if (uA.y >= 0.0) col += vec3(1.0) * exp(-abs(p.y - line) * 120.0) * 0.5;
  // Brillo húmedo de la tinta y grano del agua.
  col *= 0.9 + 0.18 * uA.w + 0.12 * uA.z;
  col *= 0.97 + 0.03 * hash12(floor(frag * 0.5));
  col += uC1 * uB.z * 0.04;
  // Brillos: con los agudos, la luz corre por los bordes de la tinta.
  float shimmer = 0.5 + 0.5 * sin(dot(p, vec2(23.0, 14.0)) - uE.y);
  col += (vec3(1.0) - col) * clamp(rim, 0.0, 1.0) * (0.25 + 0.75 * shimmer * shimmer) * uE.x * 0.8;
  col *= 1.0 - 0.25 * smoothstep(0.7, 1.5, length(p * vec2(0.9, 0.6)));
  col += (hash12(frag) - 0.5) / 255.0;
  fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

visuals.nativeSource:
class Visual final : public Scene {
  static constexpr int kMax = 10;
  static constexpr double kStep = 1.0 / 240.0;
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  std::array<float, kMax> bands{};
  std::array<double, kMax> angle{}, vel{};
  std::array<float, kMax> peak{};
  // Relojes en doble precisión: la escena sin música es idéntica a 30 y 60 FPS.
  double clock = 0, sim = 0;
  int64_t steps = 0;

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

  // Colores siempre dentro de 0..1, también con intensity 2 y golpes fuertes.
  static Color rgba(float r, float g, float b, float a) {
    return Color{std::clamp(r, 0.0f, 1.0f), std::clamp(g, 0.0f, 1.0f), std::clamp(b, 0.0f, 1.0f), std::clamp(a, 0.0f, 1.0f)};
  }

 public:
  void reset(uint32_t seed) override {
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    bands.fill(0);
    angle.fill(0);
    vel.fill(0);
    peak.fill(0);
    clock = double(seed % 97u) * 0.37;
    sim = 0;
    steps = 0;
  }

  void update(const Frame& f) override {
    auto m = modifiers(f);
    float dt = float(f.delta);
    const Music& mu = f.music;
    bass = follow(bass, mu.bass, 22.0f, 4.5f, dt);
    body = follow(body, mu.body, 12.0f, 3.0f, dt);
    spark = follow(spark, mu.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, mu.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, mu.active ? std::pow(std::clamp(mu.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);
    int n = std::clamp(m.medidores, 1, kMax);
    for (int i = 0; i < n; i++) {
      int b0 = i * 28 / n, b1 = std::max(b0 + 1, (i + 1) * 28 / n);
      float v = 0;
      for (int b = b0; b < b1; b++) v = std::max(v, mu.spectrum[size_t(b)]);
      bands[size_t(i)] = v;
    }

    float hit = 0, fl = 0;
    for (const auto& e : mu.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : mu.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : mu.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((mu.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, mu.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    clock += f.delta * f.speed;
    // Aguja con masa y muelle, integrada a paso fijo.
    double stiffness = 120.0 / double(m.inercia);
    double damping = 11.0 / std::sqrt(double(m.inercia));
    sim += f.delta * f.speed;
    int64_t want = int64_t(std::floor(sim / kStep + 1e-6));
    if (want - steps > 120) steps = want - 120;
    while (steps < want) {
      double t = double(steps) * kStep;
      for (int i = 0; i < n; i++) {
        // Sin música: respiración suave alrededor de −20 dB.
        double idle = 0.3 + 0.14 * std::sin(t * 1.7 + double(i) * 1.3) + 0.08 * std::sin(t * 3.1 + double(i) * 2.0);
        double goal = mu.active ? std::clamp(std::pow(double(bands[size_t(i)]), 0.6) * double(m.sensibilidad) * 1.1, 0.0, 1.08) : idle;
        double acc = stiffness * (goal - angle[size_t(i)]) - damping * vel[size_t(i)];
        vel[size_t(i)] += acc * kStep;
        angle[size_t(i)] += vel[size_t(i)] * kStep;
        if (angle[size_t(i)] < -0.02) {
          angle[size_t(i)] = -0.02;
          vel[size_t(i)] = std::max(0.0, vel[size_t(i)]);
        }
      }
      steps++;
    }
    for (int i = 0; i < n; i++) {
      float red = angle[size_t(i)] > 0.82 ? 1.0f : 0.0f;
      peak[size_t(i)] = std::max(peak[size_t(i)] * std::exp(-dt * 4.0f), std::max(red, kick * 0.8f));
    }
  }

  void render(const Frame& f, Canvas& c) const override {
    auto m = modifiers(f);
    float amp = f.intensity;
    const Color& bg = f.colors[0];
    const Color& amber = f.colors[1];
    const Color& red = f.colors[2];
    const Color& face = f.colors[3];
    // Panel de metal oscuro.
    c.rect({0, 0, f.width, f.height}, Paint::linear({0, 0}, {f.width, f.height},
                                                   {rgba(bg.r + 0.05f, bg.g + 0.045f, bg.b + 0.04f, 1.0f),
                                                    rgba(bg.r, bg.g, bg.b, 1.0f)}));
    int n = std::clamp(m.medidores, 1, kMax);
    int cols = n <= 3 ? 1 : 2;
    int rows = (n + cols - 1) / cols;
    float px = std::min(f.width, f.height) / 400.0f;
    float margin = f.width * 0.06f;
    float cellW = (f.width - margin * float(cols + 1)) / float(cols);
    float cellH = std::min(cellW * 0.95f, (f.height - margin * float(rows + 1)) / float(rows));
    cellW = std::min(cellW, cellH / 0.72f);
    float totalH = cellH * float(rows) + margin * float(rows - 1);
    float startY = (f.height - totalH) * 0.5f;
    float startX = (f.width - cellW * float(cols) - margin * float(cols - 1)) * 0.5f;
    for (int i = 0; i < n; i++) {
      int cx = i % cols, cy = i / cols;
      float x = startX + float(cx) * (cellW + margin), y = startY + float(cy) * (cellH + margin);
      // Marco y cristal iluminado.
      Paint frame;
      frame.color = Color{0.13f, 0.12f, 0.11f, 1.0f};
      c.rect({x - 4.0f * px, y - 4.0f * px, cellW + 8.0f * px, cellH + 8.0f * px}, frame);
      float glowAmt = (0.75f + 0.25f * body + 0.2f * kick) * amp;
      Paint glass = Paint::radial({x + cellW * 0.5f, y + cellH * 0.9f}, cellW * 0.85f,
                                  {rgba(amber.r * glowAmt, amber.g * glowAmt, amber.b * glowAmt, 1.0f),
                                   rgba(amber.r * 0.45f * glowAmt, amber.g * 0.35f * glowAmt, amber.b * 0.25f * glowAmt, 1.0f)});
      c.rect({x, y, cellW, cellH}, glass);
      // Escala curva con marcas; la última parte en rojo.
      Vec2 pivot{x + cellW * 0.5f, y + cellH * 0.92f};
      float R = std::min(cellH * 0.72f, cellW * 0.62f);
      const float a0 = -2.35f, a1 = -0.79f;
      Path arc, arcRed, ticks, ticksRed;
      for (int k = 0; k <= 40; k++) {
        float t = float(k) / 40.0f;
        float a = a0 + (a1 - a0) * t;
        float xx = pivot.x + R * std::cos(a), yy = pivot.y + R * std::sin(a);
        Path& dst = t < 0.78f ? arc : arcRed;
        if (k == 0 || (t >= 0.78f && t - 1.0f / 40.0f < 0.78f)) dst.moveTo(xx, yy); else dst.lineTo(xx, yy);
      }
      for (int k = 0; k <= 10; k++) {
        float t = float(k) / 10.0f;
        float a = a0 + (a1 - a0) * t;
        float inner = R * (k % 2 == 0 ? 0.86f : 0.92f);
        Path& dst = t < 0.78f ? ticks : ticksRed;
        dst.moveTo(pivot.x + inner * std::cos(a), pivot.y + inner * std::sin(a)).lineTo(pivot.x + R * std::cos(a), pivot.y + R * std::sin(a));
      }
      Paint ink;
      ink.strokeWidth = 1.8f * px;
      ink.color = face;
      c.path(arc, ink);
      c.path(ticks, ink);
      Paint redInk;
      redInk.strokeWidth = 3.2f * px;
      redInk.color = red;
      c.path(arcRed, redInk);
      redInk.strokeWidth = 1.8f * px;
      c.path(ticksRed, redInk);
      // Aguja.
      float v = float(std::clamp(angle[size_t(i)], -0.02, 1.1));
      float a = a0 + (a1 - a0) * v;
      Path needle;
      needle.moveTo(pivot.x, pivot.y).lineTo(pivot.x + R * 1.04f * std::cos(a), pivot.y + R * 1.04f * std::sin(a));
      Paint shadow;
      shadow.strokeWidth = 2.6f * px;
      shadow.strokeCap = 1;
      shadow.color = Color{0, 0, 0, 0.25f};
      c.save();
      Path clip;
      clip.rect({x, y, cellW, cellH});
      c.clip(clip);
      c.translate(3.0f * px, 3.0f * px);
      c.path(needle, shadow);
      c.restore();
      c.save();
      c.clip(clip);
      Paint np;
      np.strokeWidth = 2.0f * px;
      np.strokeCap = 1;
      np.color = Color{0.06f, 0.05f, 0.05f, 1.0f};
      c.path(needle, np);
      c.restore();
      // Reflejo del cristal.
      Paint shine = Paint::linear({x, y}, {x, y + cellH * 0.4f}, {Color{1, 1, 1, 0.14f}, Color{1, 1, 1, 0.0f}});
      c.rect({x, y, cellW, cellH * 0.4f}, shine);
      // Piloto rojo.
      if (m.pilotos) {
        Vec2 led{x + cellW * 0.9f, y + cellH * 0.15f};
        float on = peak[size_t(i)] * amp;
        Paint ledGlow = Paint::radial(led, 14.0f * px, {red.opacity(std::clamp(on * f.glow, 0.0f, 1.0f)), red.opacity(0.0f)});
        ledGlow.blend = Blend::plus;
        c.circle(led, 14.0f * px, ledGlow);
        Paint ledDot;
        ledDot.color = rgba(0.25f + 0.75f * red.r * on, 0.04f + red.g * on, 0.03f + red.b * on, 1.0f);
        c.circle(led, 3.5f * px, ledDot);
      }
    }
    if (flash > 0.01f) {
      Paint fl;
      fl.blend = Blend::plus;
      fl.color = amber.opacity(std::clamp(flash * 0.05f * amp, 0.0f, 1.0f));
      c.rect({0, 0, f.width, f.height}, fl);
    }
  }
};

visuals.shaderSource:
float liquidField(vec2 p, float t, float bass, float spark, float flow) {
  float r = length(p);
  // Concentric liquid ripples expanding from center
  float ripple = sin(r * (14.0 + 3.0 * flow) - t * 3.8) * (0.035 + 0.055 * bass);

  // Cross-interfering droplet orbits
  vec2 c1 = vec2(sin(t * 0.7) * 0.42, cos(t * 0.8) * 0.35);
  vec2 c2 = vec2(cos(t * 0.9 + 1.8) * 0.38, sin(t * 0.6) * 0.42);
  float wave1 = sin(length(p - c1) * 16.0 - t * 4.2) * (0.025 + 0.035 * bass);
  float wave2 = sin(length(p - c2) * 18.0 - t * 3.6) * (0.020 + 0.030 * spark);

  // High-frequency surface sizzle from spark / hi-hats
  float sizzle = sin(p.x * 32.0 + t * 4.5) * cos(p.y * 32.0 + t * 4.0) * (0.006 + 0.018 * spark);

  // Base organic dome
  float dome = exp(-r * r * 2.2) * 0.16;

  return dome + ripple + wave1 + wave2 + sizzle;
}

vec4 paintVisual(vec2 uv, CreatorFrame f) {
  float aspect = max(f.size.x, 1.0) / max(f.size.y, 1.0);
  vec2 p = (uv - 0.5) * vec2(aspect, 1.0) * 2.1;

  float bass = clamp(f.bass, 0.0, 1.0);
  float energy = clamp(f.energy, 0.0, 1.0);
  float spark = clamp(f.spark, 0.0, 1.0);
  float flow = clamp(f.flow, 0.0, 1.0);

  float t = f.time * f.speed * 0.48;

  // Surface Normal via finite differences
  float eps = 0.0035;
  float hC = liquidField(p, t, bass, spark, flow);
  float hR = liquidField(p + vec2(eps, 0.0), t, bass, spark, flow);
  float hU = liquidField(p + vec2(0.0, eps), t, bass, spark, flow);

  vec3 normal = normalize(vec3((hC - hR) / eps, (hC - hU) / eps, 0.32));

  // Environmental reflection vector
  vec3 view = normalize(vec3(p * 0.22, 1.0));
  vec3 ref = reflect(-view, normal);

  // Studio lighting environment ramp (chrome horizon, deep velvet zenith)
  float horizon = smoothstep(-0.25, 0.25, ref.y);
  float stripe = sin(ref.y * 12.0 + ref.x * 6.0 + t * 0.25);
  float studioStripe = smoothstep(0.35, 0.75, stripe);

  vec3 deepMetal = vec3(0.02, 0.035, 0.07);
  vec3 silver = vec3(0.85, 0.90, 0.98);
  vec3 neonCyan = vec3(0.20, 0.85, 1.0);
  vec3 neonMagenta = vec3(0.95, 0.20, 0.65);

  vec3 chrome = mix(deepMetal, silver, horizon * 0.8 + studioStripe * 0.25);

  // Directional specular glints
  vec3 lightDir1 = normalize(vec3(-0.45, 0.7, 0.6));
  float spec1 = pow(max(dot(ref, lightDir1), 0.0), 36.0) * (1.6 + 2.4 * spark);
  vec3 lightDir2 = normalize(vec3(0.55, -0.5, 0.55));
  float spec2 = pow(max(dot(ref, lightDir2), 0.0), 22.0) * (0.8 + 1.4 * bass);

  // Fresnel rim glow with subtle chromatic sheen
  float fresnel = pow(1.0 - max(dot(normal, view), 0.0), 2.6);
  vec3 rimColor = mix(neonCyan, neonMagenta, 0.5 + 0.5 * sin(t * 0.35 + p.y * 2.2));

  // Combine chrome surface
  vec3 surface = chrome + (spec1 + spec2) * vec3(1.0, 0.98, 0.93) + fresnel * rimColor * (0.65 + 0.85 * energy);

  // Smooth dropoff into deep velvet background
  float fluidAlpha = smoothstep(1.4, 0.85, length(p));
  vec3 bg = vec3(0.015, 0.02, 0.035) * (1.0 - 0.45 * length(p));
  vec3 finalColor = mix(bg, surface, fluidAlpha);

  return vec4(clamp(finalColor * f.intensity * f.glow, 0.0, 1.0), 1.0);
}

float liquidField(vec2 p, float t, float bass, float spark, float flow) {
  float r = length(p);
  // Concentric liquid ripples expanding from center
  float ripple = sin(r * (14.0 + 3.0 * flow) - t * 3.8) * (0.035 + 0.055 * bass);

  // Cross-interfering droplet orbits
  vec2 c1 = vec2(sin(t * 0.7) * 0.42, cos(t * 0.8) * 0.35);
  vec2 c2 = vec2(cos(t * 0.9 + 1.8) * 0.38, sin(t * 0.6) * 0.42);
  float wave1 = sin(length(p - c1) * 16.0 - t * 4.2) * (0.025 + 0.035 * bass);
  float wave2 = sin(length(p - c2) * 18.0 - t * 3.6) * (0.020 + 0.030 * spark);

  // High-frequency surface sizzle from spark / hi-hats
  float sizzle = sin(p.x * 32.0 + t * 4.5) * cos(p.y * 32.0 + t * 4.0) * (0.006 + 0.018 * spark);

  // Base organic dome
  float dome = exp(-r * r * 2.2) * 0.16;

  return dome + ripple + wave1 + wave2 + sizzle;
}

vec4 paintVisual(vec2 uv, CreatorFrame f) {
  float aspect = max(f.size.x, 1.0) / max(f.size.y, 1.0);
  vec2 p = (uv - 0.5) * vec2(aspect, 1.0) * 2.1;

  float bass = clamp(f.bass, 0.0, 1.0);
  float energy = clamp(f.energy, 0.0, 1.0);
  float spark = clamp(f.spark, 0.0, 1.0);
  float flow = clamp(f.flow, 0.0, 1.0);

  float t = f.time * f.speed * 0.48;

  // Surface Normal via finite differences
  float eps = 0.0035;
  float hC = liquidField(p, t, bass, spark, flow);
  float hR = liquidField(p + vec2(eps, 0.0), t, bass, spark, flow);
  float hU = liquidField(p + vec2(0.0, eps), t, bass, spark, flow);

  vec3 normal = normalize(vec3((hC - hR) / eps, (hC - hU) / eps, 0.32));

  // Environmental reflection vector
  vec3 view = normalize(vec3(p * 0.22, 1.0));
  vec3 ref = reflect(-view, normal);

  // Studio lighting environment ramp (chrome horizon, deep velvet zenith)
  float horizon = smoothstep(-0.25, 0.25, ref.y);
  float stripe = sin(ref.y * 12.0 + ref.x * 6.0 + t * 0.25);
  float studioStripe = smoothstep(0.35, 0.75, stripe);

  vec3 deepMetal = vec3(0.02, 0.035, 0.07);
  vec3 silver = vec3(0.85, 0.90, 0.98);
  vec3 neonCyan = vec3(0.20, 0.85, 1.0);
  vec3 neonMagenta = vec3(0.95, 0.20, 0.65);

  vec3 chrome = mix(deepMetal, silver, horizon * 0.8 + studioStripe * 0.25);

  // Directional specular glints
  vec3 lightDir1 = normalize(vec3(-0.45, 0.7, 0.6));
  float spec1 = pow(max(dot(ref, lightDir1), 0.0), 36.0) * (1.6 + 2.4 * spark);
  vec3 lightDir2 = normalize(vec3(0.55, -0.5, 0.55));
  float spec2 = pow(max(dot(ref, lightDir2), 0.0), 22.0) * (0.8 + 1.4 * bass);

  // Fresnel rim glow with subtle chromatic sheen
  float fresnel = pow(1.0 - max(dot(normal, view), 0.0), 2.6);
  vec3 rimColor = mix(neonCyan, neonMagenta, 0.5 + 0.5 * sin(t * 0.35 + p.y * 2.2));

  // Combine chrome surface
  vec3 surface = chrome + (spec1 + spec2) * vec3(1.0, 0.98, 0.93) + fresnel * rimColor * (0.65 + 0.85 * energy);

  // Smooth dropoff into transparency
  float fluidAlpha = smoothstep(1.35, 0.65, length(p));
  float alpha = fluidAlpha * smoothstep(0.04, 0.20, max(surface.r, max(surface.g, surface.b)));

  // RGBA recto: el motor multiplica por alpha al componer.
  return vec4(clamp(surface * f.intensity * f.glow, 0.0, 1.0), alpha);
}

