class Visual final : public Scene {
  static constexpr int kRipples = 4;
  static constexpr double kPeriod = 7.0;  // segundos que dura cada figura
  static constexpr float kTurn = 1.8f;    // lo que tarda cada reloj en cambiar
  static constexpr float kTau = 6.2831853f;
  float bass = 0, spark = 0, slowBass = 0, kick = 0;
  // Reloj en doble precisión: la pared sin música es idéntica a 30 y 60 FPS.
  double clock = 0;
  std::array<double, kRipples> rippleAge{};
  std::array<float, kRipples> ripplePower{};
  int nextRipple = 0;

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }
  static float wrapPi(float a) {
    a = std::fmod(a + 3.14159265f, kTau);
    if (a < 0) a += kTau;
    return a - 3.14159265f;
  }
  static float hashU(uint32_t x) {
    x ^= x >> 16; x *= 0x7feb352dU; x ^= x >> 15; x *= 0x846ca68bU; x ^= x >> 16;
    return float(x & 0xffffffu) / 16777216.0f;
  }
  static int cycleFigure(int64_t n) {
    static const int order[5] = {0, 2, 4, 1, 3};
    return order[int(((n % 5) + 5) % 5)];
  }
  // Las dos agujas de un reloj en (u, v) para una figura y un instante.
  static void figureAngles(int k, float u, float v, int parity, float t, float& a1, float& a2) {
    const float r = std::sqrt(u * u + v * v);
    switch (k) {
      case 0: {  // Olas: líneas que ondulan por la pared.
        float d = 0.9f * std::sin(u * 2.4f - t * 0.9f) + 0.5f * std::sin(v * 1.6f + t * 0.6f);
        a1 = d; a2 = d + 3.14159265f; break;
      }
      case 1: {  // Espiral que gira despacio.
        float d = std::atan2(v, u) + 1.5707963f + 1.4f * r - t * 0.5f;
        a1 = d; a2 = d + 3.14159265f; break;
      }
      case 2: {  // Remolino: esquinas que giran alrededor del centro.
        float d = std::atan2(v, u) + t * 0.7f;
        a1 = d; a2 = d + 1.5707963f; break;
      }
      case 3: {  // Rombos: diagonales alternas que forman una red.
        float d = parity == 0 ? 0.7853982f : 2.3561945f;
        float s = 0.35f * std::sin(t * 0.8f + (u + v) * 1.5f);
        a1 = d + s; a2 = d + 3.14159265f - s; break;
      }
      default: {  // Abanico: rayos que salen del centro.
        float d = std::atan2(v, u) + 0.4f * std::sin(t * 0.6f);
        a1 = d; a2 = d + 3.14159265f + 0.5f * std::sin(t * 0.9f + r * 2.0f); break;
      }
    }
  }
  // Agujas para una opción de Figura: la figura anterior gira hasta la nueva
  // con una vuelta completa, empezando cuando le llega el barrido.
  static void handsFor(int option, float u, float v, int parity, float delay, double time, float& a1, float& a2) {
    const int64_t n = int64_t(std::floor(time / kPeriod));
    const float local = float(time - double(n) * kPeriod);
    const float t = float(time);
    const int kNew = option == 0 ? cycleFigure(n) : option - 1;
    const int kOld = option == 0 ? cycleFigure(n - 1) : option - 1;
    // Con una figura fija, cada periodo la gira un cuarto de vuelta.
    const float rotNew = option == 0 ? 0.0f : float(((n % 2) + 2) % 2) * 1.5707963f;
    const float rotOld = option == 0 ? 0.0f : float((((n - 1) % 2) + 2) % 2) * 1.5707963f;
    float o1, o2, n1, n2;
    figureAngles(kOld, u, v, parity, t, o1, o2);
    figureAngles(kNew, u, v, parity, t, n1, n2);
    o1 += rotOld; o2 += rotOld; n1 += rotNew; n2 += rotNew;
    const float k = std::clamp((local - delay) / kTurn, 0.0f, 1.0f);
    const float e = k * k * (3.0f - 2.0f * k);
    const float spin = (((n % 2) + 2) % 2) == 0 ? 1.0f : -1.0f;
    a1 = o1 + e * (wrapPi(n1 - o1) + kTau * spin);
    a2 = o2 + e * (wrapPi(n2 - o2) - kTau * spin);
  }

 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    bass = spark = slowBass = kick = 0;
    clock = double(rng.unit()) * kPeriod * 5.0;
    rippleAge.fill(100.0);
    ripplePower.fill(0.0f);
    nextRipple = 0;
  }

  void update(const Frame& f) override {
    const float dt = float(f.delta);
    const Music& mu = f.music;
    bass = follow(bass, mu.bass, 22.0f, 4.5f, dt);
    spark = follow(spark, mu.spark, 30.0f, 7.0f, dt);
    float hit = 0;
    for (const auto& e : mu.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : mu.events[2]) hit = std::max(hit, e.strength * 0.85f);
    const float onset = std::clamp((mu.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, mu.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    for (auto& age : rippleAge) age += f.delta;
    if (hit > kick + 0.2f) {
      rippleAge[size_t(nextRipple)] = 0.0;
      ripplePower[size_t(nextRipple)] = hit;
      nextRipple = (nextRipple + 1) % kRipples;
    }
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    clock += f.delta * f.speed;
  }

  void render(const Frame& f, Canvas& c) const override {
    auto g = glide(f);
    const auto& pal = f.colors;
    const float amp = f.intensity;
    const float W = f.width, H = f.height;
    const float side = std::min(W, H);
    const Color& bg = pal[0];
    c.rect({0, 0, W, H}, Paint::radial({W * 0.5f, H * 0.45f}, std::max(W, H) * 0.8f,
                                       {Color{std::min(1.0f, bg.r + 0.05f), std::min(1.0f, bg.g + 0.03f), std::min(1.0f, bg.b + 0.02f), 1.0f},
                                        Color{bg.r, bg.g, bg.b, 1.0f}}));
    // Detalle: cuántos relojes caben a lo ancho.
    const int cols = std::clamp(int(std::lround(4.5f + 2.6f * f.detail)), 5, 10);
    const float cell = W / float(cols);
    const int rows = int(std::ceil(H / cell)) + 1;
    const float y0 = (H - float(rows) * cell) * 0.5f;
    const float R = cell * 0.46f;
    const float maxDist = std::sqrt(W * W + H * H) / side;
    const float wGolpes = g.pulso.weight(0), wGraves = g.pulso.weight(1), wBrillos = g.pulso.weight(2);
    const float open = std::min(bass * amp, 1.2f) * 0.85f * wGraves;
    // Graves: las agujas se alargan, se engrosan y brillan más.
    const float graves = std::min(bass * amp, 1.0f) * wGraves;
    // Agujas casi hasta el borde: entre relojes vecinos se ven líneas seguidas.
    const float lenK = 0.97f * (1.0f + 0.12f * graves);
    const float wDiag = g.barrido.weight(0), wCenter = g.barrido.weight(1);
    const int from = g.figura.from, to = g.figura.to;
    const float tf = std::clamp(g.figura.t, 0.0f, 1.0f);
    const float ef = tf * tf * (3.0f - 2.0f * tf);
    const float trail = std::clamp(g.estela, 0.0f, 1.0f);
    const float faces = std::clamp(g.esferas, 0.0f, 1.0f);
    const int sparkleSlot = int(std::floor(clock * 10.0));

    Path hands, facePath;
    std::array<Path, 3> trails;
    // Golpes: las agujas que la onda sacude se encienden (suave y fuerte).
    std::array<Path, 2> shaken;
    std::array<bool, 2> anyShaken{false, false};
    std::vector<Vec2> hubs, tips;
    hubs.reserve(size_t(rows * cols));
    tips.reserve(size_t(rows * cols) * 2);
    auto angles = [&](float u, float v, int parity, float delay, double time, float& a1, float& a2) {
      handsFor(from, u, v, parity, delay, time, a1, a2);
      if (from != to && ef < 1.0f) {
        float b1, b2;
        handsFor(to, u, v, parity, delay, time, b1, b2);
        a1 += ef * wrapPi(b1 - a1);
        a2 += ef * wrapPi(b2 - a2);
      }
    };
    for (int row = 0; row < rows; row++) {
      for (int col = 0; col < cols; col++) {
        const float cx = (float(col) + 0.5f) * cell;
        const float cy = y0 + (float(row) + 0.5f) * cell;
        const float u = (cx - W * 0.5f) / (side * 0.5f);
        const float v = (cy - H * 0.5f) / (side * 0.5f);
        const float dist = std::sqrt(u * u + v * v);
        const float diag = std::clamp((cx / W + cy / H) * 0.5f, 0.0f, 1.0f);
        const float delay = 1.6f * (wDiag * diag + wCenter * std::min(dist / maxDist * 2.0f, 1.0f));
        const int parity = (row + col) % 2;
        float a1, a2;
        angles(u, v, parity, delay, clock, a1, a2);
        // Golpes: una onda que sale del centro y sacude las agujas a su paso.
        float rip = 0;
        for (int i = 0; i < kRipples; i++) {
          const float age = float(rippleAge[size_t(i)]);
          if (age > 4.0f) continue;
          const float front = (dist - age * 1.9f) / 0.25f;
          rip += ripplePower[size_t(i)] * std::exp(-age * 1.4f) * std::exp(-front * front);
        }
        // El doble de fuerte que antes, con un tope para que no dé la vuelta entera.
        rip = std::min(rip * 2.8f * wGolpes * amp, 2.6f);
        a1 += rip + open;
        a2 += rip - open;
        const float L = R * lenK;
        const Vec2 t1{cx + L * std::cos(a1), cy + L * std::sin(a1)};
        const Vec2 t2{cx + L * std::cos(a2), cy + L * std::sin(a2)};
        hands.moveTo(cx, cy).lineTo(t1.x, t1.y);
        hands.moveTo(cx, cy).lineTo(t2.x, t2.y);
        if (rip > 0.12f) {
          const size_t level = rip > 0.6f ? 1 : 0;
          shaken[level].moveTo(cx, cy).lineTo(t1.x, t1.y);
          shaken[level].moveTo(cx, cy).lineTo(t2.x, t2.y);
          anyShaken[level] = true;
        }
        if (faces > 0.01f) facePath.circle({cx, cy}, R);
        hubs.push_back({cx, cy});
        // Brillos: las puntas de algunas agujas se encienden con los agudos.
        if (wBrillos > 0.01f) {
          const uint32_t key = uint32_t(row * 131 + col * 7919) ^ uint32_t(sparkleSlot * 104729);
          if (hashU(key) < spark * amp * wBrillos * 2.4f) {
            tips.push_back(t1);
            tips.push_back(t2);
          }
        }
        // Estela: las agujas de hace un instante, cada vez más tenues.
        if (trail > 0.01f) {
          for (int k = 0; k < 3; k++) {
            float b1, b2;
            angles(u, v, parity, delay, clock - 0.06 * double(k + 1), b1, b2);
            trails[size_t(k)].moveTo(cx, cy).lineTo(cx + L * std::cos(b1), cy + L * std::sin(b1));
            trails[size_t(k)].moveTo(cx, cy).lineTo(cx + L * std::cos(b2), cy + L * std::sin(b2));
          }
        }
      }
    }
    if (faces > 0.01f) {
      Paint face;
      face.color = pal[1].opacity(std::clamp(0.08f * faces, 0.0f, 1.0f));
      c.path(facePath, face);
      Paint rim;
      rim.strokeWidth = std::max(1.0f, R * 0.04f);
      rim.color = pal[1].opacity(std::clamp(0.55f * faces, 0.0f, 1.0f));
      c.path(facePath, rim);
    }
    if (trail > 0.01f) {
      const float fade[3] = {0.4f, 0.24f, 0.12f};
      for (int k = 0; k < 3; k++) {
        Paint tp;
        tp.blend = Blend::plus;
        tp.strokeWidth = R * 0.1f;
        tp.strokeCap = 1;
        tp.color = pal[2].opacity(std::clamp(fade[k] * trail, 0.0f, 1.0f));
        c.path(trails[size_t(k)], tp);
      }
    }
    // Golpes: un resplandor local en el centro de la pared y un anillo de luz
    // que viaja con cada onda (sólo existen mientras dura el golpe).
    const float punch = std::min(kick * amp, 1.0f) * wGolpes;
    if (punch > 0.01f) {
      Paint bloom = Paint::radial({W * 0.5f, H * 0.5f}, side * 0.6f,
                                  {pal[2].opacity(std::clamp(0.3f * punch * f.glow, 0.0f, 0.45f)), pal[2].opacity(0.0f)});
      bloom.blend = Blend::plus;
      c.circle({W * 0.5f, H * 0.5f}, side * 0.6f, bloom);
    }
    for (int i = 0; i < kRipples; i++) {
      const float age = float(rippleAge[size_t(i)]);
      if (age > 4.0f) continue;
      const float strength = std::min(ripplePower[size_t(i)] * std::exp(-age * 1.4f) * wGolpes * amp, 1.0f);
      if (strength < 0.01f) continue;
      const float rr = age * 1.9f * side * 0.5f;
      const float w = 0.25f * side * 0.5f;
      const float outer = rr + w;
      const float inner = std::max(0.0f, rr - w);
      const Color clear = pal[3].opacity(0.0f);
      Paint ring = Paint::radial({W * 0.5f, H * 0.5f}, outer,
                                 {clear, clear, pal[3].opacity(std::clamp(0.34f * strength * f.glow, 0.0f, 0.5f)), clear},
                                 {0.0f, inner / outer, rr / outer, 1.0f});
      ring.blend = Blend::plus;
      c.circle({W * 0.5f, H * 0.5f}, outer, ring);
    }
    Paint halo;
    halo.blend = Blend::plus;
    // Golpes: el halo se ensancha ×1,8 y brilla el doble. Graves: +85 %.
    halo.strokeWidth = R * 0.42f * (1.0f + 0.25f * graves) * (1.0f + 0.8f * punch);
    halo.strokeCap = 1;
    halo.color = pal[2].opacity(std::clamp((0.26f + 0.3f * kick * amp * wGolpes + 0.22f * graves) * f.glow, 0.0f, 1.0f));
    c.path(hands, halo);
    // Golpes: las agujas sacudidas brillan con un halo propio.
    for (size_t k = 0; k < 2; k++) {
      if (!anyShaken[k]) continue;
      Paint sh;
      sh.blend = Blend::plus;
      sh.strokeWidth = R * (k == 0 ? 0.36f : 0.48f);
      sh.strokeCap = 1;
      sh.color = pal[3].opacity(std::clamp((k == 0 ? 0.35f : 0.6f) * f.glow, 0.0f, 0.75f));
      c.path(shaken[k], sh);
    }
    Paint core;
    // Golpes: agujas ×1,8 más gruesas en el golpe. Graves: ×1,6.
    core.strokeWidth = R * 0.13f * (1.0f + 0.6f * graves) * (1.0f + 0.8f * punch);
    core.strokeCap = 1;
    core.color = pal[3];
    c.path(hands, core);
    Paint hub;
    hub.color = pal[3];
    c.points(hubs, R * 0.08f, hub);
    if (!tips.empty()) {
      // Brillos: las puntas encendidas llevan un halo.
      Paint glowTip;
      glowTip.blend = Blend::plus;
      glowTip.color = pal[3].opacity(std::clamp(0.3f * f.glow, 0.0f, 0.6f));
      c.points(tips, R * 0.36f, glowTip);
      Paint tp;
      tp.blend = Blend::plus;
      tp.color = pal[3].opacity(0.9f);
      c.points(tips, R * 0.17f, tp);
    }
  }
};

class Visual final : public Scene {
  // La red avanza en pasos fijos de 1/30 s contados con el tiempo absoluto:
  // es idéntica a 30 y a 60 FPS y los agentes se dibujan interpolados.
  static constexpr double kHz = 30.0;
  static constexpr float kTau = 6.2831853f;
  // Cada agente guarda su dirección como vector: los giros y los sensores son
  // rotaciones fijas, así no hay trigonometría por agente en cada paso.
  struct Agent { float x, y, px, py, dx, dy; int species; };
  std::vector<Agent> agents;
  std::vector<float> trail, scratch;
  int gw = 0, gh = 0;
  float w = 0, h = 0;
  int64_t steps = -1;
  float frac = 0, pendingBurst = 0;
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  Random rng{61};

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

  float sense(float x, float y) const {
    int ix = int(x), iy = int(y);
    // Fuera de la rejilla el rastro es negativo: los agentes se apartan del borde.
    if (x < 0 || y < 0 || ix >= gw || iy >= gh) return -1.0f;
    return trail[size_t(iy * gw + ix)];
  }

  static void rotate(float& x, float& y, float c, float s) {
    float nx = x * c - y * s;
    y = x * s + y * c;
    x = nx;
  }

  void step() {
    // Parámetros del modelo de Jeff Jones por especie: ángulo y distancia de
    // los sensores y giro.
    static const float sensorAngle[3] = {0.39f, 0.45f, 0.35f};
    static const float sensorDist[3] = {5.0f, 6.0f, 4.0f};
    static const float turnAngle[3] = {0.78f, 0.85f, 0.65f};
    float sc[3], ss[3], tc[3], ts[3];
    for (int k = 0; k < 3; k++) {
      sc[k] = std::cos(sensorAngle[k]);
      ss[k] = std::sin(sensorAngle[k]);
      tc[k] = std::cos(turnAngle[k]);
      ts[k] = std::sin(turnAngle[k]);
    }
    float speed = 0.8f + 0.8f * bass + 0.45f * drive;
    float deposit = 1.0f + 1.2f * energy;
    float burst = pendingBurst;
    pendingBurst = 0;
    float cx = float(gw) * 0.5f, cy = float(gh) * 0.5f;
    for (Agent& ag : agents) {
      ag.px = ag.x;
      ag.py = ag.y;
      // Una pequeña parte renace al azar en cada paso: la red nunca se
      // reduce a un solo hilo y sigue ramificándose.
      if (rng.unit() < 0.003f) {
        ag.x = ag.px = 1.0f + rng.unit() * float(gw - 2);
        ag.y = ag.py = 1.0f + rng.unit() * float(gh - 2);
      }
      if (burst > 0 && rng.unit() < 0.25f * burst) {
        // Estallido: el agente renace junto al centro mirando hacia fuera.
        float vx = rng.unit() - 0.5f, vy = rng.unit() - 0.5f;
        float l = std::sqrt(vx * vx + vy * vy) + 1e-4f;
        ag.dx = vx / l;
        ag.dy = vy / l;
        ag.x = ag.px = cx + ag.dx * 2.0f;
        ag.y = ag.py = cy + ag.dy * 2.0f;
      }
      int s = ag.species;
      float sd = sensorDist[s];
      float lx = ag.dx, ly = ag.dy, rx = ag.dx, ry = ag.dy;
      rotate(lx, ly, sc[s], ss[s]);
      rotate(rx, ry, sc[s], -ss[s]);
      float f = sense(ag.x + ag.dx * sd, ag.y + ag.dy * sd);
      float l = sense(ag.x + lx * sd, ag.y + ly * sd);
      float r = sense(ag.x + rx * sd, ag.y + ry * sd);
      if (f >= l && f >= r) {
      } else if (f < l && f < r) {
        rotate(ag.dx, ag.dy, tc[s], rng.unit() < 0.5f ? ts[s] : -ts[s]);
      } else if (l > r) {
        rotate(ag.dx, ag.dy, tc[s], ts[s]);
      } else {
        rotate(ag.dx, ag.dy, tc[s], -ts[s]);
      }
      ag.x += ag.dx * speed;
      ag.y += ag.dy * speed;
      if (ag.x < 1.0f || ag.x > float(gw) - 1.01f) {
        ag.x = std::clamp(ag.x, 1.0f, float(gw) - 1.01f);
        ag.dx = -ag.dx;
      }
      if (ag.y < 1.0f || ag.y > float(gh) - 1.01f) {
        ag.y = std::clamp(ag.y, 1.0f, float(gh) - 1.01f);
        ag.dy = -ag.dy;
      }
      trail[size_t(int(ag.y) * gw + int(ag.x))] += deposit;
    }
    // Difusión y evaporación del rastro (media 3 x 3 y pérdida del 10 %), con
    // un tope bajo para que ningún hilo acapare a todos los agentes.
    for (int y = 0; y < gh; y++) {
      int y0 = std::max(0, y - 1), y1 = std::min(gh - 1, y + 1);
      for (int x = 0; x < gw; x++) {
        int x0 = std::max(0, x - 1), x1 = std::min(gw - 1, x + 1);
        float sum = 0;
        for (int yy = y0; yy <= y1; yy++)
          for (int xx = x0; xx <= x1; xx++) sum += trail[size_t(yy * gw + xx)];
        float n = float((y1 - y0 + 1) * (x1 - x0 + 1));
        scratch[size_t(y * gw + x)] = std::min(sum / n * 0.9f, 2.0f);
      }
    }
    trail.swap(scratch);
  }

 public:
  void reset(uint32_t seed) override {
    rng = Random(seed);
    agents.clear();
    trail.clear();
    scratch.clear();
    gw = gh = 0;
    w = h = 0;
    steps = -1;
    frac = pendingBurst = 0;
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
  }

  void update(const Frame& f) override {
    float dt = float(f.delta);
    if (f.width != w || f.height != h || agents.empty()) {
      w = f.width;
      h = f.height;
      gw = int(90.0f + 30.0f * std::clamp(f.detail, 0.25f, 2.0f));
      gh = std::max(16, int(float(gw) * h / std::max(1.0f, w)));
      trail.assign(size_t(gw * gh), 0.0f);
      scratch.assign(size_t(gw * gh), 0.0f);
      int count = int(float(gw * gh) * 0.3f);
      agents.resize(size_t(count));
      for (int i = 0; i < count; i++) {
        Agent& ag = agents[size_t(i)];
        ag.x = ag.px = 1.0f + rng.unit() * float(gw - 2);
        ag.y = ag.py = 1.0f + rng.unit() * float(gh - 2);
        float a = rng.unit() * kTau;
        ag.dx = std::cos(a);
        ag.dy = std::sin(a);
        ag.species = i % 3;
      }
      // Arranque con la red ya formada.
      for (int k = 0; k < 60; k++) step();
      for (Agent& ag : agents) {
        ag.px = ag.x;
        ag.py = ag.y;
      }
    }
    const Music& m = f.music;
    bass = follow(bass, m.bass, 22.0f, 4.5f, dt);
    body = follow(body, m.body, 12.0f, 3.0f, dt);
    spark = follow(spark, m.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, m.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, m.active ? std::pow(std::clamp(m.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : m.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : m.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : m.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((m.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, m.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    if (hit > kick + 0.2f) pendingBurst = std::max(pendingBurst, hit);
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));

    int64_t target = int64_t(std::floor(f.time * kHz + 1e-6));
    if (steps < 0 || target < steps || target - steps > 8) steps = target - 1;
    while (steps < target) {
      step();
      steps++;
    }
    frac = std::clamp(float(f.time * kHz - double(steps)), 0.0f, 1.0f);
  }

  void render(const Frame& f, Canvas& c) const override {
    float amp = f.intensity;
    std::vector<float> u;
    u.reserve(20);
    u.insert(u.end(), {bass * amp, kick * amp, energy, f.glow});
    u.insert(u.end(), {spark * amp, flash * amp, 0.0f, 0.0f});
    for (int i = 0; i < 4; i++) u.insert(u.end(), {f.colors[i].r, f.colors[i].g, f.colors[i].b});
    c.material("moho_dark", {0, 0, f.width, f.height}, u);
    if (agents.empty()) return;
    float sx = f.width / float(gw), sy = f.height / float(gh);
    std::array<std::vector<Vec2>, 3> groups;
    for (auto& g : groups) g.reserve(agents.size() / 3 + 1);
    for (const Agent& ag : agents) {
      float x = ag.px + (ag.x - ag.px) * frac, y = ag.py + (ag.y - ag.py) * frac;
      groups[size_t(ag.species)].push_back({x * sx, y * sy});
    }
    float px = std::min(f.width, f.height) / 400.0f;
    float gain = std::clamp((0.85f + 0.5f * bass + 0.6f * kick) * amp, 0.0f, 1.6f);
    for (int g = 0; g < 3; g++) {
      const Color& col = f.colors[1 + g];
      Paint halo;
      halo.blend = Blend::plus;
      halo.color = {col.r, col.g, col.b, std::clamp(0.03f * gain * f.glow, 0.0f, 1.0f)};
      c.points(groups[size_t(g)], 3.5f * px, halo);
      Paint core;
      core.blend = Blend::plus;
      core.color = {col.r, col.g, col.b, std::clamp((g == 2 ? 0.16f : 0.24f) * gain, 0.0f, 1.0f)};
      c.points(groups[size_t(g)], (0.9f + 0.4f * spark * amp) * px, core);
    }
  }
};

