visuals.nativeSource:
class Visual final : public Scene {
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  // Relojes en doble precisión: la escena sin música es idéntica a 30 y 60 FPS.
  double orbit = 0, spin = 0, clock = 0;
  float spread = 0, spreadVel = 0, twirl = 0, twirlVel = 0;

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    orbit = rng.unit() * 6.2831853;
    spin = rng.unit() * 6.2831853;
    clock = rng.unit() * 50.0;
    spread = spreadVel = twirl = twirlVel = 0;
  }

  void update(const Frame& f) override {
    float dt = float(f.delta);
    const Music& m = f.music;
    bass = follow(bass, m.bass, 22.0f, 4.5f, dt);
    body = follow(body, m.body, 12.0f, 3.0f, dt);
    spark = follow(spark, m.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, m.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, m.active ? std::pow(std::clamp(m.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : m.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : m.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : m.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((m.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, m.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    if (hit > kick + 0.2f) {
      spreadVel += 2.2f * hit;
      twirlVel += 2.5f * hit;
    }
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    spreadVel += (-spread * 14.0f - spreadVel * 4.0f) * dt;
    spread += spreadVel * dt;
    twirlVel += (-twirl * 8.0f - twirlVel * 3.0f) * dt;
    twirl += twirlVel * dt;
    orbit += f.delta * f.speed * (0.10 + 0.25 * drive);
    spin += f.delta * f.speed * (0.15 + 0.2 * drive);
    clock += f.delta * f.speed;
  }

  void render(const Frame& f, Canvas& c) const override {
    float amp = f.intensity;
    std::vector<float> u;
    u.reserve(44);
    u.insert(u.end(), {float(std::fmod(orbit, 6.2831853)), bass * amp, kick * amp, energy});
    u.insert(u.end(), {f.glow, spark * amp, flash * amp, float(std::fmod(clock, 1000.0))});
    // Monolitos: posición en el suelo (x, z), altura de flote y giro propio.
    float radius = 2.1f + 0.9f * std::max(-0.3f, spread);
    for (int i = 0; i < 5; i++) {
      float a = float(std::fmod(spin, 6.2831853)) + 1.2566371f * float(i);
      float bob = 0.15f * float(std::sin(clock * 0.7 + i * 1.3));
      u.insert(u.end(), {std::cos(a) * radius, std::sin(a) * radius, bob, -a + 0.4f * twirl * (i % 2 ? 1.0f : -1.0f)});
    }
    for (int i = 0; i < 4; i++) u.insert(u.end(), {f.colors[i].r, f.colors[i].g, f.colors[i].b});
    c.material("chrome_monoliths", {0, 0, f.width, f.height}, u);
  }
};

shaderSources.chrome_monoliths:
#version 460 core
#include <flutter/runtime_effect.glsl>
uniform vec2 uSize;
uniform vec4 uA;   // órbita de cámara, graves, golpe, energía
uniform vec4 uB;   // glow, agudos, destello, reloj
uniform vec4 uM0;  // monolitos: x, z, flote, giro
uniform vec4 uM1;
uniform vec4 uM2;
uniform vec4 uM3;
uniform vec4 uM4;
uniform vec3 uC0;
uniform vec3 uC1;
uniform vec3 uC2;
uniform vec3 uC3;
out vec4 fragColor;

const vec3 HALF = vec3(0.42, 1.55, 0.14);

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

// Giro de cada monolito, calculado una sola vez por píxel.
vec2 rot0;
vec2 rot1;
vec2 rot2;
vec2 rot3;
vec2 rot4;

// Punto en el espacio local del monolito m con giro cs (coseno, seno).
vec3 toLocal(vec3 p, vec4 m, vec2 cs) {
  vec3 q = p - vec3(m.x, HALF.y + 0.35 + m.z, m.y);
  return vec3(cs.x * q.x - cs.y * q.z, q.y, cs.y * q.x + cs.x * q.z);
}

// Intersección exacta rayo-caja en el espacio local del monolito: devuelve
// la distancia del impacto (o -1) y el punto local tocado.
float boxHit(vec3 ro, vec3 rd, vec4 m, vec2 cs, out vec3 lp) {
  vec3 lo = toLocal(ro, m, cs);
  vec3 ld = vec3(cs.x * rd.x - cs.y * rd.z, rd.y, cs.y * rd.x + cs.x * rd.z);
  ld = sign(ld) * max(abs(ld), vec3(1e-5));
  vec3 inv = 1.0 / ld;
  vec3 t0 = (-HALF - lo) * inv;
  vec3 t1 = (HALF - lo) * inv;
  vec3 tmin = min(t0, t1);
  vec3 tmax = max(t0, t1);
  float tn = max(max(tmin.x, tmin.y), tmin.z);
  float tf = min(min(tmax.x, tmax.y), tmax.z);
  lp = lo + ld * tn;
  return (tn > tf || tn < 0.0) ? -1.0 : tn;
}

// Halo: cercanía del rayo al eje del monolito.
float boxHalo(vec3 ro, vec3 rd, vec4 m) {
  vec3 c = vec3(m.x, HALF.y + 0.35 + m.z, m.y) - ro;
  float along = max(dot(c, rd), 0.0);
  vec3 off = c - rd * along;
  off.y = max(abs(off.y) - HALF.y, 0.0);
  float d = max(length(off) - 0.35, 0.0);
  return exp(-d * 6.0);
}

vec4 monolith(float id) {
  return id < 0.5 ? uM0 : (id < 1.5 ? uM1 : (id < 2.5 ? uM2 : (id < 3.5 ? uM3 : uM4)));
}

vec2 monolithRot(float id) {
  return id < 0.5 ? rot0 : (id < 1.5 ? rot1 : (id < 2.5 ? rot2 : (id < 3.5 ? rot3 : rot4)));
}

// Entorno que refleja el cromo: vacío negro con franjas de neón y un foco.
vec3 environment(vec3 r) {
  float t = uB.w;
  vec3 col = uC0 + uC3 * (0.06 + 0.3 * smoothstep(-0.05, 0.7, r.y));
  // Barras verticales de luz alrededor: el cromo las refleja como rayas.
  float bars = pow(max(cos(atan(r.z, r.x) * 5.0 + t * 0.3), 0.0), 24.0) * smoothstep(-0.15, 0.1, r.y);
  col += uC2 * bars * 0.8;
  float strip1 = exp(-(r.y - 0.18) * (r.y - 0.18) * 260.0);
  float strip2 = exp(-(r.y - 0.55) * (r.y - 0.55) * 500.0);
  col += uC1 * strip1 * (1.1 + 0.8 * uA.y + 1.2 * uA.z);
  col += uC2 * strip2 * (0.7 + 0.5 * uA.z);
  float ang = atan(r.z, r.x) - t * 0.6;
  float spot = pow(max(cos(ang), 0.0), 40.0) * smoothstep(0.0, 0.4, r.y);
  col += uC2 * spot * 0.9;
  col += uC1 * smoothstep(-0.05, -0.4, r.y) * 0.12;
  return col;
}

void main() {
  vec2 frag = FlutterFragCoord().xy;
  float scale = min(uSize.x, uSize.y);
  vec2 p = (frag - 0.5 * uSize) / scale;
  p.y = -p.y;
  rot0 = vec2(cos(uM0.w), sin(uM0.w));
  rot1 = vec2(cos(uM1.w), sin(uM1.w));
  rot2 = vec2(cos(uM2.w), sin(uM2.w));
  rot3 = vec2(cos(uM3.w), sin(uM3.w));
  rot4 = vec2(cos(uM4.w), sin(uM4.w));
  float a = uA.x;
  vec3 ro = vec3(sin(a) * 7.0, 2.3, cos(a) * 7.0);
  vec3 target = vec3(0.0, 1.6, 0.0);
  vec3 fw = normalize(target - ro);
  vec3 rt = normalize(cross(fw, vec3(0.0, 1.0, 0.0)));
  vec3 up = cross(rt, fw);
  vec3 rd = normalize(fw * 1.6 + rt * p.x + up * p.y);

  // Suelo: plano analítico y = 0 con una cuadrícula de neón rojo.
  float tFloor = rd.y < -0.001 ? -ro.y / rd.y : 1e5;
  vec3 col = environment(rd) * 0.12;
  // Impacto más cercano entre los cinco monolitos.
  float t = 1e5;
  float hitId = -1.0;
  vec3 q = vec3(0.0);
  vec3 lp;
  float th = boxHit(ro, rd, uM0, rot0, lp);
  if (th > 0.0 && th < t) { t = th; hitId = 0.0; q = lp; }
  th = boxHit(ro, rd, uM1, rot1, lp);
  if (th > 0.0 && th < t) { t = th; hitId = 1.0; q = lp; }
  th = boxHit(ro, rd, uM2, rot2, lp);
  if (th > 0.0 && th < t) { t = th; hitId = 2.0; q = lp; }
  th = boxHit(ro, rd, uM3, rot3, lp);
  if (th > 0.0 && th < t) { t = th; hitId = 3.0; q = lp; }
  th = boxHit(ro, rd, uM4, rot4, lp);
  if (th > 0.0 && th < t) { t = th; hitId = 4.0; q = lp; }
  if (t > tFloor) hitId = -1.0;
  float glowAcc = (boxHalo(ro, rd, uM0) + boxHalo(ro, rd, uM1) + boxHalo(ro, rd, uM2) + boxHalo(ro, rd, uM3) +
                   boxHalo(ro, rd, uM4)) * 0.12;
  float edgeGlow = 0.6 + 1.6 * uA.y + 1.8 * uA.z;
  if (hitId >= 0.0) {
    vec2 mr = monolithRot(hitId);
    // Normal de la caja en el espacio local, devuelta al mundo.
    vec3 aq = abs(q) / HALF;
    vec3 nl = aq.x > aq.y && aq.x > aq.z ? vec3(sign(q.x), 0.0, 0.0)
            : (aq.y > aq.z ? vec3(0.0, sign(q.y), 0.0) : vec3(0.0, 0.0, sign(q.z)));
    vec3 n = vec3(mr.x * nl.x + mr.y * nl.z, nl.y, -mr.y * nl.x + mr.x * nl.z);
    vec3 r = reflect(rd, n);
    float fres = 0.55 + 0.45 * pow(1.0 - max(dot(-rd, n), 0.0), 3.0);
    col = environment(r) * fres * mix(vec3(1.0), uC3, 0.35) * 1.2;
    // Aristas de neón: cerca de dos caras a la vez.
    vec3 e = HALF - abs(q);
    float e1 = min(e.x, min(e.y, e.z));
    float e2 = e.x + e.y + e.z - e1 - max(e.x, max(e.y, e.z));
    float edge = exp(-e2 * 45.0);
    col += uC1 * edge * edgeGlow * uB.x;
    col += uC2 * edge * smoothstep(0.85, 1.0, hash12(vec2(hitId, floor(uB.w * 8.0)))) * uB.y;
  } else if (tFloor < 1e4) {
    vec3 hp = ro + rd * tFloor;
    vec2 g = abs(fract(hp.xz * 0.75) - 0.5);
    float line = exp(-min(g.x, g.y) * 40.0);
    float fade = exp(-length(hp.xz) * 0.12);
    col = uC0 + uC1 * line * fade * (0.35 + 0.4 * uA.y + 0.6 * uA.z);
    // Reflejo tenue del entorno en el suelo pulido.
    col += environment(reflect(rd, vec3(0.0, 1.0, 0.0))) * 0.12 * fade;
  }
  // Halo rojo alrededor de los monolitos.
  col += uC1 * glowAcc * (0.5 + 1.0 * uA.y + 1.2 * uA.z) * uB.x;
  col += uC2 * uB.z * 0.05;
  col *= 1.0 - 0.35 * smoothstep(0.6, 1.4, length(p * vec2(0.9, 0.65)));
  float peak = max(col.r, max(col.g, col.b));
  if (peak > 0.85) {
    float k = (peak - 0.85) / 0.15;
    col *= (0.85 + 0.15 * k / (1.0 + k)) / peak;
  }
  col += (hash12(frag) - 0.5) / 255.0;
  fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

visuals.nativeSource:
class Visual final : public Scene {
  static constexpr int kFingers = 8;
  static constexpr float kGrow = 0.14f;
  // La edad sigue contando tras derrumbarse: así se sabe si el hueco estaba libre.
  struct Finger { float x, lean, width, height; double age; };
  float bass = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, bassCredit = 0;
  // Relojes en doble precisión: sin música es idéntico a 30 y 60 FPS.
  double clock = 0, sinceIdle = 0;
  std::array<Finger, kFingers> fingers{};
  uint32_t spawns = 0;

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }
  static float hashU(uint32_t x) {
    x ^= x >> 16; x *= 0x7feb352dU; x ^= x >> 15; x *= 0x846ca68bU; x ^= x >> 16;
    return float(x & 0xffffffu) / 16777216.0f;
  }
  static float holdTime(float cons) { return 0.25f + 0.6f * cons; }
  static float collapseTime(float cons) { return 0.3f + 0.9f * cons; }
  static int capacity(float detail) { return std::clamp(int(std::lround(3.0f + 2.5f * detail)), 3, kFingers); }

  static double lifeTime(float cons) { return double(kGrow + holdTime(cons) + collapseTime(cons)); }
  // Hace brotar un dedo en un hueco que estaba libre en el instante del brote;
  // carry es el tiempo que ya pasó desde entonces. tall alarga los dedos de
  // los golpes (1 = altura normal).
  void sprout(float strength, double carry, int limit, double life, float tall = 1.0f) {
    for (int i = 0; i < limit; i++) {
      Finger& fg = fingers[size_t(i)];
      if (fg.age - carry < life) continue;
      const uint32_t k = spawns++;
      fg.x = (hashU(k * 2654435761u + 3u) - 0.5f) * 0.72f;
      fg.lean = (hashU(k * 2246822519u + 7u) - 0.5f) * 0.5f;
      fg.width = 0.03f + 0.025f * hashU(k * 3266489917u + 11u);
      fg.height = (0.3f + 0.36f * hashU(k * 668265263u + 13u)) * std::clamp(strength, 0.35f, 1.2f);
      if (tall > 1.0f) fg.height = std::min(fg.height * tall, 0.85f);
      fg.age = carry;
      return;
    }
  }
  // Los golpes pueden usar dos huecos más que el resto: sin golpes nunca se
  // ocupan, así que sin música el dibujo no cambia.
  static int burstCapacity(float detail) { return std::min(kFingers, capacity(detail) + 2); }

 public:
  void reset(uint32_t seed) override {
    bass = spark = energy = slowBass = kick = flash = bassCredit = 0;
    clock = 0;
    sinceIdle = 0;
    for (auto& fg : fingers) fg = Finger{0, 0, 0.03f, 0, 1000.0};
    spawns = seed * 13u;
  }

  void update(const Frame& f) override {
    auto m = modifiers(f);
    const float dt = float(f.delta);
    const Music& mu = f.music;
    bass = follow(bass, mu.bass, 22.0f, 4.5f, dt);
    spark = follow(spark, mu.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, mu.energy, 6.0f, 1.8f, dt);
    float hit = 0, fl = 0;
    for (const auto& e : mu.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : mu.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : mu.events[3]) fl = std::max(fl, e.strength);
    const float onset = std::clamp((mu.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, mu.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    const bool fresh = hit > kick + 0.2f;
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    const double step = f.delta * f.speed;
    clock += step;
    const double life = lifeTime(std::clamp(m.consistencia, 0.0f, 1.0f));
    for (auto& fg : fingers) fg.age = std::min(fg.age + step, 1000.0);
    const int limit = capacity(f.detail);
    const float amp = f.intensity;
    // Golpes: cada golpe hace brotar de una vez varios dedos más altos, más
    // cuanto más fuerte, y puede usar dos huecos extra.
    if (m.pulso == 0 && fresh) {
      const int count = 1 + int(hit * amp * 3.5f);
      const float tall = 1.0f + 0.25f * std::min(hit * amp, 1.0f);
      const int burstLimit = burstCapacity(f.detail);
      for (int i = 0; i < count; i++) sprout(0.7f + 0.5f * hit * amp, 0.0, burstLimit, life, tall);
    }
    // Graves: los graves sostenidos hacen brotar dedos sin parar.
    if (m.pulso == 1) {
      bassCredit += bass * amp * float(step) * 7.0f;
      while (bassCredit >= 1.0f) {
        bassCredit -= 1.0f;
        sprout(0.5f + 0.8f * std::min(bass * amp, 1.0f), 0.0, limit, life);
      }
    }
    // A su ritmo la masa sigue viva; con música, más despacio.
    {
      const double period = !mu.active ? 0.5 : (m.pulso == 2 ? 0.7 : 1.0);
      sinceIdle += step;
      while (sinceIdle >= period) {
        sinceIdle -= period;
        sprout(0.85f, sinceIdle, limit, life);
      }
    }
  }

  void render(const Frame& f, Canvas& c) const override {
    auto g = glide(f);
    const float amp = f.intensity;
    const float cons = std::clamp(g.consistencia, 0.0f, 1.0f);
    const float hold = holdTime(cons), fall = collapseTime(cons);
    // Temblor: los agudos retuercen los dedos con más fuerza.
    const float wobble = (1.2f - cons) * (1.0f + 2.6f * g.pulso.weight(2) * std::min((spark + energy) * amp, 1.0f));
    // Los huecos extra sólo los ocupan los golpes; sin golpes siguen vacíos.
    const int limit = burstCapacity(f.detail);
    std::vector<float> u;
    u.reserve(64);
    const float tremble = g.pulso.weight(2) * std::min((spark * 1.2f + energy * 0.5f) * amp, 1.2f);
    // Golpes: la masa se enciende más con cada golpe.
    const float punch = std::min(kick * amp, 1.0f) * (1.0f + 0.5f * g.pulso.weight(0));
    u.insert(u.end(), {float(std::fmod(clock, 1000.0)), std::min(bass * amp, 1.5f), punch, tremble});
    u.insert(u.end(), {g.forma.weight(0), g.forma.weight(1), g.forma.weight(2), std::clamp(g.humedad, 0.0f, 1.0f)});
    u.insert(u.end(), {wobble, f.glow, std::min(flash * amp, 1.0f), std::min(bass * amp, 1.0f) * (0.4f + 0.6f * g.pulso.weight(1))});
    for (int i = 0; i < kFingers; i++) {
      const Finger& fg = fingers[size_t(i)];
      if (i >= limit || fg.age >= double(kGrow + hold + fall)) {
        u.insert(u.end(), {0.0f, 0.0f, 0.0f, 0.03f});
        continue;
      }
      // Crece con un rebote, se sostiene y se derrumba ensanchándose.
      float h, w = fg.width, lean = fg.lean;
      const float age = float(fg.age);
      if (age < kGrow) {
        const float e = age / kGrow - 1.0f;
        h = fg.height * (1.0f + 2.7f * e * e * e + 1.7f * e * e);
      } else if (age < kGrow + hold) {
        h = fg.height;
      } else {
        const float k = std::clamp((age - kGrow - hold) / fall, 0.0f, 1.0f);
        h = fg.height * (1.0f - k) * (1.0f - k);
        w *= 1.0f + 0.8f * k;
        lean += (lean >= 0 ? 0.6f : -0.6f) * k;
      }
      u.insert(u.end(), {fg.x, std::max(h, 0.0f), lean, w});
    }
    for (int i = 0; i < 4; i++) u.insert(u.end(), {f.colors[size_t(i)].r, f.colors[size_t(i)].g, f.colors[size_t(i)].b});
    // Pulso para el material: golpe, graves y agudos de su propia opción.
    u.insert(u.end(), {std::min(kick * amp, 1.0f) * g.pulso.weight(0), std::min(bass * amp, 1.0f) * g.pulso.weight(1),
                       std::min(spark * amp, 1.0f) * g.pulso.weight(2), 0.0f});
    c.material("oobleck", {0, 0, f.width, f.height}, u);
  }
};

shaderSources.oobleck:
#version 460 core
#include <flutter/runtime_effect.glsl>
uniform vec2 uSize;
uniform vec4 uA;   // tiempo, graves, golpe, temblor
uniform vec4 uB;   // pesos de forma: dedos, garras, bulbos; humedad
uniform vec4 uE;   // bamboleo, glow, destello, vibración del cono
uniform vec4 uF0;  // dedos: x, altura, inclinación, grosor
uniform vec4 uF1;
uniform vec4 uF2;
uniform vec4 uF3;
uniform vec4 uF4;
uniform vec4 uF5;
uniform vec4 uF6;
uniform vec4 uF7;
uniform vec3 uC0;
uniform vec3 uC1;
uniform vec3 uC2;
uniform vec3 uC3;
uniform vec4 uP;   // pulso: golpe, graves, agudos (cero sin música)
out vec4 fragColor;

float sq(float x) {
  return x * x;
}

const float BASE_Y = -0.135;

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

float smin(float a, float b, float k) {
  float h = clamp(0.5 + 0.5 * (b - a) / k, 0.0, 1.0);
  return mix(b, a, h) - k * h * (1.0 - h);
}

// Un dedo de masa: tronco que se estrecha y una punta según la forma.
float finger(vec2 p, vec4 F, float t) {
  float h = F.y;
  if (h < 0.004) return 1.0;
  // Lejos del dedo: su distancia basta con una cota.
  float bound = abs(F.z) * 2.2 * h + F.w * 2.0 + 0.06;
  if (abs(p.x - F.x) > bound + 0.06) return 1.0;
  float lean = F.z * (1.0 + 1.2 * uB.y);
  float s = clamp((p.y - BASE_Y) / h, 0.0, 1.0);
  float wob = uE.x * 0.02;
  float xc = F.x + lean * h * s * s + wob * s * sin(s * 7.0 + t * 6.0 + F.x * 23.0);
  float w = F.w;
  float r = w * (uB.x * (1.0 - 0.45 * s) + uB.y * (1.0 - 0.85 * s) + uB.z * (0.75 - 0.25 * s));
  float d = length(p - vec2(xc, BASE_Y + h * s)) - r;
  float tipR = w * (uB.x * 0.55 + uB.y * 0.12 + uB.z * 1.35);
  vec2 tip = vec2(F.x + lean * h + wob * sin(7.0 + t * 6.0 + F.x * 23.0), BASE_Y + h);
  return min(d, length(p - tip) - tipR);
}

float scene(vec2 p, float t) {
  // La masa sobre el cono: una elipse con la superficie que tiembla.
  vec2 q = p - vec2(0.0, -0.19);
  q.y += uA.w * 0.02 * sin(q.x * 40.0 + t * 22.0) + 0.006 * uA.y * sin(q.x * 9.0 - t * 5.0);
  float puddle = (length(q / vec2(0.44, 0.075)) - 1.0) * 0.075;
  // Golpes: la masa da un salto de tamaño (16 %). Graves: respira (12 %).
  puddle -= 0.075 * (0.16 * uP.x + 0.12 * uP.y);
  float k = 0.05;
  float d = puddle;
  d = smin(d, finger(p, uF0, t), k);
  d = smin(d, finger(p, uF1, t), k);
  d = smin(d, finger(p, uF2, t), k);
  d = smin(d, finger(p, uF3, t), k);
  d = smin(d, finger(p, uF4, t), k);
  d = smin(d, finger(p, uF5, t), k);
  d = smin(d, finger(p, uF6, t), k);
  d = smin(d, finger(p, uF7, t), k);
  return d;
}

void main() {
  vec2 frag = FlutterFragCoord().xy;
  float scale = min(uSize.x, uSize.y);
  vec2 p = (frag - 0.5 * uSize) / scale;
  p.y = -p.y;
  float t = uA.x;
  // Fondo: oscuridad con un foco desde arriba y el cono del altavoz.
  vec3 col = uC0 + uC1 * 0.1 * exp(-length(p - vec2(0.0, 0.55)) * 1.6);
  vec2 cq = vec2(p.x, (p.y + 0.19) * 2.6);
  // Graves: el cono vibra y sus anillos brillan.
  float r = length(cq) + uE.w * 0.01 * sin(t * 60.0);
  float cone = smoothstep(0.82, 0.78, r);
  vec3 coneCol = uC0 * 1.6 + uC1 * 0.05 * (1.0 - r);
  float rings = exp(-sq((r - 0.52) / 0.01)) + exp(-sq((r - 0.64) / 0.012)) + 0.6 * exp(-sq((r - 0.76) / 0.015));
  coneCol += uC2 * rings * (0.12 + 0.5 * uE.w);
  col = mix(col, coneCol, cone);
  // Golpes: resplandor aditivo alrededor de la masa. Graves: un halo suave
  // que respira con los graves.
  float haloAmt = uP.x * 0.4 + uP.y * 0.24;
  if (haloAmt > 0.0005) {
    vec2 hq = (p - vec2(0.0, -0.08)) / vec2(0.55, 0.36);
    col += mix(uC2, uC3, 0.35) * haloAmt * uE.y * exp(-dot(hq, hq) * 1.6);
  }
  // La masa sólo se calcula donde puede estar.
  float top = BASE_Y + max(max(max(uF0.y, uF1.y), max(uF2.y, uF3.y)), max(max(uF4.y, uF5.y), max(uF6.y, uF7.y))) + 0.1;
  if (p.y < top && abs(p.x) < 0.66 && p.y > -0.32) {
    float F = scene(p, t);
    float e = 1.5 / scale;
    // Sombra de contacto alrededor de la masa.
    col *= 1.0 - 0.5 * exp(-max(F, 0.0) * 30.0) * smoothstep(-0.05, -0.3, p.y);
    float inside = smoothstep(e, -e, F);
    if (inside > 0.0) {
      vec2 grad = vec2(scene(p + vec2(e, 0.0), t) - F, scene(p + vec2(0.0, e), t) - F) / e;
      float depth = clamp(-F / 0.05, 0.0, 1.0);
      vec3 n = normalize(vec3(grad * (1.0 - depth * 0.85), 0.25 + depth));
      vec3 L = normalize(vec3(-0.45, 0.65, 0.6));
      float diff = max(dot(n, L), 0.0);
      vec3 R = reflect(-L, n);
      float wet = uB.w;
      float spec = pow(max(R.z, 0.0), mix(6.0, 48.0, wet)) * mix(0.12, 1.1, wet);
      float rim = sq(1.0 - n.z);
      vec3 goo = mix(uC1, uC2, 0.3 + 0.7 * diff);
      // La luz se cuela por los bordes finos.
      goo += uC2 * rim * 0.35 * uE.y;
      goo += uC3 * spec;
      // Sin humedad parece polvo mate.
      goo *= mix(0.88 + 0.12 * hash12(floor(frag * 0.7)), 1.0, wet);
      goo *= 1.0 + 0.25 * uA.z + 0.1 * uE.z;
      // Música: todo esto vale cero sin música.
      if (uP.x + uP.y + uP.z > 0.0005) {
        // Golpes y graves: la luz de los bordes sube un 80 %.
        goo += uC2 * rim * 0.28 * uE.y * (uP.x + uP.y);
        // Golpes: la masa entera se enciende (+85 % con la subida de antes).
        goo *= 1.0 + 0.35 * uP.x;
        // Agudos: muchas chispas húmedas centellean por toda la masa.
        goo += uC3 * uP.z * 0.75 * step(0.86, hash12(floor(frag * 0.3) + floor(t * 12.0)));
      }
      col = mix(col, goo, inside);
    }
  }
  col *= 1.0 - 0.3 * smoothstep(0.6, 1.4, length(p * vec2(0.9, 0.65)));
  float peak = max(col.r, max(col.g, col.b));
  if (peak > 0.9) col *= (0.9 + 0.1 * (peak - 0.9) / (peak - 0.8)) / peak;
  col += (hash12(frag) - 0.5) / 255.0;
  fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

visuals.nativeSource:
class Visual final : public Scene {
  struct Bird { float u, v, su, cu, sv, cv, suv, cuv, sp, cp, size; int tone; };
  std::vector<Bird> birds;
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  // Reloj en doble precisión: la escena sin música es idéntica a 30 y 60 FPS.
  double clock = 0;
  float spread = 0, spreadVel = 0, twistKick = 0, twistVel = 0;
  // Reloj de las chispas de los agudos.
  double shimmer = 0;

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }
  static float hashU(uint32_t x) {
    x ^= x >> 16; x *= 0x7feb352dU; x ^= x >> 15; x *= 0x846ca68bU; x ^= x >> 16;
    return float(x & 0xffffffu) / 16777216.0f;
  }

 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    birds.clear();
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    clock = rng.unit() * 200.0;
    spread = spreadVel = twistKick = twistVel = 0;
    shimmer = 0;
  }

  void update(const Frame& f) override {
    auto mods = modifiers(f);
    float dt = float(f.delta);
    if (birds.empty()) {
      Random rng(f.seed + 11);
      int count = int(4000.0f + 2000.0f * std::clamp(f.detail, 0.25f, 2.0f));
      birds.resize(size_t(count));
      for (int i = 0; i < count; i++) {
        Bird& b = birds[size_t(i)];
        // Lámina elíptica, más densa en el centro.
        float r = std::sqrt(rng.unit());
        float a = rng.unit() * 6.2831853f;
        b.u = r * std::cos(a);
        b.v = r * std::sin(a);
        // Senos fijos de cada punto: los pliegues se animan sin trigonometría
        // por punto en cada cuadro (suma de ángulos).
        b.su = std::sin(b.u * 2.1f);
        b.cu = std::cos(b.u * 2.1f);
        b.sv = std::sin(b.v * 3.0f);
        b.cv = std::cos(b.v * 3.0f);
        b.suv = std::sin((b.u + b.v) * 1.7f);
        b.cuv = std::cos((b.u + b.v) * 1.7f);
        float ph = rng.unit() * 6.2831853f;
        b.sp = std::sin(ph);
        b.cp = std::cos(ph);
        b.size = 0.7f + rng.unit() * 0.6f;
        b.tone = rng.unit() < 0.12f ? 2 : (i % 2);
      }
    }
    const Music& m = f.music;
    bass = follow(bass, m.bass, 22.0f, 4.5f, dt);
    body = follow(body, m.body, 12.0f, 3.0f, dt);
    spark = follow(spark, m.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, m.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, m.active ? std::pow(std::clamp(m.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : m.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : m.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : m.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((m.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, m.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    if (hit > kick + 0.2f) {
      // Golpes: la bandada se retuerce con más fuerza.
      const float burst = mods.pulso == 0 ? 1.5f : 1.0f;
      spreadVel += 2.6f * hit;
      twistVel += 3.0f * hit * ((int(clock * 10.0) % 2) ? 1.0f : -1.0f) * burst;
    }
    shimmer += f.delta;
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    // La bandada se dispersa con el golpe y se vuelve a juntar con un muelle.
    spreadVel += (-spread * 10.0f - spreadVel * 3.2f) * dt;
    spread += spreadVel * dt;
    twistVel += (-twistKick * 6.0f - twistVel * 2.5f) * dt;
    twistKick += twistVel * dt;
    clock += f.delta * f.speed * (0.55 + 0.9 * drive);
  }

  void render(const Frame& f, Canvas& c) const override {
    auto gl = glide(f);
    float amp = f.intensity;
    // Pulso: cada opción mueve algo distinto; sin música todo vale cero.
    const float kickP = std::min(kick * amp, 1.0f) * gl.pulso.weight(0);
    const float bassP = std::min(bass * amp, 1.0f) * gl.pulso.weight(1);
    const float sparkP = std::min(spark * amp, 1.0f) * gl.pulso.weight(2);
    float w = f.width, h = f.height, s = std::min(w, h);
    double t = clock;
    std::vector<float> u;
    u.reserve(20);
    u.insert(u.end(), {bass * amp, kick * amp, energy, f.glow});
    u.insert(u.end(), {spark * amp, flash * amp, 0.0f, 0.0f});
    for (int i = 0; i < 4; i++) u.insert(u.end(), {f.colors[i].r, f.colors[i].g, f.colors[i].b});
    c.material("dusk_glow", {0, 0, w, h}, u);
    if (birds.empty()) return;

    // Términos que cambian una vez por cuadro.
    float c1 = float(std::cos(t * 0.7)), s1 = float(std::sin(t * 0.7));
    float c2 = float(std::cos(t * 0.9)), s2 = float(std::sin(t * 0.9));
    float c3 = float(std::cos(t * 0.5)), s3 = float(std::sin(t * 0.5));
    float cw = float(std::cos(t * 3.0)), sw = float(std::sin(t * 3.0));
    // Graves: la lámina se pliega más; Pliegues da la profundidad de base.
    float fold = 0.45f + 0.25f * bass + 0.3f * bassP;
    fold *= gl.pliegues;
    float twist = 1.1f * float(std::sin(t * 0.31)) + twistKick;
    float ax = 0.9f * float(std::sin(t * 0.23));
    float ay = float(t * 0.15) + 0.6f * float(std::sin(t * 0.19));
    float cax = std::cos(ax), sax = std::sin(ax), cay = std::cos(ay), say = std::sin(ay);
    float scale = 0.62f * (1.0f + 0.2f * float(std::sin(t * 0.4))) * (1.0f + 0.6f * std::max(-0.3f, spread)) * (1.0f + 0.08f * bassP);
    float cx = 0.18f * float(std::sin(t * 0.13)), cy = (h / s - 1.0f) * 0.25f * float(std::sin(t * 0.11 + 1.0));
    // Agudos: la bandada tiembla finamente.
    float jitter = 0.004f + 0.05f * std::max(0.0f, spread) + 0.022f * sparkP;
    std::array<std::vector<Vec2>, 3> groups;
    for (auto& g : groups) g.reserve(birds.size() / 2 + 1);
    // Espejo: la bandada gemela reflejada.
    const float mirror = std::clamp(gl.espejo, 0.0f, 1.0f);
    std::array<std::vector<Vec2>, 3> twins;
    if (mirror > 0.001f) for (auto& g : twins) g.reserve(birds.size() / 2 + 1);
    // Agudos: chispas sueltas que cambian 14 veces por segundo.
    std::vector<Vec2> glints;
    const uint32_t tick = uint32_t(std::fmod(shimmer, 100000.0) * 14.0);
    if (sparkP > 0.002f) glints.reserve(birds.size() / 10 + 1);
    for (const Bird& b : birds) {
      float x = b.u * 1.0f;
      float y = b.v * 0.55f;
      // Pliegues de la lámina: sin(a + t) = sin(a)cos(t) + cos(a)sin(t).
      float z = fold * ((b.su * c1 + b.cu * s1) + 0.75f * (b.sv * c2 - b.cv * s2) + 0.6f * (b.suv * c3 + b.cuv * s3));
      // Torsión a lo largo de la lámina.
      float ta = twist * b.u;
      float ct = std::cos(ta), st = std::sin(ta);
      float y1 = y * ct - z * st, z1 = y * st + z * ct;
      // Giro del conjunto.
      float y2 = y1 * cax - z1 * sax, z2 = y1 * sax + z1 * cax;
      float x3 = x * cay + z2 * say, z3 = -x * say + z2 * cay;
      // Aleteo individual.
      float wob = (b.sp * cw + b.cp * sw) * jitter;
      x3 += wob;
      y2 += wob * 0.7f;
      float persp = 2.6f / std::max(2.6f - z3 * scale, 0.6f);
      const Vec2 point{w * 0.5f + (cx + x3 * scale * persp) * s, h * 0.5f + (cy + y2 * scale * persp) * s};
      groups[size_t(b.tone)].push_back(point);
      if (mirror > 0.001f) twins[size_t(b.tone)].push_back({w - point.x, point.y});
      if (sparkP > 0.002f && hashU(uint32_t(&b - birds.data()) * 2654435761u + tick * 40503u) < 0.04f * sparkP) glints.push_back(point);
    }
    float px = s / 400.0f;
    float gain = std::clamp((0.85f + 0.4f * bass + 0.5f * kick) * amp, 0.0f, 1.6f);
    // Bruma: el halo de cada chispa; Graves lo hace respirar y Golpes lo agranda.
    const float haze = std::max(gl.bruma, 0.0f);
    for (int g = 0; g < 3; g++) {
      const Color& col = f.colors[1 + g];
      Paint halo;
      halo.blend = Blend::plus;
      halo.color = {col.r, col.g, col.b, std::clamp(0.025f * gain * f.glow * haze * (1.0f + 1.2f * bassP), 0.0f, 1.0f)};
      const float haloSize = 2.6f * px * std::max(haze, 0.3f) * (1.0f + 0.5f * kickP);
      c.points(groups[size_t(g)], haloSize, halo);
      Paint core;
      core.blend = Blend::plus;
      core.color = {col.r, col.g, col.b, std::clamp((g == 2 ? 0.7f : 0.38f) * gain * (0.8f + 0.2f * spark) * (1.0f + 0.4f * kickP), 0.0f, 1.0f)};
      // Golpes: las chispas dan un salto de tamaño.
      const float coreSize = (g == 2 ? 1.0f : 0.85f) * px * (1.0f + 0.6f * kickP);
      c.points(groups[size_t(g)], coreSize, core);
      if (mirror > 0.001f) {
        halo.color.a *= mirror;
        core.color.a *= mirror;
        c.points(twins[size_t(g)], haloSize, halo);
        c.points(twins[size_t(g)], coreSize, core);
      }
    }
    if (!glints.empty()) {
      const Color& col = f.colors[3];
      Paint gp;
      gp.blend = Blend::plus;
      gp.color = {col.r, col.g, col.b, std::clamp(0.8f * sparkP, 0.0f, 0.9f)};
      c.points(glints, 1.7f * px, gp);
    }
  }
};

shaderSources.dusk_glow:
#version 460 core
#include <flutter/runtime_effect.glsl>
uniform vec2 uSize;
uniform vec4 uA;   // graves, golpe, energía, glow
uniform vec4 uB;   // agudos, destello
uniform vec3 uC0;
uniform vec3 uC1;
uniform vec3 uC2;
uniform vec3 uC3;
out vec4 fragColor;

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

void main() {
  vec2 frag = FlutterFragCoord().xy;
  vec2 uv = frag / uSize;
  float scale = min(uSize.x, uSize.y);
  vec2 p = (frag - 0.5 * uSize) / scale;
  // Negro con un resplandor de brasa abajo que late con los graves.
  vec3 col = uC0 + uC2 * smoothstep(0.55, 1.0, uv.y) * (0.06 + 0.06 * uA.x + 0.08 * uA.y) * uA.w;
  col += uC1 * exp(-dot(p, p) * 2.5) * (0.02 + 0.06 * uA.y) * uA.w;
  col += uC3 * uB.y * 0.03;
  col *= 1.0 - 0.4 * smoothstep(0.5, 1.4, length(p * vec2(0.9, 0.65)));
  col += (hash12(frag) - 0.5) / 255.0;
  fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

