#include <metal_stdlib>
#include <simd/simd.h>

using namespace metal;

struct murmuracion_dusk_glow_fragment_main_out
{
    float4 fragColor [[color(0)]];
};

struct murmuracion_dusk_glow_fragment_main_in
{
    float2 _fragCoord [[user(locn0)]];
};

fragment murmuracion_dusk_glow_fragment_main_out murmuracion_dusk_glow_fragment_main(murmuracion_dusk_glow_fragment_main_in in [[stage_in]], constant float2& uSize [[buffer(0)]], constant float4& uA [[buffer(1)]], constant float4& uB [[buffer(2)]], constant float3& uC0 [[buffer(3)]], constant float3& uC1 [[buffer(4)]], constant float3& uC2 [[buffer(5)]], constant float3& uC3 [[buffer(6)]])
{
    murmuracion_dusk_glow_fragment_main_out out = {};
    float2 _80 = (in._fragCoord - (uSize * 0.5)) / float2(fast::min(uSize.x, uSize.y));
