  plate += uC2 * rim * (0.08 + 0.25 * sunHit + 0.15 * band);
  // Destellos sueltos con los agudos y fogonazo del destello sobre el metal.
  float tw = step(0.992 - 0.012 * uD.x, hash12(cellR + floor(uD.w * 7.0)));
