float shapeRadius(float type, vec2 q) {
  if (type < 0.5) return q.x * 0.72 + q.y;                         // rombo alto
  if (type < 1.5) return max(q.x * 0.95, q.x * 0.5 + q.y * 0.87);  // hexágono
  if (type < 2.5) {
    vec2 r = sqrt(q + 1e-5);                                       // estrella cóncava
    return (r.x + r.y) * (r.x + r.y) * 0.5;
  }
  return max(q.x * 1.25, (q.x * 0.55 + q.y) * 0.85);               // barras y rombo
}

vec3 waveColor(float id) {
  float k = mod(id, 4.0);
  return k < 1.0 ? uC1 : (k < 2.0 ? uC2 : (k < 3.0 ? vec3(1.0, 0.25, 0.2) : vec3(0.85, 0.92, 1.0)));
}

void main() {
  vec2 frag = FlutterFragCoord().xy;
  float scale = min(uSize.x, uSize.y);
  vec2 p = (frag - 0.5 * uSize) / scale;
  vec2 q = abs(p);
  float r = length(p);
  float t = uA.x;
  float kick = uA.z;

  // Sin nebulosa de fondo: el cristal flota sobre lo que haya detrás.
  vec3 col = uC0;

  // Contornos de neón que salen del centro.
  for (int k = 0; k < 4; k++) {
    float fk = float(k);
    float wave = uB.x * 0.35 + fk * 0.25;
    float id = floor(wave);
    float ph = fract(wave);
    float s = 0.11 * exp(ph * 3.3);
    float type = mod(id + hash11(id) * 3.0, 4.0);
    float F = shapeRadius(floor(type), q);
    float width = 0.0035 + 0.012 * s;
    float d = abs(F - s);
    float fade = smoothstep(0.0, 0.08, ph) * smoothstep(1.0, 0.7, ph);
    vec3 wc = waveColor(id);
    float isNew = smoothstep(0.25, 0.0, ph);
    float lineCore = exp(-d / (width * 0.35));
    float lineGlow = exp(-d / (width * 2.5));
    col += (wc * lineGlow * 0.55 + mix(wc, vec3(1.0), 0.6) * lineCore) * fade * (1.0 + 1.5 * kick * isNew) * uB.y;
    // Línea fina paralela, como un segundo trazo de alambre.
    float d2 = abs(F - s * 1.07);
    col += uC1 * exp(-d2 / (width * 0.25)) * fade * 0.35;
  }

  // Cristal central: facetas plegadas en espejo que giran despacio.
  float coreR = 0.24 * (1.0 + 0.12 * uA.y + 0.08 * kick);
  if (r < coreR * 1.6) {
    vec2 z = p / coreR;
    float edges = 0.0;
    for (int i = 0; i < 4; i++) {
      z = abs(z) - vec2(0.42, 0.3);
      float a = 0.7 + 0.05 * sin(t * 0.3 + float(i));
      z = vec2(cos(a) * z.x - sin(a) * z.y, sin(a) * z.x + cos(a) * z.y);
      edges += exp(-min(abs(z.x), abs(z.y)) * 28.0);
    }
    float body = smoothstep(1.15, 0.6, max(q.x * 0.8 + q.y, 0.0) / coreR);
    vec3 facet = mix(vec3(0.25, 0.15, 0.55), uC1, 0.4) * (0.35 + 0.25 * edges) + uC3 * edges * 0.12;
    col = mix(col, facet + col * 0.4, body * 0.85);
  }
  // Corazón blanco, destellos laterales y halo rosado.
  col += vec3(1.0, 0.95, 1.0) * (0.02 + 0.03 * uA.y + 0.05 * kick) / (r * r + 0.004) * exp(-r * r * 12.0);
  float flare = exp(-q.y * 60.0) * exp(-q.x * 2.2) + exp(-q.x * 90.0) * exp(-q.y * 6.0) * 0.4;
  col += mix(uC3, vec3(1.0), 0.5) * flare * (0.6 + 0.8 * kick);
  vec2 side = vec2(q.x - coreR * 0.95, q.y);
  col += uC3 * 0.012 / (dot(side, side) + 0.002) * (0.5 + 0.8 * uA.y) * exp(-dot(side, side) * 20.0);
  // Chispas alrededor del cristal con los agudos.
  vec2 cell = floor(p * 40.0);
  float sparkle = step(0.985 - 0.02 * uB.z, hash12(cell + floor(t * 10.0))) * smoothstep(0.6, 0.15, r);
  col += vec3(0.8, 0.9, 1.0) * sparkle * uB.z;

  col *= 1.0 - 0.3 * smoothstep(0.7, 1.5, length(p * vec2(0.9, 0.65)));
  float peak = max(col.r, max(col.g, col.b));
  if (peak > 0.85) {
    float e = (peak - 0.85) / 0.15;
    col *= (0.85 + 0.15 * e / (1.0 + e)) / peak;
  }
  // Fondo transparente: color premultiplicado y opacidad según el brillo; la
  // luz muy tenue se vuelve transparente del todo para no dejar velo.
  col = clamp(col, 0.0, 1.0);
  float veilPeak = max(col.r, max(col.g, col.b));
  float clearCut = smoothstep(0.04, 0.12, veilPeak);
  col *= clearCut;
  float alpha = clamp(veilPeak * 1.25, 0.0, 1.0) * clearCut;
  fragColor = vec4(col, alpha);
}

visuals.nativeSource:
class Visual final : public Scene {
  static constexpr int kSamples = 220;
  struct Item { float depth; int index; };
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  // Relojes en doble precisión: la escena sin música es idéntica a 30 y 60 FPS.
  double yaw = 0, pitch = 0, flow = 0, morph = 1, sinceKnot = 0;
  int knotFrom = 0, knotTo = 0, autoKnot = 0, beats = 0;
  mutable std::vector<Item> items;

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

  static std::array<float, 3> knot(int kind, float t) {
    static const float ps[5] = {2, 3, 2, 3, 5};
    static const float qs[5] = {3, 5, 5, 7, 8};
    float p = ps[kind], q = qs[kind];
    float r = 0.62f + 0.3f * std::cos(q * t);
    return {r * std::cos(p * t), 0.3f * std::sin(q * t), r * std::sin(p * t)};
  }

  void goTo(int next) {
    if (next == knotTo) return;
    knotFrom = knotTo;
    knotTo = next;
    morph = 0;
  }

 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    yaw = rng.unit() * 6.2831853;
    pitch = 0;
    flow = 0;
    morph = 1;
    sinceKnot = 0;
    knotFrom = knotTo = autoKnot = 0;
    beats = 0;
    items.reserve(kSamples);
  }

  void update(const Frame& f) override {
    auto m = modifiers(f);
    float dt = float(f.delta);
    const Music& mu = f.music;
    bass = follow(bass, mu.bass, 22.0f, 4.5f, dt);
    body = follow(body, mu.body, 12.0f, 3.0f, dt);
    spark = follow(spark, mu.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, mu.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, mu.active ? std::pow(std::clamp(mu.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : mu.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : mu.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : mu.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((mu.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, mu.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    sinceKnot += f.delta;
    if (hit > kick + 0.2f) {
      beats++;
      if (beats % 8 == 0) {
        autoKnot = (autoKnot + 1) % 5;
        sinceKnot = 0;
      }
    }
    if (!mu.active && sinceKnot > 8.0) {
      autoKnot = (autoKnot + 1) % 5;
      sinceKnot -= 8.0;
    }
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    goTo(m.nudo == 0 ? autoKnot : m.nudo - 1);
    morph = std::min(morph + f.delta / 1.8, 1.0);
    yaw += f.delta * f.speed * m.giro * (0.25 + 0.5 * drive);
    pitch += f.delta * f.speed * m.giro * 0.17;
    flow += f.delta * f.speed * (0.5 + 1.5 * drive + 1.0 * kick);
  }

  void render(const Frame& f, Canvas& c) const override {
    auto m = modifiers(f);
    float amp = f.intensity;
    const Color& bg = f.colors[0];
    const Color& yellow = f.colors[1];
    const Color& red = f.colors[2];
    const Color& orange = f.colors[3];
    c.rect({0, 0, f.width, f.height},
           Paint::radial({f.width * 0.5f, f.height * 0.5f}, std::max(f.width, f.height) * 0.7f,
                         {Color{std::min(1.0f, bg.r + orange.r * 0.09f * (1.0f + bass)), std::min(1.0f, bg.g + orange.g * 0.05f),
                                std::min(1.0f, bg.b + 0.01f), 1.0f},
                          Color{bg.r, bg.g, bg.b, 1.0f}}));
    float side = std::min(f.width, f.height);
    float scale = side * 0.66f;
    float cy = float(std::cos(yaw)), sy = float(std::sin(yaw));
    float tilt = 0.5f + 0.35f * float(std::sin(pitch));
    float cp = std::cos(tilt), sp = std::sin(tilt);
    float mo = float(morph);
    mo = mo * mo * (3.0f - 2.0f * mo);
    struct P { float x, y, z, s; };
    std::array<P, kSamples + 1> pts{};
    for (int i = 0; i <= kSamples; i++) {
      float t = 6.2831853f * float(i) / float(kSamples);
      auto a = knot(knotFrom, t);
      auto b = knot(knotTo, t);
      float x = a[0] + (b[0] - a[0]) * mo, y = a[1] + (b[1] - a[1]) * mo, z = a[2] + (b[2] - a[2]) * mo;
      float rx = x * cy + z * sy, rz = -x * sy + z * cy;
      float ry = y * cp - rz * sp;
      float rzz = y * sp + rz * cp;
      float s = 2.4f / (3.0f + rzz);
      pts[size_t(i)] = {f.width * 0.5f + rx * s * scale, f.height * 0.5f - ry * s * scale, rzz, s};
    }
    // Halo naranja detrás de todo el nudo.
    Path whole;
    for (int i = 0; i <= kSamples; i++) {
      if (i == 0) whole.moveTo(pts[0].x, pts[0].y); else whole.lineTo(pts[size_t(i)].x, pts[size_t(i)].y);
    }
    float tube = 0.075f * m.grosor * (1.0f + 0.25f * bass * amp);
    Paint halo;
    halo.blend = Blend::plus;
    halo.strokeWidth = tube * scale * 2.4f * 2.2f;
    halo.strokeJoin = 1;
    halo.color = orange.opacity(std::clamp((0.045f + 0.07f * bass) * f.glow * amp, 0.0f, 1.0f));
    c.path(whole, halo);

    items.clear();
    for (int i = 0; i < kSamples; i++) items.push_back({(pts[size_t(i)].z + pts[size_t(i + 1)].z) * 0.5f, i});
    std::sort(items.begin(), items.end(), [](const Item& l, const Item& r) { return l.depth > r.depth; });
    float stripes = 14.0f;
    float lit = (1.0f + 0.35f * kick) * amp;
    for (const Item& it : items) {
      const P& a = pts[size_t(it.index)];
      const P& b = pts[size_t(it.index + 1)];
      float w = tube * 2.0f * (a.s + b.s) * 0.5f * scale;
      float dx = b.x - a.x, dy = b.y - a.y;
      float len = std::sqrt(dx * dx + dy * dy);
      float nx = len > 1e-3f ? -dy / len : 1.0f, ny = len > 1e-3f ? dx / len : 0.0f;
      Vec2 mid{(a.x + b.x) * 0.5f, (a.y + b.y) * 0.5f};
      float u = float(it.index) / float(kSamples) * stripes - float(std::fmod(flow, 1000.0));
      bool isRed = m.franjas && (u - std::floor(u)) < 0.35f;
      const Color& base = isRed ? red : yellow;
      // Lo lejano se ve más oscuro.
      float depthShade = std::clamp(1.05f - (a.z + b.z) * 0.35f, 0.45f, 1.2f) * lit;
      auto shade = [&](float g) {
        return Color{std::min(1.0f, base.r * g * depthShade), std::min(1.0f, base.g * g * depthShade),
                     std::min(1.0f, base.b * g * depthShade), 1.0f};
      };
      Color shine{std::min(1.0f, 0.9f * depthShade + 0.1f), std::min(1.0f, 0.85f * depthShade + 0.1f), std::min(1.0f, 0.7f * depthShade), 1.0f};
      Paint p = Paint::linear({mid.x - nx * w * 0.5f, mid.y - ny * w * 0.5f}, {mid.x + nx * w * 0.5f, mid.y + ny * w * 0.5f},
                              {shade(0.22f), shade(0.95f), shine, shade(0.85f), shade(0.15f)}, {0.0f, 0.3f, 0.42f, 0.6f, 1.0f});
      p.strokeWidth = w;
      p.strokeCap = 1;
      Path seg;
      seg.moveTo(a.x, a.y).lineTo(b.x, b.y);
      c.path(seg, p);
    }
    if (flash > 0.01f) {
      Paint fl;
      fl.blend = Blend::plus;
      fl.color = orange.opacity(std::clamp(flash * 0.05f * amp, 0.0f, 1.0f));
      c.rect({0, 0, f.width, f.height}, fl);
    }
  }
};

class Visual final : public Scene {
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  // Relojes en doble precisión: la escena sin música es idéntica a 30 y 60 FPS.
  double clock = 0, flow = 0, look = 0;
  float squeeze = 0, squeezeVel = 0;

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    clock = rng.unit() * 3.0;
    flow = rng.unit() * 10.0;
    look = rng.unit() * 20.0;
    squeeze = squeezeVel = 0;
  }

  void update(const Frame& f) override {
    float dt = float(f.delta);
    const Music& m = f.music;
    bass = follow(bass, m.bass, 22.0f, 4.5f, dt);
    body = follow(body, m.body, 12.0f, 3.0f, dt);
    spark = follow(spark, m.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, m.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, m.active ? std::pow(std::clamp(m.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : m.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : m.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : m.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((m.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, m.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    if (hit > kick + 0.2f) squeezeVel += 3.0f * hit;
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    // La pupila se contrae con el golpe y vuelve con un muelle.
    squeezeVel += (-squeeze * 35.0f - squeezeVel * 7.0f) * dt;
    squeeze += squeezeVel * dt;
    clock += f.delta;
    flow += f.delta * f.speed * (0.5 + 1.2 * drive + 0.6 * bass);
    look += f.delta * f.speed * (0.25 + 0.5 * drive);
  }

  void render(const Frame& f, Canvas& c) const override {
    float amp = f.intensity;
    // Mirada: el iris se desplaza despacio dentro del ojo.
    float gx = 0.06f * float(std::sin(look * 0.7) + 0.4 * std::sin(look * 1.9));
    float gy = 0.025f * float(std::sin(look * 0.53 + 1.0));
    // Parpadeo cada siete segundos: cierre y apertura en un tercio de segundo.
    double bt = std::fmod(clock, 7.0);
    float open = bt < 0.32 ? float(std::fabs(bt - 0.16) / 0.16) : 1.0f;
    open = open * open * (3.0f - 2.0f * open);
    float pupil = 0.055f * (1.0f + 0.5f * bass * amp) * (1.0f - 0.35f * std::max(0.0f, squeeze) * amp);
    std::vector<float> u;
    u.reserve(24);
    u.insert(u.end(), {float(std::fmod(flow, 1000.0)), bass * amp, kick * amp, energy});
    u.insert(u.end(), {gx, gy, open, pupil});
    u.insert(u.end(), {f.glow, spark * amp, flash * amp, float(std::fmod(clock, 1000.0))});
    for (int i = 0; i < 4; i++) u.insert(u.end(), {f.colors[i].r, f.colors[i].g, f.colors[i].b});
    c.material("psy_eye", {0, 0, f.width, f.height}, u);
  }
};

shaderSources.psy_eye:
#version 460 core
#include <flutter/runtime_effect.glsl>
uniform vec2 uSize;
uniform vec4 uA;   // flujo de las ondas, graves, golpe, energía
uniform vec4 uE;   // mirada x, mirada y, apertura del párpado, radio de la pupila
uniform vec4 uB;   // glow, agudos, destello, reloj
uniform vec3 uC0;
uniform vec3 uC1;
uniform vec3 uC2;
uniform vec3 uC3;
out vec4 fragColor;

const float TAU = 6.2831853;

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash12(i), hash12(i + vec2(1.0, 0.0)), u.x),
             mix(hash12(i + vec2(0.0, 1.0)), hash12(i + vec2(1.0, 1.0)), u.x), u.y);
}

// Bandas de pintura: rojo, naranja, crema, turquesa y vuelta.
vec3 bands(float x) {
  float k = fract(x) * 5.0;
  vec3 cream = vec3(1.0, 0.86, 0.62);
  vec3 a = k < 1.0 ? uC1 : (k < 2.0 ? uC2 : (k < 3.0 ? cream : (k < 4.0 ? uC3 : uC2)));
  vec3 b = k < 1.0 ? uC2 : (k < 2.0 ? cream : (k < 3.0 ? uC3 : (k < 4.0 ? uC2 : uC1)));
  return mix(a, b, smoothstep(0.75, 1.0, fract(k)));
}

void main() {
  vec2 frag = FlutterFragCoord().xy;
  float scale = min(uSize.x, uSize.y);
  vec2 p = (frag - 0.5 * uSize) / scale;
  float t = uA.x;
  float W = 0.44;
  float H = 0.24 * uE.z + 0.004;
  // Forma de almendra: el párpado superior y el inferior.
  float x = clamp(p.x / W, -1.0, 1.0);
  float lid = 1.0 - x * x;
  float upper = H * lid * (1.0 + 0.15 * (1.0 - x * x));
  float lower = -H * 0.85 * lid;
  float eyeDist = max(p.y - upper, lower - p.y);
  float outside = abs(p.x) > W ? 1.0 : 0.0;
  float contour = outside > 0.5 ? length(vec2(abs(p.x) - W, p.y)) : max(eyeDist, 0.0);

  // Ondas que siguen la forma del ojo y gotean hacia abajo.
  float drip = pow(noise(vec2(p.x * 6.0, 3.0)), 3.0) * 0.25 * smoothstep(0.0, -0.6, p.y);
  float warp = noise(p * 3.0 + vec2(0.0, t * 0.2)) * 0.12 + drip;
  float waveX = (contour + warp) * 5.5 - t * 0.6;
  vec3 col = bands(waveX) * (0.75 + 0.35 * uA.y + 0.3 * uA.z);
  // Trazos oscuros entre bandas, como pinceladas.
  float stroke = abs(fract(waveX * 5.0) - 0.5);
  col *= 0.82 + 0.18 * smoothstep(0.0, 0.25, stroke);
  col = mix(col, uC0, smoothstep(0.5, 1.3, length(p * vec2(0.9, 0.65))) * 0.5);

  if (eyeDist < 0.0 && outside < 0.5) {
    // Blanco del ojo con venitas rojas y sombra bajo el párpado.
    float veins = smoothstep(0.92, 1.0, 1.0 - abs(noise(p * 18.0) - 0.5) * 2.0) * 0.5;
    vec3 sclera = mix(vec3(1.0, 0.93, 0.85), vec3(0.95, 0.75, 0.6), smoothstep(0.0, 0.5, length(p) * 1.4));
    sclera = mix(sclera, uC1, veins * smoothstep(0.08, 0.3, length(p)));
    sclera *= 0.75 + 0.25 * smoothstep(0.0, 0.06, -eyeDist);
    vec2 ic = vec2(uE.x, uE.y);
    vec2 d = p - ic;
    float r = length(d);
    float a = atan(d.y, d.x) + uB.w * 0.05;
    float Ri = 0.17;
    vec3 eye = sclera;
    if (r < Ri) {
      // Iris: fibras radiales turquesa con un anillo dorado junto a la pupila.
      float fibers = noise(vec2(a * 18.0 / TAU * 6.0, r * 30.0)) * 0.6 + noise(vec2(a * 40.0 / TAU * 6.0, r * 60.0)) * 0.4;
      vec3 iris = mix(uC3 * 0.45, mix(uC3, vec3(0.6, 1.0, 0.95), 0.4), fibers);
      iris = mix(iris, uC2 * 1.1, smoothstep(uE.w * 2.1, uE.w * 1.1, r) * 0.85);
      iris *= 0.6 + 0.4 * smoothstep(Ri, Ri * 0.8, r);
      iris += uC2 * smoothstep(0.98, 1.0, fibers) * uB.y;
      float ring = smoothstep(Ri - 0.012, Ri, r);
      iris = mix(iris, uC3 * 0.15, ring);
      eye = mix(iris, vec3(0.0), smoothstep(uE.w + 0.004, uE.w - 0.002, r));
    }
    // Brillo húmedo de la córnea.
    vec2 hl = p - (ic + vec2(-0.05, 0.05));
    eye += vec3(1.0) * exp(-dot(hl, hl) * 900.0) * 0.9;
    col = mix(col, eye, smoothstep(0.0, 0.006, -eyeDist));
  }
  // Borde del párpado oscuro y pestañas sugeridas.
  float lidLine = exp(-abs(eyeDist) * 160.0) * (1.0 - outside);
  col = mix(col, vec3(0.08, 0.02, 0.02), lidLine * 0.9);
  float lashes = (1.0 - outside) * smoothstep(0.04, 0.0, p.y - upper) * step(upper, p.y) *
                 smoothstep(0.6, 1.0, abs(sin(p.x * 70.0)));
  col = mix(col, vec3(0.06, 0.02, 0.02), lashes * 0.7);
  col += uC2 * uB.z * 0.06;
  col += (hash12(frag) - 0.5) / 255.0;
  fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

