    }
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    tau += f.delta * f.speed * (1.0 + 1.2 * drive);
  }

  void render(const Frame& f, Canvas& c) const override {
    auto m = modifiers(f);
    float amp = f.intensity;
    const Color& c1 = f.colors[1];
    const Color& c2 = f.colors[2];
    const Color& c3 = f.colors[3];
    int n = std::clamp(m.pendulos, 10, kMax);
    float side = std::min(f.width, f.height);
    float px = side / 400.0f;
    float top = f.height * 0.08f, bottom = f.height * 0.92f;
    float cx = f.width * 0.5f;
    float swing = f.width * 0.42f * m.amplitud * (0.85f + 0.2f * bass * amp);
    double period = std::max(5.0, double(m.ciclo));
    // Destello del golpe que baja por la fila.
    float sweep = float(sinceHit) * 2.2f;
    auto bobX = [&](int k, double t) {
      double phase = 6.283185307179586 * double(20 + k) * t / period;
      return cx + swing * float(std::cos(phase));
    };
    auto rowY = [&](int k) { return top + (bottom - top) * (float(k) + 0.5f) / float(n); };

    // Guías de cada fila y eje central.
    Path guides;
    for (int k = 0; k < n; k++) {
      float y = rowY(k);
      guides.moveTo(cx - swing, y).lineTo(cx + swing, y);
    }
    Paint guide;
    guide.strokeWidth = 1.0f * px;
    guide.color = c1.opacity(0.12f);
    c.path(guides, guide);
    Path axis;
    axis.moveTo(cx, top - 8.0f * px).lineTo(cx, bottom + 8.0f * px);
    Paint ax;
    ax.strokeWidth = 1.2f * px;
    ax.color = c2.opacity(0.18f + 0.2f * kick * amp);
    c.path(axis, ax);

    // Hilos desde el eje hasta cada bola.
    Path threads;
    for (int k = 0; k < n; k++) {
      float y = rowY(k);
      threads.moveTo(cx, y).lineTo(bobX(k, tau), y);
    }
    Paint thread;
    thread.strokeWidth = 1.4f * px;
    thread.blend = Blend::plus;
    thread.color = c2.opacity(std::clamp(0.22f * amp, 0.0f, 1.0f));
    c.path(threads, thread);

    // Línea que une las bolas: la serpiente.
    if (m.curva) {
      Path curve;
      for (int k = 0; k < n; k++) {
        float x = bobX(k, tau), y = rowY(k);
        if (k == 0) curve.moveTo(x, y); else curve.lineTo(x, y);
      }
      Paint glowLine;
      glowLine.blend = Blend::plus;
      glowLine.strokeWidth = 7.0f * px;
      glowLine.strokeJoin = 1;
      glowLine.strokeCap = 1;
      glowLine.color = c1.opacity(std::clamp((0.16f + 0.2f * bass) * f.glow * amp, 0.0f, 1.0f));
      c.path(curve, glowLine);
      Paint line;
      line.blend = Blend::plus;
      line.strokeWidth = 2.0f * px;
      line.strokeJoin = 1;
      line.strokeCap = 1;
      line.color = c3.opacity(std::clamp((0.55f + 0.3f * energy) * amp, 0.0f, 1.0f));
      c.path(curve, line);
    }

    // Estelas: posiciones de las bolas un poco antes en el tiempo.
    float radius = std::min(9.0f * px, (bottom - top) / float(n) * 0.36f) * (1.0f + 0.25f * bass * amp);
    if (m.estelas) {
      for (int j = kTrail; j >= 1; j--) {
        std::vector<Vec2> pts;
        pts.reserve(size_t(n));
        double t = tau - double(j) * 0.018 * (1.0 + drive);
        for (int k = 0; k < n; k++) pts.push_back({bobX(k, t), rowY(k)});
        float fade = 1.0f - float(j) / float(kTrail + 1);
        Paint tp;
        tp.blend = Blend::plus;
        tp.color = c1.opacity(std::clamp(0.22f * fade * amp, 0.0f, 1.0f));
        c.points(pts, radius * (0.45f + 0.5f * fade), tp);
      }
    }

    // Bolas: color por fila del rojo al amarillo, halo y núcleo.
    for (int k = 0; k < n; k++) {
      float t = float(k) / float(n - 1);
      Color col = mix3(c1, c2, c3, t);
      float x = bobX(k, tau), y = rowY(k);
      float d = (sweep - float(k) / float(n) * 1.2f);
      float lit = sinceHit < 2.0 ? hitPower * std::exp(-d * d * 30.0f) : 0.0f;
      float r = radius * (1.0f + 0.6f * lit);
      Paint halo = Paint::radial({x, y}, r * 3.2f, {col.opacity(std::clamp((0.35f + 0.5f * lit) * f.glow * amp, 0.0f, 1.0f)), col.opacity(0.0f)});
      halo.blend = Blend::plus;
      c.circle({x, y}, r * 3.2f, halo);
      Paint core = Paint::radial({x - r * 0.3f, y - r * 0.3f}, r * 1.3f,
                                 {Color{1.0f, 0.97f, 0.9f, 1.0f}, col, Color{col.r * 0.5f, col.g * 0.5f, col.b * 0.5f, 1.0f}}, {0.0f, 0.45f, 1.0f});
      c.circle({x, y}, r, core);
    }
  }
};

class Visual final : public Scene {
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  // Fase en doble precisión: la escena sin música es idéntica a 30 y 60 FPS.
  double phase = 0, swirl = 0;
  float ringR = 30.0f, ringAmp = 0;

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

  static Color shade(const Color& c, float g) {
    return {std::min(1.0f, c.r * g), std::min(1.0f, c.g * g), std::min(1.0f, c.b * g), 1.0f};
  }

  static Color blend(const Color& a, const Color& b, float t) {
    return {a.r + (b.r - a.r) * t, a.g + (b.g - a.g) * t, a.b + (b.b - a.b) * t, 1.0f};
  }

 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    phase = rng.unit() * 6.2831853;
    swirl = rng.unit() * 6.2831853;
    ringR = 30.0f;
    ringAmp = 0;
  }

  void update(const Frame& f) override {
    float dt = float(f.delta);
    const Music& m = f.music;
    bass = follow(bass, m.bass, 22.0f, 4.5f, dt);
    body = follow(body, m.body, 12.0f, 3.0f, dt);
    spark = follow(spark, m.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, m.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, m.active ? std::pow(std::clamp(m.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : m.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : m.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : m.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((m.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, m.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    if (hit > kick + 0.2f) {
      ringR = 0.0f;
      ringAmp = hit;
    }
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    ringR += dt * (9.0f + 4.0f * drive);
    ringAmp *= std::exp(-dt * 1.4f);
    phase += f.delta * f.speed * (1.4 + 2.2 * drive);
    swirl += f.delta * f.speed * 0.15;
  }

  void render(const Frame& f, Canvas& c) const override {
    float amp = f.intensity;
    std::vector<float> u;
    u.reserve(20);
    u.insert(u.end(), {float(std::fmod(phase, 1000.0)), bass * amp, kick * amp, energy});
    u.insert(u.end(), {f.glow, spark * amp, flash * amp, 0.0f});
    for (int i = 0; i < 4; i++) u.insert(u.end(), {f.colors[i].r, f.colors[i].g, f.colors[i].b});
    c.material("cube_floor", {0, 0, f.width, f.height}, u);

    int n = int(15.0f + 4.0f * std::clamp(f.detail, 0.25f, 2.0f));
    float hw = f.width / (float(n) * 0.82f);  // medio ancho de una baldosa
    float hh = hw * 0.5f;
    float cx = f.width * 0.5f;
    float top = f.height * 0.5f - float(n) * hh + hw * 1.2f;
    float center = float(n - 1) * 0.5f;
    float t = float(std::fmod(phase, 6283.0));
    float baseH = hw * 1.2f;
    float waveH = hw * (1.6f + 1.4f * bass) * amp;
    const Color& coral = f.colors[1];
    const Color& ivory = f.colors[2];
    const Color& deep = f.colors[3];
    float glowKick = 1.0f + 0.35f * kick * amp + 0.25f * flash * amp;
    float sw = float(std::sin(swirl));
    // Pintor: diagonales de atrás hacia delante.
    for (int sum = 0; sum <= 2 * (n - 1); sum++) {
      for (int i = std::max(0, sum - (n - 1)); i <= std::min(n - 1, sum); i++) {
        int j = sum - i;
        float X = cx + float(i - j) * hw;
        float Y = top + float(i + j) * hh;
        float di = float(i) - center, dj = float(j) - center;
        float d = std::sqrt(di * di + dj * dj);
        float wave = 0.5f + 0.5f * std::sin(d * 0.55f - t + sw * 0.4f * di * 0.1f);
        float ring = ringAmp * std::exp(-(d - ringR) * (d - ringR) * 0.25f);
        float k = std::clamp(wave + 0.9f * ring * amp, 0.0f, 1.8f);
        float H = baseH + waveH * k;
        // Recorte: columnas fuera de la pantalla no se dibujan.
        if (X + hw < 0 || X - hw > f.width || Y - hh - H > f.height || Y + hh < 0) continue;
        float lift = std::clamp(k / 1.2f, 0.0f, 1.0f);
        Color topC = shade(blend(blend(coral, ivory, 0.8f), ivory, lift), (0.82f + 0.25f * lift) * glowKick);
        Color leftC = shade(blend(coral, deep, 0.15f - 0.15f * lift), (0.75f + 0.3f * lift) * glowKick);
        Color rightC = shade(blend(coral, deep, 0.55f), (0.6f + 0.2f * lift) * glowKick);
        Path left, right, cap;
        left.moveTo(X - hw, Y - H).lineTo(X, Y + hh - H).lineTo(X, Y + hh).lineTo(X - hw, Y).close();
        right.moveTo(X, Y + hh - H).lineTo(X + hw, Y - H).lineTo(X + hw, Y).lineTo(X, Y + hh).close();
        cap.moveTo(X, Y - hh - H).lineTo(X + hw, Y - H).lineTo(X, Y + hh - H).lineTo(X - hw, Y - H).close();
        Paint pl, pr, pt;
        pl.color = leftC;
        pr.color = rightC;
        pt.color = topC;
        c.path(left, pl);
        c.path(right, pr);
        c.path(cap, pt);
      }
    }
  }
};

