class Visual final : public Scene {
  static constexpr int kMax = 400;
  static constexpr int kTrail = 10;
  static constexpr double kStep = 1.0 / 120.0;
  struct State { double a1, a2, w1, w2; };
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  // Relojes en doble precisión: la escena sin música es idéntica a 30 y 60 FPS.
  double sim = 0, sinceReset = 0;
  int64_t steps = 0;
  int count = 0;
  bool resetPending = false;
  Random rng{1};
  std::vector<State> st;
  std::vector<float> trailX, trailY;
  int trailHead = 0, trailCount = 0;
  // Empujón del último golpe (con su lado) y reloj del centelleo.
  double swingAge = 100, shimmer = 0;
  float swingPow = 0;
  int swingSide = 0;

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }
  static float hashU(uint32_t x) {
    x ^= x >> 16; x *= 0x7feb352dU; x ^= x >> 15; x *= 0x846ca68bU; x ^= x >> 16;
    return float(x & 0xffffffu) / 16777216.0f;
  }

  // Ecuaciones del péndulo doble con masas iguales y brazos l1 y l2
  // (l1 + l2 = 2: el alcance total no cambia).
  static void deriv(const State& s, double l1, double l2, double& d1, double& d2) {
    const double g = 9.81;
    double delta = s.a1 - s.a2;
    double den = 3.0 - std::cos(2.0 * delta);
    d1 = (-3.0 * g * std::sin(s.a1) - g * std::sin(s.a1 - 2.0 * s.a2) -
          2.0 * std::sin(delta) * (s.w2 * s.w2 * l2 + s.w1 * s.w1 * l1 * std::cos(delta))) / (l1 * den);
    d2 = (2.0 * std::sin(delta) * (2.0 * s.w1 * s.w1 * l1 + 2.0 * g * std::cos(s.a1) + s.w2 * s.w2 * l2 * std::cos(delta))) / (l2 * den);
  }

  static State rk4(const State& s, double h, double l1, double l2) {
    double k1a, k1b, k2a, k2b, k3a, k3b, k4a, k4b;
    deriv(s, l1, l2, k1a, k1b);
    State s2{s.a1 + 0.5 * h * s.w1, s.a2 + 0.5 * h * s.w2, s.w1 + 0.5 * h * k1a, s.w2 + 0.5 * h * k1b};
    deriv(s2, l1, l2, k2a, k2b);
    State s3{s.a1 + 0.5 * h * s2.w1, s.a2 + 0.5 * h * s2.w2, s.w1 + 0.5 * h * k2a, s.w2 + 0.5 * h * k2b};
    deriv(s3, l1, l2, k3a, k3b);
    State s4{s.a1 + h * s3.w1, s.a2 + h * s3.w2, s.w1 + h * k3a, s.w2 + h * k3b};
    deriv(s4, l1, l2, k4a, k4b);
    return {s.a1 + h / 6.0 * (s.w1 + 2.0 * s2.w1 + 2.0 * s3.w1 + s4.w1),
            s.a2 + h / 6.0 * (s.w2 + 2.0 * s2.w2 + 2.0 * s3.w2 + s4.w2),
            s.w1 + h / 6.0 * (k1a + 2.0 * k2a + 2.0 * k3a + k4a),
            s.w2 + h / 6.0 * (k1b + 2.0 * k2b + 2.0 * k3b + k4b)};
  }

  // Brazos de un péndulo con el brazo de abajo [ratio] veces el de arriba.
  static void armLengths(float ratio, double& l1, double& l2) {
    const double r = std::clamp(double(ratio), 0.45, 2.2);
    l1 = 2.0 / (1.0 + r);
    l2 = 2.0 - l1;
  }

  void restart(double cycle) {
    double a = 3.14159265358979 * (0.62 + 0.3 * double(rng.unit()));
    double b = a + (double(rng.unit()) - 0.5) * 1.2;
    if (rng.unit() < 0.5f) {
      a = -a;
      b = -b;
    }
    // El caos multiplica por 10 la diferencia inicial cada ~1,4 s: un ciclo
    // corto parte de diferencias mayores y se abre antes. El abanico se abre
    // hacia el 30% del ciclo (20 s: 1,5e-6 rad, como siempre).
    const double spread = 1.5e-6 * std::exp(0.6 * (20.0 - std::clamp(cycle, 10.0, 40.0)));
    for (int i = 0; i < count; i++) {
      double e = spread * double(i);
      st[size_t(i)] = {a + e, b, 0.0, 0.0};
    }
    sinceReset = 0;
    resetPending = false;
    std::fill(trailX.begin(), trailX.end(), 0.0f);
    std::fill(trailY.begin(), trailY.end(), 0.0f);
    trailHead = -1;
    trailCount = 0;
  }

 public:
  void reset(uint32_t seed) override {
    rng = Random(seed);
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    sim = 0;
    steps = 0;
    count = 0;
    st.assign(kMax, State{0, 0, 0, 0});
    trailX.assign(size_t(kMax * kTrail), 0.0f);
    trailY.assign(size_t(kMax * kTrail), 0.0f);
    trailHead = -1;
    trailCount = 0;
    sinceReset = 0;
    resetPending = false;
    swingAge = 100;
    shimmer = 0;
    swingPow = 0;
    swingSide = 0;
  }

  void update(const Frame& f) override {
    auto m = modifiers(f);
    auto gl = glide(f);
    float dt = float(f.delta);
    const Music& mu = f.music;
    bass = follow(bass, mu.bass, 22.0f, 4.5f, dt);
    body = follow(body, mu.body, 12.0f, 3.0f, dt);
    spark = follow(spark, mu.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, mu.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, mu.active ? std::pow(std::clamp(mu.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : mu.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : mu.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : mu.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((mu.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, mu.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    bool beat = hit > kick + 0.2f;
    // Golpes: cada golpe empuja el conjunto, alternando el lado.
    swingAge += f.delta;
    shimmer += f.delta;
    if (beat) {
      swingAge = 0.0;
      swingPow = hit * ((swingSide++ % 2) == 0 ? 1.0f : -1.0f);
    }
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));

    int want = std::clamp(m.pendulos, 10, kMax);
    if (want != count) {
      count = want;
      restart(double(m.ciclo));
    }
    // Con música, un golpe fuerte reúne a los péndulos cuando ya hay caos.
    if (beat && hit > 0.6f && sinceReset > double(m.ciclo) * 0.6) resetPending = true;
    double l1, l2;
    armLengths(gl.brazo, l1, l2);
    sim += f.delta * f.speed;
    int64_t target = int64_t(std::floor(sim / kStep + 1e-6));
    if (target - steps > 60) steps = target - 60;
    while (steps < target) {
      for (int i = 0; i < count; i++) st[size_t(i)] = rk4(st[size_t(i)], kStep, l1, l2);
      steps++;
      sinceReset += kStep;
      // Estela de la punta: una muestra cada 4 pasos.
      if (steps % 4 == 0) {
        trailHead = (trailHead + 1) % kTrail;
        trailCount = std::min(trailCount + 1, kTrail);
        for (int i = 0; i < count; i++) {
          const State& s = st[size_t(i)];
          trailX[size_t(i * kTrail + trailHead)] = float(l1 * std::sin(s.a1) + l2 * std::sin(s.a2));
          trailY[size_t(i * kTrail + trailHead)] = float(l1 * std::cos(s.a1) + l2 * std::cos(s.a2));
        }
      }
      if (resetPending || sinceReset > double(m.ciclo)) restart(double(m.ciclo));
    }
  }

  void render(const Frame& f, Canvas& c) const override {
    auto m = modifiers(f);
    auto gl = glide(f);
    float amp = f.intensity;
    // Pulso: cada opción mueve algo distinto; sin música todo vale cero.
    const float kickP = std::min(kick * amp, 1.0f) * gl.pulso.weight(0);
    const float bassP = std::min(bass * amp, 1.0f) * gl.pulso.weight(1);
    const float sparkP = std::min(spark * amp, 1.0f) * gl.pulso.weight(2);
    const Color& bg = f.colors[0];
    c.rect({0, 0, f.width, f.height}, Paint::radial({f.width * 0.5f, f.height * 0.42f}, std::max(f.width, f.height) * 0.7f,
                                                   {Color{std::min(1.0f, bg.r + 0.05f), std::min(1.0f, bg.g + 0.03f), std::min(1.0f, bg.b + 0.07f), 1.0f},
                                                    Color{bg.r, bg.g, bg.b, 1.0f}}));
    if (count <= 0) return;
    float side = std::min(f.width, f.height);
    float px = side / 400.0f;
    // Graves: los brazos se alargan con los graves; Golpes: crecen de golpe.
    float L = side * 0.3f * (1.0f + 0.14f * bassP + 0.15f * kickP);
    double l1, l2;
    armLengths(glide(f).brazo, l1, l2);
    const float L1 = L * float(l1), L2 = L * float(l2);
    Vec2 pivot{f.width * 0.5f, f.height * 0.42f};
    const int groups = 12;
    // Colores del grupo: arcoíris entre los tres colores de la paleta.
    auto groupColor = [&](int g) {
      float t = float(g) / float(groups - 1);
      const Color& a = f.colors[1];
      const Color& b = f.colors[2];
      const Color& d = f.colors[3];
      if (t < 0.5f) {
        float u = t * 2.0f;
        return Color{a.r + (b.r - a.r) * u, a.g + (b.g - a.g) * u, a.b + (b.b - a.b) * u, 1.0f};
      }
      float u = (t - 0.5f) * 2.0f;
      return Color{b.r + (d.r - b.r) * u, b.g + (d.g - b.g) * u, b.b + (d.b - b.b) * u, 1.0f};
    };
    std::array<Path, groups> arms, trails;
    std::array<std::vector<Vec2>, groups> tips;
    for (auto& t : tips) t.reserve(size_t(count / groups + 2));
    // Agudos: puntas sueltas que destellan, 14 veces por segundo.
    std::vector<Vec2> glints;
    if (sparkP > 0.002f) glints.reserve(size_t(count));
    const uint32_t tick = uint32_t(std::fmod(shimmer, 100000.0) * 14.0);
    for (int i = 0; i < count; i++) {
      int g = std::min(groups - 1, i * groups / count);
      const State& s = st[size_t(i)];
      float x1 = pivot.x + L1 * float(std::sin(s.a1)), y1 = pivot.y + L1 * float(std::cos(s.a1));
      float x2 = x1 + L2 * float(std::sin(s.a2)), y2 = y1 + L2 * float(std::cos(s.a2));
      arms[size_t(g)].moveTo(pivot.x, pivot.y).lineTo(x1, y1).lineTo(x2, y2);
      tips[size_t(g)].push_back({x2, y2});
      if (sparkP > 0.002f && hashU(uint32_t(i) * 2654435761u + tick * 40503u) < 0.35f * sparkP) glints.push_back({x2, y2});
      if (m.estelas && trailHead >= 0) {
        for (int k = 0; k < trailCount; k++) {
          int idx = ((trailHead - k) % kTrail + kTrail) % kTrail;
          float tx = pivot.x + L * trailX[size_t(i * kTrail + idx)];
          float ty = pivot.y + L * trailY[size_t(i * kTrail + idx)];
          if (k == 0) trails[size_t(g)].moveTo(x2, y2);
          trails[size_t(g)].lineTo(tx, ty);
        }
      }
    }
    float alpha = std::clamp(4.2f / std::sqrt(float(count)) * amp, 0.05f, 1.0f);
    // Golpes: el empujón gira el conjunto alrededor del eje y se balancea
    // hasta calmarse.
    const float push = std::clamp(swingPow * amp, -1.0f, 1.0f) * gl.pulso.weight(0);
    const float theta = swingAge < 3.0 ? 0.45f * push * std::exp(-float(swingAge) * 3.2f) * std::sin(float(swingAge) * 12.0f) : 0.0f;
    const bool swing = std::fabs(theta) > 1e-4f;
    // Resplandor local del abanico: Golpes lo enciende y Graves lo hace latir.
    const float aura = std::clamp((0.3f * kickP + 0.2f * bassP) * f.glow, 0.0f, 0.6f);
    if (aura > 0.002f) {
      const float auraR = L * 2.1f;
      Paint ap = Paint::radial(pivot, auraR, {f.colors[2].opacity(aura), f.colors[1].opacity(aura * 0.4f), f.colors[1].opacity(0.0f)},
                               {0.0f, 0.5f, 1.0f});
      ap.blend = Blend::plus;
      c.circle(pivot, auraR, ap);
    }
    if (swing) {
      c.save();
      c.translate(pivot.x, pivot.y);
      c.rotate(theta);
      c.translate(-pivot.x, -pivot.y);
    }
    const float clock = float(std::fmod(shimmer, 1000.0));
    for (int g = 0; g < groups; g++) {
      Color col = groupColor(g);
      // Agudos: cada grupo centellea a su ritmo.
      const float tw = 0.5f + 0.5f * std::sin(clock * 19.0f + float(g) * 2.3f);
      if (m.estelas) {
        Paint tp;
        tp.blend = Blend::plus;
        tp.strokeWidth = 1.6f * px;
        tp.strokeJoin = 1;
        tp.color = col.opacity(std::clamp(alpha * 0.7f * f.glow * (1.0f + 1.6f * kickP + 0.8f * bassP + 1.6f * sparkP * tw), 0.0f, 1.0f));
        c.path(trails[size_t(g)], tp);
      }
      Paint arm;
      arm.blend = Blend::plus;
      arm.strokeWidth = (1.7f + 1.4f * bass + 2.2f * bassP) * px * (1.0f + 1.0f * kickP);
      arm.strokeJoin = 1;
      arm.strokeCap = 1;
      arm.color = col.opacity(std::clamp(alpha * (0.8f + 0.4f * energy) * (1.0f + 0.8f * bassP + 0.9f * kickP), 0.0f, 1.0f));
      c.path(arms[size_t(g)], arm);
      Paint tip;
      tip.blend = Blend::plus;
      tip.color = col.opacity(std::clamp((0.35f + 0.5f * kick) * amp + 0.7f * kickP + 0.8f * sparkP * tw, 0.0f, 1.0f));
      c.points(tips[size_t(g)], (2.6f + 2.5f * kick) * px * (1.0f + 1.0f * kickP + 0.5f * bassP + 1.8f * sparkP * tw), tip);
    }
    if (!glints.empty()) {
      const Color& c3 = f.colors[3];
      Paint gp;
      gp.blend = Blend::plus;
      gp.color = Color{std::min(1.0f, c3.r * 0.5f + 0.5f), std::min(1.0f, c3.g * 0.5f + 0.5f), std::min(1.0f, c3.b * 0.5f + 0.5f),
                       std::clamp(0.9f * sparkP, 0.0f, 0.95f)};
      c.points(glints, 3.6f * px, gp);
    }
    if (swing) c.restore();
    Paint hub;
    hub.color = Color{1.0f, 0.97f, 0.9f, 1.0f};
    c.circle(pivot, 3.5f * px, hub);
    if (flash > 0.01f) {
      Paint fl;
      fl.blend = Blend::plus;
      fl.color = f.colors[2].opacity(std::clamp(flash * 0.05f * amp, 0.0f, 1.0f));
      c.rect({0, 0, f.width, f.height}, fl);
    }
  }
};

class Visual final : public Scene {
  static constexpr int kMax = 400;
  static constexpr int kTrail = 10;
  static constexpr double kStep = 1.0 / 120.0;
  struct State { double a1, a2, w1, w2; };
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  // Relojes en doble precisión: la escena sin música es idéntica a 30 y 60 FPS.
  double sim = 0, sinceReset = 0;
  int64_t steps = 0;
  int count = 0;
  bool resetPending = false;
  Random rng{1};
  std::vector<State> st;
  std::vector<float> trailX, trailY;
  int trailHead = 0, trailCount = 0;
  // Empujón del último golpe (con su lado) y reloj del centelleo.
  double swingAge = 100, shimmer = 0;
  float swingPow = 0;
  int swingSide = 0;

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }
  static float hashU(uint32_t x) {
    x ^= x >> 16; x *= 0x7feb352dU; x ^= x >> 15; x *= 0x846ca68bU; x ^= x >> 16;
    return float(x & 0xffffffu) / 16777216.0f;
  }

  // Ecuaciones del péndulo doble con masas iguales y brazos l1 y l2
  // (l1 + l2 = 2: el alcance total no cambia).
  static void deriv(const State& s, double l1, double l2, double& d1, double& d2) {
    const double g = 9.81;
    double delta = s.a1 - s.a2;
    double den = 3.0 - std::cos(2.0 * delta);
    d1 = (-3.0 * g * std::sin(s.a1) - g * std::sin(s.a1 - 2.0 * s.a2) -
          2.0 * std::sin(delta) * (s.w2 * s.w2 * l2 + s.w1 * s.w1 * l1 * std::cos(delta))) / (l1 * den);
    d2 = (2.0 * std::sin(delta) * (2.0 * s.w1 * s.w1 * l1 + 2.0 * g * std::cos(s.a1) + s.w2 * s.w2 * l2 * std::cos(delta))) / (l2 * den);
  }

  static State rk4(const State& s, double h, double l1, double l2) {
    double k1a, k1b, k2a, k2b, k3a, k3b, k4a, k4b;
    deriv(s, l1, l2, k1a, k1b);
    State s2{s.a1 + 0.5 * h * s.w1, s.a2 + 0.5 * h * s.w2, s.w1 + 0.5 * h * k1a, s.w2 + 0.5 * h * k1b};
    deriv(s2, l1, l2, k2a, k2b);
    State s3{s.a1 + 0.5 * h * s2.w1, s.a2 + 0.5 * h * s2.w2, s.w1 + 0.5 * h * k2a, s.w2 + 0.5 * h * k2b};
    deriv(s3, l1, l2, k3a, k3b);
    State s4{s.a1 + h * s3.w1, s.a2 + h * s3.w2, s.w1 + h * k3a, s.w2 + h * k3b};
    deriv(s4, l1, l2, k4a, k4b);
    return {s.a1 + h / 6.0 * (s.w1 + 2.0 * s2.w1 + 2.0 * s3.w1 + s4.w1),
            s.a2 + h / 6.0 * (s.w2 + 2.0 * s2.w2 + 2.0 * s3.w2 + s4.w2),
            s.w1 + h / 6.0 * (k1a + 2.0 * k2a + 2.0 * k3a + k4a),
            s.w2 + h / 6.0 * (k1b + 2.0 * k2b + 2.0 * k3b + k4b)};
  }

  // Brazos de un péndulo con el brazo de abajo [ratio] veces el de arriba.
  static void armLengths(float ratio, double& l1, double& l2) {
    const double r = std::clamp(double(ratio), 0.45, 2.2);
    l1 = 2.0 / (1.0 + r);
    l2 = 2.0 - l1;
  }

  void restart(double cycle) {
    double a = 3.14159265358979 * (0.62 + 0.3 * double(rng.unit()));
    double b = a + (double(rng.unit()) - 0.5) * 1.2;
    if (rng.unit() < 0.5f) {
      a = -a;
      b = -b;
    }
    // El caos multiplica por 10 la diferencia inicial cada ~1,4 s: un ciclo
    // corto parte de diferencias mayores y se abre antes. El abanico se abre
    // hacia el 30% del ciclo (20 s: 1,5e-6 rad, como siempre).
    const double spread = 1.5e-6 * std::exp(0.6 * (20.0 - std::clamp(cycle, 10.0, 40.0)));
    for (int i = 0; i < count; i++) {
      double e = spread * double(i);
      st[size_t(i)] = {a + e, b, 0.0, 0.0};
    }
    sinceReset = 0;
    resetPending = false;
    std::fill(trailX.begin(), trailX.end(), 0.0f);
    std::fill(trailY.begin(), trailY.end(), 0.0f);
    trailHead = -1;
    trailCount = 0;
  }

 public:
  void reset(uint32_t seed) override {
    rng = Random(seed);
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    sim = 0;
    steps = 0;
    count = 0;
    st.assign(kMax, State{0, 0, 0, 0});
    trailX.assign(size_t(kMax * kTrail), 0.0f);
    trailY.assign(size_t(kMax * kTrail), 0.0f);
    trailHead = -1;
    trailCount = 0;
    sinceReset = 0;
    resetPending = false;
    swingAge = 100;
    shimmer = 0;
    swingPow = 0;
    swingSide = 0;
  }

  void update(const Frame& f) override {
    auto m = modifiers(f);
    auto gl = glide(f);
    float dt = float(f.delta);
    const Music& mu = f.music;
    bass = follow(bass, mu.bass, 22.0f, 4.5f, dt);
    body = follow(body, mu.body, 12.0f, 3.0f, dt);
    spark = follow(spark, mu.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, mu.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, mu.active ? std::pow(std::clamp(mu.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : mu.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : mu.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : mu.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((mu.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, mu.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    bool beat = hit > kick + 0.2f;
    // Golpes: cada golpe empuja el conjunto, alternando el lado.
    swingAge += f.delta;
    shimmer += f.delta;
    if (beat) {
      swingAge = 0.0;
      swingPow = hit * ((swingSide++ % 2) == 0 ? 1.0f : -1.0f);
    }
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));

    int want = std::clamp(m.pendulos, 10, kMax);
    if (want != count) {
      count = want;
      restart(double(m.ciclo));
    }
    // Con música, un golpe fuerte reúne a los péndulos cuando ya hay caos.
    if (beat && hit > 0.6f && sinceReset > double(m.ciclo) * 0.6) resetPending = true;
    double l1, l2;
    armLengths(gl.brazo, l1, l2);
    sim += f.delta * f.speed;
    int64_t target = int64_t(std::floor(sim / kStep + 1e-6));
    if (target - steps > 60) steps = target - 60;
    while (steps < target) {
      for (int i = 0; i < count; i++) st[size_t(i)] = rk4(st[size_t(i)], kStep, l1, l2);
      steps++;
      sinceReset += kStep;
      // Estela de la punta: una muestra cada 4 pasos.
      if (steps % 4 == 0) {
        trailHead = (trailHead + 1) % kTrail;
        trailCount = std::min(trailCount + 1, kTrail);
        for (int i = 0; i < count; i++) {
          const State& s = st[size_t(i)];
          trailX[size_t(i * kTrail + trailHead)] = float(l1 * std::sin(s.a1) + l2 * std::sin(s.a2));
          trailY[size_t(i * kTrail + trailHead)] = float(l1 * std::cos(s.a1) + l2 * std::cos(s.a2));
        }
      }
      if (resetPending || sinceReset > double(m.ciclo)) restart(double(m.ciclo));
    }
  }

  void render(const Frame& f, Canvas& c) const override {
    auto m = modifiers(f);
    auto gl = glide(f);
    float amp = f.intensity;
    // Pulso: cada opción mueve algo distinto; sin música todo vale cero.
    const float kickP = std::min(kick * amp, 1.0f) * gl.pulso.weight(0);
    const float bassP = std::min(bass * amp, 1.0f) * gl.pulso.weight(1);
    const float sparkP = std::min(spark * amp, 1.0f) * gl.pulso.weight(2);
    if (count <= 0) return;
    float side = std::min(f.width, f.height);
    float px = side / 400.0f;
    // Graves: los brazos se alargan con los graves; Golpes: crecen de golpe.
    float L = side * 0.3f * (1.0f + 0.14f * bassP + 0.15f * kickP);
    double l1, l2;
    armLengths(glide(f).brazo, l1, l2);
    const float L1 = L * float(l1), L2 = L * float(l2);
    Vec2 pivot{f.width * 0.5f, f.height * 0.42f};
    const int groups = 12;
    // Colores del grupo: arcoíris entre los tres colores de la paleta.
    auto groupColor = [&](int g) {
      float t = float(g) / float(groups - 1);
      const Color& a = f.colors[1];
      const Color& b = f.colors[2];
      const Color& d = f.colors[3];
      if (t < 0.5f) {
        float u = t * 2.0f;
        return Color{a.r + (b.r - a.r) * u, a.g + (b.g - a.g) * u, a.b + (b.b - a.b) * u, 1.0f};
      }
      float u = (t - 0.5f) * 2.0f;
      return Color{b.r + (d.r - b.r) * u, b.g + (d.g - b.g) * u, b.b + (d.b - b.b) * u, 1.0f};
    };
    std::array<Path, groups> arms, trails;
    std::array<std::vector<Vec2>, groups> tips;
    for (auto& t : tips) t.reserve(size_t(count / groups + 2));
    // Agudos: puntas sueltas que destellan, 14 veces por segundo.
    std::vector<Vec2> glints;
    if (sparkP > 0.002f) glints.reserve(size_t(count));
    const uint32_t tick = uint32_t(std::fmod(shimmer, 100000.0) * 14.0);
    for (int i = 0; i < count; i++) {
      int g = std::min(groups - 1, i * groups / count);
      const State& s = st[size_t(i)];
      float x1 = pivot.x + L1 * float(std::sin(s.a1)), y1 = pivot.y + L1 * float(std::cos(s.a1));
      float x2 = x1 + L2 * float(std::sin(s.a2)), y2 = y1 + L2 * float(std::cos(s.a2));
      arms[size_t(g)].moveTo(pivot.x, pivot.y).lineTo(x1, y1).lineTo(x2, y2);
      tips[size_t(g)].push_back({x2, y2});
      if (sparkP > 0.002f && hashU(uint32_t(i) * 2654435761u + tick * 40503u) < 0.35f * sparkP) glints.push_back({x2, y2});
      if (m.estelas && trailHead >= 0) {
        for (int k = 0; k < trailCount; k++) {
          int idx = ((trailHead - k) % kTrail + kTrail) % kTrail;
          float tx = pivot.x + L * trailX[size_t(i * kTrail + idx)];
          float ty = pivot.y + L * trailY[size_t(i * kTrail + idx)];
          if (k == 0) trails[size_t(g)].moveTo(x2, y2);
          trails[size_t(g)].lineTo(tx, ty);
        }
      }
    }
    float alpha = std::clamp(4.2f / std::sqrt(float(count)) * amp, 0.05f, 1.0f);
    // Golpes: el empujón gira el conjunto alrededor del eje y se balancea
    // hasta calmarse.
    const float push = std::clamp(swingPow * amp, -1.0f, 1.0f) * gl.pulso.weight(0);
    const float theta = swingAge < 3.0 ? 0.45f * push * std::exp(-float(swingAge) * 3.2f) * std::sin(float(swingAge) * 12.0f) : 0.0f;
    const bool swing = std::fabs(theta) > 1e-4f;
    // Resplandor local del abanico: Golpes lo enciende y Graves lo hace latir.
    const float aura = std::clamp((0.3f * kickP + 0.2f * bassP) * f.glow, 0.0f, 0.6f);
    if (aura > 0.002f) {
      const float auraR = L * 2.1f;
      Paint ap = Paint::radial(pivot, auraR, {f.colors[2].opacity(aura), f.colors[1].opacity(aura * 0.4f), f.colors[1].opacity(0.0f)},
                               {0.0f, 0.5f, 1.0f});
      ap.blend = Blend::plus;
      c.circle(pivot, auraR, ap);
    }
    if (swing) {
      c.save();
      c.translate(pivot.x, pivot.y);
      c.rotate(theta);
      c.translate(-pivot.x, -pivot.y);
    }
    const float clock = float(std::fmod(shimmer, 1000.0));
    for (int g = 0; g < groups; g++) {
      Color col = groupColor(g);
      // Agudos: cada grupo centellea a su ritmo.
      const float tw = 0.5f + 0.5f * std::sin(clock * 19.0f + float(g) * 2.3f);
      if (m.estelas) {
        Paint tp;
        tp.blend = Blend::plus;
        tp.strokeWidth = 1.6f * px;
        tp.strokeJoin = 1;
        tp.color = col.opacity(std::clamp(alpha * 0.7f * f.glow * (1.0f + 1.6f * kickP + 0.8f * bassP + 1.6f * sparkP * tw), 0.0f, 1.0f));
        c.path(trails[size_t(g)], tp);
      }
      Paint arm;
      arm.blend = Blend::plus;
      arm.strokeWidth = (1.7f + 1.4f * bass + 2.2f * bassP) * px * (1.0f + 1.0f * kickP);
      arm.strokeJoin = 1;
      arm.strokeCap = 1;
      arm.color = col.opacity(std::clamp(alpha * (0.8f + 0.4f * energy) * (1.0f + 0.8f * bassP + 0.9f * kickP), 0.0f, 1.0f));
      c.path(arms[size_t(g)], arm);
      Paint tip;
      tip.blend = Blend::plus;
      tip.color = col.opacity(std::clamp((0.35f + 0.5f * kick) * amp + 0.7f * kickP + 0.8f * sparkP * tw, 0.0f, 1.0f));
      c.points(tips[size_t(g)], (2.6f + 2.5f * kick) * px * (1.0f + 1.0f * kickP + 0.5f * bassP + 1.8f * sparkP * tw), tip);
    }
    if (!glints.empty()) {
      const Color& c3 = f.colors[3];
      Paint gp;
      gp.blend = Blend::plus;
      gp.color = Color{std::min(1.0f, c3.r * 0.5f + 0.5f), std::min(1.0f, c3.g * 0.5f + 0.5f), std::min(1.0f, c3.b * 0.5f + 0.5f),
                       std::clamp(0.9f * sparkP, 0.0f, 0.95f)};
      c.points(glints, 3.6f * px, gp);
    }
    if (swing) c.restore();
    Paint hub;
    hub.color = Color{1.0f, 0.97f, 0.9f, 1.0f};
    c.circle(pivot, 3.5f * px, hub);
  }
};

class Visual final : public Scene {
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  // Relojes en doble precisión: la escena sin música es idéntica a 30 y 60 FPS.
  double clock = 0, drip = 0;
  int tears = 0;

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    clock = rng.unit() * 50.0;
    drip = rng.unit() * 100.0;
    tears = 0;
  }

  void update(const Frame& f) override {
    float dt = float(f.delta);
    const Music& mu = f.music;
    bass = follow(bass, mu.bass, 22.0f, 4.5f, dt);
    body = follow(body, mu.body, 12.0f, 3.0f, dt);
    spark = follow(spark, mu.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, mu.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, mu.active ? std::pow(std::clamp(mu.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : mu.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : mu.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : mu.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((mu.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, mu.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    if (hit > kick + 0.2f) tears++;
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    clock += f.delta * f.speed * (0.4 + 0.8 * drive);
    drip += f.delta * f.speed * (1.0 + 2.5 * drive + 2.0 * kick);
  }

  void render(const Frame& f, Canvas& c) const override {
    auto m = modifiers(f);
    float amp = f.intensity;
    std::vector<float> u;
    u.reserve(28);
    u.insert(u.end(), {float(std::fmod(clock, 1000.0)), float(std::fmod(drip, 4000.0)), bass * amp, kick * amp});
    u.insert(u.end(), {float(m.direccion), std::clamp(m.cantidad + 0.3f * drive + 0.25f * kick, 0.0f, 1.0f), m.ancho, m.rasgado ? 1.0f : 0.0f});
    u.insert(u.end(), {float(tears % 97), energy, f.glow, flash * amp});
    for (int i = 0; i < 4; i++) u.insert(u.end(), {f.colors[i].r, f.colors[i].g, f.colors[i].b});
    c.material("pixel_sort", {0, 0, f.width, f.height}, u);
  }
};

shaderSources.pixel_sort:
#version 460 core
#include <flutter/runtime_effect.glsl>
uniform vec2 uSize;
uniform vec4 uA;   // reloj, goteo, graves, golpe
uniform vec4 uB;   // dirección, cantidad, ancho de columna, rasgado
uniform vec4 uD;   // rasgados, energía, glow, destello
uniform vec3 uC0;
uniform vec3 uC1;
uniform vec3 uC2;
uniform vec3 uC3;
out vec4 fragColor;

float hash11(float n) {
  n = fract(n * 0.1031);
  n *= n + 33.33;
  n *= n + n;
  return fract(n);
}

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

// Rampa de atardecer: violeta → rosa-rojo → naranja → amarillo.
vec3 ramp(float v) {
  v = clamp(v, 0.0, 1.0);
  vec3 c = mix(uC0 * 1.6, uC1, smoothstep(0.0, 0.4, v));
  c = mix(c, uC2, smoothstep(0.35, 0.7, v));
  return mix(c, uC3, smoothstep(0.68, 1.0, v));
}

// La imagen de debajo: brillo de un atardecer con manchas que se mueven.
float source(vec2 p, float t) {
  // Cielo oscuro arriba, horizonte encendido y un sol que se mueve.
  float horizon = 0.18 + 0.06 * sin(p.x * 2.0 + t * 0.4);
  float v = 0.12 + 0.62 * exp(-(p.y - horizon) * (p.y - horizon) * 4.5);
  v += 0.12 * sin(p.x * 4.1 + t * 0.7) * sin(p.y * 3.3 - t * 0.5);
  vec2 sun = vec2(0.28 * sin(t * 0.21), horizon - 0.12 + 0.05 * cos(t * 0.17));
  v += 0.55 * exp(-dot(p - sun, p - sun) * 26.0);
  vec2 s2 = vec2(-0.3 * cos(t * 0.27), -0.45 + 0.2 * sin(t * 0.19));
  v += 0.3 * exp(-dot(p - s2, p - s2) * 14.0);
  return v;
}

void main() {
  vec2 frag = FlutterFragCoord().xy;
  float scale = min(uSize.x, uSize.y);
  // En horizontal se intercambian los ejes: las columnas pasan a ser filas.
  bool horizontal = uB.x > 0.5;
  vec2 g = horizontal ? frag.yx : frag;
  vec2 size = horizontal ? uSize.yx : uSize;
  // Rasgado: franjas que saltan a un lado con cada golpe.
  float band = floor(g.y / (size.y / 26.0));
  float tearH = hash11(band * 7.3 + uD.x * 13.1);
  float tear = uB.w * step(0.72, tearH) * (tearH - 0.72) * 3.5 * uA.w * 90.0;
  g.x += tear;
  float w = max(uB.z, 1.0);
  float col = floor(g.x / w);
  float hc = hash11(col * 0.137 + 3.0);
  // Tramos de cada columna: largo propio y goteo propio.
  float len = mix(60.0, 340.0, hc) * (0.7 + 0.8 * uB.y);
  float slide = uA.y * (12.0 + 30.0 * hash11(col * 1.37 + 9.0));
  float k = floor((g.y + hc * len + slide) / len);
  float t = fract((g.y + hc * len + slide) / len);
  float y0 = k * len - hc * len - slide;
  float y1 = y0 + len;
  float tm = uA.x;
  vec2 toP = vec2(1.0, 1.0) / scale;
  vec2 here = horizontal ? (vec2(g.y, g.x) - 0.5 * uSize) * toP : (g - 0.5 * uSize) * toP;
  float v = source(here, tm);
  vec3 outCol = ramp(v);
  // ¿Se ordena este tramo? Más probable donde la imagen brilla.
  vec2 a = horizontal ? (vec2(y0, g.x) - 0.5 * uSize) * toP : (vec2(g.x, y0) - 0.5 * uSize) * toP;
  vec2 b = horizontal ? (vec2(y1, g.x) - 0.5 * uSize) * toP : (vec2(g.x, y1) - 0.5 * uSize) * toP;
  float va = source(a, tm);
  float vb = source(b, tm);
  float chosen = step(hash12(vec2(col, k)), uB.y) * step(0.5 - 0.25 * uB.y, max(va, vb));
  if (chosen > 0.5) {
    float lo = min(va, vb);
    float hi = max(va, vb) + 0.08;
    float s = lo + (hi - lo) * t * t * (3.0 - 2.0 * t);
    outCol = ramp(s);
    // Borde final cortado en seco con un brillo.
    outCol += uC3 * smoothstep(0.96, 1.0, t) * 0.35;
  }
  // Separación de colores en las franjas rasgadas.
  if (abs(tear) > 1.0) outCol = vec3(outCol.r * 1.15, outCol.g * 0.85, outCol.b * 1.2);
  outCol *= (0.9 + 0.3 * uA.z) * mix(1.0, uD.z, 0.4);
  outCol += uC3 * uD.w * 0.05;
  vec2 p0 = (frag - 0.5 * uSize) / scale;
  outCol *= 1.0 - 0.25 * smoothstep(0.7, 1.5, length(p0 * vec2(0.9, 0.65)));
  float peak = max(outCol.r, max(outCol.g, outCol.b));
  if (peak > 0.85) {
    float e = (peak - 0.85) / 0.15;
    outCol *= (0.85 + 0.15 * e / (1.0 + e)) / peak;
  }
  outCol += (hash12(frag) - 0.5) / 255.0;
  fragColor = vec4(clamp(outCol, 0.0, 1.0), 1.0);
}

