class Visual final : public Scene {
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  float phase = 0, press = 0, pressVel = 0, hue = 0, wobble = 0;

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    phase = rng.unit() * 50.0f;
    press = pressVel = 0;
    hue = rng.unit();
    wobble = 0;
  }

  void update(const Frame& f) override {
    float dt = float(f.delta);
    const Music& m = f.music;
    bass = follow(bass, m.bass, 20.0f, 4.0f, dt);
    body = follow(body, m.body, 10.0f, 2.5f, dt);
    spark = follow(spark, m.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, m.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, m.active ? std::pow(std::clamp(m.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : m.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : m.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : m.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((m.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, m.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    if (hit > kick + 0.2f) pressVel += 2.6f * hit;
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 7.0f), std::min(fl, 1.0f));

    // Muelle amortiguado: el cristal se presiona y rebota como en el proyector.
    pressVel += (-press * 38.0f - pressVel * 7.0f) * dt;
    press += pressVel * dt;

    phase += dt * f.speed * (0.16f + 0.75f * drive + 0.5f * kick);
    hue += dt * (0.01f + 0.12f * body);
    wobble += dt * f.speed * (0.3f + 2.2f * bass);
  }

  void render(const Frame& f, Canvas& c) const override {
    float amp = f.intensity;
    std::vector<float> u;
    u.reserve(28);
    u.insert(u.end(), {phase, press * amp, bass * amp, kick * amp});
    u.insert(u.end(), {hue, wobble, spark * amp, flash});
    u.insert(u.end(), {energy, f.glow, f.detail, 0.0f});
    for (int i = 0; i < 4; i++) u.insert(u.end(), {f.colors[i].r, f.colors[i].g, f.colors[i].b});
    c.material("liquid", {0, 0, f.width, f.height}, u);
  }
};

shaderSources.liquid:
#version 460 core
#include <flutter/runtime_effect.glsl>
uniform vec2 uSize;
uniform vec4 uA;   // tiempo, presión, graves, golpe
uniform vec4 uB;   // tono, ondulación, agudos, destello
uniform vec4 uX;   // energía, glow, detalle
uniform vec3 uC0;
uniform vec3 uC1;
uniform vec3 uC2;
uniform vec3 uC3;
out vec4 fragColor;

// Campana gaussiana segura: pow() con base negativa no está definido en GLSL.
float gauss(float x) {
  return exp(-x * x);
}

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash12(i), hash12(i + vec2(1.0, 0.0)), u.x),
             mix(hash12(i + vec2(0.0, 1.0)), hash12(i + vec2(1.0, 1.0)), u.x), u.y);
}

float fbm(vec2 p, int octaves) {
  float s = 0.0;
  float a = 0.5;
  float norm = 0.0;
  for (int i = 0; i < 4; i++) {
    if (i >= octaves) break;
    s += a * noise(p);
    norm += a;
    p = mat2(1.6, 1.2, -1.2, 1.6) * p;
    a *= 0.5;
  }
  return s / norm;
}

// Gira un color en la rueda de tono preservando su luminancia.
vec3 hueShift(vec3 c, float a) {
  const vec3 k = vec3(0.57735);
  float ca = cos(a);
  return c * ca + cross(k, c) * sin(a) + k * dot(k, c) * (1.0 - ca);
}

// Campo de un tinte: comparte la deformación global y añade la suya propia.
float dyeField(vec2 p, vec2 warp, float t, float seed) {
  vec2 q = p + warp * (1.0 + 0.25 * seed) +
           0.06 * vec2(sin(uB.y + seed), cos(uB.y * 0.8 + seed));
  return fbm(q * 1.7 + vec2(seed * 3.1, -t * 0.04), 3);
}

void main() {
  vec2 frag = FlutterFragCoord().xy;
  float scale = min(uSize.x, uSize.y);
  vec2 uv = (frag - 0.5 * uSize) / scale;
  uv.y = -uv.y;
  float t = uA.x;
  float r = length(uv);

  // El golpe presiona el cristal: el centro se expande y la luz sube.
  vec2 p = uv / (1.0 + 0.22 * uA.y);
  float lamp = (0.95 - 0.45 * smoothstep(0.0, 1.1, r)) * (1.0 + 0.45 * uA.y + 0.5 * uB.w);

  vec3 light = mix(vec3(1.0, 0.95, 0.86), uC3, 0.2) * lamp;
  vec3 trans = vec3(1.0);
  float lines = 0.0;
  float highlight = 0.0;
  float shift = sin(uB.x * 6.2831853) * 0.35;
  // Deformación compartida por los tres tintes (más barata que una por capa).
  vec2 warp = vec2(fbm(p * 0.8 + vec2(0.0, t * 0.06), 3), fbm(p * 0.8 + vec2(5.2, -t * 0.05), 3));
  warp = (warp - 0.5) * (0.9 + 0.9 * uA.z);
  for (int i = 0; i < 3; i++) {
    float fi = float(i);
    vec2 d = vec2(dyeField(p * (0.62 + fi * 0.16), warp, t * (1.0 + fi * 0.3), fi * 1.7 + 0.4), 0.0);
    float thresh = 0.47 - 0.05 * uA.z - 0.04 * uA.w;
    float edgeSoft = 0.02;
    float dye = smoothstep(thresh - edgeSoft, thresh + edgeSoft, d.x);
    // Tinte translúcido: más denso hacia el interior de cada mancha.
    float depth = smoothstep(thresh, thresh + 0.18, d.x);
    vec3 tint = i == 0 ? uC1 : (i == 1 ? uC2 : uC3);
    tint = clamp(hueShift(tint, shift + fi * 0.1), 0.0, 1.0);
    vec3 absorb = pow(tint, vec3(1.0 + 0.9 * depth));
    trans *= mix(vec3(1.0), absorb, dye * (0.72 + 0.2 * depth));
    float edge = gauss((d.x - thresh) / 0.008);
    lines = max(lines, edge);
    highlight += gauss((d.x - thresh - 0.025) / 0.012) * 0.5;
  }
  vec3 col = light * trans;
  col *= 1.0 - 0.6 * lines;
  col += light * trans * highlight * 0.6;

  // Pocas burbujas grandes atrapadas entre los cristales.
  vec2 g = (p + vec2(sin(t * 0.2) * 0.2, t * 0.03)) * 4.0;
  vec2 id = floor(g);
  vec2 f = fract(g) - 0.5;
  float h = hash12(id);
  if (h > 0.9) {
    vec2 o = (vec2(hash12(id + 1.3), hash12(id + 7.1)) - 0.5) * 0.3;
    float rad = 0.10 + 0.12 * hash12(id + 3.3);
    float d = length(f - o);
    float rim = gauss((d - rad) / 0.012);
    float inner = smoothstep(rad, rad * 0.6, d);
    col = mix(col, col * 1.15 + light * 0.06, inner);
    col *= 1.0 - 0.45 * rim;
    col += light * smoothstep(0.03, 0.0, length(f - o - vec2(-0.35, 0.35) * rad)) * (0.35 + 0.8 * uB.z);
  }

  // Grano de la pantalla y bordes del haz del proyector.
  col *= 0.94 + 0.06 * noise(frag * 0.7);
  float cone = smoothstep(1.35, 0.55, length(uv * vec2(0.9, 0.62)));
  col = mix(uC0, col * uX.y, cone);
  col += vec3(1.0) * uB.w * 0.15;
  col = clamp((col * (2.51 * col + 0.03)) / (col * (2.43 * col + 0.59) + 0.14), 0.0, 1.0);
  col = pow(col, vec3(0.4545));
  col += (hash12(frag) - 0.5) / 255.0;
  fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

visuals.nativeSource:
class Visual final : public Scene {
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  // Relojes en doble precisión: la escena sin música es idéntica a 30 y 60 FPS.
  double travel = 0, sinceSwitch = 0, sinceTurn = 0;
  float boost = 0, patternA = 0, patternB = 0, mix = 1, turn = 0, turnTarget = 0;
  int beats = 0;

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

  void nextPattern() {
    patternA = patternB;
    patternB += 1.0f;
    mix = 0;
    sinceSwitch = 0;
  }

 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    travel = rng.unit() * 50.0;
    sinceSwitch = sinceTurn = 0;
    boost = 0;
    patternA = patternB = float(int(rng.unit() * 20.0f));
    mix = 1;
    turn = turnTarget = 0;
    beats = 0;
  }

  void update(const Frame& f) override {
    auto m = modifiers(f);
    float dt = float(f.delta);
    const Music& mu = f.music;
    bass = follow(bass, mu.bass, 22.0f, 4.5f, dt);
    body = follow(body, mu.body, 12.0f, 3.0f, dt);
    spark = follow(spark, mu.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, mu.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, mu.active ? std::pow(std::clamp(mu.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : mu.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : mu.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : mu.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((mu.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, mu.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    if (hit > kick + 0.2f) {
      beats++;
      boost = std::max(boost, hit);
      if (beats % 4 == 0) nextPattern();
      if (beats % 16 == 0) {
        turnTarget = 1.0f - turnTarget;
        sinceTurn = 0;
      }
    }
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    boost *= std::exp(-dt * 3.0f);
    sinceSwitch += f.delta;
    sinceTurn += f.delta;
    if (!mu.active && sinceSwitch > 6.0) nextPattern();
    if (!mu.active && sinceTurn > 14.0) {
      turnTarget = 1.0f - turnTarget;
      sinceTurn = 0;
    }
    // Planos: Auto alterna; las otras opciones fijan suelo y techo o paredes.
    float goal = m.orientacion == 1 ? 0.0f : (m.orientacion == 2 ? 1.0f : turnTarget);
    turn += (goal - turn) * (1.0f - std::exp(-dt * 2.0f));
    mix = std::min(1.0f, mix + dt * 1.5f);
    travel += f.delta * f.speed * m.velocidad_luz * (0.8 + 1.8 * drive + 2.5 * boost);
  }

  void render(const Frame& f, Canvas& c) const override {
    auto m = modifiers(f);
    float amp = f.intensity;
    float e = mix * mix * (3.0f - 2.0f * mix);
    float t = turn * turn * (3.0f - 2.0f * turn);
    std::vector<float> u;
    u.reserve(24);
    u.insert(u.end(), {float(std::fmod(travel, 1000.0)), bass * amp, kick * amp, energy});
    u.insert(u.end(), {patternA, patternB, e, t * 1.5707963f});
    u.insert(u.end(), {f.glow, float(m.franjas), m.horizonte ? 1.0f : 0.0f, flash * amp});
    for (int i = 0; i < 4; i++) u.insert(u.end(), {f.colors[i].r, f.colors[i].g, f.colors[i].b});
    c.material("star_gate", {0, 0, f.width, f.height}, u);
  }
};

shaderSources.star_gate:
#version 460 core
#include <flutter/runtime_effect.glsl>
uniform vec2 uSize;
uniform vec4 uA;   // vuelo, graves, golpe, energía
uniform vec4 uB;   // patrón anterior, patrón nuevo, transición, giro de los planos
uniform vec4 uD;   // glow, franjas, horizonte, destello
uniform vec3 uC0;
uniform vec3 uC1;
uniform vec3 uC2;
uniform vec3 uC3;
out vec4 fragColor;

float hash11(float x) {
  x = fract(x * 0.1031);
  x *= x + 33.33;
  x *= x + x;
  return fract(x);
}

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

vec3 tone(float x) {
  float k = fract(x) * 3.0;
  vec3 a = k < 1.0 ? uC1 : (k < 2.0 ? uC2 : uC3);
  vec3 b = k < 1.0 ? uC2 : (k < 2.0 ? uC3 : uC1);
  return mix(a, b, smoothstep(0.0, 1.0, fract(k)));
}

// Patrón de un plano: bandas de color anchas y suaves, encima muchas rayas
// finas de luz cortadas en tramos que corren hacia la cámara, y rombos de
// luz que pasan de vez en cuando.
vec3 plane(float seed, float x, float depth, float side, float z) {
  float k = uD.y;
  float b1 = x * k * 0.6 + side * 3.1 + seed * 7.3;
  float id1 = floor(b1);
  float f1 = fract(b1);
  float h1 = hash11(id1 * 1.7 + seed * 13.0);
  float body = smoothstep(0.0, 0.2, f1) * smoothstep(1.0, 0.8, f1);
  float flow = 0.5 + 0.5 * sin(depth * (0.35 + 0.7 * h1) + h1 * 40.0);
  vec3 col = tone(h1 + depth * 0.01 + seed * 0.37) * body * (0.05 + 0.22 * flow);
  // Rayas finas: se apagan cerca del horizonte para no hacer muaré.
  float fine = exp(-z * 0.3);
  for (int L = 0; L < 2; L++) {
    float fl = float(L);
    float b2 = x * k * (2.6 + 1.9 * fl) + side * (1.7 + fl) + seed * 3.1 + fl * 0.5;
    float id2 = floor(b2);
    float f2 = fract(b2);
    float h2 = hash11(id2 * 3.3 + seed * 7.0 + fl * 17.0);
    float line = exp(-abs(f2 - 0.5) * (10.0 + 14.0 * h2));
    float seg = smoothstep(0.2, 0.85, 0.5 + 0.5 * sin(depth * (0.8 + 1.6 * h2) + h2 * 60.0));
    col += mix(tone(h2 + 0.33 + seed * 0.21), vec3(1.0), 0.15) * line * seg * step(0.25, h2) * (1.5 - 0.4 * fl) * fine;
  }
  // Rombos de luz pequeños.
  vec2 cell = vec2(id1, floor(depth * 0.3));
  vec2 lc = vec2(f1, fract(depth * 0.3)) - 0.5;
  float gem = step(0.88, hash12(cell + seed)) * exp(-(abs(lc.x) * 6.0 + abs(lc.y) * 9.0)) * fine;
  col += mix(tone(h1 + 0.66), vec3(1.0), 0.5) * gem * 1.4;
  return col;
}

void main() {
  vec2 frag = FlutterFragCoord().xy;
  float scale = min(uSize.x, uSize.y);
  vec2 p = (frag - 0.5 * uSize) / scale;
  float cs = cos(uB.w);
  float sn = sin(uB.w);
  p = vec2(cs * p.x + sn * p.y, -sn * p.x + cs * p.y);
  float ay = abs(p.y) + 1e-3;
  float side = p.y > 0.0 ? 1.0 : -1.0;
  // Perspectiva de un plano: lo lejano se junta en el horizonte.
  float z = 0.16 / ay;
  float x = p.x * z;
  float depth = z * 3.0 + uA.x * 4.0;
  vec3 col = plane(uB.y, x, depth, side, z);
  if (uB.z < 0.999) col = mix(plane(uB.x, x, depth, side, z), col, uB.z);
  float near = smoothstep(0.012, 0.08, ay);
  float far = exp(-z * 0.12);
  col *= near * far * (0.85 + 0.5 * uA.y + 0.6 * uA.z) * uD.x;
  // Horizonte brillante en el centro.
  float horizon = uD.z * (0.9 + 0.8 * uA.z);
  col += vec3(1.0) * exp(-ay * 220.0) * horizon;
  col += tone(uB.y * 0.37) * exp(-ay * 30.0) * 0.35 * horizon;
  col += tone(uB.y * 0.37 + 0.5) * uD.w * 0.06;
  float peak = max(col.r, max(col.g, col.b));
  if (peak > 0.85) {
    float e = (peak - 0.85) / 0.15;
    col *= (0.85 + 0.15 * e / (1.0 + e)) / peak;
  }
  col += uC0 + (hash12(frag) - 0.5) / 255.0;
  fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

visuals.nativeSource:
class Visual final : public Scene {
  static constexpr int kSpirals = 3;
  static constexpr int kTargets = 4;
  float bass = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  // Relojes en doble precisión: la placa sin música es idéntica a 30 y 60 FPS.
  double chem = 0, sinceIdle = 0, sinceSpawn = 10;
  std::array<float, kSpirals> sx{}, sy{}, sphase{};
  std::array<float, kTargets> tx{}, ty{};
  std::array<double, kTargets> tBirth{};
  std::array<bool, kTargets> tActive{};
  int nextTarget = 0;
  uint32_t spawns = 0;

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }
  static float hashU(uint32_t x) {
    x ^= x >> 16; x *= 0x7feb352dU; x ^= x >> 15; x *= 0x846ca68bU; x ^= x >> 16;
    return float(x & 0xffffffu) / 16777216.0f;
  }
  // Un foco nuevo lanza anillos desde un punto de la placa.
  void spawn(double carry) {
    const uint32_t k = spawns++;
    tx[size_t(nextTarget)] = (hashU(k * 2654435761u + 17u) - 0.5f) * 0.8f;
    ty[size_t(nextTarget)] = (hashU(k * 2246822519u + 91u) - 0.5f) * 1.4f;
    tBirth[size_t(nextTarget)] = chem - carry;
    tActive[size_t(nextTarget)] = true;
    nextTarget = (nextTarget + 1) % kTargets;
  }

 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    bass = energy = slowBass = kick = flash = drive = 0;
    chem = 30.0 + double(rng.unit()) * 20.0;
    sinceIdle = 0;
    sinceSpawn = 10;
    const float bx[kSpirals] = {-0.2f, 0.22f, -0.12f};
    const float by[kSpirals] = {-0.5f, 0.02f, 0.52f};
    for (int i = 0; i < kSpirals; i++) {
      sx[size_t(i)] = bx[i] + (rng.unit() - 0.5f) * 0.12f;
      sy[size_t(i)] = by[i] + (rng.unit() - 0.5f) * 0.12f;
      sphase[size_t(i)] = rng.unit();
    }
    tActive.fill(false);
    tBirth.fill(0.0);
    nextTarget = 0;
    spawns = seed * 7u;
  }

  void update(const Frame& f) override {
    auto m = modifiers(f);
    const float dt = float(f.delta);
    const Music& mu = f.music;
    bass = follow(bass, mu.bass, 22.0f, 4.5f, dt);
    energy = follow(energy, mu.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, mu.active ? std::pow(std::clamp(mu.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);
    float hit = 0, fl = 0;
    for (const auto& e : mu.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : mu.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : mu.events[3]) fl = std::max(fl, e.strength);
    const float onset = std::clamp((mu.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, mu.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    const bool fresh = hit > kick + 0.2f;
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    // Energía: la música acelera la química.
    const double rate = 1.0 + (m.pulso == 2 ? 1.6 : 0.3) * double(drive * f.intensity);
    chem += f.delta * f.speed * rate;
    sinceSpawn += f.delta;
    // Golpes: cada golpe hace nacer un foco nuevo.
    if (m.pulso == 0 && fresh && sinceSpawn > 0.4) {
      spawn(0.0);
      sinceSpawn = 0;
    }
    // Sin música nace un foco cada 4,5 s; con música, cada 9 s.
    const double period = mu.active ? 9.0 : 4.5;
    sinceIdle += f.delta * f.speed;
    if (sinceIdle >= period) {
      sinceIdle -= period;
      spawn(sinceIdle);
    }
  }

  void render(const Frame& f, Canvas& c) const override {
    auto m = modifiers(f);
    auto g = glide(f);
    const float amp = f.intensity;
    const float t = float(std::fmod(chem, 100000.0));
    std::vector<float> u;
    u.reserve(64);
    u.insert(u.end(), {t, std::min(bass * amp, 1.5f), std::min(kick * amp, 1.0f), std::min(flash * amp, 1.0f)});
    // Velocidad de la onda, periodo, ancho del frente y brazos.
    // Detalle: ondas más juntas (periodo más corto).
    u.insert(u.end(), {0.11f, 2.6f / (0.55f + 0.45f * f.detail), 0.05f + 0.16f * g.frente, float(m.brazos)});
    u.insert(u.end(), {g.deriva.weight(1), g.deriva.weight(2), g.placa, g.pulso.weight(1)});
    u.insert(u.end(), {f.glow, float(f.width / std::min(f.width, f.height)), float(f.height / std::min(f.width, f.height)), 0.0f});
    for (int i = 0; i < kSpirals; i++) {
      const float drift = float(std::sin(chem * 0.03 + double(i) * 2.1));
      const float sign = i % 2 == 0 ? 1.0f : -1.0f;
      u.insert(u.end(), {sx[size_t(i)] + 0.04f * drift, sy[size_t(i)] + 0.03f * float(std::cos(chem * 0.025 + double(i))), sign, sphase[size_t(i)]});
    }
    for (int i = 0; i < kTargets; i++) {
      const float age = tActive[size_t(i)] ? float(std::min(chem - tBirth[size_t(i)], 1000.0)) : -1.0f;
      u.insert(u.end(), {tx[size_t(i)], ty[size_t(i)], age, tActive[size_t(i)] ? 1.0f : 0.0f});
    }
    for (int i = 0; i < 4; i++) u.insert(u.end(), {f.colors[size_t(i)].r, f.colors[size_t(i)].g, f.colors[size_t(i)].b});
    c.material("bz_reaction", {0, 0, f.width, f.height}, u);
  }
};

shaderSources.bz_reaction:
#version 460 core
#include <flutter/runtime_effect.glsl>
uniform vec2 uSize;
uniform vec4 uA;   // tiempo químico, graves, golpe, destello
uniform vec4 uB;   // velocidad de onda, periodo, ancho del frente, brazos
uniform vec4 uM;   // remolino, turbulenta, placa, peso de graves
uniform vec4 uV;   // glow, ancho y alto en unidades
uniform vec4 uS0;  // espirales: x, y, giro, desfase
uniform vec4 uS1;
uniform vec4 uS2;
uniform vec4 uT0;  // focos: x, y, edad, activo
uniform vec4 uT1;
uniform vec4 uT2;
uniform vec4 uT3;
uniform vec3 uC0;
uniform vec3 uC1;
uniform vec3 uC2;
uniform vec3 uC3;
out vec4 fragColor;

const float TAU = 6.2831853;

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash12(i), hash12(i + vec2(1.0, 0.0)), u.x),
             mix(hash12(i + vec2(0.0, 1.0)), hash12(i + vec2(1.0, 1.0)), u.x), u.y);
}

// Fase de una fuente en p, su llegada (segundos) y la distancia.
vec3 source(vec2 p, vec2 c, float arms, float offset, float time, float v, float T) {
  vec2 d = p - c;
  float dist = sqrt(dot(d, d) + 0.0004);
  float phase = (time - dist / v) / T + arms * atan(d.y, d.x) / TAU + offset;
  return vec3(phase, dist / v, dist);
}

vec2 wave(float phase) {
  return vec2(cos(phase * TAU), sin(phase * TAU));
}

void main() {
  vec2 frag = FlutterFragCoord().xy;
  float scale = min(uSize.x, uSize.y);
  vec2 p = (frag - 0.5 * uSize) / scale;
  float t = uA.x;
  vec2 p0 = p;
  // Corriente: el líquido gira o se agita bajo la reacción.
  if (uM.x > 0.001) {
    float ang = uM.x * 0.9 * exp(-length(p) * 1.6) * sin(t * 0.07);
    float cs = cos(ang);
    float sn = sin(ang);
    p = vec2(cs * p.x - sn * p.y, sn * p.x + cs * p.y);
  }
  if (uM.y > 0.001) {
    vec2 w = vec2(noise(p * 3.0 + vec2(t * 0.05, 0.0)), noise(p * 3.0 + vec2(4.7, -t * 0.04))) - 0.5;
    p += w * 0.09 * uM.y;
  }
  float v = uB.x;
  float T = uB.y;
  vec3 s0 = source(p, uS0.xy, uB.w * uS0.z, uS0.w, t, v, T);
  vec3 s1 = source(p, uS1.xy, uB.w * uS1.z, uS1.w, t, v, T);
  vec3 s2 = source(p, uS2.xy, uB.w * uS2.z, uS2.w, t, v, T);
  vec3 q0 = source(p, uT0.xy, 0.0, 0.0, uT0.z, v, T);
  vec3 q1 = source(p, uT1.xy, 0.0, 0.0, uT1.z, v, T);
  vec3 q2 = source(p, uT2.xy, 0.0, 0.0, uT2.z, v, T);
  vec3 q3 = source(p, uT3.xy, 0.0, 0.0, uT3.z, v, T);
  // Un foco nuevo sólo alcanza hasta donde llegó su primer anillo.
  float r0 = uT0.w * smoothstep(0.0, 0.03, uT0.z * v - q0.z);
  float r1 = uT1.w * smoothstep(0.0, 0.03, uT1.z * v - q1.z);
  float r2 = uT2.w * smoothstep(0.0, 0.03, uT2.z * v - q2.z);
  float r3 = uT3.w * smoothstep(0.0, 0.03, uT3.z * v - q3.z);
  // Gana el frente que llega antes: los focos, cerca de su centro.
  float a0 = mix(1e3, q0.y - 0.6, step(0.001, r0));
  float a1 = mix(1e3, q1.y - 0.6, step(0.001, r1));
  float a2 = mix(1e3, q2.y - 0.6, step(0.001, r2));
  float a3 = mix(1e3, q3.y - 0.6, step(0.001, r3));
  float best = min(min(min(s0.y, s1.y), min(s2.y, a0)), min(min(a1, a2), a3));
  float w0 = exp(-(s0.y - best) * 3.0);
  float w1 = exp(-(s1.y - best) * 3.0);
  float w2 = exp(-(s2.y - best) * 3.0);
  float w3 = exp(-(a0 - best) * 3.0) * r0;
  float w4 = exp(-(a1 - best) * 3.0) * r1;
  float w5 = exp(-(a2 - best) * 3.0) * r2;
  float w6 = exp(-(a3 - best) * 3.0) * r3;
  // Las fases se mezclan como vectores: donde chocan dos frentes se anulan.
  vec2 z = w0 * wave(s0.x) + w1 * wave(s1.x) + w2 * wave(s2.x) + w3 * wave(q0.x) +
           w4 * wave(q1.x) + w5 * wave(q2.x) + w6 * wave(q3.x);
  float wsum = w0 + w1 + w2 + w3 + w4 + w5 + w6;
  float coherence = clamp(length(z) / max(wsum, 1e-4), 0.0, 1.0);
  float phase = atan(z.y, z.x) / TAU;
  // Tiempo desde que pasó el último frente.
  float tau = fract(phase) * T;
  float width = uB.z * T * (1.0 + 0.9 * uA.y * uM.w);
  float front = exp(-tau / max(width * 0.35, 0.01));
  float body = exp(-tau / max(width * 1.4, 0.02));
  float rest = smoothstep(0.3 * T, T, tau);
  vec3 ready = mix(uC0, uC1, 0.55);
  vec3 col = mix(uC0 * 0.7, ready, rest);
  col = mix(col, uC1, body * coherence * 0.8);
  col = mix(col, uC2, smoothstep(0.15, 0.6, body) * coherence);
  col = mix(col, uC3, front * coherence);
  // Brillo de los frentes.
  col += uC2 * front * coherence * 0.25 * uV.x;
  // Textura del gel.
  col *= 0.94 + 0.06 * noise(p0 * 40.0);
  col *= 1.0 + 0.2 * uA.z + 0.15 * uA.w;
  // Placa de Petri: la reacción queda dentro de un círculo de cristal.
  if (uM.z > 0.001) {
    float r = length(p0);
    float R = 0.47 * min(uV.y, uV.z);
    float inside = smoothstep(R + 0.004, R - 0.004, r);
    float rim = exp(-abs(r - R) * 90.0);
    vec3 outside = uC0 * 0.4 * (1.0 - 0.3 * smoothstep(R, R + 0.6, r));
    vec3 dish = mix(outside, col, inside) + uC3 * rim * 0.35;
    col = mix(col, dish, uM.z);
  }
  col *= 1.0 - 0.25 * smoothstep(0.6, 1.4, length(p0 * vec2(0.9, 0.65)));
  col += (hash12(frag) - 0.5) / 255.0;
  fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

visuals.nativeSource:
class Visual final : public Scene {
  static constexpr int kLobes = 6;
  static constexpr double kMorph = 0.6;
  struct Lobe { float x, y, r, w; };
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  // Relojes en doble precisión: sin música es idéntico a 30 y 60 FPS.
  double clock = 0, flow = 0, aux = 0, shapeAt = -100, sinceBeat = 100, sinceIdle = 0;
  float beatPower = 0, spread = 0, spreadVel = 0;
  uint32_t shapes = 0, beats = 0;
  std::array<Lobe, kLobes> from{}, to{};

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }
  static float hashU(uint32_t x) {
    x ^= x >> 16; x *= 0x7feb352dU; x ^= x >> 15; x *= 0x846ca68bU; x ^= x >> 16;
    return float(x & 0xffffffu) / 16777216.0f;
  }
  // Rebote al llegar a la forma nueva: se pasa un poco y vuelve.
  static float easeBack(float p) {
    p = std::clamp(p, 0.0f, 1.0f);
    const float e = p - 1.0f;
    return 1.0f + 2.4f * e * e * e + 1.4f * e * e;
  }
  // Lóbulo i de la forma número k: el primero es siempre el cuerpo central;
  // algunos son negativos y abren huecos de papel dentro de la tinta.
  static Lobe pick(uint32_t k, int i) {
    const uint32_t s = k * 2654435761u + uint32_t(i) * 2246822519u + 0x9e3779b9u;
    const float a = hashU(s + 1u), b = hashU(s + 2u), c = hashU(s + 3u), d = hashU(s + 4u);
    if (i == 0) return {0.02f + 0.05f * a, -0.15f + 0.3f * b, 0.17f + 0.06f * c, 1.0f};
    Lobe L;
    L.x = 0.04f + 0.38f * a * a;
    L.y = -0.62f + 1.24f * b;
    L.r = 0.07f + 0.13f * c;
    L.w = d < 0.22f ? -0.45f - 0.4f * hashU(s + 5u) : 0.7f + 0.5f * hashU(s + 6u);
    return L;
  }
  Lobe lobeAt(int i, double time) const {
    const float e = easeBack(float((time - shapeAt) / kMorph));
    const Lobe& a = from[size_t(i)];
    const Lobe& b = to[size_t(i)];
    return {a.x + (b.x - a.x) * e, a.y + (b.y - a.y) * e, std::max(0.03f, a.r + (b.r - a.r) * e), a.w + (b.w - a.w) * e};
  }
  // Forma nueva; carry es el tiempo que ya pasó desde el instante del cambio.
  void newShape(double carry) {
    const double at = clock - carry;

    for (int i = 0; i < kLobes; i++) from[size_t(i)] = lobeAt(i, at);
    shapes++;
    for (int i = 0; i < kLobes; i++) to[size_t(i)] = pick(shapes, i);
    shapeAt = at;

  }

 public:
  void reset(uint32_t seed) override {
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    clock = flow = aux = 0;
    shapeAt = -100;
    sinceBeat = 100;
    sinceIdle = 0;
    beatPower = spread = spreadVel = 0;
    shapes = seed % 977u;
    beats = 0;
    for (int i = 0; i < kLobes; i++) from[size_t(i)] = to[size_t(i)] = pick(shapes, i);

  }

  void update(const Frame& f) override {
    auto m = modifiers(f);
    const float dt = float(f.delta);
    const Music& mu = f.music;
    bass = follow(bass, mu.bass, 22.0f, 4.5f, dt);
    body = follow(body, mu.body, 12.0f, 3.0f, dt);
    spark = follow(spark, mu.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, mu.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, mu.active ? std::pow(std::clamp(mu.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);
    float hit = 0, fl = 0;
    for (const auto& e : mu.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : mu.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : mu.events[3]) fl = std::max(fl, e.strength);
    const float onset = std::clamp((mu.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, mu.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    const bool fresh = hit > kick + 0.2f;
    sinceBeat += f.delta;
    if (fresh) {
      spreadVel += 2.2f * hit;
      sinceBeat = 0;
      beatPower = hit;
      beats++;
    }
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    spreadVel += (-spread * 18.0f - spreadVel * 5.0f) * dt;
    spread += spreadVel * dt;
    const double step = f.delta * f.speed;
    clock += step;
    // La tinta fluye más deprisa con la energía y con cada golpe.
    flow += step * (0.3 + 1.2 * double(drive) + 0.9 * double(kick)) * 0.8;
    // Metamorfosis: la forma cambia con cada golpe, cada cuatro o despacio.
    if (fresh && mu.active && m.mutacion != 2) {
      const uint32_t every = m.mutacion == 0 ? 1u : 4u;
      if (beats % every == 0u && clock - shapeAt > 0.4) newShape(0.0);
    }
    if (!mu.active || m.mutacion == 2) {
      const double idle = m.mutacion == 2 ? 2.8 * 1.8 : 2.8;
      sinceIdle += step;
      while (sinceIdle >= idle) {
        sinceIdle -= idle;
        newShape(sinceIdle);
        if (!mu.active) {
          // Sin música, cada forma nueva llega con un sobresalto.
          beatPower = 0.6f;
          sinceBeat = sinceIdle;
        }
      }
    }
    aux += step * (0.25 + 0.6 * double(drive));
  }

  void render(const Frame& f, Canvas& c) const override {
    auto m = modifiers(f);
    auto g = glide(f);
    (void)m;
    const float amp = f.intensity;
    const float pulse = sinceBeat < 2.0 ? beatPower * float(std::exp(-sinceBeat * 3.0)) : 0.0f;
    // Pulso: cada opción mueve una parte distinta de la mancha.
    const float golpe = std::min(pulse * amp, 1.2f) * g.pulso.weight(0);
    const float graves = std::min(bass * amp, 1.2f) * g.pulso.weight(1);
    const float agudos = std::min(spark * amp, 1.2f) * g.pulso.weight(2);
    const float morphP = float(std::clamp((clock - shapeAt) / kMorph, 0.0, 1.0));
    const float ft = float(std::fmod(flow, 1000.0));

    std::vector<float> u;
    u.reserve(64);
    u.insert(u.end(), {ft, std::min(bass * amp, 1.5f), std::min(kick * amp, 1.0f), std::min(energy * amp, 1.0f)});
    u.insert(u.end(), {g.presencia, g.lagrimas, g.negativo, f.detail});
    u.insert(u.end(), {f.glow, std::min(flash * amp, 1.0f), std::min(spark * amp, 1.0f), float(std::fmod(clock, 1000.0))});
    // Los lóbulos orbitan alrededor de su sitio; los graves los hinchan.
    const float wob = 0.045f * (1.0f + 0.8f * graves);
    for (int i = 0; i < kLobes; i++) {
      Lobe L = lobeAt(i, clock);
      const float fi = float(i);
      L.x = std::max(0.0f, L.x + wob * std::sin(ft * 0.83f + fi * 1.7f));
      L.y += wob * 1.3f * std::cos(ft * 0.61f + fi * 2.3f);
      L.r *= 1.0f + 0.12f * graves + 0.06f * std::sin(ft * 1.1f + fi);
      u.insert(u.end(), {L.x, L.y, L.r, L.w});
    }
    u.insert(u.end(), {float(std::fmod(aux, 1000.0)), float(std::min(clock - shapeAt, 30.0)), 0.0f, 0.0f});
    u.insert(u.end(), {golpe, graves, agudos, morphP});
    u.insert(u.end(), {std::max(-0.2f, spread) * amp * g.pulso.weight(0), float(std::min(sinceBeat, 9.0)),
                       std::min(pulse * amp, 1.2f), float(shapes % 997u)});
    for (int i = 0; i < 4; i++) u.insert(u.end(), {f.colors[size_t(i)].r, f.colors[size_t(i)].g, f.colors[size_t(i)].b});
    c.material("inkblot_skull", {0, 0, f.width, f.height}, u);
  }
};

shaderSources.inkblot_skull:
#version 460 core
#include <flutter/runtime_effect.glsl>
uniform vec2 uSize;
uniform vec4 uA;   // flujo de la tinta, graves, golpe, energía
uniform vec4 uB;   // ajustes de la variante
uniform vec4 uD;   // glow, destello, agudos, reloj
uniform vec4 uL0;  // lóbulos: x, y, radio, peso (negativo = hueco)
uniform vec4 uL1;
uniform vec4 uL2;
uniform vec4 uL3;
uniform vec4 uL4;
uniform vec4 uL5;
uniform vec4 uX;   // datos de la variante
uniform vec4 uY;   // Pulso: golpe, graves, agudos; avance del cambio de forma
uniform vec4 uP;   // expansión del golpe, edad del golpe, golpe, número de forma
uniform vec3 uC0;
uniform vec3 uC1;
uniform vec3 uC2;
uniform vec3 uC3;
out vec4 fragColor;

const float TAU = 6.2831853;

float sq(float x) {
  return x * x;
}

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash12(i), hash12(i + vec2(1.0, 0.0)), u.x),
             mix(hash12(i + vec2(0.0, 1.0)), hash12(i + vec2(1.0, 1.0)), u.x), u.y);
}

float fbm(vec2 p) {
  float v = 0.0;
  float a = 0.5;
  for (int i = 0; i < 3; i++) {
    v += noise(p) * a;
    p = p * 2.03 + vec2(1.7, 9.2);
    a *= 0.5;
  }
  return v / 0.875;
}

float lobe(vec2 q, vec4 L) {
  vec2 d = q - L.xy;
  return L.w * exp(-dot(d, d) / (L.z * L.z));
}

// La silueta sin ruido: los seis lóbulos y el eje del pliegue.
float envelope(vec2 q) {
  float e = lobe(q, uL0) + lobe(q, uL1) + lobe(q, uL2) + lobe(q, uL3) + lobe(q, uL4) + lobe(q, uL5);
  return e + 0.85 * exp(-q.x * q.x / 0.0035) * (1.0 - smoothstep(0.5, 0.92, abs(q.y)));
}

// Campo de tinta (positivo dentro). q ya viene reflejado. Los agudos agitan
// los bordes.
float blot(vec2 q, float t, float grow, out vec2 w, out float n) {
  w = vec2(noise(q * 1.9 + vec2(t * 0.42, 1.3)), noise(q * 1.9 + vec2(5.1, -t * 0.37))) - 0.5;
  vec2 qq = q + w * (0.13 + 0.16 * uY.z);
  n = fbm(qq * 3.3 + vec2(0.0, t * 0.5));
  float fine = noise(qq * 11.0 + vec2(t * 0.3, 2.0)) - 0.5;
  return envelope(qq) * 0.85 + (n - 0.5) * 1.15 + fine * 0.15 - 0.52 + grow;
}

// Los graves hinchan la mancha y el golpe la empuja hacia fuera.
float growth() {
  return 0.08 * uY.y + 0.22 * uP.x + 0.04 * uA.w;
}

vec3 paper(vec2 frag, vec2 p) {
  float fiber = hash12(floor(frag * vec2(0.5, 0.08))) * 0.6 + noise(frag * 0.05) * 0.4;
  vec3 col = uC0 * (0.92 + 0.08 * fiber);
  return col * (1.0 - 0.18 * smoothstep(0.55, 1.4, length(p * vec2(0.9, 0.62))));
}

// Tinta de calidad: lavado más claro donde es fina, borde acumulado más
// oscuro y grano de pigmento.
vec3 inkShade(vec3 inkC, vec3 tint, float F, float n, vec2 frag) {
  float grain = noise(frag * 0.9) * 0.5 + noise(frag * 0.23) * 0.5;
  float thin = 1.0 - smoothstep(0.0, 0.35, F);
  vec3 c = mix(inkC, tint, 0.1 + 0.32 * thin * (0.4 + 0.6 * n)) * (0.82 + 0.3 * grain);
  float pool = smoothstep(0.07, 0.0, F) * smoothstep(-0.012, 0.012, F);
  return mix(c, inkC * 0.35, pool * 0.85);
}

// Gotas que saltan alrededor del borde.
float spatter(vec2 q, float F, float amount, float seed) {
  if (F > 0.0 || F < -0.4) return 0.0;
  vec2 g = q * 30.0;
  vec2 cell = floor(g);
  if (hash12(cell + seed) > amount) return 0.0;
  vec2 off = vec2(hash12(cell + 3.1 + seed), hash12(cell + 7.7 + seed)) - 0.5;
  float rad = 0.08 + 0.25 * hash12(cell + 11.3);
  return 1.0 - smoothstep(rad - 0.05, rad, length(fract(g) - 0.5 - off * 0.45));
}

void main() {
  vec2 frag = FlutterFragCoord().xy;
  float scale = min(uSize.x, uSize.y);
  vec2 p = (frag - 0.5 * uSize) / scale;
  float t = uA.x;
  float br = uX.x;
  float age = uX.y;
  vec2 q = vec2(abs(p.x), p.y);
  vec2 w;
  float n;
  float F = blot(q, t, growth() + 0.05, w, n);
  // La calavera sólo se insinúa: aparece y desaparece despacio.
  float pres = clamp(uB.x * (0.6 + 0.4 * sin(br * 0.55)) + 0.45 * uY.x, 0.0, 1.0);
  vec2 qw = q + w * 0.1;
  // Tinta alrededor: la calavera es el hueco de papel que queda dentro.
  float halo = exp(-sq(length((qw - vec2(0.0, -0.02)) / vec2(0.36, 0.5))));
  float cr = length((qw - vec2(0.0, -0.1)) / vec2(0.19, 0.21));
  float jaw = length((qw - vec2(0.0, 0.1)) / vec2(0.12, 0.1));
  float skullM = max(smoothstep(1.15, 0.75, cr), smoothstep(1.2, 0.7, jaw));
  // Cuencas, nariz y dientes: islas de tinta dentro del hueco.
  vec2 eyeC = vec2(0.082 + 0.012 * sin(br), -0.1);
  float socket = smoothstep(1.1, 0.65, length((qw - eyeC) / vec2(0.055, 0.05 * (1.0 + 0.25 * uY.y))));
  float nose = smoothstep(1.1, 0.6, length((qw - vec2(0.0, 0.012)) / vec2(0.02, 0.035)));
  float teeth = smoothstep(0.55, 0.9, sin(qw.x * 70.0)) * exp(-sq((qw.y - 0.115) / 0.018)) * step(qw.x, 0.09);
  F += pres * (1.2 * halo - 2.6 * skullM + 2.8 * socket + 2.2 * nose + 1.2 * teeth);
  // Lágrimas de tinta que bajan desde las cuencas.
  float tears = 0.0;
  for (int k = 0; k < 3; k++) {
    float fk = float(k);
    float dx = eyeC.x - 0.025 + 0.025 * fk + 0.01 * (hash12(vec2(fk, uP.w)) - 0.5);
    float y0 = eyeC.y + 0.04;
    float len = uB.y * pres * (0.1 + 0.25 * hash12(vec2(fk, uP.w + 1.0))) * (1.0 - exp(-age * (0.4 + 1.2 * uY.x)));
    float along = qw.y - y0;
    float wd = 0.006 * (1.0 - 0.5 * clamp(along / max(len, 0.01), 0.0, 1.0));
    float stem = step(0.0, along) * step(along, len) * smoothstep(wd, wd * 0.4, abs(qw.x - dx));
    float bulb = smoothstep(wd * 2.0, wd * 1.3, length(qw - vec2(dx, y0 + len)));
    tears = max(tears, max(stem, bulb) * step(0.01, len));
  }
  float ink = max(smoothstep(-0.007, 0.007, F), tears);
  float grain = noise(frag * 0.9) * 0.5 + noise(frag * 0.23) * 0.5;
  vec3 inkCol = inkShade(uC1, uC2, F, n, frag);
  vec3 pap = paper(frag, p);
  pap = mix(pap, uC3, 0.2 * smoothstep(-0.12, 0.0, F) * (1.0 - ink));
  vec3 col = mix(pap, inkCol, ink);
  // Negativo: papel oscuro y tinta de hueso.
  vec3 neg = mix(uC1 * 0.6 + uC2 * 0.1, mix(uC3, uC0, 0.4) * (0.85 + 0.25 * grain), ink);
  col = mix(col, neg, uB.z);
  col += uC2 * 0.12 * pres * uY.x * (1.0 - ink) * exp(-sq(length(qw - vec2(0.0, -0.05)) / 0.25));
  float sp = spatter(q, F, 0.02 + 0.25 * uY.z + 0.15 * uY.x, floor(uD.w * 5.0));
  col = mix(col, mix(uC1, uC3, uB.z), sp);
  col = mix(col, uC2, uD.y * 0.04);
  col *= 0.97 + 0.03 * uD.x;
  fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

visuals.nativeSource:
class Visual final : public Scene {
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  // Relojes en doble precisión: la escena sin música es idéntica a 30 y 60 FPS.
  double morph = 0, clock = 0, aux = 0, sinceBeat = 100, sinceIdle = 0;
  float spread = 0, spreadVel = 0, beatPower = 0;
  int beats = 0;


  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

  static float hashf(int n) {
    uint32_t x = uint32_t(n) * 2654435761u;
    x ^= x >> 15;
    x *= 2246822519u;
    x ^= x >> 13;
    return float(x & 0xffffff) / 16777216.0f;
  }

 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    morph = rng.unit() * 40.0;
    clock = 0;
    aux = 0;
    sinceBeat = 100;
    sinceIdle = 0;
    spread = spreadVel = beatPower = 0;
    beats = 0;

  }

  void update(const Frame& f) override {
    auto m = modifiers(f);
    float dt = float(f.delta);
    const Music& mu = f.music;
    bass = follow(bass, mu.bass, 22.0f, 4.5f, dt);
    body = follow(body, mu.body, 12.0f, 3.0f, dt);
    spark = follow(spark, mu.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, mu.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, mu.active ? std::pow(std::clamp(mu.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : mu.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : mu.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : mu.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((mu.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, mu.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    sinceBeat += f.delta;
    sinceIdle += f.delta;
    if (hit > kick + 0.2f) {
      spreadVel += 2.2f * hit;
      sinceBeat = 0;
      beatPower = hit;
      beats++;
      sinceIdle = 0;
    }
    // Sin música también hay un sobresalto cada pocos segundos.
    if (!mu.active && sinceIdle > 1.8) {
      sinceIdle -= 1.8;
      sinceBeat = sinceIdle;
      beatPower = 0.7f;
      beats++;
    }
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    spreadVel += (-spread * 18.0f - spreadVel * 5.0f) * dt;
    spread += spreadVel * dt;
    clock += f.delta * f.speed;
    morph += f.delta * f.speed * (0.14 + 0.35 * drive) * 1.4;
    aux += f.delta * f.speed * m.giro * (0.15 + 0.4 * drive);
  }

  void render(const Frame& f, Canvas& c) const override {
    auto m = modifiers(f);
    float amp = f.intensity;
    float t = float(std::fmod(morph, 1000.0));
    float pulse = sinceBeat < 2.0 ? beatPower * float(std::exp(-sinceBeat * 3.0)) : 0.0f;
    std::vector<float> u;
    u.reserve(56);
    u.insert(u.end(), {t, bass * amp, kick * amp, energy});
    u.insert(u.end(), {float(m.pliegues), m.tamano, float(m.colores), 0.0f});
    u.insert(u.end(), {f.glow, flash * amp, spark * amp, float(std::fmod(clock, 1000.0))});
    // Lóbulos de la mancha: cinco manchas grandes que derivan despacio.
    static const float lx[5] = {0.25f, 0.4f, 0.15f, 0.32f, 0.5f};
    static const float ly[5] = {0.05f, 0.12f, 0.02f, 0.25f, 0.1f};
    static const float lr[5] = {0.12f, 0.14f, 0.1f, 0.12f, 0.1f};
    for (int k = 0; k < 5; k++) {
      float fk = float(k);
      u.insert(u.end(), {lx[k] + 0.07f * std::sin(t * 0.7f + fk * 1.9f), ly[k] + 0.07f * std::cos(t * 0.5f + fk * 2.7f), lr[k], 0.0f});
    }
    u.insert(u.end(), {float(std::fmod(aux, 6.2831853)), sinceBeat < 3.0 ? float(sinceBeat) * 0.45f : 9.0f, 0.0f, 0.0f});
    u.insert(u.end(), {pulse, std::max(-0.2f, spread) * amp, 0.0f, 0.0f});
    for (int i = 0; i < 4; i++) u.insert(u.end(), {f.colors[i].r, f.colors[i].g, f.colors[i].b});
    c.material("inkblot_kaleido", {0, 0, f.width, f.height}, u);
  }
};

shaderSources.inkblot_kaleido:
#version 460 core
#include <flutter/runtime_effect.glsl>
uniform vec2 uSize;
uniform vec4 uA;   // cambio, graves, golpe, energía
uniform vec4 uB;   // ajustes de la variante
uniform vec4 uD;   // glow, destello, agudos, reloj real
uniform vec4 uL0;  // lóbulos: x, y, radio
uniform vec4 uL1;
uniform vec4 uL2;
uniform vec4 uL3;
uniform vec4 uL4;
uniform vec4 uX;   // datos propios de la variante
uniform vec4 uP;   // sobresalto, expansión
uniform vec3 uC0;
uniform vec3 uC1;
uniform vec3 uC2;
uniform vec3 uC3;
out vec4 fragColor;

const float TAU = 6.2831853;

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash12(i), hash12(i + vec2(1.0, 0.0)), u.x),
             mix(hash12(i + vec2(0.0, 1.0)), hash12(i + vec2(1.0, 1.0)), u.x), u.y);
}

float fbm(vec2 p) {
  float v = 0.0;
  float a = 0.5;
  for (int i = 0; i < 3; i++) {
    v += noise(p) * a;
    p = p * 2.03 + vec2(1.7, 9.2);
    a *= 0.5;
  }
  return v / 0.875;
}

float lobe(vec2 q, vec4 L) {
  vec2 d = q - L.xy;
  return exp(-dot(d, d) / (L.z * L.z));
}

// Campo de tinta: positivo dentro de la mancha. q ya viene reflejado.
float blot(vec2 q, float t, float grow, out vec2 w, out float n) {
  w = vec2(noise(q * 2.2 + vec2(t * 0.6, 0.0)), noise(q * 2.2 + vec2(4.3, -t * 0.5))) - 0.5;
  n = fbm(q * 3.6 + w * 1.4 + vec2(0.0, t * 0.25));
  vec2 qw = q + w * 0.08;
  float env = lobe(qw, uL0) + lobe(qw, uL1) + lobe(qw, uL2) + lobe(qw, uL3) + lobe(qw, uL4);
  env += 0.9 * exp(-q.x * q.x / 0.004) * (1.0 - smoothstep(0.55, 0.95, abs(q.y)));
  return env * 0.8 + (n - 0.5) * 1.1 - 0.5 + grow;
}

vec3 paper(vec2 frag, vec2 p) {
  float fiber = hash12(floor(frag * vec2(0.5, 0.08))) * 0.6 + noise(frag * 0.05) * 0.4;
  vec3 col = uC0 * (0.93 + 0.07 * fiber);
  return col * (1.0 - 0.16 * smoothstep(0.6, 1.4, length(p * vec2(0.9, 0.65))));
}

vec3 ink(float k) {
  if (uB.z < 0.5) return k < 1.0 ? uC1 : (k < 2.0 ? uC2 : uC3);
  if (uB.z < 1.5) return k < 1.0 ? uC1 * 0.6 : (k < 2.0 ? uC1 : vec3(1.0, 0.35, 0.3));
  return k < 1.0 ? vec3(0.4, 0.9, 0.0) : (k < 2.0 ? vec3(0.9, 1.0, 0.1) : vec3(1.0, 0.5, 0.0));
}

void main() {
  vec2 frag = FlutterFragCoord().xy;
  float scale = min(uSize.x, uSize.y);
  vec2 p = (frag - 0.5 * uSize) / scale / uB.y;
  float t = uA.x;
  float r = length(p);
  float sector = TAU / uB.x;
  float a = mod(atan(p.y, p.x) + uX.x, sector);
  a = abs(a - sector * 0.5);
  vec2 q = vec2(cos(a), sin(a)) * r;
  vec2 w;
  float n;
  float F = blot(q, t, 0.1 * uA.y + 0.2 * uP.y - 0.15, w, n);
  // Anillos de tinta que salen con cada golpe.
  F = max(F, (0.06 - abs(r - uX.y)) * 3.0 * uP.x + (n - 0.5) * 0.2);
  float n2 = fbm(q * 5.0 - w * 2.0 + vec2(t * 0.3, 1.7));
  vec3 col = uC0;
  float aa = 0.01;
  float l1 = smoothstep(-aa, aa, F);
  float l2 = smoothstep(-aa, aa, F - 0.42 + (n2 - 0.5) * 0.5);
  float l3 = smoothstep(-aa, aa, F - 0.95 + (n2 - 0.5) * 0.6);
  col = mix(col, ink(0.0) * (0.6 + 0.6 * n), l1);
  col = mix(col, ink(0.0) * 0.25, l1 * smoothstep(0.08, 0.0, F));
  col = mix(col, ink(1.0) * (0.8 + 0.4 * n2), l2);
  col = mix(col, ink(2.0) * (0.9 + 0.3 * uA.z), l3);
  col *= 1.0 + 0.3 * uA.y;
  col += ink(1.0) * uD.y * 0.05;
  col *= 1.0 - 0.25 * smoothstep(0.8, 1.6, r * uB.y);
  float cover = l1;
  fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

