class Visual final : public Scene {
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  // Relojes en doble precisión: la escena sin música es idéntica a 30 y 60 FPS.
  double morph = 0, clock = 0, aux = 0, sinceBeat = 100, sinceIdle = 0;
  float spread = 0, spreadVel = 0, beatPower = 0;
  int beats = 0;


  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

  static float hashf(int n) {
    uint32_t x = uint32_t(n) * 2654435761u;
    x ^= x >> 15;
    x *= 2246822519u;
    x ^= x >> 13;
    return float(x & 0xffffff) / 16777216.0f;
  }

 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    morph = rng.unit() * 40.0;
    clock = 0;
    aux = 0;
    sinceBeat = 100;
    sinceIdle = 0;
    spread = spreadVel = beatPower = 0;
    beats = 0;

  }

  void update(const Frame& f) override {
    auto m = modifiers(f);
    float dt = float(f.delta);
    const Music& mu = f.music;
    bass = follow(bass, mu.bass, 22.0f, 4.5f, dt);
    body = follow(body, mu.body, 12.0f, 3.0f, dt);
    spark = follow(spark, mu.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, mu.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, mu.active ? std::pow(std::clamp(mu.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : mu.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : mu.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : mu.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((mu.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, mu.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    sinceBeat += f.delta;
    sinceIdle += f.delta;
    if (hit > kick + 0.2f) {
      spreadVel += 2.2f * hit;
      sinceBeat = 0;
      beatPower = hit;
      beats++;
      sinceIdle = 0;
    }
    // Sin música también hay un sobresalto cada pocos segundos.
    if (!mu.active && sinceIdle > 2.0) {
      sinceIdle -= 2.0;
      sinceBeat = sinceIdle;
      beatPower = 0.7f;
      beats++;
    }
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    spreadVel += (-spread * 18.0f - spreadVel * 5.0f) * dt;
    spread += spreadVel * dt;
    clock += f.delta * f.speed;
    morph += f.delta * f.speed * (0.14 + 0.35 * drive) * 1.0;
    aux += f.delta * f.speed * m.agitacion * (0.6 + 1.5 * drive);
  }

  void render(const Frame& f, Canvas& c) const override {
    auto m = modifiers(f);
    float amp = f.intensity;
    float t = float(std::fmod(morph, 1000.0));
    float pulse = sinceBeat < 2.0 ? beatPower * float(std::exp(-sinceBeat * 3.0)) : 0.0f;
    std::vector<float> u;
    u.reserve(56);
    u.insert(u.end(), {t, bass * amp, kick * amp, energy});
    u.insert(u.end(), {float(m.tentaculos), m.tamano, m.roja ? 1.0f : 0.0f, 0.0f});
    u.insert(u.end(), {f.glow, flash * amp, spark * amp, float(std::fmod(clock, 1000.0))});
    // Lóbulos de la mancha: cinco manchas grandes que derivan despacio.
    static const float lx[5] = {0.08f, 0.16f, 0.12f, 0.2f, 0.06f};
    static const float ly[5] = {-0.2f, -0.05f, 0.1f, 0.22f, -0.32f};
    static const float lr[5] = {0.13f, 0.14f, 0.15f, 0.11f, 0.1f};
    for (int k = 0; k < 5; k++) {
      float fk = float(k);
      u.insert(u.end(), {lx[k] + 0.07f * std::sin(t * 0.7f + fk * 1.9f), ly[k] + 0.07f * std::cos(t * 0.5f + fk * 2.7f), lr[k], 0.0f});
    }
    u.insert(u.end(), {float(std::fmod(aux, 1000.0)), 0.0f, 0.0f, 0.0f});
    u.insert(u.end(), {pulse, std::max(-0.2f, spread) * amp, 0.0f, 0.0f});
    for (int i = 0; i < 4; i++) u.insert(u.end(), {f.colors[i].r, f.colors[i].g, f.colors[i].b});
    c.material("inkblot_tentacles", {0, 0, f.width, f.height}, u);
  }
};

shaderSources.inkblot_tentacles:
#version 460 core
#include <flutter/runtime_effect.glsl>
uniform vec2 uSize;
uniform vec4 uA;   // cambio, graves, golpe, energía
uniform vec4 uB;   // ajustes de la variante
uniform vec4 uD;   // glow, destello, agudos, reloj real
uniform vec4 uL0;  // lóbulos: x, y, radio
uniform vec4 uL1;
uniform vec4 uL2;
uniform vec4 uL3;
uniform vec4 uL4;
uniform vec4 uX;   // datos propios de la variante
uniform vec4 uP;   // sobresalto, expansión
uniform vec3 uC0;
uniform vec3 uC1;
uniform vec3 uC2;
uniform vec3 uC3;
out vec4 fragColor;

const float TAU = 6.2831853;

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash12(i), hash12(i + vec2(1.0, 0.0)), u.x),
             mix(hash12(i + vec2(0.0, 1.0)), hash12(i + vec2(1.0, 1.0)), u.x), u.y);
}

float fbm(vec2 p) {
  float v = 0.0;
  float a = 0.5;
  for (int i = 0; i < 3; i++) {
    v += noise(p) * a;
    p = p * 2.03 + vec2(1.7, 9.2);
    a *= 0.5;
  }
  return v / 0.875;
}

float lobe(vec2 q, vec4 L) {
  vec2 d = q - L.xy;
  return exp(-dot(d, d) / (L.z * L.z));
}

// Campo de tinta: positivo dentro de la mancha. q ya viene reflejado.
float blot(vec2 q, float t, float grow, out vec2 w, out float n) {
  w = vec2(noise(q * 2.2 + vec2(t * 0.6, 0.0)), noise(q * 2.2 + vec2(4.3, -t * 0.5))) - 0.5;
  n = fbm(q * 3.6 + w * 1.4 + vec2(0.0, t * 0.25));
  vec2 qw = q + w * 0.08;
  float env = lobe(qw, uL0) + lobe(qw, uL1) + lobe(qw, uL2) + lobe(qw, uL3) + lobe(qw, uL4);
  env += 0.9 * exp(-q.x * q.x / 0.004) * (1.0 - smoothstep(0.55, 0.95, abs(q.y)));
  return env * 0.8 + (n - 0.5) * 1.1 - 0.5 + grow;
}

vec3 paper(vec2 frag, vec2 p) {
  float fiber = hash12(floor(frag * vec2(0.5, 0.08))) * 0.6 + noise(frag * 0.05) * 0.4;
  vec3 col = uC0 * (0.93 + 0.07 * fiber);
  return col * (1.0 - 0.16 * smoothstep(0.6, 1.4, length(p * vec2(0.9, 0.65))));
}

void main() {
  vec2 frag = FlutterFragCoord().xy;
  float scale = min(uSize.x, uSize.y);
  vec2 p = (frag - 0.5 * uSize) / scale;
  float t = uA.x;
  float s = uB.y;
  vec2 q = vec2(abs(p.x), p.y) / s;
  vec2 w;
  float n;
  float F = blot(q, t, 0.0 + 0.08 * uA.y, w, n);
  // Tentáculos: brazos que salen del centro, se enroscan y se estrechan.
  float r = length(q);
  float a = atan(q.y, q.x);
  float lash = 0.46 + 0.15 * uA.w + 0.3 * uP.x + 0.2 * uP.y;
  float curl = sin(r * 9.0 - uX.x * 2.2) * 0.45 * smoothstep(0.05, 0.4, r) + sin(r * 4.0 + uX.x) * 0.25;
  float arms = uB.x;
  float k = (a + curl) / TAU * arms * 2.0;
  float dArm = abs(fract(k) - 0.5) / (arms * 2.0) * TAU * r;
  float taper = 1.0 - smoothstep(0.0, lash, r);
  float width = 0.075 * pow(taper, 0.8) + 0.004;
  // Fuera del alcance de los brazos no hay tentáculo (campo negativo).
  float tent = r < lash + 0.02 ? (width - dArm) * 6.0 : -1.0;
  F = max(F, tent);
  float aa = 0.008;
  float ink = smoothstep(-aa, aa, F);
  vec3 col = paper(frag, p) * vec3(1.0, 0.98, 0.88);
  float rim = smoothstep(0.1, 0.0, F);
  vec3 under = uB.z > 0.5 ? mix(uC2, uC3, n) : uC1 * 1.5;
  vec3 inkCol = mix(uC1, under, (1.0 - rim) * 0.35 * smoothstep(0.35, 0.75, n));
  inkCol *= 1.0 + 0.2 * uA.z;
  col = mix(col, inkCol, ink);
  // Ventosas: puntitos claros a lo largo de los tentáculos.
  float cups = step(0.0, tent) * smoothstep(0.35, 0.0, length(fract(vec2(k * 2.0, r * 22.0)) - 0.5)) * step(0.1, r);
  col = mix(col, uC3 * 0.6, cups * 0.5 * ink);
  float cover = ink;
  col = mix(col, uC3, uD.y * 0.04);
  // Fondo transparente: el papel desaparece y sólo queda lo pintado.
  float inkAlpha = clamp(cover, 0.0, 1.0);
  fragColor = vec4(clamp(col, 0.0, 1.0) * inkAlpha, inkAlpha);
}

visuals.nativeSource:
class Visual final : public Scene {
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  // Relojes en doble precisión: la escena sin música es idéntica a 30 y 60 FPS.
  double clock = 0, travel = 0, pulseAge = 100, sinceIdle = 0;
  float pulsePower = 0;
  // Fuerza del golpe que lanzó la ola (0 en las olas sin música).
  float pulseHit = 0;

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    clock = rng.unit() * 40.0;
    travel = rng.unit() * 100.0;
    pulseAge = 100;
    pulsePower = 0;
    pulseHit = 0;
    sinceIdle = 0;
  }

  void update(const Frame& f) override {
    auto m = modifiers(f);
    float dt = float(f.delta);
    const Music& mu = f.music;
    bass = follow(bass, mu.bass, 22.0f, 4.5f, dt);
    body = follow(body, mu.body, 12.0f, 3.0f, dt);
    spark = follow(spark, mu.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, mu.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, mu.active ? std::pow(std::clamp(mu.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : mu.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : mu.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : mu.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((mu.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, mu.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    pulseAge += f.delta;
    sinceIdle += f.delta;
    if (hit > kick + 0.2f) {
      pulseAge = 0;
      pulsePower = hit;
      pulseHit = hit;
    }
    if (!mu.active && sinceIdle > 3.5) {
      sinceIdle -= 3.5;
      pulseAge = sinceIdle;
      pulsePower = 0.7f;
      pulseHit = 0;
    }
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    clock += f.delta * f.speed;
    travel += f.delta * f.speed * m.avance * (0.6 + 1.6 * drive);
  }

  void render(const Frame& f, Canvas& c) const override {
    auto m = modifiers(f);
    auto g = glide(f);
    float amp = f.intensity;
    // La ola del golpe viaja desde la cámara hacia el fondo.
    float pulseZ = pulseAge < 4.0 ? float(pulseAge) * 9.0f : 99.0f;
    float pulseP = pulseAge < 4.0 ? pulsePower * float(1.0 - pulseAge / 4.0) * amp : 0.0f;
    std::vector<float> u;
    u.reserve(32);
    u.insert(u.end(), {float(std::fmod(clock, 1000.0)), bass * amp, kick * amp, energy});
    u.insert(u.end(), {float(std::fmod(travel, 1000.0)), m.densidad, float(m.color), m.parpadeo ? 1.0f : 0.0f});
    u.insert(u.end(), {f.glow, flash * amp, pulseZ, pulseP});
    // Pulso: cada opción mueve una parte distinta (sin música, todo 0).
    const float golpe = g.pulso.weight(0);
    const float wide = pulseAge < 4.0 ? std::min(pulseHit * amp, 1.2f) * float(1.0 - pulseAge / 4.0) * golpe : 0.0f;
    u.insert(u.end(), {std::min(kick * amp, 1.2f) * golpe, std::min(bass * amp, 1.2f) * g.pulso.weight(1),
                       std::min(spark * amp, 1.2f) * g.pulso.weight(2), wide});
    for (int i = 0; i < 4; i++) u.insert(u.end(), {f.colors[i].r, f.colors[i].g, f.colors[i].b});
    c.material("mirror_room", {0, 0, f.width, f.height}, u);
  }
};

shaderSources.mirror_room:
#version 460 core
#include <flutter/runtime_effect.glsl>
uniform vec2 uSize;
uniform vec4 uA;   // reloj, graves, golpe, energía
uniform vec4 uB;   // avance, densidad, modo de color, parpadeo
uniform vec4 uD;   // glow, destello, distancia de la ola, fuerza de la ola
uniform vec4 uP;   // Pulso: golpe, graves, agudos, fuerza de la ola ancha
uniform vec3 uC0;
uniform vec3 uC1;
uniform vec3 uC2;
uniform vec3 uC3;
out vec4 fragColor;

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

vec3 hue(float h) {
  return clamp(abs(fract(h + vec3(0.0, 0.667, 0.333)) * 6.0 - 3.0) - 1.0, 0.0, 1.0);
}

vec3 lightColor(float h, float wave) {
  float mode = uB.z;
  if (mode < 0.5) {
    // Kusama: rojos, naranjas, rosas, amarillos y algún verde lima.
    float k = fract(h * 5.0 + wave);
    vec3 c = k < 0.3 ? uC1 : (k < 0.55 ? uC2 : (k < 0.75 ? vec3(1.0, 0.2, 0.6) : (k < 0.92 ? uC3 : vec3(0.55, 1.0, 0.15))));
    return c;
  }
  if (mode < 1.5) {
    float k = fract(h * 3.0 + wave);
    return k < 0.33 ? uC1 : (k < 0.66 ? uC2 : uC3);
  }
  if (mode < 2.5) return mix(uC1, vec3(1.0, 0.35, 0.1), fract(h * 2.0 + wave * 0.5));
  return hue(h * 0.3 + wave * 0.5);
}

void main() {
  vec2 frag = FlutterFragCoord().xy;
  float scale = min(uSize.x, uSize.y);
  vec2 p = (frag - 0.5 * uSize) / scale;
  float t = uA.x;
  // La cámara se mece un poco.
  p += 0.025 * vec2(sin(t * 0.31), cos(t * 0.23));
  float spacing = 1.0 / uB.y;
  float trav = uB.x;
  float base = floor(trav);
  float frac = trav - base;
  vec3 col = uC0;
  float glowSum = 0.0;
  // Halo grande de las luces con la música (0 en silencio).
  float bigSum = 0.0;
  float bigReach = 0.5 * min(uP.x + uP.y + uP.w, 1.0);
  for (int k = 0; k < 8; k++) {
    float z = float(k) + 1.0 - frac;
    float layer = base + float(k) + 1.0;
    float zoom = z * 1.5 / spacing;
    vec2 q = p * zoom;
    vec2 cell = floor(q + 0.5);
    vec2 key = cell + vec2(layer * 17.13, layer * 7.31);
    // Sólo algunas celdas tienen luz: la sala queda despejada. Las vacías
    // no cuestan nada más.
    if (hash12(key + 41.7) > 0.3) continue;
    float h = hash12(key);
    // Cada luz cuelga a su altura, sin salirse de su celda.
    vec2 local = q - cell - (vec2(hash12(key + 3.1), h) - 0.5) * 0.5;
    float d = length(local);
    // Graves: todas las luces se hinchan con los graves.
    float size = 0.055 + 0.035 * h + 0.025 * uA.y * step(z, 4.0) + 0.012 * uP.y + 0.012 * uP.x;
    // Borde suave de un píxel aunque la luz esté lejos.
    float aa = 1.2 * zoom / scale;
    // Lejos de la luz no llega ni su halo (con música, el halo grande sí).
    if (d > max(0.24 + bigReach, size + aa)) continue;
    float core = smoothstep(size + aa, size * 0.3, d);
    // Halo compacto: se apaga antes del borde de la celda, sin cortes.
    float hr = clamp(1.0 - d / 0.24, 0.0, 1.0);
    float halo = hr * hr * hr * (0.3 + 0.2 * uP.y);
    float fog = exp(-z * 0.2) * smoothstep(0.0, 0.9, z) * smoothstep(8.0, 5.5, z);
    float wave = sin(z * 0.45 - t * 1.8 + h * 2.0) * 0.12 + t * 0.05;
    vec3 lc = lightColor(h, wave);
    float twinkle = uB.w > 0.5 ? 0.6 + 0.4 * sin(t * (2.0 + 3.0 * h) + h * 40.0) : 1.0;
    float pulse = uD.w * exp(-abs(z - uD.z) * 0.9);
    float b = (core + halo) * fog * twinkle * (1.0 + 2.5 * pulse + 0.4 * uA.z);
    col += lc * b;
    if (uP.x + uP.y + uP.z + uP.w > 0.001) {
      // Golpes: la ola del golpe llega ancha y enciende toda la sala un instante.
      float beat = 0.9 * uP.x + 1.6 * uP.w * exp(-abs(z - uD.z) * 0.3);
      col += lc * (core + halo) * fog * twinkle * beat;
      // Golpes / Graves: un halo grande y suave que se apaga antes del borde
      // de su celda (sin cortes); el brillo del núcleo se satura, el halo no.
      vec2 inCell = abs(q - cell);
      float big = exp(-d * 7.0) * smoothstep(0.5, 0.3, max(inCell.x, inCell.y)) * fog;
      col += lc * big * (0.7 * beat + 0.4 * uP.y);
      bigSum += big;
      // Agudos: la mitad de las luces centellean con una chispa blanca.
      float flick = uP.z * step(0.45, hash12(key + floor(t * 11.0)));
      col += mix(lc, vec3(1.0), 0.6) * (core + halo * 0.6) * fog * 1.5 * flick;
    }
    glowSum += halo * fog;
  }
  // Bruma general de la sala, del color de las luces.
  col += mix(uC1, uC2, 0.5) * glowSum * 0.12 * uD.x;
  // Golpes: la bruma de la sala se enciende con el golpe.
  if (uP.x > 0.001) col += mix(uC1, uC2, 0.5) * glowSum * 0.12 * uD.x * 1.6 * uP.x;
  // Golpes / Graves: la bruma se enciende alrededor de las luces y al fondo de
  // la sala, donde se juntan todas (resplandor local, no un velo).
  if (uP.x + uP.y > 0.001) {
    col += mix(uC1, uC2, 0.5) * (exp(-length(p) / 0.35) * (0.3 * uP.x + 0.15 * uP.y) + bigSum * 0.12 * uP.x) * uD.x;
  }
  col += uC2 * uD.y * 0.05;
  col *= 1.0 - 0.3 * smoothstep(0.7, 1.5, length(p * vec2(0.9, 0.65)));
  float peak = max(col.r, max(col.g, col.b));
  if (peak > 0.85) {
    float e = (peak - 0.85) / 0.15;
    col *= (0.85 + 0.15 * e / (1.0 + e)) / peak;
  }
  col += (hash12(frag) - 0.5) / 255.0;
  fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

