class Visual final : public Scene {
  float road=0;
  // Música: envolventes suavizadas y golpe corto (valen 0 sin música).
  float bass=0,body=0,spark=0,energy=0,drive=0,slowBass=0,kick=0,flash=0;
  // Reloj propio para las chispas de los agudos.
  double clock=0;
  static float follow(float v,float target,float up,float down,float dt){
    return v+(target-v)*(1.0f-std::exp(-(target>v?up:down)*dt));
  }
  static float hashU(uint32_t x){
    x^=x>>16;x*=0x7feb352dU;x^=x>>15;x*=0x846ca68bU;x^=x>>16;
    return float(x&0xffffffu)/16777216.0f;
  }
 public:
  void reset(uint32_t) override {road=0;bass=body=spark=energy=drive=slowBass=kick=flash=0;clock=0;}
  void update(const Frame& f) override {road+=float(f.delta)*f.speed*.18f;
    // Música estándar: graves, cuerpo, agudos, energía y golpe corto.
    const float dt=float(f.delta);
    const Music& mu=f.music;
    bass=follow(bass,mu.bass,22.0f,4.5f,dt);
    body=follow(body,mu.body,12.0f,3.0f,dt);
    spark=follow(spark,mu.spark,30.0f,7.0f,dt);
    energy=follow(energy,mu.energy,6.0f,1.8f,dt);
    drive=follow(drive,mu.active?std::pow(std::clamp(mu.energy,0.0f,1.0f),0.8f):0.0f,3.0f,0.7f,dt);
    float hit=0,fl=0;
    for(const auto& e:mu.events[0])hit=std::max(hit,e.strength);
    for(const auto& e:mu.events[2])hit=std::max(hit,e.strength*0.85f);
    for(const auto& e:mu.events[3])fl=std::max(fl,e.strength);
    const float onset=std::clamp((mu.bass-slowBass-0.15f)*2.5f,0.0f,1.0f);
    slowBass=follow(slowBass,mu.bass,3.0f,3.0f,dt);
    hit=std::min(std::max(hit,onset),1.0f);
    kick=std::max(kick*std::exp(-dt*5.0f),hit);
    flash=std::max(flash*std::exp(-dt*8.0f),std::min(fl,1.0f));
    clock+=f.delta*f.speed;
  }
  void render(const Frame& f, Canvas& c) const override {
    auto g=glide(f);
    const float amp=f.intensity;
    // Pulso: cada opción mueve algo distinto y sus pesos mezclan las opciones.
    const float golpe=g.pulso.weight(0)*std::min(kick*amp,1.0f);
    const float graves=g.pulso.weight(1)*std::min(bass*amp,1.0f);
    const float agudos=g.pulso.weight(2)*std::min(spark*amp,1.0f);
    float w=f.width,h=f.height,horizon=h*.61f;
    c.rect({0,0,w,h},Paint::linear({0,0},{0,h},
      {Color::argb(0xff050722),Color::argb(0xff391b58),Color::argb(0xffee487b),Color::argb(0xff070614)},{0,.38f,.61f,.85f}));
    // Golpes: el sol late en cada golpe (+15%); Graves lo hace respirar (+12%).
    float radius=w*.27f*(1+golpe*.15f+graves*.12f); Vec2 sun={w*.5f,h*.39f};
    if(graves>.001f){
      // Graves: un halo rosa respira alrededor del sol.
      const float reach=radius*(1.3f+graves*.5f);
      Paint halo=Paint::radial(sun,reach,{Color{1,.45f,.55f,std::min(1.0f,.7f*graves)},Color{1,.2f,.6f,.3f*graves},Color{1,.1f,.5f,0}},{.55f,.78f,1});
      halo.blend=Blend::screen;c.circle(sun,reach,halo);
    }
    if(golpe>.001f){
      // Golpes: un resplandor cálido estalla detrás del sol en cada golpe y
      // se cuela entre sus franjas.
      const float flare=std::min(1.0f,.6f*golpe*f.glow);
      Paint burst=Paint::radial(sun,radius*2.6f,{Color{1,.7f,.5f,flare},Color{1,.45f,.55f,flare*.6f},Color{1,.2f,.5f,0}},{0,.4f,1});
      burst.blend=Blend::plus;c.circle(sun,radius*2.6f,burst);
    }
    Path cut;cut.fillRule=FillRule::evenOdd;cut.circle(sun,radius);
    // Franjas del sol: pocas y anchas o muchas y finas (8 es el original).
    const float bands=g.franjas;
    const int whole=int(bands);const float part=bands-float(whole);
    const float gap=.14f*8.0f/bands,ratio=8.0f/bands,thick=ratio*ratio;
    for(int i=0;i<whole+(part>.001f?1:0);i++) {float y=sun.y+radius*(-.1f+i*gap);cut.rect({sun.x-radius,y,radius*2,(2+i*1.2f)*thick*(i<whole?1.0f:part)});}
    c.save();c.clip(cut);
    Path within;within.circle(sun,radius);c.clip(within);
    c.rect({sun.x-radius,sun.y-radius,radius*2,radius*2},Paint::linear({0,sun.y-radius},{0,sun.y+radius},
      {Color::argb(0xfffff39d),Color::argb(0xffff7770),Color::argb(0xffff2cbd)}));c.restore();
    Paint mountain;mountain.color=Color::argb(0xff0a0b27);
    Path ridge;ridge.moveTo(0,horizon).lineTo(0,horizon-25).lineTo(w*.13f,horizon-95)
      .lineTo(w*.27f,horizon-45).lineTo(w*.4f,horizon-100).lineTo(w*.6f,horizon-22)
      .lineTo(w*.83f,horizon-116).lineTo(w,horizon-41).lineTo(w,horizon).close();c.path(ridge,mountain);
    Paint ground;ground.color=Color::argb(0xff080715);c.rect({0,horizon,w,h-horizon},ground);
    c.saveLayer(std::min(1.0f,.65f+f.music.bass*.25f+golpe*.35f),Blend::screen);
    // Golpes engrosa un instante la rejilla (×2,5); Graves, despacio (×1,6).
    Paint grid;grid.color=Color{.55f,.2f,1,1};grid.strokeWidth=1+golpe*1.5f+graves*.6f;
    // Camino: Curvas hace serpentear la carretera; Olas hace ondular el suelo.
    const float curve=g.camino.weight(1),waves=g.camino.weight(2);
    const float bend=std::sin(road*1.9f)*w*.32f*curve;
    for(int i=-10;i<=10;i++){Path p;p.moveTo(w*.5f+i*5,horizon);
      if(curve>.001f)p.quadraticTo(w*.5f+i*(5+w*.22f)*.5f+bend,(horizon+h)*.5f,w*.5f+i*w*.22f,h);
      else p.lineTo(w*.5f+i*w*.22f,h);
      c.path(p,grid);}
    // Altura de una ola en x para la línea i a profundidad t.
    auto swell=[&](float x,int i,float t){
      return t*t*(h-horizon)*.09f*waves*(.5f+.5f*std::sin(x/w*13.2f+float(i)*1.3f+road*4.0f));
    };
    for(int i=0;i<18;i++){float t=std::fmod(i/18.f+road,1.f);float y=horizon+t*t*(h-horizon);Path p;
      if(waves>.001f){
        for(int k=0;k<=24;k++){const float x=w*float(k)/24.0f;
          if(k==0)p.moveTo(x,y-swell(x,i,t));else p.lineTo(x,y-swell(x,i,t));}
      }else p.moveTo(0,y).lineTo(w,y);
      c.path(p,grid);}
    c.restore();
    if(agudos>.001f){
      // Agudos: chispas que titilan en los cruces de la rejilla.
      std::vector<Vec2> sparks;sparks.reserve(96);
      const uint32_t beat=uint32_t(std::fmod(clock*12.0,1.0e6));
      for(int j=0;j<18;j++){float t=std::fmod(j/18.f+road,1.f);float y=horizon+t*t*(h-horizon);
        const float u=(y-horizon)/(h-horizon);
        // Cerca del horizonte las líneas se apiñan: allí saltan menos chispas.
        for(int i=-10;i<=10;i++){
          if(hashU(uint32_t(j*21+i+10)*2654435761u^beat*0x9e3779b9u)>.25f+.45f*u)continue;
          const float x0=w*.5f+i*5,x2=w*.5f+i*w*.22f,x1=w*.5f+i*(5+w*.22f)*.5f+bend;
          const float x=(1-u)*(1-u)*x0+2*u*(1-u)*x1+u*u*x2;
          sparks.push_back({x,y-swell(x,j,t)});
        }
      }
      Paint sp;sp.blend=Blend::plus;sp.color=Color{1,.5f,.9f,std::min(1.0f,agudos*.3f*f.glow)};
      c.points(sparks,(1.8f+agudos*2.0f)*2.2f,sp);
      sp.color=Color{1,.82f,.97f,std::min(1.0f,agudos)};
      c.points(sparks,1.8f+agudos*2.0f,sp);
    }
    // Graves hace crecer el resplandor del horizonte; Golpes lo enciende.
    Paint glow=Paint::radial({w*.5f,horizon},w*.6f*(1+graves*.3f),{Color{1,.12f,.48f,std::min(1.0f,.22f+graves*.3f+golpe*.35f)},Color{1,0,.4f,0}});glow.blend=Blend::screen;
    c.rect({0,horizon-w*.2f,w,w*.4f},glow);
    const float fog=std::clamp(g.bruma,0.0f,1.0f);
    if(fog>.001f){
      // Bruma: niebla de neón posada sobre el horizonte.
      Paint mist=Paint::linear({0,horizon-h*.2f},{0,horizon+h*.3f},
        {Color{1,.3f,.62f,0},Color{1,.32f,.6f,.5f*fog},Color{.6f,.2f,.9f,.2f*fog},Color{.4f,.1f,.7f,0}},{0,.42f,.7f,1});
      mist.blend=Blend::screen;
      c.rect({0,horizon-h*.2f,w,h*.5f},mist);
    }
  }
};

class Visual final : public Scene {
  static constexpr int kMaxBins = 17;
  static constexpr int kSlots = 420;
  static constexpr int kActive = 480;
  struct Ball { double t0; uint32_t path; int bin, slot; uint8_t color; bool landed; };
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  // La simulación avanza en pasos fijos de 1/120 s contados con enteros:
  // nacimientos, aterrizajes y capas de color caen en el mismo paso a 30 y a
  // 60 FPS. El reloj continuo sólo sitúa las bolas en el dibujo.
  static constexpr double kTick = 1.0 / 120.0;
  static constexpr int kLayerTicks = 300;  // una capa de color cada 2,5 s
  double clock = 0, emitted = 0, drainStart = -100;
  int64_t ticks = 0;
  int colorTicks = 0;
  int rowsUsed = 0, layer = 0, burst = 0;
  // Golpes: tiempo desde el último golpe y su fuerza (la ola de los clavos).
  double beatAge = 100;
  float beatPower = 0;
  uint32_t seedBase = 1, born = 0;
  std::vector<Ball> balls;
  std::array<int, kMaxBins> count{}, drainCount{};
  std::array<std::array<uint8_t, kSlots>, kMaxBins> colorOf{}, drainColor{};

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

  static constexpr double kDrop = 0.14, kHop = 0.085, kFall = 0.32;
  // Una bola que ya descansa sigue un rato en la lista: su estela se recoge.
  static constexpr double kTrailMax = 0.6;

  int binOf(uint32_t path, int rows) const {
    int j = 0;
    for (int r = 0; r < rows; r++) j += int((path >> r) & 1u);
    return j;
  }

  // Camino de la bola número [serial]: un bit por fila (izquierda o derecha).
  // Es una fórmula de la semilla, sin Random fuera de reset.
  uint32_t pathOf(uint32_t serial) const {
    uint32_t x = seedBase ^ (serial * 0x9E3779B9u);
    x ^= x >> 16;
    x *= 0x7feb352du;
    x ^= x >> 15;
    x *= 0x846ca68bu;
    x ^= x >> 16;
    return x;
  }

  // Azar fijo para los centelleos: fórmula de un número, sin Random.
  static float sparkleOf(uint32_t x) {
    x ^= x >> 15;
    x *= 0x2c1b3c6du;
    x ^= x >> 12;
    x *= 0x297a2d39u;
    x ^= x >> 15;
    return float(x & 0xffffu) / 65536.0f;
  }

 public:
  void reset(uint32_t seed) override {
    seedBase = seed ? seed : 1u;
    born = 0;
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    clock = 0;
    ticks = 0;
    emitted = 0;
    drainStart = -100;
    colorTicks = 0;
    rowsUsed = 0;
    layer = 0;
    burst = 0;
    beatAge = 100;
    beatPower = 0;
    balls.clear();
    balls.reserve(kActive);
    count.fill(0);
    drainCount.fill(0);
  }

  void update(const Frame& f) override {
    auto m = modifiers(f);
    auto g = glide(f);
    float dt = float(f.delta);
    const Music& mu = f.music;
    bass = follow(bass, mu.bass, 22.0f, 4.5f, dt);
    body = follow(body, mu.body, 12.0f, 3.0f, dt);
    spark = follow(spark, mu.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, mu.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, mu.active ? std::pow(std::clamp(mu.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : mu.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : mu.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : mu.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((mu.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, mu.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    bool beat = hit > kick + 0.2f;
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));

    int rows = std::clamp(m.filas, 4, kMaxBins - 1);
    if (rows != rowsUsed) {
      rowsUsed = rows;
      balls.clear();
      count.fill(0);
      drainCount.fill(0);
    }
    clock += f.delta * f.speed;
    beatAge += f.delta;
    // Un golpe empieza una capa de color nueva y suelta una ráfaga.
    if (beat) {
      layer++;
      colorTicks = 0;
      burst += 6 + int(8.0f * hit);
      // Golpes: la ráfaga es mucho mayor (sólo hay golpes con música).
      burst += int(std::lround(14.0f * hit * std::min(f.intensity, 2.0f) * g.pulso.weight(0)));
      beatAge = 0;
      beatPower = hit;
    }
    const double rate = 16.0 * double(m.caudal) * (1.0 + 1.5 * double(drive));
    const double entry = kDrop + double(rows) * kHop;
    // Capacidad real de una casilla según el tamaño de la pantalla.
    float px = std::min(f.width, f.height) / 400.0f;
    float binW = f.width * 0.92f / float(rows + 1);
    float ballR = std::min(binW * 0.16f, 5.5f * px);
    int perRow = std::max(1, int(binW * 0.9f / (2.0f * ballR)));
    int capacity = std::min(kSlots, perRow * int((f.height * (0.965f - 0.55f)) / (1.85f * ballR)));

    const int64_t target = int64_t(std::floor(clock / kTick + 1e-6));
    // Tras un salto largo no se pone al día bola a bola.
    if (target - ticks > 240) ticks = target - 240;
    while (ticks < target) {
      ticks++;
      const double now = double(ticks) * kTick;
      // Color por capas: cambia cada 2,5 s (o con un golpe, arriba).
      if (++colorTicks >= kLayerTicks) {
        colorTicks = 0;
        layer++;
      }
      // Nacimientos en su instante exacto dentro del paso.
      const double before = emitted;
      emitted += kTick * rate;
      for (double k = std::floor(before) + 1.0; k <= emitted + 1e-9; k += 1.0) {
        if (int(balls.size()) >= kActive) break;
        balls.push_back({now - (emitted - k) / rate, pathOf(born++), 0, 0, uint8_t(layer % 6), false});
      }
      // Al entrar en su casilla la bola reserva su hueco del montón.
      for (auto& b : balls) {
        if (b.landed || now - b.t0 < entry) continue;
        double when = b.t0 + entry;
        b.bin = binOf(b.path, rows);
        if (count[size_t(b.bin)] >= capacity) {
          // Casilla llena: el suelo se abre y el montón cae.
          drainCount = count;
          drainColor = colorOf;
          drainStart = when;
          count.fill(0);
        }
        b.slot = count[size_t(b.bin)]++;
        colorOf[size_t(b.bin)][size_t(b.slot)] = b.color;
        b.landed = true;
      }
    }
    // Las que ya descansan en el montón (y recogieron su estela) se van.
    const double now = double(ticks) * kTick;
    balls.erase(std::remove_if(balls.begin(), balls.end(),
                               [&](const Ball& b) { return b.landed && now - b.t0 > entry + kFall + kTrailMax; }),
                balls.end());
    // Ráfaga del golpe: bolas que ya van en camino, en orden de salida.
    if (burst > 0) {
      // Una ráfaga grande (Golpes) sale más apretada, sin aparecer a media altura.
      const double gap = 0.02 * std::min(1.0, 14.0 / double(burst));
      while (burst > 0 && int(balls.size()) < kActive) {
        balls.push_back({clock - gap * double(burst), pathOf(born++), 0, 0, uint8_t(layer % 6), false});
        burst--;
      }
      burst = 0;
      std::stable_sort(balls.begin(), balls.end(), [](const Ball& a, const Ball& b) { return a.t0 < b.t0; });
    }
  }

  void render(const Frame& f, Canvas& c) const override {
    auto m = modifiers(f);
    auto g = glide(f);
    float amp = f.intensity;
    const Color& bg = f.colors[0];
    c.rect({0, 0, f.width, f.height}, Paint::linear({0, 0}, {0, f.height},
                                                   {Color{std::min(1.0f, bg.r + 0.05f), std::min(1.0f, bg.g + 0.035f), std::min(1.0f, bg.b + 0.06f), 1.0f},
                                                    Color{bg.r, bg.g, bg.b, 1.0f}}));
    int rows = rowsUsed;
    if (rows <= 0) return;
    int bins = rows + 1;
    float px = std::min(f.width, f.height) / 400.0f;
    float binW = f.width * 0.92f / float(bins);
    float cx = f.width * 0.5f;
    float pegTop = f.height * 0.13f, pegBottom = f.height * 0.5f;
    float dy = (pegBottom - pegTop) / float(rows);
    float binTop = f.height * 0.55f, binBottom = f.height * 0.965f;
    float ballR = std::min(binW * 0.16f, 5.5f * px);
    int perRow = std::max(1, int(binW * 0.9f / (2.0f * ballR)));
    // Tiempo de la simulación: decide qué ya pasó; el reloj continuo, dónde se ve.
    const double simNow = double(ticks) * kTick;
    std::array<Color, 6> layers = {f.colors[1], f.colors[2], f.colors[3], Color{1.0f, 0.35f, 0.55f, 1.0f},
                                   Color{1.0f, 0.97f, 0.88f, 1.0f}, Color{1.0f, 0.55f, 0.1f, 1.0f}};
    auto ballColor = [&](uint8_t layerIdx) { return layers[size_t(layerIdx % 6)]; };
    auto slotPos = [&](int bin, int slot) {
      int row = slot / perRow, col = slot % perRow;
      float left = cx + (float(bin) - float(bins) * 0.5f) * binW + (binW - float(perRow) * 2.0f * ballR) * 0.5f;
      float x = left + ballR + float(col) * 2.0f * ballR + ((row & 1) ? ballR * 0.5f : 0.0f);
      return Vec2{std::min(x, cx + (float(bin) - float(bins) * 0.5f + 1.0f) * binW - ballR), binBottom - ballR - float(row) * 1.8f * ballR};
    };
    double entry = kDrop + double(rows) * kHop;
    // Dónde está una bola a cualquier edad: la usan la bola y su estela.
    auto ballAt = [&](const Ball& b, double age) {
      Vec2 p;
      if (age < kDrop) {
        float t = float(age / kDrop);
        p = {cx, pegTop - dy * 1.4f + dy * 1.4f * t * t - ballR * 2.0f};
      } else if (age < entry) {
        double u = (age - kDrop) / kHop;
        int level = std::min(int(u), rows - 1);
        float t = float(u - double(level));
        int j0 = 0;
        for (int r = 0; r < level; r++) j0 += int((b.path >> r) & 1u);
        int j1 = j0 + int((b.path >> level) & 1u);
        float x0 = cx + (float(j0) - float(level) * 0.5f) * binW;
        float x1 = cx + (float(j1) - float(level + 1) * 0.5f) * binW;
        float y0 = pegTop + float(level) * dy - ballR * 2.0f;
        float y1 = y0 + dy;
        p = {x0 + (x1 - x0) * t, y0 + (y1 - y0) * t * t - dy * 0.55f * std::sin(t * 3.14159265f)};
      } else {
        float t = std::min(float((age - entry) / kFall), 1.0f);
        int bin = binOf(b.path, rows);
        float x0 = cx + (float(bin) - float(rows) * 0.5f) * binW;
        Vec2 target = b.landed ? slotPos(b.bin, b.slot) : Vec2{x0, binBottom - ballR};
        float y0 = pegTop + float(rows) * dy - ballR * 2.0f;
        p = {x0 + (target.x - x0) * t, y0 + (target.y - y0) * t * t};
      }
      return p;
    };

    // Pulso: cada opción mueve una parte distinta (sin música, todo 0).
    const float golpe = g.pulso.weight(0), graves = g.pulso.weight(1), agudos = g.pulso.weight(2);
    const float swell = std::min(bass * amp, 1.2f) * graves;
    const float glint = std::min(spark * amp, 1.2f) * agudos;
    const float punch = std::min(kick * amp, 1.2f) * golpe;
    // Golpes / Graves: resplandor local sobre el tablero de clavos y sobre el montón.
    if (punch + swell > 0.01f) {
      const float pegsR = (pegBottom - pegTop) * 0.95f;
      Paint boardGlow = Paint::radial({cx, (pegTop + pegBottom) * 0.5f}, pegsR,
                                      {f.colors[2].opacity(std::clamp((0.35f * punch + 0.15f * swell) * f.glow, 0.0f, 1.0f)),
                                       f.colors[2].opacity(0.0f)});
      boardGlow.blend = Blend::plus;
      c.circle({cx, (pegTop + pegBottom) * 0.5f}, pegsR, boardGlow);
      const float pileR = float(bins) * binW * 0.5f;
      Paint pileGlow = Paint::radial({cx, binBottom}, pileR,
                                     {f.colors[1].opacity(std::clamp((0.3f * punch + 0.25f * swell) * f.glow, 0.0f, 1.0f)),
                                      f.colors[1].opacity(0.0f)});
      pileGlow.blend = Blend::plus;
      c.circle({cx, binBottom}, pileR, pileGlow);
    }
    // Casillas: paredes finas y suelo.
    Path walls;
    for (int b = 0; b <= bins; b++) {
      float x = cx + (float(b) - float(bins) * 0.5f) * binW;
      walls.moveTo(x, binTop).lineTo(x, binBottom);
    }
    walls.moveTo(cx - float(bins) * 0.5f * binW, binBottom).lineTo(cx + float(bins) * 0.5f * binW, binBottom);
    Paint wp;
    wp.strokeWidth = 1.4f * px * (1.0f + 0.5f * swell);
    wp.color = Color{0.75f, 0.72f, 0.78f, std::min(1.0f, 0.35f * (1.0f + 0.8f * swell))};
    c.path(walls, wp);
    // Clavos.
    std::vector<Vec2> pegs;
    pegs.reserve(size_t((rows + 1) * (rows + 2) / 2));
    for (int r = 0; r < rows; r++) {
      for (int k = 0; k <= r; k++) pegs.push_back({cx + (float(k) - float(r) * 0.5f) * binW, pegTop + float(r) * dy});
    }
    Paint pegGlow;
    pegGlow.blend = Blend::plus;
    // Graves: los clavos brillan más y su halo crece con los graves.
    pegGlow.color = f.colors[2].opacity(std::clamp((0.1f + 0.25f * bass + 0.2f * kick + 0.8f * bass * graves) * f.glow * amp, 0.0f, 1.0f));
    c.points(pegs, 5.5f * px * (1.0f + 0.5f * swell), pegGlow);
    Paint pegDot;
    pegDot.color = Color{0.86f, 0.84f, 0.9f, 1.0f};
    c.points(pegs, 2.2f * px, pegDot);
    // Golpes: una ola de luz baja fila a fila por los clavos con cada golpe.
    const float ripple = std::min(beatPower * amp, 1.2f) * golpe;
    if (ripple > 0.01f && beatAge < 1.2) {
      Paint flashPeg;
      flashPeg.blend = Blend::plus;
      std::vector<Vec2> rowPegs;
      rowPegs.reserve(size_t(rows));
      for (int r = 0; r < rows; r++) {
        const float local = float(beatAge) - 0.32f * float(r) / float(rows);
        if (local < 0.0f) continue;
        const float lightUp = std::exp(-local * 6.0f) * ripple;
        if (lightUp < 0.01f) continue;
        rowPegs.clear();
        for (int k = 0; k <= r; k++) rowPegs.push_back({cx + (float(k) - float(r) * 0.5f) * binW, pegTop + float(r) * dy});
        flashPeg.color = f.colors[3].opacity(std::clamp(1.1f * lightUp, 0.0f, 1.0f));
        c.points(rowPegs, 5.0f * px * (1.0f + 0.5f * lightUp), flashPeg);
      }
    }
    // Agudos: algunos clavos centellean.
    if (glint > 0.01f) {
      const uint32_t pegTick = uint32_t(int64_t(std::floor(clock * 9.0)) & 0xffffff);
      std::vector<Vec2> twinkle;
      twinkle.reserve(pegs.size());
      for (size_t i = 0; i < pegs.size(); i++)
        if (sparkleOf(uint32_t(i) * 747796405u + pegTick * 2891336453u) > 0.5f) twinkle.push_back(pegs[i]);
      Paint tw;
      tw.blend = Blend::plus;
      tw.color = Color{1.0f, 0.97f, 0.9f, std::clamp(0.8f * glint, 0.0f, 1.0f)};
      c.points(twinkle, 3.6f * px, tw);
    }

    // Estela: el camino reciente de cada bola, en muestras fijas de su propio
    // recorrido (no tiemblan) y en tres tramos que se apagan hacia atrás.
    const float trail = std::clamp(g.estela, 0.0f, 1.0f);
    if (trail > 0.02f) {
      std::array<Path, 18> streaks;  // 6 colores × 3 tramos
      const double h = kHop * 0.25;
      const int window = std::max(1, int(std::ceil(kTrailMax * double(trail) / h)));
      for (const auto& b : balls) {
        const double age = std::max(0.0, clock - b.t0);
        const int qHi = int(std::floor(age / h + 1e-6));
        const int qLo = std::max(0, qHi - window);
        if (qHi <= qLo) continue;
        Vec2 prev = ballAt(b, age);
        int open = -1;
        for (int q = qHi; q >= qLo; q--) {
          const int part = std::min(2, (qHi - q) * 3 / window);
          Path& path = streaks[size_t(b.color % 6) * 3 + size_t(part)];
          if (part != open) {
            path.moveTo(prev.x, prev.y);
            open = part;
          }
          const Vec2 p = ballAt(b, double(q) * h);
          path.lineTo(p.x, p.y);
          prev = p;
        }
      }
      const float strength = (0.3f + 0.4f * trail) * std::min(1.0f, 0.6f + 0.4f * f.glow);
      for (size_t i = 0; i < streaks.size(); i++) {
        if (streaks[i].data().empty()) continue;
        const float part = float(i % 3);
        Paint sp;
        sp.strokeWidth = ballR * (0.95f - 0.2f * part);
        sp.strokeCap = 1;
        sp.strokeJoin = 1;
        sp.color = ballColor(uint8_t(i / 3)).opacity(std::clamp(strength * (1.0f - 0.32f * part), 0.0f, 1.0f));
        c.path(streaks[i], sp);
      }
    }

    // Montón actual y el que se vacía.
    std::array<std::vector<Vec2>, 8> groups;
    std::array<Color, 8> groupColor{};
    for (auto& gr : groups) gr.reserve(512);
    auto add = [&](Vec2 p, Color col) {
      // Agrupa por color cuantizado: hasta 8 grupos por frame.
      for (int i = 0; i < 8; i++) {
        if (groups[size_t(i)].empty()) {
          groupColor[size_t(i)] = col;
          groups[size_t(i)].push_back(p);
          return;
        }
        const Color& gc = groupColor[size_t(i)];
        if (std::fabs(gc.r - col.r) + std::fabs(gc.g - col.g) + std::fabs(gc.b - col.b) < 0.08f) {
          groups[size_t(i)].push_back(p);
          return;
        }
      }
      groups[7].push_back(p);
    };
    for (int b = 0; b < bins; b++) {
      for (int s = 0; s < count[size_t(b)]; s++) add(slotPos(b, s), ballColor(colorOf[size_t(b)][size_t(s)]));
    }
    if (simNow - drainStart < 1.2) {
      float drainT = float(std::max(0.0, clock - drainStart));
      float drop = 0.5f * 2600.0f * px * drainT * drainT;
      for (int b = 0; b < bins; b++) {
        for (int s = 0; s < drainCount[size_t(b)]; s++) {
          Vec2 p = slotPos(b, s);
          p.y += drop * (1.0f + 0.002f * float(s));
          if (p.y < f.height + ballR) add(p, ballColor(drainColor[size_t(b)][size_t(s)]));
        }
      }
    }
    // Bolas en el aire (las que ya descansan se dibujan en el montón).
    std::vector<Vec2> flying;
    flying.reserve(balls.size());
    for (const auto& b : balls) {
      if (b.landed && simNow - b.t0 > entry + kFall) continue;
      Vec2 p = ballAt(b, std::max(0.0, clock - b.t0));
      add(p, ballColor(b.color));
      flying.push_back(p);
    }
    float lit = (0.85f + 0.2f * bass + 0.25f * kick) * amp;
    for (int i = 0; i < 8; i++) {
      if (groups[size_t(i)].empty()) continue;
      const Color& col = groupColor[size_t(i)];
      Paint p;
      p.color = Color{std::min(1.0f, col.r * lit), std::min(1.0f, col.g * lit), std::min(1.0f, col.b * lit), 1.0f};
      // Graves: las bolas se hinchan con los graves.
      c.points(groups[size_t(i)], ballR * 0.92f * (1.0f + 0.12f * swell + 0.15f * punch), p);
    }
    Paint shine;
    shine.blend = Blend::plus;
    shine.color = Color{1.0f, 0.95f, 0.85f, std::clamp(0.35f * amp + 0.5f * punch, 0.0f, 1.0f)};
    c.points(flying, ballR * 0.45f * (1.0f + 0.4f * punch), shine);
    // Agudos: las bolas en el aire centellean.
    if (glint > 0.01f) {
      const uint32_t tick = uint32_t(int64_t(std::floor(clock * 12.0)) & 0xffffff);
      std::vector<Vec2> sparkles;
      sparkles.reserve(flying.size());
      size_t k = 0;
      for (const auto& b : balls) {
        if (b.landed && simNow - b.t0 > entry + kFall) continue;
        if (sparkleOf(b.path ^ (tick * 2654435761u)) > 0.4f) sparkles.push_back(flying[k]);
        k++;
      }
      std::vector<Vec2> pile;
      for (int bi = 0; bi < bins; bi++)
        for (int s = 0; s < count[size_t(bi)]; s++)
          if (sparkleOf(uint32_t(bi * kSlots + s) * 2246822519u + tick * 3266489917u) > 0.8f) pile.push_back(slotPos(bi, s));
      Paint pp;
      pp.blend = Blend::plus;
      pp.color = Color{1.0f, 1.0f, 0.95f, std::clamp(0.7f * glint, 0.0f, 1.0f)};
      c.points(pile, ballR * 0.6f, pp);
      Paint sp;
      sp.blend = Blend::plus;
      sp.color = Color{1.0f, 1.0f, 0.95f, std::clamp(0.9f * glint, 0.0f, 1.0f)};
      c.points(sparkles, ballR * 0.75f, sp);
    }
    // Curva teórica: la campana que el montón va dibujando.
    if (m.curva) {
      int total = 0;
      for (int b = 0; b < bins; b++) total += count[size_t(b)];
      if (total > bins) {
        Path curve;
        double mean = double(rows) * 0.5, var = double(rows) * 0.25;
        for (int i = 0; i <= 80; i++) {
          double xb = double(i) / 80.0 * double(bins) - 0.5;
          double expect = double(total) * std::exp(-(xb - mean) * (xb - mean) / (2.0 * var)) / std::sqrt(6.283185307 * var);
          float hgt = float(expect) / float(perRow) * 1.8f * ballR;
          float x = cx + (float(xb) + 0.5f - float(bins) * 0.5f) * binW;
          float y = binBottom - hgt;
          if (i == 0) curve.moveTo(x, y); else curve.lineTo(x, y);
        }
        Paint cp;
        cp.blend = Blend::plus;
        cp.strokeWidth = 2.0f * px * (1.0f + 0.5f * swell);
        cp.strokeJoin = 1;
        cp.color = Color{1.0f, 1.0f, 1.0f, std::clamp((0.35f + 0.3f * kick) * amp, 0.0f, 1.0f)};
        c.path(curve, cp);
      }
    }
    if (flash > 0.01f) {
      Paint fl;
      fl.blend = Blend::plus;
      fl.color = f.colors[2].opacity(std::clamp(flash * 0.05f * amp, 0.0f, 1.0f));
      c.rect({0, 0, f.width, f.height}, fl);
    }
  }
};

class Visual final : public Scene {
  static constexpr int kMaxBins = 17;
  static constexpr int kSlots = 420;
  static constexpr int kActive = 480;
  struct Ball { double t0; uint32_t path; int bin, slot; uint8_t color; bool landed; };
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  // La simulación avanza en pasos fijos de 1/120 s contados con enteros:
  // nacimientos, aterrizajes y capas de color caen en el mismo paso a 30 y a
  // 60 FPS. El reloj continuo sólo sitúa las bolas en el dibujo.
  static constexpr double kTick = 1.0 / 120.0;
  static constexpr int kLayerTicks = 300;  // una capa de color cada 2,5 s
  double clock = 0, emitted = 0, drainStart = -100;
  int64_t ticks = 0;
  int colorTicks = 0;
  int rowsUsed = 0, layer = 0, burst = 0;
  // Golpes: tiempo desde el último golpe y su fuerza (la ola de los clavos).
  double beatAge = 100;
  float beatPower = 0;
  uint32_t seedBase = 1, born = 0;
  std::vector<Ball> balls;
  std::array<int, kMaxBins> count{}, drainCount{};
  std::array<std::array<uint8_t, kSlots>, kMaxBins> colorOf{}, drainColor{};

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

  static constexpr double kDrop = 0.14, kHop = 0.085, kFall = 0.32;
  // Una bola que ya descansa sigue un rato en la lista: su estela se recoge.
  static constexpr double kTrailMax = 0.6;

  int binOf(uint32_t path, int rows) const {
    int j = 0;
    for (int r = 0; r < rows; r++) j += int((path >> r) & 1u);
    return j;
  }

  // Camino de la bola número [serial]: un bit por fila (izquierda o derecha).
  // Es una fórmula de la semilla, sin Random fuera de reset.
  uint32_t pathOf(uint32_t serial) const {
    uint32_t x = seedBase ^ (serial * 0x9E3779B9u);
    x ^= x >> 16;
    x *= 0x7feb352du;
    x ^= x >> 15;
    x *= 0x846ca68bu;
    x ^= x >> 16;
    return x;
  }

  // Azar fijo para los centelleos: fórmula de un número, sin Random.
  static float sparkleOf(uint32_t x) {
    x ^= x >> 15;
    x *= 0x2c1b3c6du;
    x ^= x >> 12;
    x *= 0x297a2d39u;
    x ^= x >> 15;
    return float(x & 0xffffu) / 65536.0f;
  }

 public:
  void reset(uint32_t seed) override {
    seedBase = seed ? seed : 1u;
    born = 0;
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    clock = 0;
    ticks = 0;
    emitted = 0;
    drainStart = -100;
    colorTicks = 0;
    rowsUsed = 0;
    layer = 0;
    burst = 0;
    beatAge = 100;
    beatPower = 0;
    balls.clear();
    balls.reserve(kActive);
    count.fill(0);
    drainCount.fill(0);
  }

  void update(const Frame& f) override {
    auto m = modifiers(f);
    auto g = glide(f);
    float dt = float(f.delta);
    const Music& mu = f.music;
    bass = follow(bass, mu.bass, 22.0f, 4.5f, dt);
    body = follow(body, mu.body, 12.0f, 3.0f, dt);
    spark = follow(spark, mu.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, mu.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, mu.active ? std::pow(std::clamp(mu.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : mu.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : mu.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : mu.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((mu.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, mu.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    bool beat = hit > kick + 0.2f;
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));

    int rows = std::clamp(m.filas, 4, kMaxBins - 1);
    if (rows != rowsUsed) {
      rowsUsed = rows;
      balls.clear();
      count.fill(0);
      drainCount.fill(0);
    }
    clock += f.delta * f.speed;
    beatAge += f.delta;
    // Un golpe empieza una capa de color nueva y suelta una ráfaga.
    if (beat) {
      layer++;
      colorTicks = 0;
      burst += 6 + int(8.0f * hit);
      // Golpes: la ráfaga es mucho mayor (sólo hay golpes con música).
      burst += int(std::lround(14.0f * hit * std::min(f.intensity, 2.0f) * g.pulso.weight(0)));
      beatAge = 0;
      beatPower = hit;
    }
    const double rate = 16.0 * double(m.caudal) * (1.0 + 1.5 * double(drive));
    const double entry = kDrop + double(rows) * kHop;
    // Capacidad real de una casilla según el tamaño de la pantalla.
    float px = std::min(f.width, f.height) / 400.0f;
    float binW = f.width * 0.92f / float(rows + 1);
    float ballR = std::min(binW * 0.16f, 5.5f * px);
    int perRow = std::max(1, int(binW * 0.9f / (2.0f * ballR)));
    int capacity = std::min(kSlots, perRow * int((f.height * (0.965f - 0.55f)) / (1.85f * ballR)));

    const int64_t target = int64_t(std::floor(clock / kTick + 1e-6));
    // Tras un salto largo no se pone al día bola a bola.
    if (target - ticks > 240) ticks = target - 240;
    while (ticks < target) {
      ticks++;
      const double now = double(ticks) * kTick;
      // Color por capas: cambia cada 2,5 s (o con un golpe, arriba).
      if (++colorTicks >= kLayerTicks) {
        colorTicks = 0;
        layer++;
      }
      // Nacimientos en su instante exacto dentro del paso.
      const double before = emitted;
      emitted += kTick * rate;
      for (double k = std::floor(before) + 1.0; k <= emitted + 1e-9; k += 1.0) {
        if (int(balls.size()) >= kActive) break;
        balls.push_back({now - (emitted - k) / rate, pathOf(born++), 0, 0, uint8_t(layer % 6), false});
      }
      // Al entrar en su casilla la bola reserva su hueco del montón.
      for (auto& b : balls) {
        if (b.landed || now - b.t0 < entry) continue;
        double when = b.t0 + entry;
        b.bin = binOf(b.path, rows);
        if (count[size_t(b.bin)] >= capacity) {
          // Casilla llena: el suelo se abre y el montón cae.
          drainCount = count;
          drainColor = colorOf;
          drainStart = when;
          count.fill(0);
        }
        b.slot = count[size_t(b.bin)]++;
        colorOf[size_t(b.bin)][size_t(b.slot)] = b.color;
        b.landed = true;
      }
    }
    // Las que ya descansan en el montón (y recogieron su estela) se van.
    const double now = double(ticks) * kTick;
    balls.erase(std::remove_if(balls.begin(), balls.end(),
                               [&](const Ball& b) { return b.landed && now - b.t0 > entry + kFall + kTrailMax; }),
                balls.end());
    // Ráfaga del golpe: bolas que ya van en camino, en orden de salida.
    if (burst > 0) {
      // Una ráfaga grande (Golpes) sale más apretada, sin aparecer a media altura.
      const double gap = 0.02 * std::min(1.0, 14.0 / double(burst));
      while (burst > 0 && int(balls.size()) < kActive) {
        balls.push_back({clock - gap * double(burst), pathOf(born++), 0, 0, uint8_t(layer % 6), false});
        burst--;
      }
      burst = 0;
      std::stable_sort(balls.begin(), balls.end(), [](const Ball& a, const Ball& b) { return a.t0 < b.t0; });
    }
  }

  void render(const Frame& f, Canvas& c) const override {
    auto m = modifiers(f);
    auto g = glide(f);
    float amp = f.intensity;
    int rows = rowsUsed;
    if (rows <= 0) return;
    int bins = rows + 1;
    float px = std::min(f.width, f.height) / 400.0f;
    float binW = f.width * 0.92f / float(bins);
    float cx = f.width * 0.5f;
    float pegTop = f.height * 0.13f, pegBottom = f.height * 0.5f;
    float dy = (pegBottom - pegTop) / float(rows);
    float binTop = f.height * 0.55f, binBottom = f.height * 0.965f;
    float ballR = std::min(binW * 0.16f, 5.5f * px);
    int perRow = std::max(1, int(binW * 0.9f / (2.0f * ballR)));
    // Tiempo de la simulación: decide qué ya pasó; el reloj continuo, dónde se ve.
    const double simNow = double(ticks) * kTick;
    std::array<Color, 6> layers = {f.colors[1], f.colors[2], f.colors[3], Color{1.0f, 0.35f, 0.55f, 1.0f},
                                   Color{1.0f, 0.97f, 0.88f, 1.0f}, Color{1.0f, 0.55f, 0.1f, 1.0f}};
    auto ballColor = [&](uint8_t layerIdx) { return layers[size_t(layerIdx % 6)]; };
    auto slotPos = [&](int bin, int slot) {
      int row = slot / perRow, col = slot % perRow;
      float left = cx + (float(bin) - float(bins) * 0.5f) * binW + (binW - float(perRow) * 2.0f * ballR) * 0.5f;
      float x = left + ballR + float(col) * 2.0f * ballR + ((row & 1) ? ballR * 0.5f : 0.0f);
      return Vec2{std::min(x, cx + (float(bin) - float(bins) * 0.5f + 1.0f) * binW - ballR), binBottom - ballR - float(row) * 1.8f * ballR};
    };
    double entry = kDrop + double(rows) * kHop;
    // Dónde está una bola a cualquier edad: la usan la bola y su estela.
    auto ballAt = [&](const Ball& b, double age) {
      Vec2 p;
      if (age < kDrop) {
        float t = float(age / kDrop);
        p = {cx, pegTop - dy * 1.4f + dy * 1.4f * t * t - ballR * 2.0f};
      } else if (age < entry) {
        double u = (age - kDrop) / kHop;
        int level = std::min(int(u), rows - 1);
        float t = float(u - double(level));
        int j0 = 0;
        for (int r = 0; r < level; r++) j0 += int((b.path >> r) & 1u);
        int j1 = j0 + int((b.path >> level) & 1u);
        float x0 = cx + (float(j0) - float(level) * 0.5f) * binW;
        float x1 = cx + (float(j1) - float(level + 1) * 0.5f) * binW;
        float y0 = pegTop + float(level) * dy - ballR * 2.0f;
        float y1 = y0 + dy;
        p = {x0 + (x1 - x0) * t, y0 + (y1 - y0) * t * t - dy * 0.55f * std::sin(t * 3.14159265f)};
      } else {
        float t = std::min(float((age - entry) / kFall), 1.0f);
        int bin = binOf(b.path, rows);
        float x0 = cx + (float(bin) - float(rows) * 0.5f) * binW;
        Vec2 target = b.landed ? slotPos(b.bin, b.slot) : Vec2{x0, binBottom - ballR};
        float y0 = pegTop + float(rows) * dy - ballR * 2.0f;
        p = {x0 + (target.x - x0) * t, y0 + (target.y - y0) * t * t};
      }
      return p;
    };

    // Pulso: cada opción mueve una parte distinta (sin música, todo 0).
    const float golpe = g.pulso.weight(0), graves = g.pulso.weight(1), agudos = g.pulso.weight(2);
    const float swell = std::min(bass * amp, 1.2f) * graves;
    const float glint = std::min(spark * amp, 1.2f) * agudos;
    const float punch = std::min(kick * amp, 1.2f) * golpe;
    // Golpes / Graves: resplandor local sobre el tablero de clavos y sobre el montón.
    if (punch + swell > 0.01f) {
      const float pegsR = (pegBottom - pegTop) * 0.95f;
      Paint boardGlow = Paint::radial({cx, (pegTop + pegBottom) * 0.5f}, pegsR,
                                      {f.colors[2].opacity(std::clamp((0.35f * punch + 0.15f * swell) * f.glow, 0.0f, 1.0f)),
                                       f.colors[2].opacity(0.0f)});
      boardGlow.blend = Blend::plus;
      c.circle({cx, (pegTop + pegBottom) * 0.5f}, pegsR, boardGlow);
      const float pileR = float(bins) * binW * 0.5f;
      Paint pileGlow = Paint::radial({cx, binBottom}, pileR,
                                     {f.colors[1].opacity(std::clamp((0.3f * punch + 0.25f * swell) * f.glow, 0.0f, 1.0f)),
                                      f.colors[1].opacity(0.0f)});
      pileGlow.blend = Blend::plus;
      c.circle({cx, binBottom}, pileR, pileGlow);
    }
    // Casillas: paredes finas y suelo.
    Path walls;
    for (int b = 0; b <= bins; b++) {
      float x = cx + (float(b) - float(bins) * 0.5f) * binW;
      walls.moveTo(x, binTop).lineTo(x, binBottom);
    }
    walls.moveTo(cx - float(bins) * 0.5f * binW, binBottom).lineTo(cx + float(bins) * 0.5f * binW, binBottom);
    Paint wp;
    wp.strokeWidth = 1.4f * px * (1.0f + 0.5f * swell);
    wp.color = Color{0.75f, 0.72f, 0.78f, std::min(1.0f, 0.35f * (1.0f + 0.8f * swell))};
    c.path(walls, wp);
    // Clavos.
    std::vector<Vec2> pegs;
    pegs.reserve(size_t((rows + 1) * (rows + 2) / 2));
    for (int r = 0; r < rows; r++) {
      for (int k = 0; k <= r; k++) pegs.push_back({cx + (float(k) - float(r) * 0.5f) * binW, pegTop + float(r) * dy});
    }
    Paint pegGlow;
    pegGlow.blend = Blend::plus;
    // Graves: los clavos brillan más y su halo crece con los graves.
    pegGlow.color = f.colors[2].opacity(std::clamp((0.1f + 0.25f * bass + 0.2f * kick + 0.8f * bass * graves) * f.glow * amp, 0.0f, 1.0f));
    c.points(pegs, 5.5f * px * (1.0f + 0.5f * swell), pegGlow);
    Paint pegDot;
    pegDot.color = Color{0.86f, 0.84f, 0.9f, 1.0f};
    c.points(pegs, 2.2f * px, pegDot);
    // Golpes: una ola de luz baja fila a fila por los clavos con cada golpe.
    const float ripple = std::min(beatPower * amp, 1.2f) * golpe;
    if (ripple > 0.01f && beatAge < 1.2) {
      Paint flashPeg;
      flashPeg.blend = Blend::plus;
      std::vector<Vec2> rowPegs;
      rowPegs.reserve(size_t(rows));
      for (int r = 0; r < rows; r++) {
        const float local = float(beatAge) - 0.32f * float(r) / float(rows);
        if (local < 0.0f) continue;
        const float lightUp = std::exp(-local * 6.0f) * ripple;
        if (lightUp < 0.01f) continue;
        rowPegs.clear();
        for (int k = 0; k <= r; k++) rowPegs.push_back({cx + (float(k) - float(r) * 0.5f) * binW, pegTop + float(r) * dy});
        flashPeg.color = f.colors[3].opacity(std::clamp(1.1f * lightUp, 0.0f, 1.0f));
        c.points(rowPegs, 5.0f * px * (1.0f + 0.5f * lightUp), flashPeg);
      }
    }
    // Agudos: algunos clavos centellean.
    if (glint > 0.01f) {
      const uint32_t pegTick = uint32_t(int64_t(std::floor(clock * 9.0)) & 0xffffff);
      std::vector<Vec2> twinkle;
      twinkle.reserve(pegs.size());
      for (size_t i = 0; i < pegs.size(); i++)
        if (sparkleOf(uint32_t(i) * 747796405u + pegTick * 2891336453u) > 0.5f) twinkle.push_back(pegs[i]);
      Paint tw;
      tw.blend = Blend::plus;
      tw.color = Color{1.0f, 0.97f, 0.9f, std::clamp(0.8f * glint, 0.0f, 1.0f)};
      c.points(twinkle, 3.6f * px, tw);
    }

    // Estela: el camino reciente de cada bola, en muestras fijas de su propio
    // recorrido (no tiemblan) y en tres tramos que se apagan hacia atrás.
    const float trail = std::clamp(g.estela, 0.0f, 1.0f);
    if (trail > 0.02f) {
      std::array<Path, 18> streaks;  // 6 colores × 3 tramos
      const double h = kHop * 0.25;
      const int window = std::max(1, int(std::ceil(kTrailMax * double(trail) / h)));
      for (const auto& b : balls) {
        const double age = std::max(0.0, clock - b.t0);
        const int qHi = int(std::floor(age / h + 1e-6));
        const int qLo = std::max(0, qHi - window);
        if (qHi <= qLo) continue;
        Vec2 prev = ballAt(b, age);
        int open = -1;
        for (int q = qHi; q >= qLo; q--) {
          const int part = std::min(2, (qHi - q) * 3 / window);
          Path& path = streaks[size_t(b.color % 6) * 3 + size_t(part)];
          if (part != open) {
            path.moveTo(prev.x, prev.y);
            open = part;
          }
          const Vec2 p = ballAt(b, double(q) * h);
          path.lineTo(p.x, p.y);
          prev = p;
        }
      }
      const float strength = (0.3f + 0.4f * trail) * std::min(1.0f, 0.6f + 0.4f * f.glow);
      for (size_t i = 0; i < streaks.size(); i++) {
        if (streaks[i].data().empty()) continue;
        const float part = float(i % 3);
        Paint sp;
        sp.strokeWidth = ballR * (0.95f - 0.2f * part);
        sp.strokeCap = 1;
        sp.strokeJoin = 1;
        sp.color = ballColor(uint8_t(i / 3)).opacity(std::clamp(strength * (1.0f - 0.32f * part), 0.0f, 1.0f));
        c.path(streaks[i], sp);
      }
    }

    // Montón actual y el que se vacía.
    std::array<std::vector<Vec2>, 8> groups;
    std::array<Color, 8> groupColor{};
    for (auto& gr : groups) gr.reserve(512);
    auto add = [&](Vec2 p, Color col) {
      // Agrupa por color cuantizado: hasta 8 grupos por frame.
      for (int i = 0; i < 8; i++) {
        if (groups[size_t(i)].empty()) {
          groupColor[size_t(i)] = col;
          groups[size_t(i)].push_back(p);
          return;
        }
        const Color& gc = groupColor[size_t(i)];
        if (std::fabs(gc.r - col.r) + std::fabs(gc.g - col.g) + std::fabs(gc.b - col.b) < 0.08f) {
          groups[size_t(i)].push_back(p);
          return;
        }
      }
      groups[7].push_back(p);
    };
    for (int b = 0; b < bins; b++) {
      for (int s = 0; s < count[size_t(b)]; s++) add(slotPos(b, s), ballColor(colorOf[size_t(b)][size_t(s)]));
    }
    if (simNow - drainStart < 1.2) {
      float drainT = float(std::max(0.0, clock - drainStart));
      float drop = 0.5f * 2600.0f * px * drainT * drainT;
      for (int b = 0; b < bins; b++) {
        for (int s = 0; s < drainCount[size_t(b)]; s++) {
          Vec2 p = slotPos(b, s);
          p.y += drop * (1.0f + 0.002f * float(s));
          if (p.y < f.height + ballR) add(p, ballColor(drainColor[size_t(b)][size_t(s)]));
        }
      }
    }
    // Bolas en el aire (las que ya descansan se dibujan en el montón).
    std::vector<Vec2> flying;
    flying.reserve(balls.size());
    for (const auto& b : balls) {
      if (b.landed && simNow - b.t0 > entry + kFall) continue;
      Vec2 p = ballAt(b, std::max(0.0, clock - b.t0));
      add(p, ballColor(b.color));
      flying.push_back(p);
    }
    float lit = (0.85f + 0.2f * bass + 0.25f * kick) * amp;
    for (int i = 0; i < 8; i++) {
      if (groups[size_t(i)].empty()) continue;
      const Color& col = groupColor[size_t(i)];
      Paint p;
      p.color = Color{std::min(1.0f, col.r * lit), std::min(1.0f, col.g * lit), std::min(1.0f, col.b * lit), 1.0f};
      // Graves: las bolas se hinchan con los graves.
      c.points(groups[size_t(i)], ballR * 0.92f * (1.0f + 0.12f * swell + 0.15f * punch), p);
    }
    Paint shine;
    shine.blend = Blend::plus;
    shine.color = Color{1.0f, 0.95f, 0.85f, std::clamp(0.35f * amp + 0.5f * punch, 0.0f, 1.0f)};
    c.points(flying, ballR * 0.45f * (1.0f + 0.4f * punch), shine);
    // Agudos: las bolas en el aire centellean.
    if (glint > 0.01f) {
      const uint32_t tick = uint32_t(int64_t(std::floor(clock * 12.0)) & 0xffffff);
      std::vector<Vec2> sparkles;
      sparkles.reserve(flying.size());
      size_t k = 0;
      for (const auto& b : balls) {
        if (b.landed && simNow - b.t0 > entry + kFall) continue;
        if (sparkleOf(b.path ^ (tick * 2654435761u)) > 0.4f) sparkles.push_back(flying[k]);
        k++;
      }
      std::vector<Vec2> pile;
      for (int bi = 0; bi < bins; bi++)
        for (int s = 0; s < count[size_t(bi)]; s++)
          if (sparkleOf(uint32_t(bi * kSlots + s) * 2246822519u + tick * 3266489917u) > 0.8f) pile.push_back(slotPos(bi, s));
      Paint pp;
      pp.blend = Blend::plus;
      pp.color = Color{1.0f, 1.0f, 0.95f, std::clamp(0.7f * glint, 0.0f, 1.0f)};
      c.points(pile, ballR * 0.6f, pp);
      Paint sp;
      sp.blend = Blend::plus;
      sp.color = Color{1.0f, 1.0f, 0.95f, std::clamp(0.9f * glint, 0.0f, 1.0f)};
      c.points(sparkles, ballR * 0.75f, sp);
    }
    // Curva teórica: la campana que el montón va dibujando.
    if (m.curva) {
      int total = 0;
      for (int b = 0; b < bins; b++) total += count[size_t(b)];
      if (total > bins) {
        Path curve;
        double mean = double(rows) * 0.5, var = double(rows) * 0.25;
        for (int i = 0; i <= 80; i++) {
          double xb = double(i) / 80.0 * double(bins) - 0.5;
          double expect = double(total) * std::exp(-(xb - mean) * (xb - mean) / (2.0 * var)) / std::sqrt(6.283185307 * var);
          float hgt = float(expect) / float(perRow) * 1.8f * ballR;
          float x = cx + (float(xb) + 0.5f - float(bins) * 0.5f) * binW;
          float y = binBottom - hgt;
          if (i == 0) curve.moveTo(x, y); else curve.lineTo(x, y);
        }
        Paint cp;
        cp.blend = Blend::plus;
        cp.strokeWidth = 2.0f * px * (1.0f + 0.5f * swell);
        cp.strokeJoin = 1;
        cp.color = Color{1.0f, 1.0f, 1.0f, std::clamp((0.35f + 0.3f * kick) * amp, 0.0f, 1.0f)};
        c.path(curve, cp);
      }
    }
  }
};

class Visual final : public Scene {
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  // Relojes en doble precisión: la escena sin música es idéntica a 30 y 60 FPS.
  double clock = 0, rows = 0;

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    clock = rng.unit() * 30.0;
    rows = rng.unit() * 400.0;
  }

  void update(const Frame& f) override {
    float dt = float(f.delta);
    const Music& mu = f.music;
    bass = follow(bass, mu.bass, 22.0f, 4.5f, dt);
    body = follow(body, mu.body, 12.0f, 3.0f, dt);
    spark = follow(spark, mu.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, mu.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, mu.active ? std::pow(std::clamp(mu.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : mu.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : mu.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : mu.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((mu.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, mu.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    clock += f.delta * f.speed;
    // Pasadas de trama por segundo.
    rows += f.delta * f.speed * (2.5 + 5.0 * drive + 3.0 * kick);
  }

  void render(const Frame& f, Canvas& c) const override {
    auto m = modifiers(f);
    float amp = f.intensity;
    std::vector<float> u;
    u.reserve(24);
    u.insert(u.end(), {float(std::fmod(clock, 1000.0)), bass * amp, kick * amp, energy});
    u.insert(u.end(), {float(m.hilos), float(m.tejido), float(std::fmod(rows, 96000.0)), m.relieve ? 1.0f : 0.0f});
    u.insert(u.end(), {f.glow, flash * amp, spark * amp, 0.0f});
    for (int i = 0; i < 4; i++) u.insert(u.end(), {f.colors[i].r, f.colors[i].g, f.colors[i].b});
    c.material("loom", {0, 0, f.width, f.height}, u);
  }
};

shaderSources.loom:
#version 460 core
#include <flutter/runtime_effect.glsl>
uniform vec2 uSize;
uniform vec4 uA;   // reloj, graves, golpe, energía
uniform vec4 uB;   // hilos, ligamento, pasadas tejidas, relieve
uniform vec4 uD;   // glow, destello, agudos
uniform vec3 uC0;
uniform vec3 uC1;
uniform vec3 uC2;
uniform vec3 uC3;
out vec4 fragColor;

float hash11(float n) {
  n = fract(n * 0.1031);
  n *= n + 33.33;
  n *= n + n;
  return fract(n);
}

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

// Paleta andina: rojo, naranja, amarillo, fucsia, turquesa y negro.
vec3 yarn(float k) {
  k = mod(k, 6.0);
  if (k < 1.0) return uC1;
  if (k < 2.0) return uC2;
  if (k < 3.0) return uC3;
  if (k < 4.0) return vec3(1.0, 0.16, 0.55);
  if (k < 5.0) return vec3(0.0, 0.72, 0.66);
  return vec3(0.07, 0.05, 0.05);
}

// ¿Queda encima la urdimbre en el cruce (i, j)?
bool warpOver(float i, float j, float mode) {
  if (mode < 0.5) return mod(i + j, 2.0) < 1.0;
  if (mode < 1.5) return mod(i + j, 4.0) < 2.0;
  if (mode < 2.5) return mod(abs(mod(i, 12.0) - 6.0) + abs(mod(j, 12.0) - 6.0), 4.0) < 2.0;
  float dir = mod(floor(i / 4.0), 2.0) < 1.0 ? 1.0 : -1.0;
  return mod(i * dir + j + 400.0, 4.0) < 2.0;
}

void main() {
  vec2 frag = FlutterFragCoord().xy;
  float n = uB.x;
  float tp = uSize.x / n;
  float fell = uSize.y * 0.84;
  float t = uA.x;
  vec2 cell = vec2(frag.x / tp, frag.y / tp + uB.z);
  float i = floor(cell.x);
  float j = floor(cell.y);
  vec2 fr = fract(cell);
  // Franjas de urdimbre simétricas, de tres hilos cada una.
  float wi = abs(mod(i, 30.0) - 15.0);
  vec3 warpCol = yarn(floor(wi / 3.0) + floor(i / 30.0) * 2.0);
  // Tramos de tela: cada uno con su ligamento y su secuencia de franjas.
  float section = floor(j / 48.0);
  float mode = uB.y < 0.5 ? floor(hash11(section * 3.7 + 1.0) * 4.0) : uB.y - 1.0;
  float stripe = floor(mod(j, 48.0) / 4.0);
  float sym = abs(stripe - 5.5);
  vec3 weftCol = yarn(floor(hash11(section * 7.1 + floor(sym)) * 6.0));
  vec3 col;
  float gapX = smoothstep(0.0, 0.12, fr.x) * smoothstep(1.0, 0.88, fr.x);
  float gapY = smoothstep(0.0, 0.12, fr.y) * smoothstep(1.0, 0.88, fr.y);
  float lit = 0.9 + 0.25 * uA.y;
  if (frag.y > fell) {
    // Debajo del peine sólo hay urdimbre: hilos tensos sobre el fondo.
    float prof = cos((fr.x - 0.5) * 3.14159);
    col = mix(uC0, warpCol * (0.35 + 0.75 * prof) * lit, gapX * 0.95);
    // Lanzadera que cruza de lado a lado con cada pasada.
    float pass = fract(uB.z);
    float dir = mod(floor(uB.z), 2.0) < 1.0 ? pass : 1.0 - pass;
    vec2 sh = vec2(frag.x / uSize.x - dir, (frag.y - fell - 0.05 * uSize.y) / uSize.y);
    float shuttle = exp(-dot(sh * vec2(9.0, 40.0), sh * vec2(9.0, 40.0)));
    col = mix(col, mix(vec3(0.55, 0.32, 0.12), vec3(1.0, 0.85, 0.5), 0.3 + 0.7 * uA.z), clamp(shuttle * 2.0, 0.0, 1.0));
    col += uC3 * shuttle * (0.3 + 0.8 * uA.z) * uD.x;
  } else {
    bool over = warpOver(i, j, mode);
    float relief = uB.w;
    if (over) {
      float prof = cos((fr.x - 0.5) * 3.14159);
      float along = mix(1.0, 0.75 + 0.25 * sin(fr.y * 3.14159), relief);
      col = warpCol * (0.3 + 0.8 * prof) * along * gapX;
    } else {
      float prof = cos((fr.y - 0.5) * 3.14159);
      float along = mix(1.0, 0.75 + 0.25 * sin(fr.x * 3.14159), relief);
      col = weftCol * (0.3 + 0.8 * prof) * along * gapY;
    }
    col *= lit;
    // Fibras del hilo.
    col *= 0.92 + 0.08 * hash12(floor(frag * 0.8));
    // Brillo que recorre la tela en diagonal con los golpes.
    float sheen = exp(-abs(fract((frag.x + frag.y) / uSize.y * 0.6 - t * 0.15) - 0.5) * 18.0);
    col += vec3(1.0, 0.9, 0.7) * sheen * (0.04 + 0.2 * uA.z) * uD.x;
    // Barra del peine sobre la última pasada.
    col = mix(col, vec3(0.75, 0.7, 0.62), smoothstep(5.0, 0.0, abs(frag.y - fell + 2.0)) * 0.9);
  }
  col += uC2 * uD.y * 0.05;
  vec2 p = (frag - 0.5 * uSize) / min(uSize.x, uSize.y);
  col *= 1.0 - 0.25 * smoothstep(0.7, 1.5, length(p * vec2(0.9, 0.65)));
  fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

visuals.nativeSource:
class Visual final : public Scene {
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  // Relojes en doble precisión: la escena sin música es idéntica a 30 y 60 FPS.
  double spin = 0, wander = 0, sinceSwitch = 0;
  float push = 0, pushVel = 0;
  int beats = 0, autoIndex = 1;

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    spin = rng.unit() * 6.2831853;
    wander = rng.unit() * 6.2831853;
    sinceSwitch = 0;
    push = pushVel = 0;
    beats = 0;
    autoIndex = 1;
  }

  void update(const Frame& f) override {
    auto m = modifiers(f);
    float dt = float(f.delta);
    const Music& mu = f.music;
    bass = follow(bass, mu.bass, 22.0f, 4.5f, dt);
    body = follow(body, mu.body, 12.0f, 3.0f, dt);
    spark = follow(spark, mu.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, mu.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, mu.active ? std::pow(std::clamp(mu.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : mu.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : mu.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : mu.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((mu.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, mu.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    sinceSwitch += f.delta;
    if (hit > kick + 0.2f) {
      beats++;
      pushVel += 1.4f * hit;
      if (beats % 8 == 0) {
        autoIndex = autoIndex % 5 + 1;
        sinceSwitch = 0;
      }
    }
    if (!mu.active && sinceSwitch > 12.0) {
      autoIndex = autoIndex % 5 + 1;
      sinceSwitch = 0;
    }
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    pushVel += (-push * 12.0f - pushVel * 3.5f) * dt;
    push += pushVel * dt;
    spin += f.delta * f.speed * m.flujo * (0.08 + 0.25 * drive);
    wander += f.delta * f.speed * m.flujo * (0.15 + 0.3 * drive);
  }

  void render(const Frame& f, Canvas& c) const override {
    auto m = modifiers(f);
    float amp = f.intensity;
    static const float ps[6] = {4, 3, 4, 5, 6, 8};
    static const float qs[6] = {5, 7, 5, 4, 4, 3};
    int idx = m.patron == 0 ? autoIndex : m.patron;
    // Traslación hiperbólica: deriva lenta más el empujón del golpe.
    float t = 0.28f * float(std::sin(wander)) + 0.25f * std::max(-0.3f, push);
    std::vector<float> u;
    u.reserve(28);
    u.insert(u.end(), {float(std::fmod(spin, 6.2831853)), bass * amp, kick * amp, energy});
    u.insert(u.end(), {ps[idx], qs[idx], std::clamp(t, -0.6f, 0.6f), float(std::sin(wander * 0.7)) * 0.2f});
    u.insert(u.end(), {m.bordes ? 1.0f : 0.0f, f.glow, flash * amp, spark * amp});
    // El disco puede ser más ancho que la pantalla, pero no más alto.
    float radius = std::min(0.49f * std::min(f.width, f.height) * m.tamano, 0.48f * std::max(f.width, f.height));
    u.insert(u.end(), {radius, 0.0f, 0.0f, 0.0f});
    for (int i = 0; i < 4; i++) u.insert(u.end(), {f.colors[i].r, f.colors[i].g, f.colors[i].b});
    c.material("hyperbolic", {0, 0, f.width, f.height}, u);
  }
};

shaderSources.hyperbolic:
#version 460 core
#include <flutter/runtime_effect.glsl>
uniform vec2 uSize;
uniform vec4 uA;   // giro, graves, golpe, energía
uniform vec4 uB;   // p, q, traslación en x, traslación en y
uniform vec4 uD;   // bordes, glow, destello, agudos
uniform vec4 uE;   // radio del disco en píxeles
uniform vec3 uC0;
uniform vec3 uC1;
uniform vec3 uC2;
uniform vec3 uC3;
out vec4 fragColor;

const float PI = 3.14159265;

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

vec2 cmul(vec2 a, vec2 b) { return vec2(a.x * b.x - a.y * b.y, a.x * b.y + a.y * b.x); }
vec2 cdiv(vec2 a, vec2 b) { return vec2(a.x * b.x + a.y * b.y, a.y * b.x - a.x * b.y) / dot(b, b); }

void main() {
  vec2 frag = FlutterFragCoord().xy;
  vec2 z = (frag - 0.5 * uSize) / uE.x;
  float r = length(z);
  vec3 col = uC0;
  if (r < 1.0) {
    // Giro y traslación hiperbólica (Möbius): el mosaico fluye por el disco.
    float cs = cos(uA.x);
    float sn = sin(uA.x);
    z = vec2(cs * z.x - sn * z.y, sn * z.x + cs * z.y);
    vec2 a = uB.zw;
    z = cdiv(z + a, vec2(1.0, 0.0) + cmul(vec2(a.x, -a.y), z));
    // Triángulo base: ángulo pi/p en el centro y pi/q en el vértice exterior.
    float A = PI / uB.x;
    float Bq = PI / uB.y;
    float c = 1.0 / sqrt(1.0 - sin(A) * sin(A) / (cos(Bq) * cos(Bq)));
    float rr = c * sin(A) / cos(Bq);
    vec2 C = vec2(c, 0.0);
    float flips = 0.0;
    for (int i = 0; i < 48; i++) {
      float ang = atan(z.y, z.x);
      float len = length(z);
      ang = mod(ang, 2.0 * A);
      if (ang > A) {
        ang = 2.0 * A - ang;
        flips += 1.0;
      }
      z = len * vec2(cos(ang), sin(ang));
      vec2 d = z - C;
      float dd = dot(d, d);
      if (dd < rr * rr) {
        z = C + rr * rr * d / dd;
        flips += 1.0;
      } else {
        break;
      }
    }
    // Distancias a los lados del triángulo base.
    float dCircle = abs(length(z - C) - rr);
    float dAxis = abs(z.y);
    float dRay = abs(dot(z, vec2(-sin(A), cos(A))));
    float parity = mod(flips, 2.0);
    // Pieza: polígono centrado en el origen; color por la paridad de su teja.
    float center = length(z);
    vec3 tile = mix(uC1, uC2, parity);
    tile *= 0.65 + 0.35 * smoothstep(0.9, 0.0, center);
    tile += uC3 * exp(-dAxis * 60.0) * 0.08 + uC3 * exp(-dRay * 60.0) * 0.08;
    // Bordes dorados entre piezas (el lado curvo es el borde del polígono).
    float edge = exp(-dCircle * 90.0);
    tile += uC3 * edge * (0.7 + 0.8 * uA.y + 1.0 * uA.z) * uD.x * uD.y;
    // Destellos en las piezas con los agudos.
    tile += uC3 * step(0.996 - 0.01 * uD.w, hash12(floor(frag * 0.4) + floor(uA.x * 20.0))) * uD.w * 0.5;
    // Hacia el borde las piezas se vuelven diminutas: se funden suavemente.
    float rim = smoothstep(1.0, 0.86, r);
    col = mix(mix(uC1, uC2, 0.5) * 0.4, tile, rim);
  }
  // Aro dorado del disco.
  col += uC3 * exp(-abs(r - 1.0) * 120.0) * (0.6 + 0.8 * uA.z);
  col += uC3 * exp(-max(r - 1.0, 0.0) * 6.0) * step(1.0, r) * (0.08 + 0.1 * uA.y);
  col += uC1 * uD.z * 0.05;
  col += (hash12(frag) - 0.5) / 255.0;
  fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

visuals.nativeSource:
class Visual final : public Scene {
  static constexpr int kWaves = 3;
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  // Relojes en doble precisión: la escena sin música es idéntica a 30 y 60 FPS.
  double spin = 0, clock = 0, sinceIdle = 0;
  std::array<double, kWaves> waveAge{};
  std::array<float, kWaves> wavePower{};
  int nextWave = 0;

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

  void launch(float power, double age) {
    waveAge[size_t(nextWave)] = age;
    wavePower[size_t(nextWave)] = power;
    nextWave = (nextWave + 1) % kWaves;
  }

 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    spin = rng.unit() * 6.2831853;
    clock = 0;
    sinceIdle = 0;
    waveAge.fill(100.0);
    wavePower.fill(0.0f);
    nextWave = 0;
  }

  void update(const Frame& f) override {
    auto m = modifiers(f);
    float dt = float(f.delta);
    const Music& mu = f.music;
    bass = follow(bass, mu.bass, 22.0f, 4.5f, dt);
    body = follow(body, mu.body, 12.0f, 3.0f, dt);
    spark = follow(spark, mu.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, mu.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, mu.active ? std::pow(std::clamp(mu.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : mu.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : mu.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : mu.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((mu.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, mu.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    for (auto& a : waveAge) a += f.delta * f.speed;
    sinceIdle += f.delta;
    if (hit > kick + 0.2f && m.ondas) {
      launch(0.6f + 0.6f * hit, 0.0);
      sinceIdle = 0;
    }
    if (!mu.active && m.ondas && sinceIdle > 2.5) {
      sinceIdle -= 2.5;
      launch(0.75f, sinceIdle);
    }
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    spin += f.delta * f.speed * m.giro * (0.025 + 0.05 * drive);
    clock += f.delta * f.speed;
  }

  void render(const Frame& f, Canvas& c) const override {
    auto m = modifiers(f);
    auto g = glide(f);
    float amp = f.intensity;
    // Detalle (0,25 a 2) da de 4 a 8 subdivisiones: 6 con el valor normal.
    int levels = std::clamp(int(std::lround(4.0f + (f.detail - 0.25f) / 1.75f * 4.0f)), 4, 8);
    std::vector<float> u;
    u.reserve(33);
    u.insert(u.end(), {float(std::fmod(spin, 6.2831853)), bass * amp, kick * amp, energy});
    u.insert(u.end(), {float(levels), m.bordes ? 1.0f : 0.0f, f.glow, flash * amp});
    std::array<float, 4> radius{9, 9, 9, 9}, power{0, 0, 0, 0};
    for (int i = 0; i < kWaves; i++) {
      if (waveAge[size_t(i)] < 4.0) {
        radius[size_t(i)] = float(waveAge[size_t(i)]) * 0.55f;
        power[size_t(i)] = wavePower[size_t(i)] * float(1.0 - waveAge[size_t(i)] / 4.0) * amp;
      }
    }
    u.insert(u.end(), {radius[0], radius[1], radius[2], float(std::fmod(clock, 1000.0))});
    u.insert(u.end(), {power[0], power[1], power[2], spark * amp});
    // Piezas: peso de cometas y dardos; al cambiar, un mosaico se funde en el otro.
    u.push_back(std::clamp(g.piezas.weight(1), 0.0f, 1.0f));
    for (int i = 0; i < 4; i++) u.insert(u.end(), {f.colors[i].r, f.colors[i].g, f.colors[i].b});
    c.material("penrose", {0, 0, f.width, f.height}, u);
  }
};

shaderSources.penrose:
#version 460 core
#include <flutter/runtime_effect.glsl>
uniform vec2 uSize;
uniform vec4 uA;   // giro, graves, golpe, energía
uniform vec4 uB;   // niveles, bordes, glow, destello
uniform vec4 uW;   // radios de las ondas, reloj
uniform vec4 uP;   // fuerza de las ondas, agudos
uniform float uK;  // peso de cometas y dardos (0 = rombos)
uniform vec3 uC0;
uniform vec3 uC1;
uniform vec3 uC2;
uniform vec3 uC3;
out vec4 fragColor;

const float PI = 3.14159265;
const float PHI = 1.6180340;

float hash11(float n) {
  n = fract(n * 0.1031);
  n *= n + 33.33;
  n *= n + n;
  return fract(n);
}

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

float cross2(vec2 a, vec2 b) { return a.x * b.y - a.y * b.x; }

// ¿Están p y r al mismo lado de la recta a→b?
bool sameSide(vec2 p, vec2 r, vec2 a, vec2 b) {
  return cross2(b - a, p - a) * cross2(b - a, r - a) >= 0.0;
}

float segDist(vec2 p, vec2 a, vec2 b) {
  vec2 pa = p - a;
  vec2 ba = b - a;
  float h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
  return length(pa - ba * h);
}

// Distancia "pentagonal": así las ondas tienen cinco puntas.
float pentaDist(vec2 p) {
  float d = dot(p, vec2(0.0, 1.0));
  d = max(d, dot(p, vec2(-0.9510565, 0.3090170)));
  d = max(d, dot(p, vec2(-0.5877853, -0.8090170)));
  d = max(d, dot(p, vec2(0.5877853, -0.8090170)));
  return max(d, dot(p, vec2(0.9510565, 0.3090170)));
}

// Color de la pieza bajo q en uno de los dos mosaicos de Penrose: rombos
// (P3) o cometas y dardos (P2). Ambos parten de una rueda de diez triángulos
// de Robinson y bajan por sus subdivisiones; cada pieza son dos triángulos
// unidos por BC, así que sus bordes son AB y AC.
vec3 tile(vec2 q, bool kites) {
  float R0 = 1.5;
  float ang = atan(q.y, q.x);
  float i = mod(floor((ang + PI / 10.0) / (PI / 5.0)), 10.0);
  vec2 A = vec2(0.0);
  vec2 B = R0 * vec2(cos((2.0 * i - 1.0) * PI / 10.0), sin((2.0 * i - 1.0) * PI / 10.0));
  vec2 C = R0 * vec2(cos((2.0 * i + 1.0) * PI / 10.0), sin((2.0 * i + 1.0) * PI / 10.0));
  if (mod(i, 2.0) < 0.5) {
    vec2 tmp = B;
    B = C;
    C = tmp;
  }
  if (kites) {
    // En cometas y dardos el vértice del ángulo agudo va en medio (B).
    vec2 tmp = A;
    A = B;
    B = tmp;
  }
  float kind = 0.0;
  for (int level = 0; level < 8; level++) {
    if (float(level) >= uB.x) break;
    if (kites) {
      if (kind < 0.5) {
        // Media cometa: se parte en dos medias cometas y un medio dardo.
        vec2 Q = A + (B - A) / PHI;
        vec2 Rr = B + (C - B) / PHI;
        if (sameSide(q, B, Q, Rr)) {
          vec2 nA = Rr; vec2 nB = Q; vec2 nC = B; A = nA; B = nB; C = nC;
          kind = 1.0;
        } else if (sameSide(q, C, A, Rr)) {
          vec2 nA = C; vec2 nB = A; vec2 nC = Rr; A = nA; B = nB; C = nC;
        } else {
          vec2 nA = Q; vec2 nB = A; vec2 nC = Rr; A = nA; B = nB; C = nC;
        }
      } else {
        // Medio dardo: se parte en un medio dardo y una media cometa.
        vec2 P = C + (A - C) / PHI;
        if (sameSide(q, A, B, P)) {
          vec2 nA = B; vec2 nB = P; vec2 nC = A; A = nA; B = nB; C = nC;
          kind = 1.0;
        } else {
          vec2 nA = P; vec2 nB = C; vec2 nC = B; A = nA; B = nB; C = nC;
          kind = 0.0;
        }
      }
    } else if (kind < 0.5) {
      // Triángulo fino: se parte en dos.
      vec2 P = A + (B - A) / PHI;
      if (sameSide(q, B, C, P)) {
        A = C; vec2 nB = P; vec2 nC = B; B = nB; C = nC;
        kind = 0.0;
      } else {
        vec2 nA = P; vec2 nB = C; vec2 nC = A; A = nA; B = nB; C = nC;
        kind = 1.0;
      }
    } else {
      // Triángulo grueso: se parte en tres.
      vec2 Q = B + (A - B) / PHI;
      vec2 Rr = B + (C - B) / PHI;
      if (sameSide(q, C, Rr, A)) {
        vec2 nA = Rr; vec2 nB = C; vec2 nC = A; A = nA; B = nB; C = nC;
        kind = 1.0;
      } else if (sameSide(q, B, Q, Rr)) {
        vec2 nA = Q; vec2 nB = Rr; vec2 nC = B; A = nA; B = nB; C = nC;
        kind = 1.0;
      } else {
        vec2 nA = Rr; vec2 nB = Q; vec2 nC = A; A = nA; B = nB; C = nC;
        kind = 0.0;
      }
    }
  }
  // La pieza son dos triángulos unidos por BC; su centro es el de BC.
  vec2 center = (B + C) * 0.5;
  float tileHash = hash11(floor(center.x * 97.0) + floor(center.y * 61.0) * 13.0);
  // Ámbar para rombos gruesos y cometas; rojo para rombos finos y dardos.
  bool amber = kites ? kind < 0.5 : kind > 0.5;
  vec3 col = amber ? uC1 : uC2;
  col *= 0.62 + 0.38 * tileHash;
  col *= 0.85 + 0.25 * uA.y;
  // Ondas pentagonales que encienden piezas enteras.
  float dc = pentaDist(center);
  float light = 0.0;
  light += uP.x * smoothstep(0.09, 0.0, abs(dc - uW.x));
  light += uP.y * smoothstep(0.09, 0.0, abs(dc - uW.y));
  light += uP.z * smoothstep(0.09, 0.0, abs(dc - uW.z));
  col = mix(col, uC3, clamp(light, 0.0, 1.0) * 0.85);
  // Bordes de las piezas (AB y AC; BC es la línea interior).
  float scale = min(uSize.x, uSize.y);
  float e = min(segDist(q, A, B), segDist(q, A, C));
  float px = 1.0 / scale;
  float edge = 1.0 - smoothstep(px * 0.8, px * 2.2, e);
  vec3 edgeCol = uB.y > 0.5 ? mix(uC0, uC3, 0.35 + 0.4 * uA.y + 0.5 * light) : uC0;
  col = mix(col, edgeCol, edge);
  // Brillos en los vértices con los agudos.
  if (uP.w > 0.02) {
    vec2 da = q - A;
    vec2 db = q - B;
    vec2 dcv = q - C;
    float vtx2 = min(dot(da, da), min(dot(db, db), dot(dcv, dcv)));
    col += uC3 * (1.0 - smoothstep(px * px, 9.0 * px * px, vtx2)) * uP.w * 0.8;
  }
  return col;
}

void main() {
  vec2 frag = FlutterFragCoord().xy;
  float scale = min(uSize.x, uSize.y);
  vec2 p = (frag - 0.5 * uSize) / scale;
  float cs = cos(uA.x);
  float sn = sin(uA.x);
  vec2 q = vec2(cs * p.x - sn * p.y, sn * p.x + cs * p.y);
  // Piezas: un mosaico o el otro; sólo al cambiar se calculan los dos.
  vec3 col = vec3(0.0);
  if (uK < 0.999) col = tile(q, false);
  if (uK > 0.001) col = mix(col, tile(q, true), uK);
  col *= mix(1.0, uB.z, 0.4);
  col += uC1 * uB.w * 0.05;
  col *= 1.0 - 0.3 * smoothstep(0.7, 1.5, length(p * vec2(0.9, 0.65)));
  float peak = max(col.r, max(col.g, col.b));
  if (peak > 0.85) {
    float ee = (peak - 0.85) / 0.15;
    col *= (0.85 + 0.15 * ee / (1.0 + ee)) / peak;
  }
  col += (hash12(frag) - 0.5) / 255.0;
  fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

visuals.nativeSource:
class Visual final : public Scene {
  static constexpr int kPlumes = 6;
  float bass = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  // Relojes en doble precisión: sin música es idéntico a 30 y 60 FPS.
  double flow = 0, sinceIdle = 0, sinceDrop = 10;
  std::array<float, kPlumes> px{}, psize{}, pcolor{};
  std::array<double, kPlumes> pbirth{};
  int nextPlume = 0;
  uint32_t drops = 0;

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }
  static float hashU(uint32_t x) {
    x ^= x >> 16; x *= 0x7feb352dU; x ^= x >> 15; x *= 0x846ca68bU; x ^= x >> 16;
    return float(x & 0xffffffu) / 16777216.0f;
  }
  static int slots(float detail) { return std::clamp(int(std::lround(3.0f + 1.5f * detail)), 3, kPlumes); }
  // Suelta una gota; carry es el tiempo que ya pasó desde que cayó.
  void drop(float strength, double carry, int limit) {
    const uint32_t k = drops++;
    const int slot = nextPlume % limit;
    px[size_t(slot)] = (hashU(k * 2654435761u + 5u) - 0.5f) * 0.76f;
    psize[size_t(slot)] = (0.8f + 0.5f * hashU(k * 2246822519u + 9u)) * strength;
    pcolor[size_t(slot)] = float(k % 3u);
    pbirth[size_t(slot)] = flow - carry;
    nextPlume = (slot + 1) % limit;
  }

 public:
  void reset(uint32_t seed) override {
    bass = energy = slowBass = kick = flash = drive = 0;
    flow = 0;
    sinceIdle = 0;
    sinceDrop = 10;
    px.fill(0.0f);
    psize.fill(1.0f);
    pcolor.fill(0.0f);
    pbirth.fill(-1000.0);
    nextPlume = 0;
    drops = seed * 3u;
    // Unas gotas ya en el agua para no empezar vacío.
    for (int i = 0; i < 3; i++) drop(1.0f, 1.0 + 2.2 * double(i), kPlumes);
  }

  void update(const Frame& f) override {
    auto m = modifiers(f);
    const float dt = float(f.delta);
    const Music& mu = f.music;
    bass = follow(bass, mu.bass, 22.0f, 4.5f, dt);
    energy = follow(energy, mu.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, mu.active ? std::pow(std::clamp(mu.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);
    float hit = 0, fl = 0;
    for (const auto& e : mu.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : mu.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : mu.events[3]) fl = std::max(fl, e.strength);
    const float onset = std::clamp((mu.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, mu.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    const bool fresh = hit > kick + 0.2f;
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    const double step = f.delta * f.speed;
    flow += step;
    sinceDrop += f.delta;
    const int limit = slots(f.detail);
    // Golpes: cada golpe suelta una gota, más grande cuanto más fuerte.
    if (m.pulso == 0 && fresh && sinceDrop > 0.3) {
      drop(0.8f + 0.6f * hit * f.intensity, 0.0, limit);
      sinceDrop = 0;
    }
    // A su ritmo cae una gota; en Lluvia, el doble.
    double period = m.gotas == 1 ? 0.9 : 1.8;
    if (mu.active && m.pulso == 0) period *= 3.0;
    sinceIdle += step;
    while (sinceIdle >= period) {
      sinceIdle -= period;
      drop(1.0f, sinceIdle, limit);
    }
  }

  void render(const Frame& f, Canvas& c) const override {
    auto g = glide(f);
    const float amp = f.intensity;
    const float side = std::min(f.width, f.height);
    std::vector<float> u;
    u.reserve(64);
    const float current = g.pulso.weight(2) * std::min((energy + drive) * amp, 1.2f);
    u.insert(u.end(), {float(std::fmod(flow, 1000.0)), std::min(bass * amp, 1.5f) * g.pulso.weight(1), std::min(kick * amp, 1.0f), current});
    u.insert(u.end(), {g.gotas.weight(0), g.gotas.weight(1), g.gotas.weight(2), std::clamp(g.turbulencia, 0.0f, 1.0f)});
    u.insert(u.end(), {std::clamp(g.contraluz, 0.0f, 1.0f), f.glow, std::min(flash * amp, 1.0f), 0.5f * f.height / side});
    for (int i = 0; i < kPlumes; i++) {
      const float age = float(std::min(flow - pbirth[size_t(i)], 1000.0));
      u.insert(u.end(), {px[size_t(i)], age, psize[size_t(i)], pcolor[size_t(i)]});
    }
    for (int i = 0; i < 4; i++) u.insert(u.end(), {f.colors[size_t(i)].r, f.colors[size_t(i)].g, f.colors[size_t(i)].b});
    c.material("ink_water", {0, 0, f.width, f.height}, u);
  }
};

shaderSources.ink_water:
#version 460 core
#include <flutter/runtime_effect.glsl>
uniform vec2 uSize;
uniform vec4 uA;   // tiempo, graves, golpe, corriente
uniform vec4 uB;   // pesos de caída: hongo, lluvia, columna; turbulencia
uniform vec4 uE;   // contraluz, glow, destello, media altura
uniform vec4 uP0;  // gotas: x, edad, tamaño, color
uniform vec4 uP1;
uniform vec4 uP2;
uniform vec4 uP3;
uniform vec4 uP4;
uniform vec4 uP5;
uniform vec3 uC0;
uniform vec3 uC1;
uniform vec3 uC2;
uniform vec3 uC3;
out vec4 fragColor;

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash12(i), hash12(i + vec2(1.0, 0.0)), u.x),
             mix(hash12(i + vec2(0.0, 1.0)), hash12(i + vec2(1.0, 1.0)), u.x), u.y);
}

float fbm2(vec2 p) {
  return (noise(p) * 0.65 + noise(p * 2.07 + vec2(3.1, 1.7)) * 0.35);
}

vec3 inkColor(float sel) {
  return sel < 0.5 ? uC1 : (sel < 1.5 ? uC2 : uC3);
}

// Densidad de una gota: capuchón de hongo con su anillo, cúpula e hilo.
float plume(vec2 p, vec4 P, vec2 warp, float halfH) {
  float age = P.y;
  if (age < 0.0 || age > 40.0) return 0.0;
  float fallK = uB.x * 1.0 + uB.y * 1.5 + uB.z * 0.8;
  float headK = uB.x * 1.0 + uB.y * 0.45 + uB.z * 0.55;
  float stemK = uB.x * 0.55 + uB.y * 0.15 + uB.z * 1.3;
  float top = -halfH - 0.03;
  float fall = (0.85 * (1.0 - exp(-age / 2.4)) + 0.06 * age) * fallK;
  vec2 head = vec2(P.x, top + 0.05 + fall);
  float R = P.z * headK * (0.05 + 0.13 * (1.0 - exp(-age / 1.5)) + 0.012 * age) * (1.0 + 0.15 * uA.y);
  float turb = (0.2 + 0.7 * uB.w) * (0.3 + 0.7 * min(age / 3.0, 1.0)) * (1.0 + 0.4 * uA.y);
  // Lejos de la gota no hay tinta: se descarta sin calcular más.
  float reach = R * 1.6 + turb * (0.05 + R * 1.6) * 0.8 + 0.02;
  if (abs(p.x - P.x) > reach || p.y > head.y + reach) return 0.0;
  vec2 pw = p + warp * turb * (0.05 + R * 1.6);
  vec2 q = (pw - head) / R;
  vec2 l = q - vec2(0.62, -0.05);
  vec2 r = q - vec2(-0.62, -0.05);
  float lobes = exp(-dot(l, l) / 0.08) + exp(-dot(r, r) / 0.08);
  float dome = exp(-(q.x * q.x / 0.6 + (q.y - 0.2) * (q.y - 0.2) / 0.16));
  float d = max(lobes, 0.7 * dome);
  // El hilo que une la gota con el punto donde entró.
  float stemW = R * 0.14 + 0.004;
  float dx = (pw.x - P.x) / stemW;
  float stem = exp(-dx * dx) * smoothstep(top, top + 0.08, pw.y) *
               (1.0 - smoothstep(head.y - R * 0.8, head.y - R * 0.2, pw.y)) * stemK * exp(-age / 6.0);
  d = max(d, stem);
  return d * smoothstep(0.0, 0.25, age) * exp(-age / 11.0);
}

void main() {
  vec2 frag = FlutterFragCoord().xy;
  float scale = min(uSize.x, uSize.y);
  vec2 p = (frag - 0.5 * uSize) / scale;
  float t = uA.x;
  float halfH = uE.w;
  // Corriente: el agua arrastra la tinta hacia los lados, más al fondo.
  p.x -= uA.w * 0.14 * sin(p.y * 2.2 + t * 0.45) * (p.y + halfH);
  vec2 warp = vec2(fbm2(p * 1.8 + vec2(0.0, -t * 0.12)), fbm2(p * 1.8 + vec2(5.2, -t * 0.1))) - 0.5;
  // Una segunda capa de remolinos más finos, con un solo ruido.
  float fineW = noise(p * 4.5 + warp * 1.5 + vec2(t * 0.05, -t * 0.06)) - 0.5;
  warp += vec2(fineW, -fineW * 0.8) * 0.6;
  float d0 = plume(p, uP0, warp, halfH);
  float d1 = plume(p, uP1, warp, halfH);
  float d2 = plume(p, uP2, warp, halfH);
  float d3 = plume(p, uP3, warp, halfH);
  float d4 = plume(p, uP4, warp, halfH);
  float d5 = plume(p, uP5, warp, halfH);
  float D = d0 + d1 + d2 + d3 + d4 + d5;
  vec3 acc = d0 * inkColor(uP0.w) + d1 * inkColor(uP1.w) + d2 * inkColor(uP2.w) +
             d3 * inkColor(uP3.w) + d4 * inkColor(uP4.w) + d5 * inkColor(uP5.w);
  vec3 ink = acc / max(D, 1e-4);
  // Volutas finas dentro de la nube (sólo donde hay tinta).
  float det = D > 0.01 ? fbm2(p * 7.0 + warp * 2.5 + vec2(0.0, -t * 0.2)) : 0.5;
  // Filamentos: hilos finos donde el ruido cruza su punto medio.
  float ridge = 1.0 - abs(2.0 * det - 1.0);
  float dens = D * (0.3 + 1.2 * det) + ridge * ridge * smoothstep(0.03, 0.25, D) * 0.5;
  // Agua oscura iluminada desde arriba.
  vec3 col = uC0 + uC3 * 0.04 * (1.0 - smoothstep(-halfH, halfH, p.y));
  // Bordes nítidos, como la tinta de verdad.
  float cover = smoothstep(0.08, 0.5, dens);
  // Lo fino deja pasar la luz; lo espeso se oscurece.
  vec3 lit = ink * (0.75 + 0.55 * exp(-dens * 0.8)) * (0.8 + 0.4 * ridge);
  col = mix(col, lit, cover);
  col += ink * uE.x * uE.y * 0.3 * (1.0 - exp(-D * 0.6));
  col *= 1.0 + 0.15 * uA.z + 0.08 * uE.z;
  col *= 1.0 - 0.3 * smoothstep(0.6, 1.4, length(p * vec2(0.9, 0.65)));
  float peak = max(col.r, max(col.g, col.b));
  if (peak > 0.9) col *= (0.9 + 0.1 * (peak - 0.9) / (peak - 0.8)) / peak;
  col += (hash12(frag) - 0.5) / 255.0;
  fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

