class Visual final : public Scene {
  using Stroke = std::vector<Vec2>;
  using Glyph = std::vector<Stroke>;
  float bass = 0, spark = 0, slowBass = 0;
  float kick = 0, flash = 0;
  // Relojes en doble precisión: sin música es idéntico a 30 y 60 FPS.
  double clock = 0, wordAge = 0, sinceWord = 10;
  uint32_t wordIndex = 0;
  std::array<Glyph, 26> glyphs{};

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }
  static float hashU(uint32_t x) {
    x ^= x >> 16; x *= 0x7feb352dU; x ^= x >> 15; x *= 0x846ca68bU; x ^= x >> 16;
    return float(x & 0xffffffu) / 16777216.0f;
  }
  static float easeOutBack(float x) {
    const float e = x - 1.0f;
    return 1.0f + 2.70158f * e * e * e + 1.70158f * e * e;
  }
  static float bounce(float x) {
    if (x < 0.5f) return 4.0f * x * x;
    const float e = x - 0.82f;
    return 1.0f - 0.9f * std::max(0.0f, 0.15f - 2.2f * e * e);
  }
  // Fuente de trazos: puntos en medias unidades (x 0..8, y 0..12), '|' separa trazos.
  static int hexValue(char ch) { return ch >= 'A' ? ch - 'A' + 10 : ch - '0'; }
  static Glyph parse(const char* code) {
    Glyph glyph;
    Stroke stroke;
    for (const char* p = code; *p; p++) {
      if (*p == '|') { glyph.push_back(stroke); stroke.clear(); continue; }
      if (*p == ' ') continue;
      const int x = hexValue(p[0]), y = hexValue(p[1]);
      stroke.push_back({float(x), float(y)});
      p++;
    }
    if (!stroke.empty()) glyph.push_back(stroke);
    return glyph;
  }
  static int length(const char* w) {
    int n = 0;
    while (w[n]) n++;
    return n;
  }
  static const char* word(int language, uint32_t index) {
    static const char* es[10] = {"FUEGO", "RITMO", "BAILA", "SUBE", "GOLPE", "LUZ", "VAMOS", "DALE", "OTRA", "ARRIBA"};
    static const char* en[10] = {"BASS", "DROP", "BEAT", "BOOM", "LOUD", "HYPE", "VIBE", "DANCE", "JUMP", "MORE"};
    return language == 1 ? en[index % 10u] : es[index % 10u];
  }
  void addGlyph(Path& path, char ch, float cx, float cy, float unit, float scale, float rot) const {
    if (ch < 'A' || ch > 'Z') return;
    const Glyph& g = glyphs[size_t(ch - 'A')];
    const float cs = std::cos(rot), sn = std::sin(rot);
    for (const Stroke& s : g) {
      bool first = true;
      for (const Vec2& pt : s) {
        const float x = (pt.x - 4.0f) * unit * scale, y = (pt.y - 6.0f) * unit * scale;
        const float X = cx + x * cs - y * sn, Y = cy + x * sn + y * cs;
        if (first) { path.moveTo(X, Y); first = false; } else path.lineTo(X, Y);
      }
    }
  }

 public:
  void reset(uint32_t seed) override {
    static const char* codes[26] = {
        "0C 03 30 50 83 8C|07 87", "0C 00 50 72 74 56 06|56 78 7A 5C 0C", "82 60 20 02 0A 2C 6C 8A",
        "00 50 83 89 5C 0C 00", "80 00 0C 8C|06 66", "80 00 0C|06 66", "82 60 20 02 0A 2C 6C 8A 87 47",
        "00 0C|80 8C|06 86", "40 4C|20 60|2C 6C", "80 8A 6C 2C 0A", "00 0C|80 17|35 8C", "00 0C 8C",
        "0C 00 46 80 8C", "0C 00 8C 80", "20 60 82 8A 6C 2C 0A 02 20", "0C 00 60 82 84 66 06",
        "20 60 82 8A 6C 2C 0A 02 20|59 8C", "0C 00 60 82 84 66 06|46 8C",
        "82 60 20 02 04 26 66 88 8A 6C 2C 0A", "00 80|40 4C", "00 0A 2C 6C 8A 80", "00 4C 80",
        "00 2C 45 6C 80", "00 8C|80 0C", "00 46 80|46 4C", "00 80 0C 8C"};
    for (int i = 0; i < 26; i++) glyphs[size_t(i)] = parse(codes[i]);
    bass = spark = slowBass = kick = flash = 0;
    clock = 0;
    wordAge = 1.0;
    sinceWord = 10;
    wordIndex = seed % 10u;
  }

  void update(const Frame& f) override {
    auto m = modifiers(f);
    const float dt = float(f.delta);
    const Music& mu = f.music;
    bass = follow(bass, mu.bass, 22.0f, 4.5f, dt);
    spark = follow(spark, mu.spark, 30.0f, 7.0f, dt);
    float hit = 0, fl = 0;
    for (const auto& e : mu.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : mu.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : mu.events[3]) fl = std::max(fl, e.strength);
    const float onset = std::clamp((mu.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, mu.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    const bool fresh = hit > kick + 0.2f;
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    const double step = f.delta * f.speed;
    clock += step;
    wordAge += step;
    sinceWord += f.delta;
    // Golpes: cada golpe trae la palabra siguiente.
    const bool onBeats = mu.active && m.pulso == 0;
    if (onBeats && fresh && sinceWord > 0.16) {
      wordIndex++;
      wordAge = 0;
      sinceWord = 0;
    }
    // A su ritmo cambia de palabra cada 0,75 s.
    while (!onBeats && wordAge >= 0.75) {
      wordAge -= 0.75;
      wordIndex++;
    }
  }

  void render(const Frame& f, Canvas& c) const override {
    auto m = modifiers(f);
    auto g = glide(f);
    const auto& pal = f.colors;
    const float amp = f.intensity;
    const float W = f.width, H = f.height;
    const float side = std::min(W, H);
    const float wGolpes = g.pulso.weight(0), wGraves = g.pulso.weight(1), wAgudos = g.pulso.weight(2);
    const float boom = std::min(kick * amp, 1.0f) * wGolpes;
    const float swell = 1.0f + 0.12f * std::min(bass * amp, 1.0f) * wGraves;
    const float jitter = std::min(spark * amp, 1.0f) * wAgudos;
    // Fondo: oscuro, con un fogonazo rojo en cada golpe.
    const Color& bg = pal[0];
    const float flashK = std::clamp(0.45f * boom + 0.08f * flash * amp, 0.0f, 0.55f);
    const Color back{bg.r + (pal[1].r - bg.r) * flashK, bg.g + (pal[1].g - bg.g) * flashK, bg.b + (pal[1].b - bg.b) * flashK, 1.0f};
    Paint backPaint;
    backPaint.color = back;
    c.rect({0, 0, W, H}, backPaint);
    const int lang = m.idioma;
    // Filas de palabras en contorno que pasan detrás (más con más detalle).
    {
      const int rows = std::clamp(int(std::lround(4.0f + 4.0f * f.detail)), 4, 12);
      const float unit = H / float(rows) / 16.0f;
      Path marquee;
      for (int r = 0; r < rows; r++) {
        const float y = H * (float(r) + 0.5f) / float(rows);
        const float dir = r % 2 == 0 ? 1.0f : -1.0f;
        float x = float(std::fmod(clock * double(W) * 0.05 * double(1 + r % 3), double(W))) * dir - W;
        uint32_t k = uint32_t(r * 3);
        while (x < W * 1.2f) {
          const char* w = word(lang, wordIndex + k++);
          for (const char* ch = w; *ch; ch++) {
            addGlyph(marquee, *ch, x + 4.0f * unit, y, unit, 1.0f, 0.0f);
            x += 11.0f * unit;
          }
          x += 14.0f * unit;
        }
      }
      Paint mp;
      mp.strokeWidth = unit * 1.2f;
      mp.color = pal[1].opacity(std::clamp(0.14f * f.glow, 0.0f, 1.0f));
      c.path(marquee, mp);
    }
    const char* current = word(lang, wordIndex);
    const char* previous = word(lang, wordIndex + 9u);
    const int n = length(current);
    const Color& ink = (wordIndex % 2u == 0) ? pal[3] : pal[2];
    const float hollow = std::clamp(g.contorno, 0.0f, 1.0f);
    const float wGolpe = g.entrada.weight(0), wCaida = g.entrada.weight(1), wGiro = g.entrada.weight(2);
    const float stagger = 0.04f * (wCaida + wGiro);
    const float age = float(wordAge);
    const uint32_t jitterSlot = uint32_t(std::floor(clock * 20.0));

    // Dibuja una palabra con su animación de entrada en un trazado.
    auto layoutWord = [&](Path& path, Path* split, const char* w, int count, float composition, float scaleAll, float alphaAge, bool exiting) {
      (void)alphaAge;
      float unit, step, x0, y0;
      bool column = composition > 0.5f;
      if (!column) {
        unit = std::min(W * 0.9f / (11.0f * float(count) - 3.0f), H * 0.4f / 12.0f);
        step = 11.0f * unit;
        x0 = W * 0.5f - (float(count) * step - 3.0f * unit) * 0.5f + 4.0f * unit;
        y0 = H * 0.5f;
      } else {
        unit = std::min(H * 0.86f / (float(count) * 14.5f - 2.5f), W * 0.8f / 8.0f);
        step = 14.5f * unit;
        x0 = W * 0.5f;
        y0 = H * 0.5f - (float(count) * step - 2.5f * unit) * 0.5f + 6.0f * unit;
      }
      unit *= scaleAll;
      for (int j = 0; j < count; j++) {
        float cx = column ? x0 : x0 + float(j) * step * scaleAll + (1.0f - scaleAll) * (W * 0.5f - x0);
        float cy = column ? y0 + float(j) * step * scaleAll + (1.0f - scaleAll) * (H * 0.5f - y0) : y0;
        float s = 1.0f, rot = 0.0f;
        if (!exiting) {
          const float a = age - float(j) * stagger;
          if (a < 0.0f) continue;
          const float kG = std::clamp(a / 0.22f, 0.0f, 1.0f);
          const float kC = std::clamp(a / 0.35f, 0.0f, 1.0f);
          const float kR = std::clamp(a / 0.3f, 0.0f, 1.0f);
          s = wGolpe * (1.8f - 0.8f * easeOutBack(kG)) + wCaida + wGiro * (0.4f + 0.6f * kR);
          cy -= wCaida * (1.0f - bounce(kC)) * H * 0.6f;
          rot = wGiro * (1.0f - easeOutBack(kR)) * 1.6f;
        }
        if (jitter > 0.01f) {
          cx += (hashU(uint32_t(j) * 2654435761u + jitterSlot) - 0.5f) * jitter * 0.04f * W;
          cy += (hashU(uint32_t(j) * 2246822519u + jitterSlot) - 0.5f) * jitter * 0.02f * W;
        }
        addGlyph(path, w[j], cx, cy, unit, s, rot);
        if (split) addGlyph(*split, w[j], cx + jitter * 6.0f * side / 400.0f, cy, unit, s, rot);
      }
      return unit;
    };

    auto drawComposition = [&](float compo, float weight) {
      if (weight < 0.01f) return;
      if (weight < 0.99f) c.saveLayer(weight);
      if (compo < 1.5f) {
        // Gigante o Columna: la palabra sola en el centro.
        Path main, split, gone;
        const float unit = layoutWord(main, jitter > 0.01f ? &split : nullptr, current, n, compo, swell, age, false);
        const float strokeW = unit * 2.2f * (1.0f + 0.3f * std::min(bass * amp, 1.0f) * wGraves);
        if (age < 0.15f) {
          // La palabra anterior sale disparada.
          layoutWord(gone, nullptr, previous, length(previous), compo, 1.0f + age * 3.0f, age, true);
          Paint gp;
          gp.strokeWidth = strokeW;
          gp.strokeCap = 2;
          gp.color = pal[1].opacity(std::clamp(1.0f - age / 0.15f, 0.0f, 1.0f));
          c.path(gone, gp);
        }
        if (jitter > 0.01f) {
          Paint sp;
          sp.blend = Blend::plus;
          sp.strokeWidth = strokeW;
          sp.strokeCap = 2;
          sp.color = pal[1].opacity(std::clamp(0.8f * jitter, 0.0f, 1.0f));
          c.path(split, sp);
        }
        Paint tp;
        tp.strokeWidth = strokeW;
        tp.strokeCap = 2;
        tp.color = ink;
        c.path(main, tp);
        if (hollow > 0.01f) {
          Paint hp;
          hp.strokeWidth = strokeW * 0.55f;
          hp.strokeCap = 2;
          hp.color = back.opacity(hollow);
          c.path(main, hp);
        }
      } else {
        // Mosaico: la palabra repetida en filas que corren en sentidos opuestos.
        const int rows = 7;
        const float unit = std::min(W * 0.62f / (11.0f * float(n) - 3.0f), H / float(rows) / 15.0f) * swell;
        const float wordW = (11.0f * float(n) + 11.0f) * unit;
        for (int r = 0; r < rows; r++) {
          Path rowPath;
          const float y = H * (float(r) + 0.5f) / float(rows);
          const float dir = r % 2 == 0 ? 1.0f : -1.0f;
          const float k = std::clamp(age / 0.25f, 0.0f, 1.0f);
          const float slide = (1.0f - easeOutBack(k)) * W * 0.5f * dir;
          float x = float(std::fmod(clock * double(wordW) * 0.35 * double(dir), double(wordW))) - wordW + slide;
          while (x < W + wordW) {
            for (int j = 0; j < n; j++) addGlyph(rowPath, current[j], x + float(j) * 11.0f * unit + 4.0f * unit, y, unit, 1.0f, 0.0f);
            x += wordW;
          }
          const float strokeW = unit * 2.2f * (1.0f + 0.3f * std::min(bass * amp, 1.0f) * wGraves);
          Paint rp;
          rp.strokeWidth = strokeW;
          rp.strokeCap = 2;
          rp.color = (r == rows / 2 ? ink : (r % 2 == 0 ? pal[2] : pal[3])).opacity(r == rows / 2 ? 1.0f : 0.75f);
          c.path(rowPath, rp);
          // Las filas alternas van en contorno; con Contorno, todas.
          const float rowHollow = std::max(hollow, r % 2 == 1 ? 1.0f : 0.0f);
          if (rowHollow > 0.01f) {
            Paint hp;
            hp.strokeWidth = strokeW * 0.55f;
            hp.strokeCap = 2;
            hp.color = back.opacity(rowHollow);
            c.path(rowPath, hp);
          }
        }
      }
      if (weight < 0.99f) c.restore();
    };
    drawComposition(0.0f, g.composicion.weight(0));
    drawComposition(1.0f, g.composicion.weight(1));
    drawComposition(2.0f, g.composicion.weight(2));
  }
};

class Visual final : public Scene {
  static constexpr int kTrail = 16;
  // La simulación avanza en pasos fijos de 1/60 s contados con el tiempo
  // absoluto: es idéntica a 30 y a 60 FPS y se dibuja interpolada.
  static constexpr double kHz = 60.0;
  static constexpr float kStep = float(1.0 / kHz);
  static constexpr int kRecordEvery = 2;  // una muestra de estela cada 1/30 s
  struct Particle { float x, y, px, py, vx, vy, life, size; int group; };
  std::vector<Particle> ps;
  std::vector<float> trail;  // anillo de posiciones: partícula * kTrail * 2
  int head = 0;
  int recordCount = 0;
  int64_t steps = -1;
  float frac = 0, pendingHit = 0;
  float w = 0, h = 0;
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0, surge = 0;
  std::array<float, 3> groups{};
  float t = 0, spin = 0, ringR = 3.0f, ringAmp = 0;
  Random rng{23};

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

  void spawn(size_t i) {
    Particle& p = ps[i];
    float s = std::min(w, h);
    float margin = s * 0.06f;
    p.x = -margin + rng.unit() * (w + 2.0f * margin);
    p.y = -margin + rng.unit() * (h + 2.0f * margin);
    p.px = p.x;
    p.py = p.y;
    p.vx = p.vy = 0;
    p.life = 2.5f + rng.unit() * 4.5f;
    for (int k = 0; k < kTrail; k++) {
      trail[(i * kTrail + k) * 2] = p.x;
      trail[(i * kTrail + k) * 2 + 1] = p.y;
    }
  }

  // Velocidad del remolino (en lados cortos por segundo): giro que se acelera
  // hacia el núcleo, hundimiento lento y una ondulación que forma brazos.
  void field(float x, float y, float& fx, float& fy) const {
    float s = std::min(w, h);
    float u = (x - w * 0.5f) / s, v = (y - h * 0.5f) / s;
    float r = std::sqrt(u * u + v * v) + 1e-3f;
    float tx = -v / r, ty = u / r;
    float rx = u / r, ry = v / r;
    float vt = 0.22f + 0.10f / (r + 0.10f);
    float vr = -(0.10f + 0.06f * r + 0.025f / (r + 0.05f));
    float wave = 0.18f * std::sin(r * 9.0f - t * 1.3f + 3.0f * std::atan2(v, u));
    float bx = tx * vt + rx * vr, by = ty * vt + ry * vr;
    float cw = std::cos(wave), sw = std::sin(wave);
    fx = bx * cw - by * sw;
    fy = bx * sw + by * cw;
  }

  void step(float flow, float speed) {
    float s = std::min(w, h);
    float hit = pendingHit;
    pendingHit = 0;
    t += kStep * speed * (0.4f + 0.8f * drive);
    const float decay = std::exp(-kStep * 2.4f);
    float margin = s * 0.1f;
    for (size_t i = 0; i < ps.size(); i++) {
      Particle& p = ps[i];
      p.px = p.x;
      p.py = p.y;
      float dx = p.x - w * 0.5f, dy = p.y - h * 0.5f;
      float d = std::sqrt(dx * dx + dy * dy) + 1.0f;
      if (hit > 0) {
        // Onda de choque: las estelas salen disparadas hacia fuera.
        float push = s * (0.7f + 0.5f * rng.unit()) * hit;
        p.vx += dx / d * push;
        p.vy += dy / d * push;
      }
      // Las partículas siguen el remolino sin inercia (la inercia las expulsa
      // por fuerza centrífuga y vacía el centro); sólo el empujón del golpe
      // tiene inercia y se amortigua.
      float fx, fy;
      field(p.x, p.y, fx, fy);
      p.vx *= decay;
      p.vy *= decay;
      p.x += (fx * s * flow * p.size + p.vx) * kStep;
      p.y += (fy * s * flow * p.size + p.vy) * kStep;
      p.life -= kStep;
      bool sunk = d < s * 0.05f;
      if (p.life <= 0 || sunk || p.x < -margin || p.x > w + margin || p.y < -margin || p.y > h + margin) spawn(i);
    }
    if (++recordCount >= kRecordEvery) {
      recordCount = 0;
      for (size_t i = 0; i < ps.size(); i++) {
        trail[(i * kTrail + head) * 2] = ps[i].x;
        trail[(i * kTrail + head) * 2 + 1] = ps[i].y;
      }
      head = (head + 1) % kTrail;
    }
  }

 public:
  void reset(uint32_t seed) override {
    rng = Random(seed);
    ps.clear();
    trail.clear();
    w = h = 0;
    head = 0;
    recordCount = 0;
    steps = -1;
    frac = pendingHit = 0;
    bass = body = spark = energy = slowBass = kick = flash = drive = surge = 0;
    groups.fill(0);
    t = rng.unit() * 20.0f;
    spin = rng.unit() * 6.2831853f;
    ringR = 3.0f;
    ringAmp = 0;
  }

  void update(const Frame& f) override {
    float dt = float(f.delta);
    if (f.width != w || f.height != h || ps.empty()) {
      w = f.width;
      h = f.height;
      int count = int(300.0f + 120.0f * std::clamp(f.detail, 0.25f, 2.0f));
      ps.assign(count, Particle{0, 0, 0, 0, 0, 0, 0, 1, 0});
      trail.assign(size_t(count) * kTrail * 2, 0.0f);
      for (int i = 0; i < count; i++) {
        ps[i].group = i % 3;
        ps[i].size = 0.75f + rng.unit() * 0.5f;
        spawn(size_t(i));
        ps[i].life *= rng.unit();
      }
    }
    const Music& m = f.music;
    bass = follow(bass, m.bass, 22.0f, 4.5f, dt);
    body = follow(body, m.body, 12.0f, 3.0f, dt);
    spark = follow(spark, m.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, m.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, m.active ? std::pow(std::clamp(m.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);
    float lo = 0, mi = 0, hi = 0;
    for (int i = 0; i < 9; i++) lo = std::max(lo, m.smoothSpectrum[i]);
    for (int i = 9; i < 21; i++) mi = std::max(mi, m.smoothSpectrum[i]);
    for (int i = 21; i < 31; i++) hi = std::max(hi, m.smoothSpectrum[i]);
    groups[0] = follow(groups[0], lo, 20.0f, 4.0f, dt);
    groups[1] = follow(groups[1], mi, 20.0f, 4.0f, dt);
    groups[2] = follow(groups[2], hi, 20.0f, 4.0f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : m.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : m.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : m.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((m.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, m.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    bool strike = hit > kick + 0.2f;
    if (strike) {
      pendingHit = std::max(pendingHit, hit);
      surge = std::max(surge, hit);
      ringR = 0.0f;
      ringAmp = hit;
    }
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    surge *= std::exp(-dt * 1.8f);
    ringR += dt * (0.9f + 0.5f * drive);
    ringAmp *= std::exp(-dt * 2.4f);

    float flow = f.speed * (0.65f + 0.7f * drive + 0.45f * bass + 0.6f * surge);
    spin += dt * flow * 0.8f;
    int64_t target = int64_t(std::floor(f.time * kHz + 1e-6));
    if (steps < 0 || target < steps || target - steps > 30) steps = target - 1;
    while (steps < target) {
      step(flow, f.speed);
      steps++;
    }
    frac = std::clamp(float(f.time * kHz - double(steps)), 0.0f, 1.0f);
  }

  void render(const Frame& f, Canvas& c) const override {
    float amp = f.intensity;
    float s = std::min(f.width, f.height);
    float px = s / 400.0f;
    std::vector<float> u;
    u.reserve(20);
    u.insert(u.end(), {t, bass * amp, kick * amp, energy});
    u.insert(u.end(), {spin, f.glow, ringR, ringAmp * amp});
    for (int i = 0; i < 4; i++) u.insert(u.end(), {f.colors[i].r, f.colors[i].g, f.colors[i].b});
    c.material("vortex", {0, 0, f.width, f.height}, u);
    if (ps.empty()) return;
    auto alpha = [](float v) { return std::clamp(v, 0.0f, 1.0f); };
    for (int g = 0; g < 3; g++) {
      const Color& col = f.colors[1 + g];
      // Puntas casi blancas pero cálidas: el naranja no vira a amarillo.
      Color hot = {col.r + (1.0f - col.r) * 0.45f, col.g + (0.82f - col.g) * 0.45f,
                   col.b + (0.55f - col.b) * 0.45f, 1.0f};
      float gain = (0.8f + 1.0f * groups[g] + 0.6f * kick) * amp;
      Path tail, tip;
      std::vector<Vec2> heads;
      for (size_t i = 0; i < ps.size(); i++) {
        const Particle& p = ps[i];
        if (p.group != g) continue;
        float x = p.px + (p.x - p.px) * frac, y = p.py + (p.y - p.py) * frac;
        tail.moveTo(x, y);
        tip.moveTo(x, y);
        for (int k = 1; k <= kTrail; k++) {
          int slot = (head - k + kTrail) % kTrail;
          float tx = trail[(i * kTrail + slot) * 2], ty = trail[(i * kTrail + slot) * 2 + 1];
          tail.lineTo(tx, ty);
          if (k <= 3) tip.lineTo(tx, ty);
        }
        heads.push_back({x, y});
      }
      Paint glow;
      glow.blend = Blend::plus;
      glow.strokeCap = 1;
      glow.strokeJoin = 1;
      glow.strokeWidth = 9.0f * px;
      glow.color = {col.r, col.g, col.b, alpha(0.06f * gain * f.glow)};
      c.path(tail, glow);
      Paint core = glow;
      core.strokeWidth = 2.0f * px;
      core.color = {col.r, col.g, col.b, alpha(0.42f * gain)};
      c.path(tail, core);
      Paint bright = glow;
      bright.strokeWidth = 3.2f * px;
      bright.color = {hot.r, hot.g, hot.b, alpha(0.5f * gain)};
      c.path(tip, bright);
      Paint dot;
      dot.blend = Blend::plus;
      float twinkle = 0.75f + 0.25f * std::sin(t * 9.0f + float(g) * 2.0f) * spark;
      dot.color = {hot.r, hot.g, hot.b, alpha((0.6f + 0.4f * groups[g] + 0.3f * kick) * twinkle)};
      c.points(heads, (2.4f + 1.6f * groups[g] * amp + 1.2f * kick * amp) * px, dot);
    }
  }
};

shaderSources.vortex:
#version 460 core
#include <flutter/runtime_effect.glsl>
uniform vec2 uSize;
uniform vec4 uA;   // tiempo, graves, golpe, energía
uniform vec4 uB;   // fase de giro, glow, radio y fuerza de la onda de choque
uniform vec3 uC0;
uniform vec3 uC1;
uniform vec3 uC2;
uniform vec3 uC3;
out vec4 fragColor;

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash12(i), hash12(i + vec2(1.0, 0.0)), u.x),
             mix(hash12(i + vec2(0.0, 1.0)), hash12(i + vec2(1.0, 1.0)), u.x), u.y);
}

float fbm(vec2 p) {
  float s = 0.0;
  float a = 0.5;
  for (int i = 0; i < 3; i++) {
    s += a * noise(p);
    p = mat2(1.6, 1.2, -1.2, 1.6) * p;
    a *= 0.5;
  }
  return s / 0.875;
}

void main() {
  vec2 frag = FlutterFragCoord().xy;
  float scale = min(uSize.x, uSize.y);
  vec2 p = (frag - 0.5 * uSize) / scale;
  float r = length(p) + 0.0005;
  float kick = uA.z;
  float bass = uA.y;

  // Humo en espiral: el ruido se retuerce con el logaritmo del radio y gira
  // con las estelas, así forma brazos que se hunden en el núcleo.
  float th = uB.x - 1.7 * log(r);
  vec2 q = mat2(cos(th), sin(th), -sin(th), cos(th)) * p;
  float smoke = fbm(q * 2.4 + vec2(uA.x * 0.05, 0.0));
  float arms = 0.55 + 0.45 * cos(atan(q.y, q.x) * 2.0);
  vec3 tint = mix(uC1, uC2, smoothstep(0.35, 0.75, smoke));
  float haze = smoothstep(0.42, 0.9, smoke) * arms * smoothstep(1.3, 0.15, r);
  vec3 col = uC0 + tint * haze * (0.06 + 0.10 * uA.w + 0.16 * kick + 0.08 * bass) * uB.y;

  // Núcleo incandescente que late con los graves.
  float core = (0.0012 + 0.003 * bass + 0.006 * kick) / (r * r + 0.0025);
  col += mix(uC2, uC3, 0.5) * core * uB.y;
  // Onda de choque que sale del núcleo con cada golpe.
  col += mix(uC2, uC3, 0.4) * uB.w * exp(-(r - uB.z) * (r - uB.z) * 700.0) * 0.9;

  col *= 1.0 - 0.4 * smoothstep(0.5, 1.3, length(p * vec2(0.9, 0.65)));
  // Compresión que conserva el tono: el naranja intenso no se vuelve amarillo.
  float peak = max(col.r, max(col.g, col.b));
  if (peak > 0.75) {
    float e = (peak - 0.75) / 0.25;
    col *= (0.75 + 0.25 * e / (1.0 + e)) / peak;
  }
  col += (hash12(frag) - 0.5) / 255.0;
  fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

visuals.nativeSource:
class Visual final : public Scene {
  // Las chispas avanzan en pasos fijos de 1/120 s contados con el tiempo
  // absoluto: son idénticas a 30 y a 60 FPS y se dibujan interpoladas.
  static constexpr double kHz = 120.0;
  static constexpr float kStep = float(1.0 / kHz);
  struct Ember { float x, y, px, py, vx, vy, life, size; };
  std::vector<Ember> embers;
  float w = 0, h = 0;
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0, surge = 0;
  std::array<float, 3> groups{};
  float t = 0, current = 0, breath = 0, breathVel = 0, ringR = 3.0f, ringAmp = 0;
  Random rng{29};
  int64_t steps = -1;
  float frac = 0, pendingHit = 0;

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

  void spawn(Ember& e) {
    float s = std::min(w, h);
    float margin = s * 0.06f;
    e.x = -margin + rng.unit() * (w + 2.0f * margin);
    e.y = -margin + rng.unit() * (h + 2.0f * margin);
    e.px = e.x;
    e.py = e.y;
    e.vx = e.vy = 0;
    e.life = 2.0f + rng.unit() * 4.0f;
  }

  // Mismo remolino que Torbellino Ígneo: giro que se acelera hacia el núcleo,
  // hundimiento y una ondulación que forma brazos.
  void field(float x, float y, float& fx, float& fy) const {
    float s = std::min(w, h);
    float u = (x - w * 0.5f) / s, v = (y - h * 0.5f) / s;
    float r = std::sqrt(u * u + v * v) + 1e-3f;
    float tx = -v / r, ty = u / r;
    float rx = u / r, ry = v / r;
    float vt = 0.22f + 0.10f / (r + 0.10f);
    float vr = -(0.10f + 0.06f * r + 0.025f / (r + 0.05f));
    float wave = 0.18f * std::sin(r * 9.0f - t * 1.3f + 3.0f * std::atan2(v, u));
    float bx = tx * vt + rx * vr, by = ty * vt + ry * vr;
    float cw = std::cos(wave), sw = std::sin(wave);
    fx = bx * cw - by * sw;
    fy = bx * sw + by * cw;
  }

  void step(float flow, float speed) {
    float s = std::min(w, h);
    float hit = pendingHit;
    pendingHit = 0;
    t += kStep * speed * (0.4f + 0.8f * drive);
    const float decay = std::exp(-kStep * 2.4f);
    float margin = s * 0.1f;
    for (auto& e : embers) {
      e.px = e.x;
      e.py = e.y;
      float dx = e.x - w * 0.5f, dy = e.y - h * 0.5f;
      float d = std::sqrt(dx * dx + dy * dy) + 1.0f;
      if (hit > 0) {
        float push = s * (0.7f + 0.5f * rng.unit()) * hit;
        e.vx += dx / d * push;
        e.vy += dy / d * push;
      }
      float fx, fy;
      field(e.x, e.y, fx, fy);
      e.vx *= decay;
      e.vy *= decay;
      e.x += (fx * s * flow * e.size + e.vx) * kStep;
      e.y += (fy * s * flow * e.size + e.vy) * kStep;
      e.life -= kStep;
      if (e.life <= 0 || d < s * 0.05f || e.x < -margin || e.x > w + margin || e.y < -margin || e.y > h + margin) spawn(e);
    }
  }

 public:
  void reset(uint32_t seed) override {
    rng = Random(seed);
    embers.clear();
    w = h = 0;
    bass = body = spark = energy = slowBass = kick = flash = drive = surge = 0;
    groups.fill(0);
    t = rng.unit() * 20.0f;
    current = rng.unit() * 64.0f;
    breath = breathVel = 0;
    ringR = 3.0f;
    ringAmp = 0;
    steps = -1;
    frac = pendingHit = 0;
  }

  void update(const Frame& f) override {
    float dt = float(f.delta);
    if (f.width != w || f.height != h || embers.empty()) {
      w = f.width;
      h = f.height;
      int count = int(100.0f + 50.0f * std::clamp(f.detail, 0.25f, 2.0f));
      embers.assign(count, Ember{0, 0, 0, 0, 0, 0, 0, 1});
      for (auto& e : embers) {
        e.size = 0.6f + rng.unit() * 0.8f;
        spawn(e);
        e.life *= rng.unit();
      }
    }
    const Music& m = f.music;
    bass = follow(bass, m.bass, 22.0f, 4.5f, dt);
    body = follow(body, m.body, 12.0f, 3.0f, dt);
    spark = follow(spark, m.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, m.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, m.active ? std::pow(std::clamp(m.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);
    float lo = 0, mi = 0, hi = 0;
    for (int i = 0; i < 9; i++) lo = std::max(lo, m.smoothSpectrum[i]);
    for (int i = 9; i < 21; i++) mi = std::max(mi, m.smoothSpectrum[i]);
    for (int i = 21; i < 31; i++) hi = std::max(hi, m.smoothSpectrum[i]);
    groups[0] = follow(groups[0], lo, 20.0f, 4.0f, dt);
    groups[1] = follow(groups[1], mi, 20.0f, 4.0f, dt);
    groups[2] = follow(groups[2], hi, 20.0f, 4.0f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : m.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : m.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : m.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((m.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, m.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    bool strike = hit > kick + 0.2f;
    if (strike) {
      pendingHit = std::max(pendingHit, hit);
      surge = std::max(surge, hit);
      breathVel += 2.4f * hit;
      ringR = 0.0f;
      ringAmp = hit;
    }
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    surge *= std::exp(-dt * 1.8f);
    ringR += dt * (0.9f + 0.5f * drive);
    ringAmp *= std::exp(-dt * 2.4f);
    // El torbellino respira: se expande con el golpe y vuelve con un muelle.
    breathVel += (-breath * 28.0f - breathVel * 6.0f) * dt;
    breath += breathVel * dt;

    float flow = f.speed * (0.65f + 0.7f * drive + 0.45f * bass + 0.6f * surge);
    // La corriente del fuego avanza en espiral; se envuelve en el periodo
    // radial de la textura para no perder precisión.
    current = std::fmod(current + dt * flow * 0.55f, 64.0f);
    int64_t target = int64_t(std::floor(f.time * kHz + 1e-6));
    if (steps < 0 || target < steps || target - steps > 30) steps = target - 1;
    while (steps < target) {
      step(flow, f.speed);
      steps++;
    }
    frac = std::clamp(float(f.time * kHz - double(steps)), 0.0f, 1.0f);
  }

  void render(const Frame& f, Canvas& c) const override {
    float amp = f.intensity;
    std::vector<float> u;
    u.reserve(24);
    u.insert(u.end(), {current, bass * amp, kick * amp, energy});
    u.insert(u.end(), {f.glow, ringR, ringAmp * amp, breath * amp});
    u.insert(u.end(), {groups[0] * amp, groups[1] * amp, groups[2] * amp, flash * amp});
    for (int i = 0; i < 4; i++) u.insert(u.end(), {f.colors[i].r, f.colors[i].g, f.colors[i].b});
    c.material("maelstrom", {0, 0, f.width, f.height}, u);
    if (embers.empty()) return;
    // Chispas: halo tenue y punto caliente, nunca líneas.
    float px = std::min(f.width, f.height) / 400.0f;
    std::vector<Vec2> pts;
    pts.reserve(embers.size());
    for (const auto& e : embers) pts.push_back({e.px + (e.x - e.px) * frac, e.py + (e.y - e.py) * frac});
    const Color& hot = f.colors[3];
    float gain = std::clamp((0.55f + 0.5f * groups[2] + 0.5f * kick) * amp, 0.0f, 1.0f);
    float twinkle = 0.8f + 0.2f * std::sin(t * 11.0f) * spark;
    Paint halo;
    halo.blend = Blend::plus;
    halo.color = {hot.r, hot.g * 0.8f, hot.b * 0.6f, 0.10f * gain * f.glow};
    c.points(pts, (5.0f + 2.0f * kick * amp) * px, halo);
    Paint core;
    core.blend = Blend::plus;
    core.color = {1.0f, 0.86f, 0.62f, gain * twinkle};
    c.points(pts, (1.3f + 0.8f * groups[2] * amp + 0.6f * kick * amp) * px, core);
  }
};

shaderSources.maelstrom:
#version 460 core
#include <flutter/runtime_effect.glsl>
uniform vec2 uSize;
uniform vec4 uA;   // corriente en espiral, graves, golpe, energía
uniform vec4 uB;   // glow, radio y fuerza de la onda de choque, respiración
uniform vec4 uD;   // graves, medios y agudos del espectro, destello
uniform vec3 uC0;
uniform vec3 uC1;
uniform vec3 uC2;
uniform vec3 uC3;
out vec4 fragColor;

const float TAU = 6.2831853;
const float ARMS = 12.0;     // celdas de ruido por vuelta
const float RADIAL = 64.0;   // periodo radial de la textura, en celdas
const float WIND = 2.6;      // enrollamiento de la espiral

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

// Ruido periódico: sin costura en el corte del ángulo y sin perder precisión
// aunque la corriente avance durante horas.
float pnoise(vec2 p, vec2 period) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  vec2 i0 = mod(i, period);
  vec2 i1 = mod(i + 1.0, period);
  float a = hash12(i0);
  float b = hash12(vec2(i1.x, i0.y));
  float c = hash12(vec2(i0.x, i1.y));
  float d = hash12(i1);
  return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}

float pfbm(vec2 p, vec2 period) {
  float s = 0.0;
  float a = 0.5;
  for (int i = 0; i < 4; i++) {
    s += a * pnoise(p, period);
    p = p * 2.0 + vec2(0.0, 17.0);
    period *= 2.0;
    a *= 0.5;
  }
  return s / 0.9375;
}

// Rampa de fuego: brasa roja, naranja, ámbar y blanco sólo en lo más intenso.
// La paleta se pasa a luz lineal para que, tras la corrección gamma final, el
// naranja conserve su tono y no se vuelva dorado.
vec3 fireRamp(float I) {
  vec3 c1 = pow(uC1, vec3(2.2));
  vec3 c2 = pow(uC2, vec3(2.2));
  vec3 c3 = pow(uC3, vec3(2.2));
  vec3 c = mix(c1, c2, smoothstep(0.1, 0.8, I));
  c = mix(c, c3, smoothstep(1.3, 2.5, I));
  c = mix(c, vec3(1.0, 0.94, 0.82), smoothstep(2.8, 4.2, I));
  return c * min(I, 2.2) * 0.6;
}

void main() {
  vec2 frag = FlutterFragCoord().xy;
  float scale = min(uSize.x, uSize.y);
  vec2 p = (frag - 0.5 * uSize) / scale;
  float r = length(p) + 0.0005;
  float a = atan(p.y, p.x);
  float bass = uA.y;
  float kick = uA.z;

  // La onda de choque empuja el fuego al pasar y el golpe expande el remolino.
  float dr = r - uB.y;
  float shock = uB.z * exp(-dr * dr * 160.0);
  float rr = max(r / (1.0 + 0.5 * uB.w) - 0.04 * shock, 0.0005);
  float lr = log(rr);

  // Coordenadas de espiral: X etiqueta cada brazo y Y avanza hacia el centro
  // con la corriente; las celdas quedan alargadas a lo largo del giro.
  float X = (a + WIND * lr) * (ARMS / TAU);
  float Y = lr * 1.5 + uA.x;
  float warp = pnoise(vec2(X * 0.5, lr * 0.75 + uA.x * 0.5), vec2(ARMS * 0.5, RADIAL * 0.5));
  float n = pfbm(vec2(X + 2.4 * (warp - 0.5), Y), vec2(ARMS, RADIAL));

  // Filamentos de luz donde el ruido cruza su valor medio y cuerpo de fuego.
  float ridge = 1.0 - abs(2.0 * n - 1.0);
  float r4 = ridge * ridge;
  r4 *= r4;
  float fil = r4 * r4 * r4;
  float hot = fil * fil;
  float bodyFire = smoothstep(0.55, 1.0, n);

  float env = smoothstep(0.03, 0.16, r) * (0.35 + 1.0 * exp(-r * 2.0));
  float I = bodyFire * (0.12 + 0.35 * uD.x + 0.15 * bass)
          + fil * (0.7 + 1.2 * uD.y + 0.7 * kick)
          + hot * (0.5 + 2.0 * uD.z);
  I *= env * (0.75 + 0.5 * uA.w) * uB.x;
  // Umbral de negro: el fuego tenue desaparece y el fondo queda negro.
  I = max(I - 0.05, 0.0) * 1.1;

  // Núcleo ardiente que late con los graves, anillo de choque y destello.
  I += (0.0015 + 0.004 * bass + 0.008 * kick) / (r * r + 0.002);
  I += shock * exp(-dr * dr * 900.0) * 3.0;
  I += uD.w * 0.3 * env;

  vec3 col = pow(uC0, vec3(2.2)) + fireRamp(I);
  col *= 1.0 - 0.35 * smoothstep(0.6, 1.4, length(p * vec2(0.9, 0.65)));
  // Mapeo de tonos que conserva el tono: el naranja no vira a amarillo.
  float peak = max(col.r, max(col.g, col.b));
  float mapped = clamp((peak * (2.51 * peak + 0.03)) / (peak * (2.43 * peak + 0.59) + 0.14), 0.0, 1.0);
  col *= mapped / max(peak, 0.0001);
  col = pow(max(col, 0.0), vec3(0.4545));
  col += (hash12(frag) - 0.5) / 255.0;
  fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

visuals.nativeSource:
class Visual final : public Scene {
  static constexpr int kTrail = 16;
  // La simulación avanza en pasos fijos de 1/60 s contados con el tiempo
  // absoluto: es idéntica a 30 y a 60 FPS y se dibuja interpolada.
  static constexpr double kHz = 60.0;
  static constexpr float kStep = float(1.0 / kHz);
  static constexpr int kRecordEvery = 2;  // una muestra de estela cada 1/30 s
  struct Particle { float x, y, px, py, vx, vy, life, size; int group; };
  std::vector<Particle> ps;
  std::vector<float> trail;  // anillo de posiciones: partícula * kTrail * 2
  int head = 0;
  int recordCount = 0;
  int64_t steps = -1;
  float frac = 0, pendingHit = 0;
  float w = 0, h = 0;
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0, surge = 0;
  std::array<float, 3> groups{};
  float t = 0, spin = 0, ringR = 3.0f, ringAmp = 0;
  Random rng{23};

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

  void spawn(size_t i) {
    Particle& p = ps[i];
    float s = std::min(w, h);
    float margin = s * 0.06f;
    p.x = -margin + rng.unit() * (w + 2.0f * margin);
    p.y = -margin + rng.unit() * (h + 2.0f * margin);
    p.px = p.x;
    p.py = p.y;
    p.vx = p.vy = 0;
    p.life = 2.5f + rng.unit() * 4.5f;
    for (int k = 0; k < kTrail; k++) {
      trail[(i * kTrail + k) * 2] = p.x;
      trail[(i * kTrail + k) * 2 + 1] = p.y;
    }
  }

  // Velocidad del remolino (en lados cortos por segundo): giro que se acelera
  // hacia el núcleo, hundimiento lento y una ondulación que forma brazos.
  void field(float x, float y, float& fx, float& fy) const {
    float s = std::min(w, h);
    float u = (x - w * 0.5f) / s, v = (y - h * 0.5f) / s;
    float r = std::sqrt(u * u + v * v) + 1e-3f;
    float tx = -v / r, ty = u / r;
    float rx = u / r, ry = v / r;
    float vt = 0.22f + 0.10f / (r + 0.10f);
    float vr = -(0.10f + 0.06f * r + 0.025f / (r + 0.05f));
    float wave = 0.18f * std::sin(r * 9.0f - t * 1.3f + 3.0f * std::atan2(v, u));
    float bx = tx * vt + rx * vr, by = ty * vt + ry * vr;
    float cw = std::cos(wave), sw = std::sin(wave);
    fx = bx * cw - by * sw;
    fy = bx * sw + by * cw;
  }

  void step(float flow, float speed) {
    float s = std::min(w, h);
    float hit = pendingHit;
    pendingHit = 0;
    t += kStep * speed * (0.4f + 0.8f * drive);
    const float decay = std::exp(-kStep * 2.4f);
    float margin = s * 0.1f;
    for (size_t i = 0; i < ps.size(); i++) {
      Particle& p = ps[i];
      p.px = p.x;
      p.py = p.y;
      float dx = p.x - w * 0.5f, dy = p.y - h * 0.5f;
      float d = std::sqrt(dx * dx + dy * dy) + 1.0f;
      if (hit > 0) {
        // Onda de choque: las estelas salen disparadas hacia fuera.
        float push = s * (0.7f + 0.5f * rng.unit()) * hit;
        p.vx += dx / d * push;
        p.vy += dy / d * push;
      }
      // Las partículas siguen el remolino sin inercia (la inercia las expulsa
      // por fuerza centrífuga y vacía el centro); sólo el empujón del golpe
      // tiene inercia y se amortigua.
      float fx, fy;
      field(p.x, p.y, fx, fy);
      p.vx *= decay;
      p.vy *= decay;
      p.x += (fx * s * flow * p.size + p.vx) * kStep;
      p.y += (fy * s * flow * p.size + p.vy) * kStep;
      p.life -= kStep;
      bool sunk = d < s * 0.05f;
      if (p.life <= 0 || sunk || p.x < -margin || p.x > w + margin || p.y < -margin || p.y > h + margin) spawn(i);
    }
    if (++recordCount >= kRecordEvery) {
      recordCount = 0;
      for (size_t i = 0; i < ps.size(); i++) {
        trail[(i * kTrail + head) * 2] = ps[i].x;
        trail[(i * kTrail + head) * 2 + 1] = ps[i].y;
      }
      head = (head + 1) % kTrail;
    }
  }

 public:
  void reset(uint32_t seed) override {
    rng = Random(seed);
    ps.clear();
    trail.clear();
    w = h = 0;
    head = 0;
    recordCount = 0;
    steps = -1;
    frac = pendingHit = 0;
    bass = body = spark = energy = slowBass = kick = flash = drive = surge = 0;
    groups.fill(0);
    t = rng.unit() * 20.0f;
    spin = rng.unit() * 6.2831853f;
    ringR = 3.0f;
    ringAmp = 0;
  }

  void update(const Frame& f) override {
    float dt = float(f.delta);
    if (f.width != w || f.height != h || ps.empty()) {
      w = f.width;
      h = f.height;
      int count = int(300.0f + 120.0f * std::clamp(f.detail, 0.25f, 2.0f));
      ps.assign(count, Particle{0, 0, 0, 0, 0, 0, 0, 1, 0});
      trail.assign(size_t(count) * kTrail * 2, 0.0f);
      for (int i = 0; i < count; i++) {
        ps[i].group = i % 3;
        ps[i].size = 0.75f + rng.unit() * 0.5f;
        spawn(size_t(i));
        ps[i].life *= rng.unit();
      }
    }
    const Music& m = f.music;
    bass = follow(bass, m.bass, 22.0f, 4.5f, dt);
    body = follow(body, m.body, 12.0f, 3.0f, dt);
    spark = follow(spark, m.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, m.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, m.active ? std::pow(std::clamp(m.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);
    float lo = 0, mi = 0, hi = 0;
    for (int i = 0; i < 9; i++) lo = std::max(lo, m.smoothSpectrum[i]);
    for (int i = 9; i < 21; i++) mi = std::max(mi, m.smoothSpectrum[i]);
    for (int i = 21; i < 31; i++) hi = std::max(hi, m.smoothSpectrum[i]);
    groups[0] = follow(groups[0], lo, 20.0f, 4.0f, dt);
    groups[1] = follow(groups[1], mi, 20.0f, 4.0f, dt);
    groups[2] = follow(groups[2], hi, 20.0f, 4.0f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : m.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : m.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : m.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((m.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, m.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    bool strike = hit > kick + 0.2f;
    if (strike) {
      pendingHit = std::max(pendingHit, hit);
      surge = std::max(surge, hit);
      ringR = 0.0f;
      ringAmp = hit;
    }
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    surge *= std::exp(-dt * 1.8f);
    ringR += dt * (0.9f + 0.5f * drive);
    ringAmp *= std::exp(-dt * 2.4f);

    float flow = f.speed * (0.65f + 0.7f * drive + 0.45f * bass + 0.6f * surge);
    spin += dt * flow * 0.8f;
    int64_t target = int64_t(std::floor(f.time * kHz + 1e-6));
    if (steps < 0 || target < steps || target - steps > 30) steps = target - 1;
    while (steps < target) {
      step(flow, f.speed);
      steps++;
    }
    frac = std::clamp(float(f.time * kHz - double(steps)), 0.0f, 1.0f);
  }

  void render(const Frame& f, Canvas& c) const override {
    float amp = f.intensity;
    float s = std::min(f.width, f.height);
    float px = s / 400.0f;
    std::vector<float> u;
    u.reserve(20);
    u.insert(u.end(), {t, bass * amp, kick * amp, energy});
    u.insert(u.end(), {spin, f.glow, ringR, ringAmp * amp});
    for (int i = 0; i < 4; i++) u.insert(u.end(), {f.colors[i].r, f.colors[i].g, f.colors[i].b});
    c.material("vortex", {0, 0, f.width, f.height}, u);
    if (ps.empty()) return;
    auto alpha = [](float v) { return std::clamp(v, 0.0f, 1.0f); };
    for (int g = 0; g < 3; g++) {
      const Color& col = f.colors[1 + g];
      // Puntas casi blancas pero cálidas: el naranja no vira a amarillo.
      Color hot = {col.r + (1.0f - col.r) * 0.45f, col.g + (0.82f - col.g) * 0.45f,
                   col.b + (0.55f - col.b) * 0.45f, 1.0f};
      float gain = (0.8f + 1.0f * groups[g] + 0.6f * kick) * amp;
      Path tail, tip;
      std::vector<Vec2> heads;
      for (size_t i = 0; i < ps.size(); i++) {
        const Particle& p = ps[i];
        if (p.group != g) continue;
        float x = p.px + (p.x - p.px) * frac, y = p.py + (p.y - p.py) * frac;
        tail.moveTo(x, y);
        tip.moveTo(x, y);
        for (int k = 1; k <= kTrail; k++) {
          int slot = (head - k + kTrail) % kTrail;
          float tx = trail[(i * kTrail + slot) * 2], ty = trail[(i * kTrail + slot) * 2 + 1];
          tail.lineTo(tx, ty);
          if (k <= 3) tip.lineTo(tx, ty);
        }
        heads.push_back({x, y});
      }
      Paint glow;
      glow.blend = Blend::plus;
      glow.strokeCap = 1;
      glow.strokeJoin = 1;
      glow.strokeWidth = 9.0f * px;
      glow.color = {col.r, col.g, col.b, alpha(0.06f * gain * f.glow)};
      c.path(tail, glow);
      Paint core = glow;
      core.strokeWidth = 2.0f * px;
      core.color = {col.r, col.g, col.b, alpha(0.42f * gain)};
      c.path(tail, core);
      Paint bright = glow;
      bright.strokeWidth = 3.2f * px;
      bright.color = {hot.r, hot.g, hot.b, alpha(0.5f * gain)};
      c.path(tip, bright);
      Paint dot;
      dot.blend = Blend::plus;
      float twinkle = 0.75f + 0.25f * std::sin(t * 9.0f + float(g) * 2.0f) * spark;
      dot.color = {hot.r, hot.g, hot.b, alpha((0.6f + 0.4f * groups[g] + 0.3f * kick) * twinkle)};
      c.points(heads, (2.4f + 1.6f * groups[g] * amp + 1.2f * kick * amp) * px, dot);
    }
  }
};

shaderSources.vortex:
#version 460 core
#include <flutter/runtime_effect.glsl>
uniform vec2 uSize;
uniform vec4 uA;   // tiempo, graves, golpe, energía
uniform vec4 uB;   // fase de giro, glow, radio y fuerza de la onda de choque
uniform vec3 uC0;
uniform vec3 uC1;
uniform vec3 uC2;
uniform vec3 uC3;
out vec4 fragColor;

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash12(i), hash12(i + vec2(1.0, 0.0)), u.x),
             mix(hash12(i + vec2(0.0, 1.0)), hash12(i + vec2(1.0, 1.0)), u.x), u.y);
}

float fbm(vec2 p) {
  float s = 0.0;
  float a = 0.5;
  for (int i = 0; i < 3; i++) {
    s += a * noise(p);
    p = mat2(1.6, 1.2, -1.2, 1.6) * p;
    a *= 0.5;
  }
  return s / 0.875;
}

void main() {
  vec2 frag = FlutterFragCoord().xy;
  float scale = min(uSize.x, uSize.y);
  vec2 p = (frag - 0.5 * uSize) / scale;
  float r = length(p) + 0.0005;
  float kick = uA.z;
  float bass = uA.y;

  // Humo en espiral: el ruido se retuerce con el logaritmo del radio y gira
  // con las estelas, así forma brazos que se hunden en el núcleo.
  float th = uB.x - 1.7 * log(r);
  vec2 q = mat2(cos(th), sin(th), -sin(th), cos(th)) * p;
  float smoke = fbm(q * 2.4 + vec2(uA.x * 0.05, 0.0));
  float arms = 0.55 + 0.45 * cos(atan(q.y, q.x) * 2.0);
  vec3 tint = mix(uC1, uC2, smoothstep(0.35, 0.75, smoke));
  float haze = smoothstep(0.42, 0.9, smoke) * arms * smoothstep(1.3, 0.15, r);
  vec3 col = uC0 + tint * haze * (0.06 + 0.10 * uA.w + 0.16 * kick + 0.08 * bass) * uB.y;

  // Núcleo incandescente que late con los graves.
  float core = (0.0012 + 0.003 * bass + 0.006 * kick) / (r * r + 0.0025);
  col += mix(uC2, uC3, 0.5) * core * uB.y;
  // Onda de choque que sale del núcleo con cada golpe.
  col += mix(uC2, uC3, 0.4) * uB.w * exp(-(r - uB.z) * (r - uB.z) * 700.0) * 0.9;

  col *= 1.0 - 0.4 * smoothstep(0.5, 1.3, length(p * vec2(0.9, 0.65)));
  // Compresión que conserva el tono: el naranja intenso no se vuelve amarillo.
  float peak = max(col.r, max(col.g, col.b));
  if (peak > 0.75) {
    float e = (peak - 0.75) / 0.25;
    col *= (0.75 + 0.25 * e / (1.0 + e)) / peak;
  }
  // Fondo transparente: el color va premultiplicado y la opacidad sale del
  // brillo, así la luz se compone sobre lo que haya debajo.
  col = clamp(col, 0.0, 1.0);
  // La luz muy tenue se vuelve transparente del todo: sin velo sobre la app.
  float veilPeak = max(col.r, max(col.g, col.b));
  float clearCut = smoothstep(0.04, 0.12, veilPeak);
  col *= clearCut;
  float alpha = clamp(veilPeak * 1.25, 0.0, 1.0) * clearCut;
  fragColor = vec4(col, alpha);
}

visuals.nativeSource:
class Visual final : public Scene {
  static constexpr int kMax = 5;
  static constexpr int kTrail = 360;
  static constexpr double kStep = 1.0 / 480.0;
  struct Body { double x, y, vx, vy; };
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  // Relojes en doble precisión: la escena sin música es idéntica a 30 y 60 FPS.
  double sim = 0, sceneTime = 0, camX = 0, camY = 0, camR = 1.2;
  // Golpes: tiempo desde el último golpe y su fuerza (el anillo que se expande).
  double beatAge = 100;
  float beatPower = 0;
  int64_t steps = 0;
  int count = 3, scene = 0, autoScene = 0, trailHead = 0, trailCount = 0;
  Random rng{1};
  std::array<Body, kMax> b{};
  std::array<std::array<Vec2, kTrail>, kMax> trail{};

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }
  // Azar fijo para los centelleos: fórmula de un número, sin Random.
  static float sparkleOf(uint32_t x) {
    x ^= x >> 16;
    x *= 0x7feb352du;
    x ^= x >> 15;
    x *= 0x846ca68bu;
    x ^= x >> 16;
    return float(x & 0xffffu) / 65536.0f;
  }

  void start(int which) {
    scene = which;
    sceneTime = 0;
    trailHead = 0;
    trailCount = 0;
    if (which == 0) {
      // Órbita en ocho de Chenciner y Montgomery (G = m = 1).
      count = 3;
      b[0] = {-0.97000436, 0.24308753, 0.46620368, 0.43236573};
      b[1] = {0.97000436, -0.24308753, 0.46620368, 0.43236573};
      b[2] = {0.0, 0.0, -0.93240737, -0.86473146};
    } else if (which == 1) {
      // Triángulo de Lagrange con un pequeño empujón: gira y acaba rompiéndose.
      count = 3;
      double r = 1.0, v = std::sqrt(1.0 / (std::sqrt(3.0) * r)) * 1.0;
      for (int i = 0; i < 3; i++) {
        double a = 6.283185307 * double(i) / 3.0 + 0.3;
        b[size_t(i)] = {r * std::cos(a), r * std::sin(a), -v * std::sin(a), v * std::cos(a)};
      }
      b[0].vx *= 1.004;
    } else {
      count = which == 2 ? 3 : 5;
      double px = 0, py = 0;
      for (int i = 0; i < count; i++) {
        b[size_t(i)] = {double(rng.unit() * 2.0f - 1.0f), double(rng.unit() * 2.0f - 1.0f),
                        double(rng.unit() - 0.5f) * 0.6, double(rng.unit() - 0.5f) * 0.6};
        px += b[size_t(i)].vx;
        py += b[size_t(i)].vy;
      }
      for (int i = 0; i < count; i++) {
        b[size_t(i)].vx -= px / count;
        b[size_t(i)].vy -= py / count;
      }
    }
  }

  void accel(const std::array<Body, kMax>& s, std::array<double, kMax>& ax, std::array<double, kMax>& ay) const {
    for (int i = 0; i < count; i++) ax[size_t(i)] = ay[size_t(i)] = 0;
    for (int i = 0; i < count; i++) {
      for (int j = i + 1; j < count; j++) {
        double dx = s[size_t(j)].x - s[size_t(i)].x, dy = s[size_t(j)].y - s[size_t(i)].y;
        double r2 = dx * dx + dy * dy + 0.0004;
        double inv = 1.0 / (r2 * std::sqrt(r2));
        ax[size_t(i)] += dx * inv;
        ay[size_t(i)] += dy * inv;
        ax[size_t(j)] -= dx * inv;
        ay[size_t(j)] -= dy * inv;
      }
    }
  }

  void step() {
    std::array<double, kMax> ax{}, ay{};
    accel(b, ax, ay);
    for (int i = 0; i < count; i++) {
      b[size_t(i)].vx += ax[size_t(i)] * kStep * 0.5;
      b[size_t(i)].vy += ay[size_t(i)] * kStep * 0.5;
      b[size_t(i)].x += b[size_t(i)].vx * kStep;
      b[size_t(i)].y += b[size_t(i)].vy * kStep;
    }
    accel(b, ax, ay);
    for (int i = 0; i < count; i++) {
      b[size_t(i)].vx += ax[size_t(i)] * kStep * 0.5;
      b[size_t(i)].vy += ay[size_t(i)] * kStep * 0.5;
    }
  }

 public:
  void reset(uint32_t seed) override {
    rng = Random(seed);
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    sim = 0;
    steps = 0;
    beatAge = 100;
    beatPower = 0;
    autoScene = 0;
    camX = camY = 0;
    camR = 1.2;
    start(0);
  }

  void update(const Frame& f) override {
    auto m = modifiers(f);
    float dt = float(f.delta);
    const Music& mu = f.music;
    bass = follow(bass, mu.bass, 22.0f, 4.5f, dt);
    body = follow(body, mu.body, 12.0f, 3.0f, dt);
    spark = follow(spark, mu.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, mu.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, mu.active ? std::pow(std::clamp(mu.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : mu.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : mu.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : mu.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((mu.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, mu.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    beatAge += f.delta;
    if (hit > kick + 0.2f) {
      beatAge = 0;
      beatPower = hit;
    }
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));

    int wanted = m.baile == 0 ? -1 : m.baile - 1;
    if (wanted >= 0 && wanted != scene) start(wanted);
    sim += f.delta * f.speed * (1.0 + 0.8 * drive);
    int64_t target = int64_t(std::floor(sim / kStep + 1e-6));
    if (target - steps > 960) steps = target - 960;
    while (steps < target) {
      step();
      steps++;
      sceneTime += kStep;
      // Cámara: sigue al centro de masas y abarca a todas las estrellas.
      double cx = 0, cy = 0;
      for (int i = 0; i < count; i++) {
        cx += b[size_t(i)].x;
        cy += b[size_t(i)].y;
      }
      cx /= count;
      cy /= count;
      double far = 0.6;
      for (int i = 0; i < count; i++) far = std::max(far, std::hypot(b[size_t(i)].x - cx, b[size_t(i)].y - cy));
      double k = 1.0 - std::exp(-kStep * 1.5);
      camX += (cx - camX) * k;
      camY += (cy - camY) * k;
      camR += (std::min(far * 1.25, 6.0) - camR) * k;
      if (steps % 4 == 0) {
        trailHead = (trailHead + 1) % kTrail;
        trailCount = std::min(trailCount + 1, kTrail);
        for (int i = 0; i < count; i++) trail[size_t(i)][size_t(trailHead)] = {float(b[size_t(i)].x), float(b[size_t(i)].y)};
      }
      // Otra coreografía si una estrella escapa o pasa demasiado tiempo.
      bool escaped = far > 5.0;
      double limit = scene == 0 ? 40.0 : 24.0;
      if (escaped || sceneTime > limit) {
        if (m.baile == 0) {
          autoScene = (autoScene + 1) % 4;
          start(autoScene);
        } else {
          start(scene);
        }
      }
    }
  }

  void render(const Frame& f, Canvas& c) const override {
    auto m = modifiers(f);
    auto g = glide(f);
    float amp = f.intensity;
    // Pulso: cada opción mueve una parte distinta (sin música, todo 0).
    const float golpe = g.pulso.weight(0);
    const float burst = std::min(kick * amp, 1.2f) * golpe;
    const float thick = std::min(bass * amp, 1.2f) * g.pulso.weight(1);
    const float glint = std::min(spark * amp, 1.2f) * g.pulso.weight(2);
    const Color& bg = f.colors[0];
    c.rect({0, 0, f.width, f.height}, Paint::radial({f.width * 0.5f, f.height * 0.5f}, std::max(f.width, f.height) * 0.7f,
                                                   {Color{std::min(1.0f, bg.r + 0.05f), std::min(1.0f, bg.g + 0.025f), std::min(1.0f, bg.b + 0.05f), 1.0f},
                                                    Color{bg.r, bg.g, bg.b, 1.0f}}));
    float side = std::min(f.width, f.height);
    float px = side / 400.0f;
    if (m.estrellas) {
      std::vector<Vec2> stars;
      stars.reserve(160);
      for (int i = 0; i < 160; i++) {
        uint32_t hsh = uint32_t(i) * 2654435761u;
        float x = float(hsh & 0xffff) / 65535.0f, y = float((hsh >> 16) & 0xffff) / 65535.0f;
        stars.push_back({x * f.width, y * f.height});
      }
      Paint sp;
      sp.color = Color{0.9f, 0.85f, 0.8f, 0.35f};
      c.points(stars, 0.9f * px, sp);
      // Agudos: el cielo de fondo titila.
      if (glint > 0.01f) {
        const uint32_t tick = uint32_t(int64_t(std::floor(sim * 8.0)) & 0xffffff);
        std::vector<Vec2> twinkle;
        twinkle.reserve(stars.size());
        for (size_t i = 0; i < stars.size(); i++)
          if (sparkleOf(uint32_t(i) * 747796405u + tick * 2891336453u) > 0.55f) twinkle.push_back(stars[i]);
        Paint tw;
        tw.blend = Blend::plus;
        tw.color = Color{1.0f, 0.95f, 0.9f, std::clamp(0.7f * glint, 0.0f, 1.0f)};
        c.points(twinkle, 2.0f * px, tw);
      }
    }
    float scale = side * 0.62f / float(camR);
    auto toPx = [&](float x, float y) { return Vec2{f.width * 0.5f + (x - float(camX)) * scale, f.height * 0.5f + (y - float(camY)) * scale}; };
    std::array<Color, kMax> cols = {f.colors[1], f.colors[2], f.colors[3], Color{1.0f, 0.4f, 0.6f, 1.0f}, Color{1.0f, 0.6f, 0.2f, 1.0f}};
    int len = std::max(2, int(float(trailCount) * m.estela));
    const int chunks = 8;
    if (burst + thick > 0.01f) {
      Vec2 mid{0, 0};
      for (int i = 0; i < count; i++) {
        const Vec2 q = toPx(float(b[size_t(i)].x), float(b[size_t(i)].y));
        mid.x += q.x / float(count);
        mid.y += q.y / float(count);
      }
      float reach = side * 0.25f;
      for (int i = 0; i < count; i++) {
        const Vec2 q = toPx(float(b[size_t(i)].x), float(b[size_t(i)].y));
        reach = std::max(reach, std::hypot(q.x - mid.x, q.y - mid.y) + 40.0f * px);
      }
      reach = std::min(reach, side * 0.7f);
      Paint groupGlow = Paint::radial(mid, reach, {f.colors[2].opacity(std::clamp((0.22f * burst + 0.12f * thick) * f.glow, 0.0f, 1.0f)),
                                                    f.colors[2].opacity(0.0f)});
      groupGlow.blend = Blend::plus;
      c.circle(mid, reach, groupGlow);
    }
    for (int i = 0; i < count; i++) {
      const Color& col = cols[size_t(i)];
      for (int ch = 0; ch < chunks; ch++) {
        int a = len * ch / chunks, e = std::min(len - 1, len * (ch + 1) / chunks);
        if (e <= a) continue;
        Path p;
        for (int k = a; k <= e; k++) {
          int idx = ((trailHead - (len - 1 - k)) % kTrail + kTrail) % kTrail;
          const Vec2& tp = trail[size_t(i)][size_t(idx)];
          Vec2 q = toPx(tp.x, tp.y);
          if (k == a) p.moveTo(q.x, q.y); else p.lineTo(q.x, q.y);
        }
        float t = float(ch + 1) / float(chunks);
        Paint glow;
        glow.blend = Blend::plus;
        // Graves: las estelas se ensanchan y brillan con los graves.
        glow.strokeWidth = (7.0f + 9.0f * t) * px * (1.0f + 0.6f * thick + 0.8f * burst);
        glow.strokeCap = 1;
        glow.strokeJoin = 1;
        glow.color = col.opacity(std::clamp(0.14f * t * f.glow * amp * (1.0f + 0.8f * thick + 1.2f * burst), 0.0f, 1.0f));
        c.path(p, glow);
        Paint line;
        line.blend = Blend::plus;
        line.strokeWidth = (1.2f + 3.2f * t) * px * (1.0f + 0.6f * thick + 0.8f * burst);
        line.strokeCap = 1;
        line.strokeJoin = 1;
        line.color = col.opacity(std::clamp((0.15f + 0.75f * t) * amp * (1.0f + 0.7f * burst), 0.0f, 1.0f));
        c.path(p, line);
      }
    }
    // Agudos: las estelas sueltan polvo de estrellas que centellea.
    if (glint > 0.01f) {
      const uint32_t tick = uint32_t(int64_t(std::floor(sim * 10.0)) & 0xffffff);
      for (int i = 0; i < count; i++) {
        std::vector<Vec2> dust;
        dust.reserve(size_t(len / 2 + 1));
        for (int k = 0; k < len; k += 2) {
          int idx = ((trailHead - (len - 1 - k)) % kTrail + kTrail) % kTrail;
          if (sparkleOf(uint32_t(idx + i * kTrail) * 2654435761u + tick * 40503u) < 0.5f) continue;
          const Vec2& tp = trail[size_t(i)][size_t(idx)];
          dust.push_back(toPx(tp.x, tp.y));
        }
        Paint dp;
        dp.blend = Blend::plus;
        const Color& col = cols[size_t(i)];
        dp.color = Color{std::min(1.0f, col.r * 0.4f + 0.6f), std::min(1.0f, col.g * 0.4f + 0.6f), std::min(1.0f, col.b * 0.4f + 0.6f),
                         std::clamp(0.85f * glint, 0.0f, 1.0f)};
        c.points(dust, 2.2f * px, dp);
      }
    }
    for (int i = 0; i < count; i++) {
      Vec2 q = toPx(float(b[size_t(i)].x), float(b[size_t(i)].y));
      const Color& col = cols[size_t(i)];
      float r = (7.0f + 5.0f * bass * amp) * px;
      // Graves: el halo crece un 60 % y brilla un 80 % más. Agudos: parpadea.
      const float flick = glint > 0.01f ? glint * float(sparkleOf(uint32_t(i) * 374761393u + uint32_t(int64_t(std::floor(sim * 12.0)) & 0xffffff) * 668265263u) > 0.4f) : 0.0f;
      const float haloR = r * (4.0f + 3.0f * kick) * (1.0f + 0.5f * thick);
      Paint halo = Paint::radial(q, haloR, {col.opacity(std::clamp((0.55f + 0.4f * kick) * f.glow * amp * (1.0f + 0.8f * thick + 0.9f * flick), 0.0f, 1.0f)), col.opacity(0.0f)});
      halo.blend = Blend::plus;
      c.circle(q, haloR, halo);
      // Golpes: un resplandor amplio alrededor de cada estrella.
      if (burst > 0.01f) {
        Paint bloom = Paint::radial(q, r * 12.0f, {col.opacity(std::clamp(0.35f * burst * f.glow, 0.0f, 1.0f)), col.opacity(0.0f)});
        bloom.blend = Blend::plus;
        c.circle(q, r * 12.0f, bloom);
      }
      // Golpes: el núcleo da un salto (18 %). Graves: respira (14 %).
      const float rc = r * (1.0f + 0.15f * burst + 0.12f * thick);
      Paint core = Paint::radial(q, rc, {Color{1.0f, 1.0f, 0.95f, 1.0f}, col, col.opacity(0.0f)}, {0.0f, 0.55f, 1.0f});
      c.circle(q, rc, core);
      // Golpes: cada golpe hace destellar la estrella con una cruz de luz y
      // un anillo que se expande y se apaga.
      if (burst > 0.01f) {
        const float arm = r * (3.0f + 9.0f * burst);
        Path cross;
        cross.moveTo(q.x - arm, q.y).lineTo(q.x + arm, q.y).moveTo(q.x, q.y - arm).lineTo(q.x, q.y + arm);
        Paint ray = Paint::radial(q, arm, {Color{1.0f, 1.0f, 0.95f, std::clamp(1.2f * burst, 0.0f, 1.0f)},
                                           col.opacity(std::clamp(0.7f * burst, 0.0f, 1.0f)), col.opacity(0.0f)},
                                  {0.0f, 0.35f, 1.0f});
        ray.blend = Blend::plus;
        ray.strokeWidth = 2.4f * px;
        ray.strokeCap = 1;
        c.path(cross, ray);
      }
      if (golpe > 0.01f && beatAge < 0.7) {
        const float ring = std::min(beatPower * amp, 1.2f) * golpe * float(1.0 - beatAge / 0.7);
        if (ring > 0.01f) {
          Paint rp;
          rp.blend = Blend::plus;
          rp.strokeWidth = 2.6f * px;
          rp.color = col.opacity(std::clamp(0.95f * ring, 0.0f, 1.0f));
          c.circle(q, r * (1.5f + 18.0f * float(beatAge)), rp);
        }
      }
    }
    if (flash > 0.01f) {
      Paint fl;
      fl.blend = Blend::plus;
      fl.color = f.colors[2].opacity(std::clamp(flash * 0.05f * amp, 0.0f, 1.0f));
      c.rect({0, 0, f.width, f.height}, fl);
    }
  }
};

class Visual final : public Scene {
  static constexpr int kGrid = 8;
  static constexpr int kCells = kGrid * kGrid * kGrid;
  static constexpr int kMaxSegments = 380;
  static constexpr int kMaxPipes = 6;
  // Duración del fundido (segundos del reloj propio) y margen de redondeo del
  // crecimiento: el tramo nuevo usa el mismo margen que decide cuántos hay.
  static constexpr double kClear = 1.4;
  static constexpr double kEps = 1e-6;
  struct Segment { int ax, ay, az, bx, by, bz, color; int64_t step; };
  struct Joint { int x, y, z, color; };
  struct Pipe { int x, y, z, dir, color; bool alive; };
  struct Item { float depth; int index; bool joint; };
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  // Relojes en doble precisión: la escena sin música es idéntica a 30 y 60 FPS.
  double growth = 0, yaw = 0, clearing = -1;
  int64_t stepsDone = 0;
  int nextColor = 0;
  Random rng{1};
  std::array<uint8_t, kCells> used{};
  std::vector<Segment> segments;
  std::vector<Joint> joints;
  std::array<Pipe, kMaxPipes> pipes{};
  mutable std::vector<Item> items;

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

  static int cellIndex(int x, int y, int z) { return (z * kGrid + y) * kGrid + x; }
  static bool inside(int x, int y, int z) { return x >= 0 && y >= 0 && z >= 0 && x < kGrid && y < kGrid && z < kGrid; }

  void clearAll() {
    used.fill(0);
    segments.clear();
    joints.clear();
    for (auto& p : pipes) p.alive = false;
  }

  bool spawn(Pipe& p) {
    for (int attempt = 0; attempt < 24; attempt++) {
      int x = int(rng.unit() * kGrid), y = int(rng.unit() * kGrid), z = int(rng.unit() * kGrid);
      x = std::min(x, kGrid - 1);
      y = std::min(y, kGrid - 1);
      z = std::min(z, kGrid - 1);
      if (used[size_t(cellIndex(x, y, z))]) continue;
      used[size_t(cellIndex(x, y, z))] = 1;
      p = {x, y, z, int(rng.unit() * 6.0f) % 6, nextColor, true};
      nextColor = (nextColor + 1) % 4;
      joints.push_back({x, y, z, p.color});
      return true;
    }
    return false;
  }

  void step(int active) {
    static const int dx[6] = {1, -1, 0, 0, 0, 0};
    static const int dy[6] = {0, 0, 1, -1, 0, 0};
    static const int dz[6] = {0, 0, 0, 0, 1, -1};
    stepsDone++;
    for (int i = 0; i < kMaxPipes; i++) {
      Pipe& p = pipes[size_t(i)];
      if (i >= active) {
        p.alive = false;
        continue;
      }
      if (!p.alive) {
        if (int(segments.size()) < kMaxSegments - 20) spawn(p);
        continue;
      }
      auto freeDir = [&](int d) {
        int x = p.x + dx[d], y = p.y + dy[d], z = p.z + dz[d];
        return inside(x, y, z) && !used[size_t(cellIndex(x, y, z))];
      };
      int dir = -1;
      if (freeDir(p.dir) && rng.unit() < 0.7f) {
        dir = p.dir;
      } else {
        int options[6];
        int count = 0;
        for (int d = 0; d < 6; d++) if (freeDir(d)) options[count++] = d;
        if (count > 0) dir = options[std::min(int(rng.unit() * float(count)), count - 1)];
      }
      if (dir < 0) {
        p.alive = false;
        continue;
      }
      if (dir != p.dir) joints.push_back({p.x, p.y, p.z, p.color});
      int nx = p.x + dx[dir], ny = p.y + dy[dir], nz = p.z + dz[dir];
      segments.push_back({p.x, p.y, p.z, nx, ny, nz, p.color, stepsDone});
      used[size_t(cellIndex(nx, ny, nz))] = 1;
      p.x = nx;
      p.y = ny;
      p.z = nz;
      p.dir = dir;
    }
    if (int(segments.size()) >= kMaxSegments) clearing = 0;
  }

 public:
  void reset(uint32_t seed) override {
    rng = Random(seed);
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    growth = 0;
    yaw = rng.unit() * 6.2831853;
    clearing = -1;
    stepsDone = 0;
    nextColor = 0;
    segments.reserve(kMaxSegments + kMaxPipes);
    joints.reserve(kMaxSegments + kMaxPipes * 2);
    items.reserve(size_t(kMaxSegments + kMaxPipes) * 3);
    clearAll();
  }

  void update(const Frame& f) override {
    auto m = modifiers(f);
    float dt = float(f.delta);
    const Music& mu = f.music;
    bass = follow(bass, mu.bass, 22.0f, 4.5f, dt);
    body = follow(body, mu.body, 12.0f, 3.0f, dt);
    spark = follow(spark, mu.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, mu.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, mu.active ? std::pow(std::clamp(mu.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : mu.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : mu.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : mu.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((mu.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, mu.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    bool beat = hit > kick + 0.2f;
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    if (m.giro) yaw += f.delta * f.speed * (0.12 + 0.2 * drive);

    // Segundos del reloj propio en este cuadro y tramos por segundo: el
    // crecimiento y el fundido siguen el tiempo, no la cantidad de cuadros.
    double run = f.delta * f.speed;
    const double rate = double(m.velocidad) * (5.0 + 9.0 * drive);
    if (clearing >= 0.0) {
      // Todo se desvanece y la rejilla se vacía para empezar de nuevo.
      clearing += run;
      if (clearing < kClear) return;
      // El fundido termina dentro de este cuadro: lo que sobra ya hace crecer.
      run = clearing - kClear;
      clearing = -1;
      clearAll();
      growth = double(stepsDone);
    }
    growth += run * rate + (beat ? 1.5 * hit : 0.0);
    int64_t target = int64_t(std::floor(growth + kEps));
    if (target - stepsDone > 24) stepsDone = target - 24;
    int active = std::clamp(m.tubos, 1, kMaxPipes);
    while (stepsDone < target) {
      step(active);
      if (clearing < 0.0) continue;
      // La rejilla se llenó en el instante en que growth cruzó este tramo: el
      // crecimiento que sobra en este cuadro ya cuenta como fundido.
      clearing = rate > 1e-9 ? std::clamp((growth - double(stepsDone)) / rate, 0.0, run) : 0.0;
      growth = double(stepsDone);
      break;
    }
  }

  void render(const Frame& f, Canvas& c) const override {
    auto m = modifiers(f);
    float amp = f.intensity;
    const Color& bg = f.colors[0];
    c.rect({0, 0, f.width, f.height},
           Paint::radial({f.width * 0.5f, f.height * 0.45f}, std::max(f.width, f.height) * 0.75f,
                         {Color{std::min(1.0f, bg.r + 0.05f), std::min(1.0f, bg.g + 0.05f), std::min(1.0f, bg.b + 0.08f), 1.0f},
                          Color{bg.r, bg.g, bg.b, 1.0f}}));
    std::array<Color, 4> pal = {f.colors[1], f.colors[2], f.colors[3],
                                Color{(f.colors[1].r + f.colors[2].r) * 0.5f, (f.colors[1].g + f.colors[2].g) * 0.5f,
                                      (f.colors[1].b + f.colors[2].b) * 0.5f, 1.0f}};
    float fade = clearing >= 0.0 ? float(std::clamp(1.0 - clearing / kClear, 0.0, 1.0)) : 1.0f;
    float side = std::min(f.width, f.height);
    float scale = side * 0.62f;
    float cyaw = float(std::cos(yaw)), syaw = float(std::sin(yaw));
    const float pitch = 0.42f;
    float cp = std::cos(pitch), sp = std::sin(pitch);
    const float spacing = 2.0f / float(kGrid - 1) * 0.9f;
    auto world = [&](float gx, float gy, float gz) {
      float h = float(kGrid - 1) * 0.5f;
      return std::array<float, 3>{(gx - h) * spacing, (gy - h) * spacing, (gz - h) * spacing};
    };
    struct Proj { float x, y, depth, s; };
    auto project = [&](float gx, float gy, float gz) {
      auto w = world(gx, gy, gz);
      float x = w[0] * cyaw + w[2] * syaw;
      float z = -w[0] * syaw + w[2] * cyaw;
      float y = w[1] * cp - z * sp;
      float zz = w[1] * sp + z * cp;
      float s = 2.6f / (3.6f + zz);
      return Proj{f.width * 0.5f + x * s * scale, f.height * 0.5f - y * s * scale, zz, s};
    };
    // Cuánto ha crecido el tramo nuevo, con el mismo margen que decidió crearlo:
    // así un crecimiento de 49.9999999 o 50.0000001 dibuja lo mismo.
    float frac = float(std::clamp(growth + kEps - double(stepsDone), 0.0, 1.0));
    float tube = 0.055f * m.grosor * (1.0f + 0.12f * bass * amp);
    float lit = (1.0f + 0.45f * kick * amp) * fade;

    items.clear();
    for (size_t i = 0; i < segments.size(); i++) {
      const Segment& s = segments[i];
      Proj a = project(float(s.ax), float(s.ay), float(s.az));
      Proj b = project(float(s.bx), float(s.by), float(s.bz));
      items.push_back({(a.depth + b.depth) * 0.5f, int(i), false});
    }
    for (size_t i = 0; i < joints.size(); i++) {
      const Joint& j = joints[i];
      items.push_back({project(float(j.x), float(j.y), float(j.z)).depth - 0.001f, int(i), true});
    }
    std::sort(items.begin(), items.end(), [](const Item& l, const Item& r) { return l.depth > r.depth; });

    auto shade = [&](const Color& col, float g) {
      return Color{std::min(1.0f, col.r * g), std::min(1.0f, col.g * g), std::min(1.0f, col.b * g), fade};
    };
    for (const Item& it : items) {
      if (it.joint) {
        const Joint& j = joints[size_t(it.index)];
        Proj p = project(float(j.x), float(j.y), float(j.z));
        float r = tube * 1.3f * p.s * scale;
        const Color& col = pal[size_t(j.color)];
        Paint ball = Paint::radial({p.x - r * 0.35f, p.y - r * 0.4f}, r * 1.5f,
                                   {shade(Color{1, 1, 1, 1}, 0.95f * lit), shade(col, 1.0f * lit), shade(col, 0.25f)}, {0.0f, 0.3f, 1.0f});
        c.circle({p.x, p.y}, r, ball);
        continue;
      }
      const Segment& s = segments[size_t(it.index)];
      float t = s.step == stepsDone && clearing < 0.0 ? frac : 1.0f;
      Proj a = project(float(s.ax), float(s.ay), float(s.az));
      Proj b = project(float(s.ax) + float(s.bx - s.ax) * t, float(s.ay) + float(s.by - s.ay) * t,
                       float(s.az) + float(s.bz - s.az) * t);
      float w = tube * 2.0f * (a.s + b.s) * 0.5f * scale;
      float ddx = b.x - a.x, ddy = b.y - a.y;
      float len = std::sqrt(ddx * ddx + ddy * ddy);
      float nx = len > 1e-3f ? -ddy / len : 1.0f, ny = len > 1e-3f ? ddx / len : 0.0f;
      Vec2 mid{(a.x + b.x) * 0.5f, (a.y + b.y) * 0.5f};
      const Color& col = pal[size_t(s.color)];
      // Sombreado de cilindro: borde oscuro, color, reflejo claro y borde.
      Paint pipe = Paint::linear({mid.x - nx * w * 0.5f, mid.y - ny * w * 0.5f}, {mid.x + nx * w * 0.5f, mid.y + ny * w * 0.5f},
                                 {shade(col, 0.25f), shade(col, 0.9f * lit), shade(Color{1, 1, 1, 1}, 0.9f * lit), shade(col, 0.8f * lit), shade(col, 0.18f)},
                                 {0.0f, 0.28f, 0.4f, 0.6f, 1.0f});
      pipe.strokeWidth = w;
      pipe.strokeCap = 1;
      Path p;
      p.moveTo(a.x, a.y).lineTo(b.x, b.y);
      c.path(p, pipe);
    }
    if (flash > 0.01f) {
      Paint fl;
      fl.blend = Blend::plus;
      fl.color = f.colors[2].opacity(std::clamp(flash * 0.05f * amp, 0.0f, 1.0f));
      c.rect({0, 0, f.width, f.height}, fl);
    }
  }
};

class Visual final : public Scene {
  float bass = 0, energy = 0, slowBass = 0, spark = 0;
  float kick = 0, flash = 0, mode = 3.0f, modeTarget = 3.0f, centroid = 0.3f;
  // Reloj en doble precisión: sin música es idéntico a 30 y 60 FPS.
  double clock = 0;
  std::array<float, 32> spec{};
  uint32_t beats = 0;

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }
  static float hashU(uint32_t x) {
    x ^= x >> 16; x *= 0x7feb352dU; x ^= x >> 15; x *= 0x846ca68bU; x ^= x >> 16;
    return float(x & 0xffffffu) / 16777216.0f;
  }

 public:
  void reset(uint32_t seed) override {
    bass = energy = slowBass = kick = flash = spark = 0;
    mode = modeTarget = 3.0f;
    centroid = 0.3f;
    clock = 0;
    spec.fill(0.0f);
    beats = seed;
  }

  void update(const Frame& f) override {
    auto m = modifiers(f);
    const float dt = float(f.delta);
    const Music& mu = f.music;
    bass = follow(bass, mu.bass, 22.0f, 4.5f, dt);
    energy = follow(energy, mu.energy, 6.0f, 1.8f, dt);
    spark = follow(spark, mu.spark, 30.0f, 7.0f, dt);
    float hit = 0, fl = 0;
    for (const auto& e : mu.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : mu.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : mu.events[3]) fl = std::max(fl, e.strength);
    const float onset = std::clamp((mu.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, mu.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    // Golpes: cada golpe salta a otro modo de la onda.
    if (hit > kick + 0.2f && m.pulso == 1) modeTarget = 2.0f + float(int(hashU(beats++ * 2654435761u) * 6.0f));
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    for (int i = 0; i < 31; i++) spec[size_t(i)] = mu.smoothSpectrum[size_t(i)];
    spec[31] = spec[30];
    // Tono: el modo sigue a lo agudo o grave que suena la música.
    float sum = 0, weighted = 0;
    for (int i = 0; i < 31; i++) {
      sum += mu.smoothSpectrum[size_t(i)];
      weighted += mu.smoothSpectrum[size_t(i)] * float(i);
    }
    if (sum > 0.05f) centroid = follow(centroid, weighted / sum / 30.0f, 4.0f, 4.0f, dt);
    if (m.pulso == 2 && mu.active) modeTarget = std::clamp(3.5f + (centroid - 0.3f) * 16.0f, 1.5f, 9.0f);
    mode = follow(mode, modeTarget, 6.0f, 6.0f, dt);
    clock += f.delta * f.speed;
  }

  void render(const Frame& f, Canvas& c) const override {
    auto g = glide(f);
    const float amp = f.intensity;
    const float side = std::min(f.width, f.height);
    const float t = float(std::fmod(clock, 1000.0));
    // Sin música el modo pasea solo de 2 a 5 medias ondas.
    const bool live = f.music.active;
    const float idleMode = 3.5f + 1.5f * std::sin(t * 0.09f);
    const float m = live ? mode : idleMode;
    float A = 0.3f + 0.12f * std::min(energy * amp, 1.0f);
    A *= 1.0f + g.pulso.weight(0) * (std::min(bass * amp, 1.2f) * 1.05f - 0.3f) * (live ? 1.0f : 0.0f);
    // Golpes: toda la onda de llamas pega un salto con cada golpe.
    const float punch = std::min(kick * amp, 1.0f);
    A *= 1.0f + 0.35f * g.pulso.weight(1) * punch;
    std::vector<float> u;
    u.reserve(80);
    u.insert(u.end(), {t, 0.5f * f.height / side, punch * (0.4f + 0.6f * g.pulso.weight(1)), live ? 1.0f : 0.0f});
    // Detalle: cuántos agujeros tiene el tubo.
    u.insert(u.end(), {m, t * 0.3f, A, std::round(24.0f + 16.0f * f.detail)});
    u.insert(u.end(), {g.onda.weight(0), g.onda.weight(1), g.onda.weight(2), std::clamp(g.llama, 0.0f, 1.0f)});
    u.insert(u.end(), {std::clamp(g.calor, 0.0f, 1.0f), std::clamp(g.reflejo, 0.0f, 1.0f), f.glow, std::min(flash * amp, 1.0f)});
    // Espectro amplificado con una curva suave: las bandas flojas suben casi
    // al doble y las fuertes se acercan al tope sin cortarse de golpe.
    for (int i = 0; i < 32; i++) u.push_back(1.4f * (1.0f - std::exp(-std::max(spec[size_t(i)], 0.0f) * amp * 1.8f)));
    for (int i = 0; i < 4; i++) u.insert(u.end(), {f.colors[size_t(i)].r, f.colors[size_t(i)].g, f.colors[size_t(i)].b});
    // Pulso para el material: golpe, graves y agudos de su propia opción.
    u.insert(u.end(), {punch * g.pulso.weight(1), std::min(bass * amp, 1.0f) * g.pulso.weight(0) * (live ? 1.0f : 0.0f),
                       std::min(spark * amp, 1.0f) * g.pulso.weight(2), 0.0f});
    c.material("rubens_tube", {0, 0, f.width, f.height}, u);
  }
};

shaderSources.rubens_tube:
#version 460 core
#include <flutter/runtime_effect.glsl>
uniform vec2 uSize;
uniform vec4 uA;   // tiempo, media altura, golpe, con música
uniform vec4 uB;   // modo, fase, amplitud, agujeros
uniform vec4 uW;   // pesos de onda: estacionaria, espectro, viajera; agitación
uniform vec4 uE;   // calor, reflejo, glow, destello
uniform vec4 uS0;  // espectro de la música en 32 valores
uniform vec4 uS1;
uniform vec4 uS2;
uniform vec4 uS3;
uniform vec4 uS4;
uniform vec4 uS5;
uniform vec4 uS6;
uniform vec4 uS7;
uniform vec3 uC0;
uniform vec3 uC1;
uniform vec3 uC2;
uniform vec3 uC3;
uniform vec4 uP;   // pulso: golpe, graves, agudos (cero sin música)
out vec4 fragColor;

const float TUBE_Y = 0.22;
const float TUBE_R = 0.028;
const float LEFT = -0.42;
const float RIGHT = 0.46;

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

float specIdx(float i) {
  float k = floor(i / 4.0);
  float c = i - k * 4.0;
  vec4 v = k < 0.5 ? uS0 : (k < 1.5 ? uS1 : (k < 2.5 ? uS2 : (k < 3.5 ? uS3 : (k < 4.5 ? uS4 : (k < 5.5 ? uS5 : (k < 6.5 ? uS6 : uS7))))));
  return c < 0.5 ? v.x : (c < 1.5 ? v.y : (c < 2.5 ? v.z : v.w));
}

float specAt(float x) {
  float fi = clamp(x, 0.0, 1.0) * 30.0;
  float i0 = floor(fi);
  float i1 = min(i0 + 1.0, 31.0);
  float a = specIdx(i0);
  float b = specIdx(i1);
  return mix(a, b, fi - i0);
}

// Altura de la llama en la posición x del tubo (0..1).
float flameHeight(float x, float t) {
  // Sólo se calcula la onda que pesa en la mezcla.
  float h = 0.0;
  if (uW.x > 0.001) h += uW.x * pow(abs(sin(3.14159265 * uB.x * x + uB.y)), 1.3);
  if (uW.y > 0.001) h += uW.y * (specAt(x) * 1.4 + 0.08);
  if (uW.z > 0.001) h += uW.z * (0.5 + 0.5 * sin(6.2831853 * (2.5 * x - t * 0.8)));
  // Golpes: todas las llamas se disparan hacia arriba.
  return 0.025 + uB.z * h + uA.z * 0.16;
}

// Las llamas de los agujeros cercanos a p.
vec3 flames(vec2 p, float t) {
  float N = uB.w;
  float spacing = (RIGHT - LEFT) / N;
  float tx = (p.x - LEFT) / (RIGHT - LEFT);
  float idx = floor(tx * N);
  float yTop = TUBE_Y - TUBE_R;
  vec3 acc = vec3(0.0);
  // Por debajo del tubo o muy por encima de la llama más alta no hay fuego.
  float maxH = 0.03 + uB.z * 1.5 + uA.z * 0.16;
  if (p.y > yTop + 0.01 || yTop - p.y > maxH * 1.7 || p.x < LEFT - 0.05 || p.x > RIGHT + 0.05) return acc;
  for (int k = -1; k <= 1; k++) {
    float i = idx + float(k);
    if (i < 0.0 || i > N - 1.0) continue;
    float xn = (i + 0.5) / N;
    float xi = LEFT + xn * (RIGHT - LEFT);
    float H = flameHeight(xn, t);
    float hN = (yTop - p.y) / H;
    if (hN < -0.05 || hN > 1.6) continue;
    float wob = uW.w * 0.022 * hN * sin(hN * 7.0 - t * 12.0 + i * 1.7) + 0.006 * hN * sin(t * 23.0 + i * 3.1);
    float dx = abs(p.x - xi - wob);
    float w0 = spacing * 1.05;
    // Graves: las llamas engordan (×1,5).
    w0 += w0 * 0.5 * uP.y;
    float wp = w0 * (0.45 + 1.6 * clamp(hN, 0.0, 1.0)) * pow(max(1.0 - hN, 0.0), 0.75) + 0.0015;
    float inside = smoothstep(wp, wp * 0.25, dx) * step(0.0, hN);
    float core = smoothstep(wp * 0.55, 0.0, dx) * clamp(1.0 - hN, 0.0, 1.0);
    vec3 c = mix(uC1, uC2, smoothstep(0.05, 0.3, hN));
    c = mix(c, uC3, core * 0.8);
    // Golpes: el fuego se aviva de brillo (+85 % con su opción). Agudos: cada
    // llama parpadea por su cuenta.
    acc += c * inside * (0.8 + 0.4 * core) *
           (1.0 + 0.35 * uA.z + 0.5 * uP.x + uP.z * (0.8 * (0.5 + 0.5 * sin(t * 31.0 + i * 2.7)) - 0.15));
    vec3 flameGlow = uC2 * exp(-dx / (wp * 2.5 + 0.01)) * exp(-max(hN, 0.0) * 2.0) * 0.1 * uE.z * step(0.0, hN);
    acc += flameGlow;
    // Golpes y graves: el halo de cada llama sube un 80 %.
    acc += flameGlow * 0.8 * (uP.x + uP.y);
  }
  return acc;
}

void main() {
  vec2 frag = FlutterFragCoord().xy;
  float scale = min(uSize.x, uSize.y);
  vec2 p = (frag - 0.5 * uSize) / scale;
  float t = uA.x;
  // Calor: el aire sobre las llamas tiembla.
  vec2 q = p;
  q.x += uE.x * 0.006 * sin(p.y * 55.0 + t * 7.0) * smoothstep(TUBE_Y, TUBE_Y - 0.5, p.y);
  vec3 col = uC0 + uC2 * 0.1 * exp(-abs(p.y - TUBE_Y + 0.2) * 3.0) * (0.5 + uE.x);
  // Golpes y graves: resplandor aditivo local sobre la fila de llamas.
  float haloAmt = 0.38 * uP.x + 0.24 * uP.y;
  if (haloAmt > 0.0005) {
    vec2 hq = (p - vec2(0.02, TUBE_Y - 0.16)) / vec2(0.62, 0.22);
    col += uC2 * haloAmt * uE.z * exp(-dot(hq, hq) * 1.4);
  }
  col += flames(q, t);
  // Agudos: chispas que centellean sobre el fuego.
  if (uP.z > 0.001) {
    float above = (1.0 - smoothstep(TUBE_Y - 0.08, TUBE_Y - TUBE_R, p.y)) * exp(-max(TUBE_Y - p.y, 0.0) * 2.5) *
                  step(LEFT - 0.03, p.x) * step(p.x, RIGHT + 0.03);
    float glit = step(0.9, hash12(floor(frag * 0.3) + floor(t * 12.0)));
    col += uC3 * uP.z * 0.8 * glit * above;
  }
  // El tubo de metal, con la luz de las llamas encima.
  float v = (p.y - TUBE_Y) / TUBE_R;
  if (abs(v) < 1.0 && p.x > LEFT - 0.01 && p.x < RIGHT + 0.01) {
    float shade = 0.2 + 0.7 * pow(1.0 - abs(v + 0.35) / 1.35, 2.0);
    vec3 metal = mix(uC0 * 2.0 + vec3(0.04), mix(uC3, vec3(1.0), 0.5) * 0.55, shade);
    metal += uC2 * 0.3 * smoothstep(0.2, -1.0, v);
    float holes = smoothstep(0.35, 0.2, abs(fract((p.x - LEFT) / (RIGHT - LEFT) * uB.w) - 0.5)) * smoothstep(-0.55, -0.95, v);
    col = mix(metal, uC0, holes * 0.8);
  }
  // El altavoz en el extremo izquierdo.
  vec2 sp = p - vec2(LEFT - 0.03, TUBE_Y);
  if (abs(sp.x) < 0.035 && abs(sp.y) < 0.06) {
    float cone = length(sp / vec2(0.03, 0.05));
    col = mix(uC0 * 2.5 + vec3(0.03), uC1 * 0.25, smoothstep(1.0, 0.3, cone) * (0.6 + 0.4 * sin(t * 40.0) * uA.w));
  }
  // Suelo de espejo: las llamas reflejadas y onduladas.
  float floorY = TUBE_Y + 0.07;
  if (uE.y > 0.001 && p.y > floorY) {
    vec2 r = vec2(p.x + 0.004 * sin(p.y * 80.0 + t * 3.0), 2.0 * floorY - p.y);
    float fade = exp(-(p.y - floorY) * 4.0);
    col += flames(r, t) * 0.35 * uE.y * fade;
  }
  col *= 1.0 + 0.12 * uE.w;
  col *= 1.0 - 0.3 * smoothstep(0.7, 1.5, length(p * vec2(0.9, 0.65)));
  float peak = max(col.r, max(col.g, col.b));
  if (peak > 0.9) col *= (0.9 + 0.1 * (peak - 0.9) / (peak - 0.8)) / peak;
  col += (hash12(frag) - 0.5) / 255.0;
  fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

visuals.nativeSource:
class Visual final : public Scene {
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  // Relojes en doble precisión: la escena sin música es idéntica a 30 y 60 FPS.
  double travel = 0, spin = 0, beam = 0, sinceSwitch = 0;
  float boost = 0, theme = 0, themeTarget = 0, laser = 0;
  int beats = 0;

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    travel = rng.unit() * 20.0;
    spin = rng.unit() * 6.2831853;
    beam = rng.unit() * 6.2831853;
    sinceSwitch = 0;
    boost = laser = 0;
    theme = themeTarget = 0;
    beats = 0;
  }

  void update(const Frame& f) override {
    float dt = float(f.delta);
    const Music& m = f.music;
    bass = follow(bass, m.bass, 22.0f, 4.5f, dt);
    body = follow(body, m.body, 12.0f, 3.0f, dt);
    spark = follow(spark, m.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, m.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, m.active ? std::pow(std::clamp(m.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : m.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : m.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : m.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((m.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, m.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    if (hit > kick + 0.2f) {
      beats++;
      boost = std::max(boost, hit);
      laser = std::max(laser, hit);
      if (beats % 8 == 0) themeTarget = 1.0f - themeTarget;
    }
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    boost *= std::exp(-dt * 3.0f);
    laser *= std::exp(-dt * 2.2f);
    sinceSwitch += f.delta;
    if (!m.active && sinceSwitch > 10.0) {
      themeTarget = 1.0f - themeTarget;
      sinceSwitch = 0;
    }
    theme += (themeTarget - theme) * (1.0f - std::exp(-dt * 2.5f));
    travel += f.delta * f.speed * (0.8 + 1.6 * drive + 2.2 * boost);
    spin += f.delta * f.speed * (0.25 + 0.6 * drive);
    beam += f.delta * f.speed * (0.15 + 0.35 * drive);
  }

  void render(const Frame& f, Canvas& c) const override {
    float amp = f.intensity;
    std::vector<float> u;
    u.reserve(24);
    u.insert(u.end(), {float(std::fmod(travel, 1000.0)), bass * amp, kick * amp, energy});
    u.insert(u.end(), {theme, f.glow, spark * amp, flash * amp});
    u.insert(u.end(), {float(std::fmod(spin, 6.2831853)), float(std::fmod(beam, 6.2831853)), (0.25f + laser) * amp, 0.0f});
    for (int i = 0; i < 4; i++) u.insert(u.end(), {f.colors[i].r, f.colors[i].g, f.colors[i].b});
    c.material("cyber_tunnel", {0, 0, f.width, f.height}, u);
  }
};

shaderSources.cyber_tunnel:
#version 460 core
#include <flutter/runtime_effect.glsl>
uniform vec2 uSize;
uniform vec4 uA;   // avance, graves, golpe, energía
uniform vec4 uB;   // tema (0 azul, 1 rojo), glow, agudos, destello
uniform vec4 uR;   // giro de los anillos, giro de los láseres, fuerza de los láseres
uniform vec3 uC0;
uniform vec3 uC1;
uniform vec3 uC2;
uniform vec3 uC3;
out vec4 fragColor;

const float TAU = 6.2831853;
const float SIDES = 10.0;

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

float segment(vec2 p, vec2 a, vec2 b) {
  vec2 pa = p - a;
  vec2 ba = b - a;
  float h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
  return length(pa - ba * h);
}

void main() {
  vec2 frag = FlutterFragCoord().xy;
  float scale = min(uSize.x, uSize.y);
  vec2 p = (frag - 0.5 * uSize) / scale;
  float r = length(p) + 1e-4;
  float a = atan(p.y, p.x);
  float travel = uA.x;
  float kick = uA.z;
  float theme = uB.x;
  vec3 wallA = mix(uC1, uC2, theme);
  vec3 wallB = mix(vec3(0.75, 0.1, 1.0), vec3(1.0, 0.25, 0.1), theme);

  // Paredes de bloques: celdas en ángulo y profundidad con bisel.
  float z = 0.28 / r;
  float depth = z + travel;
  vec2 g = vec2(a / TAU * 36.0, depth * 3.0);
  vec2 cell = floor(g);
  vec2 lc = fract(g);
  float h = hash12(cell);
  float bevel = smoothstep(0.0, 0.12, min(min(lc.x, 1.0 - lc.x), min(lc.y, 1.0 - lc.y)));
  vec3 block = mix(wallA, wallB, step(0.6, h)) * (0.15 + 0.6 * h * h) * (0.4 + 0.6 * bevel);
  block *= 0.5 + 0.9 * uA.w + 0.4 * uA.y;
  // Paneles dorados encendidos.
  float panel = step(0.93, hash12(cell + 17.0));
  vec2 pr = abs(lc - 0.5);
  float panelShape = step(pr.x, 0.32) * step(pr.y, 0.18);
  block += vec3(1.0, 0.78, 0.15) * panel * panelShape * (1.2 + 0.8 * kick);
  float fog = exp(-z * 0.12);
  vec3 col = uC0 + block * fog * smoothstep(0.0, 0.06, r);

  // Anillos de neón de diez lados que vienen hacia la cámara.
  for (int k = 0; k < 3; k++) {
    float fk = float(k);
    float ringZ = fk + 1.0 - fract(travel * 0.35);
    float R = 0.34 / ringZ;
    float rot = uR.x * (mod(fk, 2.0) < 1.0 ? 1.0 : -1.0) + fk;
    float sector = TAU / SIDES;
    float ang = a - rot;
    float sa = mod(ang + 0.5 * sector, sector) - 0.5 * sector;
    // Distancia al lado del polígono (apotema R) en el sector plegado.
    float dEdge = abs(r * cos(sa) - R * cos(0.5 * sector));
    // Cada anillo aparece suave en el fondo y se apaga al pasar la cámara.
    float bright = smoothstep(3.0, 2.2, ringZ) * smoothstep(0.25, 0.6, ringZ);
    float w = 0.003 + 0.004 / ringZ;
    col += uC3 * (exp(-dEdge / (w * 0.5)) + 0.4 * exp(-dEdge / (w * 3.0))) * bright * uB.y;
    // Orbes en los vértices y radios hacia dentro.
    float vang = floor((ang) / sector + 0.5) * sector + rot;
    vec2 vtx = vec2(cos(vang - 0.5 * sector), sin(vang - 0.5 * sector)) * R / cos(0.5 * sector);
    float dOrb = length(p - vtx);
    vec3 orbCol = mix(uC2, vec3(1.0, 0.85, 0.3), 0.15);
    col += orbCol * (0.0004 + 0.0012 * uA.y) / (dOrb * dOrb + 0.00025 / ringZ) * bright * 0.08;
    vec2 inner = vec2(cos(vang + 0.9), sin(vang + 0.9)) * R * 0.35;
    float dSpoke = segment(p, vtx, inner);
    col += uC3 * exp(-dSpoke / (w * 0.6)) * bright * 0.6;
  }

  // Láseres cian que salen del centro.
  float beams = 0.0;
  for (int i = 0; i < 6; i++) {
    float ba = uR.y + float(i) * TAU / 6.0;
    float da = abs(sin(a - ba)) * r;
    float front = step(0.0, cos(a - ba));
    beams += exp(-da * (120.0 / (0.3 + r))) * front;
  }
  col += mix(uC3, vec3(1.0), 0.3) * beams * uR.z * smoothstep(0.03, 0.2, r) * 1.1;

  // Chispas doradas que pasan volando.
  vec2 sg = vec2(a / TAU * 60.0, z * 2.0 + travel * 2.0);
  vec2 sc = floor(sg);
  vec2 sl = fract(sg) - 0.5;
  float spark = step(0.92, hash12(sc + 5.0)) * exp(-(sl.x * sl.x * 40.0 + sl.y * sl.y * 6.0));
  col += vec3(1.0, 0.75, 0.2) * spark * fog * (0.8 + 0.8 * uB.z);
  col += mix(uC3, uC2, theme) * uB.w * 0.05;

  float peak = max(col.r, max(col.g, col.b));
  if (peak > 0.85) {
    float e = (peak - 0.85) / 0.15;
    col *= (0.85 + 0.15 * e / (1.0 + e)) / peak;
  }
  col += (hash12(frag) - 0.5) / 255.0;
  fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

