  vec2 size = vec2(0.2 + 0.25 * hash12(cell + 1.3), 0.15 + 0.3 * hash12(cell + 2.7));
  vec2 dd = abs(lc - 0.5) - size;
  float panel = step(0.62, h) * smoothstep(0.03, -0.01, max(dd.x, dd.y));
  float fog = exp(-z * 0.14);
