    const Music& mu = f.music;
    bass = follow(bass, mu.bass, 22.0f, 4.5f, dt);
    spark = follow(spark, mu.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, mu.energy, 6.0f, 1.8f, dt);
    float hit = 0, fl = 0;
    for (const auto& e : mu.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : mu.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : mu.events[3]) fl = std::max(fl, e.strength);
    const float onset = std::clamp((mu.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, mu.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    const bool fresh = hit > kick + 0.2f;
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    ringAge += f.delta;
    if (fresh) { ringAge = 0.0; ringPower = hit; }
    // Remolino: 1 conserva el empuje tangencial original.
    const float swirlExtra = 0.035f * (glide(f).remolino - 1.0f);

    fActive = f.music.active;
    fenergy = f.music.active ? f.music.energy : 0.0f;
    fbass = f.music.active ? f.music.bass : 0.0f;
    float rate = (f.reducedMotion ? 0.3f : 1.0f) * f.speed;
    int target = int(float(f.time) * rate * 60.0f + 0.001f);
    int guard = 0;
    while (done < target && guard < 16) {
      step(f.width, f.height, swirlExtra);
      guard++;
    }
  }

  void render(const Frame& f, Canvas& c) const override {
    auto g = glide(f);
    float w = f.width, h = f.height;
    float t = float(f.time) * f.speed;
    Vec2 center{w * 0.5f, h * 0.5f};
    float maxDim = std::max(w, h);
    const float amp = f.intensity;
    // Pulso: sus pesos reparten la reacción; todo vale cero sin música.
    const float punch = std::min(kick * amp, 1.0f) * g.pulso.weight(0);
    const float swell = std::min(bass * amp, 1.0f) * g.pulso.weight(1);
    const float glint = std::min(spark * amp, 1.0f) * g.pulso.weight(2);
    const float trail = g.estela;

    // 2. Remanente central (Púlsar ultra-denso con haz rotatorio)
    float bassKick = (1.0f + f.music.bass * 0.5f);
    // Resplandor local de la música alrededor del púlsar (nunca a pantalla
    // completa): Golpes lo enciende en cada golpe, Graves lo hace respirar y
    // Agudos lo hace parpadear en cian.
    const float side = std::min(w, h);
    if (punch > 0.0f || swell > 0.0f) {
      const float auraR = side * 0.46f * (1.0f + 0.15f * swell + 0.12f * punch);
      Paint aura = Paint::radial(center, auraR,
        {{1.0f, 0.34f, 0.13f, std::clamp((0.42f * punch + 0.34f * swell) * f.glow, 0.0f, 1.0f)},
         {1.0f, 0.34f, 0.13f, std::clamp((0.18f * punch + 0.14f * swell) * f.glow, 0.0f, 1.0f)},
         {1.0f, 0.34f, 0.13f, 0.0f}}, {0.0f, 0.5f, 1.0f});
      aura.blend = Blend::plus;
      c.circle(center, auraR, aura);
    }
    if (glint > 0.0f) {
      const float flicker = 0.6f + 0.4f * std::sin(t * 47.0f);
      Paint shimmer = Paint::radial(center, side * 0.34f,
        {{0.0f, 0.9f, 1.0f, std::clamp(0.36f * glint * flicker * f.glow, 0.0f, 1.0f)}, {0.0f, 0.9f, 1.0f, 0.0f}}, {0.0f, 1.0f});
      shimmer.blend = Blend::plus;
      c.circle(center, side * 0.34f, shimmer);
    }
    // Golpes: el púlsar da un salto; Graves: su halo crece y brilla despacio.
    const float glowR = 50.0f * bassKick * (1.0f + 0.2f * punch + 0.15f * swell);
    Paint pulsarGlow = Paint::radial(center, glowR,
      {{1.0f, 0.35f, 0.0f, std::clamp(0.40f * f.intensity + 0.5f * punch + 0.4f * swell, 0.0f, 1.0f)}, {0, 0, 0, 0}},
      {0.0f, 1.0f});
    pulsarGlow.blend = Blend::plus;
    c.circle(center, glowR, pulsarGlow);

    Paint pulsarCore; pulsarCore.blend = Blend::plus;
    pulsarCore.color = {1.0f, 1.0f, 1.0f, std::clamp(0.95f * f.intensity, 0.0f, 1.0f)};
    c.circle(center, 5.0f * bassKick * (1.0f + 0.6f * punch), pulsarCore);

    // Haces de emisión del púlsar rotando a gran velocidad (Agudos: se avivan)
    float beamAngle = t * 4.0f;
    float beamLen = 35.0f * bassKick * (1.0f + 0.6f * glint);
    Paint beamPaint; beamPaint.blend = Blend::plus;
    beamPaint.color = {0.0f, 0.9f, 1.0f, std::clamp(0.6f * f.intensity + 0.4f * glint, 0.0f, 1.0f)};
    beamPaint.strokeWidth = 2.0f;
    if (glint > 0.0f) beamPaint.strokeWidth *= 1.0f + 1.2f * glint;
    Path beams;
    beams.moveTo(center.x - std::cos(beamAngle) * beamLen, center.y - std::sin(beamAngle) * beamLen);
    beams.lineTo(center.x + std::cos(beamAngle) * beamLen, center.y + std::sin(beamAngle) * beamLen);
    c.path(beams, beamPaint);

    // 3. Onda de choque expansiva
    if (shockRadius > 0.0f) {
      float shockAlpha = std::clamp((1.0f - shockRadius / (maxDim * 1.2f)) * f.intensity, 0.0f, 1.0f);
      Paint shockPaint; shockPaint.blend = Blend::plus;
      shockPaint.color = {1.0f, 0.84f, 0.0f, shockAlpha};
      shockPaint.strokeWidth = std::clamp(4.0f * shockAlpha, 1.0f, 4.0f);
      c.circle(center, shockRadius, shockPaint);
    }

    // Golpes: un anillo de choque corto sale del púlsar con cada golpe.
    const float ringFade = ringPower * float(std::exp(-ringAge * 3.0)) * g.pulso.weight(0);
    if (ringFade > 0.01f) {
      Paint ring; ring.blend = Blend::plus;
      ring.color = {1.0f, 0.62f, 0.22f, std::clamp(0.95f * ringFade * amp, 0.0f, 1.0f)};
      ring.strokeWidth = 2.5f + 6.0f * ringFade;
      c.circle(center, 50.0f * bassKick + float(ringAge) * maxDim * 0.55f, ring);
    }

    // 4. Renderizar partículas termodinámicas con estelas de velocidad
    const uint32_t thermalPal[5] = {0xffff5722, 0xffffd600, 0xff00e5ff, 0xffff007f, 0xffe040fb};
    const uint32_t twinkleTick = uint32_t(std::floor(t * 14.0f));

    for (size_t i = 0; i < particles.size(); i++) {
      const auto& p = particles[i];
      float speed = std::sqrt(p.vx * p.vx + p.vy * p.vy);
      float trailLen = std::clamp(speed * 1.5f, 2.0f, 24.0f);
      // Estela: más corta o más larga que la original (1 = igual).
      trailLen *= trail;
      float normVx = (speed > 0.01f) ? (p.vx / speed) : 0.0f;
      float normVy = (speed > 0.01f) ? (p.vy / speed) : 0.0f;

      float px = (done == 0 ? center.x + p.x : p.x);
      float py = (done == 0 ? center.y + p.y : p.y);
      // Graves: la nube se hincha desde el púlsar.
      if (swell > 0.0f) {
        px = center.x + (px - center.x) * (1.0f + 0.14f * swell);
        py = center.y + (py - center.y) * (1.0f + 0.14f * swell);
      }
      float tailX = px - normVx * trailLen;
      float tailY = py - normVy * trailLen;

      Color base = Color::argb(thermalPal[p.colIdx]);
      Color col{
        base.r * (1.0f - p.energy) + 1.0f * p.energy,
        base.g * (1.0f - p.energy) + 1.0f * p.energy,
        base.b * (1.0f - p.energy) + 1.0f * p.energy,
        std::clamp((0.40f + p.energy * 0.60f) * f.intensity, 0.0f, 1.0f)
      };
      // Golpes: la nube entera se enciende; Agudos: algunas partículas centellean.
      if (punch > 0.0f || glint > 0.0f) {
        const float sparkle = hashU(uint32_t(i) * 2654435761u + twinkleTick * 40503u) < glint * 0.9f ? glint : 0.0f;
        col.r = std::min(1.0f, col.r + (1.0f - col.r) * 0.8f * sparkle);
        col.g = std::min(1.0f, col.g + (1.0f - col.g) * 0.8f * sparkle);
        col.b = std::min(1.0f, col.b + (1.0f - col.b) * 0.8f * sparkle);
        col.a = std::clamp(col.a + 0.65f * punch + 0.6f * sparkle, 0.0f, 1.0f);
      }

      Paint partPaint; partPaint.blend = Blend::plus;
      partPaint.color = col;
      partPaint.strokeWidth = std::max(1.0f, p.size);
      // Graves y Golpes: estelas más gruesas.
      if (swell > 0.0f || punch > 0.0f) partPaint.strokeWidth *= 1.0f + 0.6f * swell + 0.9f * punch;
      partPaint.strokeCap = 1;

      Path pLine; pLine.moveTo(tailX, tailY); pLine.lineTo(px, py);
      c.path(pLine, partPaint);
    }
  }
};

class Visual final : public Scene {
  struct CorruptRow {
    float baseShift;
    float blockWidth;
    float blockHeight;
    float chromaOffset;
    float seedPhase;
    float burstShift;
    float burstLife;
    bool hasAlert;
  };

  std::vector<CorruptRow> rows;
  float simTime = 0.0f;
  float lastBurstTime = -10.0f;
  float sparkChromaTimer = 0.0f;
  float trackingY = 0.88f;
  float smoothEnergy = 0.0f;
  float smoothBass = 0.0f;
  // Envolventes de la música para Pulso (cero en silencio).
  float bass = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0;

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }
  static float hashU(uint32_t x) {
    x ^= x >> 16; x *= 0x7feb352dU; x ^= x >> 15; x *= 0x846ca68bU; x ^= x >> 16;
    return float(x & 0xffffffu) / 16777216.0f;
  }

 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    rows.clear();
    rows.reserve(90);
    simTime = 0.0f;
    lastBurstTime = -10.0f;
    sparkChromaTimer = 0.0f;
    trackingY = 0.88f;
    smoothEnergy = 0.0f;
    smoothBass = 0.0f;
    bass = spark = energy = slowBass = kick = flash = 0.0f;

    for (int i = 0; i < 90; i++) {
      CorruptRow r;
      r.baseShift = (rng.unit() - 0.5f) * 24.0f;
      r.blockWidth = 8.0f + rng.unit() * 32.0f;
      r.blockHeight = 2.0f + rng.unit() * 4.0f;
      r.chromaOffset = 4.0f + rng.unit() * 14.0f;
      r.seedPhase = rng.unit() * 6.2831853f;
      r.burstShift = 0.0f;
      r.burstLife = 0.0f;
      r.hasAlert = rng.unit() < 0.14f;
      rows.push_back(r);
    }
  }

  void update(const Frame& f) override {
    float dt = float(f.delta);
    // Música para Pulso: envolventes y golpes (todo vale cero en silencio).
    const Music& mu = f.music;
    bass = follow(bass, mu.bass, 22.0f, 4.5f, dt);
    spark = follow(spark, mu.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, mu.energy, 6.0f, 1.8f, dt);
    float hit = 0, fl = 0;
    for (const auto& e : mu.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : mu.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : mu.events[3]) fl = std::max(fl, e.strength);
    const float onset = std::clamp((mu.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, mu.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));

    float targetEnergy = f.music.active ? f.music.energy : 0.0f;
    float targetBass = f.music.active ? f.music.bass : 0.0f;
    float targetSpark = f.music.active ? f.music.spark : 0.0f;

    smoothEnergy += (targetEnergy - smoothEnergy) * float(1.0 - std::exp(-dt * 5.0));
    smoothBass += (targetBass - smoothBass) * float(1.0 - std::exp(-dt * 6.0));

    // En silencio reposa en un barrido CRT limpio con mínima deriva (~0.12f).
    // Con música acelera el datamosh glitch y los saltos cromáticos.
    float audioDrive = 0.12f + smoothEnergy * 0.72f + smoothBass * 0.35f;
    float speedMult = (f.reducedMotion ? 0.25f : 1.0f) * f.speed * audioDrive;
    simTime += dt * speedMult;

    // Detección de ráfaga de desplazamiento en bombos fuertes con música activa
    if (f.music.active && (targetSpark > 0.65f || smoothBass > 0.72f) && (simTime - lastBurstTime >= 1.8f)) {
      lastBurstTime = simTime;
      Random burstRng(uint32_t(simTime * 1000.0f) ^ 0x30303);
      int centerRow = int(burstRng.unit() * 70.0f) + 10;
      for (int i = 0; i < 90; i++) {
        if (std::abs(i - centerRow) < 22 || burstRng.unit() < 0.28f) {
          rows[i].burstLife = 0.30f;
          float sgn = burstRng.unit() > 0.5f ? 1.0f : -1.0f;
          rows[i].burstShift = sgn * (28.0f + burstRng.unit() * 65.0f);
        }
      }
    }

    // Salto cromático de 120ms en chispas agudas con música activa
    if (f.music.active && targetSpark > 0.60f) {
      sparkChromaTimer = 0.12f;
    }
    if (sparkChromaTimer > 0.0f) {
      sparkChromaTimer = std::max(0.0f, sparkChromaTimer - dt);
    }

    for (auto& r : rows) {
      if (r.burstLife > 0.0f) {
        r.burstLife = std::max(0.0f, r.burstLife - dt);
      }
    }
  }

  void render(const Frame& f, Canvas& c) const override {
    auto g = glide(f);
    float w = f.width, h = f.height;
    float time = simTime;
    // Carácter: Entrecortado congela la imagen y la hace avanzar a saltos.
    if (g.caracter.weight(1) > 0.0f) {
      const float stepped = std::floor(simTime * 5.0f) / 5.0f;
      time = simTime * g.caracter.weight(0) + stepped * g.caracter.weight(1);
    }
    const float amp = f.intensity;
    // Pulso: sus pesos reparten la reacción; todo vale cero sin música.
    const float punch = std::min(kick * amp, 1.0f) * g.pulso.weight(0);
    const float swell = std::min(bass * amp, 1.0f) * g.pulso.weight(1);
    const float glint = std::min(spark * amp, 1.0f) * g.pulso.weight(2);
    const uint32_t tick = uint32_t(std::floor(simTime * 24.0f));
    std::vector<Vec2> deadPixels;

    // 1. Degradado base cyberpunk: #0a0a12 a #1a1030
    Paint bg = Paint::linear({0.0f, 0.0f}, {0.0f, h},
      {Color::argb(0xff0a0a12), Color::argb(0xff120d22), Color::argb(0xff1a1030)},
      {0.0f, 0.5f, 1.0f});
    c.rect({0, 0, w, h}, bg);

    // Barrido CRT: líneas horizontales sutiles cada 4px
    Paint scanline;
    scanline.color = {0.02f, 0.015f, 0.04f, 0.45f};
    scanline.strokeWidth = 1.4f;
    Path scanlines;
    for (float y = 0.0f; y < h; y += 4.0f) {
      scanlines.moveTo(0.0f, y);
      scanlines.lineTo(w, y);
    }
    c.path(scanlines, scanline);

    // Resplandor local de la música sobre la franja de datos (nunca a pantalla
    // completa): magenta en cada golpe, violeta con los graves y cian que
    // parpadea con los agudos.
    if (punch > 0.0f || swell > 0.0f || glint > 0.0f) {
      const float side = std::min(w, h);
      const float auraR = side * 0.62f * (1.0f + 0.12f * punch + 0.15f * swell);
      const float flicker = 0.55f + 0.45f * std::sin(simTime * 61.0f);
      const float warm = (0.4f * punch + 0.3f * swell) * f.glow;
      const float cool = (0.18f * swell + 0.32f * glint * flicker) * f.glow;
      Paint aura = Paint::radial({w * 0.5f, h * 0.45f}, auraR,
        {{std::clamp(0.4f + 0.6f * warm / std::max(warm + cool, 0.001f), 0.0f, 1.0f), 0.3f,
          std::clamp(0.53f + 0.47f * cool / std::max(warm + cool, 0.001f), 0.0f, 1.0f), std::clamp(warm + cool, 0.0f, 1.0f)},
         {1.0f, 0.18f, 0.53f, std::clamp((warm + cool) * 0.35f, 0.0f, 1.0f)},
         {1.0f, 0.18f, 0.53f, 0.0f}}, {0.0f, 0.5f, 1.0f});
      aura.blend = Blend::plus;
      c.circle({w * 0.5f, h * 0.45f}, auraR, aura);
    }

    float chromaJump = sparkChromaTimer > 0.0f ? 18.0f * (sparkChromaTimer / 0.12f) : 0.0f;
    float densityThreshold = 0.25f + smoothEnergy * 0.58f;
    // Golpes y Graves: se encienden más filas de datos.
    if (punch > 0.0f || swell > 0.0f) densityThreshold += 0.22f * punch + 0.18f * swell;
    float rowStep = h / 90.0f;

    Path pathR, pathB, pathLuma, pathAlert;

    for (int i = 0; i < 90; i++) {
      const auto& r = rows[i];

      // Onda de datamosh continuo
      float structuralWave =
        std::sin(float(i) * 0.16f + time * 1.8f + r.seedPhase) *
        std::cos(float(i) * 0.05f - time * 0.9f);
      float activeScore = std::abs(structuralWave) + (r.burstLife > 0.0f ? 0.8f : 0.0f);
      if (activeScore < 1.0f - densityThreshold) continue;

      float y = float(i) * rowStep;
      float bh = r.blockHeight;
      // Graves: los bloques engordan despacio; Golpes: de golpe.
      if (swell > 0.0f || punch > 0.0f) bh *= 1.0f + 0.9f * swell + 1.1f * punch;
      float bw = r.blockWidth * (w / 380.0f);
      // Ancho de bloque (1 = el original).
      bw *= g.bloques;
      float burstFactor = r.burstLife / 0.30f;
      float shiftX = w * 0.5f + structuralWave * (w * 0.26f) + r.baseShift + r.burstShift * burstFactor;
      // Golpes: cada golpe sacude la fila hacia un lado.
      if (punch > 0.0f) shiftX += punch * w * 0.09f * (std::sin(r.seedPhase * 7.0f) >= 0.0f ? 1.0f : -1.0f);
      float cOff = r.chromaOffset + chromaJump + burstFactor * 12.0f;
      // Aberración: separación de los canales (1 = la original).
      cOff *= g.aberracion;
      // Golpes abre los canales; Agudos los hace temblar.
      if (punch > 0.0f || glint > 0.0f) cOff += punch * 14.0f + glint * 14.0f * std::sin(simTime * 57.0f + float(i) * 1.3f);

      int clusterCount = r.burstLife > 0.0f ? 4 : 2;
      for (int k = 0; k < clusterCount; k++) {
        float bx = shiftX + float(k - 1) * (bw * 1.35f);

        // Canal Rojo desplazado hacia la izquierda
        pathR.rect({bx - cOff, y, bw, bh});

        // Canal Azul desplazado hacia la derecha
        float yOffB = sparkChromaTimer > 0.0f ? 2.0f : 0.0f;
        pathB.rect({bx + cOff, y + yOffB, bw, bh});

        // Bloque central Luma
        pathLuma.rect({bx, y, bw * 0.78f, bh});

        if (r.hasAlert && k == 0 && (r.burstLife > 0.0f || structuralWave > 0.65f)) {
          pathAlert.rect({bx + bw * 0.9f, y, 10.0f, bh + 1.0f});
        }

        // Agudos: píxeles muertos que parpadean sobre los bloques.
        if (glint > 0.0f && hashU(uint32_t(i * 4 + k) * 2654435761u + tick * 40503u) < glint * 0.8f) {
          deadPixels.push_back({bx + bw * hashU(uint32_t(i * 4 + k) * 747796405u + tick), y + bh * 0.5f});
        }
      }
    }

    // Dibujado aditivo de canales RGB
    float boost = std::clamp((0.75f + smoothEnergy * 0.35f) * f.intensity, 0.0f, 1.0f);

    // Canal Magenta #ff2e88
    Paint pR; pR.blend = Blend::plus;
    pR.color = {1.0f, 0.18f, 0.53f, std::clamp(0.78f * boost + 0.22f * punch, 0.0f, 1.0f)};
    c.path(pathR, pR);

    // Canal Cian #00f0ff
    Paint pB; pB.blend = Blend::plus;
    pB.color = {0.0f, 0.94f, 1.0f, std::clamp(0.78f * boost + 0.22f * punch, 0.0f, 1.0f)};
    c.path(pathB, pB);

    // Canal Luma claro
    Paint pLuma; pLuma.blend = Blend::plus;
    pLuma.color = {0.90f, 0.94f, 1.0f, std::clamp(0.42f * boost + 0.58f * punch, 0.0f, 1.0f)};
    c.path(pathLuma, pLuma);

    // Canal de alertas doradas #ffe14d
    Paint pAlert; pAlert.blend = Blend::plus;
    pAlert.color = {1.0f, 0.88f, 0.30f, std::clamp(0.95f * boost, 0.0f, 1.0f)};
    c.path(pathAlert, pAlert);

    if (!deadPixels.empty()) {
      Paint dead; dead.blend = Blend::plus;
      dead.color = {0.92f, 0.96f, 1.0f, std::clamp(1.0f * glint, 0.0f, 1.0f)};
      c.points(deadPixels, 2.4f, dead);
    }

    // 2. Franja VHS rodante de sincronismo inferior
    float trackNormY = 0.89f + 0.04f * std::sin(time * 1.7f);
    float trackY = h * trackNormY;
    float trackH = 18.0f + smoothBass * 14.0f;
    // Golpes: la franja VHS se ensancha con cada golpe.
    if (punch > 0.0f) trackH *= 1.0f + 1.2f * punch;

    Paint trackGrad = Paint::linear({0.0f, trackY}, {0.0f, trackY + trackH},
      {{1.0f, 0.18f, 0.53f, 0.0f},
       {0.0f, 0.94f, 1.0f, std::clamp(0.35f * boost, 0.0f, 1.0f)},
       {1.0f, 0.18f, 0.53f, std::clamp(0.45f * boost, 0.0f, 1.0f)},
       {0.04f, 0.04f, 0.07f, 0.0f}},
      {0.0f, 0.35f, 0.65f, 1.0f});
    trackGrad.blend = Blend::plus;
    c.rect({0, trackY, w, trackH}, trackGrad);

    // Rasgaduras de sincronismo horizontales en la franja
    Path tearPath;
    for (int k = 0; k < 6; k++) {
      float sliceX = std::fmod(time * 220.0f + float(k) * 83.0f, w + 40.0f) - 20.0f;
      tearPath.rect({sliceX, trackY + float(k) * 2.5f, 36.0f, 1.8f});
    }
    Paint tearPaint; tearPaint.blend = Blend::plus;
    tearPaint.color = {1.0f, 0.88f, 0.30f, std::clamp(0.55f * boost, 0.0f, 1.0f)};
    c.path(tearPath, tearPaint);
  }
};

class Visual final : public Scene {
  struct CorruptRow {
    float baseShift;
    float blockWidth;
    float blockHeight;
    float chromaOffset;
    float seedPhase;
    float burstShift;
    float burstLife;
    bool hasAlert;
  };

  std::vector<CorruptRow> rows;
  float simTime = 0.0f;
  float lastBurstTime = -10.0f;
  float sparkChromaTimer = 0.0f;
  float trackingY = 0.88f;
  float smoothEnergy = 0.0f;
  float smoothBass = 0.0f;
  // Envolventes de la música para Pulso (cero en silencio).
  float bass = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0;

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }
  static float hashU(uint32_t x) {
    x ^= x >> 16; x *= 0x7feb352dU; x ^= x >> 15; x *= 0x846ca68bU; x ^= x >> 16;
    return float(x & 0xffffffu) / 16777216.0f;
  }

 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    rows.clear();
    rows.reserve(90);
    simTime = 0.0f;
    lastBurstTime = -10.0f;
    sparkChromaTimer = 0.0f;
    trackingY = 0.88f;
    smoothEnergy = 0.0f;
    smoothBass = 0.0f;
    bass = spark = energy = slowBass = kick = flash = 0.0f;

    for (int i = 0; i < 90; i++) {
      CorruptRow r;
      r.baseShift = (rng.unit() - 0.5f) * 24.0f;
      r.blockWidth = 8.0f + rng.unit() * 32.0f;
      r.blockHeight = 2.0f + rng.unit() * 4.0f;
      r.chromaOffset = 4.0f + rng.unit() * 14.0f;
      r.seedPhase = rng.unit() * 6.2831853f;
      r.burstShift = 0.0f;
      r.burstLife = 0.0f;
      r.hasAlert = rng.unit() < 0.14f;
      rows.push_back(r);
    }
  }

  void update(const Frame& f) override {
    float dt = float(f.delta);
    // Música para Pulso: envolventes y golpes (todo vale cero en silencio).
    const Music& mu = f.music;
    bass = follow(bass, mu.bass, 22.0f, 4.5f, dt);
    spark = follow(spark, mu.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, mu.energy, 6.0f, 1.8f, dt);
    float hit = 0, fl = 0;
    for (const auto& e : mu.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : mu.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : mu.events[3]) fl = std::max(fl, e.strength);
    const float onset = std::clamp((mu.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, mu.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));

    float targetEnergy = f.music.active ? f.music.energy : 0.0f;
    float targetBass = f.music.active ? f.music.bass : 0.0f;
    float targetSpark = f.music.active ? f.music.spark : 0.0f;

    smoothEnergy += (targetEnergy - smoothEnergy) * float(1.0 - std::exp(-dt * 5.0));
    smoothBass += (targetBass - smoothBass) * float(1.0 - std::exp(-dt * 6.0));

    // En silencio reposa en un barrido CRT limpio con mínima deriva (~0.12f).
    // Con música acelera el datamosh glitch y los saltos cromáticos.
    float audioDrive = 0.12f + smoothEnergy * 0.72f + smoothBass * 0.35f;
    float speedMult = (f.reducedMotion ? 0.25f : 1.0f) * f.speed * audioDrive;
    simTime += dt * speedMult;

    // Detección de ráfaga de desplazamiento en bombos fuertes con música activa
    if (f.music.active && (targetSpark > 0.65f || smoothBass > 0.72f) && (simTime - lastBurstTime >= 1.8f)) {
      lastBurstTime = simTime;
      Random burstRng(uint32_t(simTime * 1000.0f) ^ 0x30303);
      int centerRow = int(burstRng.unit() * 70.0f) + 10;
      for (int i = 0; i < 90; i++) {
        if (std::abs(i - centerRow) < 22 || burstRng.unit() < 0.28f) {
          rows[i].burstLife = 0.30f;
          float sgn = burstRng.unit() > 0.5f ? 1.0f : -1.0f;
          rows[i].burstShift = sgn * (28.0f + burstRng.unit() * 65.0f);
        }
      }
    }

    // Salto cromático de 120ms en chispas agudas con música activa
    if (f.music.active && targetSpark > 0.60f) {
      sparkChromaTimer = 0.12f;
    }
    if (sparkChromaTimer > 0.0f) {
      sparkChromaTimer = std::max(0.0f, sparkChromaTimer - dt);
    }

    for (auto& r : rows) {
      if (r.burstLife > 0.0f) {
        r.burstLife = std::max(0.0f, r.burstLife - dt);
      }
    }
  }

  void render(const Frame& f, Canvas& c) const override {
    auto g = glide(f);
    float w = f.width, h = f.height;
    float time = simTime;
    // Carácter: Entrecortado congela la imagen y la hace avanzar a saltos.
    if (g.caracter.weight(1) > 0.0f) {
      const float stepped = std::floor(simTime * 5.0f) / 5.0f;
      time = simTime * g.caracter.weight(0) + stepped * g.caracter.weight(1);
    }
    const float amp = f.intensity;
    // Pulso: sus pesos reparten la reacción; todo vale cero sin música.
    const float punch = std::min(kick * amp, 1.0f) * g.pulso.weight(0);
    const float swell = std::min(bass * amp, 1.0f) * g.pulso.weight(1);
    const float glint = std::min(spark * amp, 1.0f) * g.pulso.weight(2);
    const uint32_t tick = uint32_t(std::floor(simTime * 24.0f));
    std::vector<Vec2> deadPixels;

    // Sin fondo opaco: lienzo 100% transparente para efecto HUD / filtro glitch

    // Resplandor local de la música sobre la franja de datos (nunca a pantalla
    // completa): magenta en cada golpe, violeta con los graves y cian que
    // parpadea con los agudos.
    if (punch > 0.0f || swell > 0.0f || glint > 0.0f) {
      const float side = std::min(w, h);
      const float auraR = side * 0.62f * (1.0f + 0.12f * punch + 0.15f * swell);
      const float flicker = 0.55f + 0.45f * std::sin(simTime * 61.0f);
      const float warm = (0.4f * punch + 0.3f * swell) * f.glow;
      const float cool = (0.18f * swell + 0.32f * glint * flicker) * f.glow;
      Paint aura = Paint::radial({w * 0.5f, h * 0.45f}, auraR,
        {{std::clamp(0.4f + 0.6f * warm / std::max(warm + cool, 0.001f), 0.0f, 1.0f), 0.3f,
          std::clamp(0.53f + 0.47f * cool / std::max(warm + cool, 0.001f), 0.0f, 1.0f), std::clamp(warm + cool, 0.0f, 1.0f)},
         {1.0f, 0.18f, 0.53f, std::clamp((warm + cool) * 0.35f, 0.0f, 1.0f)},
         {1.0f, 0.18f, 0.53f, 0.0f}}, {0.0f, 0.5f, 1.0f});
      aura.blend = Blend::plus;
      c.circle({w * 0.5f, h * 0.45f}, auraR, aura);
    }

    float chromaJump = sparkChromaTimer > 0.0f ? 18.0f * (sparkChromaTimer / 0.12f) : 0.0f;
    float densityThreshold = 0.25f + smoothEnergy * 0.58f;
    // Golpes y Graves: se encienden más filas de datos.
    if (punch > 0.0f || swell > 0.0f) densityThreshold += 0.22f * punch + 0.18f * swell;
    float rowStep = h / 90.0f;

    Path pathR, pathB, pathLuma, pathAlert;

    for (int i = 0; i < 90; i++) {
      const auto& r = rows[i];

      // Onda de datamosh continuo
      float structuralWave =
        std::sin(float(i) * 0.16f + time * 1.8f + r.seedPhase) *
        std::cos(float(i) * 0.05f - time * 0.9f);
      float activeScore = std::abs(structuralWave) + (r.burstLife > 0.0f ? 0.8f : 0.0f);
      if (activeScore < 1.0f - densityThreshold) continue;

      float y = float(i) * rowStep;
      float bh = r.blockHeight;
      // Graves: los bloques engordan despacio; Golpes: de golpe.
      if (swell > 0.0f || punch > 0.0f) bh *= 1.0f + 0.9f * swell + 1.1f * punch;
      float bw = r.blockWidth * (w / 380.0f);
      // Ancho de bloque (1 = el original).
      bw *= g.bloques;
      float burstFactor = r.burstLife / 0.30f;
      float shiftX = w * 0.5f + structuralWave * (w * 0.26f) + r.baseShift + r.burstShift * burstFactor;
      // Golpes: cada golpe sacude la fila hacia un lado.
      if (punch > 0.0f) shiftX += punch * w * 0.09f * (std::sin(r.seedPhase * 7.0f) >= 0.0f ? 1.0f : -1.0f);
      float cOff = r.chromaOffset + chromaJump + burstFactor * 12.0f;
      // Aberración: separación de los canales (1 = la original).
      cOff *= g.aberracion;
      // Golpes abre los canales; Agudos los hace temblar.
      if (punch > 0.0f || glint > 0.0f) cOff += punch * 14.0f + glint * 14.0f * std::sin(simTime * 57.0f + float(i) * 1.3f);

      int clusterCount = r.burstLife > 0.0f ? 4 : 2;
      for (int k = 0; k < clusterCount; k++) {
        float bx = shiftX + float(k - 1) * (bw * 1.35f);

        // Canal Rojo desplazado hacia la izquierda
        pathR.rect({bx - cOff, y, bw, bh});

        // Canal Azul desplazado hacia la derecha
        float yOffB = sparkChromaTimer > 0.0f ? 2.0f : 0.0f;
        pathB.rect({bx + cOff, y + yOffB, bw, bh});

        // Bloque central Luma
        pathLuma.rect({bx, y, bw * 0.78f, bh});

        if (r.hasAlert && k == 0 && (r.burstLife > 0.0f || structuralWave > 0.65f)) {
          pathAlert.rect({bx + bw * 0.9f, y, 10.0f, bh + 1.0f});
        }

        // Agudos: píxeles muertos que parpadean sobre los bloques.
        if (glint > 0.0f && hashU(uint32_t(i * 4 + k) * 2654435761u + tick * 40503u) < glint * 0.8f) {
          deadPixels.push_back({bx + bw * hashU(uint32_t(i * 4 + k) * 747796405u + tick), y + bh * 0.5f});
        }
      }
    }

    // Dibujado aditivo de canales RGB
    float boost = std::clamp((0.75f + smoothEnergy * 0.35f) * f.intensity, 0.0f, 1.0f);

    // Canal Magenta #ff2e88
    Paint pR; pR.blend = Blend::plus;
    pR.color = {1.0f, 0.18f, 0.53f, std::clamp(0.78f * boost + 0.22f * punch, 0.0f, 1.0f)};
    c.path(pathR, pR);

    // Canal Cian #00f0ff
    Paint pB; pB.blend = Blend::plus;
    pB.color = {0.0f, 0.94f, 1.0f, std::clamp(0.78f * boost + 0.22f * punch, 0.0f, 1.0f)};
    c.path(pathB, pB);

    // Canal Luma claro
    Paint pLuma; pLuma.blend = Blend::plus;
    pLuma.color = {0.90f, 0.94f, 1.0f, std::clamp(0.42f * boost + 0.58f * punch, 0.0f, 1.0f)};
    c.path(pathLuma, pLuma);

    // Canal de alertas doradas #ffe14d
    Paint pAlert; pAlert.blend = Blend::plus;
    pAlert.color = {1.0f, 0.88f, 0.30f, std::clamp(0.95f * boost, 0.0f, 1.0f)};
    c.path(pathAlert, pAlert);

    if (!deadPixels.empty()) {
      Paint dead; dead.blend = Blend::plus;
      dead.color = {0.92f, 0.96f, 1.0f, std::clamp(1.0f * glint, 0.0f, 1.0f)};
      c.points(deadPixels, 2.4f, dead);
    }

    // Franja VHS rodante de sincronismo inferior
    float trackNormY = 0.89f + 0.04f * std::sin(time * 1.7f);
    float trackY = h * trackNormY;
    float trackH = 18.0f + smoothBass * 14.0f;
    // Golpes: la franja VHS se ensancha con cada golpe.
    if (punch > 0.0f) trackH *= 1.0f + 1.2f * punch;

    Paint trackGrad = Paint::linear({0.0f, trackY}, {0.0f, trackY + trackH},
      {{1.0f, 0.18f, 0.53f, 0.0f},
       {0.0f, 0.94f, 1.0f, std::clamp(0.35f * boost, 0.0f, 1.0f)},
       {1.0f, 0.18f, 0.53f, std::clamp(0.45f * boost, 0.0f, 1.0f)},
       {0.04f, 0.04f, 0.07f, 0.0f}},
      {0.0f, 0.35f, 0.65f, 1.0f});
    trackGrad.blend = Blend::plus;
    c.rect({0, trackY, w, trackH}, trackGrad);

    // Rasgaduras de sincronismo horizontales en la franja
    Path tearPath;
    for (int k = 0; k < 6; k++) {
      float sliceX = std::fmod(time * 220.0f + float(k) * 83.0f, w + 40.0f) - 20.0f;
      tearPath.rect({sliceX, trackY + float(k) * 2.5f, 36.0f, 1.8f});
    }
    Paint tearPaint; tearPaint.blend = Blend::plus;
    tearPaint.color = {1.0f, 0.88f, 0.30f, std::clamp(0.55f * boost, 0.0f, 1.0f)};
    c.path(tearPath, tearPaint);
  }
};

class Visual final : public Scene {
  struct Planet {
    float radiusRatio;
    float size;
    float basePeriod;
    float inclination;
    float tiltAngle;
    bool retrograde;
    Color color;
    float angle;
  };

  std::vector<Planet> planets;
  float clockTime = 0.0f;
  float smoothEnergy = 0.0f;
  float smoothBass = 0.0f;
  float smoothSpark = 0.0f;
  // Fase de la precesión (sólo se ve si Precesión > 0).
  double precPhase = 0.0;
  // Envolventes de la música para Pulso (cero en silencio) y el último golpe.
  float bass = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0;
  double ringAge = 100.0;
  float ringPower = 0.0f;

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }
  static float hashU(uint32_t x) {
    x ^= x >> 16; x *= 0x7feb352dU; x ^= x >> 15; x *= 0x846ca68bU; x ^= x >> 16;
    return float(x & 0xffffffu) / 16777216.0f;
  }
  // Precesión: cada plano gira a su ritmo, en sentidos alternos.
  float tiltOf(size_t i, float base, float prec) const {
    if (prec <= 0.0f) return base;
    const float rate = (i % 2 == 0 ? 1.0f : -1.0f) * (0.6f + 0.25f * float(i));
    return base + float(std::fmod(precPhase, 1000.0)) * rate * prec;
  }

 public:
  void reset(uint32_t seed) override {
    (void)seed;
    planets.clear();
    planets.reserve(4);
    clockTime = 0.0f;
    smoothEnergy = 0.0f;
    smoothBass = 0.0f;
    smoothSpark = 0.0f;
    precPhase = 0.0;
    bass = spark = energy = slowBass = kick = flash = 0.0f;
    ringAge = 100.0; ringPower = 0.0f;

    // Cobre
    planets.push_back({0.19f, 8.5f, 14.0f, 0.0f, 0.20f, false, {0.85f, 0.55f, 0.29f, 1.0f}, 0.8f});
    // Bronce
    planets.push_back({0.27f, 7.0f, 8.5f, 0.36f, 0.65f, false, {0.72f, 0.63f, 0.42f, 1.0f}, 2.3f});
    // Acero
    planets.push_back({0.35f, 9.5f, 11.2f, 0.42f, -0.50f, false, {0.44f, 0.62f, 0.77f, 1.0f}, 4.1f});
    // Jade (retrogrado)
    planets.push_back({0.42f, 6.5f, 6.8f, 0.15f, 1.10f, true, {0.37f, 0.75f, 0.63f, 1.0f}, 5.4f});
  }

  void update(const Frame& f) override {
    float dt = float(f.delta);
    float targetEnergy = f.music.active ? f.music.energy : 0.0f;
    float targetBass = f.music.active ? f.music.bass : 0.0f;
    float targetSpark = f.music.active ? f.music.spark : 0.0f;
    smoothEnergy += (targetEnergy - smoothEnergy) * float(1.0 - std::exp(-dt * 5.0));
    smoothBass += (targetBass - smoothBass) * float(1.0 - std::exp(-dt * 6.0));
    smoothSpark += (targetSpark - smoothSpark) * float(1.0 - std::exp(-dt * 15.0));

    // En silencio reposa en un tic-tac de reloj celestial sereno y majestuoso (~0.12f).
    // Con música la maquinaria de relojería se revoluciona al compás del ritmo.
    float audioDrive = 0.12f + smoothEnergy * 0.76f + smoothBass * 0.35f;
    float speedFactor = (f.reducedMotion ? 0.25f : 1.0f) * f.speed * audioDrive;
    clockTime += dt * speedFactor;

    for (auto& p : planets) {
      float dir = p.retrograde ? -1.0f : 1.0f;
      p.angle += dir * (6.2831853f / p.basePeriod) * dt * speedFactor;
    }

    precPhase += f.delta * double(f.speed) * (f.reducedMotion ? 0.1 : 0.35);
    // Música para Pulso: envolventes y golpes (todo vale cero en silencio).
    const Music& mu = f.music;
    bass = follow(bass, mu.bass, 22.0f, 4.5f, dt);
    spark = follow(spark, mu.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, mu.energy, 6.0f, 1.8f, dt);
    float hit = 0, fl = 0;
    for (const auto& e : mu.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : mu.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : mu.events[3]) fl = std::max(fl, e.strength);
    const float onset = std::clamp((mu.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, mu.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    const bool fresh = hit > kick + 0.2f;
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    ringAge += f.delta;
    if (fresh) { ringAge = 0.0; ringPower = hit; }
  }

  void render(const Frame& f, Canvas& c) const override {
    float w = f.width, h = f.height;
    float minDim = std::min(w, h);
    Vec2 center{w * 0.5f, h * 0.5f};
    float time = clockTime;
    float boost = std::clamp((0.85f + smoothEnergy * 0.35f) * f.intensity, 0.0f, 1.0f);
    auto g = glide(f);
    const float amp = f.intensity;
    // Pulso: sus pesos reparten la reacción; todo vale cero sin música.
    const float punch = std::min(kick * amp, 1.0f) * g.pulso.weight(0);
    const float swell = std::min(bass * amp, 1.0f) * g.pulso.weight(1);
    const float glint = std::min(spark * amp, 1.0f) * g.pulso.weight(2);
    const float tiltK = g.inclinacion;
    const float prec = g.precesion;

    // 1. Fondo de piedra tallada #14100c con núcleo ámbar
    Paint bg = Paint::radial(center, minDim * 0.75f,
      {Color::argb(0xff1e1812), Color::argb(0xff14100c), Color::argb(0xff090705)},
      {0.0f, 0.55f, 1.0f});
    c.rect({0, 0, w, h}, bg);

    // Barras diagonales estructurales de latón
    Paint crossbar;
    crossbar.color = {0.42f, 0.35f, 0.23f, std::clamp(0.28f * boost, 0.0f, 1.0f)};
    crossbar.strokeWidth = 1.5f;
    Path cross;
    for (int a = 0; a < 4; a++) {
      float ang = (float(a) * 3.14159265f * 0.5f) + 0.785398f;
      cross.moveTo(center.x + std::cos(ang) * minDim * 0.07f, center.y + std::sin(ang) * minDim * 0.07f);
      cross.lineTo(center.x + std::cos(ang) * minDim * 0.46f, center.y + std::sin(ang) * minDim * 0.46f);
    }
    c.path(cross, crossbar);

    // Resplandor local de la música sobre la maquinaria (nunca a pantalla
    // completa): cobre en cada golpe y con los graves, azul acero que
    // parpadea con los agudos.
    if (punch > 0.0f || swell > 0.0f || glint > 0.0f) {
      const float auraR = minDim * 0.6f * (1.0f + 0.12f * punch + 0.15f * swell);
      const float flicker = 0.55f + 0.45f * std::sin(float(f.time) * 43.0f);
      const float warm = (0.4f * punch + 0.32f * swell) * f.glow;
      const float cool = 0.3f * glint * flicker * f.glow;
      Paint auraWarm = Paint::radial(center, auraR,
        {{0.85f, 0.55f, 0.29f, std::clamp(warm, 0.0f, 1.0f)},
         {0.85f, 0.55f, 0.29f, std::clamp(warm * 0.7f, 0.0f, 1.0f)},
         {0.85f, 0.55f, 0.29f, 0.0f}}, {0.0f, 0.62f, 1.0f});
      auraWarm.blend = Blend::plus;
      if (warm > 0.0f) c.circle(center, auraR, auraWarm);
      Paint auraCool = Paint::radial(center, auraR,
        {{0.44f, 0.62f, 0.77f, std::clamp(cool, 0.0f, 1.0f)}, {0.44f, 0.62f, 0.77f, 0.0f}}, {0.0f, 1.0f});
      auraCool.blend = Blend::plus;
      if (cool > 0.0f) c.circle(center, auraR, auraCool);
    }

    // 2. Bisel exterior de la corona graduada con 96 muescas y glifos
    float crownTilt = (f.music.flow - 0.5f) * 0.16f;
    float outerR = minDim * 0.455f;
    float innerR = minDim * 0.415f;

    c.save();
    c.translate(center.x, center.y);
    c.rotate(crownTilt);

    // Aros del bisel
    Paint bezel;
    // Golpes: el bisel se enciende con cada golpe.
    bezel.color = {0.72f, 0.63f, 0.42f, std::clamp(0.38f * boost + 0.62f * punch, 0.0f, 1.0f)};
    bezel.strokeWidth = 1.8f;
    if (punch > 0.0f) bezel.strokeWidth *= 1.0f + 1.3f * punch;
    c.circle({0, 0}, outerR, bezel);
    c.circle({0, 0}, innerR, bezel);

    // 96 marcas graduadas en el bisel
    Path ticks;
    for (int i = 0; i < 96; i++) {
      float ang = (float(i) / 96.0f) * 6.2831853f;
      bool isMajor = (i % 8 == 0);
      float r0 = isMajor ? innerR : innerR + (outerR - innerR) * 0.45f;
      ticks.moveTo(std::cos(ang) * r0, std::sin(ang) * r0);
      ticks.lineTo(std::cos(ang) * outerR, std::sin(ang) * outerR);
    }
    Paint tickPaint;
    tickPaint.color = {0.72f, 0.63f, 0.42f, std::clamp(0.48f * boost + 0.52f * punch, 0.0f, 1.0f)};
    tickPaint.strokeWidth = 1.0f;
    c.path(ticks, tickPaint);

    // 12 Glifos geométricos abstractos
    float midRingR = (outerR + innerR) * 0.5f;
    float glyphR = minDim * 0.012f;
    Path glyphsPath;
    for (int s = 0; s < 12; s++) {
      float ang = (float(s) / 12.0f) * 6.2831853f + 0.130899f;
      float gx = std::cos(ang) * midRingR;
      float gy = std::sin(ang) * midRingR;

      if (s % 3 == 0) {
        // Rombo con punto central
        glyphsPath.moveTo(gx, gy - glyphR);
        glyphsPath.lineTo(gx + glyphR, gy);
        glyphsPath.lineTo(gx, gy + glyphR);
        glyphsPath.lineTo(gx - glyphR, gy);
        glyphsPath.close();
      } else if (s % 3 == 1) {
        // Círculo / bisector
        glyphsPath.circle({gx, gy}, glyphR * 0.75f);
      } else {
        // Triángulo
        glyphsPath.moveTo(gx, gy - glyphR);
        glyphsPath.lineTo(gx + glyphR * 0.9f, gy + glyphR * 0.8f);
        glyphsPath.lineTo(gx - glyphR * 0.9f, gy + glyphR * 0.8f);
        glyphsPath.close();
      }
    }
    Paint glyphPaint;
    glyphPaint.color = {0.85f, 0.55f, 0.29f, std::clamp(0.65f * boost, 0.0f, 1.0f)};
    glyphPaint.strokeWidth = 1.2f;
    c.path(glyphsPath, glyphPaint);

    // Agudos: los glifos centellean uno a uno.
    if (glint > 0.0f) {
      const uint32_t tick = uint32_t(std::floor(f.time * 10.0));
      Path sparkGlyphs;
      for (int s = 0; s < 12; s++) {
        if (hashU(uint32_t(s) * 2654435761u + tick * 40503u) >= glint * 0.95f) continue;
        float ang = (float(s) / 12.0f) * 6.2831853f + 0.130899f;
        sparkGlyphs.circle({std::cos(ang) * midRingR, std::sin(ang) * midRingR}, glyphR * 2.0f);
      }
      // Y destellos que corren por las 96 muescas.
      std::vector<Vec2> tickSparks;
      for (int i = 0; i < 96; i++) {
        if (hashU(uint32_t(i) * 747796405u + tick * 2891336453u) >= glint * 0.5f) continue;
        const float ang = (float(i) / 96.0f) * 6.2831853f;
        tickSparks.push_back({std::cos(ang) * outerR, std::sin(ang) * outerR});
      }
      if (!tickSparks.empty()) {
        Paint tickSpark; tickSpark.blend = Blend::plus;
        tickSpark.color = {1.0f, 0.95f, 0.8f, std::clamp(glint, 0.0f, 1.0f)};
        c.points(tickSparks, 2.4f, tickSpark);
      }
      Paint glyphSpark; glyphSpark.blend = Blend::plus;
      glyphSpark.color = {1.0f, 0.9f, 0.6f, std::clamp(0.8f * glint, 0.0f, 1.0f)};
      c.path(sparkGlyphs, glyphSpark);
    }

    // 4 Tornillos ranurados de latón en diagonales
    Paint screwHead; screwHead.color = Color::argb(0xff8b734b);
    Paint screwSlot; screwSlot.color = Color::argb(0xff14100c); screwSlot.strokeWidth = 1.2f;
    for (int k = 0; k < 4; k++) {
      float ang = float(k) * 1.570796f + 0.785398f;
      float sx = std::cos(ang) * (innerR - minDim * 0.018f);
      float sy = std::sin(ang) * (innerR - minDim * 0.018f);
      c.circle({sx, sy}, 4.5f, screwHead);
      Path slot; slot.moveTo(sx - 3.0f, sy - 3.0f); slot.lineTo(sx + 3.0f, sy + 3.0f);
      c.path(slot, screwSlot);
    }

    c.restore();

    // 3. Órbitas elípticas inclinadas con desvanecimiento de profundidad
    for (size_t pi = 0; pi < planets.size(); pi++) {
      const auto& p = planets[pi];
      float orbitR = minDim * p.radiusRatio;
      // Inclinación y Precesión (1 y 0 = las órbitas originales).
      const float tilt = tiltOf(pi, p.tiltAngle, prec);
      const float incl = p.inclination * tiltK;
      float cosTilt = std::cos(tilt);
      float sinTilt = std::sin(tilt);
      float squash = 1.0f - incl * 0.32f;

      for (int half = 0; half < 2; half++) {
        Path orbitHalf;
        int startSeg = half == 0 ? 0 : 64;
        int endSeg = half == 0 ? 64 : 128;
        for (int s = startSeg; s <= endSeg; s++) {
          float theta = (float(s) / 128.0f) * 6.2831853f;
          float lx = std::cos(theta) * orbitR;
          float ly = std::sin(theta) * orbitR * squash;
          float rx = center.x + lx * cosTilt - ly * sinTilt;
          float ry = center.y + lx * sinTilt + ly * cosTilt;
          if (s == startSeg) orbitHalf.moveTo(rx, ry);
          else orbitHalf.lineTo(rx, ry);
        }
        Paint op;
        float alpha = (half == 0 ? 0.35f : 0.14f) * boost;
        op.color = {0.42f, 0.35f, 0.23f, std::clamp(alpha, 0.0f, 1.0f)};
        op.strokeWidth = 1.35f;
        // Graves: las órbitas se encienden de latón y engordan despacio.
        if (swell > 0.0f) {
          op.color = {0.42f + 0.43f * swell, 0.35f + 0.27f * swell, 0.23f + 0.12f * swell,
                      std::clamp(alpha + 0.4f * swell, 0.0f, 1.0f)};
          op.strokeWidth *= 1.0f + 1.4f * swell;
        }
        c.path(orbitHalf, op);
      }
    }

    // 4. Sol central iluminado
    float sunR = minDim * 0.056f;
    float bassGlow = std::clamp((0.25f + smoothBass * 0.75f) * f.intensity, 0.0f, 1.0f);

    // Graves: la corona crece despacio; Golpes: el sol late con cada golpe.
    const float coronaR = sunR * 2.8f * (1.0f + 0.25f * swell + 0.2f * punch);
    const float bodyR = sunR * (1.0f + 0.13f * swell + 0.2f * punch);
    Paint sunCorona = Paint::radial(center, coronaR,
      {{1.0f, 0.88f, 0.59f, std::clamp(0.85f * boost, 0.0f, 1.0f)},
       {0.85f, 0.55f, 0.29f, std::clamp(0.28f * boost, 0.0f, 1.0f)},
       {0, 0, 0, 0}}, {0.0f, 0.45f, 1.0f});
    sunCorona.blend = Blend::plus;
    c.circle(center, coronaR, sunCorona);

    Paint sunBody = Paint::radial({center.x - bodyR * 0.3f, center.y - bodyR * 0.3f}, bodyR,
      {Color::argb(0xfffff4d2), Color::argb(0xffd99b4a), Color::argb(0xff6b4820)},
      {0.0f, 0.6f, 1.0f});
    c.circle(center, bodyR, sunBody);

    // Golpes: un anillo de latón sale del sol hasta el bisel.
    const float ringFade = ringPower * float(std::exp(-ringAge * 2.5)) * g.pulso.weight(0);
    if (ringFade > 0.01f) {
      Paint ring; ring.blend = Blend::plus;
      ring.color = {1.0f, 0.82f, 0.45f, std::clamp(0.95f * ringFade * amp, 0.0f, 1.0f)};
      ring.strokeWidth = 2.0f + 5.0f * ringFade;
      c.circle(center, sunR * 1.4f + float(ringAge) * minDim * 0.7f, ring);
    }

    // Índice dorado giratorio esmaltado (reloj mecánico)
    c.save();
    c.translate(center.x, center.y);
    c.rotate(time * 0.25f);
    Path needle;
    needle.moveTo(0.0f, -sunR * 1.30f);
    needle.lineTo(sunR * 0.28f, 0.0f);
    needle.lineTo(0.0f, sunR * 0.55f);
    needle.lineTo(-sunR * 0.28f, 0.0f);
    needle.close();
    Paint needlePaint;
    needlePaint.color = {1.0f, 0.85f, 0.35f, bassGlow};
    needlePaint.blend = Blend::plus;
    c.path(needle, needlePaint);
    c.restore();

    // 5. Esferas planetarias con sombra arrojada, halo y destello spark
    for (size_t pi = 0; pi < planets.size(); pi++) {
      const auto& p = planets[pi];
      float orbitR = minDim * p.radiusRatio;
      const float tilt = tiltOf(pi, p.tiltAngle, prec);
      const float incl = p.inclination * tiltK;
      float cosTilt = std::cos(tilt);
      float sinTilt = std::sin(tilt);
      float squash = 1.0f - incl * 0.32f;

      float lx = std::cos(p.angle) * orbitR;
      float ly = std::sin(p.angle) * orbitR * squash;
      float px = center.x + lx * cosTilt - ly * sinTilt;
      float py = center.y + lx * sinTilt + ly * cosTilt;

      float depthScale = 1.0f + std::sin(p.angle) * incl * 0.22f;
      float pr = p.size * (minDim / 420.0f) * depthScale;
      // Golpes: los planetas dan un salto; Graves: respiran.
      if (punch > 0.0f || swell > 0.0f) pr *= 1.0f + 0.2f * punch + 0.12f * swell;

      float dx = px - center.x;
      float dy = py - center.y;
      float dist = std::sqrt(dx * dx + dy * dy);
      if (dist < 1.0f) dist = 1.0f;
      float nx = dx / dist;
      float ny = dy / dist;

      // Sombra cónica arrojada hacia el exterior
      Path shadowPoly;
      shadowPoly.moveTo(px - ny * pr * 0.9f, py + nx * pr * 0.9f);
      shadowPoly.lineTo(px + ny * pr * 0.9f, py - nx * pr * 0.9f);
      shadowPoly.lineTo(px + nx * pr * 3.6f + ny * pr * 0.4f, py + ny * pr * 3.6f - nx * pr * 0.4f);
      shadowPoly.lineTo(px + nx * pr * 3.6f - ny * pr * 0.4f, py + ny * pr * 3.6f + nx * pr * 0.4f);
      shadowPoly.close();

      Paint shadowPaint = Paint::linear({px, py}, {px + nx * pr * 3.6f, py + ny * pr * 3.6f},
        {{0.02f, 0.02f, 0.01f, std::clamp(0.78f * boost, 0.0f, 1.0f)}, {0.02f, 0.02f, 0.01f, 0.0f}},
        {0.0f, 1.0f});
      c.path(shadowPoly, shadowPaint);

      // Halo atmosférico del planeta (Halo: 0 lo apaga, 1 = el original)
      float haloR = pr * (2.6f + smoothSpark * 1.8f);
      haloR *= g.halo;
      // Golpes y Graves: el halo de cada planeta crece y se aviva.
      if (punch > 0.0f || swell > 0.0f) haloR *= 1.0f + 0.8f * punch + 0.8f * swell;
      if (g.halo > 0.001f) {
        Paint halo = Paint::radial({px, py}, haloR,
          {{p.color.r, p.color.g, p.color.b, std::clamp(0.55f * boost * std::min(g.halo, 1.4f) + 0.35f * punch + 0.25f * swell, 0.0f, 1.0f)},
           {p.color.r, p.color.g, p.color.b, 0.0f}}, {0.0f, 1.0f});
        halo.blend = Blend::plus;
        c.circle({px, py}, haloR, halo);
      }

      // Esfera 3D iluminada hacia el sol central
      float lightX = px - nx * pr * 0.42f;
      float lightY = py - ny * pr * 0.42f;
      Paint spherePaint = Paint::radial({lightX, lightY}, pr * 1.35f,
        {{1.0f, 0.99f, 0.96f, 1.0f},
         p.color,
         Color::argb(0xff120f0b)}, {0.0f, 0.45f, 1.0f});
      c.circle({px, py}, pr, spherePaint);

      // Destello en chispas agudas (90ms)
      if (smoothSpark > 0.02f) {
        Paint sparkPaint; sparkPaint.blend = Blend::plus;
        sparkPaint.color = {1.0f, 0.98f, 0.92f, std::clamp(smoothSpark * 0.90f * f.intensity, 0.0f, 1.0f)};
        c.circle({px, py}, pr * (1.0f + smoothSpark * 0.55f), sparkPaint);
      }
    }
  }
};

class Visual final : public Scene {
  struct Planet {
    float radiusRatio;
    float size;
    float basePeriod;
    float inclination;
    float tiltAngle;
    bool retrograde;
    Color color;
    float angle;
  };

  std::vector<Planet> planets;
  float clockTime = 0.0f;
  float smoothEnergy = 0.0f;
  float smoothBass = 0.0f;
  float smoothSpark = 0.0f;
  // Fase de la precesión (sólo se ve si Precesión > 0).
  double precPhase = 0.0;
  // Envolventes de la música para Pulso (cero en silencio) y el último golpe.
  float bass = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0;
  double ringAge = 100.0;
  float ringPower = 0.0f;

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }
  static float hashU(uint32_t x) {
    x ^= x >> 16; x *= 0x7feb352dU; x ^= x >> 15; x *= 0x846ca68bU; x ^= x >> 16;
    return float(x & 0xffffffu) / 16777216.0f;
  }
  // Precesión: cada plano gira a su ritmo, en sentidos alternos.
  float tiltOf(size_t i, float base, float prec) const {
    if (prec <= 0.0f) return base;
    const float rate = (i % 2 == 0 ? 1.0f : -1.0f) * (0.6f + 0.25f * float(i));
    return base + float(std::fmod(precPhase, 1000.0)) * rate * prec;
  }

 public:
  void reset(uint32_t seed) override {
    (void)seed;
    planets.clear();
    planets.reserve(4);
    clockTime = 0.0f;
    smoothEnergy = 0.0f;
    smoothBass = 0.0f;
    smoothSpark = 0.0f;
    precPhase = 0.0;
    bass = spark = energy = slowBass = kick = flash = 0.0f;
    ringAge = 100.0; ringPower = 0.0f;

    // Cobre
    planets.push_back({0.19f, 8.5f, 14.0f, 0.0f, 0.20f, false, {0.85f, 0.55f, 0.29f, 1.0f}, 0.8f});
    // Bronce
    planets.push_back({0.27f, 7.0f, 8.5f, 0.36f, 0.65f, false, {0.72f, 0.63f, 0.42f, 1.0f}, 2.3f});
    // Acero
    planets.push_back({0.35f, 9.5f, 11.2f, 0.42f, -0.50f, false, {0.44f, 0.62f, 0.77f, 1.0f}, 4.1f});
    // Jade (retrogrado)
    planets.push_back({0.42f, 6.5f, 6.8f, 0.15f, 1.10f, true, {0.37f, 0.75f, 0.63f, 1.0f}, 5.4f});
  }

  void update(const Frame& f) override {
    float dt = float(f.delta);
    float targetEnergy = f.music.active ? f.music.energy : 0.0f;
    float targetBass = f.music.active ? f.music.bass : 0.0f;
    float targetSpark = f.music.active ? f.music.spark : 0.0f;
    smoothEnergy += (targetEnergy - smoothEnergy) * float(1.0 - std::exp(-dt * 5.0));
    smoothBass += (targetBass - smoothBass) * float(1.0 - std::exp(-dt * 6.0));
    smoothSpark += (targetSpark - smoothSpark) * float(1.0 - std::exp(-dt * 15.0));

    // En silencio reposa en un tic-tac de reloj celestial sereno y majestuoso (~0.12f).
    // Con música la maquinaria de relojería se revoluciona al compás del ritmo.
    float audioDrive = 0.12f + smoothEnergy * 0.76f + smoothBass * 0.35f;
    float speedFactor = (f.reducedMotion ? 0.25f : 1.0f) * f.speed * audioDrive;
    clockTime += dt * speedFactor;

    for (auto& p : planets) {
      float dir = p.retrograde ? -1.0f : 1.0f;
      p.angle += dir * (6.2831853f / p.basePeriod) * dt * speedFactor;
    }

    precPhase += f.delta * double(f.speed) * (f.reducedMotion ? 0.1 : 0.35);
    // Música para Pulso: envolventes y golpes (todo vale cero en silencio).
    const Music& mu = f.music;
    bass = follow(bass, mu.bass, 22.0f, 4.5f, dt);
    spark = follow(spark, mu.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, mu.energy, 6.0f, 1.8f, dt);
    float hit = 0, fl = 0;
    for (const auto& e : mu.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : mu.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : mu.events[3]) fl = std::max(fl, e.strength);
    const float onset = std::clamp((mu.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, mu.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    const bool fresh = hit > kick + 0.2f;
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    ringAge += f.delta;
    if (fresh) { ringAge = 0.0; ringPower = hit; }
  }

  void render(const Frame& f, Canvas& c) const override {
    float w = f.width, h = f.height;
    float minDim = std::min(w, h);
    Vec2 center{w * 0.5f, h * 0.5f};
    float time = clockTime;
    float boost = std::clamp((0.85f + smoothEnergy * 0.35f) * f.intensity, 0.0f, 1.0f);
    auto g = glide(f);
    const float amp = f.intensity;
    // Pulso: sus pesos reparten la reacción; todo vale cero sin música.
    const float punch = std::min(kick * amp, 1.0f) * g.pulso.weight(0);
    const float swell = std::min(bass * amp, 1.0f) * g.pulso.weight(1);
    const float glint = std::min(spark * amp, 1.0f) * g.pulso.weight(2);
    const float tiltK = g.inclinacion;
    const float prec = g.precesion;

    // Sin fondo opaco: lienzo 100% transparente para efecto HUD / astrolabio flotante

    // 1. Barras diagonales estructurales de latón
    Paint crossbar;
    crossbar.color = {0.72f, 0.60f, 0.40f, std::clamp(0.38f * boost, 0.0f, 1.0f)};
    crossbar.strokeWidth = 1.5f;
    Path cross;
    for (int a = 0; a < 4; a++) {
      float ang = (float(a) * 3.14159265f * 0.5f) + 0.785398f;
      cross.moveTo(center.x + std::cos(ang) * minDim * 0.07f, center.y + std::sin(ang) * minDim * 0.07f);
      cross.lineTo(center.x + std::cos(ang) * minDim * 0.46f, center.y + std::sin(ang) * minDim * 0.46f);
    }
    c.path(cross, crossbar);

    // Resplandor local de la música sobre la maquinaria (nunca a pantalla
    // completa): cobre en cada golpe y con los graves, azul acero que
    // parpadea con los agudos.
    if (punch > 0.0f || swell > 0.0f || glint > 0.0f) {
      const float auraR = minDim * 0.6f * (1.0f + 0.12f * punch + 0.15f * swell);
      const float flicker = 0.55f + 0.45f * std::sin(float(f.time) * 43.0f);
      const float warm = (0.4f * punch + 0.32f * swell) * f.glow;
      const float cool = 0.3f * glint * flicker * f.glow;
      Paint auraWarm = Paint::radial(center, auraR,
        {{0.85f, 0.55f, 0.29f, std::clamp(warm, 0.0f, 1.0f)},
         {0.85f, 0.55f, 0.29f, std::clamp(warm * 0.7f, 0.0f, 1.0f)},
         {0.85f, 0.55f, 0.29f, 0.0f}}, {0.0f, 0.62f, 1.0f});
      auraWarm.blend = Blend::plus;
      if (warm > 0.0f) c.circle(center, auraR, auraWarm);
      Paint auraCool = Paint::radial(center, auraR,
        {{0.44f, 0.62f, 0.77f, std::clamp(cool, 0.0f, 1.0f)}, {0.44f, 0.62f, 0.77f, 0.0f}}, {0.0f, 1.0f});
      auraCool.blend = Blend::plus;
      if (cool > 0.0f) c.circle(center, auraR, auraCool);
    }

    // 2. Bisel exterior de la corona graduada con 96 muescas y glifos
    float crownTilt = (f.music.flow - 0.5f) * 0.16f;
    float outerR = minDim * 0.455f;
    float innerR = minDim * 0.415f;

    c.save();
    c.translate(center.x, center.y);
    c.rotate(crownTilt);

    // Aros del bisel
    Paint bezel;
    // Golpes: el bisel se enciende con cada golpe.
    bezel.color = {0.85f, 0.72f, 0.48f, std::clamp(0.48f * boost + 0.62f * punch, 0.0f, 1.0f)};
    bezel.strokeWidth = 1.8f;
    if (punch > 0.0f) bezel.strokeWidth *= 1.0f + 1.3f * punch;
    c.circle({0, 0}, outerR, bezel);
    c.circle({0, 0}, innerR, bezel);

    // 96 marcas graduadas en el bisel
    Path ticks;
    for (int i = 0; i < 96; i++) {
      float ang = (float(i) / 96.0f) * 6.2831853f;
      bool isMajor = (i % 8 == 0);
      float r0 = isMajor ? innerR : innerR + (outerR - innerR) * 0.45f;
      ticks.moveTo(std::cos(ang) * r0, std::sin(ang) * r0);
      ticks.lineTo(std::cos(ang) * outerR, std::sin(ang) * outerR);
    }
    Paint tickPaint;
    tickPaint.color = {0.85f, 0.72f, 0.48f, std::clamp(0.55f * boost + 0.52f * punch, 0.0f, 1.0f)};
    tickPaint.strokeWidth = 1.0f;
    c.path(ticks, tickPaint);

    // 12 Glifos geométricos abstractos
    float midRingR = (outerR + innerR) * 0.5f;
    float glyphR = minDim * 0.012f;
    Path glyphsPath;
    for (int s = 0; s < 12; s++) {
      float ang = (float(s) / 12.0f) * 6.2831853f + 0.130899f;
      float gx = std::cos(ang) * midRingR;
      float gy = std::sin(ang) * midRingR;

      if (s % 3 == 0) {
        glyphsPath.moveTo(gx, gy - glyphR);
        glyphsPath.lineTo(gx + glyphR, gy);
        glyphsPath.lineTo(gx, gy + glyphR);
        glyphsPath.lineTo(gx - glyphR, gy);
        glyphsPath.close();
      } else if (s % 3 == 1) {
        glyphsPath.circle({gx, gy}, glyphR * 0.75f);
      } else {
        glyphsPath.moveTo(gx, gy - glyphR);
        glyphsPath.lineTo(gx + glyphR, gy + glyphR * 0.8f);
        glyphsPath.lineTo(gx - glyphR, gy + glyphR * 0.8f);
        glyphsPath.close();
      }
    }
    Paint glyphPaint;
    glyphPaint.color = {0.95f, 0.82f, 0.55f, std::clamp(0.70f * boost, 0.0f, 1.0f)};
    glyphPaint.strokeWidth = 1.2f;
    c.path(glyphsPath, glyphPaint);

    // Agudos: los glifos centellean uno a uno.
    if (glint > 0.0f) {
      const uint32_t tick = uint32_t(std::floor(f.time * 10.0));
      Path sparkGlyphs;
      for (int s = 0; s < 12; s++) {
        if (hashU(uint32_t(s) * 2654435761u + tick * 40503u) >= glint * 0.95f) continue;
        float ang = (float(s) / 12.0f) * 6.2831853f + 0.130899f;
        sparkGlyphs.circle({std::cos(ang) * midRingR, std::sin(ang) * midRingR}, glyphR * 2.0f);
      }
      // Y destellos que corren por las 96 muescas.
      std::vector<Vec2> tickSparks;
      for (int i = 0; i < 96; i++) {
        if (hashU(uint32_t(i) * 747796405u + tick * 2891336453u) >= glint * 0.5f) continue;
        const float ang = (float(i) / 96.0f) * 6.2831853f;
        tickSparks.push_back({std::cos(ang) * outerR, std::sin(ang) * outerR});
      }
      if (!tickSparks.empty()) {
        Paint tickSpark; tickSpark.blend = Blend::plus;
        tickSpark.color = {1.0f, 0.95f, 0.8f, std::clamp(glint, 0.0f, 1.0f)};
        c.points(tickSparks, 2.4f, tickSpark);
      }
      Paint glyphSpark; glyphSpark.blend = Blend::plus;
      glyphSpark.color = {1.0f, 0.9f, 0.6f, std::clamp(0.8f * glint, 0.0f, 1.0f)};
      c.path(sparkGlyphs, glyphSpark);
    }

    c.restore();

    // 3. Órbitas elípticas de latón grabadas con tren de engranajes
    for (size_t i = 0; i < planets.size(); i++) {
      const auto& p = planets[i];
      float orbitR = minDim * p.radiusRatio;

      // Inclinación y Precesión (1 y 0 = las órbitas originales).
      const float incl = p.inclination * tiltK;
      c.save();
      c.translate(center.x, center.y);
      c.rotate(tiltOf(i, p.tiltAngle, prec));

      Paint orbitPaint;
      orbitPaint.color = {0.75f, 0.65f, 0.45f, std::clamp(0.25f * boost, 0.0f, 1.0f)};
      orbitPaint.strokeWidth = 1.0f;
      // Graves: las órbitas se encienden de latón y engordan despacio.
      // Golpes: las órbitas destellan.
      if (swell > 0.0f || punch > 0.0f) {
        const float lit = std::min(1.0f, swell + punch);
        orbitPaint.color = {0.75f + 0.2f * lit, 0.65f + 0.15f * lit, 0.45f + 0.05f * lit,
                            std::clamp(0.25f * boost + 0.5f * swell + 0.5f * punch, 0.0f, 1.0f)};
        orbitPaint.strokeWidth *= 1.0f + 1.6f * swell + 1.0f * punch;
      }

      Path orbitPath;
      float bAxis = orbitR * (1.0f - incl * 0.32f);
      const int kEllipsePts = 48;
      for (int ep = 0; ep <= kEllipsePts; ep++) {
        float ea = (float(ep) / float(kEllipsePts)) * 6.2831853f;
        float ex = std::cos(ea) * orbitR;
        float ey = std::sin(ea) * bAxis;
        if (ep == 0) orbitPath.moveTo(ex, ey);
        else orbitPath.lineTo(ex, ey);
      }
      c.path(orbitPath, orbitPaint);

      // Engranaje anular dentado concéntrico en la órbita 2
      if (i == 1) {
        float gearR = orbitR * 0.96f;
        int teeth = 36;
        Path gearPath;
        for (int t = 0; t < teeth; t++) {
          float a0 = (float(t) / float(teeth)) * 6.2831853f + time * 0.12f;
          float a1 = a0 + (6.2831853f / float(teeth)) * 0.5f;
          float tr0 = gearR - 2.5f;
          float tr1 = gearR + 2.5f;
          gearPath.moveTo(std::cos(a0) * tr0, std::sin(a0) * tr0);
          gearPath.lineTo(std::cos(a0) * tr1, std::sin(a0) * tr1);
          gearPath.lineTo(std::cos(a1) * tr1, std::sin(a1) * tr1);
          gearPath.lineTo(std::cos(a1) * tr0, std::sin(a1) * tr0);
        }
        Paint gearPaint;
        gearPaint.color = {0.68f, 0.58f, 0.38f, std::clamp(0.35f * boost, 0.0f, 1.0f)};
        gearPaint.strokeWidth = 1.0f;
        c.path(gearPath, gearPaint);
      }

      c.restore();
    }

    // 4. Sol central de latón macizo con engranaje solar y corona flamígera
    float sunR = minDim * 0.052f;
    float bassGlow = std::clamp(0.35f + smoothBass * 0.65f, 0.0f, 1.0f);

    // Graves: la corona crece despacio; Golpes: el sol late con cada golpe.
    const float coronaR = sunR * 2.8f * (1.0f + 0.25f * swell + 0.2f * punch);
    const float bodyR = sunR * (1.0f + 0.13f * swell + 0.2f * punch);
    Paint sunCorona = Paint::radial(center, coronaR,
      {{1.0f, 0.88f, 0.59f, std::clamp(0.85f * bassGlow * boost, 0.0f, 1.0f)},
       {0.85f, 0.55f, 0.29f, std::clamp(0.28f * bassGlow * boost, 0.0f, 1.0f)},
       {0, 0, 0, 0}}, {0.0f, 0.45f, 1.0f});
    sunCorona.blend = Blend::plus;
    c.circle(center, coronaR, sunCorona);

    Paint sunBody = Paint::radial({center.x - bodyR * 0.3f, center.y - bodyR * 0.3f}, bodyR,
      {Color::argb(0xfffff4d2), Color::argb(0xffd99b4a), Color::argb(0xff6b4820)},
      {0.0f, 0.6f, 1.0f});
    c.circle(center, bodyR, sunBody);

    // Golpes: un anillo de latón sale del sol hasta el bisel.
    const float ringFade = ringPower * float(std::exp(-ringAge * 2.5)) * g.pulso.weight(0);
    if (ringFade > 0.01f) {
      Paint ring; ring.blend = Blend::plus;
      ring.color = {1.0f, 0.82f, 0.45f, std::clamp(0.95f * ringFade * amp, 0.0f, 1.0f)};
      ring.strokeWidth = 2.0f + 5.0f * ringFade;
      c.circle(center, sunR * 1.4f + float(ringAge) * minDim * 0.7f, ring);
    }

    // Índice dorado giratorio esmaltado (reloj mecánico)
    c.save();
    c.translate(center.x, center.y);
    c.rotate(time * 0.25f);
    Path needle;
    needle.moveTo(0.0f, -sunR * 1.30f);
    needle.lineTo(sunR * 0.28f, 0.0f);
    needle.lineTo(0.0f, sunR * 0.55f);
    needle.lineTo(-sunR * 0.28f, 0.0f);
    needle.close();
    Paint needlePaint;
    needlePaint.color = {1.0f, 0.85f, 0.35f, bassGlow};
    needlePaint.blend = Blend::plus;
    c.path(needle, needlePaint);
    c.restore();

    // 5. Esferas planetarias con halo y destello spark
    for (size_t pi = 0; pi < planets.size(); pi++) {
      const auto& p = planets[pi];
      float orbitR = minDim * p.radiusRatio;
      const float tilt = tiltOf(pi, p.tiltAngle, prec);
      const float incl = p.inclination * tiltK;
      float cosTilt = std::cos(tilt);
      float sinTilt = std::sin(tilt);
      float squash = 1.0f - incl * 0.32f;

      float lx = std::cos(p.angle) * orbitR;
      float ly = std::sin(p.angle) * orbitR * squash;
      float px = center.x + lx * cosTilt - ly * sinTilt;
      float py = center.y + lx * sinTilt + ly * cosTilt;

      float depthScale = 1.0f + std::sin(p.angle) * incl * 0.22f;
      float pr = p.size * (minDim / 420.0f) * depthScale;
      // Golpes: los planetas dan un salto; Graves: respiran.
      if (punch > 0.0f || swell > 0.0f) pr *= 1.0f + 0.2f * punch + 0.12f * swell;

      // Halo atmosférico del planeta (Halo: 0 lo apaga, 1 = el original)
      float haloR = pr * (2.6f + smoothSpark * 1.8f);
      haloR *= g.halo;
      // Golpes y Graves: el halo de cada planeta crece y se aviva.
      if (punch > 0.0f || swell > 0.0f) haloR *= 1.0f + 0.8f * punch + 0.8f * swell;
      if (g.halo > 0.001f) {
        Paint halo = Paint::radial({px, py}, haloR,
          {{p.color.r, p.color.g, p.color.b, std::clamp(0.55f * boost * std::min(g.halo, 1.4f) + 0.35f * punch + 0.25f * swell, 0.0f, 1.0f)},
           {p.color.r, p.color.g, p.color.b, 0.0f}}, {0.0f, 1.0f});
        halo.blend = Blend::plus;
        c.circle({px, py}, haloR, halo);
      }

      // Esfera 3D iluminada hacia el sol central
      float dx = px - center.x;
      float dy = py - center.y;
      float dist = std::sqrt(dx * dx + dy * dy);
      if (dist < 1.0f) dist = 1.0f;
      float nx = dx / dist;
      float ny = dy / dist;

      float lightX = px - nx * pr * 0.42f;
      float lightY = py - ny * pr * 0.42f;
      Paint spherePaint = Paint::radial({lightX, lightY}, pr * 1.35f,
        {{1.0f, 0.99f, 0.96f, 1.0f},
         p.color,
         Color::argb(0xff120f0b)}, {0.0f, 0.45f, 1.0f});
      c.circle({px, py}, pr, spherePaint);

      // Destello en chispas agudas (90ms)
      if (smoothSpark > 0.02f) {
        Paint sparkPaint; sparkPaint.blend = Blend::plus;
        sparkPaint.color = {1.0f, 0.98f, 0.92f, std::clamp(smoothSpark * 0.90f * f.intensity, 0.0f, 1.0f)};
        c.circle({px, py}, pr * (1.0f + smoothSpark * 0.55f), sparkPaint);
      }
    }
  }
};

class Visual final : public Scene {
  float cloudTime = 0.0f;
  float warpOffset = 0.0f;
  float smoothBass = 0.0f;
  float smoothEnergy = 0.0f;
  float smoothSpark = 0.0f;

 public:
  void reset(uint32_t seed) override {
    (void)seed;
    cloudTime = 0.0f;
    warpOffset = 0.0f;
    smoothBass = 0.0f;
    smoothEnergy = 0.0f;
    smoothSpark = 0.0f;
  }

  void update(const Frame& f) override {
    float dt = float(f.delta);
    float targetEnergy = f.music.active ? f.music.energy : 0.0f;
    float targetBass = f.music.active ? f.music.bass : 0.0f;
    float targetSpark = f.music.active ? f.music.spark : 0.0f;
    smoothBass += (targetBass - smoothBass) * float(1.0 - std::exp(-dt * 6.0));
    smoothEnergy += (targetEnergy - smoothEnergy) * float(1.0 - std::exp(-dt * 5.0));
    smoothSpark += (targetSpark - smoothSpark) * float(1.0 - std::exp(-dt * 15.0));

    // En silencio las nubes flotan en una deriva reposada y etérea (~0.10f).
    // Con música la masa nubosa se arremolina y deforma con el audio.
    float audioDrive = 0.10f + smoothEnergy * 0.75f + smoothBass * 0.35f;
    float speedMult = (f.reducedMotion ? 0.25f : 1.0f) * f.speed * audioDrive;
    cloudTime += dt * speedMult;

    // Desplazamiento orgánico del dominio de ruido con los graves
    warpOffset += dt * (0.05f + smoothBass * 0.70f) * f.speed;
  }

  void render(const Frame& f, Canvas& c) const override {
    float w = f.width, h = f.height;
    std::vector<float> u;
    u.reserve(6);
    u.push_back(cloudTime);
    u.push_back(warpOffset);
    u.push_back(smoothEnergy * 0.12f);
    u.push_back(smoothSpark * f.intensity);
    u.push_back(f.reducedMotion ? 1.0f : 0.0f);

    c.material("nubes", {0.0f, 0.0f, w, h}, u);
  }
};

