class Visual final : public Scene {
  struct PlasmaIon {
    int lineIdx;
    float prog;
    float speed;
    float phase;
    float size;
    int colIdx;
  };

  struct Filing {
    float x, y;
    float angle;
    float len;
    bool isPolar;
  };

  static constexpr int kLines = 48;
  static constexpr int kLinePts = 64;
  static constexpr int kIonCount = 380;
  static constexpr int kFilingCount = 2200;

  // Tubos de flujo magnético precalculados por fotograma
  Vec2 linePts[kLines][kLinePts];

  std::vector<PlasmaIon> ions;
  std::vector<Filing> filings;

  float simTime = 0.0f;
  float smoothEnergy = 0.0f;
  float smoothBass = 0.0f;
  float smoothSpark = 0.0f;

  float targetPolarity = 1.0f;
  float polarityAngle = 0.0f;
  float polarityVel = 0.0f;
  float lastInvertTime = -10.0f;

  float shockRadius1 = 0.0f;
  float shockRadius2 = 0.0f;

  // Música estándar: envolventes y golpe corto (valen 0 sin música).
  float bass = 0, body = 0, spark = 0, energy = 0, drive = 0, slowBass = 0, kick = 0, flash = 0;
  // Segundos reales para los anillos de los golpes y el chisporroteo.
  double clock = 0;
  // Golpes: anillo fijo de ondas de inducción {nacimiento, fuerza}.
  static constexpr int kPulses = 4;
  std::array<double, kPulses> pulseBirth{};
  std::array<float, kPulses> pulsePower{};
  int nextPulse = 0;

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

  static Vec2 evalFieldDir(float x, float y, float mx, float my) {
    const float soft2 = 0.014f;
    float bx = 0.0f, by = 0.0f;

    for (int p = 0; p < 2; p++) {
      float px = (p == 0) ? -0.28f : 0.28f;
      float sign = (p == 0) ? 1.0f : -1.0f;
      float dx = x - px;
      float dy = y;
      float r2 = dx * dx + dy * dy + soft2;
      float invR25 = 1.0f / (r2 * std::sqrt(r2));
      float invR35 = invR25 / r2;

      float mDotD = sign * (mx * dx + my * dy);
      float dVdx = sign * mx * invR25 - 3.0f * dx * mDotD * invR35;
      float dVdy = sign * my * invR25 - 3.0f * dy * mDotD * invR35;

      bx -= dVdx;
      by -= dVdy;
    }

    float len = std::sqrt(bx * bx + by * by);
    if (len < 1e-5f) return Vec2{0.0f, 1.0f};
    return Vec2{bx / len, by / len};
  }

 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    simTime = 0.0f;
    smoothEnergy = 0.0f;
    smoothBass = 0.0f;
    smoothSpark = 0.0f;
    targetPolarity = 1.0f;
    polarityAngle = 0.0f;
    polarityVel = 0.0f;
    lastInvertTime = -10.0f;
    shockRadius1 = 0.0f;
    shockRadius2 = 0.0f;
    bass = body = spark = energy = drive = slowBass = kick = flash = 0;
    clock = 0;
    pulseBirth.fill(-100.0);
    pulsePower.fill(0.0f);
    nextPulse = 0;

    ions.clear();
    ions.reserve(kIonCount);
    for (int i = 0; i < kIonCount; i++) {
      ions.push_back({
        i % kLines,
        rng.unit(),
        0.35f + rng.unit() * 0.55f,
        rng.unit() * 6.2831853f,
        1.2f + rng.unit() * 2.2f,
        int(rng.unit() * 3.999f)
      });
    }

    filings.clear();
    filings.reserve(kFilingCount);
    for (int i = 0; i < kFilingCount; i++) {
      Filing f;
      if (i < 1500) {
        // 70% concentrado cerca de los dos polos
        float poleX = (i % 2 == 0) ? -0.28f : 0.28f;
        float r = std::pow(rng.unit(), 1.8f) * 0.42f + 0.025f;
        float th = rng.unit() * 6.2831853f;
        f.x = poleX + std::cos(th) * r;
        f.y = std::sin(th) * r * 0.85f;
        f.len = 0.008f + rng.unit() * 0.006f;
        f.isPolar = true;
      } else {
        // 30% ambiente
        f.x = (rng.unit() - 0.5f) * 1.15f;
        f.y = (rng.unit() - 0.5f) * 0.95f;
        f.len = 0.006f + rng.unit() * 0.005f;
        f.isPolar = false;
      }
      Vec2 b = evalFieldDir(f.x, f.y, 1.0f, 0.0f);
      f.angle = std::atan2(b.y, b.x);
      filings.push_back(f);
    }
  }

  void update(const Frame& f) override {
    float dt = float(f.delta);
    float targetEnergy = f.music.active ? f.music.energy : 0.0f;
    float targetBass = f.music.active ? f.music.bass : 0.0f;
    float targetSpark = f.music.active ? f.music.spark : 0.0f;

    smoothEnergy += (targetEnergy - smoothEnergy) * float(1.0 - std::exp(-dt * 5.0));
    smoothBass += (targetBass - smoothBass) * float(1.0 - std::exp(-dt * 6.0));
    smoothSpark += (targetSpark - smoothSpark) * float(1.0 - std::exp(-dt * 15.0));

    // En silencio reposa en un flujo magnético laminar lento (~0.10f).
    // Con música acelera el flujo de iones Lorentz y desata arcos e inversiones de dipolo.
    float audioDrive = 0.10f + smoothEnergy * 0.76f + smoothBass * 0.35f;
    float speedMult = (f.reducedMotion ? 0.3f : 1.0f) * f.speed * audioDrive;
    simTime += dt * speedMult;

    // Inversión física del dipolo ante bombos rítmicos marcados con música activa
    if (f.music.active && !f.reducedMotion && f.music.bass > 0.80f && (simTime - lastInvertTime > 1.8f)) {
      lastInvertTime = simTime;
      targetPolarity *= -1.0f;
      shockRadius1 = 15.0f;
      shockRadius2 = 15.0f;
    }

    // Ondas de choque de inducción
    if (shockRadius1 > 0.0f) {
      shockRadius1 += dt * 320.0f;
      if (shockRadius1 > 450.0f) shockRadius1 = 0.0f;
    }
    if (shockRadius2 > 0.0f) {
      shockRadius2 += dt * 320.0f;
      if (shockRadius2 > 450.0f) shockRadius2 = 0.0f;
    }

    // Muelle físico con amortiguamiento crítico para la orientación del dipolo
    float targetAngle = (targetPolarity > 0.0f) ? 0.0f : 3.14159265f;
    float omega = 9.5f;
    float diffAngle = targetAngle - polarityAngle;
    polarityVel += (diffAngle * omega * omega - 2.0f * omega * 0.78f * polarityVel) * dt;
    polarityAngle += polarityVel * dt;

    float mx = std::cos(polarityAngle);
    float my = std::sin(polarityAngle);

    // Integración de los 48 tubos de flujo
    float stepDt = 0.0022f;
    for (int l = 0; l < kLines; l++) {
      float ang = (float(l) / float(kLines)) * 6.2831853f;
      float startPole = (l % 2 == 0) ? -0.28f : 0.28f;
      float x = startPole + std::cos(ang) * 0.038f;
      float y = std::sin(ang) * 0.038f;
      float dirSign = (l % 2 == 0) ? 1.0f : -1.0f;

      for (int pt = 0; pt < kLinePts; pt++) {
        linePts[l][pt] = Vec2{x, y};
        for (int sub = 0; sub < 4; sub++) {
          Vec2 b = evalFieldDir(x, y, mx, my);
          x += b.x * stepDt * dirSign;
          y += b.y * stepDt * dirSign;
        }
      }
    }

    // Actualización de iones de plasma (movimiento de Lorentz a lo largo de las líneas)
    float ionSpeedFactor = (1.0f + smoothEnergy * 0.85f);
    for (auto& ion : ions) {
      ion.prog += dt * ion.speed * 0.45f * ionSpeedFactor;
      if (ion.prog >= 1.0f) {
        ion.prog = std::fmod(ion.prog, 1.0f);
      }
    }

    // Alineación física de limaduras de hierro con amortiguamiento
    float alignRate = std::min(1.0f, dt * 14.0f);
    for (auto& fil : filings) {
      Vec2 b = evalFieldDir(fil.x, fil.y, mx, my);
      float targetA = std::atan2(b.y, b.x);
      float deltaA = targetA - fil.angle;
      while (deltaA > 3.14159265f) deltaA -= 6.2831853f;
      while (deltaA < -3.14159265f) deltaA += 6.2831853f;
      fil.angle += deltaA * alignRate;
    }

    // Música estándar: graves, cuerpo, agudos, energía y golpe corto.
    const Music& mu = f.music;
    bass = follow(bass, mu.bass, 22.0f, 4.5f, dt);
    body = follow(body, mu.body, 12.0f, 3.0f, dt);
    spark = follow(spark, mu.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, mu.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, mu.active ? std::pow(std::clamp(mu.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);
    float hit = 0, fl = 0;
    for (const auto& e : mu.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : mu.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : mu.events[3]) fl = std::max(fl, e.strength);
    const float onset = std::clamp((mu.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, mu.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    const bool fresh = hit > kick + 0.2f;
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    clock += f.delta;
    // Golpes: cada golpe nuevo lanza un anillo de inducción.
    if (fresh) {
      pulseBirth[size_t(nextPulse)] = clock;
      pulsePower[size_t(nextPulse)] = hit;
      nextPulse = (nextPulse + 1) % kPulses;
    }
  }

  void render(const Frame& f, Canvas& c) const override {
    auto g = glide(f);
    const float level = f.intensity;
    // Pulso: cada opción mueve algo distinto y sus pesos mezclan las opciones.
    const float golpe = g.pulso.weight(0) * std::min(kick * level, 1.0f);
    const float graves = g.pulso.weight(1) * std::min(bass * level, 1.0f);
    const float agudos = g.pulso.weight(2) * std::min(spark * level, 1.0f);
    const float tick = float(std::fmod(clock, 1000.0));
    // Patrón: las limaduras siguen el campo (Dipolo, el original), lo cruzan
    // en anillos (Equipotencial) o apuntan a su polo (Radial).
    const float crossW = g.patron.weight(1), radialW = g.patron.weight(2);
    float w = f.width, h = f.height;
    float minDim = std::min(w, h);
    Vec2 center{w * 0.5f, h * 0.5f};
    float boost = std::clamp((0.85f + smoothEnergy * 0.40f) * f.intensity, 0.0f, 1.0f);

    float mx = std::cos(polarityAngle);

    // 1. Cámara oscura de laboratorio electromagnético #080b12
    Paint bg = Paint::radial(center, minDim * 0.85f,
      {Color::argb(0xff101726), Color::argb(0xff080b12), Color::argb(0xff030407)},
      {0.0f, 0.55f, 1.0f});
    c.rect({0, 0, w, h}, bg);

    // Reflejo difuso central
    Paint chamberGlow = Paint::radial(center, minDim * 0.45f,
      {{0.0f, 0.94f, 1.0f, std::clamp(0.12f * boost, 0.0f, 1.0f)}, {0, 0, 0, 0}},
      {0.0f, 1.0f});
    chamberGlow.blend = Blend::plus;
    c.circle(center, minDim * 0.45f, chamberGlow);

    // Golpes: cada polo estalla en un resplandor de su color; Graves los hace
    // respirar más suave.
    const float burst = std::min(1.0f, (0.6f * golpe + 0.25f * graves) * f.glow);
    if (burst > 0.001f) {
      for (int k = 0; k < 2; k++) {
        const Vec2 pole{center.x + (k == 0 ? -0.28f : 0.28f) * minDim, center.y};
        const Color tint = k == 0 ? Color{0.2f, 0.95f, 1.0f, 1.0f} : Color{0.8f, 0.45f, 1.0f, 1.0f};
        const float reach = minDim * (0.42f + 0.08f * golpe);
        Paint light = Paint::radial(pole, reach,
          {{tint.r, tint.g, tint.b, burst}, {tint.r, tint.g, tint.b, burst * 0.35f}, {tint.r, tint.g, tint.b, 0}}, {0, 0.4f, 1.0f});
        light.blend = Blend::plus;
        c.circle(pole, reach, light);
      }
    }

    // Ondas de choque de inducción expansivas
    if (shockRadius1 > 0.0f) {
      float alpha = std::clamp((1.0f - shockRadius1 / 450.0f) * 0.40f * boost, 0.0f, 1.0f);
      Paint shk; shk.blend = Blend::plus; shk.strokeWidth = 2.0f;
      shk.color = {0.0f, 0.94f, 1.0f, alpha};
      c.circle({center.x - 0.28f * minDim, center.y}, shockRadius1, shk);
    }
    if (shockRadius2 > 0.0f) {
      float alpha = std::clamp((1.0f - shockRadius2 / 450.0f) * 0.40f * boost, 0.0f, 1.0f);
      Paint shk; shk.blend = Blend::plus; shk.strokeWidth = 2.0f;
      shk.color = {0.62f, 0.31f, 0.87f, alpha};
      c.circle({center.x + 0.28f * minDim, center.y}, shockRadius2, shk);
    }

    // Golpes: un anillo de inducción sale de cada polo y se apaga al crecer.
    const float pulseWeight = g.pulso.weight(0);
    if (pulseWeight > 0.001f) {
      for (int k = 0; k < kPulses; k++) {
        const float age = float(clock - pulseBirth[size_t(k)]);
        if (age < 0.0f || age >= 0.9f) continue;
        const float fade = 1.0f - age / 0.9f;
        const float power = std::min(pulsePower[size_t(k)] * level, 1.0f) * pulseWeight * fade;
        if (power <= 0.001f) continue;
        const float radius = minDim * (0.05f + age * 0.55f);
        Paint ring; ring.blend = Blend::plus; ring.strokeWidth = 3.0f + 5.0f * fade;
        ring.color = {0.0f, 0.94f, 1.0f, std::min(1.0f, 0.85f * power * boost)};
        c.circle({center.x - 0.28f * minDim, center.y}, radius, ring);
        ring.color = {0.75f, 0.35f, 1.0f, std::min(1.0f, 0.85f * power * boost)};
        c.circle({center.x + 0.28f * minDim, center.y}, radius, ring);
      }
    }

    // 2. Campo de limaduras de hierro orientadas (Ferrofluido que vibra con el audio)
    // Limaduras: largo de las agujas (1 es el original; 0 las quita).
    const float needle = g.limaduras;
    if (needle > 0.01f) {
      Path filingsPath;
      float filingLengthMult = 0.5f * (1.0f + smoothBass * 0.45f);

      for (const auto& fil : filings) {
        float sx = center.x + fil.x * minDim;
        float sy = center.y + fil.y * minDim;
        float flen = fil.len * minDim * filingLengthMult * needle;
        float angle = fil.angle;
        if (crossW + radialW > 0.001f) {
          // Las agujas no tienen sentido: se mezclan con el ángulo doble.
          const float toPole = std::atan2(fil.y, fil.x - (fil.x < 0.0f ? -0.28f : 0.28f));
          const float across = angle + float(pi) * 0.5f;
          const float keep = 1.0f - crossW - radialW;
          const float mx2 = keep * std::cos(2.0f * angle) + crossW * std::cos(2.0f * across) + radialW * std::cos(2.0f * toPole);
          const float my2 = keep * std::sin(2.0f * angle) + crossW * std::sin(2.0f * across) + radialW * std::sin(2.0f * toPole);
          angle = 0.5f * std::atan2(my2, mx2);
        }
        float dx = std::cos(angle) * flen;
        float dy = std::sin(angle) * flen;
        filingsPath.moveTo(sx - dx, sy - dy);
        filingsPath.lineTo(sx + dx, sy + dy);
      }
      Paint filPaint; filPaint.blend = Blend::plus;
      // Golpes enciende las limaduras (+80%); Graves las aviva; Agudos las
      // hace chisporrotear.
      filPaint.color = {0.45f, 0.65f, 0.95f, std::clamp(0.40f * boost * (1.0f + golpe * 0.8f + graves * 0.4f
        + agudos * 0.6f * std::sin(tick * 29.0f)), 0.0f, 1.0f)};
      filPaint.strokeWidth = 1.1f;
      c.path(filingsPath, filPaint);
    }

    // 3. Tubos de flujo magnético en arco (Cian -> Violeta -> Azul)
    Path linesCyan, linesViolet;

    for (int l = 0; l < kLines; l++) {
      Path& curPath = (l % 2 == 0) ? linesCyan : linesViolet;
      bool first = true;
      for (int pt = 0; pt < kLinePts; pt++) {
        float sx = center.x + linePts[l][pt].x * minDim;
        float sy = center.y + linePts[l][pt].y * minDim;
        if (first) { curPath.moveTo(sx, sy); first = false; }
        else curPath.lineTo(sx, sy);
      }
    }

    // Halo ancho de los tubos de flujo
    // Graves: el halo de los tubos se engrosa y se aviva con los graves.
    Paint lpGlow; lpGlow.blend = Blend::plus;
    lpGlow.strokeWidth = 3.5f * (1.0f + graves * 0.8f + golpe * 1.2f);
    lpGlow.color = {0.0f, 0.94f, 1.0f, std::clamp(0.22f * boost * (1.0f + graves * 0.6f), 0.0f, 1.0f)};
    c.path(linesCyan, lpGlow);
    lpGlow.color = {0.62f, 0.31f, 0.87f, std::clamp(0.22f * boost * (1.0f + graves * 0.6f), 0.0f, 1.0f)};
    c.path(linesViolet, lpGlow);

    // Filamentos brillantes de flujo
    Paint lpCore; lpCore.blend = Blend::plus;
    lpCore.strokeWidth = 1.3f;
    // Golpes: los filamentos se encienden en cada golpe.
    lpCore.color = {0.50f, 0.95f, 1.0f, std::clamp(0.65f * boost * (1.0f + golpe * 0.6f), 0.0f, 1.0f)};
    c.path(linesCyan, lpCore);
    lpCore.color = {0.85f, 0.50f, 1.0f, std::clamp(0.65f * boost * (1.0f + golpe * 0.6f), 0.0f, 1.0f)};
    c.path(linesViolet, lpCore);

    // 4. Plasma de Lorentz: iones bioluminiscentes en espirales ciclotrón
    const Color ionCols[4] = {
      {1.0f, 1.0f, 1.0f, 1.0f},
      {0.0f, 0.95f, 1.0f, 1.0f},
      {0.75f, 0.35f, 1.0f, 1.0f},
      {1.0f, 0.85f, 0.20f, 1.0f}
    };

    for (const auto& ion : ions) {
      int lIdx = ion.lineIdx;
      float fIdx = ion.prog * float(kLinePts - 1);
      int p0 = std::clamp(int(fIdx), 0, kLinePts - 2);
      int p1 = p0 + 1;
      float frac = fIdx - float(p0);

      Vec2 pt0 = linePts[lIdx][p0];
      Vec2 pt1 = linePts[lIdx][p1];
      float basePx = center.x + (pt0.x + (pt1.x - pt0.x) * frac) * minDim;
      float basePy = center.y + (pt0.y + (pt1.y - pt0.y) * frac) * minDim;

      // Espiral de ciclotrón transversal a la línea de campo
      float helixAngle = ion.prog * 35.0f + ion.phase + simTime * 6.0f;
      // Ciclotrón: radio de la hélice (0 resbalan por la línea, 1 es el original).
      float helixRad = (1.5f + std::sin(ion.prog * 3.14159f) * 4.5f) * g.ciclotron;
      float ipx = basePx + std::cos(helixAngle) * helixRad;
      float ipy = basePy + std::sin(helixAngle) * helixRad;
      // Agudos: los iones tiemblan y parpadean con los agudos.
      float flick = 1.0f;
      if (agudos > 0.001f) {
        ipx += std::sin(tick * 61.0f + ion.phase * 7.0f) * 1.6f * agudos;
        ipy += std::cos(tick * 53.0f + ion.phase * 5.0f) * 1.6f * agudos;
        flick += agudos * 0.5f * (0.5f + 0.5f * std::sin(tick * 29.0f + ion.phase * 5.0f));
      }

      Color ic = ionCols[ion.colIdx];
      Paint ionPaint; ionPaint.blend = Blend::plus;
      ionPaint.color = {ic.r, ic.g, ic.b, std::clamp(0.85f * boost, 0.0f, 1.0f)};
      c.circle({ipx, ipy}, ion.size * (1.0f + smoothEnergy * 0.4f) * flick, ionPaint);
    }

    // 5. Arcos eléctricos Tesla de alta tensión ante transients y chispas
    if (smoothSpark > 0.18f || smoothBass > 0.75f) {
      float p1x = center.x - 0.28f * minDim;
      float p2x = center.x + 0.28f * minDim;
      float sparkInt = std::max(smoothSpark, (smoothBass - 0.65f) * 2.0f);

      Path lightning;
      lightning.moveTo(p1x, center.y);
      const int arcSteps = 16;
      for (int s = 1; s < arcSteps; s++) {
        float u = float(s) / float(arcSteps);
        float lx = p1x + (p2x - p1x) * u;
        float envelope = std::sin(u * 3.14159265f);
        float jitterY = std::sin(float(s) * 17.3f + simTime * 120.0f) * 28.0f * envelope * sparkInt;
        float jitterX = std::cos(float(s) * 11.7f + simTime * 95.0f) * 8.0f * envelope * sparkInt;
        lightning.lineTo(lx + jitterX, center.y + jitterY);
      }
      lightning.lineTo(p2x, center.y);

      // Resplandor del rayo
      Paint arcGlow; arcGlow.blend = Blend::plus;
      arcGlow.strokeWidth = 5.5f;
      arcGlow.color = {0.0f, 0.85f, 1.0f, std::clamp(0.60f * sparkInt * boost, 0.0f, 1.0f)};
      c.path(lightning, arcGlow);

      // Núcleo blanco del rayo
      Paint arcCore; arcCore.blend = Blend::plus;
      arcCore.strokeWidth = 2.0f;
      arcCore.color = {1.0f, 1.0f, 1.0f, std::clamp(0.95f * sparkInt * boost, 0.0f, 1.0f)};
      c.path(lightning, arcCore);
    }

    // 6. Dos Electroimanes Industriales con bobinas de cobre incandescentes
    for (int p = 0; p < 2; p++) {
      float poleSign = (p == 0) ? -1.0f : 1.0f;
      float px = center.x + poleSign * 0.28f * minDim;
      float py = center.y;
      float cylW = minDim * 0.088f;
      float cylH = minDim * 0.155f;

      bool isNorth = (poleSign * mx >= 0.0f);
      Color poleTint = isNorth ? Color{0.0f, 0.94f, 1.0f, 1.0f} : Color{0.75f, 0.25f, 1.0f, 1.0f};

      // Resplandor de inducción del polo
      // Graves: el resplandor del polo crece con los graves.
      float coreGlowR = cylW * (1.2f + smoothEnergy * 0.5f + smoothBass * 0.4f) * (1.0f + graves * 0.8f);
      Paint coreGlow = Paint::radial({px, py}, coreGlowR,
        {{1.0f, 1.0f, 1.0f, std::clamp(0.75f * boost, 0.0f, 1.0f)},
         {poleTint.r, poleTint.g, poleTint.b, std::clamp(0.40f * boost, 0.0f, 1.0f)},
         {0, 0, 0, 0}}, {0.0f, 0.45f, 1.0f});
      coreGlow.blend = Blend::plus;
      c.circle({px, py}, coreGlowR, coreGlow);

      // Cuerpo cilíndrico de acero de alta densidad
      Paint cylBody; cylBody.color = Color::argb(0xff181d26);
      c.rect({px - cylW * 0.5f, py - cylH * 0.5f, cylW, cylH}, cylBody);

      Paint cylBorder; cylBorder.color = Color::argb(0xff3c4657); cylBorder.strokeWidth = 1.8f;
      Path cylBox; cylBox.rect({px - cylW * 0.5f, py - cylH * 0.5f, cylW, cylH});
      c.path(cylBox, cylBorder);

      // 5 Vueltas de bobina de cobre incandescente (#b87333 / oro fundido)
      Path copperCoils;
      for (int turn = 0; turn < 5; turn++) {
        float ty = py - cylH * 0.35f + (float(turn) / 4.0f) * (cylH * 0.70f);
        copperCoils.moveTo(px - cylW * 0.58f, ty - 3.5f);
        copperCoils.cubicTo(
          px - cylW * 0.2f, ty + 5.0f,
          px + cylW * 0.2f, ty - 5.0f,
          px + cylW * 0.58f, ty + 3.5f
        );
      }
      Paint coilPaint;
      coilPaint.color = {0.92f, 0.55f, 0.20f, std::clamp(0.95f * boost, 0.0f, 1.0f)};
      coilPaint.strokeWidth = 3.6f;
      c.path(copperCoils, coilPaint);

      // Brillo especular sobre el cobre
      Paint coilSpec; coilSpec.blend = Blend::plus;
      coilSpec.color = {1.0f, 0.90f, 0.70f, std::clamp(0.60f * boost, 0.0f, 1.0f)};
      coilSpec.strokeWidth = 1.4f;
      c.path(copperCoils, coilSpec);

      // Núcleo blanco del emisor de campo
      Paint emitterCore; emitterCore.blend = Blend::plus;
      emitterCore.color = {1.0f, 1.0f, 1.0f, std::clamp(0.92f * boost, 0.0f, 1.0f)};
      // Golpes: el núcleo del emisor late en cada golpe.
      c.circle({px, py}, cylW * 0.22f * (1.0f + golpe * 0.6f), emitterCore);
    }
  }
};

class Visual final : public Scene {
  struct PlasmaIon {
    int lineIdx;
    float prog;
    float speed;
    float phase;
    float size;
    int colIdx;
  };

  struct Filing {
    float x, y;
    float angle;
    float len;
    bool isPolar;
  };

  static constexpr int kLines = 48;
  static constexpr int kLinePts = 64;
  static constexpr int kIonCount = 380;
  static constexpr int kFilingCount = 2200;

  // Tubos de flujo magnético precalculados por fotograma
  Vec2 linePts[kLines][kLinePts];

  std::vector<PlasmaIon> ions;
  std::vector<Filing> filings;

  float simTime = 0.0f;
  float smoothEnergy = 0.0f;
  float smoothBass = 0.0f;
  float smoothSpark = 0.0f;

  float targetPolarity = 1.0f;
  float polarityAngle = 0.0f;
  float polarityVel = 0.0f;
  float lastInvertTime = -10.0f;

  float shockRadius1 = 0.0f;
  float shockRadius2 = 0.0f;

  // Música estándar: envolventes y golpe corto (valen 0 sin música).
  float bass = 0, body = 0, spark = 0, energy = 0, drive = 0, slowBass = 0, kick = 0, flash = 0;
  // Segundos reales para los anillos de los golpes y el chisporroteo.
  double clock = 0;
  // Golpes: anillo fijo de ondas de inducción {nacimiento, fuerza}.
  static constexpr int kPulses = 4;
  std::array<double, kPulses> pulseBirth{};
  std::array<float, kPulses> pulsePower{};
  int nextPulse = 0;

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

  static Vec2 evalFieldDir(float x, float y, float mx, float my) {
    const float soft2 = 0.014f;
    float bx = 0.0f, by = 0.0f;

    for (int p = 0; p < 2; p++) {
      float px = (p == 0) ? -0.28f : 0.28f;
      float sign = (p == 0) ? 1.0f : -1.0f;
      float dx = x - px;
      float dy = y;
      float r2 = dx * dx + dy * dy + soft2;
      float invR25 = 1.0f / (r2 * std::sqrt(r2));
      float invR35 = invR25 / r2;

      float mDotD = sign * (mx * dx + my * dy);
      float dVdx = sign * mx * invR25 - 3.0f * dx * mDotD * invR35;
      float dVdy = sign * my * invR25 - 3.0f * dy * mDotD * invR35;

      bx -= dVdx;
      by -= dVdy;
    }

    float len = std::sqrt(bx * bx + by * by);
    if (len < 1e-5f) return Vec2{0.0f, 1.0f};
    return Vec2{bx / len, by / len};
  }

 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    simTime = 0.0f;
    smoothEnergy = 0.0f;
    smoothBass = 0.0f;
    smoothSpark = 0.0f;
    targetPolarity = 1.0f;
    polarityAngle = 0.0f;
    polarityVel = 0.0f;
    lastInvertTime = -10.0f;
    shockRadius1 = 0.0f;
    shockRadius2 = 0.0f;
    bass = body = spark = energy = drive = slowBass = kick = flash = 0;
    clock = 0;
    pulseBirth.fill(-100.0);
    pulsePower.fill(0.0f);
    nextPulse = 0;

    ions.clear();
    ions.reserve(kIonCount);
    for (int i = 0; i < kIonCount; i++) {
      ions.push_back({
        i % kLines,
        rng.unit(),
        0.35f + rng.unit() * 0.55f,
        rng.unit() * 6.2831853f,
        1.2f + rng.unit() * 2.2f,
        int(rng.unit() * 3.999f)
      });
    }

    filings.clear();
    filings.reserve(kFilingCount);
    for (int i = 0; i < kFilingCount; i++) {
      Filing f;
      if (i < 1500) {
        // 70% concentrado cerca de los dos polos
        float poleX = (i % 2 == 0) ? -0.28f : 0.28f;
        float r = std::pow(rng.unit(), 1.8f) * 0.42f + 0.025f;
        float th = rng.unit() * 6.2831853f;
        f.x = poleX + std::cos(th) * r;
        f.y = std::sin(th) * r * 0.85f;
        f.len = 0.012f + (1.0f - std::min(r / 0.42f, 1.0f)) * 0.022f;
        f.isPolar = true;
      } else {
        // 30% distribuido por el espacio
        f.x = (rng.unit() - 0.5f) * 1.55f;
        f.y = (rng.unit() - 0.5f) * 1.55f;
        f.len = 0.010f + rng.unit() * 0.014f;
        f.isPolar = false;
      }
      f.angle = rng.unit() * 3.14159265f;
      filings.push_back(f);
    }
  }

  void update(const Frame& f) override {
    float dt = float(f.delta);
    float targetEnergy = f.music.active ? f.music.energy : 0.0f;
    float targetBass = f.music.active ? f.music.bass : 0.0f;
    float targetSpark = f.music.active ? f.music.spark : 0.0f;

    smoothEnergy += (targetEnergy - smoothEnergy) * float(1.0 - std::exp(-dt * 6.0));
    smoothBass += (targetBass - smoothBass) * float(1.0 - std::exp(-dt * 7.0));
    smoothSpark += (targetSpark - smoothSpark) * float(1.0 - std::exp(-dt * 15.0));

    // En silencio reposa en un flujo de Lorentz suave (~0.10f). Con música acelera.
    float audioDrive = 0.10f + smoothEnergy * 0.75f + smoothBass * 0.35f;
    float speedMult = (f.reducedMotion ? 0.3f : 1.0f) * f.speed * audioDrive;
    simTime += dt * speedMult;

    // Inversión de polaridad en caídas de bajos con música activa
    if (f.music.active && f.music.bass > 0.78f && (simTime - lastInvertTime >= 1.6f)) {
      lastInvertTime = simTime;
      targetPolarity *= -1.0f;
      shockRadius1 = 12.0f;
      shockRadius2 = 12.0f;
    }

    if (shockRadius1 > 0.0f) {
      shockRadius1 += dt * 420.0f;
      if (shockRadius1 > 450.0f) shockRadius1 = 0.0f;
    }
    if (shockRadius2 > 0.0f) {
      shockRadius2 += dt * 420.0f;
      if (shockRadius2 > 450.0f) shockRadius2 = 0.0f;
    }

    float targetAngle = (targetPolarity > 0.0f) ? 0.0f : 3.14159265f;
    float angleDiff = targetAngle - polarityAngle;
    while (angleDiff > 3.14159265f) angleDiff -= 6.2831853f;
    while (angleDiff < -3.14159265f) angleDiff += 6.2831853f;
    polarityVel += (angleDiff * 38.0f - polarityVel * 9.5f) * dt;
    polarityAngle += polarityVel * dt;

    float mx = std::cos(polarityAngle);
    float my = std::sin(polarityAngle);

    // Recomputar los 48 tubos de flujo
    for (int l = 0; l < kLines; l++) {
      float side = (l < kLines / 2) ? 1.0f : -1.0f;
      int idx = l % (kLines / 2);
      float frac = float(idx) / float(kLines / 2 - 1);
      float emitterAngle = (frac - 0.5f) * 2.5f;

      float p1x = -0.28f + std::cos(emitterAngle) * 0.038f;
      float p1y = side * (0.015f + std::sin(std::abs(emitterAngle)) * 0.038f);
      float p2x = 0.28f - std::cos(emitterAngle) * 0.038f;
      float p2y = side * (0.015f + std::sin(std::abs(emitterAngle)) * 0.038f);

      float apexDist = 0.16f + std::pow(frac, 1.45f) * 0.72f * (1.0f + smoothBass * 0.40f);
      float apexY = side * apexDist;
      float apexX = (emitterAngle * 0.045f) + std::sin(simTime * 1.8f + float(l) * 0.2f) * (0.012f + smoothEnergy * 0.02f);

      for (int pt = 0; pt < kLinePts; pt++) {
        float u = float(pt) / float(kLinePts - 1);
        float omt = 1.0f - u;
        float bx = omt * omt * p1x + 2.0f * omt * u * apexX + u * u * p2x;
        float by = omt * omt * p1y + 2.0f * omt * u * apexY + u * u * p2y;

        float wav = std::sin(u * 14.0f - simTime * (4.0f + smoothEnergy * 5.0f) + float(l) * 0.35f);
        float wavAmp = (0.003f + smoothSpark * 0.008f) * std::sin(u * 3.14159265f);
        by += wav * wavAmp * side;

        linePts[l][pt] = Vec2{bx, by};
      }
    }

    // Actualizar iones de Lorentz
    for (auto& ion : ions) {
      ion.prog += dt * ion.speed * (0.75f + smoothEnergy * 0.85f);
      if (ion.prog >= 1.0f) ion.prog -= 1.0f;
      ion.phase += dt * (12.0f + smoothSpark * 18.0f);
    }

    // Orientar las 2200 limaduras de hierro
    float alignRate = std::clamp(dt * 18.0f, 0.0f, 1.0f);
    for (auto& fil : filings) {
      Vec2 b = evalFieldDir(fil.x, fil.y, mx, my);
      float targetA = std::atan2(b.y, b.x);
      float deltaA = targetA - fil.angle;
      while (deltaA > 3.14159265f) deltaA -= 6.2831853f;
      while (deltaA < -3.14159265f) deltaA += 6.2831853f;
      fil.angle += deltaA * alignRate;
    }

    // Música estándar: graves, cuerpo, agudos, energía y golpe corto.
    const Music& mu = f.music;
    bass = follow(bass, mu.bass, 22.0f, 4.5f, dt);
    body = follow(body, mu.body, 12.0f, 3.0f, dt);
    spark = follow(spark, mu.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, mu.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, mu.active ? std::pow(std::clamp(mu.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);
    float hit = 0, fl = 0;
    for (const auto& e : mu.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : mu.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : mu.events[3]) fl = std::max(fl, e.strength);
    const float onset = std::clamp((mu.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, mu.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    const bool fresh = hit > kick + 0.2f;
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    clock += f.delta;
    // Golpes: cada golpe nuevo lanza un anillo de inducción.
    if (fresh) {
      pulseBirth[size_t(nextPulse)] = clock;
      pulsePower[size_t(nextPulse)] = hit;
      nextPulse = (nextPulse + 1) % kPulses;
    }
  }

  void render(const Frame& f, Canvas& c) const override {
    auto g = glide(f);
    const float level = f.intensity;
    // Pulso: cada opción mueve algo distinto y sus pesos mezclan las opciones.
    const float golpe = g.pulso.weight(0) * std::min(kick * level, 1.0f);
    const float graves = g.pulso.weight(1) * std::min(bass * level, 1.0f);
    const float agudos = g.pulso.weight(2) * std::min(spark * level, 1.0f);
    const float tick = float(std::fmod(clock, 1000.0));
    // Patrón: las limaduras siguen el campo (Dipolo, el original), lo cruzan
    // en anillos (Equipotencial) o apuntan a su polo (Radial).
    const float crossW = g.patron.weight(1), radialW = g.patron.weight(2);
    float w = f.width, h = f.height;
    float minDim = std::min(w, h);
    Vec2 center{w * 0.5f, h * 0.5f};
    float boost = std::clamp((0.85f + smoothEnergy * 0.40f) * f.intensity, 0.0f, 1.0f);

    // Sin fondo opaco: lienzo 100% transparente

    // 1. Reflejo difuso central aditivo
    Paint chamberGlow = Paint::radial(center, minDim * 0.45f,
      {{0.0f, 0.94f, 1.0f, std::clamp(0.12f * boost, 0.0f, 1.0f)}, {0, 0, 0, 0}},
      {0.0f, 1.0f});
    chamberGlow.blend = Blend::plus;
    c.circle(center, minDim * 0.45f, chamberGlow);

    // Golpes: cada polo estalla en un resplandor de su color; Graves los hace
    // respirar más suave.
    const float burst = std::min(1.0f, (0.6f * golpe + 0.25f * graves) * f.glow);
    if (burst > 0.001f) {
      for (int k = 0; k < 2; k++) {
        const Vec2 pole{center.x + (k == 0 ? -0.28f : 0.28f) * minDim, center.y};
        const Color tint = k == 0 ? Color{0.2f, 0.95f, 1.0f, 1.0f} : Color{0.8f, 0.45f, 1.0f, 1.0f};
        const float reach = minDim * (0.42f + 0.08f * golpe);
        Paint light = Paint::radial(pole, reach,
          {{tint.r, tint.g, tint.b, burst}, {tint.r, tint.g, tint.b, burst * 0.35f}, {tint.r, tint.g, tint.b, 0}}, {0, 0.4f, 1.0f});
        light.blend = Blend::plus;
        c.circle(pole, reach, light);
      }
    }

    // Ondas de choque de inducción expansivas
    if (shockRadius1 > 0.0f) {
      float alpha = std::clamp((1.0f - shockRadius1 / 450.0f) * 0.40f * boost, 0.0f, 1.0f);
      Paint shk; shk.blend = Blend::plus; shk.strokeWidth = 2.0f;
      shk.color = {0.0f, 0.94f, 1.0f, alpha};
      c.circle({center.x - 0.28f * minDim, center.y}, shockRadius1, shk);
    }
    if (shockRadius2 > 0.0f) {
      float alpha = std::clamp((1.0f - shockRadius2 / 450.0f) * 0.40f * boost, 0.0f, 1.0f);
      Paint shk; shk.blend = Blend::plus; shk.strokeWidth = 2.0f;
      shk.color = {0.62f, 0.31f, 0.87f, alpha};
      c.circle({center.x + 0.28f * minDim, center.y}, shockRadius2, shk);
    }

    // Golpes: un anillo de inducción sale de cada polo y se apaga al crecer.
    const float pulseWeight = g.pulso.weight(0);
    if (pulseWeight > 0.001f) {
      for (int k = 0; k < kPulses; k++) {
        const float age = float(clock - pulseBirth[size_t(k)]);
        if (age < 0.0f || age >= 0.9f) continue;
        const float fade = 1.0f - age / 0.9f;
        const float power = std::min(pulsePower[size_t(k)] * level, 1.0f) * pulseWeight * fade;
        if (power <= 0.001f) continue;
        const float radius = minDim * (0.05f + age * 0.55f);
        Paint ring; ring.blend = Blend::plus; ring.strokeWidth = 3.0f + 5.0f * fade;
        ring.color = {0.0f, 0.94f, 1.0f, std::min(1.0f, 0.85f * power * boost)};
        c.circle({center.x - 0.28f * minDim, center.y}, radius, ring);
        ring.color = {0.75f, 0.35f, 1.0f, std::min(1.0f, 0.85f * power * boost)};
        c.circle({center.x + 0.28f * minDim, center.y}, radius, ring);
      }
    }

    // 2. Campo de limaduras de hierro orientadas (Ferrofluido que vibra con el audio)
    // Limaduras: largo de las agujas (1 es el original; 0 las quita).
    const float needle = g.limaduras;
    if (needle > 0.01f) {
      Path filingsPath;
      float filingLengthMult = 0.5f * (1.0f + smoothBass * 0.45f);

      for (const auto& fil : filings) {
        float sx = center.x + fil.x * minDim;
        float sy = center.y + fil.y * minDim;
        float flen = fil.len * minDim * filingLengthMult * needle;
        float angle = fil.angle;
        if (crossW + radialW > 0.001f) {
          // Las agujas no tienen sentido: se mezclan con el ángulo doble.
          const float toPole = std::atan2(fil.y, fil.x - (fil.x < 0.0f ? -0.28f : 0.28f));
          const float across = angle + float(pi) * 0.5f;
          const float keep = 1.0f - crossW - radialW;
          const float mx2 = keep * std::cos(2.0f * angle) + crossW * std::cos(2.0f * across) + radialW * std::cos(2.0f * toPole);
          const float my2 = keep * std::sin(2.0f * angle) + crossW * std::sin(2.0f * across) + radialW * std::sin(2.0f * toPole);
          angle = 0.5f * std::atan2(my2, mx2);
        }
        float dx = std::cos(angle) * flen;
        float dy = std::sin(angle) * flen;
        filingsPath.moveTo(sx - dx, sy - dy);
        filingsPath.lineTo(sx + dx, sy + dy);
      }
      Paint filPaint; filPaint.blend = Blend::plus;
      // Golpes enciende las limaduras (+80%); Graves las aviva; Agudos las
      // hace chisporrotear.
      filPaint.color = {0.45f, 0.65f, 0.95f, std::clamp(0.40f * boost * (1.0f + golpe * 0.8f + graves * 0.4f
        + agudos * 0.6f * std::sin(tick * 29.0f)), 0.0f, 1.0f)};
      filPaint.strokeWidth = 1.1f;
      c.path(filingsPath, filPaint);
    }

    // 3. Tubos de flujo magnético en arco (Cian -> Violeta -> Azul)
    Path linesCyan, linesViolet;

    for (int l = 0; l < kLines; l++) {
      Path& curPath = (l % 2 == 0) ? linesCyan : linesViolet;
      bool first = true;
      for (int pt = 0; pt < kLinePts; pt++) {
        float sx = center.x + linePts[l][pt].x * minDim;
        float sy = center.y + linePts[l][pt].y * minDim;
        if (first) { curPath.moveTo(sx, sy); first = false; }
        else curPath.lineTo(sx, sy);
      }
    }

    // Halo ancho de los tubos de flujo
    // Graves: el halo de los tubos se engrosa y se aviva con los graves.
    Paint lpGlow; lpGlow.blend = Blend::plus;
    lpGlow.strokeWidth = 3.5f * (1.0f + graves * 0.8f + golpe * 1.2f);
    lpGlow.color = {0.0f, 0.94f, 1.0f, std::clamp(0.22f * boost * (1.0f + graves * 0.6f), 0.0f, 1.0f)};
    c.path(linesCyan, lpGlow);
    lpGlow.color = {0.62f, 0.31f, 0.87f, std::clamp(0.22f * boost * (1.0f + graves * 0.6f), 0.0f, 1.0f)};
    c.path(linesViolet, lpGlow);

    // Filamentos brillantes de flujo
    Paint lpCore; lpCore.blend = Blend::plus;
    lpCore.strokeWidth = 1.3f;
    // Golpes: los filamentos se encienden en cada golpe.
    lpCore.color = {0.50f, 0.95f, 1.0f, std::clamp(0.65f * boost * (1.0f + golpe * 0.6f), 0.0f, 1.0f)};
    c.path(linesCyan, lpCore);
    lpCore.color = {0.85f, 0.50f, 1.0f, std::clamp(0.65f * boost * (1.0f + golpe * 0.6f), 0.0f, 1.0f)};
    c.path(linesViolet, lpCore);

    // 4. Plasma de Lorentz: iones bioluminiscentes en espirales ciclotrón
    const Color ionCols[4] = {
      {1.0f, 1.0f, 1.0f, 1.0f},
      {0.0f, 0.95f, 1.0f, 1.0f},
      {0.75f, 0.35f, 1.0f, 1.0f},
      {1.0f, 0.85f, 0.20f, 1.0f}
    };

    std::vector<Vec2> ionPoints[4];
    for (const auto& ion : ions) {
      int l = ion.lineIdx;
      float pNorm = ion.prog * float(kLinePts - 1);
      int idx0 = std::clamp(int(pNorm), 0, kLinePts - 2);
      float frac = pNorm - float(idx0);

      Vec2 p0 = linePts[l][idx0];
      Vec2 p1 = linePts[l][idx0 + 1];
      float bx = p0.x + (p1.x - p0.x) * frac;
      float by = p0.y + (p1.y - p0.y) * frac;

      // Ciclotrón: radio de la hélice (0 resbalan por la línea, 1 es el original).
      float gyroR = (0.005f + smoothSpark * 0.012f) * (0.8f + 0.4f * std::sin(ion.phase)) * g.ciclotron;
      float px = center.x + (bx + std::cos(ion.phase) * gyroR) * minDim;
      float py = center.y + (by + std::sin(ion.phase) * gyroR) * minDim;
      // Agudos: los iones tiemblan con los agudos.
      if (agudos > 0.001f) {
        px += std::sin(tick * 61.0f + ion.phase * 7.0f) * 1.6f * agudos;
        py += std::cos(tick * 53.0f + ion.phase * 5.0f) * 1.6f * agudos;
      }

      ionPoints[ion.colIdx].push_back({px, py});
    }

    for (int cIdx = 0; cIdx < 4; cIdx++) {
      if (!ionPoints[cIdx].empty()) {
        Paint ip; ip.blend = Blend::plus;
        Color baseCol = ionCols[cIdx];
        ip.color = {baseCol.r, baseCol.g, baseCol.b, std::clamp(0.85f * boost, 0.0f, 1.0f)};
        // Agudos: cada color de iones parpadea a su ritmo.
        const float flick = 1.0f + agudos * 0.5f * (0.5f + 0.5f * std::sin(tick * 29.0f + float(cIdx) * 1.9f));
        c.points(ionPoints[cIdx], (1.8f + smoothSpark * 1.6f) * flick, ip);
      }
    }

    // 5. Arcos eléctricos Tesla bifurcados entre los polos
    if (f.music.active && smoothSpark > 0.35f) {
      Path arcPath;
      float pole1X = center.x - 0.28f * minDim;
      float pole2X = center.x + 0.28f * minDim;
      float baseY = center.y;

      arcPath.moveTo(pole1X, baseY);
      const int kArcSteps = 12;
      for (int step = 1; step < kArcSteps; step++) {
        float u = float(step) / float(kArcSteps);
        float ax = pole1X + (pole2X - pole1X) * u;
        float sag = std::sin(u * 3.14159265f) * (std::sin(simTime * 35.0f + float(step)) * 24.0f * smoothSpark);
        float ay = baseY + sag;
        arcPath.lineTo(ax, ay);
      }
      arcPath.lineTo(pole2X, baseY);

      Paint arcPaint; arcPaint.blend = Blend::plus;
      arcPaint.strokeWidth = 2.2f;
      arcPaint.color = {1.0f, 1.0f, 1.0f, std::clamp(smoothSpark * boost, 0.0f, 1.0f)};
      c.path(arcPath, arcPaint);
    }

    // 6. Polos magnéticos translúcidos con bobinas de cobre
    for (int p = 0; p < 2; p++) {
      float px = (p == 0) ? (center.x - 0.28f * minDim) : (center.x + 0.28f * minDim);
      float py = center.y;
      Color poleColor = (p == 0) ? Color{0.0f, 0.95f, 1.0f, 1.0f} : Color{0.75f, 0.35f, 1.0f, 1.0f};

      // Resplandor del polo
      // Graves: el resplandor del polo crece con los graves.
      Paint poleGlow = Paint::radial({px, py}, minDim * 0.16f * (1.0f + graves * 0.8f),
        {{poleColor.r, poleColor.g, poleColor.b, std::clamp(0.65f * boost, 0.0f, 1.0f)}, {0, 0, 0, 0}},
        {0.0f, 1.0f});
      poleGlow.blend = Blend::plus;
      c.circle({px, py}, minDim * 0.16f * (1.0f + graves * 0.8f), poleGlow);

      // Cilindro del electroimán
      float cylW = minDim * 0.075f;
      float cylH = minDim * 0.14f;

      Paint cylBorder; cylBorder.color = {0.35f, 0.45f, 0.55f, 0.85f}; cylBorder.strokeWidth = 1.8f;
      Path cylBox; cylBox.rect({px - cylW * 0.5f, py - cylH * 0.5f, cylW, cylH});
      c.path(cylBox, cylBorder);

      // Vueltas de bobina de cobre incandescente
      Path copperCoils;
      for (int turn = 0; turn < 5; turn++) {
        float ty = py - cylH * 0.35f + (float(turn) / 4.0f) * (cylH * 0.70f);
        copperCoils.moveTo(px - cylW * 0.58f, ty - 3.5f);
        copperCoils.cubicTo(
          px - cylW * 0.2f, ty + 5.0f,
          px + cylW * 0.2f, ty - 5.0f,
          px + cylW * 0.58f, ty + 3.5f
        );
      }
      Paint coilPaint;
      coilPaint.color = {0.92f, 0.55f, 0.20f, std::clamp(0.95f * boost, 0.0f, 1.0f)};
      coilPaint.strokeWidth = 3.6f;
      c.path(copperCoils, coilPaint);

      // Brillo especular sobre el cobre
      Paint coilSpec; coilSpec.blend = Blend::plus;
      coilSpec.color = {1.0f, 0.90f, 0.70f, std::clamp(0.60f * boost, 0.0f, 1.0f)};
      coilSpec.strokeWidth = 1.4f;
      c.path(copperCoils, coilSpec);

      // Núcleo blanco del emisor de campo
      Paint emitterCore; emitterCore.blend = Blend::plus;
      emitterCore.color = {1.0f, 1.0f, 1.0f, std::clamp(0.92f * boost, 0.0f, 1.0f)};
      // Golpes: el núcleo del emisor late en cada golpe.
      c.circle({px, py}, cylW * 0.22f * (1.0f + golpe * 0.6f), emitterCore);
    }
  }
};

class Visual final : public Scene {
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  // Relojes en doble precisión: la escena sin música es idéntica a 30 y 60 FPS.
  double clock = 0, flow = 0;
  float spread = 0, spreadVel = 0;

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    clock = rng.unit() * 100.0;
    flow = rng.unit() * 100.0;
    spread = spreadVel = 0;
  }

  void update(const Frame& f) override {
    float dt = float(f.delta);
    const Music& m = f.music;
    bass = follow(bass, m.bass, 20.0f, 4.0f, dt);
    body = follow(body, m.body, 12.0f, 3.0f, dt);
    spark = follow(spark, m.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, m.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, m.active ? std::pow(std::clamp(m.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : m.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : m.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : m.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((m.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, m.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    if (hit > kick + 0.2f) spreadVel += 1.8f * hit;
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    // Las gotas se separan con el golpe y vuelven a juntarse con un muelle.
    spreadVel += (-spread * 16.0f - spreadVel * 4.0f) * dt;
    spread += spreadVel * dt;
    clock += f.delta * f.speed * (0.35 + 0.6 * drive);
    flow += f.delta * f.speed * (0.2 + 0.5 * energy);
  }

  void render(const Frame& f, Canvas& c) const override {
    float amp = f.intensity;
    float aspectY = f.height / std::max(1.0f, std::min(f.width, f.height));
    float k = 1.0f + std::max(-0.3f, spread) * 0.9f;
    std::vector<float> u;
    u.reserve(40);
    u.insert(u.end(), {float(std::fmod(flow, 1000.0)), bass * amp, kick * amp, energy});
    u.insert(u.end(), {f.glow, spark * amp, flash * amp, 0.0f});
    float px[6], py[6], pr[6];
    for (int i = 0; i < 6; i++) {
      double t = clock * (0.6 + 0.13 * i) + i * 1.7;
      px[i] = 0.30f * float(std::sin(t * 0.9 + i)) * k;
      py[i] = (0.30f + 0.18f * (aspectY - 1.0f)) * float(std::cos(t * 0.7 + i * 2.3)) * k;
      pr[i] = (0.09f + 0.035f * float((i * 7) % 4)) * (1.0f + 0.25f * bass * amp + 0.1f * kick * amp);
    }
    u.insert(u.end(), {px[0], py[0], px[1], py[1]});
    u.insert(u.end(), {px[2], py[2], px[3], py[3]});
    u.insert(u.end(), {px[4], py[4], px[5], py[5]});
    u.insert(u.end(), {pr[0], pr[1], pr[2], pr[3]});
    u.insert(u.end(), {pr[4], pr[5], 0.0f, 0.0f});
    for (int i = 0; i < 4; i++) u.insert(u.end(), {f.colors[i].r, f.colors[i].g, f.colors[i].b});
    c.material("liquid_glass", {0, 0, f.width, f.height}, u);
  }
};

shaderSources.liquid_glass:
#version 460 core
#include <flutter/runtime_effect.glsl>
uniform vec2 uSize;
uniform vec4 uA;   // flujo del fondo, graves, golpe, energía
uniform vec4 uB;   // glow, agudos, destello
uniform vec4 uP0;  // gotas 1 y 2 (lado corto, centradas)
uniform vec4 uP1;  // gotas 3 y 4
uniform vec4 uP2;  // gotas 5 y 6
uniform vec4 uR0;  // radios 1 a 4
uniform vec4 uR1;  // radios 5 y 6
uniform vec3 uC0;
uniform vec3 uC1;
uniform vec3 uC2;
uniform vec3 uC3;
out vec4 fragColor;

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

// Fondo vivo con franjas y anillos suaves para que la refracción se note.
vec3 backdrop(vec2 q) {
  float t = uA.x;
  float g = smoothstep(-0.9, 0.9, q.y + 0.3 * sin(q.x * 1.7 + t * 0.4));
  vec3 col = mix(uC1, uC2, g);
  float stripes = smoothstep(0.55, 1.0, sin((q.x - q.y) * 7.0 + t * 0.6));
  col = mix(col, mix(col, uC3, 0.6), stripes * 0.35);
  vec2 rc = q - vec2(0.25 * sin(t * 0.13), 0.3 * cos(t * 0.11));
  float rings = smoothstep(0.08, 0.0, abs(fract(length(rc) * 3.5 - t * 0.15) - 0.5) - 0.38);
  col += uC3 * rings * 0.12;
  return col * (0.82 + 0.15 * uA.w);
}

void addBlob(vec2 p, vec2 b, float r, inout float field, inout vec2 grad) {
  vec2 d = p - b;
  float d2 = dot(d, d) + 1e-4;
  float k = r * r / d2;
  field += k;
  grad += -2.0 * k / d2 * d;
}

void main() {
  vec2 frag = FlutterFragCoord().xy;
  float scale = min(uSize.x, uSize.y);
  vec2 p = (frag - 0.5 * uSize) / scale;
  float field = 0.0;
  vec2 grad = vec2(0.0);
  addBlob(p, uP0.xy, uR0.x, field, grad);
  addBlob(p, uP0.zw, uR0.y, field, grad);
  addBlob(p, uP1.xy, uR0.z, field, grad);
  addBlob(p, uP1.zw, uR0.w, field, grad);
  addBlob(p, uP2.xy, uR1.x, field, grad);
  addBlob(p, uP2.zw, uR1.y, field, grad);

  // Sombra suave de las gotas sobre el fondo.
  vec3 outside = backdrop(p) * (1.0 - 0.18 * smoothstep(0.45, 1.0, field));
  float inside = smoothstep(0.96, 1.04, field);
  vec3 col = outside;
  if (field > 0.9) {
    // Pendiente de la gota: grande en el borde y nula en el centro, así la
    // lente es plana en el medio y curva hacia los bordes (sin remolinos).
    vec2 slope = -grad * 0.02;
    float sl = length(slope);
    if (sl > 0.12) slope *= 0.12 / sl;
    // Lente: el fondo se curva hacia el centro y los colores se separan un poco.
    vec2 off = slope;
    vec3 glass = vec3(backdrop(p + off * 1.1).r, backdrop(p + off).g, backdrop(p + off * 0.9).b);
    glass *= 1.08;
    vec3 n3 = normalize(vec3(slope * 6.0, 1.0));
    vec3 L = normalize(vec3(-0.45, 0.6, 0.65));
    float spec = pow(max(dot(n3, L), 0.0), 48.0);
    float rim = 1.0 - smoothstep(1.0, 1.35, field);
    glass += uC3 * spec * (0.55 + 0.6 * uB.y + 0.4 * uA.z);
    glass += uC3 * rim * 0.22;
    col = mix(outside, glass, inside);
  }
  col += uC3 * uB.z * 0.03;
  col *= 1.0 - 0.3 * smoothstep(0.6, 1.4, length(p * vec2(0.9, 0.65)));
  col += (hash12(frag) - 0.5) / 255.0;
  fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

visuals.nativeSource:
class Visual final : public Scene {
  float bass = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0;
  // Reloj en doble precisión: sin música es idéntico a 30 y 60 FPS.
  double clock = 0;

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }
  // Un dígito de siete segmentos (a b c d e f g, de arriba en sentido horario).
  static void digit(Path& p, float x, float y, float w, float h, int mask) {
    const float s = w * 0.2f;
    if (mask & 1) p.rect({x, y, w, s});
    if (mask & 2) p.rect({x + w - s, y, s, h * 0.5f});
    if (mask & 4) p.rect({x + w - s, y + h * 0.5f, s, h * 0.5f});
    if (mask & 8) p.rect({x, y + h - s, w, s});
    if (mask & 16) p.rect({x, y + h * 0.5f, s, h * 0.5f});
    if (mask & 32) p.rect({x, y, s, h * 0.5f});
    if (mask & 64) p.rect({x, y + h * 0.5f - s * 0.5f, w, s});
  }

 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    bass = spark = energy = slowBass = kick = flash = 0;
    clock = double(rng.unit()) * 30.0;
  }

  void update(const Frame& f) override {
    const float dt = float(f.delta);
    const Music& mu = f.music;
    bass = follow(bass, mu.bass, 22.0f, 4.5f, dt);
    spark = follow(spark, mu.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, mu.energy, 6.0f, 1.8f, dt);
    float hit = 0, fl = 0;
    for (const auto& e : mu.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : mu.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : mu.events[3]) fl = std::max(fl, e.strength);
    const float onset = std::clamp((mu.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, mu.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    kick = std::max(kick * std::exp(-dt * 4.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    clock += f.delta * f.speed;
  }

  void render(const Frame& f, Canvas& c) const override {
    auto g = glide(f);
    const auto& pal = f.colors;
    const float amp = f.intensity;
    const float W = f.width, H = f.height;
    const float side = std::min(W, H);
    const float px = side / 400.0f;
    const float sensor = std::clamp(g.sensor, 0.0f, 1.0f);
    std::vector<float> u;
    u.reserve(40);
    u.insert(u.end(), {float(std::fmod(clock, 1000.0)), std::min(bass * amp, 1.5f) * g.pulso.weight(1),
                       std::min(kick * amp, 1.0f) * g.pulso.weight(0), std::min(spark * amp, 1.0f) * g.pulso.weight(2)});
    u.insert(u.end(), {g.fuentes.weight(0), g.fuentes.weight(1), g.fuentes.weight(2), std::clamp(g.conveccion, 0.0f, 1.0f)});
    u.insert(u.end(), {sensor, std::clamp(g.isotermas, 0.0f, 1.0f), f.glow, std::min(flash * amp, 1.0f)});
    // Detalle: cuántas manchas de calor hay.
    u.insert(u.end(), {std::clamp(2.5f + 1.8f * f.detail, 3.0f, 6.0f), 0.5f * H / side, std::min(kick * amp, 1.0f), 0.0f});
    for (int i = 0; i < 4; i++) u.insert(u.end(), {pal[size_t(i)].r, pal[size_t(i)].g, pal[size_t(i)].b});
    c.material("thermal", {0, 0, W, H}, u);

    // El visor de la cámara: mira, esquinas, escala y temperatura.
    const float hud = 0.35f + 0.65f * sensor;
    Paint line;
    line.strokeWidth = 1.4f * px;
    line.color = pal[3].opacity(0.85f * hud);
    const float cx = W * 0.5f, cy = H * 0.5f, arm = 16.0f * px, gap = 5.0f * px;
    Path cross;
    cross.moveTo(cx - arm, cy).lineTo(cx - gap, cy).moveTo(cx + gap, cy).lineTo(cx + arm, cy);
    cross.moveTo(cx, cy - arm).lineTo(cx, cy - gap).moveTo(cx, cy + gap).lineTo(cx, cy + arm);
    const float bx = W * 0.32f, by = H * 0.38f, bl = 14.0f * px;
    for (int k = 0; k < 4; k++) {
      const float sx = k % 2 == 0 ? -1.0f : 1.0f, sy = k < 2 ? -1.0f : 1.0f;
      const float x = cx + sx * bx, y = cy + sy * by;
      cross.moveTo(x - sx * bl, y).lineTo(x, y).lineTo(x, y - sy * bl);
    }
    c.path(cross, line);
    const Color hot{std::min(1.0f, pal[3].r * 0.3f + 0.7f), std::min(1.0f, pal[3].g * 0.3f + 0.7f), std::min(1.0f, pal[3].b * 0.3f + 0.7f), 1.0f};
    const Rect bar{W - 22.0f * px, H * 0.22f, 8.0f * px, H * 0.56f};
    Paint scaleBar = Paint::linear({0, bar.y}, {0, bar.y + bar.height}, {hot, pal[3], pal[2], pal[1], pal[0]});
    c.save();
    c.saveLayer(hud);
    c.rect(bar, scaleBar);
    c.restore();
    c.restore();
    Path ticks;
    for (int k = 0; k <= 8; k++) {
      const float y = bar.y + bar.height * float(k) / 8.0f;
      ticks.moveTo(bar.x - (k % 4 == 0 ? 7.0f : 4.0f) * px, y).lineTo(bar.x - 1.0f * px, y);
    }
    c.path(ticks, line);
    // Temperatura del punto central, en dígitos de siete segmentos.
    const float temp = 24.0f + 10.0f * std::min(energy * amp, 1.2f) + 5.0f * std::min(kick * amp, 1.0f) + 1.5f * std::sin(float(clock) * 0.3f);
    const int tenths = std::clamp(int(std::lround(temp * 10.0f)), 0, 999);
    static const int masks[10] = {63, 6, 91, 79, 102, 109, 125, 7, 127, 111};
    const float dw = 9.0f * px, dh = 16.0f * px, x0 = 14.0f * px, y0 = 14.0f * px;
    Path digits;
    digit(digits, x0, y0, dw, dh, masks[(tenths / 100) % 10]);
    digit(digits, x0 + dw * 1.5f, y0, dw, dh, masks[(tenths / 10) % 10]);
    digits.rect({x0 + dw * 2.75f, y0 + dh - dw * 0.2f, dw * 0.2f, dw * 0.2f});
    digit(digits, x0 + dw * 3.25f, y0, dw, dh, masks[tenths % 10]);
    digits.circle({x0 + dw * 4.75f, y0 + dw * 0.25f}, dw * 0.18f);
    digit(digits, x0 + dw * 5.15f, y0, dw, dh, 1 | 8 | 16 | 32);
    Paint dp;
    dp.color = pal[3].opacity(0.95f * hud);
    c.path(digits, dp);
  }
};

shaderSources.thermal:
#version 460 core
#include <flutter/runtime_effect.glsl>
uniform vec2 uSize;
uniform vec4 uA;   // tiempo, graves, fogonazo, chispas
uniform vec4 uB;   // pesos de fuentes: manchas, siluetas, ondas; convección
uniform vec4 uE;   // sensor, isotermas, glow, destello
uniform vec4 uF;   // manchas, media altura, golpe para los bailarines
uniform vec3 uC0;
uniform vec3 uC1;
uniform vec3 uC2;
uniform vec3 uC3;
out vec4 fragColor;

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash12(i), hash12(i + vec2(1.0, 0.0)), u.x),
             mix(hash12(i + vec2(0.0, 1.0)), hash12(i + vec2(1.0, 1.0)), u.x), u.y);
}

float seg(vec2 p, vec2 a, vec2 b) {
  vec2 pa = p - a;
  vec2 ba = b - a;
  float h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
  return length(pa - ba * h);
}

float heat(float d, float r) {
  return exp(-d * d / (r * r));
}

// Un bailarín: tronco y cabeza calientes, brazos y piernas tibios.
float dancer(vec2 p, float x, float i, float t) {
  float sway = 0.06 * sin(t * 1.8 + i * 1.3);
  float hop = -0.04 * uF.z * (0.5 + 0.5 * sin(i * 2.1));
  vec2 hip = vec2(x + sway * 0.3, 0.15 + hop);
  vec2 neck = vec2(x + sway, -0.2 + hop);
  vec2 head = vec2(x + sway * 1.2, -0.3 + hop);
  float wave = sin(t * 2.0 + i);
  vec2 handL = neck + vec2(-0.17, 0.05 - 0.2 * wave);
  vec2 handR = neck + vec2(0.17, 0.05 + 0.2 * wave);
  vec2 footL = vec2(x - 0.08, 0.6);
  vec2 footR = vec2(x + 0.08 + 0.03 * sin(t * 1.8 + i), 0.6);
  float h = heat(seg(p, hip, neck), 0.055) * 1.0;
  h = max(h, heat(length(p - head), 0.06) * 1.1);
  h = max(h, heat(min(seg(p, neck, handL), seg(p, neck, handR)), 0.028) * 0.75);
  h = max(h, heat(min(seg(p, hip, footL), seg(p, hip, footR)), 0.032) * 0.7);
  return h;
}

vec3 thermal(float T) {
  T = clamp(T, 0.0, 1.0);
  vec3 white = mix(uC3, vec3(1.0), 0.7);
  if (T < 0.3) return mix(uC0, uC1, T / 0.3);
  if (T < 0.55) return mix(uC1, uC2, (T - 0.3) / 0.25);
  if (T < 0.8) return mix(uC2, uC3, (T - 0.55) / 0.25);
  return mix(uC3, white, (T - 0.8) / 0.2);
}

void main() {
  vec2 frag = FlutterFragCoord().xy;
  float scale = min(uSize.x, uSize.y);
  vec2 p = (frag - 0.5 * uSize) / scale;
  float t = uA.x;
  // Sensor: píxeles gruesos como una cámara térmica de verdad.
  float cell = mix(0.0, 0.012, uE.x);
  if (cell > 0.0005) p = (floor(p / cell) + 0.5) * cell;
  // Convección: el aire caliente hace temblar la imagen.
  p.x += uB.w * 0.012 * sin(p.y * 30.0 + t * 4.0);
  float T = 0.0;
  if (uB.x > 0.001) {
    float m = 0.0;
    for (int i = 0; i < 6; i++) {
      float fi = float(i);
      if (fi >= uF.x) break;
      float h = fract(sin(fi * 12.9898) * 43758.5453);
      vec2 c = vec2(0.32 * sin(t * (0.21 + 0.13 * h) + fi * 2.1), 0.7 * sin(t * (0.17 + 0.11 * h) + fi * 1.3) * uF.y / 0.89);
      float r = (0.12 + 0.05 * h) * (1.0 + 0.25 * uA.y);
      m += heat(length(p - c), r) * (0.7 + 0.3 * h);
    }
    T += uB.x * min(m, 1.2);
  }
  if (uB.y > 0.001) {
    float d = dancer(p, -0.33, 0.0, t);
    d = max(d, dancer(p, -0.11, 1.0, t));
    d = max(d, dancer(p, 0.11, 2.0, t));
    d = max(d, dancer(p, 0.33, 3.0, t));
    T += uB.y * (0.12 + d * (0.85 + 0.2 * uA.y));
  }
  if (uB.z > 0.001) {
    float w = 0.5 + 0.4 * sin(p.y * 9.0 + t * 2.0 + 1.5 * sin(p.x * 4.0 + t));
    T += uB.z * w * (0.35 + 0.65 * smoothstep(-0.9, 0.9, p.y)) * (1.0 + 0.2 * uA.y);
  }
  // Aire caliente que sube desde lo que quema.
  T += uB.w * 0.2 * (noise(p * vec2(4.0, 2.0) + vec2(0.0, t * 0.8)) - 0.5) * smoothstep(0.05, 0.5, T);
  // Fogonazo de calor con cada golpe.
  T += uA.z * 0.22;
  // Chispas calientes.
  T += step(0.985 - uA.w * 0.04, hash12(floor(p * 40.0) + floor(t * 6.0))) * uA.w * 0.8;
  T += (noise(p * 3.0 + t * 0.1) - 0.5) * 0.05;
  vec3 col = thermal(T);
  // Isotermas: bandas de igual temperatura con su línea.
  if (uE.y > 0.001) {
    float bands = floor(T * 8.0) / 8.0;
    float lineIso = 1.0 - smoothstep(0.0, 0.08, abs(fract(T * 8.0) - 0.5) * 2.0 - 0.9);
    vec3 iso = mix(thermal(bands + 0.06), uC3, lineIso * 0.7);
    col = mix(col, iso, uE.y);
  }
  col *= 1.0 + 0.1 * uE.w + 0.05 * uE.z;
  col += (hash12(frag + t) - 0.5) * 0.05 * uE.x;
  col *= 1.0 - 0.3 * smoothstep(0.7, 1.5, length(p * vec2(0.9, 0.65)));
  col += (hash12(frag) - 0.5) / 255.0;
  fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

visuals.nativeSource:
class Visual final : public Scene {
  struct Cell {
    std::vector<Vec2> poly;
    Vec2 c;
    float radius = 0, tone = 1, clear = 0, delay = 0;
    float vx = 0, vy = 0, spin = 0, zoom = 0;
    int color = 1;
  };
  std::vector<Cell> window, shards;
  float w = 0, h = 0;
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  float ringR = 3.0f, ringAmp = 0, blast = 0;
  double clock = 0, sinceShatter = 100;
  bool rebuilt = false;
  Random rng{37};

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

  // Recorta el polígono al semiplano dot(p, n) <= d.
  static std::vector<Vec2> clip(const std::vector<Vec2>& poly, Vec2 n, float d) {
    std::vector<Vec2> out;
    out.reserve(poly.size() + 2);
    for (size_t i = 0; i < poly.size(); i++) {
      Vec2 p = poly[i], q = poly[(i + 1) % poly.size()];
      float dp = p.x * n.x + p.y * n.y - d, dq = q.x * n.x + q.y * n.y - d;
      if (dp <= 0) out.push_back(p);
      if ((dp <= 0) != (dq <= 0)) {
        float t = dp / (dp - dq);
        out.push_back({p.x + (q.x - p.x) * t, p.y + (q.y - p.y) * t});
      }
    }
    return out;
  }

  // Mosaico de Voronoi exacto: cada celda es el rectángulo recortado por las
  // mediatrices de sus vecinas.
  void build(float detail) {
    float s = std::min(w, h);
    float size = s / (4.6f + 1.2f * std::clamp(detail, 0.25f, 2.0f));
    int cols = int(std::ceil(w / size)) + 1, rows = int(std::ceil(h / size)) + 1;
    float cw = w / float(cols - 1), ch = h / float(rows - 1);
    std::vector<Vec2> seeds;
    for (int j = 0; j < rows; j++)
      for (int i = 0; i < cols; i++)
        seeds.push_back({(float(i) + (rng.unit() - 0.5f) * 0.8f) * cw, (float(j) + (rng.unit() - 0.5f) * 0.8f) * ch});
    window.clear();
    float pad = s * 0.05f;
    Vec2 mid{w * 0.5f, h * 0.5f};
    for (size_t i = 0; i < seeds.size(); i++) {
      std::vector<Vec2> poly = {{-pad, -pad}, {w + pad, -pad}, {w + pad, h + pad}, {-pad, h + pad}};
      for (size_t j = 0; j < seeds.size() && !poly.empty(); j++) {
        if (i == j) continue;
        float dx = seeds[j].x - seeds[i].x, dy = seeds[j].y - seeds[i].y;
        if (dx * dx + dy * dy > size * size * 9.0f) continue;
        Vec2 n{dx, dy};
        float d = ((seeds[i].x + seeds[j].x) * dx + (seeds[i].y + seeds[j].y) * dy) * 0.5f;
        poly = clip(poly, n, d);
      }
      if (poly.size() < 3) continue;
      Cell cell;
      cell.poly = poly;
      float sx = 0, sy = 0;
      for (const auto& p : poly) { sx += p.x; sy += p.y; }
      cell.c = {sx / poly.size(), sy / poly.size()};
      float r = 0;
      for (const auto& p : poly) r = std::max(r, std::hypot(p.x - cell.c.x, p.y - cell.c.y));
      cell.radius = r;
      float pick = rng.unit();
      cell.color = pick < 0.36f ? 1 : (pick < 0.68f ? 2 : 3);
      cell.clear = rng.unit() < 0.14f ? 0.55f : 0.0f;
      cell.tone = 0.8f + 0.35f * rng.unit();
      float dist = std::hypot(cell.c.x - mid.x, cell.c.y - mid.y) / s;
      cell.delay = 0.45f + dist * 0.55f;
      window.push_back(cell);
    }
  }

  void shatter() {
    float s = std::min(w, h);
    shards = window;
    Vec2 mid{w * 0.5f, h * 0.5f};
    for (auto& sh : shards) {
      float dx = sh.c.x - mid.x, dy = sh.c.y - mid.y;
      float d = std::sqrt(dx * dx + dy * dy) + 1.0f;
      float speed = s * (0.8f + 1.4f * rng.unit());
      sh.vx = dx / d * speed + (rng.unit() - 0.5f) * s * 0.3f;
      sh.vy = dy / d * speed + (rng.unit() - 0.5f) * s * 0.3f - s * 0.2f;
      sh.spin = (rng.unit() - 0.5f) * 7.0f;
      sh.zoom = 0.5f + 1.6f * rng.unit();
    }
    build(1.0f);
    sinceShatter = 0;
    rebuilt = true;
  }

  Color glassColor(const Frame& f, const Cell& cell, float light) const {
    const Color& g = f.colors[cell.color];
    float r = g.r + (1.0f - g.r) * cell.clear, gg = g.g + (1.0f - g.g) * cell.clear, b = g.b + (1.0f - g.b) * cell.clear;
    return {std::min(1.0f, r * light), std::min(1.0f, gg * light), std::min(1.0f, b * light), 1.0f};
  }

  void drawCell(const Frame& f, Canvas& c, const Cell& cell, float light, float alpha, Vec2 lamp, bool edge) const {
    float s = std::min(f.width, f.height);
    Path path;
    path.moveTo(cell.poly[0].x, cell.poly[0].y);
    for (size_t i = 1; i < cell.poly.size(); i++) path.lineTo(cell.poly[i].x, cell.poly[i].y);
    path.close();
    // Gradiente radial desplazado hacia la luz: el vidrio brilla por el lado
    // que mira a la lámpara y se oscurece hacia el plomo.
    Vec2 hot{cell.c.x + (lamp.x - cell.c.x) * 0.18f, cell.c.y + (lamp.y - cell.c.y) * 0.18f};
    Color bright = glassColor(f, cell, light * 1.35f);
    Color dark = glassColor(f, cell, light * 0.42f);
    bright.r = std::min(1.0f, bright.r + 0.08f * light);
    bright.g = std::min(1.0f, bright.g + 0.08f * light);
    bright.b = std::min(1.0f, bright.b + 0.08f * light);
    bright.a = dark.a = alpha;
    Paint fill = Paint::radial(hot, cell.radius * 1.25f, {bright, dark});
    c.path(path, fill);
    Paint lead;
    lead.strokeWidth = s * 0.011f;
    lead.strokeJoin = 1;
    lead.color = {f.colors[0].r, f.colors[0].g, f.colors[0].b, alpha};
    c.path(path, lead);
    if (edge) {
      Paint rim;
      rim.blend = Blend::plus;
      rim.strokeWidth = s * 0.003f;
      rim.strokeJoin = 1;
      rim.color = {1.0f, 0.95f, 0.85f, 0.55f * alpha};
      c.path(path, rim);
    }
  }

  float lightAt(const Frame& f, Vec2 p, Vec2 lamp) const {
    float s = std::min(f.width, f.height);
    float dx = (p.x - lamp.x) / s, dy = (p.y - lamp.y) / s;
    float d2 = dx * dx + dy * dy;
    float d = std::sqrt(d2);
    float wave = ringAmp * std::exp(-(d - ringR) * (d - ringR) * 30.0f);
    return (0.45f + 0.85f * std::exp(-d2 * 2.2f)) * (0.8f + 0.55f * bass + 0.25f * energy) + 0.9f * wave + 0.35f * flash;
  }

  Vec2 lampAt(const Frame& f) const {
    return {f.width * (0.5f + 0.16f * float(std::sin(clock * 0.21))),
            f.height * (0.45f + 0.12f * float(std::cos(clock * 0.17)))};
  }

 public:
  void reset(uint32_t seed) override {
    rng = Random(seed);
    window.clear();
    shards.clear();
    w = h = 0;
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    ringR = 3.0f;
    ringAmp = blast = 0;
    clock = rng.unit() * 20.0;
    sinceShatter = 100;
    rebuilt = false;
  }

  void update(const Frame& f) override {
    float dt = float(f.delta);
    if (f.width != w || f.height != h || window.empty()) {
      w = f.width;
      h = f.height;
      build(f.detail);
      shards.clear();
      sinceShatter = 100;
      rebuilt = false;
    }
    const Music& m = f.music;
    bass = follow(bass, m.bass, 22.0f, 4.5f, dt);
    body = follow(body, m.body, 12.0f, 3.0f, dt);
    spark = follow(spark, m.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, m.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, m.active ? std::pow(std::clamp(m.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : m.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : m.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : m.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((m.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, m.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    sinceShatter += f.delta;
    if (hit > kick + 0.2f) {
      ringR = 0.0f;
      ringAmp = hit;
      // Drop: golpe fuerte con la música lanzada y el vitral entero.
      if (hit > 0.55f && drive > 0.3f && sinceShatter > 8.0) {
        shatter();
        blast = 1.0f;
      }
    }
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    blast *= std::exp(-dt * 1.6f);
    ringR += dt * (0.9f + 0.5f * drive);
    ringAmp *= std::exp(-dt * 2.0f);
    clock += f.delta * f.speed * (0.5 + 0.8 * drive);
    if (sinceShatter > 2.5) shards.clear();
  }

  void render(const Frame& f, Canvas& c) const override {
    float amp = f.intensity;
    Vec2 lamp = lampAt(f);
    std::vector<float> u;
    u.reserve(20);
    u.insert(u.end(), {float(std::fmod(clock, 1000.0)), bass * amp, kick * amp, energy});
    u.insert(u.end(), {lamp.x / f.width, lamp.y / f.height, blast * amp, f.glow});
    for (int i = 0; i < 4; i++) u.insert(u.end(), {f.colors[i].r, f.colors[i].g, f.colors[i].b});
    // Luz de fondo: sólo se ve por el hueco cuando el vitral se rompe.
    c.material("backlight", {0, 0, f.width, f.height}, u);

    float tNew = float(sinceShatter);
    for (const Cell& cell : window) {
      float alpha = 1.0f, grow = 1.0f;
      if (rebuilt) {
        float a = std::clamp((tNew - cell.delay) / 0.4f, 0.0f, 1.0f);
        if (a <= 0) continue;
        alpha = a;
        grow = 0.75f + 0.25f * a * a * (3.0f - 2.0f * a);
      }
      float light = lightAt(f, cell.c, lamp) * amp;
      if (grow < 0.999f) {
        c.save();
        c.translate(cell.c.x, cell.c.y);
        c.scale(grow, grow);
        c.translate(-cell.c.x, -cell.c.y);
        drawCell(f, c, cell, light, alpha, lamp, false);
        c.restore();
      } else {
        drawCell(f, c, cell, light, alpha, lamp, false);
      }
    }

    // Fragmentos que vuelan hacia la cámara girando.
    float tau = float(sinceShatter);
    float s = std::min(f.width, f.height);
    for (const Cell& sh : shards) {
      float alpha = 1.0f - std::clamp((tau - 0.55f) / 0.6f, 0.0f, 1.0f);
      if (alpha <= 0) continue;
      float ox = sh.vx * tau, oy = sh.vy * tau + 0.5f * s * 1.4f * tau * tau;
      float sc = 1.0f + sh.zoom * tau;
      c.save();
      c.translate(sh.c.x + ox, sh.c.y + oy);
      c.rotate(sh.spin * tau);
      c.scale(sc, sc);
      c.translate(-sh.c.x, -sh.c.y);
      drawCell(f, c, sh, (1.1f + 0.8f * blast) * amp, alpha, lamp, true);
      c.restore();
    }

    // Brillo del vidrio: ondulaciones y destellos con los agudos.
    std::vector<float> g;
    g.reserve(16);
    g.insert(g.end(), {float(std::fmod(clock, 1000.0)), spark * amp, kick * amp, f.glow});
    for (int i = 0; i < 4; i++) g.insert(g.end(), {f.colors[i].r, f.colors[i].g, f.colors[i].b});
    c.material("glass_sheen", {0, 0, f.width, f.height}, g, {}, Blend::plus);
  }
};

shaderSources.backlight:
#version 460 core
#include <flutter/runtime_effect.glsl>
uniform vec2 uSize;
uniform vec4 uA;   // reloj, graves, golpe, energía
uniform vec4 uB;   // posición de la lámpara, fogonazo, glow
uniform vec3 uC0;
uniform vec3 uC1;
uniform vec3 uC2;
uniform vec3 uC3;
out vec4 fragColor;

void main() {
  vec2 frag = FlutterFragCoord().xy;
  float scale = min(uSize.x, uSize.y);
  vec2 p = (frag - uB.xy * uSize) / scale;
  float r = length(p);
  float a = atan(p.y, p.x);
  // Luz blanca cálida con rayos que salen de la lámpara.
  float rays = 0.6 + 0.4 * sin(a * 9.0 + uA.x * 0.7) * sin(a * 5.0 - uA.x * 0.4);
  float core = 0.05 / (r * r + 0.05);
  float I = (0.12 + core * rays * 1.6) * (0.6 + 2.2 * uB.z + 0.4 * uA.y) * uB.w;
  vec3 col = uC0 + vec3(1.0, 0.86, 0.6) * I + vec3(1.0) * smoothstep(0.6, 3.0, I) * 0.5;
  fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

shaderSources.glass_sheen:
#version 460 core
#include <flutter/runtime_effect.glsl>
uniform vec2 uSize;
uniform vec4 uA;   // reloj, agudos, golpe, glow
uniform vec3 uC0;
uniform vec3 uC1;
uniform vec3 uC2;
uniform vec3 uC3;
out vec4 fragColor;

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash12(i), hash12(i + vec2(1.0, 0.0)), u.x),
             mix(hash12(i + vec2(0.0, 1.0)), hash12(i + vec2(1.0, 1.0)), u.x), u.y);
}

void main() {
  vec2 frag = FlutterFragCoord().xy;
  float scale = min(uSize.x, uSize.y);
  vec2 p = frag / scale;
  // Vidrio soplado: ondulaciones suaves que reflejan un brillo blanco.
  float n = noise(p * vec2(6.0, 14.0) + vec2(0.0, uA.x * 0.05));
  float sheen = smoothstep(0.62, 0.95, n) * 0.05 * uA.w;
  // Destellos de luz que saltan con los agudos.
  float glint = step(0.998 - 0.004 * uA.y, hash12(floor(frag * 0.34) + floor(uA.x * 5.0)));
  vec3 col = vec3(1.0, 0.96, 0.9) * (sheen + glint * 0.7 * uA.y + 0.02 * uA.z);
  col = clamp(col, 0.0, 1.0);
  fragColor = vec4(col, max(col.r, max(col.g, col.b)));
}

